insert into public.languages (id, code, name, native_name, writing_direction, tts_locale, is_available) values ('eg', 'eg', 'Église copte', 'Église copte orthodoxe', 'ltr', 'fr-FR', true) on conflict (id) do update set name = excluded.name, native_name = excluded.native_name, writing_direction = excluded.writing_direction, tts_locale = excluded.tts_locale, is_available = excluded.is_available;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g101.pentecote', 'eg', 'grammar', 'knowledge', 'La Pentecôte : l''Église naît', 1, '{}'::text[], 1, '{"rule": {"summary": "Cinquante jours après Pâques, l''Esprit Saint descend sur les disciples à Jérusalem : c''est la Pentecôte, la naissance de l''Église.", "explanation": "Après l''Ascension, environ cent vingt disciples prient dans la chambre haute. À la Pentecôte, l''Esprit descend comme des langues de feu. Pierre prêche et trois mille personnes sont baptisées le jour même.", "pattern": "Ascension → dix jours de prière → Pentecôte → Pierre prêche → trois mille baptisés.", "examples": [{"text": "La Pentecôte tombe cinquante jours après Pâques.", "translation": "Le mot vient du grec « cinquantième »."}], "commonErrors": [{"wrong": "L''Église naît à Rome.", "right": "L''Église naît à Jérusalem.", "why": "Rome ne vient que plus tard, avec Pierre et Paul."}], "tip": "Pentecôte = 50 jours = le feu = l''Église commence."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g102.communaute', 'eg', 'grammar', 'knowledge', 'La première communauté de Jérusalem', 1, '{}'::text[], 1, '{"rule": {"summary": "La première communauté de Jérusalem met ses biens en commun, écoute les apôtres, célèbre la fraction du pain et prie.", "explanation": "Les croyants sont environ cinq mille. Ils sont fidèles à l''enseignement des apôtres, à la vie fraternelle, à la fraction du pain et aux prières. Ils sont tous juifs : la séparation avec le judaïsme viendra plus tard.", "pattern": "Pentecôte → croyants → biens en commun, enseignement, fraction du pain, prières.", "examples": [{"text": "Les croyants mettent leurs biens en commun.", "translation": "Personne ne manque de rien."}], "commonErrors": [{"wrong": "Les premiers chrétiens sont des Romains.", "right": "Les premiers chrétiens sont tous juifs.", "why": "Le christianisme naît dans le judaïsme."}], "tip": "Quatre habitudes : enseignement, frères, fraction du pain, prières."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g103.etienne', 'eg', 'grammar', 'knowledge', 'Étienne, premier martyr', 1, '{}'::text[], 1, '{"rule": {"summary": "Étienne, l''un des sept, est lapidé vers 35 : c''est le premier martyr. Sa mort disperse les chrétiens, et l''Évangile sort de Jérusalem.", "explanation": "Les hellénistes se plaignent pour leurs veuves ; sept hommes sont choisis pour le service. Étienne témoigne devant les autorités juives et il est lapidé. Saul approuve sa mort. La persécution qui suit disperse les chrétiens et répand l''Évangile.", "pattern": "Dispute des veuves → sept hommes → Étienne lapidé (vers 35) → dispersion → l''Évangile se répand.", "examples": [{"text": "Étienne est le premier martyr chrétien.", "translation": "Martyr vient du grec martys : « témoin »."}], "commonErrors": [{"wrong": "Étienne est un apôtre.", "right": "Étienne est l''un des sept hommes choisis pour le service.", "why": "Les apôtres sont les Douze ; Étienne est d''un autre groupe."}], "tip": "Étienne = témoin = premier martyr."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g104.paul', 'eg', 'grammar', 'knowledge', 'Saul devient Paul', 1, '{}'::text[], 1, '{"rule": {"summary": "Vers 35, sur la route de Damas, le Christ apparaît à Saul le persécuteur : il devient Paul, l''apôtre des nations. À Antioche, les disciples sont appelés chrétiens.", "explanation": "Saul, pharisien zélé, part à Damas arrêter les chrétiens. Le Christ lui apparaît. Accueilli par Barnabé, il prêche d''abord dans les synagogues, puis se tourne vers les païens. À Antioche, les disciples reçoivent le nom de chrétiens.", "pattern": "Saul persécute → route de Damas (vers 35) → Paul, apôtre des nations → synagogue puis païens → Antioche.", "examples": [{"text": "Paul prêche d''abord à la synagogue, puis aux païens.", "translation": "Les Juifs connaissent déjà les Écritures."}], "commonErrors": [{"wrong": "Paul est l''un des Douze.", "right": "Paul est un apôtre venu après la Résurrection.", "why": "Il devient apôtre sur la route de Damas."}], "tip": "Damas = lumière = Saul devient Paul."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g105.concile', 'eg', 'grammar', 'knowledge', 'Le concile de Jérusalem', 1, '{}'::text[], 1, '{"rule": {"summary": "Vers 49, les apôtres et les anciens se réunissent à Jérusalem et décident que la circoncision n''est plus obligatoire pour les païens convertis.", "explanation": "Des judaïsants affirment que sans circoncision on n''est pas sauvé. Paul et Barnabé montent à Jérusalem. Pierre, Paul, Barnabé puis Jacques parlent, et le concile décide que le salut vient du Christ, pas de la Loi. Sa méthode servira à tous les conciles.", "pattern": "Dispute à Antioche → voyage → témoignages → verdict → lettre.", "examples": [{"text": "Le concile de Jérusalem a lieu vers 49.", "translation": "C''est le premier concile de l''histoire chrétienne."}], "commonErrors": [{"wrong": "Les païens doivent d''abord devenir juifs.", "right": "Les païens n''ont pas besoin d''être circoncis.", "why": "Le salut vient du Christ, pas de la Loi."}], "tip": "Concile de Jérusalem = 49 = circoncision."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g106.martyrs', 'eg', 'grammar', 'knowledge', 'Les premières persécutions', 1, '{}'::text[], 1, '{"rule": {"summary": "Vers 44, Jacques, frère de Jean, est décapité. En 62, Jacques de Jérusalem est martyrisé. En 64, Néron accuse les chrétiens de l''incendie de Rome.", "explanation": "Rome tolère les religions à condition qu''on honore l''empereur ; les chrétiens refusent, car ils n''adorent que Dieu. Après l''incendie de Rome en 64, Néron les accuse. Selon la tradition, Pierre et Paul sont martyrisés à Rome vers 67.", "pattern": "44 Jacques (frère de Jean) → 62 Jacques de Jérusalem → 64 incendie de Rome → vers 67 Pierre et Paul.", "examples": [{"text": "Néron accuse les chrétiens de l''incendie de Rome.", "translation": "Il veut détourner les soupçons de lui."}], "commonErrors": [{"wrong": "Les deux Jacques sont le même homme.", "right": "Jacques, frère de Jean (vers 44), n''est pas Jacques de Jérusalem (62).", "why": "Deux martyrs, deux dates."}], "tip": "44, 62, 64, 67 : quatre dates, quatre martyrs ou persécutions."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g107.chute', 'eg', 'grammar', 'knowledge', 'La chute de Jérusalem', 1, '{}'::text[], 1, '{"rule": {"summary": "En 66 les Juifs se révoltent contre Rome ; en 70 Titus prend Jérusalem et détruit le Temple. Les chrétiens se dispersent. Sous Domitien (81-96), nouvelle persécution.", "explanation": "La guerre dure quatre ans. Après la prise de Jérusalem, les Juifs sont dispersés et le Temple, centre de leur culte, n''est plus qu''un tas de pierres. Les chrétiens se dispersent aussi, et l''Évangile gagne presque tout le monde connu. À la fin du siècle, Domitien persécute à son tour.", "pattern": "66 révolte → 70 Titus et le Temple détruit → dispersion → Domitien (81-96).", "examples": [{"text": "En 70, Titus détruit le Temple de Jérusalem.", "translation": "Le centre du culte juif disparaît."}], "commonErrors": [{"wrong": "Néron détruit le Temple.", "right": "C''est Titus qui prend Jérusalem et détruit le Temple en 70.", "why": "Néron persécute en 64 ; Titus intervient en 70."}], "tip": "66 révolte, 70 Temple, 81-96 Domitien."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g108.ecrits', 'eg', 'grammar', 'knowledge', 'Les écrits et les premières erreurs', 1, '{}'::text[], 1, '{"rule": {"summary": "L''enseignement de Jésus, d''abord oral, est mis par écrit : épîtres, évangiles, Nouveau Testament. Face au gnosticisme et au docétisme, saint Jean répond : « Le Verbe s''est fait chair ».", "explanation": "Les témoins vieillissent, les Églises s''éloignent, de faux docteurs apparaissent : il faut écrire. Les gnostiques méprisent le corps ; le docétisme en tire que Jésus n''aurait eu que l''apparence d''un corps. Chaque erreur oblige l''Église à préciser sa foi.", "pattern": "Parole orale → écrits (épîtres, évangiles) → erreurs (gnose, docétisme) → réponse de Jean.", "examples": [{"text": "Évangile veut dire « bonne nouvelle ».", "translation": "Il y a quatre évangiles."}], "commonErrors": [{"wrong": "Jésus a écrit un évangile.", "right": "Jésus n''a rien écrit : ses disciples l''ont fait.", "why": "L''enseignement a d''abord été oral."}], "tip": "Oral, puis écrit ; chaque erreur fait préciser la foi."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g109.sieges', 'eg', 'grammar', 'knowledge', 'Les apôtres et les sièges apostoliques', 1, '{}'::text[], 1, '{"rule": {"summary": "Jésus envoie les apôtres vers toutes les nations. Un siège apostolique est une Église fondée par un apôtre ou un proche ; la succession apostolique garantit la foi des origines.", "explanation": "Selon la tradition, Pierre et Paul vont à Rome, André en Grèce, Thomas en Inde, Matthieu en Éthiopie, Barthélemy en Arménie. Jean, dernier apôtre vivant, meurt vers l''an 100. Les évêques, successeurs des apôtres, transmettent la foi par l''imposition des mains.", "pattern": "Envoi → voyages (tradition) → mort de Jean vers 100 → sièges apostoliques → succession.", "examples": [{"text": "Un siège apostolique est fondé par un apôtre ou un proche.", "translation": "Jérusalem, Antioche, Rome, Éphèse et Alexandrie en sont."}], "commonErrors": [{"wrong": "La liste des voyages des apôtres est certaine.", "right": "Elle repose souvent sur la tradition.", "why": "L''histoire exacte de chaque voyage nous échappe."}], "tip": "Siège = fauteuil de l''évêque ; apostolique = fondé par un apôtre."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g110.marc', 'eg', 'grammar', 'knowledge', 'Saint Marc et le cordonnier Anianos', 1, '{}'::text[], 1, '{"rule": {"summary": "Vers 49-50 (date discutée), Marc arrive à Alexandrie. Selon la tradition copte, il guérit le cordonnier Anianos, son premier converti, et fonde l''Église d''Alexandrie.", "explanation": "Alexandrie est un grand port grec où vit une forte communauté juive. Marc, cousin de Barnabé et compagnon de Paul puis de Pierre, y arrive. Après la guérison d''Anianos, la famille est baptisée, puis beaucoup de Juifs, de Grecs et d''Égyptiens. Marc ordonne Anianos évêque.", "pattern": "Alexandrie → Marc → sandale déchirée → Anianos guéri → baptêmes → Église → Anianos évêque.", "examples": [{"text": "Marc guérit Anianos au nom du Christ.", "translation": "Anianos devient son premier converti."}], "commonErrors": [{"wrong": "Marc est l''un des Douze.", "right": "Marc est un disciple des apôtres, cousin de Barnabé.", "why": "La tradition copte l''appelle aussi apôtre."}], "tip": "Marc → Anianos → Alexandrie : trois noms pour la fondation."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g111.copte', 'eg', 'grammar', 'knowledge', 'L''Église copte, fille de Marc', 1, '{}'::text[], 1, '{"rule": {"summary": "Marc meurt martyr vers 68 ; Anianos lui succède. Ses reliques partent à Venise en 828 et en partie reviennent au Caire en 1968. Copte vient de Aigyptios : égyptien.", "explanation": "Pendant une fête païenne, une foule traîne Marc dans les rues d''Alexandrie. Il meurt martyr. Il est le premier pape d''Alexandrie, et l''Église d''Égypte commence avec le sang d''un martyr. Le mot copte, du grec Aigyptios, veut dire égyptien.", "pattern": "Martyre vers 68 → Anianos successeur → 828 Venise → 1968 le Caire.", "examples": [{"text": "Copte veut dire « égyptien ».", "translation": "Être copte, c''est être de l''Église d''Égypte."}], "commonErrors": [{"wrong": "Les coptes viennent de Copte, un homme.", "right": "Copte vient du grec Aigyptios, « égyptien ».", "why": "Le mot désigne un peuple et son Église, pas une personne."}], "tip": "Copte = égyptien. Marc → Anianos → 828 → 1968."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g112.bilan', 'eg', 'grammar', 'knowledge', 'Bilan du premier siècle', 1, '{}'::text[], 1, '{"rule": {"summary": "Le premier siècle va de la Pentecôte à saint Marc : l''Église naît à Jérusalem, se disperse, répond à deux erreurs, et arrive en Égypte.", "explanation": "Repères : Pentecôte vers 30, Étienne vers 35, concile de Jérusalem vers 49, incendie de Rome en 64, chute de Jérusalem en 70. Deux erreurs : judaïsants et gnostiques. Marc fonde l''Église d''Alexandrie, qui deviendra l''Église copte.", "pattern": "Pentecôte → Étienne → Paul → concile → persécutions → Jérusalem tombe → écrits → apôtres → Marc.", "examples": [{"text": "Marc fonde l''Église d''Alexandrie.", "translation": "Voilà l''origine de l''Église copte."}], "commonErrors": [{"wrong": "Les deux Jacques sont le même homme.", "right": "Le frère de Jean (44) et le chef de Jérusalem (62).", "why": "Deux martyrs, deux dates."}], "tip": "Jérusalem → les nations → Alexandrie."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g201.releve', 'eg', 'grammar', 'knowledge', 'Les apôtres sont morts : qui garde la foi ?', 2, '{}'::text[], 2, '{"rule": {"summary": "Quand le dernier apôtre meurt, l''Église garde la foi grâce à trois appuis : les Écritures, la tradition et les évêques successeurs des apôtres.", "explanation": "Au début du IIe siècle, plus aucun témoin direct du Christ n''est en vie, alors que l''Église grandit et que les interprétations se multiplient. Les Écritures seules ne suffisent pas, car chacun peut citer un verset à sa façon. L''Église s''appuie donc aussi sur la tradition reçue des apôtres et sur les évêques, qui en sont les successeurs.", "pattern": "Fin des apôtres → hérésies → Écritures + tradition + évêques successeurs des apôtres.", "examples": [{"text": "Les apôtres ont établi des évêques, qui en ont établi d''autres.", "translation": "C''est la succession apostolique."}], "commonErrors": [{"wrong": "La Bible seule règle toutes les disputes.", "right": "La Bible se lit avec la tradition et les évêques.", "why": "Les hérétiques citent eux aussi l''Écriture."}], "tip": "Le livre, la voix, les gardiens : trois appuis."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g202.sieges', 'eg', 'grammar', 'knowledge', 'Quatre Églises, quatre fondateurs', 2, array['eg.g201.releve']::text[], 2, '{"rule": {"summary": "Quatre sièges sont apostoliques, car leur premier évêque est un apôtre : Rome (Pierre et Paul), Alexandrie (Marc), Antioche (Pierre) et Jérusalem (Jacques).", "explanation": "Un siège est la chaise d''un évêque dans sa ville. Dans un siège apostolique, la relève est assurée depuis la source, ce qui lui donne une autorité particulière dans les questions de la foi. Notre Église copte est l''Église d''Alexandrie, fondée par saint Marc.", "pattern": "Rome = Pierre et Paul ; Alexandrie = Marc ; Antioche = Pierre ; Jérusalem = Jacques.", "examples": [{"text": "L''Église copte est le siège de saint Marc.", "translation": "Son premier évêque est un témoin de l''Évangile."}], "commonErrors": [{"wrong": "Marc a fondé l''Église de Rome.", "right": "Marc a fondé l''Église d''Alexandrie.", "why": "Rome vient de Pierre et Paul."}], "tip": "Alexandrie, c''est Marc : c''est nous."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g203.ignace', 'eg', 'grammar', 'knowledge', 'Ignace en route vers les lions', 2, array['eg.g202.sieges']::text[], 2, '{"rule": {"summary": "Après les apôtres viennent les Pères apostoliques : Clément écrit à Corinthe vers 96, Ignace écrit sept lettres en route vers le martyre à Rome vers 110.", "explanation": "Les Pères apostoliques sont proches des apôtres et enseignent les chrétiens par lettres. Ignace d''Antioche, arrêté sous Trajan, insiste sur l''unité autour de l''évêque et sur la réalité du corps du Christ. Il est le premier à parler de l''Église catholique, c''est-à-dire universelle. Vers 112, Trajan répond à Pline de ne pas rechercher les chrétiens mais de punir ceux qu''on dénonce.", "pattern": "Clément (Rome, Corinthiens, 96) → Ignace (Antioche, sept lettres, 110) → Pline et Trajan (112).", "examples": [{"text": "Ignace est le premier à parler de l''Église catholique.", "translation": "Catholique veut dire « selon le tout »."}], "commonErrors": [{"wrong": "Ignace est évêque de Smyrne.", "right": "Ignace est évêque d''Antioche.", "why": "Smyrne est la ville de Polycarpe."}], "tip": "Clément écrit à Corinthe ; Ignace marche vers Rome."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g204.polycarpe', 'eg', 'grammar', 'knowledge', 'Polycarpe sur le bûcher', 2, array['eg.g203.ignace']::text[], 2, '{"rule": {"summary": "Polycarpe, évêque de Smyrne et disciple de Jean, préfère mourir plutôt que de renier le Christ : il relie l''apôtre Jean à Irénée.", "explanation": "Polycarpe, très âgé, est arrêté à Smyrne vers le milieu du IIe siècle. Le proconsul lui demande de renier le Christ. Il répond qu''il le sert depuis 86 ans. Son martyre est l''un des plus anciens récits que nous ayons. Disciple de Jean et maître d''Irénée, il montre la chaîne de la foi.", "pattern": "Jean → Polycarpe → Irénée. Polycarpe : arrêté, sommé de renier, refuse, martyr.", "examples": [{"text": "Voilà 86 ans que je le sers, et il ne m''a fait aucun mal.", "translation": "La réponse de Polycarpe au proconsul."}], "commonErrors": [{"wrong": "Polycarpe est évêque d''Antioche.", "right": "Polycarpe est évêque de Smyrne.", "why": "Antioche est la ville d''Ignace."}], "tip": "Polycarpe : 86 ans de service, un seul Roi."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g205.ichthys', 'eg', 'grammar', 'knowledge', 'Le poisson dans le sable', 2, array['eg.g204.polycarpe']::text[], 2, '{"rule": {"summary": "Les chrétiens refusent le culte de l''empereur, d''où les persécutions ; pour se reconnaître, ils dessinent un poisson : ICHTHYS, Jésus Christ, Fils de Dieu, Sauveur.", "explanation": "Rome voit dans le refus du culte de l''empereur un danger pour l''Empire, et des rumeurs absurdes circulent. Selon la tradition, Trajan ordonne la troisième persécution, Marc Aurèle la quatrième (martyrs de Lyon en 177) et Septime Sévère la cinquième (Alexandrie frappée). Pour se reconnaître, les chrétiens tracent un poisson, ICHTHYS.", "pattern": "Refus du culte → rumeurs → persécutions (Trajan 3e, Marc Aurèle 4e, Septime Sévère 5e) → signe du poisson.", "examples": [{"text": "I, X, Θ, Υ, Σ : Jésus Christ, Fils de Dieu, Sauveur.", "translation": "Chaque lettre du poisson est une initiale."}], "commonErrors": [{"wrong": "Les chrétiens refusent de prier pour l''empereur.", "right": "Ils prient pour lui mais ne l''adorent pas.", "why": "Seul Dieu est adoré."}], "tip": "Un poisson, cinq lettres, toute la foi."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g206.justin', 'eg', 'grammar', 'knowledge', 'Justin le philosophe', 2, array['eg.g205.ichthys']::text[], 2, '{"rule": {"summary": "Face aux accusations des païens, les apologistes, comme Justin et Tertullien, défendent la foi : ils écrivent à ceux du dehors, alors que les Pères apostoliques écrivent aux chrétiens.", "explanation": "Justin, philosophe converti à Naplouse et martyr vers 165, montre que le Christ, Verbe de Dieu, accomplit la quête des philosophes : ce sont les semences du Verbe. Tertullien, juriste de Carthage, écrit l''Apologétique en 197 et la phrase célèbre sur le sang des martyrs.", "pattern": "Pères apostoliques → aux chrétiens ; apologistes → aux païens. Justin = semences du Verbe ; Tertullien = Apologétique.", "examples": [{"text": "Justin écrit des Apologies à l''empereur.", "translation": "Il défend les chrétiens devant le pouvoir."}], "commonErrors": [{"wrong": "Les apologistes écrivent pour les chrétiens.", "right": "Ils écrivent pour les païens.", "why": "Ce sont les Pères apostoliques qui parlent aux chrétiens."}], "tip": "Les uns parlent à la maison, les autres à la place publique."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g207.gnose', 'eg', 'grammar', 'knowledge', 'Le savoir secret des gnostiques', 3, array['eg.g206.justin']::text[], 2, '{"rule": {"summary": "Les gnostiques promettent le salut par une connaissance secrète et jugent la matière mauvaise ; le docétisme en découle : le Christ n''aurait eu qu''un corps apparent. L''Église répond par l''Incarnation réelle et l''enseignement public des évêques.", "explanation": "Gnosis veut dire connaissance. Pour les gnostiques, la matière est mauvaise, le monde est l''œuvre d''un démiurge et l''élite est sauvée par une connaissance secrète. De là vient le docétisme : le Christ n''aurait eu qu''un corps apparent. L''Église répond avec Ignace (le corps du Christ est réel) et Irénée de Lyon (enseignement public des évêques, reçu des apôtres).", "pattern": "Gnose : connaissance secrète + matière mauvaise → docétisme : corps apparent → réponse : Ignace, Irénée.", "examples": [{"text": "« Le Verbe s''est fait chair » (Jean 1, 14).", "translation": "Le Christ est réellement homme."}], "commonErrors": [{"wrong": "Le Christ n''avait qu''un corps apparent.", "right": "Le Christ a eu un vrai corps.", "why": "Sans vrai corps, pas de vraie croix ni de vrai salut."}], "tip": "Un mot à retenir : réel. Le Christ est réellement homme."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g208.marcion', 'eg', 'grammar', 'knowledge', 'Marcion déchire la Bible', 3, array['eg.g207.gnose']::text[], 2, '{"rule": {"summary": "Marcion croit à deux dieux et ne garde que Luc et dix lettres de Paul. L''Église répond : un seul Dieu est l''auteur des deux Testaments.", "explanation": "Marcion, armateur de Sinope, vient à Rome vers 140 et en est exclu vers 144. Il oppose un Dieu de justice, créateur, à un Dieu d''amour, Père de Jésus, et rejette l''Ancien Testament. Sa liste réduite oblige l''Église à préciser quels livres elle reçoit : le canon. Tertullien écrit Contre Marcion.", "pattern": "Marcion = deux dieux, rejet de l''Ancien Testament, Luc + dix lettres de Paul → l''Église : un seul Dieu, deux Testaments.", "examples": [{"text": "Marcion ne garde que Luc et dix lettres de Paul.", "translation": "La Bible « taillée aux ciseaux »."}], "commonErrors": [{"wrong": "Marcion garde tout le Nouveau Testament.", "right": "Il ne garde que Luc et dix lettres de Paul.", "why": "Il rejette le reste."}], "tip": "Marcion = ciseaux : deux dieux, une Bible coupée."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g209.montan', 'eg', 'grammar', 'knowledge', 'Montan et la nouvelle prophétie', 3, array['eg.g208.marcion']::text[], 2, '{"rule": {"summary": "Montanus se dit organe du Paraclet et annonce la fin des temps ; l''Église refuse sa nouvelle prophétie : la Révélation est complète en Christ et les apôtres.", "explanation": "Vers 170 en Phrygie, Montanus et deux prophétesses, Priscilla et Maximilla, annoncent l''âge de l''Esprit, exigent la continence parfaite et cherchent le martyre. L''Église condamne le mouvement : la Révélation est complète, et l''Évangile conseille de fuir la persécution. Tertullien finit par le rejoindre.", "pattern": "Montanus (Phrygie, 170) : Paraclet, fin des temps, martyre → l''Église : Révélation complète.", "examples": [{"text": "Montanus se dit l''organe du Paraclet.", "translation": "Il prétend parler au nom de l''Esprit Saint."}], "commonErrors": [{"wrong": "L''Église doit chercher le martyre.", "right": "L''Église accepte le martyre mais ne le cherche pas.", "why": "Jésus dit de fuir dans une autre ville."}], "tip": "Montan = transe : une prophétie qui prétend dépasser le Christ."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g210.canon', 'eg', 'grammar', 'knowledge', 'Quels livres garder ?', 3, array['eg.g209.montan']::text[], 2, '{"rule": {"summary": "Face à Marcion et aux gnostiques, l''Église précise quels livres sont Écriture (le canon) et confesse la règle de foi, racine du Credo.", "explanation": "Le canon est la liste des livres reçus, choisie selon l''origine apostolique, l''accord avec la foi et l''usage dans les Églises. Irénée défend les quatre Évangiles ; le Fragment de Muratori, à Rome, est une des plus anciennes listes. La règle de foi résume la foi du baptême et sert de clé de lecture. En 367, Athanase donne la liste des 27 livres.", "pattern": "Marcion → besoin d''une liste → canon + règle de foi ; 4 Évangiles (Irénée) ; 27 livres (Athanase, 367).", "examples": [{"text": "Canon veut dire « règle ».", "translation": "C''est la règle qui mesure les livres reçus."}], "commonErrors": [{"wrong": "Le canon a été fixé en une fois, au IIe siècle.", "right": "Le IIe siècle a l''essentiel ; la liste des 27 livres date de 367.", "why": "Athanase la donne en 367."}], "tip": "Canon = règle ; règle de foi = plan du roi."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g211.demetrios', 'eg', 'grammar', 'knowledge', 'Démétrios, le vigneron devenu pape', 3, array['eg.g210.canon']::text[], 2, '{"rule": {"summary": "En 189, selon la tradition, Démétrios, un paysan devenu XIIe pape d''Alexandrie, fixe le calendrier des fêtes, place le carême avant la semaine sainte et soutient l''école d''Alexandrie.", "explanation": "Démétrios est élu pape d''Alexandrie en 189 après un signe donné au pape Julien : une grappe de raisin hors saison. Dans la dispute sur la date de Pâques (14 Nisan ou dimanche suivant), Alexandrie fixe des règles de calcul avec l''épacte. L''école théologique d''Alexandrie renaît vers 190.", "pattern": "Démétrios 189 : grappe de raisin → Pâques et carême → école d''Alexandrie.", "examples": [{"text": "Le carême précède la semaine sainte.", "translation": "Démétrios le place juste avant."}], "commonErrors": [{"wrong": "Démétrios est un savant dès sa jeunesse.", "right": "Selon la tradition, c''est un paysan sans instruction.", "why": "Dieu lui donne d''apprendre à lire."}], "tip": "Démétrios = grappe de raisin = 189."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g212.bilan', 'eg', 'grammar', 'knowledge', 'Bilan du IIe siècle', 3, array['eg.g211.demetrios']::text[], 2, '{"rule": {"summary": "Au IIe siècle, l''Église garde la foi par les Écritures (canon), la succession apostolique et la règle de foi, face au gnosticisme, au docétisme, au marcionisme et au montanisme.", "explanation": "Les Pères apostoliques enseignent les chrétiens, les apologistes défendent la foi devant les païens, Irénée répond aux gnostiques. L''Église paie un lourd prix sous les persécutions et se reconnaît au signe du poisson. À Alexandrie, Démétrios fixe les fêtes et soutient l''école.", "pattern": "Frise : Ignace 110, Marcion 140, Montan 170, Lyon 177, Démétrios 189.", "examples": [{"text": "Gnose = savoir secret ; docétisme = fantôme ; Marcion = ciseaux ; Montan = transe.", "translation": "Un mot pour chaque erreur."}], "commonErrors": [{"wrong": "Les quatre hérésies disent toutes la même chose.", "right": "Chacune touche un point différent : salut, Christ, Dieu, Esprit.", "why": "Il ne faut pas les confondre."}], "tip": "Trois remparts, quatre erreurs, cinq repères."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g301.rumeurs', 'eg', 'grammar', 'knowledge', 'Pourquoi Rome persécute les chrétiens', 1, '{}'::text[], 3, '{"rule": {"summary": "Les chrétiens refusent le culte impérial, se cachent, et la foule invente des rumeurs : tout cela alimente les persécutions.", "explanation": "À Rome, sacrifier en public prouve qu''on est loyal. Les chrétiens refusent : ils passent pour de mauvais citoyens. Leur secret nourrit les rumeurs (anthropophagie, meurtre rituel) et les philosophes les traitent d''athées. Les édits sont appliqués plus ou moins fort selon les villes : les persécutions viennent par vagues.", "pattern": "Refus du sacrifice → secret → méfiance → rumeurs → colère → édits.", "examples": [{"text": "Les chrétiens ne sacrifient pas, donc on les soupçonne.", "translation": "Le refus du geste de loyauté crée la méfiance."}, {"text": "On dit qu''ils mangent de la chair humaine.", "translation": "Une fausse rumeur, née de paroles mal comprises."}], "commonErrors": [{"wrong": "Les chrétiens se révoltent contre l''empereur.", "right": "Les chrétiens refusent seulement d''adorer d''autres dieux.", "why": "C''est de la fidélité à Dieu, pas de la rébellion."}], "tip": "Refus → secret → rumeurs → colère."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g302.edit_de_dece', 'eg', 'grammar', 'knowledge', 'L''édit de Dèce et le libellus', 2, array['eg.g301.rumeurs']::text[], 3, '{"rule": {"summary": "En 250, l''édit de Dèce oblige tout le monde à sacrifier. Celui qui sacrifie reçoit un certificat, le libellus.", "explanation": "Maximin ouvre la série vers 235 en frappant les chefs de l''Église. Dèce, vers 249, ordonne la septième persécution : en 250, son édit impose le sacrifice à tous. Un chrétien peut refuser et risquer la mort, sacrifier, ou se procurer un faux libellus. Ceux qui cèdent par peur seront appelés les « tombés ».", "pattern": "Maximin (235) → Dèce (249) → édit de 250 → sacrifice → libellus → les « tombés ».", "examples": [{"text": "Dèce ordonne la septième persécution.", "translation": "Vers 249, après Maximin (sixième)."}, {"text": "Il présente son libellus.", "translation": "Preuve qu''il a sacrifié."}], "commonErrors": [{"wrong": "Le libellus est un ordre de l''empereur.", "right": "Le libellus est un certificat reçu après le sacrifice.", "why": "L''ordre, c''est l''édit ; le libellus en est la preuve."}], "tip": "Édit = ordre. Libellus = reçu."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g303.tombes_et_novatien', 'eg', 'grammar', 'knowledge', 'Les « tombés » et Novatien', 2, array['eg.g302.edit_de_dece']::text[], 3, '{"rule": {"summary": "Les tombés veulent revenir. Novatien refuse tout pardon ; l''Église reçoit les vrais pénitents après une pénitence sincère.", "explanation": "Après la persécution de Dèce, que faire de ceux qui ont renié la foi ? En 251, Novatien se fait consacrer évêque de Rome contre Corneille : pour lui, l''Église doit rester pure, sans pardon. L''Église répond qu''il faut recevoir les vrais pénitents après une pénitence sincère. Novatien est excommunié en 251 par les conciles de Rome et de Carthage, combattu par Denys d''Alexandrie et Cyprien.", "pattern": "Persécution → chute → repentir → pénitence → retour. Novatien : chute → porte fermée.", "examples": [{"text": "L''Église accueille les vrais pénitents.", "translation": "Le retour est possible, mais par la pénitence."}, {"text": "Novatien veut une Église des purs.", "translation": "Il oublie que le Christ est venu chercher les pécheurs."}], "commonErrors": [{"wrong": "Novatien est un ignorant.", "right": "Novatien est un théologien très instruit.", "why": "Son erreur est dans la discipline, pas dans l''ignorance."}], "tip": "Pas de pardon facile, pas de porte fermée : la pénitence."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g304.valerien_semence', 'eg', 'grammar', 'knowledge', 'Valérien, Cyprien et la semence de chrétiens', 2, array['eg.g303.tombes_et_novatien']::text[], 3, '{"rule": {"summary": "Valérien frappe le clergé (huitième persécution, vers 257) ; Cyprien est décapité en 258. Mais le sang des martyrs est semence de chrétiens.", "explanation": "L''Église numérote dix grandes persécutions. Au IIIe siècle : Maximin (6e, vers 235), Dèce (7e, vers 249), Valérien (8e, vers 257) et une neuvième vers 274. Valérien interdit les assemblées et frappe le clergé ; il est capturé par les Perses en 260 et son fils Gallien arrête la persécution. Les persécutions généralisées viendront avec Dioclétien.", "pattern": "6 Maximin (235) → 7 Dèce (249) → 8 Valérien (257) → 9 (vers 274) → 10 Dioclétien.", "examples": [{"text": "Valérien est capturé par les Perses en 260.", "translation": "Son fils Gallien arrête alors la persécution."}], "commonErrors": [{"wrong": "Les persécutions du IIIe siècle touchent tout l''Empire en même temps.", "right": "Elles sont locales, par vagues.", "why": "Il faut attendre Dioclétien pour des persécutions généralisées."}], "tip": "Un numéro, un empereur : 6, 7, 8, 9."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g305.diocletien_284', 'eg', 'grammar', 'knowledge', 'Dioclétien et le calendrier copte', 2, array['eg.g304.valerien_semence']::text[], 3, '{"rule": {"summary": "Dioclétien devient empereur en 284 ; en 303 éclate la grande persécution. Les Coptes font de 284 l''an 1 de leur calendrier.", "explanation": "Sous Dioclétien (dixième persécution), la persécution est générale pour la première fois. En 303, les édits ordonnent de détruire les églises et de brûler les livres. Les Coptes ont fait de l''année de l''accession de Dioclétien, 284, la première année de leur calendrier : c''est l''ère des martyrs. Le jour de l''an s''appelle le Nayrouz.", "pattern": "284 Dioclétien → 303 grande persécution → ère des martyrs → l''an 1 = 284.", "examples": [{"text": "Après le Nayrouz de 2026, on est en l''an 1743.", "translation": "2026 moins 283 égale 1743."}], "commonErrors": [{"wrong": "Les Coptes honorent Dioclétien avec leur calendrier.", "right": "Ils honorent les martyrs.", "why": "Le calendrier garde leur mémoire, pas celle de l''empereur."}], "tip": "Année copte = année actuelle − 283 (après le Nayrouz)."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g306.desert_paul_antoine', 'eg', 'grammar', 'knowledge', 'Le désert : Paul de Thèbes et Antoine', 2, array['eg.g305.diocletien_284']::text[], 3, '{"rule": {"summary": "Sous Dèce, Paul de Thèbes fuit au désert : le premier ermite. Antoine, vers 270, y va par choix : le père des moines.", "explanation": "Que faire quand on ne veut ni sacrifier ni mourir ? Paul de Thèbes fuit au désert vers 250 et y reste seul des décennies. Vers 270, Antoine, jeune Égyptien riche, entend l''Évangile, donne ses biens et part aussi. Ce qui était une fuite devient une vocation : le désert est un martyre de chaque jour et le berceau du monachisme.", "pattern": "Persécution de Dèce (250) → Paul au désert → Antoine (270) → monachisme.", "examples": [{"text": "Paul reste le premier ermite ; Antoine, le père des moines.", "translation": "Le premier à partir n''est pas le plus célèbre."}], "commonErrors": [{"wrong": "Antoine est le premier ermite.", "right": "Paul de Thèbes est le premier ermite.", "why": "Antoine devient le maître de ceux qui viennent après."}], "tip": "Paul = premier. Antoine = père."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g307.ecole_alexandrie', 'eg', 'grammar', 'knowledge', 'L''École d''Alexandrie', 2, array['eg.g306.desert_paul_antoine']::text[], 3, '{"rule": {"summary": "L''École d''Alexandrie, née pour instruire les catéchumènes, devient la première école de théologie : Pantène, Clément, Origène.", "explanation": "Alexandrie est la ville des savants. Selon la tradition, saint Marc fonde l''École, qui instruit d''abord les catéchumènes. Pantène (vers 180) montre qu''on peut aimer la sagesse grecque sans quitter la foi. Clément voit dans la philosophie une préparation à l''Évangile. Origène compose les Hexaples et cherche le sens spirituel de l''Écriture ; certaines de ses idées ont pourtant été rejetées.", "pattern": "Marc → l''École → Pantène → Clément → Origène.", "examples": [{"text": "Clément écrit le Pédagogue et les Stromates.", "translation": "Deux œuvres pour expliquer la foi aux gens instruits."}], "commonErrors": [{"wrong": "Toutes les idées d''Origène ont été suivies.", "right": "Certaines ont été rejetées.", "why": "On admire le savant sans suivre toutes ses idées."}], "tip": "Pantène l''ouvre, Clément la relie à la philosophie, Origène la creuse."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g308.deux_pieges_trinite', 'eg', 'grammar', 'knowledge', 'Paul de Samosate, Sabellius et la Trinité', 3, array['eg.g307.ecole_alexandrie']::text[], 3, '{"rule": {"summary": "Paul de Samosate fait du Christ un simple homme ; Sabellius confond les trois personnes. L''Église tient entre les deux : trois personnes, une seule divinité.", "explanation": "Paul de Samosate, évêque d''Antioche protégé par la reine Zénobie, enseigne que le Christ est un homme ordinaire. Un synode se réunit vers 264 ; le pape Denys écrit une lettre. En 269, Paul est excommunié et exilé de son siège. Sabellius tombe dans l''erreur inverse : un seul Dieu qui change de masque. Les deux sont combattus.", "pattern": "Paul : le Christ n''est qu''un homme. Sabellius : trois personnes confondues. Église : trois personnes, une seule divinité.", "examples": [{"text": "Le Fils est consubstantiel au Père.", "translation": "De même nature, égal à lui dans la divinité."}], "commonErrors": [{"wrong": "Sabellius dit que le Christ n''est qu''un homme.", "right": "C''est Paul de Samosate qui le dit.", "why": "Sabellius confond les personnes en un seul acteur."}], "tip": "Paul rabaisse le Fils. Sabellius confond les trois."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g309.mani_manicheisme', 'eg', 'grammar', 'knowledge', 'Mani et le manichéisme', 3, array['eg.g308.deux_pieges_trinite']::text[], 3, '{"rule": {"summary": "Mani fonde le manichéisme : un Dieu bon crée l''esprit, un démiurge mauvais crée la matière. L''Église le refuse car il est incompatible avec l''Incarnation.", "explanation": "Le Perse Mani, influencé par la gnose, imagine deux principes à l''origine du monde : un Dieu bon (anges, âmes) et un démiurge mauvais (corps). Pour lui, toutes les religions sont valides et on se réincarne. Pour l''Église, si le corps est mauvais, Dieu ne peut pas se faire homme : le manichéisme est incompatible avec l''Incarnation. Saint Augustin y a adhéré avant de se convertir.", "pattern": "Esprit bon + matière mauvaise → corps mauvais → pas d''Incarnation possible → rejet.", "examples": [{"text": "Le manichéisme sépare l''esprit bon et la matière mauvaise.", "translation": "Deux principes opposés."}], "commonErrors": [{"wrong": "Pour Mani, un seul Dieu a tout créé.", "right": "Pour Mani, un Dieu bon et un démiurge mauvais.", "why": "Deux principes à l''origine du monde."}], "tip": "Deux principes : Dieu bon (esprit), démiurge mauvais (corps)."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g310.sainte_tradition', 'eg', 'grammar', 'knowledge', 'La sainte Tradition et le canon', 3, array['eg.g309.mani_manicheisme']::text[], 3, '{"rule": {"summary": "L''Église précède le Nouveau Testament : elle l''écrit puis le reconnaît comme Écriture, grâce à quatre critères dont le principal est l''approbation apostolique.", "explanation": "Les apôtres prêchaient avant que les évangiles soient écrits. L''Église a construit le Nouveau Testament en deux phases : écrire les textes à l''époque apostolique, puis les reconnaître comme Écritures. Ce tri donne trois familles d''écrits : canoniques, honorables mais non inspirés, apocryphes. Quatre critères : caractère apostolique, valeur spirituelle, conformité à la doctrine, consensus des Églises.", "pattern": "Prédication → écriture → reconnaissance comme Écriture (quatre critères).", "examples": [{"text": "La Didachè et le Pasteur d''Hermas restent hors du canon.", "translation": "Honorables, mais pas inspirés."}], "commonErrors": [{"wrong": "Le Nouveau Testament existait avant l''Église.", "right": "L''Église précède le Nouveau Testament.", "why": "Les apôtres prêchaient avant que les évangiles soient écrits."}], "tip": "Quatre critères : apôtres, esprit, doctrine, consensus."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g311.heraclas_hierarchie', 'eg', 'grammar', 'knowledge', 'L''organisation de l''Église et Héraclas', 3, array['eg.g310.sainte_tradition']::text[], 3, '{"rule": {"summary": "Au IIIe siècle, la hiérarchie à trois degrés s''affirme. Héraclas, 13e évêque d''Alexandrie, est le premier appelé pape.", "explanation": "Au début, surveillants, serviteurs et anciens dirigent ensemble. Dès le IIe siècle, un évêque unique, successeur des apôtres. Au IIIe siècle, les trois degrés s''affirment : évêque, prêtre, diacre, avec la distinction clercs et laïcs. Les prophètes des premiers temps ont disparu avec les temps apostoliques. Héraclas est le premier appelé pape ; patriarche viendra en 451.", "pattern": "Équipe → évêque unique (IIe siècle) → trois degrés (IIIe siècle) → Héraclas, pape.", "examples": [{"text": "Diacre veut dire serviteur ; presbytre, ancien ; épiscope, surveillant.", "translation": "Trois mots grecs, trois services."}], "commonErrors": [{"wrong": "Le titre de patriarche existe depuis Héraclas.", "right": "Pape depuis Héraclas ; patriarche seulement à partir de 451.", "why": "Deux titres, deux époques."}], "tip": "Pape depuis Héraclas, patriarche depuis 451."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g312.bilan_troisieme_siecle', 'eg', 'grammar', 'knowledge', 'Bilan du troisième siècle', 3, array['eg.g311.heraclas_hierarchie']::text[], 3, '{"rule": {"summary": "Le IIIe siècle en un coup d''œil : persécutions, tombés, hérésies, désert, École, calendrier copte, Tradition et hiérarchie.", "explanation": "Maximin (235), Dèce (249, édit de 250), Valérien (257), puis Dioclétien (284, grande persécution de 303). Les tombés posent la question du pardon. Paul de Samosate, Sabellius et Mani déforment la foi ; Novatien ferme la porte au repentir. Le désert (Paul, Antoine) et l''École (Pantène, Clément, Origène) répondent autrement. 284 devient l''an 1 des Coptes. Héraclas est le premier pape.", "pattern": "Persécutions → tombés → hérésies → désert et École → Tradition et hiérarchie.", "examples": [{"text": "L''an 1 des Coptes, c''est 284.", "translation": "L''accession de Dioclétien, en mémoire des martyrs."}], "commonErrors": [{"wrong": "Sabellius et Paul de Samosate disent la même chose.", "right": "Paul rabaisse le Christ ; Sabellius confond les personnes.", "why": "Deux erreurs opposées."}], "tip": "Frise : 235, 249-250, 257, 284, 303."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g401.grande_persecution', 'eg', 'grammar', 'knowledge', 'La grande persécution (303-311)', 2, '{}'::text[], 4, '{"rule": {"summary": "De 303 à 311, Dioclétien puis Galère tentent d''effacer l''Église. En 311, Galère malade signe l''édit de tolérance.", "explanation": "Quatre édits frappent d''abord les églises et les livres, puis les chefs, puis tous les chrétiens. Galère, successeur de Dioclétien en 305, est encore plus cruel. Le pape Pierre d''Alexandrie, le sceau des martyrs, meurt en 311, l''année de l''édit de tolérance.", "pattern": "303 : quatre édits → 305 : Galère → 311 : pape Pierre martyr et édit de tolérance.", "examples": [{"text": "Les chrétiens ont le droit d''exister et de prier.", "translation": "C''est le contenu de l''édit de 311."}], "commonErrors": [{"wrong": "L''édit de 311 donne la pleine liberté.", "right": "L''édit de 311 tolère ; la liberté vient en 313.", "why": "311 est signé par un empereur malade, 313 par Constantin et Licinius."}], "tip": "311 = on tolère. 313 = on est libre."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g402.constantin', 'eg', 'grammar', 'knowledge', 'Constantin et l''édit de Milan (313)', 2, array['eg.g401.grande_persecution']::text[], 4, '{"rule": {"summary": "En 312, Constantin bat Maxence sous le signe de la croix. En 313, avec Licinius, il signe l''édit de Milan : la liberté pour les chrétiens.", "explanation": "Selon le récit transmis par l''Église, Constantin voit une croix dans le ciel avant la bataille de 312. Maxence meurt dans le Tibre. L''année suivante, l''édit de Milan met fin aux persécutions romaines et rend aux chrétiens leurs biens.", "pattern": "306 : empereur → 312 : croix et victoire → 313 : édit de Milan.", "examples": [{"text": "« Avec ceci tu vaincras. »", "translation": "Les mots entendus par Constantin, selon le récit."}], "commonErrors": [{"wrong": "L''édit de Milan est signé par Galère.", "right": "Il est signé par Constantin et Licinius.", "why": "Galère signe l''édit de 311, celui de la simple tolérance."}], "tip": "312 la croix, 313 la liberté."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g403.empereur_et_eglise', 'eg', 'grammar', 'knowledge', 'L''empereur et l''Église (330)', 2, array['eg.g402.constantin']::text[], 4, '{"rule": {"summary": "Sous Constantin, l''Église devient proche du pouvoir : Hélène bâtit des églises, Constantinople est fondée en 330, l''empereur se dit « évêque du dehors ».", "explanation": "Hélène retrouve la Sainte Croix à Jérusalem. Constantin fonde Constantinople en 330 et se donne le titre d''évêque du dehors. Cette faveur est un bienfait mais aussi un danger : l''empereur pèse sur les débats de foi.", "pattern": "Paix → faveur de l''empereur → danger d''ingérence.", "examples": [{"text": "Constantin se dit « évêque du dehors ».", "translation": "Il se croit chargé des affaires extérieures de l''Église."}], "commonErrors": [{"wrong": "Constantinople est fondée par Théodose.", "right": "Elle est fondée par Constantin en 330.", "why": "Son nom veut dire « la ville de Constantin »."}], "tip": "Constantin → Constantinople : son nom est dans la ville."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g404.arius', 'eg', 'grammar', 'knowledge', 'Arius et sa phrase (vers 318)', 3, array['eg.g403.empereur_et_eglise']::text[], 4, '{"rule": {"summary": "Vers 318, à Alexandrie, le prêtre Arius enseigne que le Fils a été créé. Cette doctrine s''appelle l''arianisme.", "explanation": "Arius est un prêtre aimé, bon prédicateur. Il dit : « il fut un temps où le Fils n''était pas ». Il met ses idées en chansons, gagne des appuis comme Eusèbe de Nicomédie, malgré le pape Alexandre et un synode qui le condamne.", "pattern": "Une phrase → des chansons → des appuis → une condamnation → une querelle d''Empire.", "examples": [{"text": "« Il fut un temps où le Fils n''était pas. »", "translation": "La phrase qui résume l''arianisme."}], "commonErrors": [{"wrong": "Arius est un empereur.", "right": "Arius est un prêtre d''Alexandrie.", "why": "Il n''a aucun pouvoir politique, mais il a des amis puissants."}], "tip": "Arius dit « créé » ; l''Église répond « Dieu »."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g405.divinite', 'eg', 'grammar', 'knowledge', 'Pourquoi l''arianisme est grave', 3, array['eg.g404.arius']::text[], 4, '{"rule": {"summary": "Seul Dieu peut sauver l''homme : si le Fils est créé, il ne sauve pas. D''où l''enjeu du mot homoousios, « de même substance ».", "explanation": "Une créature ne peut pas en sauver une autre. Si le Christ n''est pas Dieu, l''incarnation, la croix et la résurrection perdent leur sens, et on adorerait une créature. Trois camps : ariens (créé), semi-ariens (semblable), orthodoxes (même substance).", "pattern": "Fils créé → pas de salut. Trois camps : créé / semblable / même.", "examples": [{"text": "Le Fils est homoousios au Père.", "translation": "Il est de même substance que le Père : il est Dieu."}], "commonErrors": [{"wrong": "Homoiousios et homoousios disent la même chose.", "right": "Homoiousios = semblable ; homoousios = même.", "why": "Un iota sépare les deux mots, et c''est tout le salut qui change."}], "tip": "Un iota, tout le salut."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g406.nicee_convocation', 'eg', 'grammar', 'knowledge', 'Nicée 325 : qui, où, quand', 3, array['eg.g405.divinite']::text[], 4, '{"rule": {"summary": "En 325, Constantin convoque à Nicée le premier concile œcuménique, contre Arius. Selon la tradition, 318 évêques y viennent.", "explanation": "Un concile est une assemblée d''évêques qui décident ensemble de la foi ; œcuménique veut dire « de toute la terre habitée ». Selon la tradition copte, le pape Alexandre préside, avec son jeune diacre Athanase, face à Arius et à ses soutiens.", "pattern": "Qui convoque ? Constantin. Où ? Nicée. Quand ? 325. Contre qui ? Arius.", "examples": [{"text": "Nicée est le premier concile œcuménique.", "translation": "Les évêques de toute l''Église y sont invités."}], "commonErrors": [{"wrong": "C''est le pape qui convoque Nicée.", "right": "C''est l''empereur Constantin qui le convoque.", "why": "Constantin voulait un empire uni."}], "tip": "Nicée = Constantin, 325, Arius."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g407.nicee_decisions', 'eg', 'grammar', 'knowledge', 'Le credo de Nicée (325)', 3, array['eg.g406.nicee_convocation']::text[], 4, '{"rule": {"summary": "Nicée décide que le Fils est homoousios au Père, rédige le credo (qui finit par « et en l''Esprit Saint »), excommunie Arius et établit vingt canons.", "explanation": "Le concile choisit un mot que les ariens ne peuvent pas tordre : homoousios. Le credo de Nicée parle du Père et du Fils et finit par « et en l''Esprit Saint ». 315 évêques signent d''abord ; trois résistent aux anathèmes, puis cèdent sous la pression de Constantin.", "pattern": "Homoousios → credo → anathèmes → signatures → vingt canons.", "examples": [{"text": "Le credo de Nicée finit par « et en l''Esprit Saint ».", "translation": "L''Esprit Saint ne sera développé qu''en 381."}], "commonErrors": [{"wrong": "Nicée a écrit tout le Credo de la messe.", "right": "Nicée en pose le cœur ; la suite est ajoutée en 381.", "why": "Le credo de 325 s''arrêtait à « et en l''Esprit Saint »."}], "tip": "Nicée : le Fils. Constantinople : l''Esprit."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g408.athanase_jeune', 'eg', 'grammar', 'knowledge', 'Athanase : de jeune génie à pape', 3, array['eg.g407.nicee_decisions']::text[], 4, '{"rule": {"summary": "Athanase naît vers 298 à Alexandrie, écrit tôt « Sur l''incarnation du Verbe », est le diacre du pape Alexandre à Nicée et lui succède vers 328.", "explanation": "Formé auprès de saint Antoine, devenu diacre et secrétaire du pape Alexandre, il a environ 27 ans à Nicée. Il devient le XXe patriarche d''Alexandrie vers 328 et le restera jusqu''à sa mort en 373.", "pattern": "Vers 298 : naissance → désert → diacre → Nicée (325) → pape (vers 328).", "examples": [{"text": "Athanase a environ 27 ans à Nicée.", "translation": "Il n''est que diacre, mais c''est lui qui parle."}], "commonErrors": [{"wrong": "Athanase préside le concile de Nicée.", "right": "Selon la tradition copte, c''est le pape Alexandre qui préside.", "why": "Athanase est son jeune diacre."}], "tip": "Athanase : 27 ans à Nicée, 30 ans quand il devient pape."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g409.athanase_exils', 'eg', 'grammar', 'knowledge', 'Les exils d''Athanase', 3, array['eg.g408.athanase_jeune']::text[], 4, '{"rule": {"summary": "Après Nicée, des empereurs soutiennent les ariens et exilent Athanase plusieurs fois. Il revient chaque fois, sans changer d''avis.", "explanation": "Athanase se réfugie en Occident ou chez les moines du désert. On lui dit : « le monde est contre toi », il répond qu''il est contre le monde : l''Église l''appelle le défenseur de la foi. En 367, il publie la liste des 27 livres du Nouveau Testament.", "pattern": "Nicée (325) → empereurs ariens → exils → retour → 367 : les 27 livres.", "examples": [{"text": "« Et je suis contre le monde. »", "translation": "Sa réponse à ceux qui lui disaient que le monde était contre lui."}], "commonErrors": [{"wrong": "Après Nicée, l''arianisme est fini.", "right": "Il reste soutenu par des empereurs.", "why": "C''est pourquoi Athanase est exilé."}], "tip": "Exilé, mais jamais vaincu."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g410.monachisme_antoine', 'eg', 'grammar', 'knowledge', 'Le monachisme : Antoine et Paul', 3, array['eg.g409.athanase_exils']::text[], 4, '{"rule": {"summary": "Quand l''Église devient libre et puissante, des chrétiens partent au désert pour vivre l''Évangile plus radicalement : c''est le monachisme, né en Égypte.", "explanation": "Le moine vit de prière, de jeûne et de solitude, avec trois principes : pauvreté, obéissance, chasteté. Saint Paul est le premier ermite ; saint Antoine, copte de Haute-Égypte (251-356), est le père des moines.", "pattern": "Paix de l''Église → appel du désert → ermites (Paul, Antoine) → premiers moines.", "examples": [{"text": "Antoine est le père des moines.", "translation": "Tous les premiers moines sont ses disciples."}], "commonErrors": [{"wrong": "Le monachisme est né à Rome.", "right": "Il est né en Égypte.", "why": "L''Égypte est appelée la mère du monachisme."}], "tip": "Paul, premier ermite ; Antoine, père des moines."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g411.communautes', 'eg', 'grammar', 'knowledge', 'Pacôme, Macaire et les trois modèles', 3, array['eg.g410.monachisme_antoine']::text[], 4, '{"rule": {"summary": "Pacôme fonde en Haute-Égypte les premiers monastères communautaires ; Macaire rassemble des moines à Scété. Trois modèles : Antoine, Pacôme, Chénouté.", "explanation": "Cénobitique veut dire « en communauté » : les moines prient, travaillent et mangent ensemble sous une règle. À la fin du IVe siècle, des milliers de moines vivent au désert, et l''on vient du monde entier les voir.", "pattern": "Antoine (solitude) → Pacôme (communauté) → Macaire (Scété) → Chénouté (discipline stricte).", "examples": [{"text": "Pacôme invente la vie cénobitique.", "translation": "Les moines vivent ensemble sous une règle."}], "commonErrors": [{"wrong": "Pacôme est le premier ermite.", "right": "Le premier ermite est Paul ; Pacôme fonde la vie en communauté.", "why": "Paul et Pacôme ont presque le même nom, pas la même vie."}], "tip": "Antoine seul, Pacôme ensemble."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g412.ethiopie', 'eg', 'grammar', 'knowledge', 'Frumentius et l''Éthiopie', 3, array['eg.g411.communautes']::text[], 4, '{"rule": {"summary": "Vers 341, Athanase ordonne Frumentius premier évêque d''Éthiopie. L''Église d''Éthiopie dépend ensuite d''Alexandrie pendant des siècles.", "explanation": "Selon le récit de l''historien Rufin, Frumentius arrive à Axoum après un naufrage. Il aide à élever le jeune prince, rassemble des chrétiens, puis va à Alexandrie demander un évêque à Athanase, qui l''ordonne lui-même.", "pattern": "Naufrage → cour d''Axoum → Alexandrie → Athanase ordonne Frumentius (vers 341).", "examples": [{"text": "Frumentius est le premier évêque d''Éthiopie.", "translation": "Ordonné à Alexandrie par Athanase."}], "commonErrors": [{"wrong": "L''Éthiopie reçoit l''Évangile de Rome.", "right": "Elle reçoit son premier évêque d''Alexandrie.", "why": "Les Églises copte et éthiopienne sont étroitement liées."}], "tip": "Alexandrie envoie, Éthiopie reçoit."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g413.apollinaire_macedonius', 'eg', 'grammar', 'knowledge', 'Apollinaire, Macédonius et 380', 3, array['eg.g412.ethiopie']::text[], 4, '{"rule": {"summary": "Apollinaire dit que le Christ n''a pas d''âme humaine ; Macédonius dit que le Saint-Esprit est créé. En 380, sous Théodose Ier, le christianisme devient religion de l''État.", "explanation": "Apollinaire, évêque de Laodicée, est excommunié par Athanase en 362 ; Macédonius, évêque de Constantinople, nie la divinité de l''Esprit comme Arius celle du Fils. Le pape Timothée leur répond : pour sauver l''homme tout entier, le Christ doit prendre l''homme tout entier.", "pattern": "Arius : Fils créé. Macédonius : Esprit créé. Apollinaire : pas d''âme humaine.", "examples": [{"text": "Macédonius dit que le Saint-Esprit est créé.", "translation": "Il fait pour l''Esprit ce qu''Arius a fait pour le Fils."}], "commonErrors": [{"wrong": "Apollinaire nie la divinité du Christ.", "right": "Apollinaire nie son âme humaine.", "why": "Le Christ est vrai Dieu et vrai homme."}], "tip": "Apollinaire : le Christ sans âme. Macédonius : l''Esprit sans divinité."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g414.constantinople', 'eg', 'grammar', 'knowledge', 'Le concile de Constantinople (381)', 3, array['eg.g413.apollinaire_macedonius']::text[], 4, '{"rule": {"summary": "En 381, Théodose Ier convoque à Constantinople 150 évêques, contre Apollinaire et Macédonius. Le concile développe l''article sur l''Esprit Saint et complète le credo de Nicée.", "explanation": "Nicée se terminait par « et en l''Esprit Saint ». Constantinople développe : l''Esprit est Seigneur et vivifiant, qui procède du Père, puis ajoute l''Église, le baptême, la résurrection, la vie éternelle. C''est le Credo de la messe.", "pattern": "Théodose, 381, 150 évêques → contre Apollinaire et Macédonius → credo complété → sept canons.", "examples": [{"text": "Le Credo de la messe est celui de Nicée-Constantinople.", "translation": "325 pour le Fils, 381 pour l''Esprit et la suite."}], "commonErrors": [{"wrong": "Le Credo entier date de 325.", "right": "Il date de 325 pour le cœur, complété en 381.", "why": "381 développe l''Esprit Saint et ajoute la suite."}], "tip": "Nicée : le Fils. Constantinople : l''Esprit."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g415.bilan', 'eg', 'grammar', 'knowledge', 'Bilan du IVe siècle', 3, array['eg.g414.constantinople']::text[], 4, '{"rule": {"summary": "Du 311 au 381, l''Église passe de la persécution à la religion d''État, définit sa foi à Nicée et à Constantinople, et voit naître les moines.", "explanation": "Deux conciles, quatre erreurs, un défenseur de la foi, des moines et un credo : voilà le IVe siècle. Chaque erreur touchait au salut ; l''Église a défendu ce qui sauve.", "pattern": "311 · 313 · 325 · 330 · 367 · 380 · 381.", "examples": [{"text": "Nicée pour le Fils, Constantinople pour l''Esprit.", "translation": "Les deux moitiés de notre Credo."}], "commonErrors": [{"wrong": "Constantin convoque Constantinople.", "right": "Théodose Ier convoque Constantinople ; Constantin convoque Nicée.", "why": "Deux empereurs, deux conciles."}], "tip": "Nicée = Fils = Constantin. Constantinople = Esprit = Théodose."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g501.cinq_sieges', 'eg', 'grammar', 'knowledge', 'L''Église unie et ses cinq sièges', 1, '{}'::text[], 5, '{"rule": {"summary": "Vers 400, l''Église est unie autour de cinq grands sièges : quatre apostoliques (Jérusalem, Antioche, Alexandrie, Rome) et Constantinople, qui doit son rang à la capitale. Trois conciles œcuméniques ont eu lieu ou vont avoir lieu : Nicée (325), Constantinople (381), Éphèse (431).", "explanation": "Chaque grande ville a son évêque de premier plan, le patriarche. Constantinople, capitale depuis 330, est le plus jeune siège mais le plus proche de l''empereur. Alexandrie tient le premier rôle dans les conciles (Athanase à Nicée, Cyrille à Éphèse), ce qui fait des jaloux. Le canon 3 de 381 place Constantinople deuxième après Rome, et Alexandrie le refuse.", "pattern": "5 sièges : Jérusalem, Antioche, Alexandrie, Rome (apostoliques) + Constantinople (capitale). 3 conciles : 325, 381, 431.", "examples": [{"text": "En 330, l''empereur Constantin installe sa capitale à Constantinople.", "translation": "C''est la « nouvelle Rome »."}, {"text": "En 325, le concile de Nicée condamne Arius.", "translation": "Athanase d''Alexandrie est le grand défenseur de la foi."}, {"text": "En 381, le canon 3 place Constantinople juste après Rome.", "translation": "Alexandrie refuse ce classement."}], "commonErrors": [{"wrong": "Constantinople est un siège apostolique.", "right": "Constantinople doit son rang à la capitale de l''empire.", "why": "Les quatre autres sièges remontent aux apôtres."}, {"wrong": "Le concile d''Éphèse est le deuxième concile œcuménique.", "right": "C''est le troisième, après Nicée et Constantinople.", "why": "325, 381, 431 : environ cinquante ans d''écart à chaque fois."}], "tip": "325, 381, 431 : trois conciles, un demi-siècle entre chacun."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g502.nestorius_chaire', 'eg', 'grammar', 'knowledge', 'Nestorius et le mot Théotokos', 2, array['eg.g501.cinq_sieges']::text[], 5, '{"rule": {"summary": "En 428, Nestorius, moine formé à Antioche, devient patriarche de Constantinople. Il refuse d''appeler Marie « Théotokos » (mère de Dieu) et préfère « Christotokos » (mère du Christ).", "explanation": "Nestorius craint que « mère de Dieu » fasse croire que Dieu a commencé d''exister dans le ventre de Marie. Les fidèles, attachés au titre Théotokos, s''inquiètent : la question derrière le titre est de savoir qui est exactement Jésus.", "pattern": "Nestorius (428) → refuse Théotokos → propose Christotokos → la foule s''inquiète.", "examples": [{"text": "En 428, Nestorius devient patriarche de Constantinople.", "translation": "C''est un prédicateur célèbre."}, {"text": "Il préfère dire « Christotokos ».", "translation": "Pour lui : mère du Christ."}, {"text": "Les fidèles se demandent : qui est né de Marie ?", "translation": "La question porte sur Jésus, pas seulement sur Marie."}], "commonErrors": [{"wrong": "Nestorius est le patriarche d''Alexandrie.", "right": "Il est patriarche de Constantinople.", "why": "Alexandrie, c''est Cyrille."}, {"wrong": "Théotokos veut dire « mère du Christ ».", "right": "Théotokos veut dire « celle qui enfante Dieu ». « Mère du Christ », c''est Christotokos.", "why": "Deux mots proches, deux théologies différentes."}], "tip": "Théo = Dieu, Christo = Christ : le titre que tu choisis dit qui tu crois que Jésus est."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g503.protege_christ', 'eg', 'grammar', 'knowledge', 'Pourquoi Théotokos protège le Christ', 2, array['eg.g502.nestorius_chaire']::text[], 5, '{"rule": {"summary": "Le Verbe, Fils de Dieu, s''est fait homme en Marie (incarnation). Si celle qui l''enfante n''est pas Théotokos, on coupe Jésus en deux (nestorianisme) et le salut est en danger : le mot protège d''abord le Christ.", "explanation": "Le Verbe est le Fils de Dieu éternel. À l''incarnation, il devient vraiment homme sans cesser d''être Dieu. Appeler Marie Théotokos, c''est dire que celui qu''elle enfante est Dieu le Verbe fait chair : un seul Fils. L''école d''Antioche distingue soigneusement le divin et l''humain, Alexandrie insiste sur l''unité.", "pattern": "Le Verbe s''incarne en Marie → celui qu''elle enfante est Dieu → Marie est Théotokos → un seul Christ, un salut réel.", "examples": [{"text": "Le Verbe s''est fait chair.", "translation": "Jean 1 : le Fils de Dieu devient homme."}, {"text": "Marie est Théotokos car celui qu''elle enfante est le Verbe.", "translation": "Le titre parle du Christ autant que de Marie."}, {"text": "Le nestorianisme sépare le Verbe de l''homme Jésus.", "translation": "C''est l''enseignement que l''Église condamne."}], "commonErrors": [{"wrong": "Théotokos veut dire que Marie existe avant Dieu.", "right": "Il veut dire que celui qu''elle enfante est Dieu le Verbe fait chair.", "why": "Marie enfante le Verbe incarné, pas la divinité elle-même."}, {"wrong": "Théotokos est un simple compliment à Marie.", "right": "C''est d''abord une protection pour le Christ.", "why": "Sans ce mot, on ne sait plus qui est mort sur la croix."}], "tip": "Pas de Théotokos, pas de Dieu dans la crèche : le titre de Marie garde la divinité de Jésus."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g504.nature_personne', 'eg', 'grammar', 'knowledge', 'Nature et personne', 2, array['eg.g503.protege_christ']::text[], 5, '{"rule": {"summary": "La nature, c''est ce qu''on est (humain, par exemple) ; la personne, c''est qui on est (quelqu''un qui dit « je »). Jésus est une seule personne, vraiment Dieu et vraiment homme.", "explanation": "Tous les humains partagent la même nature humaine, mais chacun est une personne unique. Chez Jésus, une seule personne, le Verbe, est vraiment Dieu et vraiment homme. Les adversaires de Nestorius lui reprochent de faire deux personnes dans le Christ ; Cyrille répond qu''il n''y a qu''un seul « je ». Ces deux mots reviendront dans toute la crise.", "pattern": "Nature = CE QU''on est. Personne = QUI on est. Jésus : une seule personne, vraiment Dieu et vraiment homme.", "examples": [{"text": "Pierre et Paul ont la même nature humaine.", "translation": "Mais ce sont deux personnes différentes."}, {"text": "Le Christ est une seule personne.", "translation": "Un seul « je » : le Verbe fait chair."}, {"text": "Dieu, homme : ce sont des natures.", "translation": "Marie, le Verbe, toi : ce sont des personnes."}], "commonErrors": [{"wrong": "Une personne, c''est la même chose qu''une nature.", "right": "La nature dit CE QU''on est ; la personne dit QUI on est.", "why": "Pierre et Paul : même nature, deux personnes."}, {"wrong": "Jésus est deux personnes, l''une divine et l''autre humaine.", "right": "Jésus est une seule personne, vraiment Dieu et vraiment homme.", "why": "C''est ce que ses adversaires reprochent à Nestorius de ne pas respecter."}], "tip": "Nature = « quoi ? ». Personne = « qui ? »."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g505.cyrille', 'eg', 'grammar', 'knowledge', 'Saint Cyrille d''Alexandrie et sa formule', 2, array['eg.g504.nature_personne']::text[], 5, '{"rule": {"summary": "Cyrille, 24e pape d''Alexandrie (412-444), le Pilier de la foi, défend Théotokos et résume la foi en « une seule nature du Verbe incarné ». Il joint douze anathèmes à sa lettre à Nestorius ; Rome (Célestin Ier) le soutient en 430.", "explanation": "Cyrille écrit aux moines d''Égypte puis à Nestorius. Pour lui, toucher à Théotokos, c''est toucher à l''identité de Jésus. Il compare l''union du Verbe et de la chair à celle de l''âme et du corps : un seul homme. Les douze anathèmes sont jugés trop durs à Antioche. Nestorius ne cède pas, et l''empereur convoque un concile.", "pattern": "Moines d''Égypte → lettres à Nestorius → formule → douze anathèmes → Rome le soutient (430) → concile.", "examples": [{"text": "Cyrille est le Pilier de la foi.", "translation": "Surnom de l''Église copte pour le 24e pape."}, {"text": "« Une seule nature du Verbe incarné. »", "translation": "La formule de Cyrille."}, {"text": "L''âme et le corps ne font qu''un seul homme.", "translation": "L''image de Cyrille pour l''unité du Christ."}], "commonErrors": [{"wrong": "Cyrille est le 25e pape d''Alexandrie.", "right": "Cyrille est le 24e ; Dioscore est le 25e.", "why": "Cyrille 412-444, puis Dioscore."}, {"wrong": "Cyrille veut séparer le divin et l''humain.", "right": "Cyrille insiste sur l''unité du Christ.", "why": "Un seul Verbe fait chair."}], "tip": "Cyrille = 24e pape = Pilier de la foi = « une seule nature du Verbe incarné »."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g506.ephese_431', 'eg', 'grammar', 'knowledge', 'Le concile d''Éphèse (431)', 3, array['eg.g505.cyrille']::text[], 5, '{"rule": {"summary": "Théodose II convoque le concile d''Éphèse (431), troisième concile œcuménique. Cyrille le préside ; Nestorius refuse de comparaître ; Jean d''Antioche arrive en retard et tient un concile rival.", "explanation": "Environ deux cents évêques se réunissent dans l''église dédiée à Marie. Cyrille ouvre le concile sans attendre Jean d''Antioche et les évêques d''Orient, retardés. Nestorius est condamné le jour même. Les Orientaux tiennent leur propre concile et déposent Cyrille : l''empereur doit trancher.", "pattern": "Théodose II convoque → Cyrille préside → Nestorius absent → Jean en retard → deux conciles rivaux → l''empereur tranche.", "examples": [{"text": "En 431, le concile se réunit à Éphèse.", "translation": "Dans l''église dédiée à Marie."}, {"text": "Jean d''Antioche arrive après l''ouverture.", "translation": "Il tient un concile rival."}, {"text": "Cyrille préside, Nestorius ne vient pas.", "translation": "Il refuse de comparaître."}], "commonErrors": [{"wrong": "Le concile d''Éphèse est présidé par Jean d''Antioche.", "right": "Cyrille le préside.", "why": "Jean arrive en retard."}, {"wrong": "Éphèse 431 est le deuxième concile œcuménique.", "right": "C''est le troisième.", "why": "325, 381, 431."}], "tip": "Éphèse 431 = Théodose II convoque, Cyrille préside, Jean est en retard, deux conciles."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g507.decisions_ephese', 'eg', 'grammar', 'knowledge', 'Les décisions du concile d''Éphèse', 3, array['eg.g506.ephese_431']::text[], 5, '{"rule": {"summary": "Éphèse (431) dépose et anathématise Nestorius, proclame Marie Théotokos, confirme le credo de Nicée en interdisant d''en composer un autre, et condamne aussi Pélage. Nestorius est exilé en Haute-Égypte.", "explanation": "Ces décisions sont celles que l''Église copte reconnaît pleinement : Éphèse est son troisième concile. Plus tard, les coptes reprocheront à Chalcédoine d''ajouter une nouvelle définition à un credo qu''Éphèse avait interdit de changer. Selon la tradition copte, Nestorius finit ses jours à Akhmim.", "pattern": "Éphèse : Nestorius déposé + Théotokos + credo intouchable + Pélage condamné.", "examples": [{"text": "Éphèse proclame Marie Théotokos.", "translation": "Celle qui enfante Dieu."}, {"text": "Il est interdit de composer un autre credo.", "translation": "Le credo de Nicée suffit."}, {"text": "Pélage nie la nécessité de la grâce.", "translation": "Le concile le condamne."}], "commonErrors": [{"wrong": "Éphèse condamne Eutychès.", "right": "Éphèse condamne Nestorius (et Pélage).", "why": "Eutychès n''apparaît qu''en 448."}, {"wrong": "Éphèse écrit un nouveau credo.", "right": "Éphèse confirme celui de Nicée et interdit d''en composer un autre.", "why": "C''est pourquoi les coptes jugent Chalcédoine problématique."}], "tip": "Éphèse : déposer Nestorius, honorer Marie, garder le credo, rappeler la grâce."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g508.formule_union', 'eg', 'grammar', 'knowledge', 'La formule d''union (433) et la paix fragile', 3, array['eg.g507.decisions_ephese']::text[], 5, '{"rule": {"summary": "En 433, Cyrille et Jean d''Antioche signent la formule d''union : Jean accepte la déposition de Nestorius et Théotokos, Cyrille un vocabulaire plus nuancé. La question du nombre de natures reste ouverte. Cyrille meurt en 444 ; Dioscore lui succède, Flavien devient patriarche de Constantinople en 446.", "explanation": "Après Éphèse, les Orientaux restent fâchés contre les anathèmes de Cyrille. L''empereur veut la paix. Le compromis de 433 apaise les esprits mais ne tranche pas : une ou deux natures ? Des partisans de Nestorius gagnent la Perse, où naît l''Église de l''Orient. En 444, Dioscore succède à Cyrille.", "pattern": "431 Éphèse → 433 formule d''union → 444 mort de Cyrille, Dioscore 25e pape → 446 Flavien.", "examples": [{"text": "En 433, Cyrille et Jean d''Antioche signent un compromis.", "translation": "La formule d''union."}, {"text": "Des partisans de Nestorius partent en Perse.", "translation": "Naissance de l''Église de l''Orient."}, {"text": "En 444, Dioscore succède à Cyrille.", "translation": "Il est le 25e pape."}], "commonErrors": [{"wrong": "L''Église de l''Orient est l''Église copte.", "right": "C''est une Église née en Perse chez des partisans de Nestorius.", "why": "Rien à voir avec l''Église copte."}, {"wrong": "Après 433, tout est réglé.", "right": "La question « une ou deux natures ? » reste ouverte.", "why": "La paix est fragile."}], "tip": "431 le choc, 433 la paix, 444 le départ de Cyrille."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g509.eutyches', 'eg', 'grammar', 'knowledge', 'Eutychès et le monophysisme', 3, array['eg.g508.formule_union']::text[], 5, '{"rule": {"summary": "Eutychès, archimandrite près de Constantinople, enseigne que la divinité absorbe l''humanité du Christ (monophysisme). Flavien le condamne en 448 ; il fait appel à l''empereur et à Dioscore. L''Église copte condamne aussi cette erreur.", "explanation": "Là où Nestorius sépare, Eutychès mélange : l''humanité disparaît dans la divinité comme une goutte de miel dans la mer. Alors Jésus ne serait plus vraiment homme comme nous. Eutychès cite Cyrille, mais les mêmes mots n''ont pas le même sens : chez Cyrille, l''union garde l''humanité entière. L''Église copte n''est pas monophysite.", "pattern": "Nestorius sépare, Eutychès mélange. 448 : synode de Flavien → appel à Théodose II et à Dioscore → concile à Éphèse (449).", "examples": [{"text": "Eutychès est archimandrite près de Constantinople.", "translation": "Chef d''un grand monastère."}, {"text": "L''humanité est absorbée, comme du miel dans la mer.", "translation": "L''image d''Eutychès."}, {"text": "En 448, Flavien condamne Eutychès.", "translation": "Synode de Constantinople."}], "commonErrors": [{"wrong": "Les coptes suivent Eutychès.", "right": "L''Église copte condamne le monophysisme.", "why": "Elle est miaphysite, comme Cyrille."}, {"wrong": "Eutychès sépare le Verbe de l''homme Jésus.", "right": "Eutychès mélange : l''humanité est absorbée.", "why": "C''est Nestorius, selon ses adversaires, qui séparait."}], "tip": "Nestorius sépare, Eutychès mélange : deux erreurs opposées."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g510.fer_feu', 'eg', 'grammar', 'knowledge', 'Une union sans mélange ni division', 3, array['eg.g509.eutyches']::text[], 5, '{"rule": {"summary": "Les Pères comparent l''union du divin et de l''humain à l''âme et au corps, ou au fer chauffé au rouge : le fer reste du fer et brille comme le feu. Contrairement à la goutte de miel, rien ne disparaît.", "explanation": "Fer = humanité, feu = divinité du Verbe. Unis, ils ne font plus qu''un, mais le fer ne cesse pas d''être du fer. « Sans mélange » : l''humanité ne disparaît pas. « Sans division » : le Christ n''est pas coupé en deux. L''Église copte proclame cette foi à la confession, avant la communion.", "pattern": "Fer + feu = un seul tout, le fer reste du fer. Miel + mer = le miel disparaît.", "examples": [{"text": "Le fer chauffé au rouge reste du fer.", "translation": "Mais il brille comme le feu."}, {"text": "Sans mélange, sans division.", "translation": "L''union est réelle et rien n''est détruit."}, {"text": "La goutte de miel disparaît dans la mer.", "translation": "C''est l''image d''Eutychès, pas celle de Cyrille."}], "commonErrors": [{"wrong": "L''image du fer vient d''Eutychès.", "right": "L''image du miel illustre Eutychès ; le fer illustre la foi de Cyrille.", "why": "Le fer reste du fer, le miel disparaît."}, {"wrong": "Sans division veut dire que le divin disparaît.", "right": "Sans division veut dire que le Christ n''est pas coupé en deux.", "why": "Sans mélange protège l''humanité, sans division protège l''unité."}], "tip": "Fer et feu : unis mais pas confondus. Miel et mer : confondus."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g511.mono_dyo_mia', 'eg', 'grammar', 'knowledge', 'Monophysisme, dyophysisme, miaphysisme', 4, array['eg.g510.fer_feu']::text[], 5, '{"rule": {"summary": "Physis = nature. Mono (un seul) : le monophysisme d''Eutychès, condamné par les coptes. Dyo (deux) : le dyophysisme de Chalcédoine. Mia (une seule, unie) : le miaphysisme de Cyrille et de l''Église copte, sans mélange ni division.", "explanation": "Le miaphysisme n''est pas le monophysisme : le Christ est pleinement humain et pleinement divin, uni sans mélange ni division. Le dyophysisme distingue deux natures après l''union ; ses défenseurs veulent ainsi protéger la réalité de l''humanité du Christ. Les mots diffèrent, et les deux familles confessent un seul Christ.", "pattern": "mono = humanité absorbée ; dyo = deux natures ; mia = une nature unie, sans mélange ni division.", "examples": [{"text": "Les coptes sont miaphysites.", "translation": "Pas monophysites."}, {"text": "Chalcédoine : un Christ en deux natures.", "translation": "C''est le dyophysisme."}, {"text": "Mia physis : une seule nature unie.", "translation": "La formule de Cyrille."}], "commonErrors": [{"wrong": "Les coptes sont monophysites.", "right": "Les coptes sont miaphysites.", "why": "Le monophysisme est la position d''Eutychès, que l''Église copte condamne."}, {"wrong": "Miaphysisme veut dire que l''humanité disparaît.", "right": "Miaphysisme veut dire une nature unie, sans mélange ni division.", "why": "Chez Cyrille, rien n''est détruit."}], "tip": "Mono supprime l''humanité, dyo distingue deux natures, mia unit sans mélange ni division."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g512.ephese_449', 'eg', 'grammar', 'knowledge', 'Le deuxième concile d''Éphèse (449)', 4, array['eg.g511.mono_dyo_mia']::text[], 5, '{"rule": {"summary": "Éphèse II (août 449), convoqué par Théodose II et présidé par Dioscore, réhabilite Eutychès et dépose Flavien sans que le Tome de Léon soit lu. Léon Ier le nomme « brigandage d''Éphèse » ; l''Église copte conteste l''accusation faite à Dioscore.", "explanation": "Léon envoie des légats avec le Tome de Léon. Dioscore interroge Eutychès, qui cite Cyrille ; il le réhabilite. Il accuse Flavien d''avoir enfreint Nicée et Éphèse I en définissant la double nature, et le dépose. Faute de temps, la séance se clôt par les lettres de l''empereur, sans le Tome. Les rivalités entre sièges rejoignent la théologie.", "pattern": "Août 449 : Théodose II convoque → Dioscore préside → Eutychès réhabilité → Flavien déposé → Tome non lu → Léon : « brigandage ».", "examples": [{"text": "Dioscore préside Éphèse II.", "translation": "En 449."}, {"text": "Flavien est déposé, le Tome n''est pas lu.", "translation": "Faute de temps, selon le récit copte."}, {"text": "Léon appelle ce concile le brigandage d''Éphèse.", "translation": "L''Église copte défend Dioscore."}], "commonErrors": [{"wrong": "Éphèse II est un concile œcuménique reconnu par les coptes.", "right": "Les coptes reconnaissent trois conciles : Nicée, Constantinople, Éphèse I.", "why": "Éphèse II est un concile contesté."}, {"wrong": "Dioscore a été condamné pour hérésie à Éphèse II.", "right": "Dioscore préside Éphèse II ; c''est à Chalcédoine qu''il sera jugé, pour sa conduite.", "why": "Pas pour une hérésie."}], "tip": "449 : Dioscore préside, Flavien est déposé, le Tome n''est pas lu."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g513.chalcedoine', 'eg', 'grammar', 'knowledge', 'Le concile de Chalcédoine (451)', 4, array['eg.g512.ephese_449']::text[], 5, '{"rule": {"summary": "Marcien, devenu empereur en 450, convoque Chalcédoine (451) à la demande de Léon. Le Tome de Léon y est ratifié et le Christ défini « en deux natures ». Le canon 28 place Constantinople deuxième. L''Église copte refuse le concile : c''est le premier schisme.", "explanation": "Les évêques de l''Est non-chalcédonien (Alexandrie, Antioche) rejettent « deux natures », qu''ils ressentent comme nestorienne et comme une innovation. Les coptes ne reconnaissent que trois conciles. Haines nationales, rivalités et jalousies aggravent les mots.", "pattern": "450 Marcien → 451 Chalcédoine : Tome ratifié, deux natures, canon 28 → premier schisme.", "examples": [{"text": "En 451, Marcien réunit le concile à Chalcédoine.", "translation": "En face de Constantinople."}, {"text": "« Un seul Christ en deux natures. »", "translation": "La définition de Chalcédoine."}, {"text": "Le canon 28 place Constantinople deuxième.", "translation": "Léon le refuse."}], "commonErrors": [{"wrong": "Chalcédoine est le quatrième concile œcuménique pour les coptes.", "right": "Les coptes ne reconnaissent pas Chalcédoine.", "why": "Ils reconnaissent trois conciles."}, {"wrong": "Chalcédoine dit que le Christ n''a qu''une nature.", "right": "Chalcédoine dit un Christ en deux natures.", "why": "Le miaphysisme, lui, dit une nature unie."}], "tip": "451 : « deux natures » → Alexandrie et Antioche refusent → premier schisme."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g514.dioscore', 'eg', 'grammar', 'knowledge', 'Saint Dioscore, confesseur de la foi', 4, array['eg.g513.chalcedoine']::text[], 5, '{"rule": {"summary": "Saint Dioscore, 25e pape d''Alexandrie (444-454), ancien archidiacre de Cyrille, est déposé à Chalcédoine pour sa conduite à Éphèse II et pour avoir refusé de comparaître, non pour une hérésie. Selon la tradition copte, il refuse de signer la définition. Exilé à Gangra, il meurt en 454 : l''Église copte l''honore comme confesseur de la foi.", "explanation": "On lui reproche trois choses : avoir accepté l''erreur d''Eutychès, condamné Flavien sans raison et refusé de lire le Tome de Léon. Selon la tradition copte, chaque accusation a une réponse : le Christ est UN, Flavien avait enfreint Nicée et Éphèse I, et le Tome n''a pas été lu faute de temps.", "pattern": "Disciple de Cyrille → Éphèse II → jugé à Chalcédoine (déposé pour sa conduite) → exil à Gangra → mort en 454 → confesseur.", "examples": [{"text": "Dioscore était l''archidiacre de Cyrille.", "translation": "Son premier assistant."}, {"text": "Dioscore est déposé pour sa conduite, non pour hérésie.", "translation": "Selon les actes de Chalcédoine."}, {"text": "Dioscore meurt à Gangra en 454.", "translation": "Un confesseur de la foi."}], "commonErrors": [{"wrong": "Dioscore a été condamné comme hérétique à Chalcédoine.", "right": "Selon les actes, il est déposé pour sa conduite, non pour hérésie.", "why": "Les accusations portaient sur sa conduite à Éphèse II et son refus de comparaître."}, {"wrong": "Dioscore est mort martyr.", "right": "Dioscore est un confesseur : il souffre pour sa foi sans mourir martyr.", "why": "Il meurt en exil, en 454."}], "tip": "Dioscore = disciple de Cyrille, trois accusations, Gangra, 454, confesseur."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g515.deux_patriarches', 'eg', 'grammar', 'knowledge', 'Après 451 : l''Hénotikon et les deux patriarches', 4, array['eg.g514.dioscore']::text[], 5, '{"rule": {"summary": "Après Chalcédoine, l''empereur Zénon tente l''apaisement par l''Hénotikon (482), puis Justinien persécute les non-chalcédoniens (dès 527) et nomme en 538 un patriarche chalcédonien d''Alexandrie : l''Égypte a dès lors deux patriarches, l''un melkite, l''autre copte.", "explanation": "Les melkites (« gens du roi », du syriaque malka) sont les chrétiens qui acceptent Chalcédoine et restent fidèles à l''empereur. Les coptes restent fidèles à Dioscore. Les persécutions durent jusqu''à la conquête arabe vers 640. La division née en 451 demeure.", "pattern": "451 → 482 Hénotikon → 527 persécutions → 538 patriarche imposé → melkites / coptes → vers 640 conquête arabe.", "examples": [{"text": "L''Hénotikon se tait sur le nombre de natures.", "translation": "Il ne satisfait personne."}, {"text": "Les melkites sont les gens du roi.", "translation": "Fidèles à l''empereur et à Chalcédoine."}, {"text": "Il y a aujourd''hui un patriarche grec orthodoxe d''Alexandrie.", "translation": "En plus du pape copte."}], "commonErrors": [{"wrong": "Les melkites sont des coptes.", "right": "Les melkites acceptent Chalcédoine ; les coptes la refusent.", "why": "Melkite = fidèle à l''empereur."}, {"wrong": "L''Hénotikon a réglé le conflit.", "right": "Il se tait sur la question et ne satisfait personne.", "why": "Il interdit même de poser la question."}], "tip": "482 Hénotikon, 538 Justinien, melkites = gens du roi, deux patriarches à Alexandrie."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g516.aujourd_hui', 'eg', 'grammar', 'knowledge', 'Trois conciles, six Églises sœurs, l''accord de 1989', 4, array['eg.g515.deux_patriarches']::text[], 5, '{"rule": {"summary": "Les Églises orthodoxes orientales (dont l''Église copte) reconnaissent trois conciles, les Églises chalcédoniennes sept. Six Églises sœurs sont en intercommunion. L''accord de 1989 à Amba Bichoï a constaté la même christologie ; il reste les anathèmes.", "explanation": "La rupture de 451 dure, mais le dialogue a beaucoup avancé au XXe siècle. Les deux familles ont reconnu avoir la même foi en un seul Christ, vraiment Dieu et vraiment homme, avec des mots différents. L''unité visible n''est pas encore rétablie. Le schisme de 1054 est un autre schisme.", "pattern": "3 conciles (copte) / 7 conciles (chalcédoniens). 6 Églises sœurs. 1989 : même christologie. Reste : les anathèmes.", "examples": [{"text": "L''Église copte reconnaît trois conciles.", "translation": "Nicée, Constantinople, Éphèse."}, {"text": "En 1989, un accord est signé à Amba Bichoï.", "translation": "Les deux familles reconnaissent la même christologie."}, {"text": "1054 n''est pas 451.", "translation": "C''est un autre schisme."}], "commonErrors": [{"wrong": "Les coptes et les orthodoxes byzantins sont en communion.", "right": "Ils partagent la même christologie, mais l''unité visible n''est pas rétablie.", "why": "Il reste les anathèmes."}, {"wrong": "Le schisme de 1054 est celui de 451.", "right": "Ce sont deux ruptures différentes.", "why": "451 : Chalcédoine. 1054 : Rome et Constantinople."}], "tip": "Trois conciles, six Églises sœurs, 1989 à Amba Bichoï, 1054 = autre schisme."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g517.bilan', 'eg', 'grammar', 'knowledge', 'Bilan du cinquième siècle', 4, array['eg.g516.aujourd_hui']::text[], 5, '{"rule": {"summary": "428 à 451 : Nestorius sépare (selon ses adversaires), Eutychès mélange, Cyrille unit. Théotokos protège le Christ. L''Église copte, miaphysite, reconnaît trois conciles, honore Cyrille et Dioscore, et partage aujourd''hui avec les chalcédoniens la même christologie.", "explanation": "Une seule personne, vraiment Dieu et vraiment homme. Nature = ce qu''on est, personne = qui on est. Mono (humanité absorbée), dyo (deux natures), mia (nature unie, sans mélange ni division). 451 ouvre le premier schisme ; 1989 reconnaît la même christologie.", "pattern": "428 · 431 · 433 · 444 · 448 · 449 · 451 · 482 · 538 · 1989.", "examples": [{"text": "Nestorius sépare, Eutychès mélange, Cyrille unit.", "translation": "Trois positions, trois verbes."}, {"text": "Nature : ce qu''on est. Personne : qui on est.", "translation": "Ne pas confondre."}, {"text": "Même Christ, mots différents.", "translation": "Ce que tu peux dire à un ami."}], "commonErrors": [{"wrong": "Les coptes sont monophysites.", "right": "Les coptes sont miaphysites.", "why": "Ils condamnent Eutychès."}, {"wrong": "Dioscore a été condamné pour hérésie.", "right": "Il est déposé pour sa conduite.", "why": "Selon les actes de Chalcédoine."}], "tip": "Sépare, mélange, unis : Nestorius, Eutychès, Cyrille."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g601.logique_concile', 'eg', 'grammar', 'knowledge', 'La logique d''un concile', 2, array['eg.g517.bilan']::text[], 6, '{"rule": {"summary": "Une erreur menace la foi, des évêques se réunissent en concile, fixent une formule, et parfois leur réponse provoque l''erreur inverse.", "explanation": "Un concile répond toujours à une erreur. Il produit une formule de foi, des anathèmes et des canons. Un synode est local ; un concile œcuménique réunit toute l''Église. Pour les coptes, trois conciles sont reçus : Nicée, Constantinople, Éphèse.", "pattern": "erreur → concile → formule de foi → réception (et parfois erreur inverse)", "examples": [{"text": "Arius dit que le Fils est créé ; Nicée répond homoousios.", "translation": "Une erreur, un concile, une formule."}, {"text": "Nestorius sépare, Eutychès mélange.", "translation": "La réponse trop forte tombe dans l''erreur inverse."}], "commonErrors": [{"wrong": "Les canons disent qui est le Christ.", "right": "Les canons règlent la vie de l''Église.", "why": "C''est la formule de foi qui dit qui est Dieu et le Christ."}], "tip": "Erreur, concile, formule, réception : le refrain des six chapitres."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g602.erreurs_avant_nicee', 'eg', 'grammar', 'knowledge', 'Avant Nicée : quatre erreurs', 2, array['eg.g601.logique_concile']::text[], 6, '{"rule": {"summary": "Avant Nicée, quatre erreurs : la gnose, Marcion, Mani et Montan. Les trois premières font du monde l''œuvre d''un autre dieu ; la quatrième ajoute une nouvelle prophétie.", "explanation": "Gnose : un savoir secret sauve. Marcion : deux dieux, un seul Testament. Mani : un Dieu bon pour l''esprit, un démiurge mauvais pour la matière. Montan : une nouvelle prophétie. L''Église répond : un seul Dieu bon, la foi publique des apôtres, la Révélation complète.", "pattern": "gnose = savoir secret · Marcion = deux dieux · Mani = esprit bon, matière mauvaise · Montan = nouvelle prophétie", "examples": [{"text": "Le démiurge a fait le monde, disent les gnostiques.", "translation": "Un dieu inférieur : voilà l''erreur."}, {"text": "Marcion garde Luc et dix lettres de Paul.", "translation": "Il coupe la Bible."}], "commonErrors": [{"wrong": "Marcion croit en trois dieux.", "right": "Marcion croit en deux dieux.", "why": "Un Dieu de justice et un Dieu d''amour."}], "tip": "Gnose, Marcion, Mani : un second dieu. Montan : une prophétie en plus."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g603.erreurs_trinite', 'eg', 'grammar', 'knowledge', 'Père, Fils, Esprit : quatre erreurs', 3, array['eg.g602.erreurs_avant_nicee']::text[], 6, '{"rule": {"summary": "Quatre erreurs cassent l''équilibre de la Trinité : Paul de Samosate réduit le Christ à un homme, Sabellius mélange les trois, Arius crée le Fils, Macédonius crée l''Esprit.", "explanation": "L''Église confesse trois personnes et une seule divinité. Paul de Samosate (condamné en 269) fait du Christ un homme ordinaire. Sabellius fait des trois des masques. Arius (Nicée 325) fait du Fils une créature. Macédonius (Constantinople 381) fait de l''Esprit une créature.", "pattern": "Paul = simple homme · Sabellius = trois masques · Arius = Fils créé · Macédonius = Esprit créé", "examples": [{"text": "Il fut un temps où le Fils n''était pas.", "translation": "La phrase d''Arius."}, {"text": "Le Saint-Esprit est créé.", "translation": "La phrase de Macédonius."}], "commonErrors": [{"wrong": "Sabellius sépare les trois personnes.", "right": "Sabellius les mélange.", "why": "Un seul Dieu à trois masques."}], "tip": "Paul : homme. Sabellius : masques. Arius : Fils créé. Macédonius : Esprit créé."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g604.erreurs_christ', 'eg', 'grammar', 'knowledge', 'Qui est le Christ ? Quatre erreurs et une voie', 3, array['eg.g603.erreurs_trinite']::text[], 6, '{"rule": {"summary": "Quatre erreurs sur le Christ oublient chacune une pièce du puzzle : le corps (docétisme), l''âme (Apollinaire), l''unité (Nestorius), l''humanité (Eutychès). Cyrille tient le milieu.", "explanation": "Le docétisme nie le vrai corps. Apollinaire nie l''âme humaine. Nestorius, selon ses adversaires, sépare en deux personnes. Eutychès fait absorber l''humanité. Cyrille confesse un seul Christ, vraiment Dieu et vraiment homme, sans mélange ni division, comme le fer rougi au feu.", "pattern": "vrai corps · âme humaine · une personne · humanité gardée", "examples": [{"text": "Le fer rougi reste du fer.", "translation": "L''humanité du Christ n''est pas absorbée."}, {"text": "Un seul « je ».", "translation": "Contre Nestorius."}], "commonErrors": [{"wrong": "Les coptes sont monophysites.", "right": "Les coptes sont miaphysites.", "why": "Ils condamnent Eutychès."}], "tip": "Corps, âme, une personne, humanité gardée : les quatre garde-fous."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g605.fiche_nicee', 'eg', 'grammar', 'knowledge', 'Nicée 325 en fiche', 3, array['eg.g604.erreurs_christ']::text[], 6, '{"rule": {"summary": "Nicée, 325 : Constantin convoque, à Nicée, contre Arius ; on décide homoousios, un credo et vingt canons ; les héros sont Alexandre et Athanase.", "explanation": "Chaque concile se range dans la même grille : qui convoque, où, quand, contre qui, ce qu''on décide, les héros. Nicée : Constantin, Nicée (İznik), 325, Arius ; homoousios, credo, vingt canons, Arius excommunié ; Alexandre et Athanase.", "pattern": "Constantin · Nicée · 325 · Arius · homoousios · Alexandre et Athanase", "examples": [{"text": "Qui convoque ? Constantin. Où ? Nicée. Quand ? 325.", "translation": "Les trois premières cases."}, {"text": "Contre qui ? Arius.", "translation": "La quatrième case."}], "commonErrors": [{"wrong": "Le credo de Nicée est celui qu''on récite à la messe.", "right": "Celui de la messe est Nicée-Constantinople.", "why": "Nicée finit à « et en l''Esprit Saint »."}], "tip": "Six cases : qui, où, quand, contre qui, décision, héros."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g606.fiche_constantinople', 'eg', 'grammar', 'knowledge', 'Constantinople 381 en fiche', 3, array['eg.g605.fiche_nicee']::text[], 6, '{"rule": {"summary": "Constantinople, 381 : Théodose Ier convoque 150 évêques contre Apollinaire et Macédonius ; le credo de Nicée est complété ; le canon 3 place Constantinople après Rome.", "explanation": "Théodose Ier convoque le deuxième concile œcuménique à Constantinople en 381. Contre Apollinaire (un Christ sans âme humaine) et Macédonius (un Esprit créé). Décisions : le credo de Nicée-Constantinople, sept canons, dont le canon 3. Héros : le pape Timothée, Grégoire le Théologien.", "pattern": "Théodose Ier · Constantinople · 381 · Apollinaire et Macédonius · credo complété · Timothée et Grégoire", "examples": [{"text": "Le Credo de la messe est celui de 381.", "translation": "Nicée-Constantinople."}, {"text": "Alexandrie refuse le canon 3.", "translation": "Le rang ne doit pas dépendre de la capitale."}], "commonErrors": [{"wrong": "Constantinople a changé le cœur du credo de Nicée.", "right": "Constantinople l''a complété.", "why": "Nicée a posé le cœur : le Fils est de même substance."}], "tip": "381 : l''Esprit Saint. 325 : le Fils."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g607.fiche_ephese', 'eg', 'grammar', 'knowledge', 'Éphèse 431 en fiche', 3, array['eg.g606.fiche_constantinople']::text[], 6, '{"rule": {"summary": "Éphèse, 431 : Théodose II convoque environ 200 évêques contre Nestorius ; Cyrille préside ; Marie est Théotokos, le credo ne change plus.", "explanation": "Théodose II convoque Éphèse en 431. Cyrille préside avec l''appui de Rome. Nestorius refuse de comparaître et est condamné, Marie est proclamée Théotokos, le credo de Nicée est confirmé et on interdit d''en composer un autre. Pélage est aussi condamné.", "pattern": "Théodose II · Éphèse · 431 · Nestorius · Théotokos, credo intouchable · Cyrille", "examples": [{"text": "À Éphèse, Cyrille préside.", "translation": "Le pape d''Alexandrie a le premier rôle."}, {"text": "Nestorius finit à Akhmim.", "translation": "Exilé en Haute-Égypte."}], "commonErrors": [{"wrong": "Éphèse a lieu à Constantinople.", "right": "Éphèse est en Asie Mineure.", "why": "Nestorius était patriarche de Constantinople, mais le concile est à Éphèse."}], "tip": "431 : Cyrille, Théotokos, le troisième des trois."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g608.fiches_ephese2_chalcedoine', 'eg', 'grammar', 'knowledge', 'Éphèse II et Chalcédoine en fiches', 4, array['eg.g607.fiche_ephese']::text[], 6, '{"rule": {"summary": "Éphèse II (449, Dioscore préside) et Chalcédoine (451, Marcien convoque) ne font pas partie des trois conciles des coptes : deux natures, un credo ajouté, un schisme.", "explanation": "Éphèse II : Théodose II, 1er août 449, Dioscore préside, Eutychès est réhabilité, Flavien déposé, le Tome non lu. Chalcédoine : Marcien, octobre 451, le Tome ratifié, deux natures, canon 28, Dioscore déposé pour sa conduite. Les coptes ne le reçoivent pas.", "pattern": "Éphèse II = Dioscore, 449 · Chalcédoine = Marcien et Léon, 451 · coptes : trois conciles seulement", "examples": [{"text": "Léon nomme Éphèse II un brigandage.", "translation": "Un jugement romain."}, {"text": "Dioscore est exilé à Gangra.", "translation": "Il est confesseur de la foi."}], "commonErrors": [{"wrong": "Dioscore est déposé pour hérésie.", "right": "Il est déposé pour sa conduite et son refus de comparaître.", "why": "Les actes du concile le disent."}], "tip": "449 : Dioscore préside. 451 : Marcien convoque. Les coptes : trois conciles."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g609.frise', 'eg', 'grammar', 'knowledge', 'La grande frise', 3, array['eg.g608.fiches_ephese2_chalcedoine']::text[], 6, '{"rule": {"summary": "La frise des conciles : 49 Jérusalem, 325 Nicée, 381 Constantinople, 431 Éphèse, 449 Éphèse II, 451 Chalcédoine ; puis 482, 538, 1054, 1989.", "explanation": "Les dates se retiennent par paquets : 49-269 (les premiers synodes), 313-325 (la paix puis Nicée), 380-381 (Théodose), 428-433 (Nestorius et Éphèse), 444-451 (Dioscore, Éphèse II, Chalcédoine), puis la suite du schisme.", "pattern": "49 · 269 · 313 · 325 · 381 · 431 · 433 · 449 · 451 · 482 · 538 · 1054 · 1989", "examples": [{"text": "325, 381, 431 : les trois conciles des coptes.", "translation": "Une suite d''environ cinquante ans, puis cinquante ans."}, {"text": "449 puis 451 : Éphèse II puis Chalcédoine.", "translation": "Deux ans de différence."}], "commonErrors": [{"wrong": "Chalcédoine est avant Éphèse II.", "right": "Éphèse II (449) précède Chalcédoine (451).", "why": "Chalcédoine veut annuler Éphèse II."}], "tip": "Nicée, puis cinquante-six ans, Constantinople ; puis cinquante, Éphèse ; puis vingt, Chalcédoine."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g610.homonymes', 'eg', 'grammar', 'knowledge', 'Les paires à ne jamais confondre', 3, array['eg.g609.frise']::text[], 6, '{"rule": {"summary": "Plusieurs noms se ressemblent et piègent : Éphèse 431 et 449, trois Paul, deux Eusèbe, deux Cyrille et Cyprien, deux Théodose, deux Clément et deux Macaire.", "explanation": "Pour ne pas se tromper, on rattache chaque nom à une marque : un lieu, un concile, un geste. Paul de Thèbes : le corbeau. Paul de Samosate : Antioche 269. Eusèbe de Nicomédie : ami d''Arius. Eusèbe de Césarée : l''historien. Cyrille d''Alexandrie : Éphèse 431.", "pattern": "nom + marque : un lieu, un concile, un geste", "examples": [{"text": "Cyprien est évêque de Carthage.", "translation": "Pas Cyrille."}, {"text": "Théodose II convoque les deux Éphèse.", "translation": "Théodose Ier, lui, convoque Constantinople."}], "commonErrors": [{"wrong": "Paul de Samosate est l''ermite au corbeau.", "right": "Le corbeau nourrit Paul de Thèbes.", "why": "Samosate est l''évêque condamné en 269."}], "tip": "Un nom, une marque : le corbeau, l''historien, le Pilier, le brigandage."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g611.mots_jumeaux', 'eg', 'grammar', 'knowledge', 'Les mots jumeaux', 4, array['eg.g610.homonymes']::text[], 6, '{"rule": {"summary": "Des mots presque identiques disent des choses opposées : homoousios/homoiousios, Théotokos/Christotokos, mia/mono/dyo, nature/personne, deux credos, deux schismes.", "explanation": "Un iota sépare Nicée des semi-ariens. Théotokos honore Marie et protège le Christ, Christotokos laisse un doute. Mia unit sans absorber ; mono absorbe ; dyo distingue. Nature dit ce qu''on est, personne dit qui on est. Le schisme de 451 n''est pas celui de 1054.", "pattern": "iota · Théotokos / Christotokos · mia / mono / dyo · nature / personne · 451 / 1054", "examples": [{"text": "Les coptes sont miaphysites, pas monophysites.", "translation": "Une lettre qui change tout."}, {"text": "Le Christ est une personne et deux réalités, divine et humaine.", "translation": "Nature : ce qu''il est. Personne : qui il est."}], "commonErrors": [{"wrong": "Les coptes sont monophysites.", "right": "Les coptes sont miaphysites.", "why": "Ils condamnent Eutychès."}], "tip": "Mia unit, mono absorbe, dyo distingue."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g612.trois_formules', 'eg', 'grammar', 'knowledge', 'Les trois formules à savoir dire', 4, array['eg.g611.mots_jumeaux']::text[], 6, '{"rule": {"summary": "Trois formules résument la foi : homoousios (Nicée, contre Arius), Théotokos (Éphèse, contre Nestorius), « une seule nature du Verbe incarné » (Cyrille, sans mélange ni division).", "explanation": "Le Fils est Dieu comme le Père (homoousios). Celui qui naît de Marie est ce Fils : Marie est Théotokos. Il est un seul Christ, Dieu et homme, sans mélange ni division : une seule nature du Verbe incarné. Chaque formule protège la précédente.", "pattern": "Fils Dieu (homoousios) → Marie mère de Dieu (Théotokos) → un seul Christ (une nature unie)", "examples": [{"text": "Le Credo dit : de même substance que le Père.", "translation": "C''est homoousios."}, {"text": "La tasbeha chante Marie Théotokos.", "translation": "C''est la foi d''Éphèse."}], "commonErrors": [{"wrong": "Théotokos veut dire mère du Christ.", "right": "Théotokos veut dire mère de Dieu.", "why": "Christotokos est le mot de Nestorius."}], "tip": "Fils Dieu, Marie mère de Dieu, un seul Christ."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g613.bilan', 'eg', 'grammar', 'knowledge', 'Bilan : conciles et hérésies', 4, array['eg.g612.trois_formules']::text[], 6, '{"rule": {"summary": "Tout se range : cinq conciles, huit erreurs, trois formules, trois pièges.", "explanation": "Nicée (Arius), Constantinople (Apollinaire, Macédonius), Éphèse (Nestorius), Éphèse II, Chalcédoine. Les coptes reconnaissent les trois premiers. Chaque erreur oublie une pièce, chaque formule la protège.", "pattern": "erreur → concile → formule → réception", "examples": [{"text": "Arius : Nicée : homoousios.", "translation": "Une erreur, un concile, une formule."}, {"text": "Nestorius : Éphèse : Théotokos.", "translation": "Idem au Ve siècle."}], "commonErrors": [{"wrong": "Éphèse II fait partie des trois conciles.", "right": "Seuls Nicée, Constantinople, Éphèse comptent.", "why": "449 est le « brigandage »."}], "tip": "Frise, erreurs, formules, pièges."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g701.quatre_familles', 'eg', 'grammar', 'knowledge', 'Les quatre grandes familles de chrétiens', 1, '{}'::text[], 7, '{"rule": {"summary": "Les chrétiens forment quatre grandes familles : orthodoxes orientaux (dont nous), orthodoxes byzantins, catholiques et protestants.", "explanation": "Trois questions suffisent pour situer une Église. Reçoit-elle le concile de Chalcédoine (451) ? Reconnaît-elle le pape ? La Bible seule suffit-elle ? Les Églises orthodoxes orientales répondent non, non, et « Bible et Tradition ». Les orthodoxes byzantins reçoivent Chalcédoine mais pas le pape. Les catholiques reçoivent les deux. Les protestants naissent de la Réforme et s''appuient sur la Bible seule.", "pattern": "Chalcédoine ? Pape ? Bible seule ? → copte : non, non, non.", "examples": [{"text": "Un copte n''est pas un catholique.", "translation": "Les Coptes sont orthodoxes orientaux et ne reconnaissent pas le pape de Rome."}], "commonErrors": [{"wrong": "Les Coptes sont des orthodoxes grecs.", "right": "Les Coptes sont des orthodoxes orientaux.", "why": "Les orthodoxes grecs reçoivent Chalcédoine, pas les Coptes."}, {"wrong": "L''Église catholique copte est la même Église que la nôtre.", "right": "C''est une Église distincte, en communion avec le pape.", "why": "Elle garde la liturgie copte mais reconnaît le pape."}, {"wrong": "Tous les protestants forment une seule Église.", "right": "Le protestantisme regroupe de nombreuses Églises.", "why": "Il n''a pas de chef unique."}], "tip": "Retiens les trois questions : Chalcédoine, pape, Bible seule."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g702.chalcedoine_deux_formules', 'eg', 'grammar', 'knowledge', 'Chalcédoine : un même Christ, deux formules', 2, array['eg.g701.quatre_familles']::text[], 7, '{"rule": {"summary": "Les orthodoxes byzantins reçoivent Chalcédoine et disent « en deux natures » ; nous gardons la formule de saint Cyrille : « une seule nature du Verbe incarné ».", "explanation": "Les deux familles confessent le même Christ, vrai Dieu et vrai homme, né de la Vierge Marie. Elles sont d''accord contre Nestorius, qui divise le Christ, et contre Eutychès, qui mélange la divinité et l''humanité. La rupture vient de Chalcédoine (451) : Alexandrie jugeait la formule « en deux natures » trop proche de Nestorius. Depuis 1989-1990, les dialogues constatent que la foi est la même et que le désaccord est en grande partie verbal.", "pattern": "Chalcédoine : « en deux natures » ; Cyrille : « une seule nature du Verbe incarné ».", "examples": [{"text": "Nous sommes miaphysites, pas monophysites.", "translation": "Une nature unie, sans mélange : Eutychès, lui, absorbait l''humanité du Christ."}], "commonErrors": [{"wrong": "Les Coptes sont monophysites comme Eutychès.", "right": "Les Coptes sont miaphysites, comme saint Cyrille.", "why": "Eutychès niait la pleine humanité du Christ ; l''Église copte le condamne aussi."}, {"wrong": "Chalcédoine a condamné Dioscore pour hérésie.", "right": "Dioscore a été déposé pour des raisons de procédure et de discipline.", "why": "Il a refusé de comparaître, mais n''a pas été condamné pour avoir enseigné l''erreur."}, {"wrong": "Les orthodoxes grecs adorent des saints à la place de Dieu.", "right": "Ils vénèrent les saints comme nous.", "why": "Les deux familles ont les mêmes sacrements et la même vénération."}], "tip": "Même Christ, deux formules : « en deux natures » ou « une seule nature du Verbe incarné »."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g703.pape_primaute', 'eg', 'grammar', 'knowledge', 'Le pape : primauté et infaillibilité', 2, array['eg.g702.chalcedoine_deux_formules']::text[], 7, '{"rule": {"summary": "Les catholiques reconnaissent la primauté et l''infaillibilité du pape ; l''Église copte décide en concile et voit dans le Christ le chef de l''Église.", "explanation": "Pour les catholiques, le pape, successeur de Pierre, est le chef visible de l''Église ; Vatican I (1870) a défini son infaillibilité quand il enseigne ex cathedra. Pour nous, les évêques sont tous successeurs des apôtres et les grandes questions se règlent en concile, comme à Jérusalem. Le mot « pape » (père) était porté dès le IIIe siècle par l''évêque d''Alexandrie.", "pattern": "Pape chef + infaillible (Vatican I, 1870) ≠ évêques en concile, Christ seul chef.", "examples": [{"text": "Nous aussi, nous avons un pape : celui d''Alexandrie.", "translation": "Pape veut dire « père » et n''est pas réservé à Rome."}], "commonErrors": [{"wrong": "L''infaillibilité veut dire que le pape ne peut pas pécher.", "right": "Elle concerne seulement l''enseignement solennel sur la foi et la morale.", "why": "Un pape peut pécher comme tout homme."}, {"wrong": "Seuls les catholiques ont un pape.", "right": "L''évêque d''Alexandrie porte aussi ce titre.", "why": "Il le porte depuis le IIIe siècle."}], "tip": "Catholiques : un chef visible. Coptes : les évêques ensemble, en concile."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g704.filioque_1054', 'eg', 'grammar', 'knowledge', 'Le Filioque et le schisme de 1054', 2, array['eg.g703.pape_primaute']::text[], 7, '{"rule": {"summary": "Les catholiques lisent le Credo avec « et du Fils » (Filioque) ; l''Église copte garde le Credo de 381 tel quel. Le schisme de 1054 sépare Rome et Constantinople.", "explanation": "Le Credo de Nicée-Constantinople (381) dit que l''Esprit procède du Père (Jean 15, 26). En Occident, on a ajouté « et du Fils », à Tolède en 589, et Rome l''a accepté en 1014. Nous ne le suivons pas : par la méthode (on ne modifie pas le Credo sans concile) et pour la foi (le Père est la seule source). Le 16 juillet 1054, Rome et Constantinople se séparent ; les excommunications sont levées en 1965. En 1973 et en 2017, Rome et l''Église copte ont fait des pas l''une vers l''autre.", "pattern": "Credo 381 : « du Père » ≠ Credo + Filioque : « du Père et du Fils » ; 1054 : Rome ≠ Constantinople.", "examples": [{"text": "Nous récitons le Credo de 381 sans y rien ajouter.", "translation": "Le Père est la seule source dans la Trinité."}], "commonErrors": [{"wrong": "Les Coptes ont ajouté « et du Fils » au Credo.", "right": "L''Église copte dit seulement que l''Esprit procède du Père.", "why": "Le Filioque est un ajout de l''Occident."}, {"wrong": "Le schisme de 1054 sépare Rome des Coptes.", "right": "Il sépare Rome et Constantinople.", "why": "La séparation avec les Coptes date de 451."}], "tip": "Filioque = « et du Fils » ; 1054 = Rome et Constantinople."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g705.marie_purgatoire', 'eg', 'grammar', 'knowledge', 'Marie, le purgatoire et la prière pour les défunts', 2, array['eg.g704.filioque_1054']::text[], 7, '{"rule": {"summary": "Catholiques et Coptes vénèrent Marie, Mère de Dieu ; l''Église copte n''enseigne ni l''Immaculée Conception (1854) ni le purgatoire (1274), mais prie pour les défunts.", "explanation": "Marie est Mère de Dieu depuis Éphèse (431), chez les catholiques comme chez nous. En 1854, Pie IX définit qu''elle a été conçue sans péché originel : l''Église copte ne suit pas cette doctrine et célèbre Marie toute pure sans dogme défini. Le purgatoire, précisé en 1274, est une purification après la mort : nous ne l''enseignons pas, mais nous prions pour les défunts aux 3e, 7e et 40e jours et laissons le jugement à Dieu.", "pattern": "Marie Mère de Dieu (431) commune ; Immaculée Conception (1854) et purgatoire (1274) : catholiques seulement.", "examples": [{"text": "Nous prions pour nos défunts au 40e jour.", "translation": "Nous les confions à Dieu, qui seul juge."}], "commonErrors": [{"wrong": "L''Immaculée Conception, c''est la naissance virginale de Jésus.", "right": "C''est la conception de Marie sans péché originel.", "why": "La naissance virginale concerne Jésus, né de Marie sans père."}, {"wrong": "Les Coptes ne prient pas pour les défunts.", "right": "Les Coptes prient pour les défunts.", "why": "Ils les confient à la miséricorde de Dieu."}], "tip": "Retiens : 1854 pour Marie, 1274 pour le purgatoire, et nous prions pour nos défunts."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g706.pain_celibat', 'eg', 'grammar', 'knowledge', 'Le pain de la messe et les prêtres mariés', 2, array['eg.g705.marie_purgatoire']::text[], 7, '{"rule": {"summary": "Les catholiques latins consacrent du pain azyme et ont en général des prêtres célibataires ; les Coptes utilisent du pain levé et ordonnent des hommes mariés.", "explanation": "Catholiques et Coptes croient que le pain et le vin deviennent le Corps et le Sang du Christ. L''Église latine consacre du pain sans levain (azyme) ; l''Église copte, comme les byzantins, du pain levé, qui évoque la Résurrection. Dans l''Église latine, les prêtres sont en général célibataires ; chez nous, un homme marié avant l''ordination peut devenir prêtre, mais les évêques sont choisis parmi les moines. Les Églises catholiques orientales ordonnent aussi des hommes mariés. Ces points ne touchent ni la Trinité ni le Christ.", "pattern": "Azyme / célibat (Église latine) ≠ pain levé / prêtre marié avant l''ordination (copte).", "examples": [{"text": "Notre prêtre est marié ; notre évêque est moine.", "translation": "Le prêtre s''est marié avant son ordination."}], "commonErrors": [{"wrong": "Tous les prêtres catholiques sont célibataires.", "right": "Dans l''Église latine en général ; les Églises catholiques orientales ordonnent aussi des hommes mariés.", "why": "La règle varie selon le rite."}, {"wrong": "Les Coptes ne croient pas à la présence réelle.", "right": "Les Coptes croient que l''eucharistie est le vrai Corps et le vrai Sang du Christ.", "why": "Catholiques et Coptes partagent cette foi."}], "tip": "Retiens : pain levé et prêtre marié avant l''ordination."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g707.reforme_ecriture', 'eg', 'grammar', 'knowledge', 'La Réforme et l''Écriture seule', 3, array['eg.g706.pain_celibat']::text[], 7, '{"rule": {"summary": "Les protestants naissent de la Réforme de 1517 et défendent l''Écriture seule ; l''Église copte garde l''Écriture et la Sainte Tradition, avec les livres de la Septante.", "explanation": "En 1517, Luther dénonce la vente des indulgences et lance un mouvement de retour à la Bible : sola scriptura. Calvin à Genève et les anglicans en Angleterre prolongent la Réforme. L''Église copte respecte l''amour des protestants pour la Bible, mais rappelle que l''Écriture est née dans l''Église, qui en a reconnu les livres, et qu''elle s''accompagne de la Sainte Tradition. Elle garde aussi les livres deutérocanoniques de la Septante.", "pattern": "Réforme 1517 : Écriture seule. Copte : Écriture + Tradition ; 39 livres ≠ livres de la Septante.", "examples": [{"text": "Luther traduit la Bible en allemand.", "translation": "Il veut que chacun puisse la lire."}], "commonErrors": [{"wrong": "Les protestants ne croient pas en Jésus.", "right": "Les protestants confessent le Christ, vrai Dieu et vrai homme.", "why": "Ils partagent avec nous la foi en la Trinité."}, {"wrong": "Luther est le fondateur de l''Église anglicane.", "right": "Luther a lancé la Réforme allemande ; les anglicans viennent de 1534.", "why": "Henri VIII rompt avec Rome."}], "tip": "1517, Écriture seule ; nous : Écriture et Tradition."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g708.foi_oeuvres', 'eg', 'grammar', 'knowledge', 'La foi seule ou la foi et les œuvres', 3, array['eg.g707.reforme_ecriture']::text[], 7, '{"rule": {"summary": "Les protestants disent que le salut vient par la foi seule ; l''Église copte enseigne que la grâce précède tout et que la foi et les œuvres vont ensemble.", "explanation": "Luther lit Romains 3, 28 et refuse qu''on puisse acheter le salut : sola fide. L''Église copte répond que la grâce de Dieu précède tout, et cite Jacques 2, 24 : les œuvres sont le fruit de la grâce, non un achat. Le protestantisme réunit luthériens, réformés, anglicans, baptistes, pentecôtistes… sans chef unique. En Égypte, l''Église évangélique est née de la mission américaine de 1854.", "pattern": "Sola fide (Romains 3, 28) ≠ foi et œuvres (Jacques 2, 24) ; grâce d''abord.", "examples": [{"text": "Les œuvres sont le fruit de la grâce.", "translation": "On ne les fait pas pour acheter le salut."}], "commonErrors": [{"wrong": "Les Coptes pensent qu''on se sauve par ses œuvres seules.", "right": "Les Coptes croient que la grâce de Dieu précède tout.", "why": "Les œuvres répondent à la grâce, elles ne l''achètent pas."}, {"wrong": "Tous les protestants baptisent les bébés.", "right": "Les baptistes ne baptisent que les adultes qui croient.", "why": "Les protestants ne sont pas tous d''accord entre eux."}], "tip": "Grâce d''abord ; puis la foi et les œuvres ensemble."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g709.sacrements_saints_icones', 'eg', 'grammar', 'knowledge', 'Sacrements, saints, icônes et succession apostolique', 3, array['eg.g708.foi_oeuvres']::text[], 7, '{"rule": {"summary": "Nous avons sept sacrements, demandons la prière des saints, vénérons les icônes et gardons la succession apostolique ; la plupart des protestants ont deux sacrements et n''ont pas d''icônes.", "explanation": "Un sacrement est un signe visible par lequel Dieu donne sa grâce ; l''Église copte en compte sept, les protestants gardent le baptême et la Cène. Nous demandons aux saints de prier pour nous, car ils sont vivants en Christ ; beaucoup de protestants citent 1 Timothée 2, 5 : un seul médiateur. Nous vénérons les icônes parce que Dieu s''est rendu visible en Jésus. Enfin nos évêques sont ordonnés en chaîne depuis les apôtres, tandis que les pasteurs protestants sont appelés par la communauté.", "pattern": "7 sacrements, saints, icônes, évêques en chaîne ≠ 2 sacrements, Dieu seul, peu d''images, pasteurs.", "examples": [{"text": "Nous vénérons les icônes et nous adorons Dieu seul.", "translation": "L''honneur rendu à l''image passe à celui qu''elle représente."}], "commonErrors": [{"wrong": "Les Coptes adorent les saints et les icônes.", "right": "Les Coptes vénèrent les saints et les icônes, et n''adorent que Dieu.", "why": "L''honneur passe à celui qu''on représente."}, {"wrong": "Les protestants n''ont aucun sacrement.", "right": "La plupart en gardent deux : le baptême et la Cène.", "why": "Ils les prennent très au sérieux."}, {"wrong": "Les évêques coptes sont élus sans ordination.", "right": "Ils reçoivent l''imposition des mains d''autres évêques.", "why": "C''est la succession apostolique."}], "tip": "Compte : 7 contre 2, saints et icônes, évêques en chaîne."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g710.mormons', 'eg', 'grammar', 'knowledge', 'Joseph Smith et les mormons', 3, array['eg.g709.sacrements_saints_icones']::text[], 7, '{"rule": {"summary": "Les mormons (1830) ajoutent le Livre de Mormon à la Bible et voient dans le Père, le Fils et l''Esprit trois êtres distincts ; l''Église copte confesse un seul Dieu en trois personnes.", "explanation": "Au XIXe siècle américain naissent plusieurs mouvements qui se disent chrétiens. Les mormons suivent Joseph Smith, le Livre de Mormon et une doctrine où le Père, le Fils et l''Esprit sont trois êtres distincts. Pour l''Église copte, la foi a été « transmise aux saints une fois pour toutes » (Jude 3) : on n''y ajoute pas de nouveaux livres, et la Trinité définie à Nicée est un seul Dieu en trois personnes de même nature. Nous respectons les personnes et leur vie morale, tout en disant ce qui diffère.", "pattern": "Mormons : Joseph Smith, 1830, Livre de Mormon, trois êtres ≠ Bible complète, Trinité.", "examples": [{"text": "Les mormons lisent la Bible et le Livre de Mormon.", "translation": "Ils ajoutent un livre à la Bible."}], "commonErrors": [{"wrong": "Les mormons utilisent seulement la Bible.", "right": "Les mormons ajoutent le Livre de Mormon et d''autres textes.", "why": "C''est une différence centrale."}, {"wrong": "Les mormons ne croient pas en Jésus.", "right": "Les mormons croient en Jésus-Christ.", "why": "La différence porte sur qui est Dieu et sur l''autorité de leurs livres."}], "tip": "Mormons : 1830, Livre de Mormon. Nous : Bible complète, un seul Dieu en trois personnes."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g711.adventistes', 'eg', 'grammar', 'knowledge', 'Les adventistes : Miller, Ellen White et le samedi', 3, array['eg.g710.mormons']::text[], 7, '{"rule": {"summary": "Les adventistes (1863) naissent de la prédiction ratée de Miller en 1844 et de l''œuvre d''Ellen White ; ils gardent la Trinité mais observent le samedi et croient que les morts dorment.", "explanation": "William Miller annonce le retour du Christ pour le 22 octobre 1844. Rien n''arrive : c''est la Grande Déception. Un petit groupe continue autour d''Ellen White, et l''Église adventiste du septième jour est organisée en 1863. Les adventistes croient à la Trinité et à la divinité du Christ, observent le sabbat le samedi et pensent que les morts dorment jusqu''à la résurrection. Nous célébrons le dimanche, jour de la Résurrection, et croyons que les saints vivent déjà avec le Christ.", "pattern": "Miller 1844 (Grande Déception) → Ellen White → 1863 ; samedi, Trinité, morts qui dorment.", "examples": [{"text": "Anna croit à la Trinité, comme nous.", "translation": "Il ne faut pas la confondre avec les témoins de Jéhovah."}], "commonErrors": [{"wrong": "Les adventistes ne croient pas à la Trinité.", "right": "Les adventistes croient à la Trinité.", "why": "Cette confusion est fréquente avec les témoins de Jéhovah."}, {"wrong": "Miller a annoncé le retour du Christ en 1914.", "right": "Miller a annoncé 1843, puis le 22 octobre 1844.", "why": "1914 est une date des témoins de Jéhovah."}], "tip": "Adventistes : 1844, samedi, Trinité."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g712.temoins', 'eg', 'grammar', 'knowledge', 'Les témoins de Jéhovah : ce qu''ils croient, ce que nous répondons', 3, array['eg.g711.adventistes']::text[], 7, '{"rule": {"summary": "Les témoins de Jéhovah (Russell, années 1870) disent que Jésus est créé et que l''Esprit est une force ; l''Église copte répond par Jean 1, 1 et Actes 5, 3-4. Ils refusent la transfusion mais acceptent les autres soins.", "explanation": "Charles Taze Russell réunit à Pittsburgh un groupe d''étude de la Bible dans les années 1870 ; le nom « témoins de Jéhovah » est adopté en 1931. Pour eux, Jésus est le premier être créé, le Saint-Esprit une force active, et 144 000 fidèles vivent au ciel. Ils refusent la transfusion sanguine (Actes 15, 20) mais acceptent les autres soins médicaux. Nous répondons par Jean 1, 1, Jean 20, 28 et Actes 5, 3-4, avec douceur et respect.", "pattern": "Jésus créé, Esprit = force ≠ Jean 1, 1 et Actes 5, 3-4 : le Fils et l''Esprit sont Dieu.", "examples": [{"text": "Les témoins de Jéhovah acceptent les médecins.", "translation": "Ils refusent la transfusion sanguine, pas tous les soins."}], "commonErrors": [{"wrong": "Les témoins de Jéhovah refusent tous les soins médicaux.", "right": "Ils refusent surtout les transfusions de sang.", "why": "Ils acceptent les médecins et les autres soins."}, {"wrong": "Les témoins de Jéhovah croient à la Trinité.", "right": "Ils rejettent la Trinité.", "why": "Pour eux, Jésus est créé et l''Esprit est une force."}], "tip": "Jésus créé, Esprit = force, 144 000 ; nous : Jean 1, 1 et Actes 5, 3-4."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g713.science_chretienne', 'eg', 'grammar', 'knowledge', 'La Science chrétienne et ce que les groupes récents ont en commun', 3, array['eg.g712.temoins']::text[], 7, '{"rule": {"summary": "La Science chrétienne (Mary Baker Eddy, 1875-1879) voit la maladie comme une illusion ; les groupes récents ajoutent une autorité à la Bible et croient à une Église disparue ; l''Église répond avec douceur et respect.", "explanation": "Mary Baker Eddy publie Science et Santé en 1875 et fonde son Église à Boston en 1879. Pour elle, la matière, le péché, la maladie et la mort sont des illusions ; nous répondons que le Verbe s''est fait chair et que les malades ont besoin de médecin. Mormons, adventistes, Science chrétienne et témoins de Jéhovah naissent aux États-Unis au XIXe siècle et ajoutent chacun une autorité à la Bible. Plusieurs parlent d''une grande apostasie : nous répondons par Matthieu 16, 18 et 28, 20, avec douceur et respect (1 Pierre 3, 15).", "pattern": "Autorité en plus de la Bible + « grande apostasie » ≠ Bible complète + Église toujours fidèle.", "examples": [{"text": "La Science chrétienne n''a aucun rapport avec la scientologie.", "translation": "La scientologie est créée dans les années 1950."}], "commonErrors": [{"wrong": "La Science chrétienne est la scientologie.", "right": "Ce sont deux mouvements différents, sans lien.", "why": "La scientologie est fondée dans les années 1950 par L. Ron Hubbard."}, {"wrong": "Tous les groupes récents rejettent la Trinité.", "right": "Les adventistes croient à la Trinité.", "why": "Les mormons, les témoins de Jéhovah et la Science chrétienne la rejettent."}], "tip": "Une autorité en plus de la Bible ; nous : Matthieu 16, 18 et 28, 20."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g714.bilan', 'eg', 'grammar', 'knowledge', 'Bilan : expliquer calmement à un ami', 4, array['eg.g713.science_chretienne']::text[], 7, '{"rule": {"summary": "Pour expliquer calmement : commencer par ce qu''on a en commun, dire la différence avec les mots de l''ami, puis donner le pourquoi côté copte, avec douceur et respect.", "explanation": "Trois questions situent une Église : Chalcédoine ? le pape ? la Bible seule ? Quatre repères suffisent : 451, 1054, 1517, 1830. Un mot-clé par famille : pape pour les catholiques, Chalcédoine pour les byzantins, Écriture seule pour les protestants, un livre ajouté pour les groupes récents. Ce qui nous unit avec les quatre premières familles : la Trinité et le Christ, vrai Dieu et vrai homme. Toujours dans cet ordre : le commun, la différence, le pourquoi copte.", "pattern": "Commun → différence → pourquoi copte, avec douceur et respect.", "examples": [{"text": "Marc : « Pourquoi pas le même pape ? »", "translation": "Tu réponds d''abord ce que vous avez en commun, puis la différence, puis le pourquoi copte."}], "commonErrors": [{"wrong": "Les Coptes sont des orthodoxes grecs.", "right": "Les Coptes sont des orthodoxes orientaux.", "why": "Les orthodoxes grecs reçoivent Chalcédoine."}, {"wrong": "Tous les groupes récents rejettent la Trinité.", "right": "Les adventistes croient à la Trinité.", "why": "Les mormons, les témoins de Jéhovah et la Science chrétienne la rejettent."}], "tip": "Commun, différence, pourquoi copte."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g801.origine_du_credo', 'eg', 'grammar', 'knowledge', 'Le Credo : d''où il vient', 1, '{}'::text[], 8, '{"rule": {"summary": "Credo veut dire « je crois ». Le nôtre vient de deux conciles : Nicée (325) pose le Père et le Fils, Constantinople (381) développe l''Esprit Saint et ajoute la suite. Éphèse (431) interdit d''en composer un autre.", "explanation": "Les credos sont nés des confessions de foi des futurs baptisés, les catéchumènes. Le Credo de Nicée-Constantinople s''est écrit en deux temps. L''Église copte le prie en disant « nous croyons », précédé d''une introduction à Marie, Mère de la vraie lumière.", "pattern": "Credo = Nicée (325) + Constantinople (381) ; Éphèse (431) : on n''y touche plus.", "examples": [{"text": "Nous croyons en un seul Dieu.", "translation": "Le Credo copte est au pluriel : c''est la foi de tous."}], "commonErrors": [{"wrong": "Le Credo a été écrit en une fois à Nicée.", "right": "Il a été écrit en deux temps : Nicée (325) et Constantinople (381).", "why": "L''article sur l''Esprit Saint est développé en 381."}, {"wrong": "On dit « je crois » parce que la foi est personnelle.", "right": "On dit « nous croyons » : la foi est celle de toute l''Église.", "why": "Le texte des conciles et la prière copte sont au pluriel."}], "tip": "Credo = « je crois » ; 325 pour le Fils, 381 pour l''Esprit, 431 pour le verrou."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g802.un_seul_dieu_pere', 'eg', 'grammar', 'knowledge', 'Un seul Dieu, le Père, Pantocrator', 1, array['eg.g801.origine_du_credo']::text[], 8, '{"rule": {"summary": "Le Credo commence par le Père : un seul Dieu, source de la Trinité, Pantocrator, celui qui tient tout.", "explanation": "Un seul Dieu écarte les dieux multiples, Marcion et les gnostiques : c''est le même Dieu qui crée et qui sauve. Dieu est Père parce qu''il a un Fils de toute éternité, et il est la source de la Trinité. Pantocrator veut dire Tout-Puissant : sa puissance garde toute chose dans l''être.", "pattern": "Nous croyons en un seul Dieu, Dieu le Père, Pantocrator.", "examples": [{"text": "Nous croyons en un seul Dieu, Dieu le Père, Pantocrator,", "translation": "Un seul Dieu, le Père, le Tout-Puissant."}], "commonErrors": [{"wrong": "Il y a un Dieu de justice et un Dieu d''amour.", "right": "Le même Dieu unique crée et sauve.", "why": "C''était l''erreur de Marcion."}, {"wrong": "Dieu est Père seulement parce qu''il a créé le monde.", "right": "Il est Père parce qu''il a un Fils de toute éternité.", "why": "Un père sans fils n''est pas père."}], "tip": "Un seul Dieu, le Père, le Tout-Puissant : trois idées, une phrase."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g803.createur_ciel_terre', 'eg', 'grammar', 'knowledge', 'Créateur du ciel et de la terre, des choses visibles et invisibles', 1, array['eg.g802.un_seul_dieu_pere']::text[], 8, '{"rule": {"summary": "Dieu est créateur du ciel et de la terre, de tout ce qu''on voit et de tout ce qu''on ne voit pas. Il crée à partir de rien, et sa création est bonne.", "explanation": "Le monde n''est ni éternel, ni un morceau de Dieu, ni l''œuvre d''un dieu inférieur. La matière n''est pas mauvaise : Dieu a vu que cela était très bon. Les choses invisibles sont les anges, créatures spirituelles qui adorent Dieu.", "pattern": "Créateur du ciel et de la terre, de toutes les choses visibles et invisibles.", "examples": [{"text": "créateur du ciel et de la terre, de toutes les choses visibles et invisibles.", "translation": "Tout ce qui existe vient de Dieu."}], "commonErrors": [{"wrong": "La matière est mauvaise.", "right": "Le monde que Dieu a créé est bon.", "why": "Gnostiques et manichéens se trompaient."}, {"wrong": "Les anges sont des dieux.", "right": "Les anges sont des créatures invisibles de Dieu.", "why": "On adore Dieu seul."}], "tip": "Un seul Dieu, tout part de lui, tout est bon, tout est à lui."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g804.seigneur_fils_unique', 'eg', 'grammar', 'knowledge', 'Un seul Seigneur, le Fils unique, engendré avant tous les siècles', 2, array['eg.g803.createur_ciel_terre']::text[], 8, '{"rule": {"summary": "Le Fils est Seigneur (titre de Dieu), Fils unique (Fils par nature) et engendré avant tous les siècles : il est éternel, contrairement à ce que disait Arius.", "explanation": "Arius enseignait, vers 318 : « il fut un temps où le Fils n''était pas ». Le Credo répond que le Fils est engendré du Père avant tous les siècles, hors du temps. Kyrios, Seigneur, est le nom que la Bible grecque donne à Dieu. Fils unique : Fils par nature, là où nous le sommes par grâce.", "pattern": "Et en un seul Seigneur Jésus-Christ, le Fils unique de Dieu, engendré du Père avant tous les siècles.", "examples": [{"text": "Et en un seul Seigneur Jésus-Christ, le Fils unique de Dieu,", "translation": "Seigneur, donc Dieu ; Fils unique, donc Fils par nature."}], "commonErrors": [{"wrong": "Il fut un temps où le Fils n''était pas.", "right": "Le Fils est engendré avant tous les siècles.", "why": "Il est éternel, hors du temps."}, {"wrong": "Nous sommes fils de Dieu comme le Christ.", "right": "Il l''est par nature, nous le sommes par grâce.", "why": "Lui seul est Fils unique."}], "tip": "Seigneur = Dieu ; Fils unique = par nature ; avant tous les siècles = éternel."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g805.lumiere_de_lumiere', 'eg', 'grammar', 'knowledge', 'Lumière de Lumière, vrai Dieu de vrai Dieu, engendré non créé', 2, array['eg.g804.seigneur_fils_unique']::text[], 8, '{"rule": {"summary": "Lumière de Lumière, vrai Dieu de vrai Dieu, engendré non créé : trois expressions qui disent que le Fils est Dieu comme le Père et qu''il n''est pas une créature.", "explanation": "Une flamme allumée à une autre flamme ne la diminue pas : le Fils vient du Père sans rien lui enlever. Il n''est pas un Dieu moindre : il est vrai Dieu. Et il est engendré, non créé : un menuisier fait une table qui n''est pas un menuisier, mais un homme engendre un homme.", "pattern": "Lumière de Lumière, vrai Dieu de vrai Dieu, engendré non créé.", "examples": [{"text": "Lumière de Lumière, vrai Dieu de vrai Dieu, engendré non créé,", "translation": "Même lumière, même Dieu, même nature."}], "commonErrors": [{"wrong": "Le Fils est la première créature de Dieu.", "right": "Le Fils est engendré, non créé.", "why": "Engendré veut dire de même nature que le Père."}, {"wrong": "Le Fils est Dieu à moitié.", "right": "Il est vrai Dieu de vrai Dieu.", "why": "Il n''est pas un Dieu de second rang."}], "tip": "Une flamme allumée à une autre : même lumière, rien de perdu."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g806.consubstantiel', 'eg', 'grammar', 'knowledge', 'Consubstantiel au Père, par qui tout a été fait', 2, array['eg.g805.lumiere_de_lumiere']::text[], 8, '{"rule": {"summary": "Consubstantiel (homoousios) veut dire « de même substance que le Père ». Le mot est choisi à Nicée parce qu''Arius ne pouvait pas le tordre. Et « par qui tout a été fait » dit que le Fils est Créateur.", "explanation": "Arius acceptait toutes les formules de la Bible en les tordant. Le concile de Nicée choisit un mot grec, homoousios, de même substance. Les semi-ariens proposaient homoiousios, de substance semblable : un iota change tout. Le Fils est Créateur avec le Père, et seul Dieu peut sauver.", "pattern": "Consubstantiel au Père, par qui tout a été fait.", "examples": [{"text": "consubstantiel au Père, par qui tout a été fait.", "translation": "Même substance que le Père, et Créateur avec lui."}], "commonErrors": [{"wrong": "Consubstantiel veut dire « de substance semblable ».", "right": "Il veut dire de même substance (homoousios).", "why": "Semblable, c''est homoiousios : un iota change tout."}, {"wrong": "Le Fils est une créature qui nous sauve.", "right": "Seul Dieu peut sauver : le Fils est Dieu.", "why": "Une créature ne peut pas sauver une créature."}], "tip": "Homoousios = même ; homoiousios = semblable ; un iota, tout le sens."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g807.pour_notre_salut', 'eg', 'grammar', 'knowledge', 'Pour nous les hommes et pour notre salut, il descendit du ciel', 2, array['eg.g806.consubstantiel']::text[], 8, '{"rule": {"summary": "Le Fils éternel descend du ciel pour nous les hommes et pour notre salut : il prend notre condition sans cesser d''être Dieu, pour que l''homme participe à la vie divine.", "explanation": "Le sujet de « descendit » est le Fils de l''article précédent. « Descendre » dit l''abaissement : il prend ce qu''il n''était pas sans perdre ce qu''il était (Philippiens 2, 7). Saint Athanase en tire la divinisation : Dieu se fait homme pour que l''homme partage sa vie, par grâce.", "pattern": "Qui, pour nous les hommes et pour notre salut, descendit du ciel.", "examples": [{"text": "Qui, pour nous les hommes et pour notre salut, descendit du ciel,", "translation": "Le Fils éternel vient pour nous sauver."}], "commonErrors": [{"wrong": "Le Fils quitte le ciel comme on quitte une maison.", "right": "Il s''abaisse jusqu''à nous sans cesser d''être Dieu.", "why": "Le ciel n''est pas un lieu qu''il laisserait vide."}, {"wrong": "L''homme devient Dieu par nature.", "right": "L''homme reçoit la vie de Dieu par grâce.", "why": "Le fer reste du fer, même rouge de feu."}], "tip": "Il descend pour nous : un roi assis par terre avec les enfants reste roi."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g808.incarna_vierge_marie', 'eg', 'grammar', 'knowledge', 'S''incarna de l''Esprit Saint et de la Vierge Marie, et se fit homme', 2, array['eg.g807.pour_notre_salut']::text[], 8, '{"rule": {"summary": "Le Fils s''incarne de l''Esprit Saint et de la Vierge Marie, et se fait homme : un vrai corps et une âme humaine. Il reste l''unique sujet de toutes les actions du Credo.", "explanation": "La conception virginale est annoncée à Marie (Luc 1, 35). Marie est Théotokos : celui qu''elle enfante est Dieu le Verbe. « Se fit homme » écarte le docétisme (corps apparent) et Apollinaire (pas d''âme humaine, condamné en 381). Le Fils est l''unique sujet des verbes du Credo.", "pattern": "s''incarna de l''Esprit Saint et de la Vierge Marie, et se fit homme.", "examples": [{"text": "s''incarna de l''Esprit Saint et de la Vierge Marie, et se fit homme.", "translation": "Le Fils prend chair et devient vraiment homme."}], "commonErrors": [{"wrong": "Le Christ n''a eu qu''un corps apparent.", "right": "Il s''est fait vraiment homme.", "why": "C''est le docétisme, rejeté par le Credo."}, {"wrong": "Le Verbe a pris un corps sans âme humaine.", "right": "Il a pris un homme entier.", "why": "C''est l''erreur d''Apollinaire, condamné en 381."}], "tip": "Un seul « Il » dans tout le Credo : celui qui est Dieu est celui qui naît et qui souffre."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g809.crucifie_ressuscite', 'eg', 'grammar', 'knowledge', 'Crucifié sous Ponce Pilate, enseveli, ressuscité le troisième jour', 2, array['eg.g808.incarna_vierge_marie']::text[], 8, '{"rule": {"summary": "Le Fils est crucifié pour nous sous Ponce Pilate, souffre vraiment, est enseveli, et ressuscite le troisième jour selon les Écritures : la résurrection est le fondement de la foi.", "explanation": "Le nom de Pilate ancre la croix dans l''histoire. « Pour nous » : la croix n''est pas un accident. Le Fils est l''unique sujet : c''est Dieu le Verbe qui souffre dans la chair. Le troisième jour, il ressuscite, comme les Écritures l''annonçaient. Sans la résurrection, dit Paul, la foi serait vaine (1 Corinthiens 15, 14).", "pattern": "Il fut crucifié pour nous sous Ponce Pilate, souffrit, fut enseveli, et ressuscita le troisième jour selon les Écritures.", "examples": [{"text": "Il fut crucifié pour nous sous Ponce Pilate, souffrit, fut enseveli,", "translation": "Une vraie mort, à une date réelle."}], "commonErrors": [{"wrong": "Le Christ n''a souffert qu''en apparence.", "right": "Il a souffert, il est mort et il a été enseveli.", "why": "C''est le docétisme, rejeté par le Credo."}, {"wrong": "La croix est un accident.", "right": "Il est crucifié pour nous.", "why": "C''est un don pour le salut."}], "tip": "Pilate = c''est réel ; pour nous = c''est un don ; troisième jour = c''est vivant."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g810.gloire_et_regne', 'eg', 'grammar', 'knowledge', 'Il monta aux cieux, il reviendra, son règne n''aura pas de fin', 2, array['eg.g809.crucifie_ressuscite']::text[], 8, '{"rule": {"summary": "Le Christ monte aux cieux, s''assoit à la droite du Père (l''honneur et la puissance) et reviendra dans la gloire juger les vivants et les morts. Son règne n''aura pas de fin : phrase ajoutée en 381.", "explanation": "L''Ascension a lieu quarante jours après la Résurrection. La droite du Père n''est pas un endroit : c''est l''honneur et la puissance. La première venue fut dans l''humilité, la seconde sera dans la gloire. La dernière phrase vient de 381 : le texte de Nicée s''arrêtait à « et en l''Esprit Saint ».", "pattern": "Il monta aux cieux, s''assit à la droite de son Père, et il reviendra dans la gloire pour juger les vivants et les morts. Son règne n''aura pas de fin.", "examples": [{"text": "Il monta aux cieux, s''assit à la droite de son Père,", "translation": "Il reçoit l''honneur et la puissance."}], "commonErrors": [{"wrong": "La droite du Père est un endroit.", "right": "La droite du Père est l''honneur et la puissance.", "why": "Dieu n''a pas de côté droit : c''est une image."}, {"wrong": "« Son règne n''aura pas de fin » date de Nicée.", "right": "Cette phrase date de 381.", "why": "À Nicée, le texte s''arrêtait à « et en l''Esprit Saint »."}], "tip": "Monta, s''assit, reviendra : puis le règne sans fin, ajouté en 381."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g811.saint_esprit', 'eg', 'grammar', 'knowledge', 'Nous croyons au Saint-Esprit, Seigneur qui donne la vie', 3, array['eg.g810.gloire_et_regne']::text[], 8, '{"rule": {"summary": "Constantinople (381) répond à Macédonius : l''Esprit Saint est Seigneur, il donne la vie, il procède du Père, il est adoré avec le Père et le Fils, et il a parlé par les prophètes.", "explanation": "À Nicée, l''Esprit n''était que nommé. Macédonius, évêque de Constantinople, dit qu''il est une créature ; ses disciples sont les pneumatomaques. Le Credo de 381 répond en quatre « qui ». L''Occident a ajouté « et du Fils » (Filioque) ; l''Église copte garde le texte de 381.", "pattern": "Nous croyons au Saint-Esprit, Seigneur qui donne la vie, qui procède du Père, qui avec le Père et le Fils est adoré et glorifié, qui a parlé par les prophètes.", "examples": [{"text": "Nous croyons au Saint-Esprit, Seigneur qui donne la vie,", "translation": "L''Esprit est Seigneur : il est Dieu."}], "commonErrors": [{"wrong": "L''Esprit Saint est une créature.", "right": "L''Esprit est Seigneur, adoré avec le Père et le Fils.", "why": "C''est l''erreur de Macédonius, condamnée en 381."}, {"wrong": "Le Credo de 381 dit « et du Fils ».", "right": "Le Credo de 381 dit : qui procède du Père.", "why": "« Et du Fils » est un ajout latin."}], "tip": "Quatre « qui » : il donne la vie, il procède, il est adoré, il a parlé."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g812.quatre_marques', 'eg', 'grammar', 'knowledge', 'Nous croyons en une seule Église, sainte, catholique et apostolique', 2, array['eg.g811.saint_esprit']::text[], 8, '{"rule": {"summary": "Le Credo confesse une Église une (un seul Corps), sainte (sanctifiée par le Christ et l''Esprit), catholique (universelle) et apostolique (fondée sur les apôtres).", "explanation": "Une : un seul Seigneur, une seule foi, un seul baptême. Sainte : le Christ et l''Esprit la sanctifient, pas ses membres (réponse à Novatien). Catholique : « selon le tout », universelle, et non romaine. Apostolique : fondée sur les apôtres et gardée par la succession des évêques ; à Alexandrie, saint Marc.", "pattern": "Nous croyons en une seule Église, sainte, catholique et apostolique.", "examples": [{"text": "Nous croyons en une seule Église, sainte, catholique et apostolique.", "translation": "Quatre marques pour reconnaître l''Église."}], "commonErrors": [{"wrong": "Catholique veut dire romaine.", "right": "Catholique veut dire universelle.", "why": "Du grec katholikos, « selon le tout »."}, {"wrong": "L''Église est sainte parce que ses membres sont parfaits.", "right": "Elle est sainte parce que le Christ et l''Esprit la sanctifient.", "why": "Novatien oubliait cela."}], "tip": "Une, sainte, catholique, apostolique : unité, source, étendue, origine."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g813.bapteme_resurrection_amen', 'eg', 'grammar', 'knowledge', 'Un seul baptême, la résurrection des morts, la vie du siècle à venir. Amen', 2, array['eg.g812.quatre_marques']::text[], 8, '{"rule": {"summary": "Le Credo se termine par un seul baptême pour le pardon des péchés, l''attente de la résurrection des morts et de la vie du siècle à venir, puis Amen.", "explanation": "Le baptême ne se répète pas ; il pardonne et donne une vie nouvelle. La résurrection concerne l''homme tout entier, corps compris, contre le mépris gnostique de la chair. Le siècle à venir est le monde nouveau. Amen, mot hébreu, signifie « c''est vrai » : tu signes ton Credo.", "pattern": "Nous confessons un seul baptême pour la rémission des péchés. Nous attendons la résurrection des morts et la vie du siècle à venir. Amen.", "examples": [{"text": "Nous attendons la résurrection des morts et la vie du siècle à venir. Amen.", "translation": "Le Credo se termine sur l''espérance."}], "commonErrors": [{"wrong": "On ressuscite seulement en esprit.", "right": "On ressuscite avec son corps.", "why": "Les gnostiques méprisaient la chair, pas l''Église."}, {"wrong": "Le baptême peut se répéter.", "right": "Il n''y a qu''un seul baptême.", "why": "On naît une seule fois."}], "tip": "Un baptême, une résurrection, une attente, un Amen : tu signes."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g814.bilan_du_credo', 'eg', 'grammar', 'knowledge', 'Le Credo en entier : bilan', 3, array['eg.g813.bapteme_resurrection_amen']::text[], 8, '{"rule": {"summary": "Le Credo se retient en trois blocs plus l''Église. Chaque phrase répond à une erreur. Trois conciles l''ont fait : Nicée (325), Constantinople (381), Éphèse (431) l''a verrouillé.", "explanation": "Le Père créateur répond aux gnostiques et à Marcion. Le Fils consubstantiel répond à Arius. Se fit homme répond aux docètes et à Apollinaire. L''Esprit vivificateur répond à Macédonius. L''Église copte lit « il s''incarna » avec saint Cyrille : une seule nature du Verbe incarné, sans mélange ni division.", "pattern": "Père, Fils, Esprit, Église : quatre blocs, quatre erreurs, trois conciles.", "examples": [{"text": "Père : Pantocrator ; Fils : Lumière de Lumière ; Esprit : vivificateur.", "translation": "Un mot-repère par bloc pour tout retrouver."}], "commonErrors": [{"wrong": "Le Credo a été écrit en une fois à Nicée.", "right": "325 : le Père et le Fils ; 381 : l''Esprit Saint et la suite.", "why": "Deux conciles, un seul texte."}, {"wrong": "Chaque phrase du Credo est de la poésie.", "right": "Chaque phrase répond à une erreur.", "why": "Le Credo ferme des portes."}], "tip": "Père, Fils, Esprit, Église : quatre blocs, quatre erreurs, trois conciles."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g901.signe_et_grace', 'eg', 'grammar', 'knowledge', 'Un sacrement : un signe visible, une grâce invisible', 1, '{}'::text[], 9, '{"rule": {"summary": "Un sacrement, ou mystère, est un signe visible par lequel Dieu donne une grâce invisible ; il est institué par le Christ et célébré par un prêtre. L''Église copte en compte sept.", "explanation": "Le Christ s''est fait homme, avec un corps : il continue d''agir par des réalités que l''on peut toucher, comme l''eau, l''huile, le pain ou l''imposition des mains. Chaque sacrement a un signe visible (la matière et le geste) et une grâce invisible (ce que Dieu donne). Aucun n''est une invention de l''Église : chacun repose sur le Christ ou sur la pratique des apôtres. Le prêtre le célèbre, mais c''est le Christ qui agit. Trois sacrements ne se répètent pas (baptême, confirmation, sacerdoce) ; les autres reviennent au fil de la vie.", "pattern": "Sacrement = signe visible + grâce invisible. Sept sacrements. Trois ne se répètent pas.", "examples": [{"text": "L''eau du baptême est le signe visible.", "translation": "La grâce invisible est la nouvelle naissance."}, {"text": "Le pain et le vin de la messe sont le signe visible.", "translation": "La grâce invisible est le Corps et le Sang du Christ."}], "commonErrors": [{"wrong": "Un sacrement est seulement un symbole pour se souvenir.", "right": "Un sacrement donne vraiment une grâce.", "why": "Le signe n''est pas décoratif : Dieu agit par lui."}, {"wrong": "Le prêtre fabrique la grâce.", "right": "C''est le Christ qui donne la grâce ; le prêtre est son serviteur.", "why": "Le prêtre célèbre au nom du Christ, il n''en est pas la source."}], "tip": "Visible + invisible : l''eau, l''huile, le pain, les mains que l''on voit, et la grâce que l''on ne voit pas."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g902.bapteme_naissance', 'eg', 'grammar', 'knowledge', 'Le baptême : naître d''eau et d''Esprit', 1, array['eg.g901.signe_et_grace']::text[], 9, '{"rule": {"summary": "Le baptême est le premier sacrement : par la triple immersion au nom de la Trinité, on naît d''eau et d''Esprit et l''on entre dans l''Église. Il ne se reçoit qu''une fois.", "explanation": "Le Christ a ordonné de baptiser (Mt 28, 19) et il a dit qu''il faut naître d''eau et d''Esprit (Jn 3, 5). Dans l''Église copte, on plonge trois fois : une fois pour chaque Personne de la Trinité, et en souvenir des trois jours du Christ au tombeau (Rm 6, 3-4). L''eau est à la fois un tombeau et une naissance. Le baptême pardonne le péché originel et les péchés personnels, ouvre la porte aux autres sacrements et ne se répète jamais.", "pattern": "Eau bénie + myron en croix + triple immersion + Trinité. Tombeau puis naissance.", "examples": [{"text": "Le prêtre plonge l''enfant trois fois dans l''eau.", "translation": "Une immersion pour le Père, une pour le Fils, une pour le Saint-Esprit."}, {"text": "Le mot baptizein veut dire plonger.", "translation": "On plonge vraiment le baptisé."}], "commonErrors": [{"wrong": "On se contente de verser un peu d''eau sur le front.", "right": "Dans l''Église copte, on plonge le baptisé trois fois dans l''eau.", "why": "Baptizein veut dire plonger : l''eau est un tombeau et une naissance."}, {"wrong": "Le baptême se refait si l''on a péché gravement.", "right": "Le baptême ne se répète jamais ; le pardon se reçoit par la confession.", "why": "On ne naît qu''une fois."}], "tip": "L''eau est un tombeau où le vieil homme meurt et un ventre où l''homme nouveau naît."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g903.ouest_est', 'eg', 'grammar', 'knowledge', 'Renoncer à l''ouest, confesser à l''est', 2, array['eg.g902.bapteme_naissance']::text[], 9, '{"rule": {"summary": "Avant d''être plongé, le baptisé se tourne vers l''ouest pour renoncer à Satan, puis vers l''est pour confesser le Christ et dire le Credo : il quitte le mal avant de rejoindre la lumière.", "explanation": "L''ouest est le côté où le soleil disparaît : image des ténèbres et de l''exil loin de Dieu. Le baptisé y renonce à Satan. L''est est le côté où le soleil se lève : image du Christ, lumière du monde. Il y confesse le Christ et le Credo est dit. Ce double geste est une conversion, un changement de direction.", "pattern": "Ouest : ténèbres, on renonce à Satan. Est : lumière, on confesse le Christ et le Credo.", "examples": [{"text": "Le baptisé se tourne vers l''ouest pour renoncer à Satan.", "translation": "L''ouest est le côté où le soleil disparaît : les ténèbres."}, {"text": "Puis il se tourne vers l''est pour confesser le Christ.", "translation": "L''est est le côté où le soleil se lève : la lumière."}], "commonErrors": [{"wrong": "On confesse le Christ avant de renoncer à Satan.", "right": "On renonce d''abord, puis on confesse.", "why": "Il faut quitter le mal avant de rejoindre le Christ."}], "tip": "Ouest : le soleil se couche, on dit non. Est : le soleil se lève, on dit oui."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g904.bebes_parrain', 'eg', 'grammar', 'knowledge', 'Le baptême des enfants et le parrain', 2, array['eg.g903.ouest_est']::text[], 9, '{"rule": {"summary": "L''Église baptise les bébés, avec la foi des parents et du parrain. Le baptême prend la place de la circoncision. Selon l''usage, le garçon est baptisé vers le 40e jour, la fille vers le 80e.", "explanation": "Des maisons entières sont baptisées dans les Actes (Ac 16, 33). Pour saint Paul, le baptême prend la place de la circoncision que l''on faisait aux nouveau-nés (Col 2, 11-12). Le parrain répond à la place de l''enfant, renonce à Satan et confesse le Christ pour lui, puis l''aide à grandir dans la foi. Selon l''usage, d''après Lv 12, on baptise le garçon vers le 40e jour et la fille vers le 80e ; si l''enfant est en danger, on ne l''attend pas.", "pattern": "Bébé : foi des parents et du parrain. Baptême = circoncision remplacée. Garçon : 40e jour. Fille : 80e jour.", "examples": [{"text": "Le parrain tient l''enfant et répond à sa place.", "translation": "Il croit pour lui jusqu''à ce qu''il puisse le faire seul."}, {"text": "Le garçon est baptisé le 40e jour, la fille le 80e.", "translation": "C''est l''usage, fondé sur Lévitique 12."}], "commonErrors": [{"wrong": "On ne peut baptiser qu''un adulte qui choisit lui-même.", "right": "L''Église baptise aussi les bébés, avec la foi des parents et du parrain.", "why": "Le baptême prend la place de la circoncision, que l''on faisait aux nouveau-nés."}, {"wrong": "Un enfant en danger doit attendre le 40e ou le 80e jour.", "right": "On le baptise sans attendre.", "why": "Ces jours sont un usage, pas une barrière."}], "tip": "Le parrain croit pour le bébé ; 40 pour le garçon, 80 pour la fille."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g905.myron', 'eg', 'grammar', 'knowledge', 'La confirmation : le saint myron', 2, array['eg.g904.bebes_parrain']::text[], 9, '{"rule": {"summary": "La confirmation, ou chrismation, donne au baptisé le sceau du Saint-Esprit par le saint myron, une huile parfumée préparée et consacrée par le pape avec les évêques. Elle suit aussitôt le baptême.", "explanation": "Dans les Actes, les apôtres imposent les mains aux baptisés pour qu''ils reçoivent l''Esprit (Ac 8, 14-17). Comme ils ne pouvaient pas aller vers chaque fidèle, l''Église a gardé ce don par l''huile consacrée, le saint myron. C''est de l''huile d''olive mêlée à plus de vingt parfums et épices, sur le modèle d''Exode 30. Seul le pape préside sa préparation, avec les évêques, au monastère Saint-Bishoy du Ouadi Natroun ; selon la tradition, les apôtres l''ont préparé avec les aromates du tombeau du Christ.", "pattern": "Myron = huile d''olive + parfums. Préparé par le pape et les évêques. Il remplace l''imposition des mains.", "examples": [{"text": "Pierre et Jean imposent les mains aux Samaritains baptisés (Ac 8, 14-17).", "translation": "Ils reçoivent l''Esprit : c''est l''origine de la confirmation."}, {"text": "Le pape prépare le myron avec les évêques.", "translation": "Il y ajoute un peu de l''ancien myron."}], "commonErrors": [{"wrong": "La confirmation est une cérémonie de l''adolescence, par l''évêque.", "right": "Chez les Coptes, le prêtre confirme aussitôt après le baptême, même pour un bébé.", "why": "Le baptême et le myron forment un seul parcours d''initiation."}, {"wrong": "Le myron est une huile ordinaire.", "right": "C''est une huile d''olive mêlée de nombreux parfums, consacrée par le pape.", "why": "Elle est préparée de manière solennelle, d''après Ex 30."}], "tip": "Baptême : l''eau. Confirmation : l''huile. Le premier lave, le second scelle."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g906.trente_six_onctions', 'eg', 'grammar', 'knowledge', 'Les 36 onctions, l''habit blanc, le zounnar', 2, array['eg.g905.myron']::text[], 9, '{"rule": {"summary": "Juste après le baptême, le prêtre trace 36 croix de myron sur le baptisé : il devient le temple du Saint-Esprit. Il reçoit un habit blanc et, selon l''usage, un zounnar dénoué le huitième jour.", "explanation": "Le prêtre oint la tête, les sens, la poitrine, le dos et les articulations : tout le corps est consacré, car le baptisé est le temple du Saint-Esprit (1 Co 6, 19). Le sceau ne s''efface pas, donc la confirmation ne se répète jamais. L''habit blanc dit la vie nouvelle (Col 3, 9-10). Le zounnar, ceinture ou ruban, dit l''appartenance au Christ ; il est dénoué le huitième jour.", "pattern": "36 croix de myron. Sceau unique. Habit blanc. Zounnar dénoué le 8e jour.", "examples": [{"text": "Le prêtre trace 36 signes de croix avec le saint myron.", "translation": "Tout le corps est consacré."}, {"text": "L''enfant reçoit un habit blanc.", "translation": "Il a revêtu l''homme nouveau."}], "commonErrors": [{"wrong": "On renouvelle la confirmation régulièrement.", "right": "Elle ne se reçoit qu''une fois.", "why": "Le sceau de l''Esprit ne s''efface pas."}, {"wrong": "Le zounnar est un bijou de famille.", "right": "C''est une ceinture ou un ruban, signe d''appartenance au Christ.", "why": "On le dénoue le huitième jour."}], "tip": "36 croix, un habit blanc, un ruban dénoué au huitième jour."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g907.derniere_cene', 'eg', 'grammar', 'knowledge', 'L''eucharistie : la dernière Cène', 2, array['eg.g906.trente_six_onctions']::text[], 9, '{"rule": {"summary": "L''eucharistie, « action de grâce », est le sacrement où le pain et le vin deviennent vraiment le Corps et le Sang du Christ. Elle a été instituée à la dernière Cène, le soir du Jeudi saint.", "explanation": "Le soir de la dernière Cène, Jésus dit : « Prenez, mangez, ceci est mon corps » (Mt 26, 26), et il ajoute : « Faites ceci en mémoire de moi » (Lc 22, 19). Il avait promis : « Moi, je suis le pain de vie » (Jn 6, 35) et « Qui mange ma chair et boit mon sang a la vie éternelle » (Jn 6, 54). Nous croyons à la présence réelle : ce n''est pas un simple souvenir. Les premiers chrétiens appelaient l''eucharistie la fraction du pain.", "pattern": "Jeudi saint (Mt 26, 26) → « ceci est » → présence réelle → eucharistie = action de grâce.", "examples": [{"text": "Jésus prend le pain et dit : « Ceci est mon corps ».", "translation": "Il ne dit pas : « Ceci représente »."}, {"text": "Jésus s''appelle le pain de vie.", "translation": "Jean 6 annonce ce que la Cène réalise."}], "commonErrors": [{"wrong": "L''eucharistie est seulement un souvenir de la dernière Cène.", "right": "Pour l''Église copte, c''est le vrai Corps et le vrai Sang du Christ.", "why": "Jésus a dit « ceci est », et non « ceci représente »."}], "tip": "Jeudi saint, « ceci est mon corps » : pas un souvenir, une présence."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g908.qorban_jeune', 'eg', 'grammar', 'knowledge', 'Le qorban, le jeûne et la communion', 2, array['eg.g907.derniere_cene']::text[], 9, '{"rule": {"summary": "Le pain de la messe, le qorban, est un pain levé marqué d''une croix. On communie à jeun, après s''être confessé et réconcilié ; seuls les orthodoxes baptisés et confirmés communient.", "explanation": "Le qorban, « offrande », est un pain levé : vivant, il évoque la Résurrection. Les catholiques latins utilisent un pain sans levain, l''azyme. Le jeûne eucharistique, d''au moins neuf heures pour un adulte, fait du Christ la première nourriture de la journée ; le prêtre adapte pour les enfants et les malades. Saint Paul demande que chacun s''examine (1 Co 11, 28) : on se confesse et on se réconcilie avant de communier. La communion donne la vie éternelle, le pardon et l''union au Christ et à l''Église.", "pattern": "Qorban = pain levé. Jeûne ≥ 9 h. Confession avant. Communion = union au Christ et unité de l''Église.", "examples": [{"text": "Le qorban est un pain levé marqué d''une croix.", "translation": "Le levain évoque la vie, la Résurrection."}, {"text": "On reste à jeun avant la communion.", "translation": "Le Christ est la première nourriture de la journée."}], "commonErrors": [{"wrong": "Le pain de la messe est sans levain, comme chez les latins.", "right": "Le qorban est un pain levé.", "why": "Le pain levé est le pain vivant ; il rappelle la Résurrection."}, {"wrong": "On peut communier sans se préparer.", "right": "On s''examine, on se confesse et on jeûne avant.", "why": "Saint Paul avertit contre la communion indigne (1 Co 11, 27-29)."}], "tip": "Pain levé, ventre vide, cœur réconcilié : on prépare la communion."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g909.confession', 'eg', 'grammar', 'knowledge', 'La confession : lier et délier', 2, array['eg.g908.qorban_jeune']::text[], 9, '{"rule": {"summary": "La confession, ou pénitence, pardonne les péchés commis après le baptême : on les dit à un prêtre, qui prie l''absolution. Elle repose sur Jn 20, 22-23.", "explanation": "Après le baptême, nous péchons encore. Le soir de la Résurrection, Jésus souffle sur les apôtres et leur donne le pouvoir de remettre ou de retenir les péchés (Jn 20, 22-23). Pour remettre ou retenir, il faut connaître : on dit donc ses péchés. Le prêtre est père, juge et enseignant. Dieu seul pardonne, mais par le ministère de réconciliation confié aux apôtres (2 Co 5, 18). Le prêtre pose la croix sur la tête du pénitent et prie l''absolution.", "pattern": "Jn 20, 22-23. Connaître pour remettre ou retenir. Le prêtre prie l''absolution. Dieu pardonne.", "examples": [{"text": "Jésus souffle sur les apôtres : « Recevez l''Esprit Saint ».", "translation": "Il leur donne le pouvoir de remettre les péchés."}, {"text": "Le prêtre pose la croix sur la tête et prie l''absolution.", "translation": "Dieu pardonne par lui."}], "commonErrors": [{"wrong": "Le prêtre pardonne de lui-même.", "right": "Dieu pardonne par le ministère du prêtre.", "why": "Le prêtre est le serviteur de la réconciliation (2 Co 5, 18)."}, {"wrong": "On se confesse une fois dans la vie, comme le baptême.", "right": "On se confesse régulièrement, environ une fois par mois.", "why": "La confession se répète : on pèche encore."}], "tip": "Jn 20, 22-23 : remettre ou retenir. Pour remettre, il faut connaître : on dit ses péchés."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g910.repentance_pere', 'eg', 'grammar', 'knowledge', 'La repentance et le père de confession', 2, array['eg.g909.confession']::text[], 9, '{"rule": {"summary": "On se confesse à un père de confession, un prêtre qui connaît notre vie et garde un secret absolu. La repentance est un changement du cœur : contrition, décision de changer, confession, confiance en Dieu.", "explanation": "On garde le même père de confession, qui nous accompagne dans la durée ; il est tenu au secret et l''Église punit celui qui le trahirait. La repentance commence par la contrition (« cœur brisé »), puis la décision ferme de changer, la confession à voix haute et la confiance en l''amour de Dieu, comme le fils prodigue (Lc 15). Selon l''usage, on se confesse environ une fois par mois et avant de communier.", "pattern": "Contrition → décision de changer → confession → confiance. Secret absolu. Environ une fois par mois.", "examples": [{"text": "Le prêtre ne répète jamais ce qu''il entend.", "translation": "Le secret de la confession est absolu."}, {"text": "Le fils prodigue revient vers son père.", "translation": "C''est l''image de la repentance (Lc 15)."}], "commonErrors": [{"wrong": "Se repentir, c''est seulement dire « pardon » à voix haute.", "right": "C''est un regret sincère et la décision de changer.", "why": "La repentance est un changement du cœur."}, {"wrong": "On change de père de confession à chaque fois.", "right": "On garde le même, sauf raison sérieuse.", "why": "Il connaît notre vie et nous guide dans la durée."}], "tip": "Cœur brisé, décision de changer, confession, confiance : voilà la repentance."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g911.qandil', 'eg', 'grammar', 'knowledge', 'L''onction des malades : le qandil', 2, array['eg.g910.repentance_pere']::text[], 9, '{"rule": {"summary": "L''onction des malades, ou qandil (la lampe), est le sacrement où un prêtre prie et oint d''huile un malade pour la guérison de son âme et de son corps. Il repose sur Jc 5, 14-15.", "explanation": "Jacques écrit : « Qu''il appelle les anciens de l''Église ; ils prieront pour lui et l''oindront d''huile » (Jc 5, 14). Les anciens, presbyteroi, sont les prêtres. On prépare de l''huile pure et sept mèches, on dit sept prières et on allume une mèche avant chacune. L''Église soigne l''âme d''abord, le corps selon la volonté de Dieu. Le sacrement se répète à chaque maladie ; une fois par an, selon l''usage, a lieu le qandil général.", "pattern": "Jc 5, 14-15. Huile + sept prières + sept mèches. Se répète. Qandil général : une fois par an.", "examples": [{"text": "Le prêtre trace une croix d''huile sur le front, la poitrine et les mains du malade.", "translation": "Le signe visible du sacrement."}, {"text": "On allume une mèche avant chacune des sept prières.", "translation": "D''où le nom de « lampe »."}], "commonErrors": [{"wrong": "L''onction des malades est le sacrement des mourants.", "right": "C''est le sacrement des malades, pour les relever et les soulager.", "why": "Jacques dit : « le Seigneur le relèvera »."}, {"wrong": "Le qandil garantit la guérison du corps.", "right": "Il vise la guérison de l''âme, et du corps selon la volonté de Dieu.", "why": "Dieu guérit comme il veut ; la maladie n''est pas toujours une punition."}], "tip": "Qandil = lampe : sept mèches, sept prières, une huile et un malade."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g912.mariage', 'eg', 'grammar', 'knowledge', 'Le mariage : le couronnement', 2, array['eg.g911.qandil']::text[], 9, '{"rule": {"summary": "Le mariage, ou couronnement, est un sacrement où Dieu unit un homme et une femme pour la vie. Le prêtre les couronne ; leur lien est indissoluble et reflète l''amour du Christ pour son Église.", "explanation": "Saint Paul dit du mariage : « Ce mystère est grand » (Ép 5, 32) : l''amour des époux est l''image de l''amour du Christ pour son Église. Jésus a béni les noces de Cana (Jn 2) et rappelé : « Ce que Dieu a uni, que l''homme ne le sépare pas » (Mt 19, 6). Le prêtre bénit les alliances et couronne les époux. Les fiançailles précèdent, mais ne sont pas un sacrement.", "pattern": "Mariage : Ép 5, 32 + couronnes + Mt 19, 6 (indissoluble). Fiançailles : pas un sacrement.", "examples": [{"text": "Le prêtre place des couronnes sur la tête des époux.", "translation": "Ils sont roi et reine de leur foyer."}, {"text": "Jésus bénit les noces de Cana.", "translation": "Il honore le mariage dès le début de son ministère."}], "commonErrors": [{"wrong": "Le mariage n''est qu''un contrat civil béni par l''Église.", "right": "C''est un sacrement : Dieu unit les époux.", "why": "Paul parle d''un « grand mystère » (Ép 5, 32)."}, {"wrong": "Les fiançailles sont un sacrement.", "right": "Les fiançailles précèdent le mariage mais ne sont pas un sacrement.", "why": "Seul le couronnement est le sacrement."}], "tip": "Mariage : les couronnes. Cana, le premier signe de bénédiction."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g913.sacerdoce', 'eg', 'grammar', 'knowledge', 'Le sacerdoce : l''imposition des mains', 2, array['eg.g912.mariage']::text[], 9, '{"rule": {"summary": "Le sacerdoce, ou ordination, est le sacrement où l''évêque, par l''imposition des mains, ordonne diacres, prêtres et évêques dans la succession apostolique. Il ne se répète pas pour un même degré.", "explanation": "Le sacerdoce repose sur le choix des Douze (Lc 6, 13), l''Esprit qu''ils reçoivent (Jn 20, 22) et l''imposition des mains (Ac 6, 6 ; 2 Tm 1, 6). Un évêque est ordonné par plusieurs évêques, avec le patriarche, eux-mêmes ordonnés jusqu''aux apôtres ; un prêtre est ordonné par un évêque. Il y a trois degrés : diacre, prêtre, évêque. Un homme marié avant l''ordination peut être prêtre ; les évêques sont choisis parmi les moines.", "pattern": "Les Douze → imposition des mains → évêques → prêtres, diacres. Trois degrés. Chaîne jusqu''aux apôtres.", "examples": [{"text": "L''évêque impose les mains au candidat.", "translation": "Il l''ordonne, comme à Actes 6, 6."}, {"text": "Un évêque est ordonné par plusieurs évêques.", "translation": "C''est la succession apostolique."}], "commonErrors": [{"wrong": "N''importe quel chrétien peut ordonner un prêtre.", "right": "Seul un évêque ordonne.", "why": "L''ordination se fait par l''imposition des mains des évêques, dans la ligne des apôtres."}, {"wrong": "On peut être ordonné prêtre plusieurs fois.", "right": "Le sacerdoce ne se répète pas pour un même degré.", "why": "Il imprime une marque."}], "tip": "Mariage : les couronnes. Sacerdoce : les mains."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g914.bilan_sacrements', 'eg', 'grammar', 'knowledge', 'Les sept sacrements d''un coup d''œil', 2, array['eg.g913.sacerdoce']::text[], 9, '{"rule": {"summary": "Chaque sacrement a un signe visible, un fondement biblique et une grâce : baptême (eau), confirmation (myron), eucharistie (pain et vin), confession (absolution), onction des malades (huile), mariage (couronnes), sacerdoce (mains).", "explanation": "On peut regrouper les sept sacrements : l''initiation (baptême, confirmation, eucharistie), la guérison (confession, onction des malades) et la vocation (mariage, sacerdoce). Ce regroupement est pratique, pas une division officielle. Coptes et catholiques comptent sept sacrements mais diffèrent sur le pain, le célibat des prêtres et la confirmation. La plupart des protestants n''en gardent que deux : le baptême et la Cène.", "pattern": "Baptême : eau. Confirmation : myron. Eucharistie : pain et vin. Confession : absolution. Onction : huile. Mariage : couronnes. Sacerdoce : mains.", "examples": [{"text": "Baptême : l''eau et la triple immersion, Jn 3, 5.", "translation": "On naît d''eau et d''Esprit."}, {"text": "Mariage : les couronnes, Ép 5, 32.", "translation": "Dieu unit les époux."}], "commonErrors": [{"wrong": "Les Coptes et les catholiques ont exactement les mêmes usages sacramentels.", "right": "Ils partagent les sept sacrements mais diffèrent sur le pain, le célibat des prêtres et la confirmation.", "why": "Nous utilisons un pain levé, un prêtre marié avant l''ordination est possible et le prêtre confirme tout de suite."}, {"wrong": "Les protestants n''ont aucun sacrement.", "right": "La plupart gardent deux sacrements, le baptême et la Cène.", "why": "Ils ne retiennent que ceux qu''ils jugent expressément ordonnés par le Christ."}], "tip": "Eau, huile, pain, mains, couronnes : cinq signes pour sept sacrements."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1001.orientation_est', 'eg', 'grammar', 'knowledge', 'L''orientation de l''église : vers l''est', 1, '{}'::text[], 10, '{"rule": {"summary": "Une église copte est tournée vers l''est, souvent en forme d''arche de Noé, avec des coupoles qui portent un sens.", "explanation": "L''est est le côté du soleil levant, image du Christ soleil de justice. L''Éden est à l''orient, et le Christ reviendra comme l''éclair qui part de l''orient. La forme la plus courante est l''arche de Noé ; d''autres églises ont un plan en croix ou en cercle. Une coupole représente le Christ, trois la Trinité, cinq le Christ et les quatre évangélistes.", "pattern": "Est = soleil de justice + Éden + retour du Christ. Arche de Noé = navire qui sauve.", "examples": [{"text": "Le sanctuaire est à l''est.", "translation": "On prie tourné vers lui."}, {"text": "La nef vient du latin navis.", "translation": "Le navire : l''église est une arche."}], "commonErrors": [{"wrong": "L''église regarde l''ouest.", "right": "L''église regarde l''est.", "why": "Le soleil se lève à l''est : c''est la lumière du Christ."}], "tip": "Est = lumière. Arche = navire. Trois coupoles = Trinité."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1002.trois_parties', 'eg', 'grammar', 'knowledge', 'Trois parties, comme le Tabernacle', 1, array['eg.g1001.orientation_est']::text[], 10, '{"rule": {"summary": "L''église a trois parties, narthex, nef et sanctuaire, qui rappellent le parvis, le lieu saint et le saint des saints du Tabernacle.", "explanation": "On entre par l''ouest et on avance vers l''est. Le narthex est l''entrée, où se tenaient les catéchumènes ; la nef accueille les fidèles ; le sanctuaire est réservé au clergé et aux diacres. Le plan vient du Tabernacle que Dieu montre à Moïse au Sinaï.", "pattern": "Narthex = parvis ; nef = lieu saint ; sanctuaire = saint des saints.", "examples": [{"text": "Le narthex correspond au parvis.", "translation": "Les deux sont la première étape."}], "commonErrors": [{"wrong": "Le sanctuaire est à l''entrée.", "right": "Le sanctuaire est tout à l''est.", "why": "On avance vers l''est, vers Dieu."}], "tip": "Trois espaces, trois correspondances : parvis, lieu saint, saint des saints."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1003.iconostase', 'eg', 'grammar', 'knowledge', 'L''iconostase (higab) et ses icônes', 2, array['eg.g1002.trois_parties']::text[], 10, '{"rule": {"summary": "L''iconostase (higab) est le mur d''icônes entre la nef et le sanctuaire : porte royale au centre, Christ à droite, Marie à gauche, Cène au-dessus, apôtres et croix en haut.", "explanation": "L''iconostase sépare la nef et le sanctuaire sans les couper : ses rideaux s''ouvrent pendant la liturgie. On y voit le Christ, la Vierge, Jean-Baptiste, le saint de l''église, saint Marc et l''archange Michel, puis la Cène au-dessus de la porte royale, les douze apôtres et la croix.", "pattern": "Christ à droite, Marie à gauche, Cène au centre, apôtres de chaque côté, croix en haut.", "examples": [{"text": "La Cène est au-dessus de la porte royale.", "translation": "Juste au-dessus du sanctuaire."}], "commonErrors": [{"wrong": "Le higab est un rideau sans icônes.", "right": "Le higab est un mur couvert d''icônes.", "why": "Le voile s''ouvre pendant la liturgie."}], "tip": "Christ à droite, Marie à gauche, Cène au centre."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1004.symboles', 'eg', 'grammar', 'knowledge', 'L''œuf, les lampes, l''encens et les icônes', 2, array['eg.g1003.iconostase']::text[], 10, '{"rule": {"summary": "L''œuf d''autruche, les lampes et l''encens portent chacun un sens ; à l''icône on rend la vénération, l''adoration est pour Dieu seul.", "explanation": "L''œuf d''autruche dit que Dieu veille sans cesse et annonce la résurrection. La lampe représente la lumière du Christ. La fumée de l''encens représente les prières qui montent. L''icône est une fenêtre vers celui qu''elle représente : on la vénère, on ne l''adore pas.", "pattern": "Œuf = veille + résurrection. Lampe = lumière du Christ. Encens = prières. Icône = vénération.", "examples": [{"text": "On vénère l''icône.", "translation": "On s''incline et on embrasse, sans adorer."}], "commonErrors": [{"wrong": "On adore les icônes.", "right": "On vénère les icônes, on adore Dieu seul.", "why": "L''adoration est due à Dieu seul."}], "tip": "Œuf, lampe, encens : veille, lumière, prière."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1005.haikal', 'eg', 'grammar', 'knowledge', 'Le sanctuaire (haikal) et l''autel', 2, array['eg.g1004.symboles']::text[], 10, '{"rule": {"summary": "Le haikal est le sanctuaire : on y entre déchaussé, l''autel est consacré au myron, et une seule liturgie est célébrée par jour sur un autel.", "explanation": "Le haikal est l''équivalent du saint des saints. L''autel, cube qui représente le tombeau du Christ, est consacré par l''évêque avec le myron fait par le pape. Chaque autel ne sert qu''à une liturgie par jour : d''où parfois trois autels. On entre déchaussé comme Moïse sur une terre sainte.", "pattern": "Haikal = sanctuaire ; autel consacré au myron ; une liturgie par jour et par autel ; on entre déchaussé.", "examples": [{"text": "L''évêque oint l''autel avec le myron.", "translation": "C''est ce qui le met à part pour Dieu."}], "commonErrors": [{"wrong": "Le pape consacre chaque autel.", "right": "L''évêque consacre l''autel avec le myron que le pape a fait.", "why": "Le pape prépare le myron, l''évêque l''applique."}], "tip": "Haikal : on se déchausse, on consacre, on célèbre."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1006.objets_autel', 'eg', 'grammar', 'knowledge', 'Les objets de l''autel', 2, array['eg.g1005.haikal']::text[], 10, '{"rule": {"summary": "Sur l''autel : le ciborium (le ciel), le calice (le vin mêlé d''eau), la patène (le pain), l''astérisque (l''étoile des mages), la cuillère et le coffret.", "explanation": "Au-dessus de l''autel, le ciborium rappelle le ciel. Le calice contient le vin mêlé d''eau et repose sur le coffret ; la patène porte le pain ; l''astérisque soutient le voile au-dessus du pain et rappelle l''étoile des mages ; la cuillère donne aux fidèles le sang du Christ. Les détails varient un peu d''une église à l''autre.", "pattern": "Ciborium = ciel ; calice = vin ; patène = pain ; astérisque = étoile.", "examples": [{"text": "L''astérisque est posé sur la patène.", "translation": "Il tient le voile au-dessus du pain."}], "commonErrors": [{"wrong": "La patène contient le vin.", "right": "La patène porte le pain ; le calice contient le vin.", "why": "Calice = vin, patène = pain."}], "tip": "Calice = vin. Patène = pain. Astérisque = étoile."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1007.diaconat', 'eg', 'grammar', 'knowledge', 'Le diaconat : cinq rangs', 2, array['eg.g1006.objets_autel']::text[], 10, '{"rule": {"summary": "Le diaconat copte compte cinq rangs : psalte, lecteur, sous-diacre, diacre et archidiacre. Ce sont des serviteurs, pas des prêtres.", "explanation": "Le psalte chante, le lecteur lit la Bible, le sous-diacre garde les portes, le diacre prépare et sert la liturgie, l''archidiacre dirige tous les diacres. Ils servent en tunique blanche, souvent avec une étole. Le diacre aide le prêtre mais ne consacre pas.", "pattern": "Psalte (chante) → lecteur (lit) → sous-diacre (garde) → diacre (sert) → archidiacre (dirige).", "examples": [{"text": "Dioscore a été archidiacre de Cyrille.", "translation": "Un archidiacre peut devenir pape."}], "commonErrors": [{"wrong": "Le diacre consacre l''eucharistie.", "right": "Le diacre sert, le prêtre consacre.", "why": "Diakonos veut dire serviteur."}], "tip": "Chante, lit, garde, sert, dirige."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1008.pretres_eveques', 'eg', 'grammar', 'knowledge', 'Prêtres, évêques et patriarche', 3, array['eg.g1007.diaconat']::text[], 10, '{"rule": {"summary": "Le prêtre célèbre les sacrements (marié avant l''ordination, ou moine), l''évêque ordonne et vient des moines, le pape d''Alexandrie est patriarche et préside le saint-synode.", "explanation": "Le prêtre est le deuxième degré ; le qommos est un prêtre promu archiprêtre. L''évêque, toujours moine chez les coptes, dirige un diocèse et ordonne ; le métropolite est promu à la tête d''un grand diocèse. Le patriarche, pape d''Alexandrie, préside le saint-synode, ordonne les évêques et prépare le myron. Le titre de pape vient d''Héraclas, celui de patriarche de 451.", "pattern": "Prêtre (marié avant l''ordination) → évêque (moine) → métropolite → pape-patriarche.", "examples": [{"text": "Un prêtre veuf ne se remarie pas.", "translation": "Le mariage vient toujours avant l''ordination."}], "commonErrors": [{"wrong": "Le prêtre peut ordonner.", "right": "Seul l''évêque ordonne.", "why": "L''imposition des mains est réservée à l''évêque."}], "tip": "Prêtre : marié avant. Évêque : moine. Pape : patriarche."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1009.choisir_pape', 'eg', 'grammar', 'knowledge', 'Choisir un pape : le vote puis le sort', 3, array['eg.g1008.pretres_eveques']::text[], 10, '{"rule": {"summary": "Un pape se choisit en deux temps : un vote retient trois moines, puis un enfant aux yeux bandés tire un nom sur l''autel pour que Dieu choisisse.", "explanation": "À la mort d''un pape, un évêque assure l''intérim. On établit une liste de candidats, tous moines. Une assemblée d''électeurs retient les trois qui ont le plus de voix. Les trois noms sont placés sur l''autel pendant la liturgie et un enfant aux yeux bandés en tire un : c''est la qor''a haykaleya. Tawadros II, tiré le 4 novembre 2012, est le 118e pape.", "pattern": "Intérim → liste de moines → vote (3 noms) → tirage au sort sur l''autel → intronisation.", "examples": [{"text": "Un enfant tire le nom du pape sur l''autel.", "translation": "Dieu choisit, comme pour Matthias."}], "commonErrors": [{"wrong": "Le vote désigne le pape.", "right": "Le vote retient trois noms ; le sort désigne le pape.", "why": "Le vote prépare, le sort décide."}], "tip": "Vote pour trois noms, sort pour un seul."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1010.moines', 'eg', 'grammar', 'knowledge', 'Les moines et les monastères', 3, array['eg.g1009.choisir_pape']::text[], 10, '{"rule": {"summary": "Les moines coptes vivent toujours dans des monastères d''Égypte, près de la mer Rouge et à Wadi Natroun ; abbés et ermites prolongent l''élan d''Antoine.", "explanation": "Le moine prie, travaille et jeûne ; l''abbé dirige le monastère ; l''ermite vit seul au désert ; l''eskime est le grand habit des moines avancés. Saint-Antoine et Saint-Paul sont près de la mer Rouge. À Wadi Natroun, l''ancienne Scété, il reste quatre monastères : Saint-Macaire, Baramous, Anba Bishoy et celui des Syriens.", "pattern": "Moine → abbé (dirige) ; ermite (seul) ; eskime (habit). Mer Rouge : Antoine et Paul. Wadi Natroun : quatre.", "examples": [{"text": "Baramous veut dire « des Romains ».", "translation": "Une tradition parle de deux princes romains devenus moines."}], "commonErrors": [{"wrong": "Wadi Natroun est près de la mer Rouge.", "right": "Wadi Natroun est près du Caire ; la mer Rouge, c''est Antoine et Paul.", "why": "Mer Rouge : Antoine et Paul. Wadi Natroun : quatre."}], "tip": "Mer Rouge : Antoine et Paul. Wadi Natroun : quatre."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1011.bilan', 'eg', 'grammar', 'knowledge', 'Bilan : l''église et le clergé', 3, array['eg.g1010.moines']::text[], 10, '{"rule": {"summary": "Bilan : le chemin vers l''est, les objets qui parlent, le haikal, l''échelle du clergé et le choix du pape.", "explanation": "L''église est un chemin du narthex au sanctuaire, comme le Tabernacle. L''iconostase, l''œuf d''autruche, la lampe et l''encens portent chacun un sens. L''autel est le tombeau du Christ, consacré au myron. Le clergé monte du psalte au pape ; le pape est désigné par un vote puis un tirage au sort sur l''autel ; évêques et pape viennent des moines.", "pattern": "Narthex → nef → iconostase → haikal → autel. Psalte → … → pape.", "examples": [{"text": "Du psalte au pape.", "translation": "Cinq rangs de diacres, puis prêtre, évêque, patriarche."}], "commonErrors": [{"wrong": "On adore les icônes.", "right": "On vénère les icônes, on adore Dieu seul.", "why": "Adoration ≠ vénération."}], "tip": "Porte, mur d''icônes, autel : tout se tient."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1101.sept_fois', 'eg', 'grammar', 'knowledge', 'Prier sans cesse : les sept heures', 1, '{}'::text[], 11, '{"rule": {"summary": "Pour « prier sans cesse » (1 Th 5, 17), l''Église donne des heures de prière. L''Agpeya, le livre des heures, en compte sept, d''après le psaume 119, 164 : « Sept fois le jour je te loue ».", "explanation": "On ne peut pas réciter des prières toute la journée. L''Église donne donc des rendez-vous réguliers avec Dieu. Daniel priait trois fois par jour et les apôtres gardaient les heures de leur peuple. Chaque heure de l''Agpeya rappelle un moment de la vie du Christ.", "pattern": "Prier sans cesse → des rendez-vous → sept heures dans l''Agpeya → chaque heure rappelle un moment du Christ.", "examples": [{"text": "Agpeya vient du copte agp, « heure ».", "translation": "C''est le livre des heures."}, {"text": "Le psaume 119, 164 dit : « Sept fois le jour je te loue ».", "translation": "Le livre en tire ses sept heures."}, {"text": "Daniel prie trois fois par jour, même quand c''est interdit.", "translation": "Un modèle de fidélité aux heures."}], "commonErrors": [{"wrong": "Les heures de prière sont une punition.", "right": "Les heures sont des rendez-vous avec Dieu.", "why": "Comme une alarme qui rappelle un ami, pas une sanction."}, {"wrong": "L''Agpeya est un livre pour les prêtres seulement.", "right": "L''Agpeya est fait pour tous les fidèles.", "why": "On le prie seul ou à plusieurs, à la maison comme à l''église."}], "tip": "Agp = heure. L''Agpeya, c''est le livre des heures."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1102.prime_aube', 'eg', 'grammar', 'knowledge', 'Heures bibliques et Prime', 1, array['eg.g1101.sept_fois']::text[], 11, '{"rule": {"summary": "Dans la Bible, le jour commence au lever du soleil, vers 6 h. Prime, Tierce, Sexte et None sont les 1re, 3e, 6e et 9e heures : 6 h, 9 h, midi et 15 h. Prime rappelle l''incarnation et la Résurrection.", "explanation": "Les mots viennent du latin : prime « première », tierce « troisième », sexte « sixième », none « neuvième ». Pour passer d''une heure biblique à l''heure d''aujourd''hui, on ajoute 6. À Prime, on remercie Dieu pour la nuit et on lui confie la journée.", "pattern": "Heure biblique + 6 = heure d''aujourd''hui : 1re = 6 h, 3e = 9 h, 6e = midi, 9e = 15 h.", "examples": [{"text": "La troisième heure du jour, c''est 9 h.", "translation": "3 + 6 = 9."}, {"text": "Prime se prie vers 6 h, au lever du soleil.", "translation": "Le soleil qui se lève est l''image du Christ ressuscité."}], "commonErrors": [{"wrong": "La neuvième heure, c''est 9 h.", "right": "La neuvième heure, c''est 15 h.", "why": "Le jour biblique commence à 6 h : 9 + 6 = 15."}], "tip": "Prime = première heure = 6 h = le soleil qui se lève = la Résurrection."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1103.tierce', 'eg', 'grammar', 'knowledge', 'Tierce : Pilate et la Pentecôte', 1, array['eg.g1102.prime_aube']::text[], 11, '{"rule": {"summary": "Tierce se prie à 9 h, la troisième heure. Elle rappelle le procès du Christ devant Pilate et la descente du Saint-Esprit à la Pentecôte. Elle est priée avant chaque messe.", "explanation": "Deux scènes se suivent à la même heure : le Christ est jugé pour nous, puis l''Esprit est donné à l''Église. Pour s''en souvenir : un tribunal, puis une flamme. Tierce et Sexte sont priées avant chaque messe, pour arriver à la liturgie déjà en prière.", "pattern": "9 h = 3e heure = Tierce → procès devant Pilate + Pentecôte.", "examples": [{"text": "À 9 h, on prie Tierce.", "translation": "Troisième heure du jour, six plus trois."}, {"text": "Tierce rappelle Pilate puis la Pentecôte.", "translation": "Un tribunal, puis une flamme."}], "commonErrors": [{"wrong": "Tierce rappelle la crucifixion.", "right": "Tierce rappelle le procès devant Pilate et la Pentecôte.", "why": "La crucifixion est rappelée à midi, par Sexte."}], "tip": "Tierce = un tribunal, puis une flamme."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1104.sexte_none', 'eg', 'grammar', 'knowledge', 'Sexte et None : la croix', 1, array['eg.g1103.tierce']::text[], 11, '{"rule": {"summary": "Sexte se prie à midi, la sixième heure, et rappelle la crucifixion. La None se prie à 15 h, la neuvième heure, et rappelle la mort du Christ ; on la prie aussi les jours de jeûne.", "explanation": "À la sixième heure, les ténèbres couvrent la terre jusqu''à la neuvième heure (Mt 27, 45). À la neuvième heure, Jésus rend l''esprit. La None rappelle aussi le bon larron à qui Jésus promet le paradis : il n''est jamais trop tard.", "pattern": "Midi = Sexte = ténèbres sur la croix ; 15 h = None = dernier souffle et bon larron.", "examples": [{"text": "À midi, on prie Sexte.", "translation": "Le ciel noir de la crucifixion."}, {"text": "À 15 h, on prie la None.", "translation": "Le dernier souffle du Christ."}, {"text": "« Aujourd''hui tu seras avec moi dans le paradis. »", "translation": "La promesse au bon larron (Lc 23, 43)."}], "commonErrors": [{"wrong": "La None rappelle la Résurrection.", "right": "La None rappelle la mort du Christ sur la croix.", "why": "La Résurrection est rappelée à l''aube, par Prime."}, {"wrong": "Sexte se prie à 15 h.", "right": "Sexte se prie à midi.", "why": "Sexte = sixième heure = 6 + 6."}], "tip": "Sexte = midi, ciel noir. None = 15 h, dernier souffle."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1105.vepres_complies', 'eg', 'grammar', 'knowledge', 'Vêpres et Complies', 1, array['eg.g1104.sexte_none']::text[], 11, '{"rule": {"summary": "Vêpres (« soir ») se prient au coucher du soleil, vers 17-18 h, et rappellent la descente de la croix. Complies se prient vers 21 h, avant de dormir, et rappellent l''ensevelissement et le Jugement dernier.", "explanation": "Le soir de la prière suit le soir de la Passion : la None pour la mort, Vêpres pour la descente de la croix (Joseph d''Arimathie), Complies pour le tombeau. Pendant le Grand Carême et le jeûne de Ninive, Vêpres et Complies se prient aussi à l''église.", "pattern": "None (15 h) la mort → Vêpres (coucher du soleil) la descente → Complies (21 h) le tombeau.", "examples": [{"text": "Vêpres vient du latin vesper, « soir ».", "translation": "On remercie Dieu pour la journée."}, {"text": "Complies vient du latin completorium.", "translation": "Ce qui achève la journée."}], "commonErrors": [{"wrong": "Vêpres rappellent l''ensevelissement.", "right": "Vêpres rappellent la descente de la croix.", "why": "L''ensevelissement est rappelé plus tard, à 21 h, par Complies."}], "tip": "Mort, descente, tombeau : None, Vêpres, Complies."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1106.minuit', 'eg', 'grammar', 'knowledge', 'Minuit et la prière du voile', 1, array['eg.g1105.vepres_complies']::text[], 11, '{"rule": {"summary": "Minuit est la septième heure : on se lève la nuit pour louer Dieu. Elle rappelle la seconde venue du Christ (les dix vierges) et compte trois veilles, comme les trois prières du Christ à Gethsémani. La prière du voile est à part.", "explanation": "Paul et Silas chantent à minuit en prison, le psalmiste se lève à minuit. Dans la parabole des dix vierges, un cri retentit à minuit : « Voici l''époux ! ». Les cinq sages avaient de l''huile : il faut veiller. Après les sept heures, la prière du voile est un examen de conscience, surtout pour évêques, prêtres et moines.", "pattern": "Minuit = veiller = dix vierges = seconde venue ; trois veilles = trois prières à Gethsémani.", "examples": [{"text": "À minuit, un cri retentit : « Voici l''époux ! »", "translation": "La parabole des dix vierges."}, {"text": "La prière de Minuit compte trois veilles.", "translation": "Comme les trois prières du Christ à Gethsémani."}], "commonErrors": [{"wrong": "La prière du voile est la huitième heure.", "right": "La prière du voile n''est pas une des sept heures.", "why": "C''est une prière à part, un examen de conscience."}], "tip": "Minuit = veiller comme les cinq vierges sages."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1107.plan_heure', 'eg', 'grammar', 'knowledge', 'Les neuf étapes d''une heure', 1, array['eg.g1106.minuit']::text[], 11, '{"rule": {"summary": "Chaque heure de l''Agpeya suit le même plan en neuf étapes : introduction avec le Notre Père, action de grâce, psaume 50, psaumes de l''heure, Évangile, litanies, 41 Kyrie, prières et absolution, conclusion.", "explanation": "Seuls les psaumes et l''Évangile changent d''une heure à l''autre. Le psaume 50 est la repentance de David : avant de louer, on reconnaît qu''on est pécheur. On peut retenir trois blocs de trois : ouvrir, louer et écouter, conclure.", "pattern": "Ouvrir (Notre Père, action de grâce, psaume 50) → louer et écouter (psaumes, Évangile, litanies) → conclure (41 Kyrie, absolution, conclusion).", "examples": [{"text": "Chaque heure commence par le Notre Père.", "translation": "La prière que le Christ a enseignée."}, {"text": "Le psaume 50 vient avant les psaumes de louange.", "translation": "Avant de louer, on demande pardon."}], "commonErrors": [{"wrong": "Chaque heure a un plan différent.", "right": "Toutes les heures suivent le même plan en neuf étapes.", "why": "Seuls les psaumes et l''Évangile changent."}], "tip": "Trois blocs de trois : ouvrir, louer et écouter, conclure."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1108.gestes', 'eg', 'grammar', 'knowledge', 'Les gestes de la prière', 1, array['eg.g1107.plan_heure']::text[], 11, '{"rule": {"summary": "On prie debout, tourné vers l''est, avec le signe de croix et des métanies. Les 41 Kyrie rappellent, selon la tradition, les 39 coups de fouet, la couronne d''épines et la lance. On se prépare : mains et visage lavés, chaussures retirées.", "explanation": "Chaque geste a un sens. Debout : on se tient devant Dieu. La métanie : on s''abaisse pour adorer. Le signe de croix : on marque sur soi la croix du Christ. Se déchausser : comme Moïse, on se tient sur une terre sainte. Les femmes se couvrent la tête (1 Co 11, 5-6).", "pattern": "Debout, signe de croix, métanies, 41 Kyrie ; mains lavées, chaussures retirées.", "examples": [{"text": "Une métanie est une prosternation.", "translation": "On s''incline profondément pour adorer."}, {"text": "41 = 39 coups de fouet + la couronne d''épines + la lance.", "translation": "Selon la tradition copte."}], "commonErrors": [{"wrong": "Les 41 Kyrie sont un chiffre au hasard.", "right": "Selon la tradition, 41 rappelle les souffrances du Christ.", "why": "39 coups de fouet, la couronne d''épines et la lance."}], "tip": "À chaque Kyrie, pense à ce que le Christ a souffert."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1109.vers_l_est', 'eg', 'grammar', 'knowledge', 'Les six raisons de prier vers l''est', 1, array['eg.g1108.gestes']::text[], 11, '{"rule": {"summary": "On prie tourné vers l''est pour six raisons données par la tradition : le paradis perdu, la seconde venue, le soleil de justice, l''étoile des mages, la croix et le baptême.", "explanation": "Toutes les raisons tiennent en une idée : l''est est le côté de la lumière, du retour et du Christ. Le paradis est à l''orient, le Christ revient de l''orient, il est le soleil qui se lève, les mages ont suivi son étoile, le crucifié regardait l''ouest, et au baptême on se tourne vers l''est pour le confesser.", "pattern": "Paradis perdu · seconde venue · soleil de justice · étoile des mages · croix · baptême.", "examples": [{"text": "Dieu planta un jardin en Éden, à l''orient.", "translation": "Raison 1, donnée par saint Basile."}, {"text": "Comme l''éclair part de l''orient, ainsi sera l''avènement du Fils de l''homme.", "translation": "Raison 2 : le Christ reviendra de l''orient."}], "commonErrors": [{"wrong": "On prie vers l''est seulement à cause du paradis.", "right": "Il y a six raisons : le paradis n''en est qu''une.", "why": "Retiens aussi le retour du Christ, le soleil, l''étoile, la croix et le baptême."}], "tip": "L''est = la lumière, le retour, le Christ."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1110.bilan_agpeya', 'eg', 'grammar', 'knowledge', 'Bilan : l''Agpeya de A à Z', 1, array['eg.g1109.vers_l_est']::text[], 11, '{"rule": {"summary": "L''Agpeya compte sept heures, chacune liée à un moment de la vie du Christ, de Prime (6 h) à Minuit. Une heure suit neuf étapes avec 41 Kyrie, on prie debout et tourné vers l''est, pour six raisons.", "explanation": "Prime rappelle la Résurrection, Tierce Pilate et la Pentecôte, Sexte la croix, la None la mort, Vêpres la descente, Complies le tombeau, Minuit le retour du Christ. La prière du voile est à part. L''est est le côté de la lumière, du retour et du Christ.", "pattern": "6 h Prime · 9 h Tierce · midi Sexte · 15 h None · soir Vêpres · 21 h Complies · nuit Minuit.", "examples": [{"text": "Il est 15 h : c''est la None.", "translation": "La mort du Christ sur la croix."}, {"text": "Il est 21 h : ce sont Complies.", "translation": "L''ensevelissement et le Jugement dernier."}], "commonErrors": [{"wrong": "La prière du voile est la huitième heure.", "right": "La prière du voile est à part.", "why": "Elle ne compte pas parmi les sept heures."}], "tip": "Une journée, un chemin : de l''aube de la Résurrection à l''attente du retour."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1201.reveil', 'eg', 'grammar', 'knowledge', 'La tasbeha et Ten thino', 1, '{}'::text[], 12, '{"rule": {"summary": "La tasbeha (« louange » en arabe) est la louange de minuit : chaque nuit dans les monastères, surtout la veille d''une messe en paroisse. Elle prolonge l''Agpeya de minuit et commence par Ten thino : « Levez-vous, fils de la lumière ».", "explanation": "Elle garde le nom de minuit, mais l''horaire s''adapte à la vie de la paroisse. Après l''Agpeya de minuit, Ten thino réveille l''assemblée pour louer. Pour saint Paul, les fils de la lumière sont les chrétiens : ils veillent au lieu de dormir (1 Th 5, 5).", "pattern": "Agpeya de minuit → Ten thino → on se lève pour louer.", "examples": [{"text": "Tasbeha, de l''arabe : « louange ».", "translation": "C''est la louange de minuit."}, {"text": "Ten thino : « Levez-vous, fils de la lumière ».", "translation": "L''appel à se réveiller pour louer."}], "commonErrors": [{"wrong": "La tasbeha se prie seulement à minuit pile.", "right": "En paroisse, on la prie surtout la veille d''une messe, sans attendre minuit.", "why": "Le nom reste, l''horaire s''adapte à la vie de la paroisse."}, {"wrong": "La tasbeha est un chant de la messe.", "right": "La tasbeha est une prière à part, la louange de minuit.", "why": "Elle se prie avant la messe, pas pendant."}], "tip": "Tasbeha = louange. Ten thino = debout, fils de la lumière !"}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1202.nuit_louange', 'eg', 'grammar', 'knowledge', 'Les six étapes de la tasbeha', 1, array['eg.g1201.reveil']::text[], 12, '{"rule": {"summary": "La tasbeha suit six étapes : l''Agpeya de minuit, Ten thino, les quatre hoos (avec les doxologies entre le 3e et le 4e), le psali et la théotokie du jour, le difnar, la conclusion.", "explanation": "Comme une heure de l''Agpeya a neuf étapes, la tasbeha a un plan fixe. Le difnar rappelle le saint du jour, comme le synaxaire, livre de vies de saints. La conclusion réunit le Credo, le Trisagion (« trois fois saint ») et le Notre Père, avec l''absolution si un prêtre est présent.", "pattern": "Agpeya de minuit → Ten thino → 4 hoos → psali et théotokie → difnar → conclusion.", "examples": [{"text": "Le difnar rappelle le saint du jour.", "translation": "Même rôle que le synaxaire."}, {"text": "Trisagion : « trois fois saint ».", "translation": "Il clôt la nuit avec le Credo et le Notre Père."}], "commonErrors": [{"wrong": "La tasbeha a neuf étapes comme une heure de l''Agpeya.", "right": "La tasbeha a six étapes.", "why": "Les neuf étapes sont celles d''une heure de l''Agpeya."}], "tip": "Prier, se lever, louer, chanter, écouter, conclure."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1203.hoos_lobsh', 'eg', 'grammar', 'knowledge', 'Hoos et lobsh : les deux premiers', 1, array['eg.g1202.nuit_louange']::text[], 12, '{"rule": {"summary": "Un hoos est un cantique tiré de la Bible ; la tasbeha en chante quatre, chacun suivi d''un lobsh qui l''explique. Le 1er est le cantique de Moïse (Ex 15), le 2e le psaume 135 (136).", "explanation": "On chante, puis on comprend : le lobsh commente le hoos qu''on vient de chanter. Le 1er hoos célèbre la traversée de la mer Rouge, image de la sortie de l''esclavage du péché. Le 2e est une action de grâce : son amour est éternel.", "pattern": "Hoos (cantique biblique) → lobsh (explication). 1er : mer Rouge. 2e : psaume 135.", "examples": [{"text": "1er hoos : Ex 15, la traversée de la mer Rouge.", "translation": "Il symbolise la sortie de l''esclavage du péché."}, {"text": "2e hoos : le psaume 135 (136).", "translation": "Son amour est éternel : une action de grâce."}], "commonErrors": [{"wrong": "Le lobsh est un hoos.", "right": "Le lobsh explique le hoos.", "why": "On chante le hoos, puis le lobsh en donne le sens."}], "tip": "Hoos = on chante. Lobsh = on comprend."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1204.hoos_doxologies', 'eg', 'grammar', 'knowledge', 'Hoos 3 et 4, doxologies', 1, array['eg.g1203.hoos_lobsh']::text[], 12, '{"rule": {"summary": "Le 3e hoos est le cantique des trois jeunes gens dans la fournaise (Dn 3), le 4e réunit les psaumes 148 à 150. Entre les deux, on commémore les saints et on chante les doxologies, d''abord à la Vierge.", "explanation": "Les quatre hoos racontent une histoire : sortie de l''esclavage, action de grâce, louange de toute la création, joie et victoire. Doxa veut dire « gloire » en grec. La lettre aux Hébreux parle d''une nuée de témoins : l''Église chante avec ses saints.", "pattern": "Mer Rouge → psaume 135 → fournaise → (saints et doxologies) → psaumes 148-150.", "examples": [{"text": "3e hoos : Dn 3, la fournaise.", "translation": "Toute la création est appelée à louer Dieu."}, {"text": "4e hoos : psaumes 148, 149, 150.", "translation": "Joie et victoire."}], "commonErrors": [{"wrong": "Les doxologies viennent après le 4e hoos.", "right": "Les doxologies viennent entre le 3e et le 4e hoos.", "why": "Le 4e hoos, les psaumes 148 à 150, clôt la série."}], "tip": "Doxa = gloire. Les doxologies, entre le 3e et le 4e hoos."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1205.psali_theotokie', 'eg', 'grammar', 'knowledge', 'Psali et théotokie', 1, array['eg.g1204.hoos_doxologies']::text[], 12, '{"rule": {"summary": "Le psali est un chant au Christ (un par jour, deux le dimanche). La théotokie est une louange de la Vierge Marie, différente chaque jour : sept en tout. Elle explique l''incarnation par des images : buisson ardent, arche, cruche d''or, chandelier.", "explanation": "Théotokie vient de Théotokos, « mère de Dieu », titre confirmé à Éphèse en 431. Louer Marie, c''est confesser l''incarnation, à l''inverse de Nestorius. Les symboles disent que Marie porte Dieu sans être détruite, et qu''elle nous donne le Christ : feu, Verbe, pain et lumière.", "pattern": "Psali = chant au Christ ; théotokie = chant à la Vierge ; tous deux sur l''air du jour.", "examples": [{"text": "Le psali loue le Christ.", "translation": "Un par jour, deux le dimanche."}, {"text": "La théotokie loue la Vierge.", "translation": "Sept théotokies pour sept jours."}], "commonErrors": [{"wrong": "La théotokie est un chant au Christ.", "right": "La théotokie loue la Vierge Marie.", "why": "C''est le psali qui s''adresse au Christ."}], "tip": "Psali = Fils. Théotokie = Mère."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1206.adam_watos', 'eg', 'grammar', 'knowledge', 'Jours Adam et jours Watos', 1, array['eg.g1205.psali_theotokie']::text[], 12, '{"rule": {"summary": "La psalmodie a deux airs : Adam (dimanche, lundi, mardi) et Watos (mercredi, jeudi, vendredi, samedi). Adam est le premier mot de la théotokie du lundi ; Watos vient de Pibatos, premier mot de celle du jeudi.", "explanation": "Trois jours Adam, quatre jours Watos : Adam ouvre la semaine, Watos la termine. Le psali et la théotokie du jour se chantent sur l''air du jour. Les noms viennent du premier mot de deux théotokies : « Adam » le lundi, « Pibatos » (le buisson) le jeudi.", "pattern": "Adam : dim., lun., mar. (3 jours). Watos : mer., jeu., ven., sam. (4 jours).", "examples": [{"text": "Le lundi est un jour Adam.", "translation": "La théotokie du lundi commence par « Adam »."}, {"text": "Le jeudi est un jour Watos.", "translation": "La théotokie du jeudi commence par « Pibatos »."}], "commonErrors": [{"wrong": "Le mercredi est un jour Adam.", "right": "Le mercredi est un jour Watos.", "why": "Adam s''arrête au mardi."}, {"wrong": "Watos vient du nom d''un saint.", "right": "Watos vient de Pibatos, le buisson.", "why": "C''est le premier mot de la théotokie du jeudi."}], "tip": "Adam : les 3 premiers jours. Watos : les 4 derniers."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1207.regle_du_soir', 'eg', 'grammar', 'knowledge', 'La règle du soir', 1, array['eg.g1206.adam_watos']::text[], 12, '{"rule": {"summary": "Le jour liturgique commence la veille au soir. Règle du soir : le soir, on prie la théotokie du lendemain, sur l''air du lendemain. L''air change seulement deux soirs par semaine : samedi soir (Adam) et mardi soir (Watos).", "explanation": "La Genèse dit : « il y eut un soir, il y eut un matin ». Le soir, l''Église est donc déjà dans le jour suivant. Samedi à 20 h : théotokie du dimanche, air Adam. Mardi à 20 h : théotokie du mercredi, air Watos. Le matin, à 10 h, on prie celle du jour.", "pattern": "Soir (20 h) : théotokie et air du lendemain. Matin (10 h) : théotokie et air du jour.", "examples": [{"text": "Samedi, 20 h : théotokie du dimanche, air Adam.", "translation": "Le dimanche est un jour Adam."}, {"text": "Mardi, 20 h : théotokie du mercredi, air Watos.", "translation": "Le mercredi est un jour Watos."}], "commonErrors": [{"wrong": "Le mardi soir, on chante encore sur l''air Adam.", "right": "Le mardi soir, on passe à l''air Watos.", "why": "Le soir, on est déjà mercredi."}], "tip": "Le soir, regarde le jour d''après : sa théotokie, son air."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1208.kiahk', 'eg', 'grammar', 'knowledge', 'Kiahk et la tasbeha « sept et quatre »', 1, array['eg.g1207.regle_du_soir']::text[], 12, '{"rule": {"summary": "Kiahk, quatrième mois copte (vers décembre), est le mois marial, pendant le jeûne de la Nativité. On y prie la grande tasbeha « sept et quatre » : les 7 théotokies et les 4 hoos.", "explanation": "Autrefois la tasbeha de Kiahk durait toute la nuit du samedi au dimanche ; aujourd''hui on la prie souvent chaque soir du mois, avec la théotokie du jour. Louer Marie avant la Nativité prépare la venue du Christ : c''est par elle que le Verbe se fait homme.", "pattern": "Kiahk = mois marial = jeûne de la Nativité = tasbeha « sept et quatre » (7 théotokies + 4 hoos).", "examples": [{"text": "Kiahk est le mois marial.", "translation": "On y loue Marie par ses théotokies."}, {"text": "« Sept et quatre » : 7 théotokies et 4 hoos.", "translation": "La grande tasbeha de Kiahk."}], "commonErrors": [{"wrong": "Kiahk est le mois du Carême.", "right": "Kiahk tombe pendant le jeûne de la Nativité.", "why": "Il prépare Noël, pas Pâques."}], "tip": "Kiahk = Marie avant Noël."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1209.bilan_tasbeha', 'eg', 'grammar', 'knowledge', 'Bilan : la tasbeha de A à Z', 1, array['eg.g1208.kiahk']::text[], 12, '{"rule": {"summary": "La tasbeha suit six étapes : Agpeya de minuit, Ten thino, quatre hoos, psali et théotokie, difnar, conclusion. Adam : dimanche à mardi. Watos : mercredi à samedi. Le soir, on prie la théotokie et l''air du lendemain.", "explanation": "Les hoos sont la mer Rouge, le psaume 135, la fournaise et les psaumes 148 à 150, avec les doxologies entre le 3e et le 4e. Le psali loue le Christ, la théotokie sa Mère. Adam vient du premier mot de la théotokie du lundi, Watos de Pibatos, celle du jeudi.", "pattern": "Prier, se lever, louer, chanter, écouter, conclure. Soir = lendemain.", "examples": [{"text": "Samedi à 20 h : théotokie du dimanche, air Adam.", "translation": "La règle du soir."}, {"text": "Watos vient de Pibatos, le buisson.", "translation": "Premier mot de la théotokie du jeudi."}], "commonErrors": [{"wrong": "Le psali loue la Vierge.", "right": "Le psali loue le Christ ; la théotokie loue la Vierge.", "why": "Psali = Fils, théotokie = Mère."}], "tip": "Une nuit : prier, se lever, louer, chanter, écouter, conclure."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1301.treize_mois', 'eg', 'grammar', 'knowledge', 'Le calendrier copte : treize mois', 1, '{}'::text[], 13, '{"rule": {"summary": "Le calendrier copte a treize mois : douze de 30 jours et un petit mois de 5 jours. Chaque mois commence vers le 10 d''un mois de notre calendrier. Les deux premiers sont Tout et Baba.", "explanation": "Les Égyptiens ont réglé leur année sur le soleil et sur le Nil. Douze mois de 30 jours font 360 jours, et un petit mois de 5 jours complète l''année à 365. Chaque mois commence vers le 10 du nôtre, à un jour près (dans une année sur quatre, un jour plus tard). Tout ouvre l''année avec le Nayrouz, Baba vient ensuite.", "pattern": "12 × 30 jours + 5 jours ; chaque mois commence vers le 10 ; 1 Tout (11 sept.), 2 Baba (11 oct.).", "examples": [{"text": "Tout commence vers le 11 septembre.", "translation": "C''est le Nayrouz, le jour de l''an copte."}, {"text": "Baba commence vers le 11 octobre.", "translation": "Un mois après Tout."}], "commonErrors": [{"wrong": "Un mois copte commence le 1er du mois.", "right": "Il commence vers le 10.", "why": "Le calendrier copte est décalé par rapport au nôtre."}, {"wrong": "L''année copte a 12 mois.", "right": "Elle en a 13.", "why": "Le petit mois Nasie vient après les douze grands."}], "tip": "Un mois copte démarre vers le 10 du nôtre."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1302.hatour_kiahk_touba', 'eg', 'grammar', 'knowledge', 'Hatour, Kiahk, Touba', 1, array['eg.g1301.treize_mois']::text[], 13, '{"rule": {"summary": "Hatour est le troisième mois (semailles), Kiahk le quatrième (le mois marial) et Touba le cinquième (le plus froid).", "explanation": "Hatour, vers le 10 novembre, porte le nom de la déesse Hathor : on sème le blé. Kiahk, vers le 10 décembre, est le mois de la Vierge Marie, et ses jours sont très courts. Touba, vers le 9 janvier, est le cœur de l''hiver. Les proverbes de paysans résument chaque mois.", "pattern": "3 Hatour (10 nov.), 4 Kiahk (10 déc.), 5 Touba (9 janv.).", "examples": [{"text": "Hatour est le troisième mois.", "translation": "On y sème le blé."}, {"text": "Kiahk est le quatrième mois.", "translation": "C''est le mois marial."}, {"text": "Touba est le cinquième mois.", "translation": "C''est le plus froid."}], "commonErrors": [{"wrong": "Touba est un mois d''été.", "right": "Touba est un mois d''hiver, vers le 9 janvier.", "why": "Les mois coptes sont décalés par rapport aux nôtres."}, {"wrong": "Kiahk est le premier mois.", "right": "Kiahk est le quatrième.", "why": "Le premier est Tout."}], "tip": "Kiahk, le 4e, c''est Marie ; Touba, le 5e, c''est le froid."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1303.vents_et_moisson', 'eg', 'grammar', 'knowledge', 'Amshir, Baramhat, Baramouda', 2, array['eg.g1302.hatour_kiahk_touba']::text[], 13, '{"rule": {"summary": "Amshir est le sixième mois (les vents), Baramhat le septième (la récolte commence) et Baramouda le huitième (on bat le grain).", "explanation": "Amshir, vers le 8 février, est le mois des vents. Baramhat, vers le 10 mars, ouvre la récolte : « va au champ et rapporte ». Baramouda, vers le 9 avril, est celui où l''on bat le grain. Baramhat et Baramouda se ressemblent : d''abord on va au champ, ensuite on bat le blé.", "pattern": "6 Amshir (8 févr.), 7 Baramhat (10 mars), 8 Baramouda (9 avril).", "examples": [{"text": "Amshir est le mois des vents.", "translation": "Rafales et poussière."}, {"text": "Baramhat vient avant Baramouda.", "translation": "On va au champ, puis on bat le grain."}], "commonErrors": [{"wrong": "Baramouda vient avant Baramhat.", "right": "Baramhat (7e) vient avant Baramouda (8e).", "why": "D''abord le champ, ensuite le battage."}, {"wrong": "Le 20 mars est dans Amshir.", "right": "Le 20 mars est dans Baramhat.", "why": "Amshir finit vers le 9 mars."}], "tip": "Baramhat = on va au champ ; Baramouda = on bat le grain."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1304.chaleur_et_nil', 'eg', 'grammar', 'knowledge', 'Bashans, Baouna, Abib', 2, array['eg.g1303.vents_et_moisson']::text[], 13, '{"rule": {"summary": "Bashans est le neuvième mois (le champ balayé), Baouna le dixième (le Nil repart) et Abib le onzième (le plein été).", "explanation": "Bashans, vers le 9 mai, voit la moisson finie : il balaie le champ. Baouna, vers le 8 juin, est très chaud, mais le Nil recommence à monter à sa fin. Abib, vers le 8 juillet, est au cœur de l''été ; son nom est d''origine inconnue.", "pattern": "9 Bashans (9 mai), 10 Baouna (8 juin), 11 Abib (8 juillet).", "examples": [{"text": "Bashans balaie le champ.", "translation": "La moisson est finie."}, {"text": "Abib tombe en plein été.", "translation": "Le onzième mois, vers le 8 juillet."}], "commonErrors": [{"wrong": "Abib vient avant Baouna.", "right": "Baouna (10e) vient avant Abib (11e).", "why": "On avance de juin à juillet."}, {"wrong": "Les proverbes des mois sont des règles de l''Église.", "right": "Ce sont des dictons de paysans.", "why": "Ils viennent de la vie des champs."}], "tip": "Bashans balaie, Baouna voit le Nil repartir, Abib est en plein été."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1305.misra_nasie', 'eg', 'grammar', 'knowledge', 'Misra et Nasie', 2, array['eg.g1304.chaleur_et_nil']::text[], 13, '{"rule": {"summary": "Misra est le douzième mois (la crue) et Nasie le treizième : le petit mois, de 5 jours, ou 6 tous les quatre ans.", "explanation": "Misra, vers le 7 août, voit la crue remplir les canaux. Nasie, le petit mois, compte 5 jours juste avant le Nayrouz. Tous les quatre ans, il en compte 6, et le Nayrouz suivant tombe le 12 septembre. Après Nasie, l''année recommence avec Tout.", "pattern": "12 Misra (7 août), 13 Nasie (6 sept., 5 ou 6 jours), puis Tout.", "examples": [{"text": "Nasie est le petit mois.", "translation": "Il compte 5 jours, ou 6 tous les quatre ans."}, {"text": "Après Nasie vient Tout.", "translation": "L''année recommence."}], "commonErrors": [{"wrong": "Nasie compte 30 jours.", "right": "Nasie compte 5 jours, ou 6.", "why": "Il complète les 360 jours pour arriver à 365."}, {"wrong": "Misra est le dernier mois.", "right": "Misra est le douzième ; le treizième est Nasie.", "why": "Le petit mois vient après les douze grands."}], "tip": "Misra, Nasie, Tout : et la boucle recommence."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1306.saisons_et_dates', 'eg', 'grammar', 'knowledge', 'Les saisons et les dates', 3, array['eg.g1305.misra_nasie']::text[], 13, '{"rule": {"summary": "L''année a trois saisons de quatre mois : la crue (Tout à Kiahk), la croissance (Touba à Baramouda), la moisson (Bashans à Misra). Pour trouver le mois d''une date, on prend le dernier début de mois avant elle.", "explanation": "C''est l''ancien découpage de l''année égyptienne, et Nasie ferme la boucle. Pour trouver le mois copte d''une date, repère le début de mois juste avant : Baramhat commence vers le 10 mars, donc le 20 mars est dans Baramhat. Choisis des dates au milieu du mois, car près d''un début, un jour d''écart est possible.", "pattern": "Crue : Tout-Kiahk. Croissance : Touba-Baramouda. Moisson : Bashans-Misra. Mois = dernier début avant la date.", "examples": [{"text": "Le 20 mars tombe dans Baramhat.", "translation": "Baramhat commence vers le 10 mars."}, {"text": "Le 25 juillet tombe dans Abib.", "translation": "Abib commence vers le 8 juillet."}, {"text": "Le 25 décembre tombe dans Kiahk.", "translation": "Kiahk commence vers le 10 décembre."}], "commonErrors": [{"wrong": "Le 20 mars est dans Amshir.", "right": "Le 20 mars est dans Baramhat.", "why": "Amshir se termine vers le 9 mars."}], "tip": "Prends le dernier début de mois avant ta date."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1307.bilan_mois', 'eg', 'grammar', 'knowledge', 'Bilan : les treize mois', 3, array['eg.g1306.saisons_et_dates']::text[], 13, '{"rule": {"summary": "Les treize mois dans l''ordre : Tout, Baba, Hatour, Kiahk, Touba, Amshir, Baramhat, Baramouda, Bashans, Baouna, Abib, Misra, Nasie. Chacun commence vers le 10 d''un mois de notre calendrier.", "explanation": "Douze mois de 30 jours, puis Nasie, le petit mois de 5 jours. Les repères : Tout et le Nayrouz, Kiahk et Marie, Touba et le froid, Misra et la crue. Les proverbes sont des dictons de paysans, qui varient selon les villages.", "pattern": "Tout, Baba, Hatour, Kiahk, Touba, Amshir, Baramhat, Baramouda, Bashans, Baouna, Abib, Misra, Nasie.", "examples": [{"text": "Kiahk est le quatrième mois.", "translation": "Le mois marial."}, {"text": "Misra est le douzième mois.", "translation": "Nasie est le treizième."}, {"text": "Le 20 mars est dans Baramhat.", "translation": "Baramhat commence vers le 10 mars."}], "commonErrors": [{"wrong": "Misra est le dernier mois.", "right": "Nasie est le treizième.", "why": "Le petit mois ferme l''année."}, {"wrong": "Baramouda vient avant Baramhat.", "right": "Baramhat vient avant Baramouda.", "why": "D''abord le champ, puis le battage."}], "tip": "Six, puis sept : Tout…Amshir, Baramhat…Nasie."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1401.moise_le_noir', 'eg', 'grammar', 'knowledge', 'Moïse le Noir : personne n''est perdu', 1, '{}'::text[], 14, '{"rule": {"summary": "Moïse le Noir, ancien chef de brigands, devient moine à Scété et un père spirituel respecté.", "explanation": "D''origine nubienne, Moïse est esclave puis chef de voleurs. En fuite, il trouve refuge chez les moines de Scété, devient chrétien et moine, apprend à dominer sa violence et devient prêtre. Il est tué vers 405 par des Berbères, sans avoir voulu se battre.", "pattern": "Brigand → refuge à Scété → moine → père spirituel → mort vers 405.", "examples": [{"text": "Moïse arrive au jugement avec un sac de sable troué.", "translation": "Il montre qu''on ne juge pas son frère quand on a ses propres fautes."}], "commonErrors": [{"wrong": "Moïse le Noir est un martyr romain.", "right": "Moïse le Noir est un moine de Scété.", "why": "Il vit au désert d''Égypte ; ce sont des Berbères qui le tuent, vers 405."}], "tip": "Moïse le Noir : le sac de sable troué."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1402.jean_arsene', 'eg', 'grammar', 'knowledge', 'Jean le Petit et Arsène : deux leçons du désert', 1, '{}'::text[], 14, '{"rule": {"summary": "Jean le Petit apprend l''obéissance en arrosant un bâton sec ; Arsène quitte la cour pour le silence de Scété.", "explanation": "Jean le Petit (vers 339-405) vit à Scété. Son maître lui fait arroser un bâton sec pendant trois ans, jusqu''aux fruits. Arsène, précepteur des fils de l''empereur, quitte la cour vers 400 pour le silence de Scété.", "pattern": "Jean : obéir sans discuter → fruits. Arsène : cour → silence.", "examples": [{"text": "Mangez le fruit de l''obéissance.", "translation": "Le maître offre aux anciens les fruits du bâton arrosé."}], "commonErrors": [{"wrong": "Arsène arrose un bâton sec.", "right": "Jean le Petit arrose un bâton sec.", "why": "Arsène, lui, est le précepteur des fils de l''empereur."}], "tip": "Jean = bâton sec (obéissance). Arsène = cour de l''empereur (silence)."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1403.bishoy_princes', 'eg', 'grammar', 'knowledge', 'Bishoy et les princes : prière et hospitalité', 1, '{}'::text[], 14, '{"rule": {"summary": "Bishoy prie la nuit et accueille le Christ dans le pauvre ; Maxime et Domèce quittent un palais pour une cellule.", "explanation": "Bishoy (320-417) rejoint Scété auprès de Macaire. Pour ne pas s''endormir, il attache ses cheveux au plafond. Selon la tradition, il porte sur ses épaules un vieillard : c''était le Christ. Maxime et Domèce, deux princes romains selon le Synaxaire, deviennent moines auprès de Macaire ; le monastère de Baramous garde leur nom.", "pattern": "Bishoy : prière de la nuit + hospitalité. Maxime et Domèce : palais → cellule → Baramous.", "examples": [{"text": "Bishoy porte le vieillard sur ses épaules.", "translation": "Accueillir le pauvre, c''est accueillir le Christ."}], "commonErrors": [{"wrong": "Baramous veut dire « des moines ».", "right": "Baramous veut dire « des Romains ».", "why": "Le copte Pa-Romeos signifie « des Romains », en souvenir des deux princes."}], "tip": "Bishoy = cheveux au plafond. Baramous = « des Romains »."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1404.samuel', 'eg', 'grammar', 'knowledge', 'Samuel le Confesseur : souffrir sans mourir', 1, '{}'::text[], 14, '{"rule": {"summary": "Samuel refuse Chalcédoine, est battu et chassé de Scété, puis fonde le monastère de Qalamoun.", "explanation": "Samuel (vers 597-695) refuse d''accepter Chalcédoine. Selon sa Vie, le patriarche melkite le fait battre et chasser de Scété. Il fonde le monastère de Qalamoun, en Moyenne-Égypte. Il souffre sans mourir : on l''appelle confesseur.", "pattern": "Refus de Chalcédoine → battu et chassé → Qalamoun → confesseur.", "examples": [{"text": "Samuel est un confesseur, pas un martyr.", "translation": "Il a souffert pour sa foi, mais il n''est pas mort sous les coups."}], "commonErrors": [{"wrong": "Samuel est un martyr.", "right": "Samuel est un confesseur.", "why": "Un martyr meurt pour sa foi ; un confesseur souffre sans mourir."}], "tip": "Confesseur = souffrir sans mourir. Martyr = en mourir."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1405.mina', 'eg', 'grammar', 'knowledge', 'Mina : le soldat copte d''Abou Mina', 1, '{}'::text[], 14, '{"rule": {"summary": "Mina, soldat égyptien martyrisé vers 309, repose près du lac Maryût où naît le pèlerinage d''Abou Mina.", "explanation": "Mina naît vers 285 à Nikiou, quitte l''armée pour le désert, puis confesse sa foi. Il est martyrisé vers 309. Sur sa tombe naît Abou Mina, centre de pèlerinage du Ve au VIIe siècle, où l''on emporte des ampoules d''huile bénite.", "pattern": "Soldat → désert → martyre vers 309 → tombe au Maryût → Abou Mina → ampoules.", "examples": [{"text": "Les pèlerins repartent d''Abou Mina avec une ampoule d''huile bénite.", "translation": "L''ampoule porte l''image de Mina entre deux chameaux."}], "commonErrors": [{"wrong": "Mina est le saint aux deux épées.", "right": "Mina est le saint du chameau et des ampoules.", "why": "Les deux épées sont celles de Mercure, Abou Sefein."}], "tip": "Mina = le chameau + les ampoules."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1406.mercure_georges', 'eg', 'grammar', 'knowledge', 'Mercure et Georges : deux épées, un dragon', 1, '{}'::text[], 14, '{"rule": {"summary": "Mercure (Abou Sefein) reçoit une seconde épée d''un archange ; Georges, prince des martyrs, est peint perçant un dragon.", "explanation": "Les saints soldats refusent d''adorer l''empereur. Philopatir Mercure, officier sous Dèce, est décapité à Césarée vers 250 : selon la tradition, l''archange Michel lui remet une épée, d''où Abou Sefein, « père des deux épées ». Georges, martyr vers 303, est le prince des martyrs ; le dragon de son icône figure Satan vaincu.", "pattern": "Mercure = deux épées (Abou Sefein). Georges = dragon (prince des martyrs).", "examples": [{"text": "Au Vieux-Caire, une église porte le nom d''Abou Sefein.", "translation": "Beaucoup de Coptes y prient celui qu''ils appellent leur protecteur."}], "commonErrors": [{"wrong": "Georges est le père des deux épées.", "right": "Mercure est le père des deux épées.", "why": "Georges est le saint au dragon."}], "tip": "Deux épées : Mercure. Dragon : Georges."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1407.abanoub_demiana', 'eg', 'grammar', 'knowledge', 'Abanoub et Démiana : jeunes devant les puissants', 1, '{}'::text[], 14, '{"rule": {"summary": "Abanoub, douze ans, et Démiana avec quarante vierges, tiennent tête aux puissants sous Dioclétien.", "explanation": "Selon la tradition, Abanoub naît à Nehisa, dans le Delta, et refuse d''adorer les idoles devant le gouverneur à douze ans. Démiana, fille d''un gouverneur chrétien, vit en prière avec quarante jeunes filles. Elles sont décapitées sous Dioclétien.", "pattern": "Abanoub = l''enfant de douze ans. Démiana = les quarante vierges.", "examples": [{"text": "Le couvent de Démiana, près de Belqas, garde sa mémoire.", "translation": "Un lieu garde le souvenir des quarante compagnes."}], "commonErrors": [{"wrong": "Démiana est un enfant de douze ans.", "right": "Abanoub est l''enfant de douze ans.", "why": "Démiana est la fille du gouverneur, avec quarante compagnes."}], "tip": "Abanoub : douze ans. Démiana : quarante compagnes."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1408.catherine_barbara', 'eg', 'grammar', 'knowledge', 'Catherine et Barbara : lire un récit de saint', 1, '{}'::text[], 14, '{"rule": {"summary": "Catherine gagne un débat contre cinquante philosophes ; Barbara est enfermée dans une tour. Leurs vies relèvent de la tradition.", "explanation": "Les récits de martyrs ont souvent été écrits longtemps après les faits : c''est l''hagiographie. Selon la tradition, Catherine confond cinquante philosophes et la roue prévue pour la torturer se brise ; Barbara est enfermée dans une tour par son père. Les historiens discutent de ce qui est exact, l''Église garde leur exemple.", "pattern": "Catherine = débat + roue brisée. Barbara = tour + père frappé par la foudre.", "examples": [{"text": "Selon la tradition, la roue de Catherine se brise.", "translation": "Le Synaxaire dit « selon la tradition » : on retient le sens."}], "commonErrors": [{"wrong": "Catherine est la sainte de la tour.", "right": "Barbara est la sainte de la tour.", "why": "Catherine est la savante de la roue brisée."}], "tip": "Catherine = roue. Barbara = tour."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1409.marie_egyptienne', 'eg', 'grammar', 'knowledge', 'Marie l''Égyptienne : la repentance', 1, '{}'::text[], 14, '{"rule": {"summary": "Marie l''Égyptienne quitte une vie de péché, se repent devant l''icône de la Vierge et vit au désert ; le moine Zosime l''enterre avec l''aide d''un lion.", "explanation": "Marie quitte sa famille à douze ans et mène à Alexandrie une vie de péché. À Jérusalem, elle ne peut franchir la porte de l''église ; devant l''icône de la Vierge, elle pleure et promet de changer. Elle traverse le Jourdain et vit seule au désert. Sa Vie est écrite par Sophrone de Jérusalem.", "pattern": "Péché → porte fermée → icône de la Vierge → Jourdain → désert → Zosime et le lion.", "examples": [{"text": "Marie ne peut pas franchir la porte de l''église.", "translation": "Devant l''icône de la Vierge, elle décide de changer de vie."}], "commonErrors": [{"wrong": "Marie l''Égyptienne est une martyre.", "right": "Marie l''Égyptienne est une repentie du désert.", "why": "Elle ne meurt pas torturée : elle meurt au désert, après une longue pénitence."}], "tip": "Marie l''Égyptienne = la repentance. Zosime = le lion."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1410.marina_anastasie', 'eg', 'grammar', 'knowledge', 'Marina et Anastasie : l''humilité cachée', 1, '{}'::text[], 14, '{"rule": {"summary": "Marina vit en moine sous le nom de Marinos et se tait quand on l''accuse ; Anastasie fuit l''impératrice Théodora et vit en ermite à Scété.", "explanation": "Quelques saintes comme Marina et Anastasie ont vécu parmi les moines sous des habits d''homme ; les Synaxaires gardent ces récits. Marina est accusée à tort et élève l''enfant ; sa vérité éclate à sa mort. Anastasie, dame de la cour de Justinien, vit à Scété sous la conduite de l''abbé Daniel.", "pattern": "Marina : déguisée, accusée, silencieuse, innocente. Anastasie : cour, fuite, Scété.", "examples": [{"text": "À sa mort, on découvre que Marinos est une femme.", "translation": "Son innocence éclate enfin."}], "commonErrors": [{"wrong": "Marina est martyre sous Dioclétien.", "right": "Marina est une moniale déguisée en moine.", "why": "Elle n''est pas martyre : sa sainteté vient de son humilité."}], "tip": "Marina = Marinos accusé à tort. Anastasie = fuit Théodora."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1411.legion_verena', 'eg', 'grammar', 'knowledge', 'La légion thébaine et Verena : la foi voyage', 1, '{}'::text[], 14, '{"rule": {"summary": "Selon la tradition, une légion de soldats chrétiens de Thébaïde est massacrée à Agaune, en Suisse, vers 286 ; Verena soigne les pauvres près de Zurzach.", "explanation": "Selon la tradition, la légion thébaine refuse de sacrifier aux dieux et est massacrée à Agaune (Saint-Maurice), en Suisse. Les historiens discutent de ce récit. Verena, venue d''Égypte, soigne les malades près de Zurzach ; une partie de ses reliques arrive en Égypte en 1986.", "pattern": "Thébaïde → refus de sacrifier → Agaune → Verena à Zurzach → reliques en 1986.", "examples": [{"text": "Verena est représentée avec une cruche et un peigne.", "translation": "Ce sont ses outils de service aux malades."}], "commonErrors": [{"wrong": "La légion thébaine est massacrée à Alexandrie.", "right": "La légion thébaine est massacrée à Agaune, en Suisse.", "why": "Des Égyptiens meurent loin de chez eux, selon la tradition."}], "tip": "Légion thébaine = Agaune. Verena = cruche et peigne."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1412.abraam_simon', 'eg', 'grammar', 'knowledge', 'Abraam et Simon : la foi grosse comme un grain de moutarde', 1, '{}'::text[], 14, '{"rule": {"summary": "Selon la tradition, vers 975, le pape Abraam ibn Zaraa et Simon le Tanneur prient avec le peuple et la montagne du Mokattam se soulève.", "explanation": "Abraam ibn Zaraa, riche marchand d''origine syrienne devenu moine puis 62e pape, vit sous les Fatimides. Un ministre défie les chrétiens de déplacer une montagne (Mt 17, 20). Guidé par la Vierge, Abraam trouve Simon, un tanneur borgne. Selon la tradition, la montagne se soulève pendant la prière.", "pattern": "Défi du ministre → trois jours de prière → la Vierge envoie vers Simon → le Mokattam bouge.", "examples": [{"text": "Au pied du Mokattam, une église taillée dans le rocher porte le nom de Simon.", "translation": "Les Coptes y prient celui dont la foi, disent-ils, a sauvé leurs ancêtres."}], "commonErrors": [{"wrong": "Simon le Tanneur est le pape.", "right": "Abraam ibn Zaraa est le pape ; Simon est le tanneur.", "why": "Simon est un laïc humble, borgne, guidé par la Vierge."}], "tip": "Abraam = le pape marchand. Simon = le tanneur à la cruche."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1413.barsoum_abraam', 'eg', 'grammar', 'knowledge', 'Barsoum et Anba Abraam : se détacher de l''argent', 1, '{}'::text[], 14, '{"rule": {"summary": "Barsoum le Nu donne ses biens et ne garde qu''une peau de chèvre ; Anba Abraam, évêque du Fayoum, donne ses revenus aux pauvres.", "explanation": "Barsoum (1257-1317) vit en ermite au Vieux-Caire et prie pour des chrétiens emprisonnés. Anba Abraam (1829-1914), évêque du Fayoum et de Gizeh, donne ses revenus aux pauvres et est canonisé en 1964 : la canonisation est la reconnaissance d''un saint par le Saint-Synode.", "pattern": "Barsoum : peau de chèvre. Anba Abraam : évêque, ami des pauvres, canonisé 1964.", "examples": [{"text": "Anba Abraam est canonisé en 1964.", "translation": "Le Saint-Synode le reconnaît officiellement comme saint."}], "commonErrors": [{"wrong": "Anba Abraam est le pape de 975.", "right": "Abraam ibn Zaraa est le pape de 975 ; Anba Abraam est l''évêque du Fayoum.", "why": "Deux Abraam, deux siècles : ne les mélange pas."}], "tip": "Deux Abraam : le pape marchand (975) et l''évêque du Fayoum (1914)."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1414.cyrille_iv_habib', 'eg', 'grammar', 'knowledge', 'Cyrille IV et Habib Guirguis : réveiller l''Église', 1, '{}'::text[], 14, '{"rule": {"summary": "Au XIXe siècle, le pape Cyrille IV installe une imprimerie et des écoles ; le laïc Habib Guirguis fonde les écoles du dimanche.", "explanation": "Cyrille IV (110e pape, 1854-1861) est appelé le père de la réforme : imprimerie, écoles modernes, y compris pour les filles. Habib Guirguis (1876-1951), laïc et archidiacre, rassemble dès 1898 des enfants le dimanche ; l''Église adopte les écoles du dimanche en 1918. Il est proclamé saint en 2013.", "pattern": "Cyrille IV : le livre et l''école. Habib Guirguis : l''enseignement aux enfants.", "examples": [{"text": "Cyrille IV installe la première imprimerie non gouvernementale d''Égypte.", "translation": "Elle imprime d''abord des livres religieux."}], "commonErrors": [{"wrong": "Habib Guirguis est un évêque.", "right": "Habib Guirguis est un laïc, archidiacre.", "why": "Un laïc peut enseigner et être saint."}], "tip": "Cyrille IV = imprimerie. Habib Guirguis = école du dimanche."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1415.cyrille_vi_chenouda', 'eg', 'grammar', 'knowledge', 'Cyrille VI et Chenouda III : prière et enseignement', 1, '{}'::text[], 14, '{"rule": {"summary": "Cyrille VI, moine de prière, est le 116e pape et ramène les reliques de saint Marc en 1968 ; Chenouda III, le 117e, est le maître des générations.", "explanation": "Azer Youssef Atta naît en 1902, devient moine à Baramous sous le nom de père Mina, vit en ermite dans un moulin à vent, puis est élu pape en 1959 (Cyrille VI). Chenouda III, ancien professeur d''école du dimanche, est pape de 1971 à 2012 et donne une conférence chaque mercredi.", "pattern": "Cyrille VI : moulin, 1968, saint en 2013. Chenouda III : mercredi, exil 1981-1985.", "examples": [{"text": "En 1968, les reliques de saint Marc reviennent de Venise.", "translation": "C''est une immense fête pour tous les Coptes."}], "commonErrors": [{"wrong": "Cyrille IV a ramené les reliques de saint Marc.", "right": "Cyrille VI a ramené les reliques de saint Marc.", "why": "Cyrille IV (1861) est le pape de l''imprimerie."}], "tip": "Cyrille IV : l''imprimerie. Cyrille VI : le moulin et saint Marc."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1416.martyrs_libye', 'eg', 'grammar', 'knowledge', 'Les 21 martyrs de Libye : témoins aujourd''hui', 1, '{}'::text[], 14, '{"rule": {"summary": "Le 15 février 2015, vingt Coptes et un Ghanaïen sont tués près de Syrte pour avoir refusé de renier le Christ ; l''Église les compte parmi ses saints.", "explanation": "Vingt ouvriers coptes, dont treize d''Al-Our, et Matthieu, un Ghanaïen, sont tués sur une plage près de Syrte. Le pape Tawadros II les proclame saints peu après ; leurs reliques reposent à Al-Our depuis 2018. En 2023, le pape François les inscrit au Martyrologe romain.", "pattern": "Enlevés → refus de renier le Christ → tués le 15 février 2015 → saints au Synaxaire → Martyrologe romain en 2023.", "examples": [{"text": "Leur fête est le 15 février.", "translation": "L''Église copte et l''Église catholique les fêtent le même jour."}], "commonErrors": [{"wrong": "Les 21 martyrs sont tous coptes.", "right": "Vingt sont coptes, le 21e est un Ghanaïen, Matthieu.", "why": "Matthieu est compté parmi eux comme martyr."}], "tip": "21 = 20 Coptes + 1 Ghanaïen, Matthieu."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1417.bilan_saints', 'eg', 'grammar', 'knowledge', 'Bilan : les saints, qui a fait quoi', 1, '{}'::text[], 14, '{"rule": {"summary": "Chaque saint a une scène à retenir : on les replace dans le temps et on évite de les confondre.", "explanation": "Les saints viennent de cinq familles : les saints soldats, les Pères du désert, les jeunes martyrs et saintes, les saintes cachées, les réveilleurs modernes. Pour certains, les sources sont solides ; pour d''autres, c''est la tradition. Les reliques se vénèrent, le saint patron se prie.", "pattern": "Une scène par saint, un siècle par saint, une famille par saint.", "examples": [{"text": "Mercure : deux épées. Georges : dragon. Mina : chameau.", "translation": "Trois saints soldats, trois images."}], "commonErrors": [{"wrong": "Les reliques de saint se prient comme Dieu.", "right": "On vénère les reliques, on n''adore que Dieu.", "why": "La vénération n''est pas l''adoration."}], "tip": "Une scène, un siècle, une famille."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1501.langue_des_pharaons', 'eg', 'grammar', 'knowledge', 'Le copte, langue des pharaons écrite en lettres grecques', 1, '{}'::text[], 15, '{"rule": {"summary": "Le copte est la dernière étape de la langue des anciens Égyptiens, écrite avec l''alphabet grec plus six ou sept lettres venues du démotique. Le dialecte de la liturgie est le bohaïrique.", "explanation": "Les chrétiens d''Égypte ont écrit leur langue avec l''alphabet grec, qu''on connaissait à Alexandrie, et ont ajouté des lettres pour les sons qui n''existaient pas en grec. Ces lettres (ϣ ϥ ϧ ϩ ϫ ϭ, et ϯ qui note « ti ») signalent un mot d''origine égyptienne. Le sahidique (Sud) fut la langue écrite des premiers siècles ; le bohaïrique (Nord) est devenu celui de l''Église.", "pattern": "copte = égyptien + alphabet grec + ϣ ϥ ϧ ϩ ϫ ϭ (ϯ) ; liturgie = bohaïrique", "examples": [{"text": "ⲛⲟⲩϯ, ⲣⲁⲛ, ⲓⲱⲧ, ϣⲏⲣⲓ", "translation": "Dieu, nom, père, fils : des mots égyptiens très anciens."}], "commonErrors": [{"wrong": "Le copte est une langue venue de Grèce.", "right": "Le copte est de l''égyptien ancien écrit avec des lettres grecques.", "why": "L''alphabet est grec, mais la langue est celle des pharaons."}, {"wrong": "Le copte est de l''arabe ancien.", "right": "Le copte est bien plus ancien que l''arabe en Égypte.", "why": "L''arabe n''arrive qu''avec la conquête de 641 ; le copte descend de l''égyptien."}], "tip": "Lettre spéciale (ϣ ϥ ϧ ϩ ϫ ϭ) = mot égyptien."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1502.mots_grecs', 'eg', 'grammar', 'knowledge', 'Les mots grecs du copte', 1, array['eg.g1501.langue_des_pharaons']::text[], 15, '{"rule": {"summary": "Le copte a pris beaucoup de mots grecs, surtout religieux, que le français a souvent gardés : ange, évangile, église.", "explanation": "Alexandrie était une ville grecque et la Bible qu''on y lisait était la Septante. Les mots de la foi sont donc arrivés en grec dans le copte : ⲁⲅⲅⲉⲗⲟⲥ (messager), ⲉⲩⲁⲅⲅⲉⲗⲓⲟⲛ (bonne nouvelle), ⲉⲕⲕⲗⲏⲥⲓⲁ (assemblée), ⲡⲁⲣⲑⲉⲛⲟⲥ (vierge). Un mot sans lettre spéciale peut être grec, mais pas toujours : ⲓⲱⲧ est égyptien.", "pattern": "mot religieux sans lettre spéciale → souvent grec ; lettre spéciale → égyptien", "examples": [{"text": "ⲁⲅⲅⲉⲗⲟⲥ", "translation": "Un mot grec : « messager », notre ange."}, {"text": "ⲉⲩⲁⲅⲅⲉⲗⲓⲟⲛ", "translation": "Un mot grec : « bonne nouvelle », l''évangile."}, {"text": "ⲉⲕⲕⲗⲏⲥⲓⲁ", "translation": "Un mot grec : « l''assemblée », l''Église."}], "commonErrors": [{"wrong": "Tous les mots coptes sont égyptiens.", "right": "Beaucoup de mots religieux sont grecs.", "why": "Alexandrie était grecque et la Bible lue était la Septante."}, {"wrong": "Un mot sans lettre spéciale est forcément grec.", "right": "Il peut aussi être égyptien, comme ⲓⲱⲧ.", "why": "L''indice des lettres spéciales marche dans un seul sens."}], "tip": "Ange, évangile, église sont des mots grecs."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1503.jinkim', 'eg', 'grammar', 'reading', 'La jinkim, le trait de lecture', 1, array['eg.g1502.mots_grecs']::text[], 15, '{"rule": {"summary": "La jinkim est le petit trait placé sur certaines lettres : sur une consonne, elle forme une syllabe à elle seule (on ajoute un « e » devant) ; sur une voyelle, elle se lit à part.", "explanation": "La jinkim (ϫⲓⲛⲕⲓⲙ, « mouvement ») ne change pas le sens, elle guide la lecture. Sur une consonne comme ⲛ̀ ou ⲫ̀, il faut ajouter un petit « e » : ⲛ̀ⲧⲉ se lit « ente », Ⲫ̀ⲛⲟⲩϯ se lit « efnouti ». Sur une voyelle comme ⲉ̀ ou ⲁ̀, elle indique que la voyelle forme une nouvelle syllabe : ⲉ̀ⲃⲟⲗ se lit « evol ». Dans les mots grecs, elle apparaît souvent sur la première de deux consonnes de suite. Les livres l''écrivent plus ou moins : avec ou sans jinkim, c''est le même mot.", "pattern": "consonne + jinkim = « e » + consonne ; voyelle + jinkim = voyelle lue à part", "examples": [{"text": "ⲛ̀ⲧⲉ", "translation": "« ente » : de."}, {"text": "Ⲫ̀ⲛⲟⲩϯ", "translation": "« efnouti » : Dieu."}, {"text": "ⲉ̀ⲃⲟⲗ", "translation": "« evol » : dehors."}, {"text": "ϯⲧ̀ⲣⲓⲁⲥ", "translation": "La Trinité : le ⲧ̀ ajoute un petit « e » avant ⲣ."}], "commonErrors": [{"wrong": "La jinkim change le sens du mot.", "right": "Elle ne change que la lecture.", "why": "ⲛ̀ⲧⲉ et ⲛⲧⲉ sont le même mot."}, {"wrong": "La jinkim rend la lettre muette.", "right": "Elle ajoute un petit « e » à une consonne, ou détache une voyelle.", "why": "C''est un signe de lecture, pas de silence."}, {"wrong": "Si un livre n''a pas de jinkim, le mot est différent.", "right": "C''est le même mot, écrit autrement.", "why": "Selon les éditions, on la met plus ou moins."}], "tip": "Jinkim sur une consonne = petit « e » devant ; sur une voyelle = lue à part."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1504.nomina_sacra', 'eg', 'grammar', 'reading', 'Les abréviations surlignées (nomina sacra)', 2, array['eg.g1503.jinkim']::text[], 15, '{"rule": {"summary": "Une barre au-dessus de plusieurs lettres (la surligne) indique un nom sacré abrégé : ⲓ̅ⲏ̅ⲥ̅ pour Jésus, ⲭ̅ⲥ̅ pour le Christ, ⲡ̅ⲟ̅ⲥ̅ pour le Seigneur, ⲫ̅ϯ̅ pour Dieu.", "explanation": "Ces abréviations, les nomina sacra, existent déjà dans les manuscrits grecs du IIe siècle. On garde la première et la dernière lettre du mot (parfois une du milieu) et on trace une barre dessus. Elles ne se lisent pas lettre par lettre : on lit le mot entier. Ne confonds pas la surligne, qui couvre plusieurs lettres et abrège un mot, avec la jinkim, petit trait sur une seule lettre qui guide la lecture.", "pattern": "barre sur plusieurs lettres = nom sacré abrégé, à lire en entier", "examples": [{"text": "ⲓ̅ⲏ̅ⲥ̅", "translation": "Ⲓⲏⲥⲟⲩⲥ, Jésus."}, {"text": "ⲭ̅ⲥ̅", "translation": "Ⲡⲓⲭ̀ⲣⲓⲥⲧⲟⲥ, le Christ."}, {"text": "ⲡ̅ⲟ̅ⲥ̅", "translation": "Ⲡϭⲟⲓⲥ, le Seigneur."}, {"text": "ⲫ̅ϯ̅", "translation": "Ⲫ̀ⲛⲟⲩϯ, Dieu."}], "commonErrors": [{"wrong": "La barre sur ⲓ̅ⲏ̅ⲥ̅ est une jinkim.", "right": "C''est une surligne : elle abrège le nom.", "why": "La jinkim est sur une seule lettre ; la surligne couvre plusieurs lettres."}, {"wrong": "On lit ⲓ̅ⲏ̅ⲥ̅ lettre par lettre : i, è, s.", "right": "On lit le mot complet : Ⲓⲏⲥⲟⲩⲥ.", "why": "La barre dit qu''il manque des lettres."}, {"wrong": "On abrège tous les mots ainsi.", "right": "On abrège surtout les noms sacrés.", "why": "C''est une marque de respect pour Jésus, le Christ, le Seigneur et Dieu."}], "tip": "Barre sur plusieurs lettres = mot sacré abrégé ; lis le mot entier."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1505.articles', 'eg', 'grammar', 'grammar', 'Les articles collés au nom', 2, array['eg.g1504.nomina_sacra']::text[], 15, '{"rule": {"summary": "En copte, l''article est collé au nom : ⲡⲓ (le), ϯ (la), ⲛⲓ (les), ⲟⲩ (un, une), ϩⲁⲛ (des). Devant quelques mots courants il prend la forme ⲫ̀ (Ⲫ̀ⲛⲟⲩϯ, Ⲫ̀ⲓⲱⲧ, ⲫ̀ⲣⲁⲛ).", "explanation": "Le premier réflexe pour comprendre un mot copte est de détacher l''article. Le défini a trois formes : ⲡⲓ (masculin), ϯ (féminin), ⲛⲓ (pluriel). L''indéfini est ⲟⲩ (un, une) et ϩⲁⲛ (des). L''article indique le genre : ϯⲡⲁⲣⲑⲉⲛⲟⲥ est féminin. Devant certains mots l''article est raccourci ou devient ⲫ̀ (Ⲫ̀ⲛⲟⲩϯ, Ⲫ̀ⲓⲱⲧ, ⲫ̀ⲣⲁⲛ) : ce sont des mots très fréquents à apprendre tels quels.", "pattern": "article + nom : ⲡⲓ / ϯ / ⲛⲓ (le, la, les) ; ⲟⲩ / ϩⲁⲛ (un, des) ; ⲫ̀ devant quelques mots", "examples": [{"text": "ⲡⲓⲁⲅⲅⲉⲗⲟⲥ", "translation": "L''ange."}, {"text": "ϯⲉⲕⲕⲗⲏⲥⲓⲁ", "translation": "L''Église."}, {"text": "ⲛⲓⲁⲅⲅⲉⲗⲟⲥ", "translation": "Les anges."}, {"text": "Ⲫ̀ⲛⲟⲩϯ", "translation": "Dieu (ⲫ̀ + ⲛⲟⲩϯ)."}], "commonErrors": [{"wrong": "Ⲫ̀ⲛⲟⲩϯ est un seul mot qui n''a rien à voir avec ⲛⲟⲩϯ.", "right": "Ⲫ̀ⲛⲟⲩϯ = ⲫ̀ (le) + ⲛⲟⲩϯ (dieu).", "why": "Le ⲫ̀ est un article collé au nom."}, {"wrong": "ϯⲡⲁⲣⲑⲉⲛⲟⲥ est masculin parce que le mot finit comme ⲁⲅⲅⲉⲗⲟⲥ.", "right": "Il est féminin : c''est ϯ qui le montre.", "why": "Le genre se lit sur l''article, pas sur la terminaison."}, {"wrong": "ϩⲁⲛ veut dire « les ».", "right": "ϩⲁⲛ veut dire « des » ; « les » se dit ⲛⲓ.", "why": "Défini : ⲛⲓ ; indéfini : ϩⲁⲛ."}], "tip": "Détache l''article, puis cherche le nom."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1506.possessifs', 'eg', 'grammar', 'grammar', 'Les possessifs ⲡⲁ-, ⲡⲉⲕ-, ⲡⲉϥ-, ⲡⲉⲛ-', 2, array['eg.g1505.articles']::text[], 15, '{"rule": {"summary": "Le possessif se colle au nom et remplace l''article : ⲡⲁ- (mon), ⲡⲉⲕ- (ton), ⲡⲉϥ- (son), ⲡⲉⲛ- (notre), ⲡⲉⲧⲉⲛ- (votre), ⲡⲟⲩ- (leur), avec ⲡ- au masculin, ⲧ- au féminin et ⲛ- au pluriel.", "explanation": "Le possessif est un préfixe qui prend la place de l''article : ⲡⲁⲛⲟⲩϯ (mon Dieu), pas ⲡⲁⲫ̀ⲛⲟⲩϯ. Il est formé du ⲡ de l''article suivi de la personne : ϥ (lui), ⲥ (elle), ⲕ (toi), ⲛ (nous), ⲧⲉⲛ (vous), ⲟⲩ (eux). Sa première lettre s''accorde avec ce qui est possédé : ⲡ- pour un nom masculin, ⲧ- pour un féminin, ⲛ- pour un pluriel. À l''église tu entends surtout Ⲡⲉⲛ- : Ⲡⲉⲛⲓⲱⲧ (notre Père), Ⲡⲉⲛϭⲟⲓⲥ (notre Seigneur).", "pattern": "ⲡⲁ- / ⲡⲉⲕ- / ⲡⲉϥ- / ⲡⲉⲛ- / ⲡⲉⲧⲉⲛ- / ⲡⲟⲩ- + nom (ⲧ- féminin, ⲛ- pluriel)", "examples": [{"text": "ⲡⲁⲛⲟⲩϯ", "translation": "Mon Dieu."}, {"text": "ⲡⲉⲕⲣⲁⲛ", "translation": "Ton nom."}, {"text": "Ⲡⲉⲛⲓⲱⲧ", "translation": "Notre Père."}, {"text": "Ⲡⲉⲛϭⲟⲓⲥ", "translation": "Notre Seigneur."}], "commonErrors": [{"wrong": "ⲡⲉⲛ- veut dire « votre ».", "right": "ⲡⲉⲛ- veut dire « notre » ; « votre » se dit ⲡⲉⲧⲉⲛ-.", "why": "ⲡⲉⲛ- garde le ⲛ de « nous »."}, {"wrong": "On dit ⲡⲁⲫ̀ⲛⲟⲩϯ pour « mon Dieu ».", "right": "On dit ⲡⲁⲛⲟⲩϯ.", "why": "Le possessif remplace l''article : plus de ⲫ̀."}, {"wrong": "ⲧⲁ- s''emploie quand le propriétaire est une femme.", "right": "ⲧⲁ- s''emploie quand la chose possédée est féminine.", "why": "Le possessif s''accorde avec le nom possédé."}], "tip": "Ⲡⲉⲛ- = notre ; le ⲡ/ⲧ/ⲛ du début donne le genre de la chose possédée."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1507.petits_mots', 'eg', 'grammar', 'vocabulary', 'Les petits mots de la phrase', 3, array['eg.g1506.possessifs']::text[], 15, '{"rule": {"summary": "Quatre petits mots font la structure des phrases : ⲛⲉⲙ (et), ϧⲉⲛ (dans), ⲛ̀/ⲙ̀ (de) et ⲉⲑⲟⲩⲁⲃ (saint, après le nom).", "explanation": "Ces mots sont courts et fréquents : les reconnaître suffit pour comprendre une phrase comme ϧⲉⲛ ⲫ̀ⲣⲁⲛ ⲙ̀Ⲫ̀ⲓⲱⲧ. ⲛⲉⲙ relie des noms. ϧⲉⲛ donne le lieu. Le « de » s''écrit ⲛ̀ mais devient ⲙ̀ devant ⲡ, ⲫ, ⲃ, ⲙ. L''adjectif ⲉⲑⲟⲩⲁⲃ se place après le nom.", "pattern": "nom + ⲛⲉⲙ + nom ; ϧⲉⲛ + lieu ; ⲛ̀/ⲙ̀ + nom ; nom + ⲉⲑⲟⲩⲁⲃ", "examples": [{"text": "Ⲫ̀ⲓⲱⲧ ⲛⲉⲙ Ⲡ̀ϣⲏⲣⲓ", "translation": "Le Père et le Fils."}, {"text": "ϧⲉⲛ ϯⲉⲕⲕⲗⲏⲥⲓⲁ", "translation": "Dans l''Église."}, {"text": "ⲫ̀ⲣⲁⲛ ⲙ̀Ⲫ̀ⲓⲱⲧ", "translation": "Le nom du Père."}, {"text": "ϯⲉⲕⲕⲗⲏⲥⲓⲁ ⲉⲑⲟⲩⲁⲃ", "translation": "L''Église sainte."}], "commonErrors": [{"wrong": "ⲉⲑⲟⲩⲁⲃ se place avant le nom, comme en anglais.", "right": "Il se place après le nom, comme en français.", "why": "ϯⲉⲕⲕⲗⲏⲥⲓⲁ ⲉⲑⲟⲩⲁⲃ : l''Église sainte."}, {"wrong": "ⲙ̀ et ⲛ̀ sont deux mots différents.", "right": "C''est le même mot « de », qui devient ⲙ̀ devant ⲡ, ⲫ, ⲃ, ⲙ.", "why": "Comme « en » devient « em » devant p ou b."}], "tip": "ⲛⲉⲙ = et ; ϧⲉⲛ = dans ; ⲛ̀/ⲙ̀ = de ; ⲉⲑⲟⲩⲁⲃ = saint après le nom."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1508.passe_paques', 'eg', 'grammar', 'verbs', 'Le passé des verbes : ⲁϥ-, ⲁⲥ-, ⲁⲩ-', 3, array['eg.g1507.petits_mots']::text[], 15, '{"rule": {"summary": "Le passé se forme avec ⲁ + la personne : ⲁϥ- (il a), ⲁⲥ- (elle a), ⲁⲩ- (ils ont). Ainsi ⲁϥⲧⲱⲛϥ se lit ⲁ + ϥ + ⲧⲱⲛ + ϥ : il s''est levé, il est ressuscité.", "explanation": "Le verbe copte ne change pas sa fin : on ajoute des petits morceaux devant. ⲁ marque le passé et se combine avec la personne : ⲁϥ (il), ⲁⲥ (elle), ⲁⲩ (ils). Ainsi ⲁϥⲧⲱⲛϥ se lit ⲁ + ϥ + ⲧⲱⲛ + ϥ : il s''est levé, il est ressuscité. Les marques ϥ, ⲥ, ⲟⲩ sont les mêmes que pour « son », « sa », « leur » dans les noms.", "pattern": "ⲁ + personne + verbe (passé)", "examples": [{"text": "ⲁϥⲧⲱⲛϥ", "translation": "Il est ressuscité."}, {"text": "ⲁ̀ⲗⲏⲑⲱⲥ ⲁϥⲧⲱⲛϥ", "translation": "Vraiment, il est ressuscité."}], "commonErrors": [{"wrong": "ⲁϥ- veut dire « il va » (futur).", "right": "ⲁϥ- marque le passé : « il a ».", "why": "Le ⲁ est la marque du passé."}, {"wrong": "Le second ϥ de ⲁϥⲧⲱⲛϥ est une faute de frappe.", "right": "C''est le « se » : il s''est levé.", "why": "Le premier ϥ est le sujet, le second ϥ revient sur lui."}], "tip": "ⲁ = passé ; ϥ = il."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1509.je_crois_benis', 'eg', 'grammar', 'verbs', 'Les verbes : je, et l''ordre', 3, array['eg.g1508.passe_paques']::text[], 15, '{"rule": {"summary": "Devant un verbe, ϯ- veut dire « je » ; l''ordre se donne avec le verbe seul (ⲥⲙⲟⲩ, bénis !).", "explanation": "ϯ- est « je » au présent : ϯⲛⲁϩϯ, je crois. Les premiers mots du Credo copte sont Ϯⲛⲁϩϯ ϧⲉⲛ ⲟⲩⲛⲟⲩϯ : « je crois en un Dieu ». L''ordre se donne avec le verbe seul : ⲥⲙⲟⲩ. Devant un nom, ϯ est l''article « la » ; devant un verbe, c''est « je ».", "pattern": "ϯ + verbe (je) ; verbe seul (ordre)", "examples": [{"text": "ϯⲛⲁϩϯ", "translation": "Je crois."}, {"text": "Ϯⲛⲁϩϯ ϧⲉⲛ ⲟⲩⲛⲟⲩϯ", "translation": "Je crois en un Dieu."}, {"text": "ⲥⲙⲟⲩ", "translation": "Bénis !"}], "commonErrors": [{"wrong": "ϯ- est toujours l''article « la ».", "right": "Devant un verbe, ϯ- veut dire « je ».", "why": "ϯⲛⲁϩϯ = je crois, alors que ϯⲉⲕⲕⲗⲏⲥⲓⲁ = l''Église."}], "tip": "ϯ devant un verbe = je ; verbe seul = ordre."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1510.formule_trinite', 'eg', 'grammar', 'vocabulary', 'Les noms de Dieu et la formule de la Trinité', 3, array['eg.g1509.je_crois_benis']::text[], 15, '{"rule": {"summary": "Les noms de Dieu se décomposent : Ⲫ̀ⲓⲱⲧ (ⲫ̀ + père), Ⲡ̀ϣⲏⲣⲓ (ⲡ̀ + fils), Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ ⲉⲑⲟⲩⲁⲃ (ⲡⲓ + esprit + saint). La formule du signe de croix se lit mot à mot.", "explanation": "Avec l''article et les petits mots, tu peux lire la formule ϧⲉⲛ ⲫ̀ⲣⲁⲛ ⲙ̀Ⲫ̀ⲓⲱⲧ ⲛⲉⲙ Ⲡ̀ϣⲏⲣⲓ ⲛⲉⲙ Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ ⲉⲑⲟⲩⲁⲃ : dans (ϧⲉⲛ) le nom (ⲫ̀ⲣⲁⲛ) du (ⲙ̀) Père (Ⲫ̀ⲓⲱⲧ) et (ⲛⲉⲙ) du Fils (Ⲡ̀ϣⲏⲣⲓ) et (ⲛⲉⲙ) de l''Esprit (Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ) saint (ⲉⲑⲟⲩⲁⲃ). Le mot « nom » est au singulier : un seul nom, trois personnes. Père, Fils sont égyptiens ; Esprit est grec.", "pattern": "ϧⲉⲛ + ⲫ̀ⲣⲁⲛ + ⲙ̀Ⲫ̀ⲓⲱⲧ + ⲛⲉⲙ + Ⲡ̀ϣⲏⲣⲓ + ⲛⲉⲙ + Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ + ⲉⲑⲟⲩⲁⲃ", "examples": [{"text": "Ⲫ̀ⲓⲱⲧ", "translation": "Le Père (ⲫ̀ + ⲓⲱⲧ)."}, {"text": "Ⲡ̀ϣⲏⲣⲓ", "translation": "Le Fils (ⲡ̀ + ϣⲏⲣⲓ)."}, {"text": "Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ ⲉⲑⲟⲩⲁⲃ", "translation": "Le Saint-Esprit."}], "commonErrors": [{"wrong": "Dans la formule, ⲫ̀ⲣⲁⲛ est au pluriel : trois noms.", "right": "ⲫ̀ⲣⲁⲛ est au singulier : un seul nom.", "why": "Un seul nom pour trois personnes."}, {"wrong": "ⲉⲑⲟⲩⲁⲃ se rapporte au Fils seulement.", "right": "ⲉⲑⲟⲩⲁⲃ (saint) qualifie l''Esprit, placé juste avant.", "why": "L''adjectif suit son nom : Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ ⲉⲑⲟⲩⲁⲃ."}, {"wrong": "Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ est un mot égyptien.", "right": "C''est un mot grec (pneuma).", "why": "Les mots égyptiens ont souvent ϣ, ϧ, ϩ ; pneuma est un mot grec comme ange."}], "tip": "Un seul nom (ⲫ̀ⲣⲁⲛ), trois personnes : Père, Fils, Esprit."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1511.titres_de_dieu', 'eg', 'grammar', 'vocabulary', 'Les titres de Dieu', 3, array['eg.g1510.formule_trinite']::text[], 15, '{"rule": {"summary": "Les titres de Dieu se décomposent : ϯⲧ̀ⲣⲓⲁⲥ (la Trinité, grec « triade »), ⲟⲩⲣⲟ (roi, égyptien), Ⲡⲓⲡⲁⲛⲧⲟⲕⲣⲁⲧⲱⲣ (le Tout-Puissant, grec) et ⲥⲱⲧⲏⲣ (sauveur, grec).", "explanation": "ϯⲧ̀ⲣⲓⲁⲥ est ϯ (la) + trias, « groupe de trois » ; ⲉⲑⲟⲩⲁⲃ lui donne la sainte Trinité. ⲟⲩⲣⲟ est le titre du pharaon et du Christ ; avec l''article, ⲡⲓⲟⲩⲣⲟ. Ⲡⲓⲡⲁⲛⲧⲟⲕⲣⲁⲧⲱⲣ est formé de pan (tout) et krátos (puissance). ⲥⲱⲧⲏⲣ est « celui qui sauve » : Ⲡⲉⲛⲥⲱⲧⲏⲣ, notre Sauveur.", "pattern": "ϯ + ⲧ̀ⲣⲓⲁⲥ ; ⲡⲓ + ⲟⲩⲣⲟ ; pan + krátos ; ⲡⲉⲛ- + ⲥⲱⲧⲏⲣ", "examples": [{"text": "ϯⲧ̀ⲣⲓⲁⲥ", "translation": "La Trinité."}, {"text": "ⲡⲓⲟⲩⲣⲟ", "translation": "Le roi."}, {"text": "Ⲡⲓⲡⲁⲛⲧⲟⲕⲣⲁⲧⲱⲣ", "translation": "Le Tout-Puissant."}, {"text": "Ⲡⲉⲛⲥⲱⲧⲏⲣ", "translation": "Notre Sauveur."}], "commonErrors": [{"wrong": "ϯⲧ̀ⲣⲓⲁⲥ est un mot égyptien.", "right": "C''est un mot grec (trias).", "why": "Les mots égyptiens ont souvent ϣ, ϧ, ϩ ; trias est grec comme ange."}, {"wrong": "Tous ces titres sont grecs.", "right": "ⲟⲩⲣⲟ, le roi, est égyptien.", "why": "Le copte mêle les deux langues pour nommer Dieu."}], "tip": "Pan (tout) + krátos (puissance) = Tout-Puissant ; ⲥⲱⲧⲏⲣ = celui qui sauve."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1512.vierge_marie', 'eg', 'grammar', 'vocabulary', 'La Vierge Marie et la Théotokos', 3, array['eg.g1511.titres_de_dieu']::text[], 15, '{"rule": {"summary": "Les titres de la Vierge sont grecs et se décomposent avec l''article : ϯⲡⲁⲣⲑⲉⲛⲟⲥ (la Vierge), ϯⲑⲉⲟⲧⲟⲕⲟⲥ (la mère de Dieu), et le salut ⲭⲉⲣⲉ (réjouis-toi).", "explanation": "ϯⲑⲉⲟⲧⲟⲕⲟⲥ se découpe en ϯ + ⲑⲉⲟⲥ (Dieu) + ⲧⲟⲕⲟⲥ (enfantement) : la mère de Dieu, le titre proclamé à Éphèse en 431, que Nestorius refusait. ⲭⲉⲣⲉ est le salut grec « réjouis-toi » de l''ange Gabriel à Marie : ⲭⲉⲣⲉ ⲛⲉ ⲱ̀ Ⲙⲁⲣⲓⲁ, salut à toi, ô Marie. ⲉⲑⲟⲩⲁⲃ se place après le nom : ϯⲑⲉⲟⲧⲟⲕⲟⲥ ⲉⲑⲟⲩⲁⲃ.", "pattern": "ϯ + ⲑⲉⲟⲥ (Dieu) + ⲧⲟⲕⲟⲥ (enfantement) ; ⲭⲉⲣⲉ ⲛⲉ ⲱ̀ Ⲙⲁⲣⲓⲁ", "examples": [{"text": "ϯⲑⲉⲟⲧⲟⲕⲟⲥ", "translation": "La mère de Dieu (ⲑⲉⲟⲥ + ⲧⲟⲕⲟⲥ)."}, {"text": "ⲭⲉⲣⲉ ⲛⲉ ⲱ̀ Ⲙⲁⲣⲓⲁ", "translation": "Salut à toi, ô Marie."}, {"text": "ϯⲡⲁⲣⲑⲉⲛⲟⲥ Ⲙⲁⲣⲓⲁ", "translation": "La Vierge Marie."}], "commonErrors": [{"wrong": "ϯⲑⲉⲟⲧⲟⲕⲟⲥ veut dire « la servante de Dieu ».", "right": "ϯⲑⲉⲟⲧⲟⲕⲟⲥ veut dire « la mère de Dieu ».", "why": "ⲧⲟⲕⲟⲥ est l''enfantement : celle qui enfante Dieu."}, {"wrong": "En grec et en copte, le titre est différent.", "right": "C''est le même mot : ϯⲑⲉⲟⲧⲟⲕⲟⲥ.", "why": "Le copte garde le mot grec tel quel."}], "tip": "ϯⲑⲉⲟⲧⲟⲕⲟⲥ = ⲑⲉⲟⲥ (Dieu) + ⲧⲟⲕⲟⲥ (enfantement)."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1513.saints_intercession', 'eg', 'grammar', 'vocabulary', 'Les saints et l''intercession', 3, array['eg.g1512.vierge_marie']::text[], 15, '{"rule": {"summary": "Les titres des saints sont presque tous grecs (ⲁ̀ⲡⲟⲥⲧⲟⲗⲟⲥ, ⲙⲁⲣⲧⲩⲣⲟⲥ, ⲁ̀ⲅⲓⲟⲥ, ⲡ̀ⲣⲉⲥⲃⲓⲁ) et se décomposent avec l''article et les petits mots déjà appris.", "explanation": "ⲁ̀ⲡⲟⲥⲧⲟⲗⲟⲥ veut dire « envoyé », ⲙⲁⲣⲧⲩⲣⲟⲥ « témoin », ⲁ̀ⲅⲓⲟⲥ « saint » (alors que ⲉⲑⲟⲩⲁⲃ est le « saint » copte), ⲡ̀ⲣⲉⲥⲃⲓⲁ « intercession ». Avec ϩⲓⲧⲉⲛ (par), ⲛ̀ⲧⲉ (de) et ⲉⲑⲟⲩⲁⲃ, la formule ϩⲓⲧⲉⲛ ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ ⲛ̀ⲧⲉ ϯⲑⲉⲟⲧⲟⲕⲟⲥ ⲉⲑⲟⲩⲁⲃ Ⲙⲁⲣⲓⲁ se lit : par les intercessions de la sainte mère de Dieu, Marie.", "pattern": "ϩⲓⲧⲉⲛ + ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ + ⲛ̀ⲧⲉ + ϯⲑⲉⲟⲧⲟⲕⲟⲥ + ⲉⲑⲟⲩⲁⲃ + Ⲙⲁⲣⲓⲁ", "examples": [{"text": "ⲛⲓⲁ̀ⲡⲟⲥⲧⲟⲗⲟⲥ", "translation": "Les apôtres, les envoyés."}, {"text": "ⲛⲓⲙⲁⲣⲧⲩⲣⲟⲥ", "translation": "Les martyrs, les témoins."}, {"text": "ϩⲓⲧⲉⲛ ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ", "translation": "Par les intercessions."}], "commonErrors": [{"wrong": "ⲁ̀ⲅⲓⲟⲥ et ⲉⲑⲟⲩⲁⲃ n''ont rien à voir.", "right": "Les deux veulent dire « saint » : l''un est grec, l''autre copte.", "why": "Le copte emprunte souvent un mot grec à côté de son mot égyptien."}, {"wrong": "ⲛⲓⲙⲁⲣⲧⲩⲣⲟⲥ veut dire « les rois ».", "right": "ⲛⲓⲙⲁⲣⲧⲩⲣⲟⲥ veut dire « les martyrs » (les témoins).", "why": "ⲛⲓ est l''article « les » ; ⲙⲁⲣⲧⲩⲣⲟⲥ est « témoin »."}], "tip": "ϩⲓⲧⲉⲛ ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ = par les intercessions."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1514.amen_paix', 'eg', 'grammar', 'vocabulary', 'Les réponses de la messe : amen, alléluia, paix', 3, array['eg.g1513.saints_intercession']::text[], 15, '{"rule": {"summary": "Les réponses de la messe sont dans trois langues : l''hébreu (ⲁ̀ⲙⲏⲛ, ⲁ̀ⲗⲗⲏⲗⲟⲩⲓⲁ), le grec (ⲓ̀ⲣⲏⲛⲏ) et le copte (ϣⲁ ⲉ̀ⲛⲉϩ).", "explanation": "Plus besoin de tout traduire : chaque réponse se décompose en deux ou trois mots simples. ⲁ̀ⲙⲏⲛ (c''est vrai) et ⲁ̀ⲗⲗⲏⲗⲟⲩⲓⲁ (louez Dieu) viennent de l''hébreu. Ⲓ̀ⲣⲏⲛⲏ ⲡⲁⲥⲓ, « la paix à tous », est du grec. ϣⲁ ⲉ̀ⲛⲉϩ, « pour toujours », est égyptien : le ϣ et le ϩ le trahissent.", "pattern": "hébreu : ⲁ̀ⲙⲏⲛ, ⲁ̀ⲗⲗⲏⲗⲟⲩⲓⲁ ; grec : ⲓ̀ⲣⲏⲛⲏ ; copte : ϣⲁ ⲉ̀ⲛⲉϩ", "examples": [{"text": "ⲁ̀ⲙⲏⲛ ⲁ̀ⲗⲗⲏⲗⲟⲩⲓⲁ", "translation": "Amen, alléluia (hébreu)."}, {"text": "Ⲓ̀ⲣⲏⲛⲏ ⲡⲁⲥⲓ", "translation": "La paix à tous (grec)."}, {"text": "ϣⲁ ⲉ̀ⲛⲉϩ", "translation": "Pour toujours (copte)."}], "commonErrors": [{"wrong": "ⲁ̀ⲙⲏⲛ est un mot grec.", "right": "ⲁ̀ⲙⲏⲛ est un mot hébreu, passé par le grec.", "why": "Comme ⲁ̀ⲗⲗⲏⲗⲟⲩⲓⲁ, il vient de la Bible hébraïque."}], "tip": "Amen et alléluia sont hébreux ; ⲓ̀ⲣⲏⲛⲏ est grec ; ϣⲁ ⲉ̀ⲛⲉϩ est copte."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1515.pitie_gloire', 'eg', 'grammar', 'vocabulary', 'Pitié et gloire en grec et en copte', 3, array['eg.g1514.amen_paix']::text[], 15, '{"rule": {"summary": "Le grec et le copte disent la même chose de deux façons : Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ ou ⲛⲁⲓ ⲛⲁⲛ pour la pitié, Ⲇⲟⲝⲁ ⲥⲓ Ⲕⲩⲣⲓⲉ ou ⲡⲓⲱⲟⲩ pour la gloire.", "explanation": "Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ = Seigneur + aie pitié. Ⲇⲟⲝⲁ ⲥⲓ Ⲕⲩⲣⲓⲉ = gloire + à toi + Seigneur. Le copte dit la même chose avec ⲛⲁⲓ ⲛⲁⲛ (pitié à nous, où ⲛⲁⲛ contient le ⲛ de « nous ») et ⲡⲓⲱⲟⲩ (la gloire).", "pattern": "Ⲕⲩⲣⲓⲉ + ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ ; ⲇⲟⲝⲁ + ⲥⲓ + ⲕⲩⲣⲓⲉ ; ⲛⲁⲓ + ⲛⲁⲛ ; ⲡⲓ + ⲱⲟⲩ", "examples": [{"text": "Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ", "translation": "Seigneur, aie pitié (grec)."}, {"text": "ⲛⲁⲓ ⲛⲁⲛ", "translation": "Aie pitié de nous (copte)."}, {"text": "Ⲇⲟⲝⲁ ⲥⲓ Ⲕⲩⲣⲓⲉ", "translation": "Gloire à toi, Seigneur (grec)."}], "commonErrors": [{"wrong": "Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ est du copte.", "right": "C''est du grec, avec une version copte : ⲛⲁⲓ ⲛⲁⲛ.", "why": "Le copte garde des mots grecs dans sa liturgie."}, {"wrong": "ⲡⲓⲱⲟⲩ et ⲇⲟⲝⲁ sont deux mots différents.", "right": "Ils veulent tous deux dire « gloire » : l''un est copte, l''autre grec.", "why": "Le copte a souvent deux mots pour une même idée."}], "tip": "Décompose : Ⲕⲩⲣⲓⲉ + ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ = Seigneur + aie pitié."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1516.copte_dans_arabe', 'eg', 'grammar', 'knowledge', 'Le copte caché dans l''arabe d''Égypte', 3, array['eg.g1515.pitie_gloire']::text[], 15, '{"rule": {"summary": "L''arabe d''Égypte garde des mots coptes : طوب (la brique), واحة (l''oasis), تمساح (le crocodile), الفيوم (le lac).", "explanation": "Le copte n''a pas disparu : il a donné à l''arabe d''Égypte des mots de la vie quotidienne (la brique, l''oasis, le crocodile) et des noms de lieux (le Fayoum, « le lac »). Les mois portent aussi leurs noms coptes. Attention aux faux jumeaux : طوب (la brique) vient de ⲧⲱⲃⲉ, طوبة (le mois) vient de ⲧⲱⲃⲓ.", "pattern": "arabe d''Égypte ← copte ← égyptien ancien", "examples": [{"text": "طوب ← ⲧⲱⲃⲉ", "translation": "La brique."}, {"text": "تمساح ← ⲉⲙⲥⲁϩ", "translation": "Le crocodile."}, {"text": "الفيوم ← ⲫⲓⲟⲙ", "translation": "Le lac (ⲫ = l''article)."}], "commonErrors": [{"wrong": "طوب et طوبة sont le même mot.", "right": "طوب (la brique) vient de ⲧⲱⲃⲉ ; طوبة (le mois) vient de ⲧⲱⲃⲓ.", "why": "Même son, deux mots différents."}, {"wrong": "Le copte est mort sans laisser de trace.", "right": "Il survit dans l''arabe d''Égypte et dans les noms.", "why": "Mots du quotidien, noms de lieux, prénoms, mois."}], "tip": "Cherche le mot copte derrière le son arabe."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1517.prenoms_coptes', 'eg', 'grammar', 'knowledge', 'Les prénoms coptes', 3, array['eg.g1516.copte_dans_arabe']::text[], 15, '{"rule": {"summary": "Beaucoup de prénoms coptes se décomposent avec les mots appris : ⲛⲟⲩϯ, ⲁⲃⲁ, ⲡⲓ, ⲑⲉⲟ.", "explanation": "Les prénoms se lisent comme des mots : Shenouda contient ⲛⲟⲩϯ (dieu), Anba est ⲁⲃⲁ (père), Bishoy est ⲡⲓ (le) + ϣⲱⲓ (haut), Tawadros est ⲑⲉⲟ (Dieu) + ⲇⲱⲣⲟⲥ (don). Ces sens sont ceux que donne la tradition copte. Certains prénoms sont égyptiens, d''autres grecs, comme Boutros (Ⲡⲉⲧⲣⲟⲥ, « pierre »).", "pattern": "prénom = mot(s) copte(s) ou grec(s) : ⲁⲃⲁ, ⲛⲟⲩϯ, ⲡⲓ + ϣⲱⲓ, ⲑⲉⲟ + ⲇⲱⲣⲟⲥ", "examples": [{"text": "أنبا ← ⲁⲃⲁ", "translation": "Père."}, {"text": "شنودة ← Ϣⲉⲛⲟⲩϯ", "translation": "Enfant de Dieu."}, {"text": "بيشوي ← Ⲡⲓϣⲱⲓ", "translation": "Le haut."}, {"text": "تاوضروس ← ⲑⲉⲟⲇⲱⲣⲟⲥ", "translation": "Don de Dieu."}], "commonErrors": [{"wrong": "Tous les prénoms coptes sont égyptiens.", "right": "Beaucoup sont grecs (Tawadros, Boutros).", "why": "Le grec était très présent dans l''Église d''Alexandrie."}], "tip": "Cherche le mot que tu connais derrière le prénom : ⲛⲟⲩϯ dans Shenouda, ⲁⲃⲁ dans Anba."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g1518.bilan_copte', 'eg', 'grammar', 'sentence_building', 'Bilan : décortiquer une formule copte', 4, array['eg.g1517.prenoms_coptes']::text[], 15, '{"rule": {"summary": "Pour comprendre une formule copte, on la découpe : article ou possessif, nom (égyptien, grec ou hébreu), verbe avec sa marque, et petits mots (ϧⲉⲛ, ⲛⲉⲙ, ⲛ̀, ϩⲓⲧⲉⲛ).", "explanation": "Les leçons précédentes donnent toutes les clés : la jinkim (lecture), la surligne (abréviation), les articles ⲡⲓ, ϯ, ⲛⲓ, ⲟⲩ, ϩⲁⲛ et ⲫ̀, les possessifs ⲡⲉⲛ-, ⲡⲁ-, ⲡⲉⲕ-, les petits mots, les marques du verbe ⲁϥ-, ⲁⲥ-, ⲁⲩ-, ϯ-. Avec elles, une formule se lit mot à mot et se traduit. Reconnaître l''origine d''un mot (égyptien, grec, hébreu) aide à en deviner le sens.", "pattern": "article/possessif + nom ; ⲁ + personne + verbe ; petits mots entre les groupes", "examples": [{"text": "ϧⲉⲛ ⲫ̀ⲣⲁⲛ ⲙ̀Ⲫ̀ⲓⲱⲧ", "translation": "Dans le nom du Père."}, {"text": "ⲁϥⲧⲱⲛϥ", "translation": "Il est ressuscité."}, {"text": "ϩⲓⲧⲉⲛ ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ", "translation": "Par les intercessions."}, {"text": "ⲛⲁⲓ ⲛⲁⲛ", "translation": "Aie pitié de nous."}], "commonErrors": [{"wrong": "Pour comprendre une formule, il faut l''apprendre par cœur.", "right": "Il suffit de la découper en articles, noms et petits mots.", "why": "Le copte se lit par morceaux collés."}, {"wrong": "Tous les mots coptes viennent du grec.", "right": "Il y a des mots égyptiens, grecs et hébreux.", "why": "Les lettres ϣ ϩ ϧ ϫ ϭ trahissent un mot égyptien."}, {"wrong": "La barre sur ⲓ̅ⲏ̅ⲥ̅ se lit comme une jinkim.", "right": "C''est une abréviation à lire en entier : Ⲓⲏⲥⲟⲩⲥ.", "why": "La jinkim touche une lettre ; la surligne en couvre plusieurs."}], "tip": "Détache l''article, lis la jinkim, trouve le nom, lis les petits mots."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
