insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l101', 'eg', 1, 'Le feu de la Pentecôte', 'Cent vingt personnes cachées dans une chambre, et cinquante jours plus tard une Église de trois mille baptisés.', 1, 101, 'eg.g101.pentecote', array['eg.g101.pentecote','eg.v.pentecote','eg.v.chambre_haute','eg.v.apotre']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l102', 'eg', 1, 'Une communauté qui partage', 'Cinq mille croyants à Jérusalem : ils partagent tout, prient ensemble, et des Égyptiens étaient déjà là à la Pentecôte.', 1, 102, 'eg.g102.communaute', array['eg.g102.communaute','eg.v.c01_premiere_communaute','eg.v.c01_fraction_du_pain','eg.v.c01_saint_pierre']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l103', 'eg', 1, 'Étienne, le premier témoin', 'Une dispute de veuves, un jeune homme qui garde des manteaux, et la mort qui disperse l''Église au lieu de l''étouffer.', 1, 103, 'eg.g103.etienne', array['eg.g103.etienne','eg.v.c01_helleniste','eg.v.c01_saint_etienne','eg.v.c01_martyr']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l104', 'eg', 1, 'Saul devient Paul', 'Le persécuteur qui part pour Damas, une lumière sur la route, et un nom nouveau : chrétiens.', 1, 104, 'eg.g104.paul', array['eg.g104.paul','eg.v.c01_saint_paul','eg.v.c01_saint_barnabe','eg.v.c01_antioche','eg.v.c01_chretiens']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l105', 'eg', 1, 'Le concile de Jérusalem', 'Faut-il être circoncis pour être chrétien ? Une dispute éclate à Antioche et l''Église invente sa méthode pour trancher.', 1, 105, 'eg.g105.concile', array['eg.g105.concile','eg.v.c01_circoncision','eg.v.c01_judaisants','eg.v.c01_concile','eg.v.c01_concile_de_jerusalem']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l106', 'eg', 1, 'Du glaive au feu de Rome', 'Un apôtre décapité, un empereur qui accuse les chrétiens, deux Jacques à ne pas confondre : les premiers martyrs.', 1, 106, 'eg.g106.martyrs', array['eg.g106.martyrs','eg.v.c01_jacques_de_zebedee','eg.v.c01_jacques_de_jerusalem','eg.v.c01_neron','eg.v.c01_empire_romain']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l107', 'eg', 1, 'Jérusalem tombe', 'La révolte de 66, le Temple qui brûle en 70 et un empereur qui se prend pour un dieu : la fin d''un monde.', 1, 107, 'eg.g107.chute', array['eg.g107.chute','eg.v.c01_revolte_juive','eg.v.c01_chute_de_jerusalem','eg.v.c01_temple_de_jerusalem','eg.v.c01_domitien']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l108', 'eg', 1, 'Écrire pour garder la foi', 'Jésus n''a rien écrit : comment la parole devient lettres et évangiles, et comment l''Église répond aux premières fausses idées.', 1, 108, 'eg.g108.ecrits', array['eg.g108.ecrits','eg.v.c01_evangile','eg.v.c01_heresie','eg.v.c01_gnosticisme','eg.v.c01_docetisme']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l109', 'eg', 1, 'Les apôtres partent', 'Thomas en Inde, André en Grèce, Jean à Éphèse : les envoyés de Jésus vers toutes les nations, et la chaîne qui garde la foi.', 1, 109, 'eg.g109.sieges', array['eg.g109.sieges','eg.v.c01_saint_jean','eg.v.c01_saint_thomas','eg.v.c01_siege_apostolique','eg.v.c01_succession_apostolique']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l110', 'eg', 1, 'Marc arrive à Alexandrie', 'Une sandale déchirée, un cordonnier blessé, un miracle : comment l''Évangile entre en Égypte.', 1, 110, 'eg.g110.marc', array['eg.g110.marc','eg.v.c01_alexandrie','eg.v.c01_septante','eg.v.c01_saint_marc','eg.v.c01_anianos']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l111', 'eg', 1, 'Le sang de Marc, le nom des Coptes', 'Le martyre de Marc, le voyage de ses reliques jusqu''à Venise et au Caire, et le sens du mot « copte ».', 1, 111, 'eg.g111.copte', array['eg.g111.copte','eg.v.c01_eglise_d_alexandrie','eg.v.c01_copte','eg.v.c01_reliques_de_saint_marc','eg.v.c01_cathedrale_saint_marc']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l112', 'eg', 1, 'Bilan : le premier siècle', 'Une frise, deux Jacques, deux erreurs, un fil rouge : tout le chapitre en quelques minutes.', 1, 112, 'eg.g112.bilan', array['eg.g112.bilan']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l201', 'eg', 2, 'Les apôtres sont morts : qui garde la foi ?', 'Plus aucun témoin du Christ n''est en vie : comment l''Église garde-t-elle la foi intacte ?', 2, 201, 'eg.g201.releve', array['eg.g201.releve','eg.v.c02_depot','eg.v.c02_tradition','eg.v.c02_eveque']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l202', 'eg', 2, 'Quatre Églises, quatre fondateurs', 'Rome, Alexandrie, Antioche, Jérusalem : les quatre sièges apostoliques, dont celui de saint Marc, notre Église.', 2, 202, 'eg.g202.sieges', array['eg.g202.sieges','eg.v.c02_siege_alexandrie','eg.v.c02_siege_rome','eg.v.c02_siege_antioche','eg.v.c02_siege_jerusalem']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l203', 'eg', 2, 'Ignace en route vers les lions', 'Clément écrit à Corinthe, Ignace est enchaîné vers Rome, Pline interroge l''empereur : les premiers Pères après les apôtres.', 2, 203, 'eg.g203.ignace', array['eg.g203.ignace','eg.v.c02_peres_apostoliques','eg.v.c02_clement','eg.v.c02_ignace','eg.v.c02_catholique']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l204', 'eg', 2, 'Polycarpe sur le bûcher', 'Un vieil évêque, disciple de l''apôtre Jean, refuse de renier son Roi.', 2, 204, 'eg.g204.polycarpe', array['eg.g204.polycarpe','eg.v.c02_polycarpe','eg.v.c02_smyrne']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l205', 'eg', 2, 'Le poisson dans le sable', 'Pourquoi Rome persécute les chrétiens, et comment ils se reconnaissent sans se trahir : le signe ICHTHYS.', 2, 205, 'eg.g205.ichthys', array['eg.g205.ichthys','eg.v.c02_ichthys','eg.v.c02_culte_empereur','eg.v.c02_persecution','eg.v.c02_blandine']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l206', 'eg', 2, 'Justin le philosophe', 'Un philosophe devient chrétien et défend la foi devant l''empereur ; Tertullien, l''avocat de Carthage, prend la suite.', 2, 206, 'eg.g206.justin', array['eg.g206.justin','eg.v.c02_justin','eg.v.c02_apologiste','eg.v.c02_tertullien','eg.v.c02_semences']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l207', 'eg', 2, 'Le savoir secret des gnostiques', 'Des maîtres promettent une connaissance réservée à quelques-uns, et un Christ qui n''aurait eu qu''un corps de fantôme.', 3, 207, 'eg.g207.gnose', array['eg.g207.gnose','eg.v.c02_gnose','eg.v.c02_irenee','eg.v.c02_nag_hammadi']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l208', 'eg', 2, 'Marcion déchire la Bible', 'Un armateur de Sinope croit à deux dieux et ne garde que Luc et dix lettres de Paul.', 3, 208, 'eg.g208.marcion', array['eg.g208.marcion','eg.v.c02_marcion','eg.v.c02_contre_marcion','eg.v.c02_ancien_testament']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l209', 'eg', 2, 'Montan et la nouvelle prophétie', 'Un prophète en transe annonce la fin du monde : pourquoi l''Église dit non au zèle sans mesure.', 3, 209, 'eg.g209.montan', array['eg.g209.montan','eg.v.c02_montanus','eg.v.c02_paraclet','eg.v.c02_priscilla']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l210', 'eg', 2, 'Quels livres garder ?', 'Marcion a taillé sa Bible : comment l''Église décide-t-elle de la liste des livres saints ?', 3, 210, 'eg.g210.canon', array['eg.g210.canon','eg.v.c02_canon','eg.v.c02_regle_foi','eg.v.c02_muratori']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l211', 'eg', 2, 'Démétrios, le vigneron devenu pape', 'Un paysan illettré devient pape d''Alexandrie, règle la date de Pâques et fait briller l''école.', 3, 211, 'eg.g211.demetrios', array['eg.g211.demetrios','eg.v.c02_demetrios','eg.v.c02_pape_alexandrie','eg.v.c02_date_paques','eg.v.c02_epacte']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l212', 'eg', 2, 'Bilan du IIe siècle', 'La frise, les trois remparts, les quatre erreurs et les liens avec Alexandrie : tout le chapitre en un coup d''œil.', 3, 212, 'eg.g212.bilan', array['eg.g212.bilan']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l301', 'eg', 3, 'Pourquoi Rome a peur des chrétiens', 'Ils ne sacrifient pas, ils se cachent, et la foule invente le pire : voici d''où viennent les persécutions.', 1, 301, 'eg.g301.rumeurs', array['eg.g301.rumeurs','eg.v.c03_sacrifice_public','eg.v.c03_mauvais_citoyens','eg.v.c03_anthropophagie','eg.v.c03_atheisme']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l302', 'eg', 3, 'L''édit de Dèce : signer ou mourir ?', 'En 250, tout le monde doit sacrifier. Un certificat sauve la vie, mais à quel prix ?', 2, 302, 'eg.g302.edit_de_dece', array['eg.g302.edit_de_dece','eg.v.c03_maximin','eg.v.c03_dece','eg.v.c03_edit_250','eg.v.c03_libellus']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l303', 'eg', 3, 'Les « tombés » et le refus de Novatien', 'Après la tempête, ceux qui ont cédé veulent revenir. Faut-il leur ouvrir la porte ?', 2, 303, 'eg.g303.tombes_et_novatien', array['eg.g303.tombes_et_novatien','eg.v.c03_tombes','eg.v.c03_penitence','eg.v.c03_novatien','eg.v.c03_excommunication']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l304', 'eg', 3, 'Valérien, Cyprien et la semence de martyrs', 'Quatre persécutions en un siècle, un évêque décapité, et une surprise : l''Église grandit.', 2, 304, 'eg.g304.valerien_semence', array['eg.g304.valerien_semence','eg.v.c03_valerien','eg.v.c03_cyprien','eg.v.c03_semence']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l305', 'eg', 3, '284 : l''an 1 du calendrier copte', 'Dioclétien devient empereur, la plus grande persécution éclate, et les Coptes décident de compter leurs années depuis ce moment.', 2, 305, 'eg.g305.diocletien_284', array['eg.g305.diocletien_284','eg.v.c03_diocletien','eg.v.c03_persecution_303','eg.v.c03_calendrier_copte','eg.v.c03_nayrouz']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l306', 'eg', 3, 'Au désert : Paul de Thèbes et Antoine', 'Ni sacrifier ni mourir : des chrétiens partent au désert. Ce qui est une fuite devient une vocation.', 2, 306, 'eg.g306.desert_paul_antoine', array['eg.g306.desert_paul_antoine','eg.v.c03_paul_de_thebes','eg.v.c03_antoine','eg.v.c03_ermite','eg.v.c03_desert_egypte']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l307', 'eg', 3, 'L''École d''Alexandrie', 'Pantène, Clément, Origène : comment une école de catéchumènes devient la première école de théologie.', 2, 307, 'eg.g307.ecole_alexandrie', array['eg.g307.ecole_alexandrie','eg.v.c03_ecole_alexandrie','eg.v.c03_pantene','eg.v.c03_clement','eg.v.c03_origene']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l308', 'eg', 3, 'Paul de Samosate et Sabellius : deux pièges', 'Au sujet de la Trinité, deux erreurs opposées : le Christ n''est qu''un homme, ou Dieu change de masque.', 3, 308, 'eg.g308.deux_pieges_trinite', array['eg.g308.deux_pieges_trinite','eg.v.c03_paul_de_samosate','eg.v.c03_sabellius','eg.v.c03_sainte_trinite','eg.v.c03_denys']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l309', 'eg', 3, 'Mani, le Perse aux deux dieux', 'Un nouveau mouvement venu de Perse sépare l''esprit (bon) et la matière (mauvaise) : pourquoi l''Église dit non.', 3, 309, 'eg.g309.mani_manicheisme', array['eg.g309.mani_manicheisme','eg.v.c03_mani','eg.v.c03_manicheisme','eg.v.c03_augustin']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l310', 'eg', 3, 'La sainte Tradition : comment choisir les livres', 'L''Église était là avant le Nouveau Testament. Comment a-t-elle choisi les livres de l''Écriture ?', 3, 310, 'eg.g310.sainte_tradition', array['eg.g310.sainte_tradition','eg.v.c03_hermas','eg.v.c03_approbation_apostolique','eg.v.c03_apocryphes','eg.v.c03_didache']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l311', 'eg', 3, 'Évêques, prêtres, diacres : et le premier pape', 'D''une équipe de serviteurs à trois degrés bien définis, jusqu''à Héraclas, le premier évêque d''Alexandrie appelé pape.', 3, 311, 'eg.g311.heraclas_hierarchie', array['eg.g311.heraclas_hierarchie','eg.v.c03_heraclas','eg.v.c03_hierarchie','eg.v.c03_confesseur','eg.v.c03_clercs_laics']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l312', 'eg', 3, 'Bilan : le troisième siècle', 'La frise des persécutions, les erreurs à ne pas confondre, l''an 1 des Coptes, le désert et l''École.', 3, 312, 'eg.g312.bilan_troisieme_siecle', array['eg.g312.bilan_troisieme_siecle','eg.v.c03_dix_persecutions','eg.v.c03_ere_martyrs']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l401', 'eg', 4, 'Le feu avant la paix', 'Quatre édits, un empereur plus cruel encore, le dernier grand martyr d''Alexandrie, puis un édit qui arrête tout.', 2, 401, 'eg.g401.grande_persecution', array['eg.g401.grande_persecution','eg.v.c04_galere','eg.v.c04_edit_311','eg.v.c04_pierre_sceau','eg.v.c04_saint_georges']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l402', 'eg', 4, 'Le signe dans le ciel', 'Constantin marche sur Rome, voit une croix dans le ciel, et un an plus tard l''édit de Milan donne la liberté.', 2, 402, 'eg.g402.constantin', array['eg.g402.constantin','eg.v.c04_constantin','eg.v.c04_maxence','eg.v.c04_edit_milan','eg.v.c04_licinius']::text[], array['eg.g401.grande_persecution']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l403', 'eg', 4, 'La ville de Constantin', 'Hélène et la Sainte Croix, la fondation de Constantinople, et le titre étonnant que se donne l''empereur.', 2, 403, 'eg.g403.empereur_et_eglise', array['eg.g403.empereur_et_eglise','eg.v.c04_helene','eg.v.c04_constantinople','eg.v.c04_eveque_du_dehors','eg.v.c04_armenie']::text[], array['eg.g401.grande_persecution','eg.g402.constantin']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l404', 'eg', 4, 'Arius, le prêtre qu''on aime', 'Un prêtre d''Alexandrie dit une phrase qui met le feu à l''Empire. Qui est Arius, et comment sa doctrine se répand.', 3, 404, 'eg.g404.arius', array['eg.g404.arius','eg.v.c04_arius','eg.v.c04_arianisme','eg.v.c04_alexandre','eg.v.c04_eusebe_nicomedie']::text[], array['eg.g401.grande_persecution','eg.g402.constantin','eg.g403.empereur_et_eglise']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l405', 'eg', 4, 'Si le Fils est une créature', 'Pourquoi l''arianisme est si grave : seul Dieu peut sauver. Les trois camps, et l''iota qui change tout.', 3, 405, 'eg.g405.divinite', array['eg.g405.divinite','eg.v.c04_divinite_du_christ','eg.v.c04_homoousios','eg.v.c04_semi_arianisme']::text[], array['eg.g402.constantin','eg.g403.empereur_et_eglise','eg.g404.arius']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l406', 'eg', 4, 'Nicée : les évêques arrivent', 'Constantin convoque tous les évêques. Qui vient, d''où, avec quelles cicatrices, et qui est face à qui.', 3, 406, 'eg.g406.nicee_convocation', array['eg.g406.nicee_convocation','eg.v.c04_concile_de_nicee','eg.v.c04_concile_oecumenique','eg.v.c04_nicee','eg.v.c04_eusebe_cesaree']::text[], array['eg.g403.empereur_et_eglise','eg.g404.arius','eg.g405.divinite']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l407', 'eg', 4, 'Nicée : ce qu''on décide', 'Le mot homoousios, le credo, les signatures et les trois évêques qui hésitent, vingt canons, et Arius excommunié.', 3, 407, 'eg.g407.nicee_decisions', array['eg.g407.nicee_decisions','eg.v.c04_credo_de_nicee','eg.v.c04_anathemes','eg.v.c04_les_318']::text[], array['eg.g404.arius','eg.g405.divinite','eg.g406.nicee_convocation']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l408', 'eg', 4, 'Athanase, le diacre de 27 ans', 'Un jeune génie d''Alexandrie, élève des moines, qui devient le héros de Nicée puis pape.', 3, 408, 'eg.g408.athanase_jeune', array['eg.g408.athanase_jeune','eg.v.c04_athanase','eg.v.c04_sur_incarnation']::text[], array['eg.g405.divinite','eg.g406.nicee_convocation','eg.g407.nicee_decisions']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l409', 'eg', 4, 'Athanase contre le monde', 'Des empereurs soutiennent les ariens : Athanase est chassé, caché, rappelé. Il fixe aussi la liste des 27 livres du Nouveau Testament.', 3, 409, 'eg.g409.athanase_exils', array['eg.g409.athanase_exils','eg.v.c04_defenseur_de_la_foi','eg.v.c04_exils_athanase','eg.v.c04_livres_27','eg.v.c04_vie_antoine']::text[], array['eg.g406.nicee_convocation','eg.g407.nicee_decisions','eg.g408.athanase_jeune']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l410', 'eg', 4, 'Antoine et Paul : le désert appelle', 'Pourquoi des chrétiens partent au désert, et comment l''Égypte donne au monde ses premiers moines.', 3, 410, 'eg.g410.monachisme_antoine', array['eg.g410.monachisme_antoine','eg.v.c04_monachisme','eg.v.c04_saint_antoine','eg.v.c04_saint_paul_ermite']::text[], array['eg.g407.nicee_decisions','eg.g408.athanase_jeune','eg.g409.athanase_exils']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l411', 'eg', 4, 'Pacôme et Macaire : le désert devient une ville', 'Des ermites aux monastères : la vie en communauté, la règle, Scété, et pourquoi l''Égypte est la mère du monachisme.', 3, 411, 'eg.g411.communautes', array['eg.g411.communautes','eg.v.c04_saint_pacome','eg.v.c04_vie_cenobitique','eg.v.c04_saint_macaire','eg.v.c04_scete']::text[], array['eg.g408.athanase_jeune','eg.g409.athanase_exils','eg.g410.monachisme_antoine']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l412', 'eg', 4, 'Frumentius : l''Évangile vers le sud', 'Un naufrage, une cour royale, un voyage à Alexandrie : comment l''Éthiopie reçoit son premier évêque des mains d''Athanase.', 3, 412, 'eg.g412.ethiopie', array['eg.g412.ethiopie','eg.v.c04_frumentius','eg.v.c04_ethiopie']::text[], array['eg.g409.athanase_exils','eg.g410.monachisme_antoine','eg.g411.communautes']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l413', 'eg', 4, 'Deux nouvelles erreurs', 'Apollinaire retire son âme humaine au Christ, Macédonius fait de l''Esprit une créature. En 380, l''Empire devient chrétien.', 3, 413, 'eg.g413.apollinaire_macedonius', array['eg.g413.apollinaire_macedonius','eg.v.c04_apollinaire','eg.v.c04_macedonius','eg.v.c04_theodose','eg.v.c04_religion_etat_380']::text[], array['eg.g410.monachisme_antoine','eg.g411.communautes','eg.g412.ethiopie']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l414', 'eg', 4, 'Constantinople 381 : l''Esprit Saint', 'Le deuxième concile : Théodose, 150 évêques, deux erreurs condamnées, et le Credo que tu récites à la messe.', 3, 414, 'eg.g414.constantinople', array['eg.g414.constantinople','eg.v.c04_concile_de_constantinople','eg.v.c04_credo_nicee_constantinople','eg.v.c04_pape_timothee','eg.v.c04_gregoire_theologien']::text[], array['eg.g411.communautes','eg.g412.ethiopie','eg.g413.apollinaire_macedonius']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l415', 'eg', 4, 'Le siècle en un coup d''œil', 'La frise, les deux conciles, les quatre erreurs, les héros et les trois liturgies : le bilan du IVe siècle.', 3, 415, 'eg.g415.bilan', array['eg.g415.bilan','eg.v.c04_saint_basile','eg.v.c04_trois_liturgies']::text[], array['eg.g412.ethiopie','eg.g413.apollinaire_macedonius','eg.g414.constantinople']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l501', 'eg', 5, 'Cinq sièges, une seule Église', 'Vers l''an 400, l''Église est une. Mais la jalousie entre les grandes villes couve déjà.', 1, 501, 'eg.g501.cinq_sieges', array['eg.g501.cinq_sieges','eg.v.c05_patriarche','eg.v.c05_nouvelle_rome','eg.v.c05_trois_premiers_conciles','eg.v.c05_canon_3_de_381']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l502', 'eg', 5, 'Nestorius monte en chaire', 'Constantinople, 428 : le nouveau patriarche refuse le titre « mère de Dieu » et la ville s''enflamme.', 2, 502, 'eg.g502.nestorius_chaire', array['eg.g502.nestorius_chaire','eg.v.c05_nestorius','eg.v.c05_theotokos','eg.v.c05_christotokos']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l503', 'eg', 5, 'Pourquoi ce mot protège le Christ', 'Qui est dans la crèche ? Théotokos n''est pas qu''un compliment pour Marie : il garde l''unité de Jésus.', 2, 503, 'eg.g503.protege_christ', array['eg.g503.protege_christ','eg.v.c05_le_verbe','eg.v.c05_incarnation','eg.v.c05_nestorianisme','eg.v.c05_ecole_d_antioche']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l504', 'eg', 5, 'Nature et personne : deux mots à ne pas confondre', 'Ce qu''on est, et qui on est. Sans ces deux mots, tout le reste du chapitre est incompréhensible.', 2, 504, 'eg.g504.nature_personne', array['eg.g504.nature_personne','eg.v.c05_nature','eg.v.c05_personne','eg.v.c05_unite_du_christ']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l505', 'eg', 5, 'Cyrille écrit', 'Le pape d''Alexandrie prend la plume : sa formule, l''image de l''âme et du corps, les douze anathèmes.', 2, 505, 'eg.g505.cyrille', array['eg.g505.cyrille','eg.v.c05_cyrille','eg.v.c05_formule_de_cyrille','eg.v.c05_douze_anathemes']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l506', 'eg', 5, 'Éphèse 431 : deux conciles dans la même ville', 'Cyrille ouvre le concile sans attendre Jean d''Antioche. À son arrivée, un second concile se réunit.', 3, 506, 'eg.g506.ephese_431', array['eg.g506.ephese_431','eg.v.c05_concile_ephese_431','eg.v.c05_ephese','eg.v.c05_jean_d_antioche']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l507', 'eg', 5, 'Ce qu''Éphèse décide', 'Nestorius déposé, Marie Théotokos, le credo intouchable, Pélage condamné, et un exil en Égypte.', 3, 507, 'eg.g507.decisions_ephese', array['eg.g507.decisions_ephese','eg.v.c05_pelagianisme','eg.v.c05_credo_intouchable','eg.v.c05_akhmim']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l508', 'eg', 5, '433 : la formule d''union', 'Cyrille et Jean d''Antioche se réconcilient, Cyrille meurt, et la crise couve encore.', 3, 508, 'eg.g508.formule_union', array['eg.g508.formule_union','eg.v.c05_formule_d_union','eg.v.c05_eglise_de_l_orient','eg.v.c05_flavien']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l509', 'eg', 5, 'Eutychès, le vieux moine qui va trop loin', 'Nestorius séparait. Eutychès, lui, mélange : l''humanité du Christ serait absorbée, comme une goutte de miel dans la mer.', 3, 509, 'eg.g509.eutyches', array['eg.g509.eutyches','eg.v.c05_eutyches','eg.v.c05_monophysisme','eg.v.c05_archimandrite']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l510', 'eg', 5, 'L''image du fer et du feu', 'Une barre de fer chauffée au rouge : pour comprendre l''union du divin et de l''humain, sans mélange et sans division.', 3, 510, 'eg.g510.fer_feu', array['eg.g510.fer_feu','eg.v.c05_fer_et_feu','eg.v.c05_sans_melange_ni_division']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l511', 'eg', 5, 'Mono, dyo, mia : trois petits mots', 'Une seule nature, deux natures, une nature unie : pour pouvoir l''expliquer sans te tromper.', 4, 511, 'eg.g511.mono_dyo_mia', array['eg.g511.mono_dyo_mia','eg.v.c05_miaphysisme','eg.v.c05_dyophysisme','eg.v.c05_physis']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l512', 'eg', 5, 'Éphèse II (449) : le concile de la discorde', 'Dioscore préside, Eutychès est réhabilité, Flavien déposé, et le Tome de Léon n''est pas lu.', 4, 512, 'eg.g512.ephese_449', array['eg.g512.ephese_449','eg.v.c05_concile_ephese_449','eg.v.c05_tome_de_leon','eg.v.c05_leon_ier','eg.v.c05_brigandage_d_ephese']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l513', 'eg', 5, 'Chalcédoine 451 : le premier schisme', 'Un nouvel empereur, un concile en face de Constantinople, « deux natures » et la rupture.', 4, 513, 'eg.g513.chalcedoine', array['eg.g513.chalcedoine','eg.v.c05_concile_chalcedoine','eg.v.c05_definition_de_chalcedoine','eg.v.c05_canon_28','eg.v.c05_premier_schisme']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l514', 'eg', 5, 'Dioscore, seul face au concile', 'Le disciple de Cyrille, jugé à Chalcédoine, déposé pour sa conduite et non pour hérésie, exilé à Gangra.', 4, 514, 'eg.g514.dioscore', array['eg.g514.dioscore','eg.v.c05_dioscore','eg.v.c05_gangra','eg.v.c05_confesseur_de_la_foi']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l515', 'eg', 5, 'Deux patriarches à Alexandrie', 'L''Hénotikon qui ne satisfait personne, les persécutions, et deux patriarches : le melkite et le copte.', 4, 515, 'eg.g515.deux_patriarches', array['eg.g515.deux_patriarches','eg.v.c05_henotikon','eg.v.c05_melkites','eg.v.c05_macaire_d_edkou']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l516', 'eg', 5, 'Où en est-on aujourd''hui ?', 'Trois conciles ou sept, six Églises sœurs, l''accord de 1989 : comment l''expliquer à un ami.', 4, 516, 'eg.g516.aujourd_hui', array['eg.g516.aujourd_hui','eg.v.c05_eglises_soeurs','eg.v.c05_chalcedoniens','eg.v.c05_accord_de_1989']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l517', 'eg', 5, 'Bilan : le cinquième siècle', 'La frise, les trois erreurs à ne jamais confondre, nature et personne, et comment l''expliquer à un ami.', 4, 517, 'eg.g517.bilan', array['eg.g517.bilan','eg.v.c05_frise','eg.v.c05_christologie']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l601', 'eg', 6, 'La logique d''un concile', 'Une erreur, un concile, une formule : le schéma qui explique tous les conciles.', 2, 601, 'eg.g601.logique_concile', array['eg.g601.logique_concile','eg.v.c06_reception_d_un_concile']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l602', 'eg', 6, 'Avant Nicée : quatre erreurs', 'Gnose, Marcion, Mani, Montan : chaque erreur en une phrase, et la réponse de l''Église.', 2, 602, 'eg.g602.erreurs_avant_nicee', array['eg.g602.erreurs_avant_nicee']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l603', 'eg', 6, 'Père, Fils, Esprit : quatre erreurs', 'Paul de Samosate, Sabellius, Arius, Macédonius : trois personnes, une divinité, et ce qui casse l''équilibre.', 3, 603, 'eg.g603.erreurs_trinite', array['eg.g603.erreurs_trinite','eg.v.c06_adoptianisme','eg.v.c06_modalisme']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l604', 'eg', 6, 'Qui est le Christ ? Quatre erreurs et une voie', 'Docétisme, Apollinaire, Nestorius, Eutychès : chaque erreur oublie une pièce, et Cyrille tient le milieu.', 3, 604, 'eg.g604.erreurs_christ', array['eg.g604.erreurs_christ']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l605', 'eg', 6, 'Nicée 325 en fiche', 'La grille des six questions, appliquée à Nicée : qui, où, quand, contre qui, ce qu''on décide, les héros.', 3, 605, 'eg.g605.fiche_nicee', array['eg.g605.fiche_nicee']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l606', 'eg', 6, 'Constantinople 381 en fiche', 'La grille des six questions appliquée au deuxième concile : l''Esprit Saint et le credo complété.', 3, 606, 'eg.g606.fiche_constantinople', array['eg.g606.fiche_constantinople']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l607', 'eg', 6, 'Éphèse 431 en fiche', 'La grille des six questions appliquée au troisième concile : Nestorius, Théotokos, Cyrille.', 3, 607, 'eg.g607.fiche_ephese', array['eg.g607.fiche_ephese']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l608', 'eg', 6, 'Éphèse II et Chalcédoine vus par l''Église copte', 'Deux conciles que l''Église copte ne compte pas, et pourquoi : la grille, puis la voix de Dioscore.', 4, 608, 'eg.g608.fiches_ephese2_chalcedoine', array['eg.g608.fiches_ephese2_chalcedoine']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l609', 'eg', 6, 'La grande frise', 'Des conciles de 49 à Chalcédoine, puis la suite : tout remettre dans l''ordre, date après date.', 3, 609, 'eg.g609.frise', array['eg.g609.frise']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l610', 'eg', 6, 'Deux Éphèse, deux Paul, deux Eusèbe', 'Les paires de noms qui se ressemblent : qui est qui, quel concile est lequel.', 3, 610, 'eg.g610.homonymes', array['eg.g610.homonymes']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l611', 'eg', 6, 'Les mots jumeaux', 'Homoousios et homoiousios, Théotokos et Christotokos, mia et mono : un petit mot change tout.', 4, 611, 'eg.g611.mots_jumeaux', array['eg.g611.mots_jumeaux']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l612', 'eg', 6, 'Les trois formules à savoir dire', 'Homoousios, Théotokos, « une seule nature du Verbe incarné » : qui, quand, contre qui, et comment elles s''emboîtent.', 4, 612, 'eg.g612.trois_formules', array['eg.g612.trois_formules','eg.v.c06_les_trois_formules']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l613', 'eg', 6, 'Bilan : conciles et hérésies', 'La frise, les erreurs en une ligne, qui convoque, qui préside, et les pièges à éviter.', 4, 613, 'eg.g613.bilan', array['eg.g613.bilan']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l701', 'eg', 7, 'Marc te demande : « Tu es catholique ? »', 'Quatre familles de chrétiens, trois questions pour les distinguer, et ta place parmi elles.', 1, 701, 'eg.g701.quatre_familles', array['eg.g701.quatre_familles','eg.v.c07_orthodoxes_byzantins','eg.v.c07_eglise_catholique','eg.v.c07_protestantisme','eg.v.c07_patriarcat_grec']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l702', 'eg', 7, 'Eleni et les deux formules', 'Avec une orthodoxe grecque, vous confessez le même Christ : seules les formules changent.', 2, 702, 'eg.g702.chalcedoine_deux_formules', array['eg.g702.chalcedoine_deux_formules','eg.v.c07_de_deux_natures','eg.v.c07_sept_conciles']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l703', 'eg', 7, '« Pourquoi vous n''avez pas le même pape ? »', 'La question de Marc, et une réponse calme sur la primauté du pape et le rôle des évêques en concile.', 2, 703, 'eg.g703.pape_primaute', array['eg.g703.pape_primaute','eg.v.c07_pape_de_rome','eg.v.c07_primaute','eg.v.c07_infaillibilite','eg.v.c07_vatican_i']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l704', 'eg', 7, 'Un mot de plus dans le Credo', 'Le Filioque, le schisme de 1054 qui ne nous concerne pas directement, et le dialogue d''aujourd''hui.', 2, 704, 'eg.g704.filioque_1054', array['eg.g704.filioque_1054','eg.v.c07_filioque','eg.v.c07_schisme_1054','eg.v.c07_declaration_1973']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l705', 'eg', 7, 'Marie, le purgatoire et nos défunts', 'Avec Marc, vous aimez la même Vierge Marie ; deux doctrines catholiques, l''Immaculée Conception et le purgatoire, ne sont pas les nôtres.', 2, 705, 'eg.g705.marie_purgatoire', array['eg.g705.marie_purgatoire','eg.v.c07_immaculee_conception','eg.v.c07_peche_originel','eg.v.c07_purgatoire','eg.v.c07_prieres_defunts']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l706', 'eg', 7, 'Le pain levé et les prêtres mariés', 'Deux détails qui frappent à la messe de Marc : le pain et l''absence d''épouse du prêtre. Des différences de discipline, pas de foi.', 2, 706, 'eg.g706.pain_celibat', array['eg.g706.pain_celibat','eg.v.c07_azymes','eg.v.c07_pain_leve','eg.v.c07_celibat','eg.v.c07_catholique_copte']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l707', 'eg', 7, 'Luther, 1517 : la Bible seule ?', 'Comment est né le protestantisme, ce qu''il défend, et pourquoi l''Église copte garde l''Écriture et la Tradition.', 3, 707, 'eg.g707.reforme_ecriture', array['eg.g707.reforme_ecriture','eg.v.c07_95_theses','eg.v.c07_reforme','eg.v.c07_sola_scriptura','eg.v.c07_deuterocanoniques']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l708', 'eg', 7, 'La foi seule ou la foi et les œuvres ?', 'Sola fide, Jacques 2, 24, et le monde protestant : des Églises sans pape, parfois très différentes entre elles.', 3, 708, 'eg.g708.foi_oeuvres', array['eg.g708.foi_oeuvres','eg.v.c07_sola_fide','eg.v.c07_anglicans','eg.v.c07_baptistes','eg.v.c07_eglise_evangelique']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l709', 'eg', 7, 'Sept sacrements, des saints et des icônes', 'Avec Sarah : combien de sacrements, pourquoi demander la prière des saints, pourquoi des icônes, et comment on devient évêque.', 3, 709, 'eg.g709.sacrements_saints_icones', array['eg.g709.sacrements_saints_icones','eg.v.c07_sept_sacrements','eg.v.c07_intercession','eg.v.c07_veneration','eg.v.c07_icone']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l710', 'eg', 7, 'Lucas, le voisin mormon', 'Qui sont les mormons, ce que dit leur livre, et pourquoi l''Église copte garde une Bible complète et la Trinité.', 3, 710, 'eg.g710.mormons', array['eg.g710.mormons','eg.v.c07_mormons','eg.v.c07_livre_de_mormon','eg.v.c07_plaques_d_or']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l711', 'eg', 7, 'Anna, l''amie adventiste', 'Une date annoncée, une déception, un mouvement qui croit à la Trinité : ce qui nous rapproche et ce qui diffère.', 3, 711, 'eg.g711.adventistes', array['eg.g711.adventistes','eg.v.c07_adventistes','eg.v.c07_grande_deception','eg.v.c07_sabbat_samedi']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l712', 'eg', 7, 'Daniel, témoin de Jéhovah', 'Qui sont les témoins de Jéhovah, ce qu''ils croient de Jésus et de l''Esprit, et pourquoi le refus de transfusion ne veut pas dire refus de soins.', 3, 712, 'eg.g712.temoins', array['eg.g712.temoins','eg.v.c07_temoins_de_jehovah','eg.v.c07_traduction_monde_nouveau','eg.v.c07_144000','eg.v.c07_refus_transfusion']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l713', 'eg', 7, 'Claire, la Science chrétienne, et ce que tout cela a en commun', 'Un dernier mouvement du XIXe siècle, les traits communs des groupes récents, et la manière de répondre : avec douceur et respect.', 3, 713, 'eg.g713.science_chretienne', array['eg.g713.science_chretienne','eg.v.c07_science_chretienne','eg.v.c07_science_et_sante','eg.v.c07_grande_apostasie','eg.v.c07_douceur_respect']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l714', 'eg', 7, 'Bilan : ce qui nous unit et ce qui nous sépare', 'Le test des trois questions, les dates à retenir, un mot-clé par famille, et la manière de répondre à Marc, Eleni, Sarah ou Daniel.', 4, 714, 'eg.g714.bilan', array['eg.g714.bilan','eg.v.c07_trois_questions','eg.v.c07_ce_qui_nous_unit']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l801', 'eg', 8, 'Le Credo, ta carte d''identité', 'Un catéchumène répond « je crois » au bord de l''eau : c''est de là que naissent les credos, jusqu''à Nicée, Constantinople et Éphèse.', 1, 801, 'eg.g801.origine_du_credo', array['eg.g801.origine_du_credo','eg.v.c08_credo','eg.v.c08_nous_croyons','eg.v.c08_catechumene','eg.v.c08_mere_de_la_vraie_lumiere']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l802', 'eg', 8, 'Un seul Dieu, le Père, Pantocrator', 'Les premiers mots du Credo : un seul Dieu, un Père qui a un Fils de toute éternité, et le Tout-Puissant qui tient tout.', 1, 802, 'eg.g802.un_seul_dieu_pere', array['eg.g802.un_seul_dieu_pere','eg.v.c08_monotheisme','eg.v.c08_dieu_le_pere','eg.v.c08_pantocrator']::text[], array['eg.g801.origine_du_credo']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l803', 'eg', 8, 'Créateur du ciel et de la terre', 'Tout vient de Dieu, à partir de rien, et tout est bon. Les choses visibles, les choses invisibles, et les anges.', 1, 803, 'eg.g803.createur_ciel_terre', array['eg.g803.createur_ciel_terre','eg.v.c08_creation_a_partir_de_rien','eg.v.c08_visibles_et_invisibles','eg.v.c08_ange']::text[], array['eg.g802.un_seul_dieu_pere']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l804', 'eg', 8, 'Un seul Seigneur, le Fils unique', 'Arius dit que le Fils a un commencement. Le Credo répond : Seigneur, Fils unique, engendré du Père avant tous les siècles.', 2, 804, 'eg.g804.seigneur_fils_unique', array['eg.g804.seigneur_fils_unique','eg.v.c08_kyrios','eg.v.c08_fils_unique','eg.v.c08_avant_tous_les_siecles']::text[], array['eg.g803.createur_ciel_terre']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l805', 'eg', 8, 'Lumière de Lumière', 'Une flamme allumée à une autre flamme : trois expressions du Credo ferment chacune une porte à Arius.', 2, 805, 'eg.g805.lumiere_de_lumiere', array['eg.g805.lumiere_de_lumiere','eg.v.c08_lumiere_de_lumiere','eg.v.c08_vrai_dieu_de_vrai_dieu','eg.v.c08_engendre_non_cree']::text[], array['eg.g804.seigneur_fils_unique']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l806', 'eg', 8, 'Consubstantiel au Père', 'À Nicée, il fallait un mot qu''on ne puisse pas tordre : homoousios. Un iota de différence, et le salut en jeu.', 2, 806, 'eg.g806.consubstantiel', array['eg.g806.consubstantiel','eg.v.c08_par_qui_tout_a_ete_fait','eg.v.c08_seul_dieu_sauve']::text[], array['eg.g805.lumiere_de_lumiere']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l807', 'eg', 8, 'Pour nous et pour notre salut', 'Pourquoi le Fils éternel descend-il ? Pour nous, pour notre salut, et pour que l''homme partage la vie de Dieu.', 2, 807, 'eg.g807.pour_notre_salut', array['eg.g807.pour_notre_salut','eg.v.c08_pour_notre_salut','eg.v.c08_descente_du_ciel','eg.v.c08_divinisation']::text[], array['eg.g806.consubstantiel']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l808', 'eg', 8, 'De la Vierge Marie, et se fit homme', 'Le Fils prend chair de l''Esprit Saint et de la Vierge Marie. Un vrai corps, une âme humaine, et un seul « Il » dans tout le Credo.', 2, 808, 'eg.g808.incarna_vierge_marie', array['eg.g808.incarna_vierge_marie','eg.v.c08_conception_virginale','eg.v.c08_vierge_marie','eg.v.c08_un_seul_sujet']::text[], array['eg.g807.pour_notre_salut']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l809', 'eg', 8, 'Crucifié, enseveli, ressuscité', 'Un nom de Romain dans le Credo, une vraie mort, un tombeau vide le troisième jour, et des prophètes qui l''avaient annoncé.', 2, 809, 'eg.g809.crucifie_ressuscite', array['eg.g809.crucifie_ressuscite','eg.v.c08_ponce_pilate','eg.v.c08_troisieme_jour','eg.v.c08_selon_les_ecritures']::text[], array['eg.g808.incarna_vierge_marie']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l810', 'eg', 8, 'Monté aux cieux, il reviendra', 'Quarante jours, une place d''honneur, un retour dans la gloire, et une dernière phrase ajoutée en 381 : « Son règne n''aura pas de fin ».', 2, 810, 'eg.g810.gloire_et_regne', array['eg.g810.gloire_et_regne','eg.v.c08_droite_du_pere','eg.v.c08_seconde_venue','eg.v.c08_regne_sans_fin','eg.v.c08_chaine_des_verbes']::text[], array['eg.g809.crucifie_ressuscite']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l811', 'eg', 8, 'Le Saint-Esprit, Seigneur et vivificateur', 'À Nicée, l''Esprit n''était que nommé. Après Macédonius, Constantinople dit en quatre « qui » qui il est.', 3, 811, 'eg.g811.saint_esprit', array['eg.g811.saint_esprit','eg.v.c08_vivificateur','eg.v.c08_procession','eg.v.c08_a_parle_par_les_prophetes']::text[], array['eg.g810.gloire_et_regne']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l812', 'eg', 8, 'Une Église, sainte, catholique, apostolique', 'Quatre mots pour l''Église : une pour l''unité, sainte pour la source, catholique pour l''étendue, apostolique pour l''origine.', 2, 812, 'eg.g812.quatre_marques', array['eg.g812.quatre_marques','eg.v.c08_eglise_une','eg.v.c08_eglise_sainte','eg.v.c08_apostolicite']::text[], array['eg.g811.saint_esprit']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l813', 'eg', 8, 'Un baptême, la résurrection, Amen', 'La fin du Credo : un seul baptême qui pardonne, la résurrection du corps, la vie du siècle à venir, et le mot par lequel tu signes.', 2, 813, 'eg.g813.bapteme_resurrection_amen', array['eg.g813.bapteme_resurrection_amen','eg.v.c08_un_seul_bapteme','eg.v.c08_resurrection_des_morts','eg.v.c08_siecle_a_venir','eg.v.c08_amen']::text[], array['eg.g812.quatre_marques']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l814', 'eg', 8, 'Bilan : le Credo en entier', 'Les trois blocs plus l''Église, une erreur par article, trois conciles, et tout le Credo dans l''ordre.', 3, 814, 'eg.g814.bilan_du_credo', array['eg.g814.bilan_du_credo','eg.v.c08_trois_blocs','eg.v.c08_confesser']::text[], array['eg.g813.bapteme_resurrection_amen']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l901', 'eg', 9, 'Dieu agit par ce qu''on touche', 'Pourquoi l''eau, l''huile et le pain ? Le secret des sept sacrements tient en deux mots : visible et invisible.', 1, 901, 'eg.g901.signe_et_grace', array['eg.g901.signe_et_grace','eg.v.c09_sacrement','eg.v.c09_grace','eg.v.c09_signe_visible']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l902', 'eg', 9, 'Le baptême : mourir pour naître', 'Un enfant regarde son petit frère dans l''eau. Pourquoi plonge-t-on, et pourquoi trois fois ?', 1, 902, 'eg.g902.bapteme_naissance', array['eg.g902.bapteme_naissance','eg.v.c09_bapteme','eg.v.c09_triple_immersion','eg.v.c09_nouvelle_naissance']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l903', 'eg', 9, 'Dos à l''ouest, face à l''est', 'Avant de plonger, le baptisé fait deux demi-tours. Pourquoi d''abord vers le soleil couchant, puis vers le soleil levant ?', 2, 903, 'eg.g903.ouest_est', array['eg.g903.ouest_est','eg.v.c09_renoncement_a_satan','eg.v.c09_profession_de_foi']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l904', 'eg', 9, 'Pourquoi baptiser un bébé ?', 'Il ne parle pas, il ne marche pas : pourquoi l''Église le baptise-t-elle quand même ? Et pourquoi 40 jours, ou 80 ?', 2, 904, 'eg.g904.bebes_parrain', array['eg.g904.bebes_parrain','eg.v.c09_bapteme_des_enfants','eg.v.c09_parrain','eg.v.c09_quarante_quatre_vingts_jours']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l905', 'eg', 9, 'Le saint myron : une huile pas comme les autres', 'Un sceau parfumé, préparé par le pape lui-même. D''où vient cette huile et pourquoi remplace-t-elle les mains des apôtres ?', 2, 905, 'eg.g905.myron', array['eg.g905.myron','eg.v.c09_confirmation','eg.v.c09_saint_myron','eg.v.c09_preparation_du_myron','eg.v.c09_imposition_des_mains']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l906', 'eg', 9, 'Trente-six croix sur un nouveau-né', 'L''enfant sort de l''eau. Le prêtre trace 36 croix, l''habille de blanc, noue un ruban. Que veut dire chaque geste ?', 2, 906, 'eg.g906.trente_six_onctions', array['eg.g906.trente_six_onctions','eg.v.c09_trente_six_onctions','eg.v.c09_sceau_du_saint_esprit','eg.v.c09_habit_blanc','eg.v.c09_zounnar']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l907', 'eg', 9, 'Le soir du Jeudi saint', 'Un dernier repas à Jérusalem, quelques mots sur du pain : « Ceci est mon corps ». Toute l''eucharistie est là.', 2, 907, 'eg.g907.derniere_cene', array['eg.g907.derniere_cene','eg.v.c09_eucharistie','eg.v.c09_derniere_cene','eg.v.c09_presence_reelle','eg.v.c09_pain_de_vie']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l908', 'eg', 9, 'Un pain qui a levé', 'Pourquoi du pain levé, pourquoi à jeun, pourquoi se confesser avant ? La communion se prépare.', 2, 908, 'eg.g908.qorban_jeune', array['eg.g908.qorban_jeune','eg.v.c09_qorban','eg.v.c09_jeune_eucharistique','eg.v.c09_communion']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l909', 'eg', 9, 'Pourquoi dire ses péchés à un prêtre ?', '« Dieu seul pardonne » : c''est vrai. Alors pourquoi la confession ? La réponse commence le soir de Pâques.', 2, 909, 'eg.g909.confession', array['eg.g909.confession','eg.v.c09_confession','eg.v.c09_lier_et_delier','eg.v.c09_absolution']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l910', 'eg', 9, 'Un père de confession, un secret absolu', 'Se confier à quelqu''un qui te connaît. Pourquoi le prêtre se tait toujours, et ce que veut dire « se repentir ».', 2, 910, 'eg.g910.repentance_pere', array['eg.g910.repentance_pere','eg.v.c09_pere_de_confession','eg.v.c09_repentance','eg.v.c09_secret_de_la_confession','eg.v.c09_contrition']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l911', 'eg', 9, 'Le qandil : sept mèches pour un malade', 'Une lampe à sept mèches, de l''huile, un prêtre au chevet d''un malade. Ce que dit Jacques et ce que fait l''Église.', 2, 911, 'eg.g911.qandil', array['eg.g911.qandil','eg.v.c09_onction_des_malades','eg.v.c09_qandil','eg.v.c09_sept_meches','eg.v.c09_qandil_general']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l912', 'eg', 9, 'Les couronnes du mariage', 'Pourquoi coiffe-t-on les mariés de couronnes ? Parce que Dieu fait d''eux un petit royaume, et d''une maison une petite église.', 2, 912, 'eg.g912.mariage', array['eg.g912.mariage','eg.v.c09_mariage','eg.v.c09_couronnement','eg.v.c09_indissolubilite','eg.v.c09_noces_de_cana']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l913', 'eg', 9, 'Les mains qui se transmettent', 'Douze hommes choisis sur une montagne, une chaîne de mains qui traverse vingt siècles : voici le septième sacrement.', 2, 913, 'eg.g913.sacerdoce', array['eg.g913.sacerdoce','eg.v.c09_sacerdoce','eg.v.c09_ordination']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l914', 'eg', 9, 'Bilan : sept sacrements, cinq signes', 'Eau, huile, pain, mains, couronnes : tu peux maintenant raconter chacun des sept sacrements et dire pourquoi on fait ces gestes.', 2, 914, 'eg.g914.bilan_sacrements', array['eg.g914.bilan_sacrements','eg.v.c09_sacrements_d_initiation','eg.v.c09_sacrements_de_guerison','eg.v.c09_sacrements_de_vocation']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1001', 'eg', 10, 'Pourquoi l''église regarde l''est', 'Tu entres par la porte et tu te demandes pourquoi tout le monde regarde dans la même direction : l''est. Trois raisons, et une arche.', 1, 1001, 'eg.g1001.orientation_est', array['eg.g1001.orientation_est','eg.v.c10_orientation_est','eg.v.c10_arche_de_noe','eg.v.c10_nef']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1002', 'eg', 10, 'Trois parties, un chemin', 'Narthex, nef, sanctuaire : en avançant, tu refais le chemin d''Israël dans la tente de Moïse.', 1, 1002, 'eg.g1002.trois_parties', array['eg.g1002.trois_parties','eg.v.c10_narthex','eg.v.c10_tabernacle_de_moise','eg.v.c10_lieu_saint','eg.v.c10_saint_des_saints']::text[], array['eg.g1001.orientation_est']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1003', 'eg', 10, 'Le mur d''icônes', 'Devant toi se dresse un mur couvert de visages : l''iconostase. Qui est où, et pourquoi la Cène juste au-dessus de la porte ?', 2, 1003, 'eg.g1003.iconostase', array['eg.g1003.iconostase','eg.v.c10_iconostase','eg.v.c10_porte_royale','eg.v.c10_saint_jean_baptiste']::text[], array['eg.g1002.trois_parties']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1004', 'eg', 10, 'Un œuf, une flamme, un nuage', 'Un œuf d''autruche, des lampes, de l''encens : trois signes que tu vois tous les dimanches, et ce qu''ils racontent.', 2, 1004, 'eg.g1004.symboles', array['eg.g1004.symboles','eg.v.c10_oeuf_d_autruche','eg.v.c10_lampe_a_huile','eg.v.c10_encens','eg.v.c10_adoration']::text[], array['eg.g1001.orientation_est','eg.g1003.iconostase']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1005', 'eg', 10, 'Le sanctuaire : terre sainte', 'Tu te déchausses, tu passes la porte royale : voici le haikal, l''autel qui est à la fois tombeau et table, et l''huile sainte qui le consacre.', 2, 1005, 'eg.g1005.haikal', array['eg.g1005.haikal','eg.v.c10_haikal','eg.v.c10_autel','eg.v.c10_entrer_dechausse']::text[], array['eg.g1002.trois_parties','eg.g1003.iconostase']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1006', 'eg', 10, 'Sur l''autel', 'Un ciel peint au-dessus, une coupe, un plateau, une étoile : les objets de l''autel et ce qu''ils rappellent.', 2, 1006, 'eg.g1006.objets_autel', array['eg.g1006.objets_autel','eg.v.c10_ciborium','eg.v.c10_calice','eg.v.c10_patene','eg.v.c10_asterisque']::text[], array['eg.g1005.haikal']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1007', 'eg', 10, 'Du psalte à l''archidiacre', 'Cinq marches pour servir à l''autel : celui qui chante, celui qui lit, celui qui garde, celui qui sert, celui qui dirige.', 2, 1007, 'eg.g1007.diaconat', array['eg.g1007.diaconat','eg.v.c10_diaconat','eg.v.c10_psalte','eg.v.c10_lecteur','eg.v.c10_sous_diacre']::text[], array['eg.g1005.haikal','eg.g311.heraclas_hierarchie']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1008', 'eg', 10, 'Prêtres, évêques, patriarche', 'Qui célèbre, qui ordonne, qui préside : le prêtre qu''on appelle abouna, l''évêque venu du monastère et le pape d''Alexandrie.', 3, 1008, 'eg.g1008.pretres_eveques', array['eg.g1008.pretres_eveques','eg.v.c10_abouna','eg.v.c10_qommos','eg.v.c10_metropolite','eg.v.c10_saint_synode']::text[], array['eg.g1007.diaconat','eg.g311.heraclas_hierarchie']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1009', 'eg', 10, 'Choisir un pape', 'Le trône est vide. Un vote retient trois noms, puis un enfant aux yeux bandés en tire un sur l''autel : l''élection la plus surprenante de l''Église.', 3, 1009, 'eg.g1009.choisir_pape', array['eg.g1009.choisir_pape','eg.v.c10_qora_haykaleya','eg.v.c10_chenouda_iii','eg.v.c10_tawadros_ii']::text[], array['eg.g1005.haikal','eg.g1008.pretres_eveques']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1010', 'eg', 10, 'Les moines, du désert à aujourd''hui', 'Antoine et Paul ont lancé un élan qui n''a jamais cessé : des moines vivent encore près de la mer Rouge et à Wadi Natroun.', 3, 1010, 'eg.g1010.moines', array['eg.g1010.moines','eg.v.c10_abbe','eg.v.c10_eskime','eg.v.c10_monastere_saint_antoine','eg.v.c10_wadi_natroun']::text[], array['eg.g410.monachisme_antoine','eg.g411.communautes']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1011', 'eg', 10, 'Bilan : l''église et le clergé', 'De la porte à l''autel, du psalte au pape : le chapitre en un coup d''œil, et trois confusions à ne jamais faire.', 3, 1011, 'eg.g1011.bilan', array['eg.g1011.bilan','eg.v.c10_moine','eg.v.c10_clerge']::text[], array['eg.g1007.diaconat','eg.g1008.pretres_eveques','eg.g1009.choisir_pape','eg.g1010.moines']::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1101', 'eg', 11, 'Sept fois par jour', 'Pourquoi l''Église donne des rendez-vous de prière dans la journée, et le livre qui les rassemble : l''Agpeya.', 1, 1101, 'eg.g1101.sept_fois', array['eg.g1101.sept_fois','eg.v.c11_agpeya','eg.v.c11_sept_heures','eg.v.c11_prier_sans_cesse']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1102', 'eg', 11, '6 h : Prime, l''aube', 'Le jour biblique commence au lever du soleil. Les noms Prime, Tierce, Sexte et None, et la première heure : Prime.', 1, 1102, 'eg.g1102.prime_aube', array['eg.g1102.prime_aube','eg.v.c11_prime','eg.v.c11_heure_biblique']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1103', 'eg', 11, '9 h : Tierce, un tribunal puis une flamme', 'Tierce rappelle deux scènes à la même heure : le procès devant Pilate et la descente de l''Esprit à la Pentecôte.', 1, 1103, 'eg.g1103.tierce', array['eg.g1103.tierce','eg.v.c11_tierce','eg.v.c11_proces_pilate']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1104', 'eg', 11, 'Midi et 15 h : la croix', 'Sexte à midi rappelle la crucifixion, la None à 15 h la mort du Christ, avec le bon larron.', 1, 1104, 'eg.g1104.sexte_none', array['eg.g1104.sexte_none','eg.v.c11_sexte','eg.v.c11_none_heure','eg.v.c11_bon_larron']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1105', 'eg', 11, 'Le soir : Vêpres et Complies', 'Du coucher du soleil à la nuit : la descente de la croix, l''ensevelissement, et les prières ajoutées pendant le Carême.', 1, 1105, 'eg.g1105.vepres_complies', array['eg.g1105.vepres_complies','eg.v.c11_vepres','eg.v.c11_complies','eg.v.c11_descente_de_la_croix']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1106', 'eg', 11, 'Minuit : veiller', 'La dernière heure de la journée de prière : on se lève la nuit, comme les dix vierges, et on attend le retour du Christ.', 1, 1106, 'eg.g1106.minuit', array['eg.g1106.minuit','eg.v.c11_minuit_heure','eg.v.c11_dix_vierges','eg.v.c11_trois_veilles','eg.v.c11_priere_du_voile']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1107', 'eg', 11, 'Le plan d''une heure', 'Chaque heure de l''Agpeya suit le même plan en neuf étapes : on s''y repère vite, où qu''on soit dans le livre.', 1, 1107, 'eg.g1107.plan_heure', array['eg.g1107.plan_heure','eg.v.c11_psaume_50','eg.v.c11_notre_pere']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1108', 'eg', 11, 'Debout, métanies, 41 Kyrie : à quoi servent les gestes', 'Le corps prie avec l''âme : se tenir debout, la métanie, le signe de croix, les 41 Kyrie et la façon de se préparer.', 1, 1108, 'eg.g1108.gestes', array['eg.g1108.gestes','eg.v.c11_metanie','eg.v.c11_quarante_et_un_kyrie','eg.v.c11_signe_de_croix']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1109', 'eg', 11, 'Pourquoi on prie vers l''est', 'Tu connais déjà une raison : le paradis est à l''est. Voici les cinq autres, qui font six en tout.', 1, 1109, 'eg.g1109.vers_l_est', array['eg.g1109.vers_l_est','eg.v.c11_est_orient','eg.v.c11_soleil_de_justice','eg.v.c11_etoile_des_mages','eg.v.c11_orientation_des_eglises']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1110', 'eg', 11, 'Bilan : ta journée de prière', 'Les sept heures, le plan d''une heure, les gestes et les six raisons de prier vers l''est : tout le chapitre en un seul parcours.', 1, 1110, 'eg.g1110.bilan_agpeya', array['eg.g1110.bilan_agpeya']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1201', 'eg', 12, 'Levez-vous, fils de la lumière', 'La tasbeha, la louange de minuit : ce que le mot veut dire, quand on la prie, et le chant qui réveille l''assemblée.', 1, 1201, 'eg.g1201.reveil', array['eg.g1201.reveil','eg.v.c12_tasbeha','eg.v.c12_ten_thino','eg.v.c12_fils_de_la_lumiere']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1202', 'eg', 12, 'Une nuit de louange, de A à Z', 'Le plan de la tasbeha en six étapes, comme une nuit qui se déroule : prier, se lever, louer, chanter, écouter, conclure.', 1, 1202, 'eg.g1202.nuit_louange', array['eg.g1202.nuit_louange','eg.v.c12_difnar','eg.v.c12_trisagion','eg.v.c12_synaxaire']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1203', 'eg', 12, 'Les hoos : chanter la Bible', 'Ce qu''est un hoos, ce que fait le lobsh, et les deux premiers cantiques : la mer Rouge et le psaume 135.', 1, 1203, 'eg.g1203.hoos_lobsh', array['eg.g1203.hoos_lobsh','eg.v.c12_hoos','eg.v.c12_lobsh','eg.v.c12_cantique_de_moise']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1204', 'eg', 12, 'Fournaise, victoire et doxologies', 'Les deux derniers hoos, l''histoire qu''ils racontent ensemble, et les chants de gloire pour la Vierge et les saints.', 1, 1204, 'eg.g1204.hoos_doxologies', array['eg.g1204.hoos_doxologies','eg.v.c12_doxologie','eg.v.c12_commemoraison_des_saints','eg.v.c12_cantique_des_trois_jeunes']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1205', 'eg', 12, 'Le psali et la théotokie : le Fils et sa Mère', 'Deux chants du jour : l''un loue le Christ, l''autre la Vierge Marie, avec des images de l''Ancien Testament pour dire l''incarnation.', 1, 1205, 'eg.g1205.psali_theotokie', array['eg.g1205.psali_theotokie','eg.v.c12_psali','eg.v.c12_theotokie','eg.v.c12_buisson_ardent']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1206', 'eg', 12, 'Adam et Watos : deux airs, sept jours', 'Quels jours sont Adam, quels jours sont Watos, et pourquoi ces deux noms : une leçon pas à pas.', 1, 1206, 'eg.g1206.adam_watos', array['eg.g1206.adam_watos','eg.v.c12_jours_adam','eg.v.c12_jours_watos','eg.v.c12_pibatos']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1207', 'eg', 12, 'Le soir, on prie déjà le lendemain', 'Pourquoi, le samedi à 20 h, on est déjà dimanche : la règle du soir, avec beaucoup de petits cas pour s''entraîner.', 1, 1207, 'eg.g1207.regle_du_soir', array['eg.g1207.regle_du_soir','eg.v.c12_jour_liturgique','eg.v.c12_regle_du_soir']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1208', 'eg', 12, 'Kiahk, le mois de Marie', 'Le mois où l''on loue la Vierge toute la nuit, et la grande tasbeha « sept et quatre ».', 1, 1208, 'eg.g1208.kiahk', array['eg.g1208.kiahk','eg.v.c12_kiahk','eg.v.c12_tasbeha_sept_et_quatre','eg.v.c12_jeune_de_la_nativite']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1209', 'eg', 12, 'Bilan : ta nuit de louange', 'La nuit de louange en entier : les étapes, les hoos, les chants du jour, les jours Adam et Watos, et la règle du soir.', 1, 1209, 'eg.g1209.bilan_tasbeha', array['eg.g1209.bilan_tasbeha']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1301', 'eg', 13, 'Treize mois, un seul fleuve', 'Un calendrier né du Nil, l''astuce du 10, et tes deux premiers mois : Tout et Baba.', 1, 1301, 'eg.g1301.treize_mois', array['eg.g1301.treize_mois','eg.v.c13_calendrier_solaire','eg.v.c13_regle_du_dix','eg.v.c13_tout','eg.v.c13_baba']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1302', 'eg', 13, 'Hatour, Kiahk et Touba', 'L''or du blé, le mois de Marie et le grand froid : trois mois, trois images.', 1, 1302, 'eg.g1302.hatour_kiahk_touba', array['eg.g1302.hatour_kiahk_touba','eg.v.c13_hatour','eg.v.c13_touba']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1303', 'eg', 13, 'Amshir, Baramhat et Baramouda', 'Le vent, puis la récolte, puis le battage du blé : la fin de l''hiver et le printemps.', 2, 1303, 'eg.g1303.vents_et_moisson', array['eg.g1303.vents_et_moisson','eg.v.c13_amshir','eg.v.c13_baramhat','eg.v.c13_baramouda']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1304', 'eg', 13, 'Bashans, Baouna et Abib', 'Le champ balayé, le Nil qui repart et le plein été.', 2, 1304, 'eg.g1304.chaleur_et_nil', array['eg.g1304.chaleur_et_nil','eg.v.c13_bashans','eg.v.c13_baouna','eg.v.c13_abib']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1305', 'eg', 13, 'Misra et Nasie : la boucle', 'La crue, le petit mois de 5 jours, et la boucle de l''année.', 2, 1305, 'eg.g1305.misra_nasie', array['eg.g1305.misra_nasie','eg.v.c13_misra','eg.v.c13_nasie','eg.v.c13_annee_bissextile_copte']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1306', 'eg', 13, 'Quel mois, quelle saison ?', 'Les trois saisons du Nil, et comment trouver le mois copte d''une date.', 3, 1306, 'eg.g1306.saisons_et_dates', array['eg.g1306.saisons_et_dates','eg.v.c13_trois_saisons','eg.v.c13_crue_du_nil']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1307', 'eg', 13, 'Bilan : les treize mois', 'Les treize dans l''ordre, les repères, les dates : tout le chapitre en un coup d''œil.', 3, 1307, 'eg.g1307.bilan_mois', array['eg.g1307.bilan_mois','eg.v.c13_treize_mois','eg.v.c13_proverbes_paysans']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1401', 'eg', 14, 'Moïse le Noir : du brigand au moine', 'Un chef de voleurs trouve refuge chez les moines et devient un père spirituel : personne n''est perdu.', 1, 1401, 'eg.g1401.moise_le_noir', array['eg.g1401.moise_le_noir','eg.v.c14_moise_le_noir','eg.v.c14_anba','eg.v.c14_apophtegmes']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1402', 'eg', 14, 'Jean le Petit et Arsène : obéir, se taire', 'Un bâton sec qui donne des fruits, un précepteur d''empereurs qui choisit le silence.', 1, 1402, 'eg.g1402.jean_arsene', array['eg.g1402.jean_arsene','eg.v.c14_jean_le_petit','eg.v.c14_arsene','eg.v.c14_obeissance']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1403', 'eg', 14, 'Bishoy, et les deux princes de Baramous', 'Un moine qui s''attache les cheveux au plafond, un vieillard porté sur les épaules, deux princes devenus moines.', 1, 1403, 'eg.g1403.bishoy_princes', array['eg.g1403.bishoy_princes','eg.v.c14_bishoy','eg.v.c14_maxime_domece','eg.v.c14_hospitalite','eg.v.c14_baramous']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1404', 'eg', 14, 'Samuel le Confesseur : battu, mais debout', 'Un moine refuse Chalcédoine, est battu et chassé, et fonde Qalamoun.', 1, 1404, 'eg.g1404.samuel', array['eg.g1404.samuel','eg.v.c14_samuel','eg.v.c14_qalamoun']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1405', 'eg', 14, 'Mina et ses petites gourdes de pèlerins', 'Un soldat d''Égypte, un chameau qui s''arrête, une ville de pèlerinage et des ampoules d''huile bénite.', 1, 1405, 'eg.g1405.mina', array['eg.g1405.mina','eg.v.c14_saint_mina','eg.v.c14_abou_mina','eg.v.c14_ampoule','eg.v.c14_maryut']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1406', 'eg', 14, 'Abou Sefein et ses deux épées, Georges et son dragon', 'Deux saints soldats qu''on ne confond plus : celui aux deux épées et celui au dragon.', 1, 1406, 'eg.g1406.mercure_georges', array['eg.g1406.mercure_georges','eg.v.c14_saint_soldat','eg.v.c14_abou_sefein','eg.v.c14_prince_des_martyrs']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1407', 'eg', 14, 'Abanoub, Démiana et les quarante vierges', 'Un enfant de douze ans devant le gouverneur, une fille de gouverneur et ses quarante compagnes.', 1, 1407, 'eg.g1407.abanoub_demiana', array['eg.g1407.abanoub_demiana','eg.v.c14_abanoub','eg.v.c14_demiana','eg.v.c14_quarante_vierges']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1408', 'eg', 14, 'Catherine et la roue, Barbara et la tour', 'Deux jeunes saintes très aimées dont les récits viennent de la tradition : comment les lire.', 1, 1408, 'eg.g1408.catherine_barbara', array['eg.g1408.catherine_barbara','eg.v.c14_hagiographie','eg.v.c14_catherine','eg.v.c14_barbara']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1409', 'eg', 14, 'Marie l''Égyptienne : on peut toujours revenir', 'Une vie de péché à Alexandrie, une porte qui ne s''ouvre pas, un lion qui creuse une tombe.', 1, 1409, 'eg.g1409.marie_egyptienne', array['eg.g1409.marie_egyptienne','eg.v.c14_marie_egyptienne','eg.v.c14_zosime']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1410', 'eg', 14, 'Marina déguisée en moine, Anastasie à la cour', 'Deux saintes cachées parmi les moines : une accusation injuste, une fuite devant l''impératrice.', 1, 1410, 'eg.g1410.marina_anastasie', array['eg.g1410.marina_anastasie','eg.v.c14_marina','eg.v.c14_anastasie','eg.v.c14_moniale_deguisee']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1411', 'eg', 14, 'La légion thébaine et Verena : des Égyptiens en Suisse', 'Des soldats de Haute-Égypte massacrés à Agaune et une soignante venue d''Égypte qui s''installe en Suisse.', 1, 1411, 'eg.g1411.legion_verena', array['eg.g1411.legion_verena','eg.v.c14_legion_thebaine','eg.v.c14_verena']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1412', 'eg', 14, 'Simon le Tanneur et la montagne du Mokattam', 'Un pape marchand, un tanneur borgne, et une montagne qui bouge sous le regard du calife.', 1, 1412, 'eg.g1412.abraam_simon', array['eg.g1412.abraam_simon','eg.v.c14_abraam_ibn_zaraa','eg.v.c14_simon_tanneur','eg.v.c14_mokattam']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1413', 'eg', 14, 'Barsoum le Nu et Anba Abraam : tout donner', 'Un ermite qui n''a qu''une peau de chèvre et un évêque qui donne ses revenus aux pauvres.', 1, 1413, 'eg.g1413.barsoum_abraam', array['eg.g1413.barsoum_abraam','eg.v.c14_barsoum','eg.v.c14_anba_abraam','eg.v.c14_canonisation']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1414', 'eg', 14, 'Cyrille IV et Habib Guirguis : le livre et l''école', 'Un pape qui installe une imprimerie, un laïc qui rassemble les enfants le dimanche.', 1, 1414, 'eg.g1414.cyrille_iv_habib', array['eg.g1414.cyrille_iv_habib','eg.v.c14_cyrille_iv','eg.v.c14_habib_guirguis','eg.v.c14_ecoles_du_dimanche']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1415', 'eg', 14, 'Cyrille VI dans son moulin, Chenouda III le maître', 'Un moine de prière devenu pape ramène saint Marc au Caire ; un professeur devenu pape enseigne chaque mercredi.', 1, 1415, 'eg.g1415.cyrille_vi_chenouda', array['eg.g1415.cyrille_vi_chenouda','eg.v.c14_cyrille_vi','eg.v.c14_moulin']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1416', 'eg', 14, 'Les 21 martyrs de Libye', 'Quinze février 2015 : vingt Coptes et un Ghanaïen refusent de renier le Christ.', 1, 1416, 'eg.g1416.martyrs_libye', array['eg.g1416.martyrs_libye','eg.v.c14_martyrs_de_libye','eg.v.c14_matthieu','eg.v.c14_al_our']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1417', 'eg', 14, 'Bilan : qui a fait quoi', 'La frise des saints, les cinq familles, les pièges à éviter et ce qu''on peut savoir avec certitude.', 1, 1417, 'eg.g1417.bilan_saints', array['eg.g1417.bilan_saints','eg.v.c14_reliques','eg.v.c14_saint_patron','eg.v.c14_communion_des_saints']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1501', 'eg', 15, 'Le copte, langue des pharaons', 'Le copte est de l''égyptien écrit avec des lettres grecques : d''où il vient, comment le reconnaître, pourquoi l''Église l''a gardé.', 1, 1501, 'eg.g1501.langue_des_pharaons', array['eg.g1501.langue_des_pharaons','eg.v.cop_nouti','eg.v.cop_ran','eg.v.cop_iot','eg.v.cop_shiri']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1502', 'eg', 15, 'Les mots grecs que tu connais', 'Ange, évangile, église, vierge : ces mots du copte sont grecs, et le français les a gardés.', 1, 1502, 'eg.g1502.mots_grecs', array['eg.g1502.mots_grecs','eg.v.cop_angelos','eg.v.cop_euangelion','eg.v.cop_ekklesia','eg.v.cop_parthenos']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1503', 'eg', 15, 'La jinkim : le petit trait qui se lit', 'Le petit trait sur certaines lettres ne change pas le sens : il te dit comment lire.', 1, 1503, 'eg.g1503.jinkim', array['eg.g1503.jinkim','eg.v.cop_jinkim','eg.v.cop_nte','eg.v.cop_evol','eg.v.cop_agape']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1504', 'eg', 15, 'Les noms sacrés abrégés', 'La barre au-dessus de plusieurs lettres : ⲓ̅ⲏ̅ⲥ̅, ⲭ̅ⲥ̅, ⲡ̅ⲟ̅ⲥ̅, ⲫ̅ϯ̅, et pourquoi on les abrège.', 2, 1504, 'eg.g1504.nomina_sacra', array['eg.g1504.nomina_sacra','eg.v.cop_iesous','eg.v.cop_khristos','eg.v.cop_pchois','eg.v.cop_phnouti']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1505', 'eg', 15, 'Les articles : le, la, les, un', 'Détacher l''article pour comprendre un mot : ⲡⲓ, ϯ, ⲛⲓ, ⲟⲩ, ϩⲁⲛ, et le piège de ⲫ̀.', 2, 1505, 'eg.g1505.articles', array['eg.g1505.articles','eg.v.cop_pi','eg.v.cop_ti','eg.v.cop_ni','eg.v.cop_ou']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1506', 'eg', 15, 'Mon, ton, notre : les possessifs', 'Ⲡⲉⲛⲓⲱⲧ, ⲡⲁⲛⲟⲩϯ, ⲡⲉⲕⲣⲁⲛ : comment se construit « mon, ton, son, notre ».', 2, 1506, 'eg.g1506.possessifs', array['eg.g1506.possessifs','eg.v.cop_pa','eg.v.cop_pek','eg.v.cop_pef','eg.v.cop_pen']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1507', 'eg', 15, 'Les petits mots : et, dans, de, saint', 'Quatre petits mots (ⲛⲉⲙ, ϧⲉⲛ, ⲛ̀/ⲙ̀, ⲉⲑⲟⲩⲁⲃ) qui structurent presque chaque phrase.', 3, 1507, 'eg.g1507.petits_mots', array['eg.g1507.petits_mots','eg.v.cop_nem','eg.v.cop_hen','eg.v.cop_n_de','eg.v.cop_ethouab']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1508', 'eg', 15, 'Il est ressuscité : le passé', 'Le passé ⲁϥ-, ⲁⲥ-, ⲁⲩ-, et le sens mot à mot de ⲁϥⲧⲱⲛϥ, le cri de Pâques.', 3, 1508, 'eg.g1508.passe_paques', array['eg.g1508.passe_paques','eg.v.cop_af','eg.v.cop_ton','eg.v.cop_alithos']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1509', 'eg', 15, 'Je crois, bénis : le présent et l''ordre', 'ϯ- qui veut dire « je », le verbe nu qui donne l''ordre, et les premiers mots du Credo.', 3, 1509, 'eg.g1509.je_crois_benis', array['eg.g1509.je_crois_benis','eg.v.cop_ti_je','eg.v.cop_nahti','eg.v.cop_smou']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1510', 'eg', 15, 'Père, Fils, Esprit : la formule du signe de croix', 'Les trois noms divins décortiqués, puis la formule « au nom du Père, du Fils et du Saint-Esprit » lue mot à mot.', 3, 1510, 'eg.g1510.formule_trinite', array['eg.g1510.formule_trinite','eg.v.cop_phiot','eg.v.cop_pshiri','eg.v.cop_pnevma','eg.v.cop_phran']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1511', 'eg', 15, 'Trinité, roi, Tout-Puissant, Sauveur', 'Quatre titres de Dieu que tu entends dans les hymnes, décomposés mot à mot.', 3, 1511, 'eg.g1511.titres_de_dieu', array['eg.g1511.titres_de_dieu','eg.v.cop_trias','eg.v.cop_ouro','eg.v.cop_pantokrator','eg.v.cop_soter']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1512', 'eg', 15, 'La Vierge Marie : titres et salut', 'ϯⲡⲁⲣⲑⲉⲛⲟⲥ, ϯⲑⲉⲟⲧⲟⲕⲟⲥ, ⲭⲉⲣⲉ : le sens des mots que tu chantes à la Vierge.', 3, 1512, 'eg.g1512.vierge_marie', array['eg.g1512.vierge_marie','eg.v.cop_maria','eg.v.cop_theotokos','eg.v.cop_khere']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1513', 'eg', 15, 'Les saints et leurs intercessions', 'Apôtres, martyrs, saints, intercessions : le sens des mots et la formule « par les intercessions de… » mot à mot.', 3, 1513, 'eg.g1513.saints_intercession', array['eg.g1513.saints_intercession','eg.v.cop_hiten','eg.v.cop_martyros','eg.v.cop_agios','eg.v.cop_presbia']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1514', 'eg', 15, 'Amen, alléluia, la paix à tous', 'Quatre réponses de la messe : leur sens, leur langue (hébreu, grec ou copte).', 3, 1514, 'eg.g1514.amen_paix', array['eg.g1514.amen_paix','eg.v.cop_amin','eg.v.cop_alleluia','eg.v.cop_sha_enah','eg.v.cop_irini']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('eg.l1515', 'eg', 15, 'Aie pitié, gloire à toi : grec ou copte', 'Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ et ⲛⲁⲓ ⲛⲁⲛ, Ⲇⲟⲝⲁ ⲥⲓ Ⲕⲩⲣⲓⲉ et ⲡⲓⲱⲟⲩ : la même prière dite en deux langues.', 3, 1515, 'eg.g1515.pitie_gloire', array['eg.g1515.pitie_gloire','eg.v.cop_kyrie','eg.v.cop_nai','eg.v.cop_doxa','eg.v.cop_iwou']::text[], '{}'::text[], '1.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
