insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l101.e02', 'eg', 'eg.l101', 'eg.g101.pentecote', array['eg.g101.pentecote']::text[], 'mcq', 'lesson', 'Ils sont combien, à peu près, dans cette salle ?', array['environ cent vingt']::text[], 'Cent vingt personnes : toute l''Église tient alors dans une pièce.', 1, '{"id": "eg.l101.e02", "unitIds": ["eg.g101.pentecote"], "type": "mcq", "difficulty": 1, "prompt": "Ils sont combien, à peu près, dans cette salle ?", "promptLanguage": "fr", "answer": "environ cent vingt", "acceptedAnswers": ["environ cent vingt"], "explanation": "Cent vingt personnes : toute l''Église tient alors dans une pièce.", "instruction": "Choisis la bonne réponse.", "step": 1, "options": ["douze", "environ cent vingt", "trois mille"], "pool": "lesson", "lessonId": "eg.l101", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l101.e03', 'eg', 'eg.l101', 'eg.g101.pentecote', array['eg.g101.pentecote','eg.v.pentecote']::text[], 'mcq', 'lesson', 'Que veut dire le mot « Pentecôte » ?', array['cinquantième']::text[], 'Cinquante jours après Pâques. Pense à « penta », cinq.', 1, '{"id": "eg.l101.e03", "unitIds": ["eg.g101.pentecote", "eg.v.pentecote"], "type": "mcq", "difficulty": 1, "prompt": "Que veut dire le mot « Pentecôte » ?", "promptLanguage": "fr", "answer": "cinquantième", "acceptedAnswers": ["cinquantième"], "explanation": "Cinquante jours après Pâques. Pense à « penta », cinq.", "instruction": "Choisis la bonne réponse.", "step": 2, "options": ["cinquantième", "feu", "envoyé"], "pool": "lesson", "lessonId": "eg.l101", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
