insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l102.e02', 'eg', 'eg.l102', 'eg.g102.communaute', array['eg.g102.communaute','eg.v.c01_premiere_communaute']::text[], 'mcq', 'lesson', 'Combien de croyants y a-t-il à Jérusalem, environ ?', array['cinq mille']::text[], 'On est passé de 120 dans la chambre à 5 000 croyants.', 1, '{"unitIds": ["eg.g102.communaute", "eg.v.c01_premiere_communaute"], "type": "mcq", "difficulty": 1, "prompt": "Combien de croyants y a-t-il à Jérusalem, environ ?", "answer": "cinq mille", "explanation": "On est passé de 120 dans la chambre à 5 000 croyants.", "instruction": "Choisis la bonne réponse.", "options": ["trois mille", "cinq mille", "cent vingt"], "step": 1, "id": "eg.l102.e02", "promptLanguage": "fr", "acceptedAnswers": ["cinq mille"], "pool": "lesson", "lessonId": "eg.l102", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l102.e03', 'eg', 'eg.l102', 'eg.g102.communaute', array['eg.g102.communaute','eg.v.c01_fraction_du_pain']::text[], 'mcq', 'lesson', 'Comment les premiers chrétiens appellent-ils l''eucharistie ?', array['la fraction du pain']::text[], 'Rompre le pain, c''est le geste de Jésus à la dernière Cène.', 1, '{"unitIds": ["eg.g102.communaute", "eg.v.c01_fraction_du_pain"], "type": "mcq", "difficulty": 1, "prompt": "Comment les premiers chrétiens appellent-ils l''eucharistie ?", "answer": "la fraction du pain", "explanation": "Rompre le pain, c''est le geste de Jésus à la dernière Cène.", "instruction": "Choisis la bonne réponse.", "options": ["la fête de la Pentecôte", "la prière du matin", "la fraction du pain"], "step": 2, "id": "eg.l102.e03", "promptLanguage": "fr", "acceptedAnswers": ["la fraction du pain"], "pool": "lesson", "lessonId": "eg.l102", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
