insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l102.e05', 'eg', 'eg.l102', 'eg.g102.communaute', array['eg.g102.communaute']::text[], 'fill_blank', 'lesson', 'Parmi les pèlerins de la Pentecôte, il y a des gens d''___.', array['Égypte']::text[], 'Retiens-le : l''Égypte est présente dès le premier jour, bien avant saint Marc.', 1, '{"unitIds": ["eg.g102.communaute"], "type": "fill_blank", "difficulty": 1, "prompt": "Parmi les pèlerins de la Pentecôte, il y a des gens d''___.", "answer": "Égypte", "explanation": "Retiens-le : l''Égypte est présente dès le premier jour, bien avant saint Marc.", "instruction": "Complète la phrase.", "options": ["Rome", "Égypte", "Grèce"], "step": 3, "id": "eg.l102.e05", "promptLanguage": "fr", "acceptedAnswers": ["Égypte"], "pool": "lesson", "lessonId": "eg.l102", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l102.e06', 'eg', 'eg.l102', 'eg.g102.communaute', array['eg.g102.communaute']::text[], 'fill_blank', 'lesson', 'Les premiers chrétiens sont tous ___.', array['juifs']::text[], 'Jésus et les apôtres sont juifs : l''Église naît dans le judaïsme.', 1, '{"unitIds": ["eg.g102.communaute"], "type": "fill_blank", "difficulty": 1, "prompt": "Les premiers chrétiens sont tous ___.", "answer": "juifs", "explanation": "Jésus et les apôtres sont juifs : l''Église naît dans le judaïsme.", "instruction": "Complète la phrase.", "options": ["romains", "grecs", "juifs"], "step": 4, "id": "eg.l102.e06", "promptLanguage": "fr", "acceptedAnswers": ["juifs"], "pool": "lesson", "lessonId": "eg.l102", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l102.e07', 'eg', 'eg.l102', 'eg.g102.communaute', array['eg.g102.communaute','eg.g101.pentecote']::text[], 'match', 'lesson', 'Chaque nombre a sa scène.', '{}'::text[], '120, puis 3 000 baptisés, puis environ 5 000 croyants : l''Église grandit très vite.', 2, '{"unitIds": ["eg.g102.communaute", "eg.g101.pentecote"], "type": "match", "difficulty": 2, "prompt": "Chaque nombre a sa scène.", "explanation": "120, puis 3 000 baptisés, puis environ 5 000 croyants : l''Église grandit très vite.", "instruction": "Associe.", "pairs": [{"left": "cent vingt", "right": "les disciples dans la chambre haute"}, {"left": "trois mille", "right": "les baptisés de la Pentecôte"}, {"left": "cinq mille", "right": "les croyants de la première communauté"}], "id": "eg.l102.e07", "promptLanguage": "fr", "acceptedAnswers": [], "pool": "lesson", "lessonId": "eg.l102", "skill": "recognition", "answer": "cent vingt = les disciples dans la chambre haute ; trois mille = les baptisés de la Pentecôte ; cinq mille = les croyants de la première communauté"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l102.e08', 'eg', 'eg.l102', 'eg.g102.communaute', array['eg.g102.communaute','eg.g101.pentecote']::text[], 'reorder', 'lesson', 'Remets les moments dans l''ordre.', array['prière Pentecôte baptêmes partage']::text[], 'D''abord la prière, puis le feu, puis les baptêmes, puis la vie de partage.', 2, '{"unitIds": ["eg.g102.communaute", "eg.g101.pentecote"], "type": "reorder", "difficulty": 2, "prompt": "Remets les moments dans l''ordre.", "answer": "prière Pentecôte baptêmes partage", "explanation": "D''abord la prière, puis le feu, puis les baptêmes, puis la vie de partage.", "instruction": "Remets dans l''ordre.", "tokens": ["prière", "partage", "baptêmes", "Pentecôte"], "id": "eg.l102.e08", "promptLanguage": "fr", "acceptedAnswers": ["prière Pentecôte baptêmes partage"], "pool": "lesson", "lessonId": "eg.l102", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l102.e09', 'eg', 'eg.l102', 'eg.g102.communaute', array['eg.g102.communaute','eg.v.c01_premiere_communaute']::text[], 'fill_blank', 'lesson', 'Les croyants sont fidèles à l''enseignement des apôtres, à la communion fraternelle, à la fraction du pain et aux ___.', array['prières']::text[], 'Quatre habitudes : enseigner, vivre en frères, rompre le pain, prier.', 2, '{"unitIds": ["eg.g102.communaute", "eg.v.c01_premiere_communaute"], "type": "fill_blank", "difficulty": 2, "prompt": "Les croyants sont fidèles à l''enseignement des apôtres, à la communion fraternelle, à la fraction du pain et aux ___.", "answer": "prières", "explanation": "Quatre habitudes : enseigner, vivre en frères, rompre le pain, prier.", "instruction": "Complète la phrase.", "options": ["impôts", "voyages", "prières"], "id": "eg.l102.e09", "promptLanguage": "fr", "acceptedAnswers": ["prières"], "pool": "lesson", "lessonId": "eg.l102", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l102.e10', 'eg', 'eg.l102', 'eg.g101.pentecote', array['eg.g101.pentecote','eg.v.c01_saint_pierre']::text[], 'mcq', 'lesson', 'Quel apôtre prêche le jour de la Pentecôte, avant que la communauté ne grandisse ?', array['Pierre']::text[], 'Pierre, celui qui avait renié Jésus, ouvre la porte et parle à la foule.', 2, '{"unitIds": ["eg.g101.pentecote", "eg.v.c01_saint_pierre"], "type": "mcq", "difficulty": 2, "prompt": "Quel apôtre prêche le jour de la Pentecôte, avant que la communauté ne grandisse ?", "answer": "Pierre", "explanation": "Pierre, celui qui avait renié Jésus, ouvre la porte et parle à la foule.", "instruction": "Choisis la bonne réponse.", "options": ["Pierre", "Jacques", "Barnabé"], "id": "eg.l102.e10", "promptLanguage": "fr", "acceptedAnswers": ["Pierre"], "pool": "lesson", "lessonId": "eg.l102", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l102.e11', 'eg', 'eg.l102', 'eg.g102.communaute', array['eg.g102.communaute','eg.v.c01_premiere_communaute']::text[], 'mcq', 'lesson', 'Pourquoi la communauté de Jérusalem sert-elle de modèle à l''Église ?', array['Elle prie, partage et reste unie']::text[], 'Prière, partage, union : c''est ce que l''Église cherchera toujours à vivre.', 3, '{"unitIds": ["eg.g102.communaute", "eg.v.c01_premiere_communaute"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi la communauté de Jérusalem sert-elle de modèle à l''Église ?", "answer": "Elle prie, partage et reste unie", "explanation": "Prière, partage, union : c''est ce que l''Église cherchera toujours à vivre.", "instruction": "Choisis la bonne réponse.", "options": ["Elle est la plus riche de la ville", "Elle vit loin de toutes les villes", "Elle prie, partage et reste unie", "Elle n''a besoin de personne"], "id": "eg.l102.e11", "promptLanguage": "fr", "acceptedAnswers": ["Elle prie, partage et reste unie"], "pool": "lesson", "lessonId": "eg.l102", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l102.e12', 'eg', 'eg.l102', 'eg.g101.pentecote', array['eg.g101.pentecote','eg.v.chambre_haute']::text[], 'mcq', 'lesson', 'Dans quelle ville la petite communauté de la chambre haute devient-elle une foule de croyants ?', array['Jérusalem']::text[], 'Toujours Jérusalem : l''Église n''en sortira que plus tard.', 2, '{"unitIds": ["eg.g101.pentecote", "eg.v.chambre_haute"], "type": "mcq", "difficulty": 2, "prompt": "Dans quelle ville la petite communauté de la chambre haute devient-elle une foule de croyants ?", "answer": "Jérusalem", "explanation": "Toujours Jérusalem : l''Église n''en sortira que plus tard.", "instruction": "Choisis la bonne réponse.", "options": ["Rome", "Alexandrie", "Jérusalem"], "id": "eg.l102.e12", "promptLanguage": "fr", "acceptedAnswers": ["Jérusalem"], "pool": "lesson", "lessonId": "eg.l102", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l103.e01', 'eg', 'eg.l103', 'eg.g103.etienne', array['eg.g103.etienne','eg.v.c01_helleniste']::text[], 'mcq', 'lesson', 'Qui se plaint que ses veuves soient oubliées ?', array['les hellénistes']::text[], 'Les hellénistes sont des chrétiens de langue grecque : ils se sentaient moins bien servis.', 1, '{"unitIds": ["eg.g103.etienne", "eg.v.c01_helleniste"], "type": "mcq", "difficulty": 1, "prompt": "Qui se plaint que ses veuves soient oubliées ?", "answer": "les hellénistes", "explanation": "Les hellénistes sont des chrétiens de langue grecque : ils se sentaient moins bien servis.", "instruction": "Choisis la bonne réponse.", "options": ["les hellénistes", "les pharisiens", "les soldats romains"], "step": 1, "id": "eg.l103.e01", "promptLanguage": "fr", "acceptedAnswers": ["les hellénistes"], "pool": "lesson", "lessonId": "eg.l103", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
