insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l103.e04', 'eg', 'eg.l103', 'eg.g103.etienne', array['eg.g103.etienne','eg.v.c01_saint_etienne']::text[], 'mcq', 'lesson', 'Vers quelle année Étienne est-il lapidé ?', array['35']::text[], 'Vers 35 : quelques années seulement après la Pentecôte.', 2, '{"unitIds": ["eg.g103.etienne", "eg.v.c01_saint_etienne"], "type": "mcq", "difficulty": 2, "prompt": "Vers quelle année Étienne est-il lapidé ?", "answer": "35", "explanation": "Vers 35 : quelques années seulement après la Pentecôte.", "instruction": "Choisis la bonne réponse.", "options": ["35", "325", "1054"], "step": 2, "id": "eg.l103.e04", "promptLanguage": "fr", "acceptedAnswers": ["35"], "pool": "lesson", "lessonId": "eg.l103", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l103.e05', 'eg', 'eg.l103', 'eg.g103.etienne', array['eg.g103.etienne']::text[], 'mcq', 'lesson', 'Quel jeune pharisien approuve la mort d''Étienne ?', array['Saul']::text[], 'Saul est celui qui deviendra l''apôtre Paul : la suite au prochain épisode !', 1, '{"unitIds": ["eg.g103.etienne"], "type": "mcq", "difficulty": 1, "prompt": "Quel jeune pharisien approuve la mort d''Étienne ?", "answer": "Saul", "explanation": "Saul est celui qui deviendra l''apôtre Paul : la suite au prochain épisode !", "instruction": "Choisis la bonne réponse.", "options": ["Pierre", "Saul", "Marc"], "step": 3, "id": "eg.l103.e05", "promptLanguage": "fr", "acceptedAnswers": ["Saul"], "pool": "lesson", "lessonId": "eg.l103", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l103.e06', 'eg', 'eg.l103', 'eg.g103.etienne', array['eg.g103.etienne']::text[], 'mcq', 'lesson', 'Que provoque la persécution qui suit la mort d''Étienne ?', array['l''Évangile sort de Jérusalem']::text[], 'Les chrétiens dispersés emportent l''Évangile avec eux.', 1, '{"unitIds": ["eg.g103.etienne"], "type": "mcq", "difficulty": 1, "prompt": "Que provoque la persécution qui suit la mort d''Étienne ?", "answer": "l''Évangile sort de Jérusalem", "explanation": "Les chrétiens dispersés emportent l''Évangile avec eux.", "instruction": "Choisis la bonne réponse.", "options": ["l''Église disparaît de la ville", "les chrétiens deviennent romains", "l''Évangile sort de Jérusalem"], "step": 4, "id": "eg.l103.e06", "promptLanguage": "fr", "acceptedAnswers": ["l''Évangile sort de Jérusalem"], "pool": "lesson", "lessonId": "eg.l103", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l103.e07', 'eg', 'eg.l103', 'eg.g103.etienne', array['eg.g103.etienne']::text[], 'match', 'lesson', 'Chacun son rôle dans cette histoire.', '{}'::text[], 'Une dispute, un martyr, un jeune pharisien : trois noms pour retenir l''épisode.', 2, '{"unitIds": ["eg.g103.etienne"], "type": "match", "difficulty": 2, "prompt": "Chacun son rôle dans cette histoire.", "explanation": "Une dispute, un martyr, un jeune pharisien : trois noms pour retenir l''épisode.", "instruction": "Associe.", "pairs": [{"left": "les hellénistes", "right": "se plaignent pour leurs veuves"}, {"left": "Étienne", "right": "le premier martyr"}, {"left": "Saul", "right": "approuve la mort d''Étienne"}], "id": "eg.l103.e07", "promptLanguage": "fr", "acceptedAnswers": [], "pool": "lesson", "lessonId": "eg.l103", "skill": "recognition", "answer": "les hellénistes = se plaignent pour leurs veuves ; Étienne = le premier martyr ; Saul = approuve la mort d''Étienne"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l103.e08', 'eg', 'eg.l103', 'eg.g103.etienne', array['eg.g103.etienne']::text[], 'reorder', 'lesson', 'Remets l''épisode dans l''ordre.', array['dispute choix lapidation dispersion']::text[], 'Une dispute, sept hommes choisis, Étienne lapidé, puis les chrétiens se dispersent.', 2, '{"unitIds": ["eg.g103.etienne"], "type": "reorder", "difficulty": 2, "prompt": "Remets l''épisode dans l''ordre.", "answer": "dispute choix lapidation dispersion", "explanation": "Une dispute, sept hommes choisis, Étienne lapidé, puis les chrétiens se dispersent.", "instruction": "Remets dans l''ordre.", "tokens": ["lapidation", "dispersion", "choix", "dispute"], "id": "eg.l103.e08", "promptLanguage": "fr", "acceptedAnswers": ["dispute choix lapidation dispersion"], "pool": "lesson", "lessonId": "eg.l103", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l103.e09', 'eg', 'eg.l103', 'eg.g103.etienne', array['eg.g103.etienne','eg.v.c01_helleniste']::text[], 'mcq', 'lesson', 'Pourquoi les apôtres font-ils choisir sept hommes pour le service ?', array['Pour rester libres de prêcher']::text[], 'Chacun son service : les apôtres prêchent, les sept s''occupent des veuves.', 3, '{"unitIds": ["eg.g103.etienne", "eg.v.c01_helleniste"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi les apôtres font-ils choisir sept hommes pour le service ?", "answer": "Pour rester libres de prêcher", "explanation": "Chacun son service : les apôtres prêchent, les sept s''occupent des veuves.", "instruction": "Choisis la bonne réponse.", "options": ["Pour rester libres de prêcher", "Pour avoir moins de croyants", "Pour quitter Jérusalem", "Pour éviter les soldats romains"], "id": "eg.l103.e09", "promptLanguage": "fr", "acceptedAnswers": ["Pour rester libres de prêcher"], "pool": "lesson", "lessonId": "eg.l103", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l103.e10', 'eg', 'eg.l103', 'eg.g101.pentecote', array['eg.g101.pentecote','eg.v.apotre']::text[], 'mcq', 'lesson', 'Les apôtres confient le service à sept hommes. Que veut dire « apôtre » ?', array['envoyé']::text[], 'Apôtre = envoyé ; martyr = témoin. Deux mots grecs à ne pas mélanger.', 2, '{"unitIds": ["eg.g101.pentecote", "eg.v.apotre"], "type": "mcq", "difficulty": 2, "prompt": "Les apôtres confient le service à sept hommes. Que veut dire « apôtre » ?", "answer": "envoyé", "explanation": "Apôtre = envoyé ; martyr = témoin. Deux mots grecs à ne pas mélanger.", "instruction": "Choisis la bonne réponse.", "options": ["envoyé", "témoin", "lapidé"], "id": "eg.l103.e10", "promptLanguage": "fr", "acceptedAnswers": ["envoyé"], "pool": "lesson", "lessonId": "eg.l103", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l103.e11', 'eg', 'eg.l103', 'eg.g102.communaute', array['eg.g102.communaute','eg.v.c01_fraction_du_pain']::text[], 'mcq', 'lesson', 'Les chrétiens de Jérusalem célèbrent la fraction du pain. De quoi s''agit-il ?', array['l''eucharistie']::text[], 'Fraction du pain = eucharistie : le repas de Jésus.', 2, '{"unitIds": ["eg.g102.communaute", "eg.v.c01_fraction_du_pain"], "type": "mcq", "difficulty": 2, "prompt": "Les chrétiens de Jérusalem célèbrent la fraction du pain. De quoi s''agit-il ?", "answer": "l''eucharistie", "explanation": "Fraction du pain = eucharistie : le repas de Jésus.", "instruction": "Choisis la bonne réponse.", "options": ["le baptême", "l''eucharistie", "la lapidation"], "id": "eg.l103.e11", "promptLanguage": "fr", "acceptedAnswers": ["l''eucharistie"], "pool": "lesson", "lessonId": "eg.l103", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l103.e12', 'eg', 'eg.l103', 'eg.g103.etienne', array['eg.g103.etienne','eg.v.c01_martyr']::text[], 'fill_blank', 'lesson', 'Étienne est le premier ___ chrétien.', array['martyr']::text[], 'Il meurt pour avoir témoigné du Christ.', 2, '{"unitIds": ["eg.g103.etienne", "eg.v.c01_martyr"], "type": "fill_blank", "difficulty": 2, "prompt": "Étienne est le premier ___ chrétien.", "answer": "martyr", "explanation": "Il meurt pour avoir témoigné du Christ.", "instruction": "Complète la phrase.", "options": ["apôtre", "évêque", "martyr"], "id": "eg.l103.e12", "promptLanguage": "fr", "acceptedAnswers": ["martyr"], "pool": "lesson", "lessonId": "eg.l103", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l103.e13', 'eg', 'eg.l103', 'eg.g103.etienne', array['eg.g103.etienne']::text[], 'mcq', 'lesson', 'Pourquoi dit-on que la mort d''Étienne a « semé » l''Église ?', array['Les chrétiens emportent l''Évangile ailleurs']::text[], 'Comme des graines emportées par le vent, les chrétiens font naître des communautés partout.', 3, '{"unitIds": ["eg.g103.etienne"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi dit-on que la mort d''Étienne a « semé » l''Église ?", "answer": "Les chrétiens emportent l''Évangile ailleurs", "explanation": "Comme des graines emportées par le vent, les chrétiens font naître des communautés partout.", "instruction": "Choisis la bonne réponse.", "options": ["Les chrétiens emportent l''Évangile ailleurs", "Les chrétiens deviennent tous des agriculteurs", "Les Romains construisent des églises", "Les apôtres s''enfuient tous en Égypte"], "id": "eg.l103.e13", "promptLanguage": "fr", "acceptedAnswers": ["Les chrétiens emportent l''Évangile ailleurs"], "pool": "lesson", "lessonId": "eg.l103", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
