insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l104.e05', 'eg', 'eg.l104', 'eg.g104.paul', array['eg.g104.paul','eg.v.c01_saint_barnabe']::text[], 'mcq', 'lesson', 'Qui accueille Paul auprès des apôtres de Jérusalem ?', array['Barnabé']::text[], 'Barnabé fait confiance à Paul quand les autres hésitent.', 1, '{"unitIds": ["eg.g104.paul", "eg.v.c01_saint_barnabe"], "type": "mcq", "difficulty": 1, "prompt": "Qui accueille Paul auprès des apôtres de Jérusalem ?", "answer": "Barnabé", "explanation": "Barnabé fait confiance à Paul quand les autres hésitent.", "instruction": "Choisis la bonne réponse.", "options": ["Marc", "Barnabé", "Jacques"], "step": 3, "id": "eg.l104.e05", "promptLanguage": "fr", "acceptedAnswers": ["Barnabé"], "pool": "lesson", "lessonId": "eg.l104", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l104.e06', 'eg', 'eg.l104', 'eg.g104.paul', array['eg.g104.paul']::text[], 'mcq', 'lesson', 'Où Paul annonce-t-il l''Évangile en premier, dans chaque ville ?', array['la synagogue']::text[], 'Les Juifs y connaissent déjà les Écritures : le terrain est préparé.', 1, '{"unitIds": ["eg.g104.paul"], "type": "mcq", "difficulty": 1, "prompt": "Où Paul annonce-t-il l''Évangile en premier, dans chaque ville ?", "answer": "la synagogue", "explanation": "Les Juifs y connaissent déjà les Écritures : le terrain est préparé.", "instruction": "Choisis la bonne réponse.", "options": ["la chambre haute", "le port", "la synagogue"], "step": 4, "id": "eg.l104.e06", "promptLanguage": "fr", "acceptedAnswers": ["la synagogue"], "pool": "lesson", "lessonId": "eg.l104", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l104.e07', 'eg', 'eg.l104', 'eg.g104.paul', array['eg.g104.paul']::text[], 'mcq', 'lesson', 'Que veut dire « païens » ?', array['les non-juifs']::text[], 'Les païens sont ceux qui ne connaissent pas le Dieu d''Israël.', 1, '{"unitIds": ["eg.g104.paul"], "type": "mcq", "difficulty": 1, "prompt": "Que veut dire « païens » ?", "answer": "les non-juifs", "explanation": "Les païens sont ceux qui ne connaissent pas le Dieu d''Israël.", "instruction": "Choisis la bonne réponse.", "options": ["les non-juifs", "les prêtres du Temple", "les soldats romains"], "step": 4, "id": "eg.l104.e07", "promptLanguage": "fr", "acceptedAnswers": ["les non-juifs"], "pool": "lesson", "lessonId": "eg.l104", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l104.e08', 'eg', 'eg.l104', 'eg.g104.paul', array['eg.g104.paul','eg.v.c01_antioche']::text[], 'mcq', 'lesson', 'Dans quelle ville appelle-t-on les disciples « chrétiens » pour la première fois ?', array['Antioche']::text[], 'Antioche : c''est là que le nom « chrétiens » apparaît.', 1, '{"unitIds": ["eg.g104.paul", "eg.v.c01_antioche"], "type": "mcq", "difficulty": 1, "prompt": "Dans quelle ville appelle-t-on les disciples « chrétiens » pour la première fois ?", "answer": "Antioche", "explanation": "Antioche : c''est là que le nom « chrétiens » apparaît.", "instruction": "Choisis la bonne réponse.", "options": ["Damas", "Antioche", "Jérusalem"], "step": 5, "id": "eg.l104.e08", "promptLanguage": "fr", "acceptedAnswers": ["Antioche"], "pool": "lesson", "lessonId": "eg.l104", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l104.e09', 'eg', 'eg.l104', 'eg.g104.paul', array['eg.g104.paul','eg.v.c01_chretiens']::text[], 'mcq', 'lesson', 'Que veut dire « chrétiens » ?', array['partisans du Christ']::text[], 'Le mot vient du grec Christianoi : ceux qui suivent le Christ.', 1, '{"unitIds": ["eg.g104.paul", "eg.v.c01_chretiens"], "type": "mcq", "difficulty": 1, "prompt": "Que veut dire « chrétiens » ?", "answer": "partisans du Christ", "explanation": "Le mot vient du grec Christianoi : ceux qui suivent le Christ.", "instruction": "Choisis la bonne réponse.", "options": ["amis de Rome", "habitants d''Antioche", "partisans du Christ"], "step": 5, "id": "eg.l104.e09", "promptLanguage": "fr", "acceptedAnswers": ["partisans du Christ"], "pool": "lesson", "lessonId": "eg.l104", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l104.e10', 'eg', 'eg.l104', 'eg.g104.paul', array['eg.g104.paul']::text[], 'match', 'lesson', 'Chacun son rôle dans l''histoire de Paul.', '{}'::text[], 'Trois lieux ou personnes, trois moments clés.', 2, '{"unitIds": ["eg.g104.paul"], "type": "match", "difficulty": 2, "prompt": "Chacun son rôle dans l''histoire de Paul.", "explanation": "Trois lieux ou personnes, trois moments clés.", "instruction": "Associe.", "pairs": [{"left": "Barnabé", "right": "accueille Paul à Jérusalem"}, {"left": "Antioche", "right": "les disciples y sont appelés chrétiens"}, {"left": "Damas", "right": "la route où le Christ apparaît à Saul"}], "id": "eg.l104.e10", "promptLanguage": "fr", "acceptedAnswers": [], "pool": "lesson", "lessonId": "eg.l104", "skill": "recognition", "answer": "Barnabé = accueille Paul à Jérusalem ; Antioche = les disciples y sont appelés chrétiens ; Damas = la route où le Christ apparaît à Saul"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l104.e11', 'eg', 'eg.l104', 'eg.g104.paul', array['eg.g104.paul']::text[], 'reorder', 'lesson', 'Remets la vie de Paul dans l''ordre.', array['persécution lumière baptême mission']::text[], 'Saul persécute, voit la lumière, est baptisé, puis part en mission.', 2, '{"unitIds": ["eg.g104.paul"], "type": "reorder", "difficulty": 2, "prompt": "Remets la vie de Paul dans l''ordre.", "answer": "persécution lumière baptême mission", "explanation": "Saul persécute, voit la lumière, est baptisé, puis part en mission.", "instruction": "Remets dans l''ordre.", "tokens": ["baptême", "mission", "persécution", "lumière"], "id": "eg.l104.e11", "promptLanguage": "fr", "acceptedAnswers": ["persécution lumière baptême mission"], "pool": "lesson", "lessonId": "eg.l104", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l104.e12', 'eg', 'eg.l104', 'eg.g103.etienne', array['eg.g103.etienne','eg.v.c01_saint_etienne']::text[], 'mcq', 'lesson', 'À la mort de quel martyr Saul assiste-t-il, avant de rencontrer le Christ ?', array['Étienne']::text[], 'Étienne prie pour ses bourreaux, et le jeune Saul est là : cette scène marquera sa vie.', 2, '{"unitIds": ["eg.g103.etienne", "eg.v.c01_saint_etienne"], "type": "mcq", "difficulty": 2, "prompt": "À la mort de quel martyr Saul assiste-t-il, avant de rencontrer le Christ ?", "answer": "Étienne", "explanation": "Étienne prie pour ses bourreaux, et le jeune Saul est là : cette scène marquera sa vie.", "instruction": "Choisis la bonne réponse.", "options": ["l''apôtre Pierre", "l''apôtre Jacques", "Étienne"], "id": "eg.l104.e12", "promptLanguage": "fr", "acceptedAnswers": ["Étienne"], "pool": "lesson", "lessonId": "eg.l104", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l104.e13', 'eg', 'eg.l104', 'eg.g104.paul', array['eg.g104.paul']::text[], 'mcq', 'lesson', 'Vrai ou faux : dans chaque ville, Paul commence par s''adresser aux païens.', array['Faux']::text[], 'Il commence par la synagogue, et se tourne vers les païens quand on le rejette.', 2, '{"unitIds": ["eg.g104.paul"], "type": "mcq", "difficulty": 2, "prompt": "Vrai ou faux : dans chaque ville, Paul commence par s''adresser aux païens.", "answer": "Faux", "explanation": "Il commence par la synagogue, et se tourne vers les païens quand on le rejette.", "instruction": "Choisis la bonne réponse.", "options": ["Vrai", "Faux"], "id": "eg.l104.e13", "promptLanguage": "fr", "acceptedAnswers": ["Faux"], "pool": "lesson", "lessonId": "eg.l104", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l104.e14', 'eg', 'eg.l104', 'eg.g104.paul', array['eg.g104.paul']::text[], 'mcq', 'lesson', 'Pourquoi Paul va-t-il d''abord à la synagogue dans chaque ville ?', array['Les Juifs y connaissent déjà les Écritures']::text[], 'Pour parler du Messie, il vaut mieux commencer chez ceux qui l''attendent déjà.', 3, '{"unitIds": ["eg.g104.paul"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi Paul va-t-il d''abord à la synagogue dans chaque ville ?", "answer": "Les Juifs y connaissent déjà les Écritures", "explanation": "Pour parler du Messie, il vaut mieux commencer chez ceux qui l''attendent déjà.", "instruction": "Choisis la bonne réponse.", "options": ["Les païens n''ont pas le droit d''entrer dans la ville", "Les Juifs y connaissent déjà les Écritures", "Les Romains y tiennent leurs grandes assemblées", "Les synagogues sont toujours gratuites"], "id": "eg.l104.e14", "promptLanguage": "fr", "acceptedAnswers": ["Les Juifs y connaissent déjà les Écritures"], "pool": "lesson", "lessonId": "eg.l104", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l104.e15', 'eg', 'eg.l104', 'eg.g103.etienne', array['eg.g103.etienne','eg.v.c01_martyr']::text[], 'mcq', 'lesson', 'Martyr veut dire « témoin ». Quel mot, lui, veut dire « envoyé » ?', array['apôtre']::text[], 'Étienne est un témoin, Paul est un envoyé : deux mots grecs à ne pas mélanger.', 3, '{"unitIds": ["eg.g103.etienne", "eg.v.c01_martyr"], "type": "mcq", "difficulty": 3, "prompt": "Martyr veut dire « témoin ». Quel mot, lui, veut dire « envoyé » ?", "answer": "apôtre", "explanation": "Étienne est un témoin, Paul est un envoyé : deux mots grecs à ne pas mélanger.", "instruction": "Choisis la bonne réponse.", "options": ["païen", "chrétien", "apôtre"], "id": "eg.l104.e15", "promptLanguage": "fr", "acceptedAnswers": ["apôtre"], "pool": "lesson", "lessonId": "eg.l104", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l105.e01', 'eg', 'eg.l105', 'eg.g105.concile', array['eg.g105.concile','eg.v.c01_circoncision']::text[], 'mcq', 'lesson', 'Que réclament ces visiteurs aux nouveaux croyants ?', array['la circoncision']::text[], 'Ils pensent qu''on ne peut être sauvé sans ce signe de la Loi.', 1, '{"unitIds": ["eg.g105.concile", "eg.v.c01_circoncision"], "type": "mcq", "difficulty": 1, "prompt": "Que réclament ces visiteurs aux nouveaux croyants ?", "answer": "la circoncision", "explanation": "Ils pensent qu''on ne peut être sauvé sans ce signe de la Loi.", "instruction": "Choisis la bonne réponse.", "options": ["la circoncision", "un pèlerinage à Rome", "de l''argent pour le Temple"], "step": 1, "id": "eg.l105.e01", "promptLanguage": "fr", "acceptedAnswers": ["la circoncision"], "pool": "lesson", "lessonId": "eg.l105", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l105.e02', 'eg', 'eg.l105', 'eg.g105.concile', array['eg.g105.concile','eg.v.c01_judaisants']::text[], 'mcq', 'lesson', 'Qui s''oppose à ces visiteurs à Antioche ?', array['Paul et Barnabé']::text[], 'Paul et Barnabé défendent les païens : pas besoin de devenir juif pour être chrétien.', 1, '{"unitIds": ["eg.g105.concile", "eg.v.c01_judaisants"], "type": "mcq", "difficulty": 1, "prompt": "Qui s''oppose à ces visiteurs à Antioche ?", "answer": "Paul et Barnabé", "explanation": "Paul et Barnabé défendent les païens : pas besoin de devenir juif pour être chrétien.", "instruction": "Choisis la bonne réponse.", "options": ["Pierre et Jean", "Paul et Barnabé", "Étienne et Saul"], "step": 1, "id": "eg.l105.e02", "promptLanguage": "fr", "acceptedAnswers": ["Paul et Barnabé"], "pool": "lesson", "lessonId": "eg.l105", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l105.e03', 'eg', 'eg.l105', 'eg.g105.concile', array['eg.g105.concile','eg.v.c01_circoncision']::text[], 'fill_blank', 'lesson', 'Si la circoncision devenait obligatoire, il faudrait d''abord devenir ___ pour être chrétien.', array['juif']::text[], 'Le christianisme resterait alors une branche du judaïsme.', 1, '{"unitIds": ["eg.g105.concile", "eg.v.c01_circoncision"], "type": "fill_blank", "difficulty": 1, "prompt": "Si la circoncision devenait obligatoire, il faudrait d''abord devenir ___ pour être chrétien.", "answer": "juif", "explanation": "Le christianisme resterait alors une branche du judaïsme.", "instruction": "Complète la phrase.", "options": ["romain", "évêque", "juif"], "step": 2, "id": "eg.l105.e03", "promptLanguage": "fr", "acceptedAnswers": ["juif"], "pool": "lesson", "lessonId": "eg.l105", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l105.e04', 'eg', 'eg.l105', 'eg.g105.concile', array['eg.g105.concile','eg.v.c01_concile']::text[], 'mcq', 'lesson', 'Qu''est-ce qu''un concile ?', array['une assemblée de responsables de l''Église']::text[], 'Le mot latin concilium veut dire « assemblée ».', 1, '{"unitIds": ["eg.g105.concile", "eg.v.c01_concile"], "type": "mcq", "difficulty": 1, "prompt": "Qu''est-ce qu''un concile ?", "answer": "une assemblée de responsables de l''Église", "explanation": "Le mot latin concilium veut dire « assemblée ».", "instruction": "Choisis la bonne réponse.", "options": ["un long voyage de pèlerins vers le Temple", "une lettre écrite par un des apôtres à Antioche", "un repas de fête chez Pierre à Jérusalem", "une assemblée de responsables de l''Église"], "step": 3, "id": "eg.l105.e04", "promptLanguage": "fr", "acceptedAnswers": ["une assemblée de responsables de l''Église"], "pool": "lesson", "lessonId": "eg.l105", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l105.e05', 'eg', 'eg.l105', 'eg.g105.concile', array['eg.g105.concile','eg.v.c01_concile_de_jerusalem']::text[], 'mcq', 'lesson', 'Vers quelle année a lieu le concile de Jérusalem ?', array['49']::text[], 'Vers 49 : le tout premier concile, bien avant Nicée.', 2, '{"unitIds": ["eg.g105.concile", "eg.v.c01_concile_de_jerusalem"], "type": "mcq", "difficulty": 2, "prompt": "Vers quelle année a lieu le concile de Jérusalem ?", "answer": "49", "explanation": "Vers 49 : le tout premier concile, bien avant Nicée.", "instruction": "Choisis la bonne réponse.", "options": ["325", "49", "1054"], "step": 3, "id": "eg.l105.e05", "promptLanguage": "fr", "acceptedAnswers": ["49"], "pool": "lesson", "lessonId": "eg.l105", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l105.e06', 'eg', 'eg.l105', 'eg.g105.concile', array['eg.g105.concile','eg.v.c01_saint_pierre']::text[], 'mcq', 'lesson', 'Qui rappelle que l''Esprit Saint est donné aux païens sans circoncision ?', array['Pierre']::text[], 'Pierre sait que Dieu agit chez les païens : il l''a vu de ses yeux.', 1, '{"unitIds": ["eg.g105.concile", "eg.v.c01_saint_pierre"], "type": "mcq", "difficulty": 1, "prompt": "Qui rappelle que l''Esprit Saint est donné aux païens sans circoncision ?", "answer": "Pierre", "explanation": "Pierre sait que Dieu agit chez les païens : il l''a vu de ses yeux.", "instruction": "Choisis la bonne réponse.", "options": ["Étienne", "Jacques", "Pierre"], "step": 4, "id": "eg.l105.e06", "promptLanguage": "fr", "acceptedAnswers": ["Pierre"], "pool": "lesson", "lessonId": "eg.l105", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l105.e07', 'eg', 'eg.l105', 'eg.g105.concile', array['eg.g105.concile','eg.v.c01_jacques_de_jerusalem']::text[], 'mcq', 'lesson', 'Qui conclut le débat en citant les prophètes ?', array['Jacques']::text[], 'Jacques, chef de l''Église de Jérusalem, a le dernier mot.', 1, '{"unitIds": ["eg.g105.concile", "eg.v.c01_jacques_de_jerusalem"], "type": "mcq", "difficulty": 1, "prompt": "Qui conclut le débat en citant les prophètes ?", "answer": "Jacques", "explanation": "Jacques, chef de l''Église de Jérusalem, a le dernier mot.", "instruction": "Choisis la bonne réponse.", "options": ["Jacques", "Marc", "Barnabé"], "step": 4, "id": "eg.l105.e07", "promptLanguage": "fr", "acceptedAnswers": ["Jacques"], "pool": "lesson", "lessonId": "eg.l105", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l105.e08', 'eg', 'eg.l105', 'eg.g105.concile', array['eg.g105.concile','eg.v.c01_concile_de_jerusalem']::text[], 'mcq', 'lesson', 'Que décide le concile ?', array['la circoncision n''est plus obligatoire']::text[], 'Le salut vient du Christ : plus besoin de passer par la Loi.', 1, '{"unitIds": ["eg.g105.concile", "eg.v.c01_concile_de_jerusalem"], "type": "mcq", "difficulty": 1, "prompt": "Que décide le concile ?", "answer": "la circoncision n''est plus obligatoire", "explanation": "Le salut vient du Christ : plus besoin de passer par la Loi.", "instruction": "Choisis la bonne réponse.", "options": ["tous les païens doivent d''abord devenir juifs", "les païens sont chassés de l''Église", "Paul doit quitter Antioche pour toujours", "la circoncision n''est plus obligatoire"], "step": 5, "id": "eg.l105.e08", "promptLanguage": "fr", "acceptedAnswers": ["la circoncision n''est plus obligatoire"], "pool": "lesson", "lessonId": "eg.l105", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l105.e09', 'eg', 'eg.l105', 'eg.g105.concile', array['eg.g105.concile','eg.v.c01_concile_de_jerusalem']::text[], 'fill_blank', 'lesson', '« Il a paru bon à l''___ et à nous. »', array['Esprit Saint']::text[], 'Pour l''Église, un concile décide avec l''aide de l''Esprit.', 1, '{"unitIds": ["eg.g105.concile", "eg.v.c01_concile_de_jerusalem"], "type": "fill_blank", "difficulty": 1, "prompt": "« Il a paru bon à l''___ et à nous. »", "answer": "Esprit Saint", "explanation": "Pour l''Église, un concile décide avec l''aide de l''Esprit.", "instruction": "Complète la phrase.", "options": ["empereur", "assemblée", "Esprit Saint"], "step": 5, "id": "eg.l105.e09", "promptLanguage": "fr", "acceptedAnswers": ["Esprit Saint"], "pool": "lesson", "lessonId": "eg.l105", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l105.e10', 'eg', 'eg.l105', 'eg.g105.concile', array['eg.g105.concile','eg.v.c01_concile']::text[], 'mcq', 'lesson', 'Quelle étape fait partie de la méthode d''un concile ?', array['écouter les témoins']::text[], 'On écoute les témoins, on s''appuie sur l''Écriture, on décide ensemble.', 2, '{"unitIds": ["eg.g105.concile", "eg.v.c01_concile"], "type": "mcq", "difficulty": 2, "prompt": "Quelle étape fait partie de la méthode d''un concile ?", "answer": "écouter les témoins", "explanation": "On écoute les témoins, on s''appuie sur l''Écriture, on décide ensemble.", "instruction": "Choisis la bonne réponse.", "options": ["écouter les témoins", "tirer au sort les décisions", "attendre l''ordre de l''empereur"], "step": 6, "id": "eg.l105.e10", "promptLanguage": "fr", "acceptedAnswers": ["écouter les témoins"], "pool": "lesson", "lessonId": "eg.l105", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l105.e11', 'eg', 'eg.l105', 'eg.g105.concile', array['eg.g105.concile']::text[], 'match', 'lesson', 'Qui dit quoi au concile ?', '{}'::text[], 'Trois témoignages, un seul verdict.', 2, '{"unitIds": ["eg.g105.concile"], "type": "match", "difficulty": 2, "prompt": "Qui dit quoi au concile ?", "explanation": "Trois témoignages, un seul verdict.", "instruction": "Associe.", "pairs": [{"left": "Pierre", "right": "Dieu a donné l''Esprit aux païens"}, {"left": "Paul et Barnabé", "right": "racontent les signes chez les païens"}, {"left": "Jacques", "right": "conclut en citant les prophètes"}], "id": "eg.l105.e11", "promptLanguage": "fr", "acceptedAnswers": [], "pool": "lesson", "lessonId": "eg.l105", "skill": "recognition", "answer": "Pierre = Dieu a donné l''Esprit aux païens ; Paul et Barnabé = racontent les signes chez les païens ; Jacques = conclut en citant les prophètes"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l105.e12', 'eg', 'eg.l105', 'eg.g105.concile', array['eg.g105.concile']::text[], 'reorder', 'lesson', 'Remets les étapes de la dispute dans l''ordre.', array['dispute voyage débat verdict lettre']::text[], 'La dispute à Antioche, le voyage, le débat, le verdict, puis la lettre.', 2, '{"unitIds": ["eg.g105.concile"], "type": "reorder", "difficulty": 2, "prompt": "Remets les étapes de la dispute dans l''ordre.", "answer": "dispute voyage débat verdict lettre", "explanation": "La dispute à Antioche, le voyage, le débat, le verdict, puis la lettre.", "instruction": "Remets dans l''ordre.", "tokens": ["dispute", "débat", "lettre", "voyage", "verdict"], "id": "eg.l105.e12", "promptLanguage": "fr", "acceptedAnswers": ["dispute voyage débat verdict lettre"], "pool": "lesson", "lessonId": "eg.l105", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l105.e13', 'eg', 'eg.l105', 'eg.g105.concile', array['eg.g105.concile','eg.v.c01_circoncision']::text[], 'mcq', 'lesson', 'Pourquoi la circoncision n''est-elle pas un simple détail pour l''Église ?', array['Elle décide d''où vient le salut']::text[], 'Obliger les païens à devenir juifs, ce serait dire que la Loi sauve, et non le Christ.', 3, '{"unitIds": ["eg.g105.concile", "eg.v.c01_circoncision"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi la circoncision n''est-elle pas un simple détail pour l''Église ?", "answer": "Elle décide d''où vient le salut", "explanation": "Obliger les païens à devenir juifs, ce serait dire que la Loi sauve, et non le Christ.", "instruction": "Choisis la bonne réponse.", "options": ["Elle décide d''où vient le salut", "Elle coûte très cher aux nouveaux croyants", "Elle est interdite par les autorités romaines", "Elle oblige les chrétiens à quitter Antioche"], "id": "eg.l105.e13", "promptLanguage": "fr", "acceptedAnswers": ["Elle décide d''où vient le salut"], "pool": "lesson", "lessonId": "eg.l105", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l105.e14', 'eg', 'eg.l105', 'eg.g104.paul', array['eg.g104.paul','eg.v.c01_antioche']::text[], 'mcq', 'lesson', 'Le conflit éclate dans la ville où l''on a dit « chrétiens » pour la première fois. Laquelle ?', array['Antioche']::text[], 'Antioche, la base des voyages de Paul et Barnabé.', 2, '{"unitIds": ["eg.g104.paul", "eg.v.c01_antioche"], "type": "mcq", "difficulty": 2, "prompt": "Le conflit éclate dans la ville où l''on a dit « chrétiens » pour la première fois. Laquelle ?", "answer": "Antioche", "explanation": "Antioche, la base des voyages de Paul et Barnabé.", "instruction": "Choisis la bonne réponse.", "options": ["Damas", "Antioche", "Jérusalem"], "id": "eg.l105.e14", "promptLanguage": "fr", "acceptedAnswers": ["Antioche"], "pool": "lesson", "lessonId": "eg.l105", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l105.e15', 'eg', 'eg.l105', 'eg.g101.pentecote', array['eg.g101.pentecote','eg.v.c01_saint_pierre']::text[], 'mcq', 'lesson', 'Quel apôtre a prêché le jour de la Pentecôte et prend aussi la parole au concile ?', array['Pierre']::text[], 'Pierre est le porte-parole des apôtres, de la Pentecôte au concile.', 2, '{"unitIds": ["eg.g101.pentecote", "eg.v.c01_saint_pierre"], "type": "mcq", "difficulty": 2, "prompt": "Quel apôtre a prêché le jour de la Pentecôte et prend aussi la parole au concile ?", "answer": "Pierre", "explanation": "Pierre est le porte-parole des apôtres, de la Pentecôte au concile.", "instruction": "Choisis la bonne réponse.", "options": ["Jacques", "Barnabé", "Pierre"], "id": "eg.l105.e15", "promptLanguage": "fr", "acceptedAnswers": ["Pierre"], "pool": "lesson", "lessonId": "eg.l105", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l105.e16', 'eg', 'eg.l105', 'eg.g105.concile', array['eg.g105.concile','eg.v.c01_judaisants']::text[], 'fill_blank', 'lesson', 'Les chrétiens d''origine juive qui veulent imposer la Loi aux païens sont les ___.', array['judaïsants']::text[], 'Ne les confonds pas avec les hellénistes, qui parlent grec et se plaignent pour leurs veuves.', 2, '{"unitIds": ["eg.g105.concile", "eg.v.c01_judaisants"], "type": "fill_blank", "difficulty": 2, "prompt": "Les chrétiens d''origine juive qui veulent imposer la Loi aux païens sont les ___.", "answer": "judaïsants", "explanation": "Ne les confonds pas avec les hellénistes, qui parlent grec et se plaignent pour leurs veuves.", "instruction": "Complète la phrase.", "options": ["judaïsants", "hellénistes", "apôtres"], "id": "eg.l105.e16", "promptLanguage": "fr", "acceptedAnswers": ["judaïsants"], "pool": "lesson", "lessonId": "eg.l105", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l106.e01', 'eg', 'eg.l106', 'eg.g106.martyrs', array['eg.g106.martyrs','eg.v.c01_jacques_de_zebedee']::text[], 'mcq', 'lesson', 'Quel apôtre est décapité vers 44 ?', array['Jacques, frère de Jean']::text[], 'Premier des Douze à mourir pour le Christ.', 1, '{"unitIds": ["eg.g106.martyrs", "eg.v.c01_jacques_de_zebedee"], "type": "mcq", "difficulty": 1, "prompt": "Quel apôtre est décapité vers 44 ?", "answer": "Jacques, frère de Jean", "explanation": "Premier des Douze à mourir pour le Christ.", "instruction": "Choisis la bonne réponse.", "options": ["Jacques, frère de Jean", "Pierre, chef des apôtres", "Paul, l''apôtre des nations"], "step": 1, "id": "eg.l106.e01", "promptLanguage": "fr", "acceptedAnswers": ["Jacques, frère de Jean"], "pool": "lesson", "lessonId": "eg.l106", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l106.e02', 'eg', 'eg.l106', 'eg.g106.martyrs', array['eg.g106.martyrs','eg.v.c01_jacques_de_zebedee']::text[], 'mcq', 'lesson', 'Vers quelle année cet apôtre est-il décapité ?', array['44']::text[], 'Vers 44 : une douzaine d''années après la Pentecôte.', 2, '{"unitIds": ["eg.g106.martyrs", "eg.v.c01_jacques_de_zebedee"], "type": "mcq", "difficulty": 2, "prompt": "Vers quelle année cet apôtre est-il décapité ?", "answer": "44", "explanation": "Vers 44 : une douzaine d''années après la Pentecôte.", "instruction": "Choisis la bonne réponse.", "options": ["325", "44", "1054"], "step": 1, "id": "eg.l106.e02", "promptLanguage": "fr", "acceptedAnswers": ["44"], "pool": "lesson", "lessonId": "eg.l106", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l106.e03', 'eg', 'eg.l106', 'eg.g106.martyrs', array['eg.g106.martyrs','eg.v.c01_empire_romain']::text[], 'mcq', 'lesson', 'Pourquoi les chrétiens refusent-ils d''honorer l''empereur ?', array['ils n''adorent que Dieu']::text[], 'Honorer l''empereur comme un dieu, c''est impossible pour un chrétien.', 1, '{"unitIds": ["eg.g106.martyrs", "eg.v.c01_empire_romain"], "type": "mcq", "difficulty": 1, "prompt": "Pourquoi les chrétiens refusent-ils d''honorer l''empereur ?", "answer": "ils n''adorent que Dieu", "explanation": "Honorer l''empereur comme un dieu, c''est impossible pour un chrétien.", "instruction": "Choisis la bonne réponse.", "options": ["ils détestent les Romains", "ils n''ont pas le droit", "ils n''adorent que Dieu"], "step": 2, "id": "eg.l106.e03", "promptLanguage": "fr", "acceptedAnswers": ["ils n''adorent que Dieu"], "pool": "lesson", "lessonId": "eg.l106", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l106.e04', 'eg', 'eg.l106', 'eg.g106.martyrs', array['eg.g106.martyrs','eg.v.c01_empire_romain']::text[], 'fill_blank', 'lesson', 'Chaque peuple garde ses dieux, à condition d''honorer aussi l''___.', array['empereur']::text[], 'C''est la règle de Rome, et c''est là que les chrétiens bloquent.', 1, '{"unitIds": ["eg.g106.martyrs", "eg.v.c01_empire_romain"], "type": "fill_blank", "difficulty": 1, "prompt": "Chaque peuple garde ses dieux, à condition d''honorer aussi l''___.", "answer": "empereur", "explanation": "C''est la règle de Rome, et c''est là que les chrétiens bloquent.", "instruction": "Complète la phrase.", "options": ["empereur", "évêque", "apôtre"], "step": 2, "id": "eg.l106.e04", "promptLanguage": "fr", "acceptedAnswers": ["empereur"], "pool": "lesson", "lessonId": "eg.l106", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
