insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l106.e06', 'eg', 'eg.l106', 'eg.g106.martyrs', array['eg.g106.martyrs','eg.v.c01_neron']::text[], 'mcq', 'lesson', 'En quelle année a lieu l''incendie de Rome ?', array['64']::text[], '64 : juillet, six jours de flammes.', 2, '{"unitIds": ["eg.g106.martyrs", "eg.v.c01_neron"], "type": "mcq", "difficulty": 2, "prompt": "En quelle année a lieu l''incendie de Rome ?", "answer": "64", "explanation": "64 : juillet, six jours de flammes.", "instruction": "Choisis la bonne réponse.", "options": ["325", "1054", "64"], "step": 3, "id": "eg.l106.e06", "promptLanguage": "fr", "acceptedAnswers": ["64"], "pool": "lesson", "lessonId": "eg.l106", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
