insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l106.e08', 'eg', 'eg.l106', 'eg.g106.martyrs', array['eg.g106.martyrs']::text[], 'mcq', 'lesson', 'Quel statut empêche Paul d''être crucifié ?', array['citoyen romain']::text[], 'À Rome, les citoyens avaient des droits que n''avaient pas les autres.', 2, '{"unitIds": ["eg.g106.martyrs"], "type": "mcq", "difficulty": 2, "prompt": "Quel statut empêche Paul d''être crucifié ?", "answer": "citoyen romain", "explanation": "À Rome, les citoyens avaient des droits que n''avaient pas les autres.", "instruction": "Choisis la bonne réponse.", "options": ["soldat de l''armée romaine", "citoyen romain", "ami personnel de Néron"], "step": 4, "id": "eg.l106.e08", "promptLanguage": "fr", "acceptedAnswers": ["citoyen romain"], "pool": "lesson", "lessonId": "eg.l106", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l106.e09', 'eg', 'eg.l106', 'eg.g106.martyrs', array['eg.g106.martyrs','eg.v.c01_jacques_de_jerusalem']::text[], 'mcq', 'lesson', 'En quelle année Jacques, chef de l''Église de Jérusalem, est-il martyrisé ?', array['62']::text[], '62 : et il ne faut pas le confondre avec le Jacques de 44.', 2, '{"unitIds": ["eg.g106.martyrs", "eg.v.c01_jacques_de_jerusalem"], "type": "mcq", "difficulty": 2, "prompt": "En quelle année Jacques, chef de l''Église de Jérusalem, est-il martyrisé ?", "answer": "62", "explanation": "62 : et il ne faut pas le confondre avec le Jacques de 44.", "instruction": "Choisis la bonne réponse.", "options": ["325", "1054", "62"], "step": 5, "id": "eg.l106.e09", "promptLanguage": "fr", "acceptedAnswers": ["62"], "pool": "lesson", "lessonId": "eg.l106", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l106.e10', 'eg', 'eg.l106', 'eg.g106.martyrs', array['eg.g106.martyrs']::text[], 'match', 'lesson', 'Date et événement.', '{}'::text[], 'Quatre dates qui jalonnent le siècle.', 2, '{"unitIds": ["eg.g106.martyrs"], "type": "match", "difficulty": 2, "prompt": "Date et événement.", "explanation": "Quatre dates qui jalonnent le siècle.", "instruction": "Associe.", "pairs": [{"left": "vers 44", "right": "Jacques, frère de Jean, décapité"}, {"left": "62", "right": "Jacques, chef de Jérusalem, martyrisé"}, {"left": "64", "right": "l''incendie de Rome"}, {"left": "vers 67", "right": "Pierre et Paul martyrisés"}], "id": "eg.l106.e10", "promptLanguage": "fr", "acceptedAnswers": [], "pool": "lesson", "lessonId": "eg.l106", "skill": "recognition", "answer": "vers 44 = Jacques, frère de Jean, décapité ; 62 = Jacques, chef de Jérusalem, martyrisé ; 64 = l''incendie de Rome ; vers 67 = Pierre et Paul martyrisés"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
