insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l108.e14', 'eg', 'eg.l108', 'eg.g105.concile', array['eg.g105.concile','eg.v.c01_judaisants']::text[], 'mcq', 'lesson', 'Parmi ces deux erreurs du siècle, laquelle voulait imposer la circoncision aux païens ?', array['les judaïsants']::text[], 'Les judaïsants voulaient imposer la Loi ; les gnostiques méprisaient le corps.', 2, '{"unitIds": ["eg.g105.concile", "eg.v.c01_judaisants"], "type": "mcq", "difficulty": 2, "prompt": "Parmi ces deux erreurs du siècle, laquelle voulait imposer la circoncision aux païens ?", "answer": "les judaïsants", "explanation": "Les judaïsants voulaient imposer la Loi ; les gnostiques méprisaient le corps.", "instruction": "Choisis la bonne réponse.", "options": ["les gnostiques", "les judaïsants"], "id": "eg.l108.e14", "promptLanguage": "fr", "acceptedAnswers": ["les judaïsants"], "pool": "lesson", "lessonId": "eg.l108", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l108.e15', 'eg', 'eg.l108', 'eg.g108.ecrits', array['eg.g108.ecrits','eg.v.c01_docetisme']::text[], 'mcq', 'lesson', 'Pourquoi le docétisme est-il dangereux pour la foi ?', array['Sans vrai corps, il n''y a plus de vraie croix']::text[], 'Si Jésus n''a pas de vrai corps, il ne souffre pas et ne ressuscite pas vraiment.', 3, '{"unitIds": ["eg.g108.ecrits", "eg.v.c01_docetisme"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi le docétisme est-il dangereux pour la foi ?", "answer": "Sans vrai corps, il n''y a plus de vraie croix", "explanation": "Si Jésus n''a pas de vrai corps, il ne souffre pas et ne ressuscite pas vraiment.", "instruction": "Choisis la bonne réponse.", "options": ["Il interdit aux fidèles de lire les évangiles en public", "Il oblige tous les païens à être circoncis", "Sans vrai corps, il n''y a plus de vraie croix", "Il supprime tous les apôtres de l''histoire"], "id": "eg.l108.e15", "promptLanguage": "fr", "acceptedAnswers": ["Sans vrai corps, il n''y a plus de vraie croix"], "pool": "lesson", "lessonId": "eg.l108", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l108.e16', 'eg', 'eg.l108', 'eg.g107.chute', array['eg.g107.chute','eg.v.c01_domitien']::text[], 'mcq', 'lesson', 'Jean répond au docétisme. Qui est exilé à Patmos sous Domitien, selon la tradition ?', array['saint Jean']::text[], 'C''est le même Jean, le dernier apôtre vivant.', 2, '{"unitIds": ["eg.g107.chute", "eg.v.c01_domitien"], "type": "mcq", "difficulty": 2, "prompt": "Jean répond au docétisme. Qui est exilé à Patmos sous Domitien, selon la tradition ?", "answer": "saint Jean", "explanation": "C''est le même Jean, le dernier apôtre vivant.", "instruction": "Choisis la bonne réponse.", "options": ["saint Jean", "saint Marc", "saint Paul"], "id": "eg.l108.e16", "promptLanguage": "fr", "acceptedAnswers": ["saint Jean"], "pool": "lesson", "lessonId": "eg.l108", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l109.e01', 'eg', 'eg.l109', 'eg.g109.sieges', array['eg.g109.sieges']::text[], 'mcq', 'lesson', 'Vers qui Jésus envoie-t-il les apôtres ?', array['toutes les nations']::text[], '« Allez, de toutes les nations faites des disciples ».', 1, '{"unitIds": ["eg.g109.sieges"], "type": "mcq", "difficulty": 1, "prompt": "Vers qui Jésus envoie-t-il les apôtres ?", "answer": "toutes les nations", "explanation": "« Allez, de toutes les nations faites des disciples ».", "instruction": "Choisis la bonne réponse.", "options": ["toutes les nations", "les Romains seulement", "les seuls Juifs"], "step": 1, "id": "eg.l109.e01", "promptLanguage": "fr", "acceptedAnswers": ["toutes les nations"], "pool": "lesson", "lessonId": "eg.l109", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l109.e02', 'eg', 'eg.l109', 'eg.g109.sieges', array['eg.g109.sieges']::text[], 'mcq', 'lesson', 'Sur quoi repose souvent la liste des voyages des apôtres ?', array['la tradition']::text[], 'On le dit prudemment : « selon la tradition ».', 1, '{"unitIds": ["eg.g109.sieges"], "type": "mcq", "difficulty": 1, "prompt": "Sur quoi repose souvent la liste des voyages des apôtres ?", "answer": "la tradition", "explanation": "On le dit prudemment : « selon la tradition ».", "instruction": "Choisis la bonne réponse.", "options": ["les registres de Rome", "la tradition", "les lettres de Néron"], "step": 1, "id": "eg.l109.e02", "promptLanguage": "fr", "acceptedAnswers": ["la tradition"], "pool": "lesson", "lessonId": "eg.l109", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
