insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l109.e04', 'eg', 'eg.l109', 'eg.g109.sieges', array['eg.g109.sieges']::text[], 'mcq', 'lesson', 'Quel apôtre prêche en Grèce, selon la tradition ?', array['André']::text[], 'André, le frère de Pierre.', 1, '{"unitIds": ["eg.g109.sieges"], "type": "mcq", "difficulty": 1, "prompt": "Quel apôtre prêche en Grèce, selon la tradition ?", "answer": "André", "explanation": "André, le frère de Pierre.", "instruction": "Choisis la bonne réponse.", "options": ["André", "Matthieu", "Thomas"], "step": 2, "id": "eg.l109.e04", "promptLanguage": "fr", "acceptedAnswers": ["André"], "pool": "lesson", "lessonId": "eg.l109", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
