insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l109.e06', 'eg', 'eg.l109', 'eg.g109.sieges', array['eg.g109.sieges','eg.v.c01_saint_jean']::text[], 'mcq', 'lesson', 'Dans quelle ville Jean vit-il ?', array['Éphèse']::text[], 'Éphèse, en Asie Mineure, devient l''un des sièges apostoliques.', 1, '{"unitIds": ["eg.g109.sieges", "eg.v.c01_saint_jean"], "type": "mcq", "difficulty": 1, "prompt": "Dans quelle ville Jean vit-il ?", "answer": "Éphèse", "explanation": "Éphèse, en Asie Mineure, devient l''un des sièges apostoliques.", "instruction": "Choisis la bonne réponse.", "options": ["Rome", "Alexandrie", "Éphèse"], "step": 3, "id": "eg.l109.e06", "promptLanguage": "fr", "acceptedAnswers": ["Éphèse"], "pool": "lesson", "lessonId": "eg.l109", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l109.e07', 'eg', 'eg.l109', 'eg.g109.sieges', array['eg.g109.sieges','eg.v.c01_siege_apostolique']::text[], 'fill_blank', 'lesson', 'Un siège apostolique est une Église fondée par un ___ ou un de ses proches.', array['apôtre']::text[], 'Par un envoyé de Jésus, ou par quelqu''un qui lui est proche.', 1, '{"unitIds": ["eg.g109.sieges", "eg.v.c01_siege_apostolique"], "type": "fill_blank", "difficulty": 1, "prompt": "Un siège apostolique est une Église fondée par un ___ ou un de ses proches.", "answer": "apôtre", "explanation": "Par un envoyé de Jésus, ou par quelqu''un qui lui est proche.", "instruction": "Complète la phrase.", "options": ["apôtre", "empereur", "pharisien"], "step": 4, "id": "eg.l109.e07", "promptLanguage": "fr", "acceptedAnswers": ["apôtre"], "pool": "lesson", "lessonId": "eg.l109", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l109.e08', 'eg', 'eg.l109', 'eg.g109.sieges', array['eg.g109.sieges','eg.v.c01_siege_apostolique']::text[], 'mcq', 'lesson', 'Que représente le « siège » ?', array['le fauteuil de l''évêque']::text[], 'Le fauteuil symbolise le droit d''enseigner de l''évêque.', 1, '{"unitIds": ["eg.g109.sieges", "eg.v.c01_siege_apostolique"], "type": "mcq", "difficulty": 1, "prompt": "Que représente le « siège » ?", "answer": "le fauteuil de l''évêque", "explanation": "Le fauteuil symbolise le droit d''enseigner de l''évêque.", "instruction": "Choisis la bonne réponse.", "options": ["la porte principale de l''église", "le fauteuil de l''évêque", "la table du repas de la fête"], "step": 4, "id": "eg.l109.e08", "promptLanguage": "fr", "acceptedAnswers": ["le fauteuil de l''évêque"], "pool": "lesson", "lessonId": "eg.l109", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l109.e09', 'eg', 'eg.l109', 'eg.g109.sieges', array['eg.g109.sieges','eg.v.c01_succession_apostolique']::text[], 'mcq', 'lesson', 'Comment les apôtres choisissent-ils leurs successeurs ?', array['en leur imposant les mains']::text[], 'L''imposition des mains transmet la mission.', 1, '{"unitIds": ["eg.g109.sieges", "eg.v.c01_succession_apostolique"], "type": "mcq", "difficulty": 1, "prompt": "Comment les apôtres choisissent-ils leurs successeurs ?", "answer": "en leur imposant les mains", "explanation": "L''imposition des mains transmet la mission.", "instruction": "Choisis la bonne réponse.", "options": ["en tirant les noms au sort", "en leur écrivant une lettre", "en leur imposant les mains"], "step": 5, "id": "eg.l109.e09", "promptLanguage": "fr", "acceptedAnswers": ["en leur imposant les mains"], "pool": "lesson", "lessonId": "eg.l109", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l109.e10', 'eg', 'eg.l109', 'eg.g109.sieges', array['eg.g109.sieges','eg.v.c01_succession_apostolique']::text[], 'mcq', 'lesson', 'Que garantit la succession apostolique ?', array['que la foi enseignée est celle des origines']::text[], 'Une chaîne de mains jamais coupée relie chaque évêque aux apôtres.', 2, '{"unitIds": ["eg.g109.sieges", "eg.v.c01_succession_apostolique"], "type": "mcq", "difficulty": 2, "prompt": "Que garantit la succession apostolique ?", "answer": "que la foi enseignée est celle des origines", "explanation": "Une chaîne de mains jamais coupée relie chaque évêque aux apôtres.", "instruction": "Choisis la bonne réponse.", "options": ["que la foi enseignée est celle des origines", "que l''Église devient très riche et très puissante", "que tous les évêques sont de nationalité romaine"], "step": 5, "id": "eg.l109.e10", "promptLanguage": "fr", "acceptedAnswers": ["que la foi enseignée est celle des origines"], "pool": "lesson", "lessonId": "eg.l109", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l109.e11', 'eg', 'eg.l109', 'eg.g109.sieges', array['eg.g109.sieges','eg.v.c01_saint_thomas']::text[], 'match', 'lesson', 'Un apôtre, un pays (selon la tradition).', '{}'::text[], 'Quatre apôtres, quatre pays : toujours « selon la tradition ».', 2, '{"unitIds": ["eg.g109.sieges", "eg.v.c01_saint_thomas"], "type": "match", "difficulty": 2, "prompt": "Un apôtre, un pays (selon la tradition).", "explanation": "Quatre apôtres, quatre pays : toujours « selon la tradition ».", "instruction": "Associe.", "pairs": [{"left": "Thomas", "right": "l''Inde"}, {"left": "André", "right": "la Grèce"}, {"left": "Matthieu", "right": "l''Éthiopie"}, {"left": "Barthélemy", "right": "l''Arménie"}], "id": "eg.l109.e11", "promptLanguage": "fr", "acceptedAnswers": [], "pool": "lesson", "lessonId": "eg.l109", "skill": "recognition", "answer": "Thomas = l''Inde ; André = la Grèce ; Matthieu = l''Éthiopie ; Barthélemy = l''Arménie"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l109.e12', 'eg', 'eg.l109', 'eg.g109.sieges', array['eg.g109.sieges','eg.v.c01_succession_apostolique']::text[], 'reorder', 'lesson', 'Dans la succession apostolique, remets la chaîne dans l''ordre.', array['Jésus apôtres évêques']::text[], 'Jésus envoie les apôtres, qui choisissent des évêques.', 2, '{"unitIds": ["eg.g109.sieges", "eg.v.c01_succession_apostolique"], "type": "reorder", "difficulty": 2, "prompt": "Dans la succession apostolique, remets la chaîne dans l''ordre.", "answer": "Jésus apôtres évêques", "explanation": "Jésus envoie les apôtres, qui choisissent des évêques.", "instruction": "Remets dans l''ordre.", "tokens": ["évêques", "Jésus", "apôtres"], "id": "eg.l109.e12", "promptLanguage": "fr", "acceptedAnswers": ["Jésus apôtres évêques"], "pool": "lesson", "lessonId": "eg.l109", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l109.e13', 'eg', 'eg.l109', 'eg.g109.sieges', array['eg.g109.sieges','eg.v.c01_siege_apostolique']::text[], 'mcq', 'lesson', 'Pourquoi se tourne-t-on vers un siège apostolique face aux erreurs ?', array['Il garde la foi reçue des apôtres']::text[], 'Ces Églises ont reçu la foi presque de première main.', 3, '{"unitIds": ["eg.g109.sieges", "eg.v.c01_siege_apostolique"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi se tourne-t-on vers un siège apostolique face aux erreurs ?", "answer": "Il garde la foi reçue des apôtres", "explanation": "Ces Églises ont reçu la foi presque de première main.", "instruction": "Choisis la bonne réponse.", "options": ["Il garde la foi reçue des apôtres", "Il possède les plus grands palais", "Il commande aux armées de Rome", "Il a le plus grand nombre de fidèles"], "id": "eg.l109.e13", "promptLanguage": "fr", "acceptedAnswers": ["Il garde la foi reçue des apôtres"], "pool": "lesson", "lessonId": "eg.l109", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l109.e14', 'eg', 'eg.l109', 'eg.g108.ecrits', array['eg.g108.ecrits','eg.v.c01_docetisme']::text[], 'mcq', 'lesson', 'Jean, le dernier apôtre, a affronté une erreur de son temps. Laquelle ?', array['le docétisme']::text[], 'Il répond : « Le Verbe s''est fait chair ».', 2, '{"unitIds": ["eg.g108.ecrits", "eg.v.c01_docetisme"], "type": "mcq", "difficulty": 2, "prompt": "Jean, le dernier apôtre, a affronté une erreur de son temps. Laquelle ?", "answer": "le docétisme", "explanation": "Il répond : « Le Verbe s''est fait chair ».", "instruction": "Choisis la bonne réponse.", "options": ["les judaïsants", "le docétisme", "les hellénistes"], "id": "eg.l109.e14", "promptLanguage": "fr", "acceptedAnswers": ["le docétisme"], "pool": "lesson", "lessonId": "eg.l109", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
