insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l112.e09', 'eg', 'eg.l112', 'eg.g112.bilan', array['eg.g112.bilan']::text[], 'reorder', 'lesson', 'Remets ces moments dans l''ordre.', array['Pentecôte Étienne concile Néron']::text[], 'La Pentecôte, la mort d''Étienne, le concile de Jérusalem, puis Néron.', 2, '{"unitIds": ["eg.g112.bilan"], "type": "reorder", "difficulty": 2, "prompt": "Remets ces moments dans l''ordre.", "answer": "Pentecôte Étienne concile Néron", "explanation": "La Pentecôte, la mort d''Étienne, le concile de Jérusalem, puis Néron.", "instruction": "Remets dans l''ordre.", "tokens": ["Étienne", "Pentecôte", "concile", "Néron"], "id": "eg.l112.e09", "promptLanguage": "fr", "acceptedAnswers": ["Pentecôte Étienne concile Néron"], "pool": "lesson", "lessonId": "eg.l112", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l112.e10', 'eg', 'eg.l112', 'eg.g112.bilan', array['eg.g112.bilan','eg.v.c01_circoncision']::text[], 'fill_blank', 'lesson', 'Le concile décide que la ___ n''est plus obligatoire pour les païens.', array['circoncision']::text[], 'Le salut vient du Christ, pas de la Loi.', 2, '{"unitIds": ["eg.g112.bilan", "eg.v.c01_circoncision"], "type": "fill_blank", "difficulty": 2, "prompt": "Le concile décide que la ___ n''est plus obligatoire pour les païens.", "answer": "circoncision", "explanation": "Le salut vient du Christ, pas de la Loi.", "instruction": "Complète la phrase.", "options": ["circoncision", "prière", "Pentecôte"], "id": "eg.l112.e10", "promptLanguage": "fr", "acceptedAnswers": ["circoncision"], "pool": "lesson", "lessonId": "eg.l112", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l112.e11', 'eg', 'eg.l112', 'eg.g112.bilan', array['eg.g112.bilan','eg.v.c01_neron']::text[], 'mcq', 'lesson', 'Pourquoi les chrétiens sont-ils persécutés par Rome ?', array['Ils refusent d''adorer l''empereur']::text[], 'Pour Rome, refuser d''honorer l''empereur est un danger.', 3, '{"unitIds": ["eg.g112.bilan", "eg.v.c01_neron"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi les chrétiens sont-ils persécutés par Rome ?", "answer": "Ils refusent d''adorer l''empereur", "explanation": "Pour Rome, refuser d''honorer l''empereur est un danger.", "instruction": "Choisis la bonne réponse.", "options": ["Ils refusent de payer l''impôt à Rome", "Ils veulent chasser les Romains du pays", "Ils refusent d''adorer l''empereur", "Ils sont tous des étrangers à l''Empire"], "id": "eg.l112.e11", "promptLanguage": "fr", "acceptedAnswers": ["Ils refusent d''adorer l''empereur"], "pool": "lesson", "lessonId": "eg.l112", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l112.e12', 'eg', 'eg.l112', 'eg.g112.bilan', array['eg.g112.bilan','eg.v.c01_evangile']::text[], 'mcq', 'lesson', 'Pourquoi les évangiles sont-ils écrits dans la seconde moitié du siècle ?', array['Les témoins vieillissent, de faux docteurs arrivent']::text[], 'Pour garder fidèlement ce qu''on a reçu.', 3, '{"unitIds": ["eg.g112.bilan", "eg.v.c01_evangile"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi les évangiles sont-ils écrits dans la seconde moitié du siècle ?", "answer": "Les témoins vieillissent, de faux docteurs arrivent", "explanation": "Pour garder fidèlement ce qu''on a reçu.", "instruction": "Choisis la bonne réponse.", "options": ["Jésus avait ordonné de les écrire de son vivant à ses disciples", "Les Romains les avaient commandés aux apôtres vers l''an 70", "Les apôtres n''avaient plus rien à dire à personne", "Les témoins vieillissent, de faux docteurs arrivent"], "id": "eg.l112.e12", "promptLanguage": "fr", "acceptedAnswers": ["Les témoins vieillissent, de faux docteurs arrivent"], "pool": "lesson", "lessonId": "eg.l112", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l112.e13', 'eg', 'eg.l112', 'eg.g112.bilan', array['eg.g112.bilan','eg.v.c01_gnosticisme']::text[], 'mcq', 'lesson', 'Laquelle de ces phrases un gnostique pourrait-il dire ?', array['Le corps est une prison pour l''âme']::text[], 'C''est exactement ce que Jean combat avec « le Verbe s''est fait chair ».', 3, '{"unitIds": ["eg.g112.bilan", "eg.v.c01_gnosticisme"], "type": "mcq", "difficulty": 3, "prompt": "Laquelle de ces phrases un gnostique pourrait-il dire ?", "answer": "Le corps est une prison pour l''âme", "explanation": "C''est exactement ce que Jean combat avec « le Verbe s''est fait chair ».", "instruction": "Choisis la bonne réponse.", "options": ["Le corps est une prison pour l''âme", "Le Verbe s''est fait chair, vraiment homme", "Jésus a vraiment souffert sur la croix", "La circoncision est obligatoire pour être sauvé"], "id": "eg.l112.e13", "promptLanguage": "fr", "acceptedAnswers": ["Le corps est une prison pour l''âme"], "pool": "lesson", "lessonId": "eg.l112", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l112.e14', 'eg', 'eg.l112', 'eg.g112.bilan', array['eg.g112.bilan','eg.v.c01_chute_de_jerusalem']::text[], 'mcq', 'lesson', 'Qu''ont en commun la mort d''Étienne et la chute de Jérusalem ?', array['Les chrétiens se dispersent et l''Évangile se répand']::text[], 'À chaque fois, la dispersion fait sortir l''Évangile de Jérusalem.', 3, '{"unitIds": ["eg.g112.bilan", "eg.v.c01_chute_de_jerusalem"], "type": "mcq", "difficulty": 3, "prompt": "Qu''ont en commun la mort d''Étienne et la chute de Jérusalem ?", "answer": "Les chrétiens se dispersent et l''Évangile se répand", "explanation": "À chaque fois, la dispersion fait sortir l''Évangile de Jérusalem.", "instruction": "Choisis la bonne réponse.", "options": ["Les Romains se convertissent tous au christianisme aussitôt", "Les chrétiens se dispersent et l''Évangile se répand", "Les apôtres quittent l''Église et rentrent chez eux", "L''Église cesse de grandir pendant de longues années"], "id": "eg.l112.e14", "promptLanguage": "fr", "acceptedAnswers": ["Les chrétiens se dispersent et l''Évangile se répand"], "pool": "lesson", "lessonId": "eg.l112", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l112.e15', 'eg', 'eg.l112', 'eg.g112.bilan', array['eg.g112.bilan','eg.v.c01_anianos']::text[], 'fill_blank', 'lesson', 'Marc guérit un cordonnier, ___, qui devient son successeur.', array['Anianos']::text[], 'Un cordonnier, premier converti puis évêque d''Alexandrie.', 2, '{"unitIds": ["eg.g112.bilan", "eg.v.c01_anianos"], "type": "fill_blank", "difficulty": 2, "prompt": "Marc guérit un cordonnier, ___, qui devient son successeur.", "answer": "Anianos", "explanation": "Un cordonnier, premier converti puis évêque d''Alexandrie.", "instruction": "Complète la phrase.", "options": ["Agrippa", "Domitien", "Anianos"], "id": "eg.l112.e15", "promptLanguage": "fr", "acceptedAnswers": ["Anianos"], "pool": "lesson", "lessonId": "eg.l112", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l112.e16', 'eg', 'eg.l112', 'eg.g112.bilan', array['eg.g112.bilan','eg.v.c01_copte']::text[], 'mcq', 'lesson', 'Dans l''expression « Église copte », que signifie le mot copte ?', array['égyptien']::text[], 'Copte vient du grec Aigyptios.', 2, '{"unitIds": ["eg.g112.bilan", "eg.v.c01_copte"], "type": "mcq", "difficulty": 2, "prompt": "Dans l''expression « Église copte », que signifie le mot copte ?", "answer": "égyptien", "explanation": "Copte vient du grec Aigyptios.", "instruction": "Choisis la bonne réponse.", "options": ["égyptien", "apostolique", "orthodoxe"], "id": "eg.l112.e16", "promptLanguage": "fr", "acceptedAnswers": ["égyptien"], "pool": "lesson", "lessonId": "eg.l112", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l201.e01', 'eg', 'eg.l201', 'eg.g201.releve', array['eg.g201.releve']::text[], 'mcq', 'lesson', 'Que n''y a-t-il plus au début du IIe siècle ?', array['aucun témoin direct du Christ']::text[], 'Les apôtres sont morts : personne ne peut plus dire « j''ai entendu Jésus ».', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que n''y a-t-il plus au début du IIe siècle ?", "answer": "aucun témoin direct du Christ", "acceptedAnswers": ["aucun témoin direct du Christ"], "explanation": "Les apôtres sont morts : personne ne peut plus dire « j''ai entendu Jésus ».", "options": ["aucun témoin direct du Christ", "aucune Église dans l''Empire", "aucun évêque à Rome"], "id": "eg.l201.e01", "promptLanguage": "fr", "unitIds": ["eg.g201.releve"], "step": 1, "pool": "lesson", "lessonId": "eg.l201", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l201.e02', 'eg', 'eg.l201', 'eg.g201.releve', array['eg.g201.releve','eg.v.apotre']::text[], 'fill_blank', 'lesson', 'Au début du IIe siècle, les ___ sont tous morts.', array['apôtres']::text[], 'Les « envoyés » de la Pentecôte ont disparu. Il faut trouver d''autres gardiens.', 1, '{"type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Au début du IIe siècle, les ___ sont tous morts.", "answer": "apôtres", "acceptedAnswers": ["apôtres"], "explanation": "Les « envoyés » de la Pentecôte ont disparu. Il faut trouver d''autres gardiens.", "options": ["apôtres", "empereurs", "évêques"], "id": "eg.l201.e02", "promptLanguage": "fr", "unitIds": ["eg.g201.releve", "eg.v.apotre"], "step": 1, "pool": "lesson", "lessonId": "eg.l201", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l201.e03', 'eg', 'eg.l201', 'eg.g201.releve', array['eg.g201.releve','eg.v.c01_heresie']::text[], 'mcq', 'lesson', 'Que veut dire le grec hairesis, d''où vient « hérésie » ?', array['choix']::text[], 'L''hérétique choisit dans la foi ce qui lui plaît et laisse le reste.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire le grec hairesis, d''où vient « hérésie » ?", "answer": "choix", "acceptedAnswers": ["choix"], "explanation": "L''hérétique choisit dans la foi ce qui lui plaît et laisse le reste.", "options": ["pardon", "choix", "écriture"], "id": "eg.l201.e03", "promptLanguage": "fr", "unitIds": ["eg.g201.releve", "eg.v.c01_heresie"], "step": 2, "pool": "lesson", "lessonId": "eg.l201", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l201.e04', 'eg', 'eg.l201', 'eg.g201.releve', array['eg.g201.releve']::text[], 'mcq', 'lesson', 'Vrai ou faux : les maîtres hérétiques ne citent jamais l''Écriture.', array['Faux']::text[], 'Ils la citent eux aussi, à leur façon. C''est pour cela que le livre seul ne suffit pas.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Vrai ou faux : les maîtres hérétiques ne citent jamais l''Écriture.", "answer": "Faux", "acceptedAnswers": ["Faux"], "explanation": "Ils la citent eux aussi, à leur façon. C''est pour cela que le livre seul ne suffit pas.", "options": ["Vrai", "Faux"], "id": "eg.l201.e04", "promptLanguage": "fr", "unitIds": ["eg.g201.releve"], "step": 2, "pool": "lesson", "lessonId": "eg.l201", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l201.e05', 'eg', 'eg.l201', 'eg.g201.releve', array['eg.g201.releve']::text[], 'mcq', 'lesson', 'Pourquoi les Écritures seules ne suffisent-elles pas à trancher ?', array['chacun peut citer un verset à sa façon']::text[], 'Deux personnes peuvent citer le même verset et en tirer des idées contraires. Il faut un juge vivant.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi les Écritures seules ne suffisent-elles pas à trancher ?", "answer": "chacun peut citer un verset à sa façon", "acceptedAnswers": ["chacun peut citer un verset à sa façon"], "explanation": "Deux personnes peuvent citer le même verset et en tirer des idées contraires. Il faut un juge vivant.", "options": ["elles sont écrites dans une langue oubliée", "personne ne sait encore les lire", "chacun peut citer un verset à sa façon"], "id": "eg.l201.e05", "promptLanguage": "fr", "unitIds": ["eg.g201.releve"], "step": 3, "pool": "lesson", "lessonId": "eg.l201", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l201.e06', 'eg', 'eg.l201', 'eg.g201.releve', array['eg.g201.releve']::text[], 'mcq', 'lesson', 'Que faut-il en plus du livre ?', array['des gardiens vivants']::text[], 'Des responsables qui transmettent l''enseignement des apôtres de personne à personne.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que faut-il en plus du livre ?", "answer": "des gardiens vivants", "acceptedAnswers": ["des gardiens vivants"], "explanation": "Des responsables qui transmettent l''enseignement des apôtres de personne à personne.", "options": ["un second livre", "des gardiens vivants", "un nouvel empereur"], "id": "eg.l201.e06", "promptLanguage": "fr", "unitIds": ["eg.g201.releve"], "step": 3, "pool": "lesson", "lessonId": "eg.l201", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l201.e07', 'eg', 'eg.l201', 'eg.g201.releve', array['eg.g201.releve','eg.v.c01_succession_apostolique']::text[], 'mcq', 'lesson', 'Comment s''appelle la chaîne d''évêques qui remonte aux apôtres ?', array['la succession apostolique']::text[], 'Apôtres, puis évêques, puis évêques : chaque maillon tient le précédent.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Comment s''appelle la chaîne d''évêques qui remonte aux apôtres ?", "answer": "la succession apostolique", "acceptedAnswers": ["la succession apostolique"], "explanation": "Apôtres, puis évêques, puis évêques : chaque maillon tient le précédent.", "options": ["la succession apostolique", "la persécution de l''Empire", "la fête de la Pentecôte"], "id": "eg.l201.e07", "promptLanguage": "fr", "unitIds": ["eg.g201.releve", "eg.v.c01_succession_apostolique"], "step": 4, "pool": "lesson", "lessonId": "eg.l201", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l201.e08', 'eg', 'eg.l201', 'eg.g201.releve', array['eg.g201.releve','eg.v.c02_eveque']::text[], 'mcq', 'lesson', 'Évêque vient d''un mot grec qui veut dire…', array['surveillant']::text[], 'Un évêque « surveille » son Église, comme un berger son troupeau.', 2, '{"type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Évêque vient d''un mot grec qui veut dire…", "answer": "surveillant", "acceptedAnswers": ["surveillant"], "explanation": "Un évêque « surveille » son Église, comme un berger son troupeau.", "options": ["voyageur", "écrivain", "surveillant"], "id": "eg.l201.e08", "promptLanguage": "fr", "unitIds": ["eg.g201.releve", "eg.v.c02_eveque"], "step": 4, "pool": "lesson", "lessonId": "eg.l201", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
