insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l201.e10', 'eg', 'eg.l201', 'eg.g201.releve', array['eg.g201.releve']::text[], 'mcq', 'lesson', 'Vrai ou faux : au IIe siècle, des apôtres vivent encore et peuvent trancher les disputes.', array['Faux']::text[], 'Ils sont tous morts. D''où le besoin de gardiens de la foi.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Vrai ou faux : au IIe siècle, des apôtres vivent encore et peuvent trancher les disputes.", "answer": "Faux", "acceptedAnswers": ["Faux"], "explanation": "Ils sont tous morts. D''où le besoin de gardiens de la foi.", "options": ["Vrai", "Faux"], "id": "eg.l201.e10", "promptLanguage": "fr", "unitIds": ["eg.g201.releve"], "pool": "lesson", "lessonId": "eg.l201", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l201.e11', 'eg', 'eg.l201', 'eg.g201.releve', array['eg.g201.releve','eg.v.apotre','eg.g101.pentecote']::text[], 'fill_blank', 'lesson', 'Apôtre veut dire « ___ » : quelqu''un que Jésus a envoyé en mission.', array['envoyé']::text[], 'Souviens-toi de la Pentecôte : les douze deviennent des envoyés.', 2, '{"type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Apôtre veut dire « ___ » : quelqu''un que Jésus a envoyé en mission.", "answer": "envoyé", "acceptedAnswers": ["envoyé"], "explanation": "Souviens-toi de la Pentecôte : les douze deviennent des envoyés.", "options": ["envoyé", "cinquantième", "baptisé"], "id": "eg.l201.e11", "promptLanguage": "fr", "unitIds": ["eg.g201.releve", "eg.v.apotre", "eg.g101.pentecote"], "pool": "lesson", "lessonId": "eg.l201", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l201.e12', 'eg', 'eg.l201', 'eg.g201.releve', array['eg.g201.releve','eg.v.c02_tradition','eg.v.c02_eveque']::text[], 'match', 'lesson', 'Les trois appuis de la foi : à chacun son rôle.', '{}'::text[], 'Le livre, la voix, les gardiens.', 2, '{"type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Les trois appuis de la foi : à chacun son rôle.", "acceptedAnswers": [], "explanation": "Le livre, la voix, les gardiens.", "pairs": [{"left": "les Écritures", "right": "le livre lu dans les assemblées"}, {"left": "la tradition", "right": "ce que les apôtres ont transmis de vive voix"}, {"left": "les évêques", "right": "les successeurs des apôtres"}], "id": "eg.l201.e12", "promptLanguage": "fr", "unitIds": ["eg.g201.releve", "eg.v.c02_tradition", "eg.v.c02_eveque"], "pool": "lesson", "lessonId": "eg.l201", "skill": "recognition", "answer": "les Écritures = le livre lu dans les assemblées ; la tradition = ce que les apôtres ont transmis de vive voix ; les évêques = les successeurs des apôtres"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l201.e13', 'eg', 'eg.l201', 'eg.g201.releve', array['eg.g201.releve','eg.v.c01_succession_apostolique']::text[], 'reorder', 'lesson', 'Remets la chaîne de la foi dans l''ordre.', array['Jésus apôtres évêques chrétiens']::text[], 'Jésus choisit des apôtres, qui établissent des évêques, qui enseignent les chrétiens.', 2, '{"type": "reorder", "difficulty": 2, "instruction": "Remets dans l''ordre.", "prompt": "Remets la chaîne de la foi dans l''ordre.", "answer": "Jésus apôtres évêques chrétiens", "acceptedAnswers": ["Jésus apôtres évêques chrétiens"], "explanation": "Jésus choisit des apôtres, qui établissent des évêques, qui enseignent les chrétiens.", "tokens": ["apôtres", "évêques", "chrétiens", "Jésus"], "id": "eg.l201.e13", "promptLanguage": "fr", "unitIds": ["eg.g201.releve", "eg.v.c01_succession_apostolique"], "pool": "lesson", "lessonId": "eg.l201", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l201.e14', 'eg', 'eg.l201', 'eg.g201.releve', array['eg.g201.releve']::text[], 'mcq', 'lesson', 'Un maître dit : « C''est écrit dans la Bible ! » Pourquoi cela ne prouve-t-il pas qu''il a raison ?', array['Un autre maître cite le même verset pour dire le contraire']::text[], 'Citer ne suffit pas : il faut aussi savoir comment lire, et cela s''apprend des gardiens de la foi.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Un maître dit : « C''est écrit dans la Bible ! » Pourquoi cela ne prouve-t-il pas qu''il a raison ?", "answer": "Un autre maître cite le même verset pour dire le contraire", "acceptedAnswers": ["Un autre maître cite le même verset pour dire le contraire"], "explanation": "Citer ne suffit pas : il faut aussi savoir comment lire, et cela s''apprend des gardiens de la foi.", "options": ["Parce que la Bible n''existe pas encore à cette époque", "Un autre maître cite le même verset pour dire le contraire", "Parce que les hérétiques ne savent pas lire les Écritures"], "id": "eg.l201.e14", "promptLanguage": "fr", "unitIds": ["eg.g201.releve"], "pool": "lesson", "lessonId": "eg.l201", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l201.e15', 'eg', 'eg.l201', 'eg.g201.releve', array['eg.g201.releve','eg.v.c01_heresie','eg.v.c02_depot']::text[], 'mcq', 'lesson', 'Dans le mot hérésie (« choix »), que fait l''hérétique ?', array['Il choisit dans la foi ce qui lui plaît']::text[], 'Il garde une partie de la foi et laisse le reste : c''est tout le contraire du dépôt confié intact.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans le mot hérésie (« choix »), que fait l''hérétique ?", "answer": "Il choisit dans la foi ce qui lui plaît", "acceptedAnswers": ["Il choisit dans la foi ce qui lui plaît"], "explanation": "Il garde une partie de la foi et laisse le reste : c''est tout le contraire du dépôt confié intact.", "options": ["Il reçoit toute la foi sans rien changer", "Il choisit un nouvel évêque", "Il choisit dans la foi ce qui lui plaît"], "id": "eg.l201.e15", "promptLanguage": "fr", "unitIds": ["eg.g201.releve", "eg.v.c01_heresie", "eg.v.c02_depot"], "pool": "lesson", "lessonId": "eg.l201", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l202.e01', 'eg', 'eg.l202', 'eg.g202.sieges', array['eg.g202.sieges']::text[], 'mcq', 'lesson', 'Qu''est-ce qu''un siège ?', array['la « chaise » d''un évêque dans sa ville']::text[], 'Le mot a gardé son sens d''origine : l''évêque est « assis » dans sa ville pour enseigner.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''est-ce qu''un siège ?", "answer": "la « chaise » d''un évêque dans sa ville", "acceptedAnswers": ["la « chaise » d''un évêque dans sa ville"], "explanation": "Le mot a gardé son sens d''origine : l''évêque est « assis » dans sa ville pour enseigner.", "options": ["la « chaise » d''un évêque dans sa ville", "le bateau d''un pêcheur du lac de Galilée", "la maison d''un empereur de passage à Rome"], "id": "eg.l202.e01", "promptLanguage": "fr", "unitIds": ["eg.g202.sieges"], "step": 1, "pool": "lesson", "lessonId": "eg.l202", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l202.e02', 'eg', 'eg.l202', 'eg.g202.sieges', array['eg.g202.sieges']::text[], 'mcq', 'lesson', 'Qui est le premier évêque d''un siège apostolique ?', array['un apôtre']::text[], 'C''est ce qui donne à ces Églises leur autorité : leur chaîne commence avec un apôtre.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui est le premier évêque d''un siège apostolique ?", "answer": "un apôtre", "acceptedAnswers": ["un apôtre"], "explanation": "C''est ce qui donne à ces Églises leur autorité : leur chaîne commence avec un apôtre.", "options": ["un philosophe", "un empereur", "un apôtre"], "id": "eg.l202.e02", "promptLanguage": "fr", "unitIds": ["eg.g202.sieges"], "step": 1, "pool": "lesson", "lessonId": "eg.l202", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
