insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l202.e12', 'eg', 'eg.l202', 'eg.g202.sieges', array['eg.g202.sieges','eg.v.c02_siege_rome','eg.v.c02_siege_alexandrie','eg.v.c02_siege_antioche','eg.v.c02_siege_jerusalem']::text[], 'match', 'lesson', 'Quatre villes, quatre fondateurs : à chacun son siège.', '{}'::text[], 'Rome : Pierre et Paul. Alexandrie : Marc. Antioche : Pierre. Jérusalem : Jacques.', 2, '{"type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Quatre villes, quatre fondateurs : à chacun son siège.", "acceptedAnswers": [], "explanation": "Rome : Pierre et Paul. Alexandrie : Marc. Antioche : Pierre. Jérusalem : Jacques.", "pairs": [{"left": "Rome", "right": "Pierre et Paul"}, {"left": "Alexandrie", "right": "Marc"}, {"left": "Antioche", "right": "Pierre"}, {"left": "Jérusalem", "right": "Jacques"}], "id": "eg.l202.e12", "promptLanguage": "fr", "unitIds": ["eg.g202.sieges", "eg.v.c02_siege_rome", "eg.v.c02_siege_alexandrie", "eg.v.c02_siege_antioche", "eg.v.c02_siege_jerusalem"], "pool": "lesson", "lessonId": "eg.l202", "skill": "recognition", "answer": "Rome = Pierre et Paul ; Alexandrie = Marc ; Antioche = Pierre ; Jérusalem = Jacques"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l202.e13', 'eg', 'eg.l202', 'eg.g202.sieges', array['eg.g202.sieges','eg.v.c01_heresie']::text[], 'mcq', 'lesson', 'Quel mot désigne un enseignement qui s''écarte de la foi des apôtres ?', array['une hérésie']::text[], 'Rappel de la leçon précédente : hairesis, le « choix ».', 2, '{"type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel mot désigne un enseignement qui s''écarte de la foi des apôtres ?", "answer": "une hérésie", "acceptedAnswers": ["une hérésie"], "explanation": "Rappel de la leçon précédente : hairesis, le « choix ».", "options": ["un siège", "une hérésie", "un dépôt"], "id": "eg.l202.e13", "promptLanguage": "fr", "unitIds": ["eg.g202.sieges", "eg.v.c01_heresie"], "pool": "lesson", "lessonId": "eg.l202", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l202.e14', 'eg', 'eg.l202', 'eg.g202.sieges', array['eg.g202.sieges','eg.v.c01_succession_apostolique']::text[], 'mcq', 'lesson', 'Pourquoi un siège apostolique a-t-il plus d''autorité pour trancher une question de foi ?', array['Sa chaîne d''évêques remonte directement à un apôtre']::text[], 'C''est la succession apostolique : plus on est près de la source, moins la foi a pu changer.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi un siège apostolique a-t-il plus d''autorité pour trancher une question de foi ?", "answer": "Sa chaîne d''évêques remonte directement à un apôtre", "acceptedAnswers": ["Sa chaîne d''évêques remonte directement à un apôtre"], "explanation": "C''est la succession apostolique : plus on est près de la source, moins la foi a pu changer.", "options": ["Sa chaîne d''évêques remonte directement à un apôtre", "Sa ville est la plus riche et la plus peuplée de l''Empire", "Son évêque est le plus savant de tous les philosophes"], "id": "eg.l202.e14", "promptLanguage": "fr", "unitIds": ["eg.g202.sieges", "eg.v.c01_succession_apostolique"], "pool": "lesson", "lessonId": "eg.l202", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
