insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l203.e05', 'eg', 'eg.l203', 'eg.g203.ignace', array['eg.g203.ignace']::text[], 'mcq', 'lesson', 'Combien de lettres Ignace écrit-il en chemin ?', array['sept']::text[], 'Sept lettres, écrites entre deux étapes, avant de mourir à Rome.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Combien de lettres Ignace écrit-il en chemin ?", "answer": "sept", "acceptedAnswers": ["sept"], "explanation": "Sept lettres, écrites entre deux étapes, avant de mourir à Rome.", "options": ["trois", "douze", "sept"], "id": "eg.l203.e05", "promptLanguage": "fr", "unitIds": ["eg.g203.ignace"], "step": 3, "pool": "lesson", "lessonId": "eg.l203", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l203.e06', 'eg', 'eg.l203', 'eg.g203.ignace', array['eg.g203.ignace']::text[], 'mcq', 'lesson', 'Vers quelle année Ignace meurt-il martyr à Rome ?', array['110']::text[], '110, début du IIe siècle. Retiens-le avec Ignace.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Vers quelle année Ignace meurt-il martyr à Rome ?", "answer": "110", "acceptedAnswers": ["110"], "explanation": "110, début du IIe siècle. Retiens-le avec Ignace.", "options": ["33", "110", "1054"], "id": "eg.l203.e06", "promptLanguage": "fr", "unitIds": ["eg.g203.ignace"], "step": 3, "pool": "lesson", "lessonId": "eg.l203", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l203.e07', 'eg', 'eg.l203', 'eg.g203.ignace', array['eg.g203.ignace','eg.v.c02_catholique']::text[], 'mcq', 'lesson', 'Que veut dire katholikos ?', array['selon le tout']::text[], 'Catholique veut dire universelle : pour tous et partout.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire katholikos ?", "answer": "selon le tout", "acceptedAnswers": ["selon le tout"], "explanation": "Catholique veut dire universelle : pour tous et partout.", "options": ["selon la loi", "selon le tout", "selon l''empereur"], "id": "eg.l203.e07", "promptLanguage": "fr", "unitIds": ["eg.g203.ignace", "eg.v.c02_catholique"], "step": 4, "pool": "lesson", "lessonId": "eg.l203", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l203.e08', 'eg', 'eg.l203', 'eg.g203.ignace', array['eg.g203.ignace']::text[], 'mcq', 'lesson', 'Que répond Trajan à Pline à propos des chrétiens ?', array['ne pas les rechercher, mais punir ceux qu''on dénonce']::text[], 'Pas de chasse systématique, mais une dénonciation peut suffire à condamner.', 2, '{"type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que répond Trajan à Pline à propos des chrétiens ?", "answer": "ne pas les rechercher, mais punir ceux qu''on dénonce", "acceptedAnswers": ["ne pas les rechercher, mais punir ceux qu''on dénonce"], "explanation": "Pas de chasse systématique, mais une dénonciation peut suffire à condamner.", "options": ["de les chercher partout et de tous les arrêter vite", "ne pas les rechercher, mais punir ceux qu''on dénonce", "de les laisser prier en paix, sans leur infliger de peine"], "id": "eg.l203.e08", "promptLanguage": "fr", "unitIds": ["eg.g203.ignace"], "step": 5, "pool": "lesson", "lessonId": "eg.l203", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l203.e09', 'eg', 'eg.l203', 'eg.g203.ignace', array['eg.g203.ignace','eg.v.c02_catholique']::text[], 'fill_blank', 'lesson', 'Ignace est le premier à parler de l''Église « ___ ».', array['catholique']::text[], 'Le mot dit que l''Église est la même partout.', 1, '{"type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Ignace est le premier à parler de l''Église « ___ ».", "answer": "catholique", "acceptedAnswers": ["catholique"], "explanation": "Le mot dit que l''Église est la même partout.", "options": ["romaine", "catholique", "copte"], "id": "eg.l203.e09", "promptLanguage": "fr", "unitIds": ["eg.g203.ignace", "eg.v.c02_catholique"], "pool": "lesson", "lessonId": "eg.l203", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l203.e10', 'eg', 'eg.l203', 'eg.g203.ignace', array['eg.g203.ignace']::text[], 'mcq', 'lesson', 'Vrai ou faux : Ignace est évêque de Smyrne.', array['Faux']::text[], 'Il est évêque d''Antioche. Smyrne, c''est la ville de Polycarpe, que tu verras bientôt.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Vrai ou faux : Ignace est évêque de Smyrne.", "answer": "Faux", "acceptedAnswers": ["Faux"], "explanation": "Il est évêque d''Antioche. Smyrne, c''est la ville de Polycarpe, que tu verras bientôt.", "options": ["Vrai", "Faux"], "id": "eg.l203.e10", "promptLanguage": "fr", "unitIds": ["eg.g203.ignace"], "pool": "lesson", "lessonId": "eg.l203", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l203.e11', 'eg', 'eg.l203', 'eg.g203.ignace', array['eg.g203.ignace','eg.v.c02_clement','eg.v.c02_ignace']::text[], 'match', 'lesson', 'Clément, Ignace, Pline : qui a fait quoi ?', '{}'::text[], 'Deux évêques qui écrivent à des chrétiens, un gouverneur qui écrit à l''empereur.', 2, '{"type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Clément, Ignace, Pline : qui a fait quoi ?", "acceptedAnswers": [], "explanation": "Deux évêques qui écrivent à des chrétiens, un gouverneur qui écrit à l''empereur.", "pairs": [{"left": "Clément", "right": "écrit une lettre aux Corinthiens"}, {"left": "Ignace", "right": "écrit sept lettres en route vers Rome"}, {"left": "Pline le Jeune", "right": "interroge l''empereur Trajan"}], "id": "eg.l203.e11", "promptLanguage": "fr", "unitIds": ["eg.g203.ignace", "eg.v.c02_clement", "eg.v.c02_ignace"], "pool": "lesson", "lessonId": "eg.l203", "skill": "recognition", "answer": "Clément = écrit une lettre aux Corinthiens ; Ignace = écrit sept lettres en route vers Rome ; Pline le Jeune = interroge l''empereur Trajan"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l203.e12', 'eg', 'eg.l203', 'eg.g203.ignace', array['eg.g203.ignace']::text[], 'reorder', 'lesson', 'Remets ces trois hommes dans l''ordre où ils écrivent.', array['Clément Ignace Pline']::text[], 'Clément vers 96, Ignace vers 110, Pline vers 112.', 2, '{"type": "reorder", "difficulty": 2, "instruction": "Remets dans l''ordre.", "prompt": "Remets ces trois hommes dans l''ordre où ils écrivent.", "answer": "Clément Ignace Pline", "acceptedAnswers": ["Clément Ignace Pline"], "explanation": "Clément vers 96, Ignace vers 110, Pline vers 112.", "tokens": ["Ignace", "Pline", "Clément"], "id": "eg.l203.e12", "promptLanguage": "fr", "unitIds": ["eg.g203.ignace"], "pool": "lesson", "lessonId": "eg.l203", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l203.e13', 'eg', 'eg.l203', 'eg.g203.ignace', array['eg.g203.ignace','eg.v.c02_siege_antioche']::text[], 'fill_blank', 'lesson', 'Ignace est évêque d''Antioche, un siège rattaché à l''apôtre ___.', array['Pierre']::text[], 'Rappel de la leçon précédente : Antioche, c''est Pierre.', 2, '{"type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Ignace est évêque d''Antioche, un siège rattaché à l''apôtre ___.", "answer": "Pierre", "acceptedAnswers": ["Pierre"], "explanation": "Rappel de la leçon précédente : Antioche, c''est Pierre.", "options": ["Marc", "Pierre", "Jacques"], "id": "eg.l203.e13", "promptLanguage": "fr", "unitIds": ["eg.g203.ignace", "eg.v.c02_siege_antioche"], "pool": "lesson", "lessonId": "eg.l203", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l203.e14', 'eg', 'eg.l203', 'eg.g203.ignace', array['eg.g203.ignace','eg.v.c02_peres_apostoliques','eg.g201.releve']::text[], 'mcq', 'lesson', 'Pourquoi appelle-t-on Clément, Ignace et Polycarpe des Pères « apostoliques » ?', array['Ils sont tout proches des apôtres et de leur enseignement']::text[], 'Ils ont reçu la foi des apôtres eux-mêmes ou de leurs disciples : c''est la succession apostolique en action.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi appelle-t-on Clément, Ignace et Polycarpe des Pères « apostoliques » ?", "answer": "Ils sont tout proches des apôtres et de leur enseignement", "acceptedAnswers": ["Ils sont tout proches des apôtres et de leur enseignement"], "explanation": "Ils ont reçu la foi des apôtres eux-mêmes ou de leurs disciples : c''est la succession apostolique en action.", "options": ["Ils ont tous été choisis par Jésus en personne, comme les douze", "Ils sont tous morts à Jérusalem avec les apôtres", "Ils sont tout proches des apôtres et de leur enseignement"], "id": "eg.l203.e14", "promptLanguage": "fr", "unitIds": ["eg.g203.ignace", "eg.v.c02_peres_apostoliques", "eg.g201.releve"], "pool": "lesson", "lessonId": "eg.l203", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l203.e15', 'eg', 'eg.l203', 'eg.g203.ignace', array['eg.g203.ignace']::text[], 'mcq', 'lesson', 'Pourquoi la réponse de Trajan est-elle quand même dangereuse pour les chrétiens ?', array['Une simple dénonciation peut suffire à les faire punir']::text[], 'N''importe quel voisin hostile peut dénoncer un chrétien. D''où la peur permanente.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi la réponse de Trajan est-elle quand même dangereuse pour les chrétiens ?", "answer": "Une simple dénonciation peut suffire à les faire punir", "acceptedAnswers": ["Une simple dénonciation peut suffire à les faire punir"], "explanation": "N''importe quel voisin hostile peut dénoncer un chrétien. D''où la peur permanente.", "options": ["Il ordonne de brûler tous leurs livres et leurs églises", "Une simple dénonciation peut suffire à les faire punir", "Il interdit à tous les évêques de voyager en Asie"], "id": "eg.l203.e15", "promptLanguage": "fr", "unitIds": ["eg.g203.ignace"], "pool": "lesson", "lessonId": "eg.l203", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l204.e01', 'eg', 'eg.l204', 'eg.g204.polycarpe', array['eg.g204.polycarpe','eg.v.c02_polycarpe']::text[], 'mcq', 'lesson', 'De quel apôtre Polycarpe est-il le disciple ?', array['Jean']::text[], 'Il a connu Jean en personne : c''est ce qui donne du poids à son enseignement.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "De quel apôtre Polycarpe est-il le disciple ?", "answer": "Jean", "acceptedAnswers": ["Jean"], "explanation": "Il a connu Jean en personne : c''est ce qui donne du poids à son enseignement.", "options": ["Pierre", "Jean", "Paul"], "id": "eg.l204.e01", "promptLanguage": "fr", "unitIds": ["eg.g204.polycarpe", "eg.v.c02_polycarpe"], "step": 1, "pool": "lesson", "lessonId": "eg.l204", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l204.e02', 'eg', 'eg.l204', 'eg.g204.polycarpe', array['eg.g204.polycarpe','eg.v.c02_smyrne']::text[], 'mcq', 'lesson', 'Polycarpe est évêque de quelle ville ?', array['Smyrne']::text[], 'Smyrne, aujourd''hui Izmir, en Turquie.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Polycarpe est évêque de quelle ville ?", "answer": "Smyrne", "acceptedAnswers": ["Smyrne"], "explanation": "Smyrne, aujourd''hui Izmir, en Turquie.", "options": ["Smyrne", "Antioche", "Corinthe"], "id": "eg.l204.e02", "promptLanguage": "fr", "unitIds": ["eg.g204.polycarpe", "eg.v.c02_smyrne"], "step": 1, "pool": "lesson", "lessonId": "eg.l204", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l204.e03', 'eg', 'eg.l204', 'eg.g204.polycarpe', array['eg.g204.polycarpe']::text[], 'mcq', 'lesson', 'Que demande le proconsul à Polycarpe ?', array['de renier le Christ']::text[], 'S''il renie, il est libre. C''est le choix que Rome offre à chaque chrétien arrêté.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que demande le proconsul à Polycarpe ?", "answer": "de renier le Christ", "acceptedAnswers": ["de renier le Christ"], "explanation": "S''il renie, il est libre. C''est le choix que Rome offre à chaque chrétien arrêté.", "options": ["de quitter la ville", "de renier le Christ", "de payer un impôt"], "id": "eg.l204.e03", "promptLanguage": "fr", "unitIds": ["eg.g204.polycarpe"], "step": 2, "pool": "lesson", "lessonId": "eg.l204", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l204.e04', 'eg', 'eg.l204', 'eg.g204.polycarpe', array['eg.g204.polycarpe']::text[], 'fill_blank', 'lesson', 'Polycarpe, ___ âgé, est arrêté à Smyrne.', array['très']::text[], 'Un vieil homme qui n''a plus rien à prouver, sauf sa fidélité.', 1, '{"type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Polycarpe, ___ âgé, est arrêté à Smyrne.", "answer": "très", "acceptedAnswers": ["très"], "explanation": "Un vieil homme qui n''a plus rien à prouver, sauf sa fidélité.", "options": ["très", "peu", "jamais"], "id": "eg.l204.e04", "promptLanguage": "fr", "unitIds": ["eg.g204.polycarpe"], "step": 2, "pool": "lesson", "lessonId": "eg.l204", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l204.e05', 'eg', 'eg.l204', 'eg.g204.polycarpe', array['eg.g204.polycarpe']::text[], 'mcq', 'lesson', 'Depuis combien d''années Polycarpe sert-il le Christ ?', array['86 ans']::text[], '86 ans : presque toute une vie de fidélité.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Depuis combien d''années Polycarpe sert-il le Christ ?", "answer": "86 ans", "acceptedAnswers": ["86 ans"], "explanation": "86 ans : presque toute une vie de fidélité.", "options": ["12 ans", "86 ans", "120 ans"], "id": "eg.l204.e05", "promptLanguage": "fr", "unitIds": ["eg.g204.polycarpe"], "step": 3, "pool": "lesson", "lessonId": "eg.l204", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l204.e06', 'eg', 'eg.l204', 'eg.g204.polycarpe', array['eg.g204.polycarpe']::text[], 'mcq', 'lesson', 'Comment Polycarpe appelle-t-il le Christ ?', array['mon Roi']::text[], 'Face au proconsul, il ne reconnaît qu''un seul Roi.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Comment Polycarpe appelle-t-il le Christ ?", "answer": "mon Roi", "acceptedAnswers": ["mon Roi"], "explanation": "Face au proconsul, il ne reconnaît qu''un seul Roi.", "options": ["mon maître", "mon Roi", "mon juge"], "id": "eg.l204.e06", "promptLanguage": "fr", "unitIds": ["eg.g204.polycarpe"], "step": 3, "pool": "lesson", "lessonId": "eg.l204", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l204.e07', 'eg', 'eg.l204', 'eg.g204.polycarpe', array['eg.g204.polycarpe','eg.v.c01_martyr']::text[], 'mcq', 'lesson', 'Que veut dire le grec martys ?', array['témoin']::text[], 'Le martyr témoigne de sa foi jusqu''à la mort.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire le grec martys ?", "answer": "témoin", "acceptedAnswers": ["témoin"], "explanation": "Le martyr témoigne de sa foi jusqu''à la mort.", "options": ["témoin", "voyageur", "soldat"], "id": "eg.l204.e07", "promptLanguage": "fr", "unitIds": ["eg.g204.polycarpe", "eg.v.c01_martyr"], "step": 4, "pool": "lesson", "lessonId": "eg.l204", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l204.e08', 'eg', 'eg.l204', 'eg.g204.polycarpe', array['eg.g204.polycarpe']::text[], 'mcq', 'lesson', 'Qui Polycarpe forme-t-il, futur évêque de Lyon ?', array['Irénée']::text[], 'Jean, Polycarpe, Irénée : retiens cette chaîne.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui Polycarpe forme-t-il, futur évêque de Lyon ?", "answer": "Irénée", "acceptedAnswers": ["Irénée"], "explanation": "Jean, Polycarpe, Irénée : retiens cette chaîne.", "options": ["Justin", "Clément", "Irénée"], "id": "eg.l204.e08", "promptLanguage": "fr", "unitIds": ["eg.g204.polycarpe"], "step": 5, "pool": "lesson", "lessonId": "eg.l204", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l204.e09', 'eg', 'eg.l204', 'eg.g204.polycarpe', array['eg.g204.polycarpe']::text[], 'mcq', 'lesson', 'Vrai ou faux : Polycarpe accepte de renier le Christ pour sauver sa vie.', array['Faux']::text[], 'Il répond au contraire qu''il le sert depuis 86 ans.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Vrai ou faux : Polycarpe accepte de renier le Christ pour sauver sa vie.", "answer": "Faux", "acceptedAnswers": ["Faux"], "explanation": "Il répond au contraire qu''il le sert depuis 86 ans.", "options": ["Vrai", "Faux"], "id": "eg.l204.e09", "promptLanguage": "fr", "unitIds": ["eg.g204.polycarpe"], "pool": "lesson", "lessonId": "eg.l204", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l204.e10', 'eg', 'eg.l204', 'eg.g204.polycarpe', array['eg.g204.polycarpe','eg.v.c02_polycarpe']::text[], 'reorder', 'lesson', 'Remets la chaîne qui relie Jean à Lyon dans l''ordre.', array['Jean Polycarpe Irénée']::text[], 'Jean enseigne Polycarpe, qui forme Irénée.', 2, '{"type": "reorder", "difficulty": 2, "instruction": "Remets dans l''ordre.", "prompt": "Remets la chaîne qui relie Jean à Lyon dans l''ordre.", "answer": "Jean Polycarpe Irénée", "acceptedAnswers": ["Jean Polycarpe Irénée"], "explanation": "Jean enseigne Polycarpe, qui forme Irénée.", "tokens": ["Polycarpe", "Irénée", "Jean"], "id": "eg.l204.e10", "promptLanguage": "fr", "unitIds": ["eg.g204.polycarpe", "eg.v.c02_polycarpe"], "pool": "lesson", "lessonId": "eg.l204", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l204.e11', 'eg', 'eg.l204', 'eg.g204.polycarpe', array['eg.g204.polycarpe','eg.v.c02_clement','eg.v.c02_ignace']::text[], 'match', 'lesson', 'Les Pères apostoliques : à chacun sa scène.', '{}'::text[], 'Trois évêques, trois villes, trois scènes à raconter ce soir.', 2, '{"type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Les Pères apostoliques : à chacun sa scène.", "acceptedAnswers": [], "explanation": "Trois évêques, trois villes, trois scènes à raconter ce soir.", "pairs": [{"left": "Clément", "right": "écrit aux Corinthiens divisés"}, {"left": "Ignace", "right": "est conduit à Rome pour les bêtes"}, {"left": "Polycarpe", "right": "répond au proconsul de Smyrne"}], "id": "eg.l204.e11", "promptLanguage": "fr", "unitIds": ["eg.g204.polycarpe", "eg.v.c02_clement", "eg.v.c02_ignace"], "pool": "lesson", "lessonId": "eg.l204", "skill": "recognition", "answer": "Clément = écrit aux Corinthiens divisés ; Ignace = est conduit à Rome pour les bêtes ; Polycarpe = répond au proconsul de Smyrne"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l204.e12', 'eg', 'eg.l204', 'eg.g204.polycarpe', array['eg.g204.polycarpe','eg.v.c01_martyr']::text[], 'mcq', 'lesson', 'Pourquoi appelle-t-on « témoin » un martyr ?', array['Il affirme sa foi jusqu''à la mort']::text[], 'Sa mort elle-même dit : « Le Christ vaut plus que ma vie. »', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi appelle-t-on « témoin » un martyr ?", "answer": "Il affirme sa foi jusqu''à la mort", "acceptedAnswers": ["Il affirme sa foi jusqu''à la mort"], "explanation": "Sa mort elle-même dit : « Le Christ vaut plus que ma vie. »", "options": ["Il assiste à un procès", "Il affirme sa foi jusqu''à la mort", "Il écrit le récit des événements"], "id": "eg.l204.e12", "promptLanguage": "fr", "unitIds": ["eg.g204.polycarpe", "eg.v.c01_martyr"], "pool": "lesson", "lessonId": "eg.l204", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l204.e13', 'eg', 'eg.l204', 'eg.g204.polycarpe', array['eg.g204.polycarpe','eg.g201.releve']::text[], 'mcq', 'lesson', 'Polycarpe a connu l''apôtre Jean. Pourquoi est-ce précieux face aux hérétiques ?', array['Il tient son enseignement de ceux qui ont connu le Christ']::text[], 'C''est la succession apostolique vécue : un lien vivant avec les apôtres.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Polycarpe a connu l''apôtre Jean. Pourquoi est-ce précieux face aux hérétiques ?", "answer": "Il tient son enseignement de ceux qui ont connu le Christ", "acceptedAnswers": ["Il tient son enseignement de ceux qui ont connu le Christ"], "explanation": "C''est la succession apostolique vécue : un lien vivant avec les apôtres.", "options": ["Il tient son enseignement de ceux qui ont connu le Christ", "Il est plus savant que tous les philosophes de son temps", "Il n''a besoin ni des Écritures ni de la tradition"], "id": "eg.l204.e13", "promptLanguage": "fr", "unitIds": ["eg.g204.polycarpe", "eg.g201.releve"], "pool": "lesson", "lessonId": "eg.l204", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l205.e01', 'eg', 'eg.l205', 'eg.g205.ichthys', array['eg.g205.ichthys','eg.v.c02_culte_empereur']::text[], 'mcq', 'lesson', 'Quel culte les chrétiens refusent-ils ?', array['le culte de l''empereur']::text[], 'Ils prient pour l''empereur mais ne l''adorent pas : Dieu seul est adoré.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel culte les chrétiens refusent-ils ?", "answer": "le culte de l''empereur", "acceptedAnswers": ["le culte de l''empereur"], "explanation": "Ils prient pour l''empereur mais ne l''adorent pas : Dieu seul est adoré.", "options": ["la prière du dimanche", "le culte de l''empereur", "le baptême"], "id": "eg.l205.e01", "promptLanguage": "fr", "unitIds": ["eg.g205.ichthys", "eg.v.c02_culte_empereur"], "step": 1, "pool": "lesson", "lessonId": "eg.l205", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l205.e02', 'eg', 'eg.l205', 'eg.g205.ichthys', array['eg.g205.ichthys']::text[], 'fill_blank', 'lesson', 'Les chrétiens n''adorent que ___.', array['Dieu']::text[], 'C''est le cœur du refus : on peut respecter l''empereur, pas l''adorer.', 1, '{"type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Les chrétiens n''adorent que ___.", "answer": "Dieu", "acceptedAnswers": ["Dieu"], "explanation": "C''est le cœur du refus : on peut respecter l''empereur, pas l''adorer.", "options": ["Dieu", "l''empereur", "Rome"], "id": "eg.l205.e02", "promptLanguage": "fr", "unitIds": ["eg.g205.ichthys"], "step": 1, "pool": "lesson", "lessonId": "eg.l205", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l205.e03', 'eg', 'eg.l205', 'eg.g205.ichthys', array['eg.g205.ichthys']::text[], 'mcq', 'lesson', 'Que célèbrent les chrétiens à huis clos, ce qui nourrit les rumeurs ?', array['l''eucharistie']::text[], 'Personne ne voit ce qui s''y passe, alors on invente des horreurs.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que célèbrent les chrétiens à huis clos, ce qui nourrit les rumeurs ?", "answer": "l''eucharistie", "acceptedAnswers": ["l''eucharistie"], "explanation": "Personne ne voit ce qui s''y passe, alors on invente des horreurs.", "options": ["l''eucharistie", "un banquet impérial", "une fête païenne"], "id": "eg.l205.e03", "promptLanguage": "fr", "unitIds": ["eg.g205.ichthys"], "step": 2, "pool": "lesson", "lessonId": "eg.l205", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
