insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l205.e13', 'eg', 'eg.l205', 'eg.g205.ichthys', array['eg.g205.ichthys','eg.v.c02_ichthys']::text[], 'match', 'lesson', 'Les lettres de ICHTHYS : une lettre, un mot.', '{}'::text[], 'I, X, Θ, Υ, Σ : cinq lettres, une confession de foi.', 2, '{"type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Les lettres de ICHTHYS : une lettre, un mot.", "acceptedAnswers": [], "explanation": "I, X, Θ, Υ, Σ : cinq lettres, une confession de foi.", "pairs": [{"left": "I", "right": "Jésus"}, {"left": "X", "right": "Christ"}, {"left": "Θ", "right": "de Dieu"}, {"left": "Υ", "right": "Fils"}, {"left": "Σ", "right": "Sauveur"}], "id": "eg.l205.e13", "promptLanguage": "fr", "unitIds": ["eg.g205.ichthys", "eg.v.c02_ichthys"], "pool": "lesson", "lessonId": "eg.l205", "skill": "recognition", "answer": "I = Jésus ; X = Christ ; Θ = de Dieu ; Υ = Fils ; Σ = Sauveur"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
