insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l205.e15', 'eg', 'eg.l205', 'eg.g205.ichthys', array['eg.g205.ichthys','eg.v.c02_polycarpe','eg.v.c02_persecution']::text[], 'mcq', 'lesson', 'Quel point commun entre Polycarpe et Blandine ?', array['Ils meurent plutôt que de renier le Christ']::text[], 'Un vieil évêque et une jeune esclave : deux martyrs, deux témoins.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel point commun entre Polycarpe et Blandine ?", "answer": "Ils meurent plutôt que de renier le Christ", "acceptedAnswers": ["Ils meurent plutôt que de renier le Christ"], "explanation": "Un vieil évêque et une jeune esclave : deux martyrs, deux témoins.", "options": ["Ils sont tous les deux évêques de la ville de Lyon", "Ils meurent plutôt que de renier le Christ", "Ils vivent tous les deux à Alexandrie sous Septime Sévère"], "id": "eg.l205.e15", "promptLanguage": "fr", "unitIds": ["eg.g205.ichthys", "eg.v.c02_polycarpe", "eg.v.c02_persecution"], "pool": "lesson", "lessonId": "eg.l205", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l205.e16', 'eg', 'eg.l205', 'eg.g205.ichthys', array['eg.g205.ichthys']::text[], 'mcq', 'lesson', 'Pourquoi les chrétiens ont-ils besoin d''un signe secret comme le poisson ?', array['Ils risquent d''être dénoncés et punis']::text[], 'Rappelle-toi Trajan : une dénonciation peut suffire. Le poisson permet de se reconnaître sans se trahir.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi les chrétiens ont-ils besoin d''un signe secret comme le poisson ?", "answer": "Ils risquent d''être dénoncés et punis", "acceptedAnswers": ["Ils risquent d''être dénoncés et punis"], "explanation": "Rappelle-toi Trajan : une dénonciation peut suffire. Le poisson permet de se reconnaître sans se trahir.", "options": ["Ils risquent d''être dénoncés et punis", "Ils veulent cacher leur foi à jamais", "Ils n''ont pas d''autre dessin"], "id": "eg.l205.e16", "promptLanguage": "fr", "unitIds": ["eg.g205.ichthys"], "pool": "lesson", "lessonId": "eg.l205", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
