insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l206.e03', 'eg', 'eg.l206', 'eg.g206.justin', array['eg.g206.justin']::text[], 'mcq', 'lesson', 'Justin écrit ses Apologies à qui ?', array['à l''empereur']::text[], 'Il parle directement au chef de l''Empire pour dire : les chrétiens ne sont pas des criminels.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Justin écrit ses Apologies à qui ?", "answer": "à l''empereur", "acceptedAnswers": ["à l''empereur"], "explanation": "Il parle directement au chef de l''Empire pour dire : les chrétiens ne sont pas des criminels.", "options": ["à ses disciples", "à Polycarpe", "à l''empereur"], "id": "eg.l206.e03", "promptLanguage": "fr", "unitIds": ["eg.g206.justin"], "step": 2, "pool": "lesson", "lessonId": "eg.l206", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l206.e04', 'eg', 'eg.l206', 'eg.g206.justin', array['eg.g206.justin','eg.v.c02_semences']::text[], 'mcq', 'lesson', 'Comment Justin appelle-t-il les parts de vérité trouvées chez les philosophes ?', array['des semences du Verbe']::text[], 'Le Verbe, le Christ, a semé un peu de vérité partout.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Comment Justin appelle-t-il les parts de vérité trouvées chez les philosophes ?", "answer": "des semences du Verbe", "acceptedAnswers": ["des semences du Verbe"], "explanation": "Le Verbe, le Christ, a semé un peu de vérité partout.", "options": ["des erreurs du Verbe", "des semences du Verbe", "des lettres du Verbe"], "id": "eg.l206.e04", "promptLanguage": "fr", "unitIds": ["eg.g206.justin", "eg.v.c02_semences"], "step": 3, "pool": "lesson", "lessonId": "eg.l206", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l206.e05', 'eg', 'eg.l206', 'eg.g206.justin', array['eg.g206.justin']::text[], 'mcq', 'lesson', 'Où Justin est-il martyrisé ?', array['à Rome']::text[], 'Martyr : il est mort en témoin du Christ.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Où Justin est-il martyrisé ?", "answer": "à Rome", "acceptedAnswers": ["à Rome"], "explanation": "Martyr : il est mort en témoin du Christ.", "options": ["à Naplouse", "à Rome", "à Carthage"], "id": "eg.l206.e05", "promptLanguage": "fr", "unitIds": ["eg.g206.justin"], "step": 4, "pool": "lesson", "lessonId": "eg.l206", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l206.e06', 'eg', 'eg.l206', 'eg.g206.justin', array['eg.g206.justin']::text[], 'mcq', 'lesson', 'Quel livre de Justin est un débat avec un Juif ?', array['le Dialogue avec Tryphon']::text[], 'Justin y montre que les Écritures annoncent le Christ.', 2, '{"type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel livre de Justin est un débat avec un Juif ?", "answer": "le Dialogue avec Tryphon", "acceptedAnswers": ["le Dialogue avec Tryphon"], "explanation": "Justin y montre que les Écritures annoncent le Christ.", "options": ["les Apologies adressées à l''empereur", "le Dialogue avec Tryphon", "l''Apologétique écrite à Carthage"], "id": "eg.l206.e06", "promptLanguage": "fr", "unitIds": ["eg.g206.justin"], "step": 4, "pool": "lesson", "lessonId": "eg.l206", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l206.e07', 'eg', 'eg.l206', 'eg.g206.justin', array['eg.g206.justin','eg.v.c02_tertullien']::text[], 'mcq', 'lesson', 'Quelle est la célèbre phrase de Tertullien ?', array['Le sang des martyrs est une semence de chrétiens']::text[], 'Plus on tue de chrétiens, plus on en voit naître.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle est la célèbre phrase de Tertullien ?", "answer": "Le sang des martyrs est une semence de chrétiens", "acceptedAnswers": ["Le sang des martyrs est une semence de chrétiens"], "explanation": "Plus on tue de chrétiens, plus on en voit naître.", "options": ["Le silence des chrétiens est une semence de paix", "Le sang des martyrs est une semence de chrétiens", "Le sang des empereurs est une semence de tyrans"], "id": "eg.l206.e07", "promptLanguage": "fr", "unitIds": ["eg.g206.justin", "eg.v.c02_tertullien"], "step": 5, "pool": "lesson", "lessonId": "eg.l206", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l206.e08', 'eg', 'eg.l206', 'eg.g206.justin', array['eg.g206.justin']::text[], 'mcq', 'lesson', 'Quel est le métier de Tertullien ?', array['juriste']::text[], 'Un avocat de Carthage, habitué à plaider.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel est le métier de Tertullien ?", "answer": "juriste", "acceptedAnswers": ["juriste"], "explanation": "Un avocat de Carthage, habitué à plaider.", "options": ["médecin", "juriste", "soldat"], "id": "eg.l206.e08", "promptLanguage": "fr", "unitIds": ["eg.g206.justin"], "step": 5, "pool": "lesson", "lessonId": "eg.l206", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l206.e09', 'eg', 'eg.l206', 'eg.g206.justin', array['eg.g206.justin']::text[], 'mcq', 'lesson', 'À qui écrivent les apologistes ?', array['aux païens']::text[], 'Pour répondre à leurs accusations et leur expliquer la foi.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "À qui écrivent les apologistes ?", "answer": "aux païens", "acceptedAnswers": ["aux païens"], "explanation": "Pour répondre à leurs accusations et leur expliquer la foi.", "options": ["aux païens", "aux évêques", "aux apôtres"], "id": "eg.l206.e09", "promptLanguage": "fr", "unitIds": ["eg.g206.justin"], "step": 6, "pool": "lesson", "lessonId": "eg.l206", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l206.e10', 'eg', 'eg.l206', 'eg.g206.justin', array['eg.g206.justin','eg.v.c02_justin']::text[], 'fill_blank', 'lesson', 'Justin est surnommé Justin ___.', array['Martyr']::text[], 'Il meurt martyr à Rome vers 165.', 1, '{"type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Justin est surnommé Justin ___.", "answer": "Martyr", "acceptedAnswers": ["Martyr"], "explanation": "Il meurt martyr à Rome vers 165.", "options": ["Martyr", "Philosophe", "Apôtre"], "id": "eg.l206.e10", "promptLanguage": "fr", "unitIds": ["eg.g206.justin", "eg.v.c02_justin"], "pool": "lesson", "lessonId": "eg.l206", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l206.e11', 'eg', 'eg.l206', 'eg.g206.justin', array['eg.g206.justin','eg.v.c02_apologiste']::text[], 'fill_blank', 'lesson', 'Les Pères apostoliques écrivent aux chrétiens ; les apologistes écrivent aux ___.', array['païens']::text[], 'Les uns enseignent à la maison, les autres défendent sur la place publique.', 2, '{"type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Les Pères apostoliques écrivent aux chrétiens ; les apologistes écrivent aux ___.", "answer": "païens", "acceptedAnswers": ["païens"], "explanation": "Les uns enseignent à la maison, les autres défendent sur la place publique.", "options": ["païens", "apôtres", "évêques"], "id": "eg.l206.e11", "promptLanguage": "fr", "unitIds": ["eg.g206.justin", "eg.v.c02_apologiste"], "pool": "lesson", "lessonId": "eg.l206", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l206.e12', 'eg', 'eg.l206', 'eg.g206.justin', array['eg.g206.justin','eg.v.c02_clement','eg.v.c02_ignace','eg.v.c02_tertullien']::text[], 'match', 'lesson', 'Qui écrit à qui ?', '{}'::text[], 'Deux Pères apostoliques parlent à l''intérieur, deux apologistes à l''extérieur.', 2, '{"type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Qui écrit à qui ?", "acceptedAnswers": [], "explanation": "Deux Pères apostoliques parlent à l''intérieur, deux apologistes à l''extérieur.", "pairs": [{"left": "Clément", "right": "aux chrétiens de Corinthe"}, {"left": "Ignace", "right": "aux Églises sur sa route"}, {"left": "Justin", "right": "à l''empereur"}, {"left": "Tertullien", "right": "aux magistrats romains"}], "id": "eg.l206.e12", "promptLanguage": "fr", "unitIds": ["eg.g206.justin", "eg.v.c02_clement", "eg.v.c02_ignace", "eg.v.c02_tertullien"], "pool": "lesson", "lessonId": "eg.l206", "skill": "recognition", "answer": "Clément = aux chrétiens de Corinthe ; Ignace = aux Églises sur sa route ; Justin = à l''empereur ; Tertullien = aux magistrats romains"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l206.e13', 'eg', 'eg.l206', 'eg.g206.justin', array['eg.g206.justin']::text[], 'reorder', 'lesson', 'Remets la phrase célèbre de Tertullien dans l''ordre.', array['Le sang des martyrs est une semence de chrétiens']::text[], 'Sa phrase résume tout : la persécution fait grandir l''Église.', 2, '{"type": "reorder", "difficulty": 2, "instruction": "Remets dans l''ordre.", "prompt": "Remets la phrase célèbre de Tertullien dans l''ordre.", "answer": "Le sang des martyrs est une semence de chrétiens", "acceptedAnswers": ["Le sang des martyrs est une semence de chrétiens"], "explanation": "Sa phrase résume tout : la persécution fait grandir l''Église.", "tokens": ["sang", "des", "martyrs", "est", "une", "semence", "de", "chrétiens", "Le"], "id": "eg.l206.e13", "promptLanguage": "fr", "unitIds": ["eg.g206.justin"], "pool": "lesson", "lessonId": "eg.l206", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l206.e14', 'eg', 'eg.l206', 'eg.g206.justin', array['eg.g206.justin','eg.v.c02_peres_apostoliques']::text[], 'mcq', 'lesson', 'Justin appartient à quelle famille d''écrivains ?', array['les apologistes']::text[], 'Il écrit à ceux du dehors, comme Tertullien.', 2, '{"type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Justin appartient à quelle famille d''écrivains ?", "answer": "les apologistes", "acceptedAnswers": ["les apologistes"], "explanation": "Il écrit à ceux du dehors, comme Tertullien.", "options": ["les apologistes", "les Pères apostoliques", "les gnostiques"], "id": "eg.l206.e14", "promptLanguage": "fr", "unitIds": ["eg.g206.justin", "eg.v.c02_peres_apostoliques"], "pool": "lesson", "lessonId": "eg.l206", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l206.e15', 'eg', 'eg.l206', 'eg.g206.justin', array['eg.g206.justin','eg.v.c02_blandine']::text[], 'mcq', 'lesson', 'Selon Tertullien, pourquoi le sang des martyrs fait-il grandir l''Église ?', array['Leur courage fait réfléchir ceux qui les regardent mourir']::text[], 'On se demande : pourquoi meurent-ils ainsi ? La réponse conduit à la foi.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Selon Tertullien, pourquoi le sang des martyrs fait-il grandir l''Église ?", "answer": "Leur courage fait réfléchir ceux qui les regardent mourir", "acceptedAnswers": ["Leur courage fait réfléchir ceux qui les regardent mourir"], "explanation": "On se demande : pourquoi meurent-ils ainsi ? La réponse conduit à la foi.", "options": ["Leur courage fait réfléchir ceux qui les regardent mourir", "Les empereurs deviennent chrétiens par crainte des martyrs", "Les martyrs apparaissent en songe aux païens de la ville"], "id": "eg.l206.e15", "promptLanguage": "fr", "unitIds": ["eg.g206.justin", "eg.v.c02_blandine"], "pool": "lesson", "lessonId": "eg.l206", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l206.e16', 'eg', 'eg.l206', 'eg.g206.justin', array['eg.g206.justin']::text[], 'mcq', 'lesson', 'Un philosophe dit à Justin : « Je cherche la sagesse. » Que lui répond Justin ?', array['Que le Christ, le Verbe, accomplit toute quête de sagesse']::text[], 'Pour Justin, le philosophe n''a pas tout faux : il a des semences, et le Christ en est la plénitude.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Un philosophe dit à Justin : « Je cherche la sagesse. » Que lui répond Justin ?", "answer": "Que le Christ, le Verbe, accomplit toute quête de sagesse", "acceptedAnswers": ["Que le Christ, le Verbe, accomplit toute quête de sagesse"], "explanation": "Pour Justin, le philosophe n''a pas tout faux : il a des semences, et le Christ en est la plénitude.", "options": ["Qu''il doit brûler tous ses livres de philosophie païenne", "Que le Christ, le Verbe, accomplit toute quête de sagesse", "Qu''il n''existe aucune part de vérité chez les philosophes"], "id": "eg.l206.e16", "promptLanguage": "fr", "unitIds": ["eg.g206.justin"], "pool": "lesson", "lessonId": "eg.l206", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l207.e01', 'eg', 'eg.l207', 'eg.g207.gnose', array['eg.g207.gnose','eg.v.c02_gnose']::text[], 'mcq', 'lesson', 'Que veut dire le grec gnosis ?', array['connaissance']::text[], 'La gnose promet de « savoir », et un savoir secret.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire le grec gnosis ?", "answer": "connaissance", "acceptedAnswers": ["connaissance"], "explanation": "La gnose promet de « savoir », et un savoir secret.", "options": ["connaissance", "prière", "puissance"], "id": "eg.l207.e01", "promptLanguage": "fr", "unitIds": ["eg.g207.gnose", "eg.v.c02_gnose"], "step": 1, "pool": "lesson", "lessonId": "eg.l207", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l207.e02', 'eg', 'eg.l207', 'eg.g207.gnose', array['eg.g207.gnose']::text[], 'mcq', 'lesson', 'Selon les gnostiques, à qui le salut est-il réservé ?', array['aux initiés']::text[], 'Pour l''Église, au contraire, le salut est offert à tous.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Selon les gnostiques, à qui le salut est-il réservé ?", "answer": "aux initiés", "acceptedAnswers": ["aux initiés"], "explanation": "Pour l''Église, au contraire, le salut est offert à tous.", "options": ["à tous les baptisés", "aux initiés", "aux évêques seulement"], "id": "eg.l207.e02", "promptLanguage": "fr", "unitIds": ["eg.g207.gnose"], "step": 1, "pool": "lesson", "lessonId": "eg.l207", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l207.e03', 'eg', 'eg.l207', 'eg.g207.gnose', array['eg.g207.gnose']::text[], 'fill_blank', 'lesson', 'Pour les gnostiques, la matière est ___.', array['mauvaise']::text[], 'D''où le mépris du corps et de la création.', 1, '{"type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Pour les gnostiques, la matière est ___.", "answer": "mauvaise", "acceptedAnswers": ["mauvaise"], "explanation": "D''où le mépris du corps et de la création.", "options": ["mauvaise", "sacrée", "éternelle"], "id": "eg.l207.e03", "promptLanguage": "fr", "unitIds": ["eg.g207.gnose"], "step": 2, "pool": "lesson", "lessonId": "eg.l207", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l207.e04', 'eg', 'eg.l207', 'eg.g207.gnose', array['eg.g207.gnose']::text[], 'mcq', 'lesson', 'Comment s''appelle le dieu inférieur qui aurait créé le monde ?', array['le démiurge']::text[], 'Le démiurge est « l''artisan » du monde imparfait.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Comment s''appelle le dieu inférieur qui aurait créé le monde ?", "answer": "le démiurge", "acceptedAnswers": ["le démiurge"], "explanation": "Le démiurge est « l''artisan » du monde imparfait.", "options": ["le Paraclet", "le démiurge", "le proconsul"], "id": "eg.l207.e04", "promptLanguage": "fr", "unitIds": ["eg.g207.gnose"], "step": 2, "pool": "lesson", "lessonId": "eg.l207", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l207.e05', 'eg', 'eg.l207', 'eg.g207.gnose', array['eg.g207.gnose','eg.v.c01_docetisme']::text[], 'mcq', 'lesson', 'Que veut dire le grec dokein, d''où vient « docétisme » ?', array['sembler']::text[], 'Le Christ aurait seulement « semblé » avoir un corps.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire le grec dokein, d''où vient « docétisme » ?", "answer": "sembler", "acceptedAnswers": ["sembler"], "explanation": "Le Christ aurait seulement « semblé » avoir un corps.", "options": ["sembler", "mourir", "enseigner"], "id": "eg.l207.e05", "promptLanguage": "fr", "unitIds": ["eg.g207.gnose", "eg.v.c01_docetisme"], "step": 3, "pool": "lesson", "lessonId": "eg.l207", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
