insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l207.e07', 'eg', 'eg.l207', 'eg.g207.gnose', array['eg.g207.gnose']::text[], 'mcq', 'lesson', 'Sans vrai corps, le Christ n''aurait pas vraiment…', array['souffert']::text[], 'Pas de vraie souffrance, pas de vraie croix, pas de vrai salut.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Sans vrai corps, le Christ n''aurait pas vraiment…", "answer": "souffert", "acceptedAnswers": ["souffert"], "explanation": "Pas de vraie souffrance, pas de vraie croix, pas de vrai salut.", "options": ["voyagé", "enseigné", "souffert"], "id": "eg.l207.e07", "promptLanguage": "fr", "unitIds": ["eg.g207.gnose"], "step": 4, "pool": "lesson", "lessonId": "eg.l207", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
