insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l207.e09', 'eg', 'eg.l207', 'eg.g207.gnose', array['eg.g207.gnose']::text[], 'mcq', 'lesson', 'Irénée de Lyon est le disciple de quel évêque de Smyrne ?', array['Polycarpe']::text[], 'Jean, Polycarpe, Irénée : la chaîne de la foi.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Irénée de Lyon est le disciple de quel évêque de Smyrne ?", "answer": "Polycarpe", "acceptedAnswers": ["Polycarpe"], "explanation": "Jean, Polycarpe, Irénée : la chaîne de la foi.", "options": ["Polycarpe", "Ignace", "Clément"], "id": "eg.l207.e09", "promptLanguage": "fr", "unitIds": ["eg.g207.gnose"], "step": 5, "pool": "lesson", "lessonId": "eg.l207", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l207.e10', 'eg', 'eg.l207', 'eg.g207.gnose', array['eg.g207.gnose','eg.v.c02_nag_hammadi']::text[], 'mcq', 'lesson', 'En quelle langue sont écrits les textes de Nag Hammadi ?', array['en copte']::text[], 'Ils viennent d''Égypte : ce sont des livres en copte.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle langue sont écrits les textes de Nag Hammadi ?", "answer": "en copte", "acceptedAnswers": ["en copte"], "explanation": "Ils viennent d''Égypte : ce sont des livres en copte.", "options": ["en latin", "en copte", "en hébreu"], "id": "eg.l207.e10", "promptLanguage": "fr", "unitIds": ["eg.g207.gnose", "eg.v.c02_nag_hammadi"], "step": 6, "pool": "lesson", "lessonId": "eg.l207", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l207.e11', 'eg', 'eg.l207', 'eg.g207.gnose', array['eg.g207.gnose']::text[], 'mcq', 'lesson', 'Vrai ou faux : les gnostiques pensent que la création est très bonne.', array['Faux']::text[], 'Pour eux, la matière est mauvaise. L''Église répond avec la Genèse : Dieu vit que cela était très bon.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Vrai ou faux : les gnostiques pensent que la création est très bonne.", "answer": "Faux", "acceptedAnswers": ["Faux"], "explanation": "Pour eux, la matière est mauvaise. L''Église répond avec la Genèse : Dieu vit que cela était très bon.", "options": ["Vrai", "Faux"], "id": "eg.l207.e11", "promptLanguage": "fr", "unitIds": ["eg.g207.gnose"], "pool": "lesson", "lessonId": "eg.l207", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l207.e12', 'eg', 'eg.l207', 'eg.g207.gnose', array['eg.g207.gnose','eg.v.c02_gnose','eg.v.c01_docetisme','eg.v.c02_nag_hammadi']::text[], 'match', 'lesson', 'Un mot, une idée.', '{}'::text[], 'Quatre mots pour reconnaître la gnose.', 2, '{"type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Un mot, une idée.", "acceptedAnswers": [], "explanation": "Quatre mots pour reconnaître la gnose.", "pairs": [{"left": "la gnose", "right": "une connaissance secrète pour initiés"}, {"left": "le démiurge", "right": "le dieu inférieur qui crée le monde"}, {"left": "le docétisme", "right": "un Christ au corps seulement apparent"}, {"left": "Nag Hammadi", "right": "une bibliothèque gnostique en copte"}], "id": "eg.l207.e12", "promptLanguage": "fr", "unitIds": ["eg.g207.gnose", "eg.v.c02_gnose", "eg.v.c01_docetisme", "eg.v.c02_nag_hammadi"], "pool": "lesson", "lessonId": "eg.l207", "skill": "recognition", "answer": "la gnose = une connaissance secrète pour initiés ; le démiurge = le dieu inférieur qui crée le monde ; le docétisme = un Christ au corps seulement apparent ; Nag Hammadi = une bibliothèque gnostique en copte"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l207.e13', 'eg', 'eg.l207', 'eg.g207.gnose', array['eg.g207.gnose','eg.v.c02_ignace']::text[], 'mcq', 'lesson', 'Quel Père apostolique insiste déjà sur le corps réel du Christ ?', array['Ignace']::text[], 'Ignace répète dans ses lettres que le corps du Christ est bien réel.', 2, '{"type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel Père apostolique insiste déjà sur le corps réel du Christ ?", "answer": "Ignace", "acceptedAnswers": ["Ignace"], "explanation": "Ignace répète dans ses lettres que le corps du Christ est bien réel.", "options": ["Ignace", "Clément", "Justin"], "id": "eg.l207.e13", "promptLanguage": "fr", "unitIds": ["eg.g207.gnose", "eg.v.c02_ignace"], "pool": "lesson", "lessonId": "eg.l207", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l207.e14', 'eg', 'eg.l207', 'eg.g207.gnose', array['eg.g207.gnose','eg.v.c01_docetisme']::text[], 'reorder', 'lesson', 'Remets le raisonnement des docètes dans l''ordre.', array['Matière-mauvaise Incarnation-impossible Corps-apparent']::text[], 'La matière est mauvaise, donc Dieu ne peut pas se faire chair, donc le corps du Christ n''est qu''apparent.', 2, '{"type": "reorder", "difficulty": 2, "instruction": "Remets dans l''ordre.", "prompt": "Remets le raisonnement des docètes dans l''ordre.", "answer": "Matière-mauvaise Incarnation-impossible Corps-apparent", "acceptedAnswers": ["Matière-mauvaise Incarnation-impossible Corps-apparent"], "explanation": "La matière est mauvaise, donc Dieu ne peut pas se faire chair, donc le corps du Christ n''est qu''apparent.", "tokens": ["Incarnation-impossible", "Corps-apparent", "Matière-mauvaise"], "id": "eg.l207.e14", "promptLanguage": "fr", "unitIds": ["eg.g207.gnose", "eg.v.c01_docetisme"], "pool": "lesson", "lessonId": "eg.l207", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l207.e15', 'eg', 'eg.l207', 'eg.g207.gnose', array['eg.g207.gnose','eg.v.c01_docetisme']::text[], 'mcq', 'lesson', 'Pourquoi le docétisme détruit-il le salut ?', array['Un Christ sans vrai corps n''a pas vraiment souffert']::text[], 'Si la croix n''est qu''une apparence, le salut aussi. Toute la foi tient dans la réalité de l''Incarnation.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi le docétisme détruit-il le salut ?", "answer": "Un Christ sans vrai corps n''a pas vraiment souffert", "acceptedAnswers": ["Un Christ sans vrai corps n''a pas vraiment souffert"], "explanation": "Si la croix n''est qu''une apparence, le salut aussi. Toute la foi tient dans la réalité de l''Incarnation.", "options": ["Un Christ sans vrai corps n''a pas vraiment souffert", "Il interdit aux chrétiens de prier le Christ en public", "Il supprime les évêques et tous les sacrements de l''Église"], "id": "eg.l207.e15", "promptLanguage": "fr", "unitIds": ["eg.g207.gnose", "eg.v.c01_docetisme"], "pool": "lesson", "lessonId": "eg.l207", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l207.e16', 'eg', 'eg.l207', 'eg.g207.gnose', array['eg.g207.gnose','eg.v.c02_irenee','eg.v.c01_succession_apostolique']::text[], 'mcq', 'lesson', 'Pourquoi Irénée insiste-t-il sur l''enseignement public des évêques ?', array['Chacun peut vérifier qu''il vient bien des apôtres']::text[], 'Un enseignement public se vérifie ; un secret réservé aux initiés, jamais.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi Irénée insiste-t-il sur l''enseignement public des évêques ?", "answer": "Chacun peut vérifier qu''il vient bien des apôtres", "acceptedAnswers": ["Chacun peut vérifier qu''il vient bien des apôtres"], "explanation": "Un enseignement public se vérifie ; un secret réservé aux initiés, jamais.", "options": ["Chacun peut vérifier qu''il vient bien des apôtres", "Les évêques sont plus savants que les gnostiques", "Les secrets sont interdits par la loi de l''empereur"], "id": "eg.l207.e16", "promptLanguage": "fr", "unitIds": ["eg.g207.gnose", "eg.v.c02_irenee", "eg.v.c01_succession_apostolique"], "pool": "lesson", "lessonId": "eg.l207", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
