insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l208.e03', 'eg', 'eg.l208', 'eg.g208.marcion', array['eg.g208.marcion']::text[], 'mcq', 'lesson', 'Combien de dieux Marcion croit-il ?', array['deux']::text[], 'Un Dieu de justice et un Dieu d''amour : l''Église refuse cette coupure.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Combien de dieux Marcion croit-il ?", "answer": "deux", "acceptedAnswers": ["deux"], "explanation": "Un Dieu de justice et un Dieu d''amour : l''Église refuse cette coupure.", "options": ["un", "deux", "douze"], "id": "eg.l208.e03", "promptLanguage": "fr", "unitIds": ["eg.g208.marcion"], "step": 2, "pool": "lesson", "lessonId": "eg.l208", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
