insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l208.e13', 'eg', 'eg.l208', 'eg.g208.marcion', array['eg.g208.marcion','eg.v.c02_marcion','eg.v.c02_contre_marcion']::text[], 'match', 'lesson', 'Marcion et ses adversaires : qui dit quoi ?', '{}'::text[], 'Deux Testaments, un seul Dieu : c''est la réponse de l''Église.', 2, '{"type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Marcion et ses adversaires : qui dit quoi ?", "acceptedAnswers": [], "explanation": "Deux Testaments, un seul Dieu : c''est la réponse de l''Église.", "pairs": [{"left": "Marcion", "right": "deux dieux, un seul Testament"}, {"left": "l''Église", "right": "un seul Dieu, deux Testaments"}, {"left": "Tertullien", "right": "écrit Contre Marcion"}, {"left": "Polycarpe", "right": "premier-né de Satan"}], "id": "eg.l208.e13", "promptLanguage": "fr", "unitIds": ["eg.g208.marcion", "eg.v.c02_marcion", "eg.v.c02_contre_marcion"], "pool": "lesson", "lessonId": "eg.l208", "skill": "recognition", "answer": "Marcion = deux dieux, un seul Testament ; l''Église = un seul Dieu, deux Testaments ; Tertullien = écrit Contre Marcion ; Polycarpe = premier-né de Satan"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l208.e14', 'eg', 'eg.l208', 'eg.g208.marcion', array['eg.g208.marcion']::text[], 'mcq', 'lesson', 'Pourquoi la liste de Marcion oblige-t-elle l''Église à réagir ?', array['Elle doit dire clairement quels livres elle reçoit']::text[], 'Si un chrétien propose sa liste, l''Église doit proposer la sienne : c''est l''origine du canon.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi la liste de Marcion oblige-t-elle l''Église à réagir ?", "answer": "Elle doit dire clairement quels livres elle reçoit", "acceptedAnswers": ["Elle doit dire clairement quels livres elle reçoit"], "explanation": "Si un chrétien propose sa liste, l''Église doit proposer la sienne : c''est l''origine du canon.", "options": ["Elle doit dire clairement quels livres elle reçoit", "Elle doit brûler les lettres de Paul et les Évangiles", "Elle doit demander à l''empereur de choisir les livres"], "id": "eg.l208.e14", "promptLanguage": "fr", "unitIds": ["eg.g208.marcion"], "pool": "lesson", "lessonId": "eg.l208", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l208.e15', 'eg', 'eg.l208', 'eg.g208.marcion', array['eg.g208.marcion','eg.v.c02_gnose']::text[], 'mcq', 'lesson', 'Quel point commun entre Marcion et les gnostiques ?', array['Ils séparent le Dieu créateur du vrai Dieu']::text[], 'Chez les gnostiques, un démiurge crée le monde ; chez Marcion, le créateur n''est pas le Père de Jésus.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel point commun entre Marcion et les gnostiques ?", "answer": "Ils séparent le Dieu créateur du vrai Dieu", "acceptedAnswers": ["Ils séparent le Dieu créateur du vrai Dieu"], "explanation": "Chez les gnostiques, un démiurge crée le monde ; chez Marcion, le créateur n''est pas le Père de Jésus.", "options": ["Ils séparent le Dieu créateur du vrai Dieu", "Ils nient que Jésus ait réellement existé un jour", "Ils refusent tous les évêques et tous les sacrements"], "id": "eg.l208.e15", "promptLanguage": "fr", "unitIds": ["eg.g208.marcion", "eg.v.c02_gnose"], "pool": "lesson", "lessonId": "eg.l208", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l209.e01', 'eg', 'eg.l209', 'eg.g209.montan', array['eg.g209.montan','eg.v.c02_paraclet']::text[], 'mcq', 'lesson', 'Au nom de qui Montanus prétend-il parler ?', array['du Paraclet']::text[], 'Le Paraclet, c''est l''Esprit Saint que Jésus a promis.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Au nom de qui Montanus prétend-il parler ?", "answer": "du Paraclet", "acceptedAnswers": ["du Paraclet"], "explanation": "Le Paraclet, c''est l''Esprit Saint que Jésus a promis.", "options": ["de l''empereur", "du Paraclet", "de Polycarpe"], "id": "eg.l209.e01", "promptLanguage": "fr", "unitIds": ["eg.g209.montan", "eg.v.c02_paraclet"], "step": 1, "pool": "lesson", "lessonId": "eg.l209", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l209.e02', 'eg', 'eg.l209', 'eg.g209.montan', array['eg.g209.montan','eg.v.c02_montanus']::text[], 'mcq', 'lesson', 'Dans quelle région Montanus apparaît-il ?', array['Phrygie']::text[], 'La Phrygie, en Asie Mineure.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Dans quelle région Montanus apparaît-il ?", "answer": "Phrygie", "acceptedAnswers": ["Phrygie"], "explanation": "La Phrygie, en Asie Mineure.", "options": ["Phrygie", "Égypte", "Gaule"], "id": "eg.l209.e02", "promptLanguage": "fr", "unitIds": ["eg.g209.montan", "eg.v.c02_montanus"], "step": 1, "pool": "lesson", "lessonId": "eg.l209", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l209.e03', 'eg', 'eg.l209', 'eg.g209.montan', array['eg.g209.montan']::text[], 'mcq', 'lesson', 'Que cherchent les montanistes, à tort ?', array['le martyre']::text[], 'Chercher la mort n''est pas ce que demande l''Évangile.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que cherchent les montanistes, à tort ?", "answer": "le martyre", "acceptedAnswers": ["le martyre"], "explanation": "Chercher la mort n''est pas ce que demande l''Évangile.", "options": ["le martyre", "un évêque", "un empereur"], "id": "eg.l209.e03", "promptLanguage": "fr", "unitIds": ["eg.g209.montan"], "step": 2, "pool": "lesson", "lessonId": "eg.l209", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
