insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l209.e12', 'eg', 'eg.l209', 'eg.g209.montan', array['eg.g209.montan','eg.v.c02_montanus','eg.v.c02_priscilla','eg.v.c02_paraclet']::text[], 'match', 'lesson', 'Qui est qui dans le montanisme ?', '{}'::text[], 'Un prophète, deux prophétesses, et l''Esprit au nom duquel ils parlent.', 2, '{"type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Qui est qui dans le montanisme ?", "acceptedAnswers": [], "explanation": "Un prophète, deux prophétesses, et l''Esprit au nom duquel ils parlent.", "pairs": [{"left": "Montanus", "right": "prophétise en Phrygie vers 170"}, {"left": "Priscilla et Maximilla", "right": "ses deux prophétesses"}, {"left": "le Paraclet", "right": "l''Esprit Saint promis par Jésus"}], "id": "eg.l209.e12", "promptLanguage": "fr", "unitIds": ["eg.g209.montan", "eg.v.c02_montanus", "eg.v.c02_priscilla", "eg.v.c02_paraclet"], "pool": "lesson", "lessonId": "eg.l209", "skill": "recognition", "answer": "Montanus = prophétise en Phrygie vers 170 ; Priscilla et Maximilla = ses deux prophétesses ; le Paraclet = l''Esprit Saint promis par Jésus"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l209.e13', 'eg', 'eg.l209', 'eg.g209.montan', array['eg.g209.montan','eg.v.c02_gnose','eg.v.c02_marcion']::text[], 'match', 'lesson', 'Quatre erreurs, quatre auteurs ou idées.', '{}'::text[], 'Chacun apporte « plus » que la foi reçue des apôtres.', 2, '{"type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Quatre erreurs, quatre auteurs ou idées.", "acceptedAnswers": [], "explanation": "Chacun apporte « plus » que la foi reçue des apôtres.", "pairs": [{"left": "les gnostiques", "right": "le salut par un savoir secret"}, {"left": "Marcion", "right": "deux dieux"}, {"left": "Montanus", "right": "une nouvelle prophétie"}], "id": "eg.l209.e13", "promptLanguage": "fr", "unitIds": ["eg.g209.montan", "eg.v.c02_gnose", "eg.v.c02_marcion"], "pool": "lesson", "lessonId": "eg.l209", "skill": "recognition", "answer": "les gnostiques = le salut par un savoir secret ; Marcion = deux dieux ; Montanus = une nouvelle prophétie"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l209.e14', 'eg', 'eg.l209', 'eg.g209.montan', array['eg.g209.montan']::text[], 'mcq', 'lesson', 'Pourquoi chercher le martyre contredit-il l''Évangile ?', array['Jésus conseille de fuir dans une autre ville']::text[], 'Le martyre est un témoignage qu''on accepte, pas un but qu''on poursuit.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi chercher le martyre contredit-il l''Évangile ?", "answer": "Jésus conseille de fuir dans une autre ville", "acceptedAnswers": ["Jésus conseille de fuir dans une autre ville"], "explanation": "Le martyre est un témoignage qu''on accepte, pas un but qu''on poursuit.", "options": ["Jésus conseille de fuir dans une autre ville", "Jésus interdit à ses disciples d''être arrêtés un jour", "Le martyre est réservé aux seuls évêques et prêtres"], "id": "eg.l209.e14", "promptLanguage": "fr", "unitIds": ["eg.g209.montan"], "pool": "lesson", "lessonId": "eg.l209", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l209.e15', 'eg', 'eg.l209', 'eg.g209.montan', array['eg.g209.montan','eg.g201.releve']::text[], 'mcq', 'lesson', 'Gnostiques, Marcion, Montan : que font-ils tous ?', array['Chacun prétend apporter plus que la foi des apôtres']::text[], 'L''Église répond : le dépôt de la foi est complet, il se garde, il ne se complète pas.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Gnostiques, Marcion, Montan : que font-ils tous ?", "answer": "Chacun prétend apporter plus que la foi des apôtres", "acceptedAnswers": ["Chacun prétend apporter plus que la foi des apôtres"], "explanation": "L''Église répond : le dépôt de la foi est complet, il se garde, il ne se complète pas.", "options": ["Chacun prétend apporter plus que la foi des apôtres", "Chacun refuse de prier avec les autres chrétiens", "Chacun veut devenir le chef de l''Empire romain"], "id": "eg.l209.e15", "promptLanguage": "fr", "unitIds": ["eg.g209.montan", "eg.g201.releve"], "pool": "lesson", "lessonId": "eg.l209", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
