insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l210.e11', 'eg', 'eg.l210', 'eg.g210.canon', array['eg.g210.canon']::text[], 'mcq', 'lesson', 'Vrai ou faux : Irénée défend cinq Évangiles.', array['Faux']::text[], 'Quatre, ni plus ni moins.', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Vrai ou faux : Irénée défend cinq Évangiles.", "answer": "Faux", "acceptedAnswers": ["Faux"], "explanation": "Quatre, ni plus ni moins.", "options": ["Vrai", "Faux"], "id": "eg.l210.e11", "promptLanguage": "fr", "unitIds": ["eg.g210.canon"], "pool": "lesson", "lessonId": "eg.l210", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l210.e12', 'eg', 'eg.l210', 'eg.g210.canon', array['eg.g210.canon','eg.v.c02_canon','eg.v.c02_regle_foi','eg.v.c02_muratori']::text[], 'match', 'lesson', 'Trois mots du canon.', '{}'::text[], 'Une liste, un résumé, un témoin.', 2, '{"type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Trois mots du canon.", "acceptedAnswers": [], "explanation": "Une liste, un résumé, un témoin.", "pairs": [{"left": "le canon", "right": "la liste des livres reconnus par l''Église"}, {"left": "la règle de foi", "right": "le résumé de la foi du baptême"}, {"left": "le Fragment de Muratori", "right": "une liste ancienne venue de Rome"}], "id": "eg.l210.e12", "promptLanguage": "fr", "unitIds": ["eg.g210.canon", "eg.v.c02_canon", "eg.v.c02_regle_foi", "eg.v.c02_muratori"], "pool": "lesson", "lessonId": "eg.l210", "skill": "recognition", "answer": "le canon = la liste des livres reconnus par l''Église ; la règle de foi = le résumé de la foi du baptême ; le Fragment de Muratori = une liste ancienne venue de Rome"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l210.e13', 'eg', 'eg.l210', 'eg.g210.canon', array['eg.g210.canon','eg.v.c02_marcion']::text[], 'reorder', 'lesson', 'Remets ces trois repères dans l''ordre.', array['Marcion Irénée Athanase']::text[], 'Marcion vers 140, Irénée vers 180, Athanase en 367.', 2, '{"type": "reorder", "difficulty": 2, "instruction": "Remets dans l''ordre.", "prompt": "Remets ces trois repères dans l''ordre.", "answer": "Marcion Irénée Athanase", "acceptedAnswers": ["Marcion Irénée Athanase"], "explanation": "Marcion vers 140, Irénée vers 180, Athanase en 367.", "tokens": ["Irénée", "Athanase", "Marcion"], "id": "eg.l210.e13", "promptLanguage": "fr", "unitIds": ["eg.g210.canon", "eg.v.c02_marcion"], "pool": "lesson", "lessonId": "eg.l210", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l210.e14', 'eg', 'eg.l210', 'eg.g210.canon', array['eg.g210.canon','eg.v.c02_marcion']::text[], 'mcq', 'lesson', 'Pourquoi Marcion a-t-il rendu le canon nécessaire ?', array['Sa liste a forcé l''Église à dire quels livres elle reçoit']::text[], 'Quand quelqu''un coupe la Bible, il faut dire ce qui en fait partie.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi Marcion a-t-il rendu le canon nécessaire ?", "answer": "Sa liste a forcé l''Église à dire quels livres elle reçoit", "acceptedAnswers": ["Sa liste a forcé l''Église à dire quels livres elle reçoit"], "explanation": "Quand quelqu''un coupe la Bible, il faut dire ce qui en fait partie.", "options": ["Sa liste a forcé l''Église à dire quels livres elle reçoit", "Il a prouvé que tous les Évangiles étaient des faux", "Il a interdit à tous les chrétiens de lire les Évangiles"], "id": "eg.l210.e14", "promptLanguage": "fr", "unitIds": ["eg.g210.canon", "eg.v.c02_marcion"], "pool": "lesson", "lessonId": "eg.l210", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l210.e15', 'eg', 'eg.l210', 'eg.g210.canon', array['eg.g210.canon','eg.v.c02_regle_foi','eg.g201.releve']::text[], 'mcq', 'lesson', 'Que résout la règle de foi que les Écritures seules ne résolvaient pas ?', array['Elle dit comment lire les versets sans les tordre']::text[], 'On lit la Bible dans la foi de l''Église, comme on range une mosaïque d''après le plan du roi.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que résout la règle de foi que les Écritures seules ne résolvaient pas ?", "answer": "Elle dit comment lire les versets sans les tordre", "acceptedAnswers": ["Elle dit comment lire les versets sans les tordre"], "explanation": "On lit la Bible dans la foi de l''Église, comme on range une mosaïque d''après le plan du roi.", "options": ["Elle dit comment lire les versets sans les tordre", "Elle remplace les Évangiles dans la liturgie", "Elle supprime le besoin d''avoir des évêques et des prêtres"], "id": "eg.l210.e15", "promptLanguage": "fr", "unitIds": ["eg.g210.canon", "eg.v.c02_regle_foi", "eg.g201.releve"], "pool": "lesson", "lessonId": "eg.l210", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
