insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l211.e02', 'eg', 'eg.l211', 'eg.g211.demetrios', array['eg.g211.demetrios']::text[], 'mcq', 'lesson', 'Qu''apporte Démétrios le lendemain, selon la tradition ?', array['une grappe de raisin hors saison']::text[], 'Le signe annoncé par l''ange : une grappe hors saison. D''où le nom de « vigneron ».', 1, '{"type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''apporte Démétrios le lendemain, selon la tradition ?", "answer": "une grappe de raisin hors saison", "acceptedAnswers": ["une grappe de raisin hors saison"], "explanation": "Le signe annoncé par l''ange : une grappe hors saison. D''où le nom de « vigneron ».", "options": ["un agneau blanc sorti de son troupeau", "une grappe de raisin hors saison", "une lettre de l''empereur de Rome"], "id": "eg.l211.e02", "promptLanguage": "fr", "unitIds": ["eg.g211.demetrios"], "step": 1, "pool": "lesson", "lessonId": "eg.l211", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
