insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l211.e14', 'eg', 'eg.l211', 'eg.g211.demetrios', array['eg.g211.demetrios']::text[], 'mcq', 'lesson', 'Pourquoi Alexandrie est-elle bien placée pour calculer la date de Pâques ?', array['C''est une ville d''astronomes et de savants']::text[], 'Les astronomes savent suivre la lune, dont dépend la date de Pâques.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi Alexandrie est-elle bien placée pour calculer la date de Pâques ?", "answer": "C''est une ville d''astronomes et de savants", "acceptedAnswers": ["C''est une ville d''astronomes et de savants"], "explanation": "Les astronomes savent suivre la lune, dont dépend la date de Pâques.", "options": ["C''est une ville d''astronomes et de savants", "C''est la capitale de tout l''Empire romain", "C''est la ville où Jésus est ressuscité"], "id": "eg.l211.e14", "promptLanguage": "fr", "unitIds": ["eg.g211.demetrios"], "pool": "lesson", "lessonId": "eg.l211", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l211.e15', 'eg', 'eg.l211', 'eg.g211.demetrios', array['eg.g211.demetrios','eg.v.c02_siege_alexandrie']::text[], 'mcq', 'lesson', 'Quel lien y a-t-il entre Démétrios et saint Marc ?', array['Il dirige l''Église de Marc et soutient son école']::text[], 'Démétrios est un maillon de la chaîne qui remonte à Marc, le premier évêque d''Alexandrie.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel lien y a-t-il entre Démétrios et saint Marc ?", "answer": "Il dirige l''Église de Marc et soutient son école", "acceptedAnswers": ["Il dirige l''Église de Marc et soutient son école"], "explanation": "Démétrios est un maillon de la chaîne qui remonte à Marc, le premier évêque d''Alexandrie.", "options": ["Il dirige l''Église de Marc et soutient son école", "Il est le propre fils de saint Marc l''évangéliste", "Il écrit un cinquième Évangile à la place de Marc"], "id": "eg.l211.e15", "promptLanguage": "fr", "unitIds": ["eg.g211.demetrios", "eg.v.c02_siege_alexandrie"], "pool": "lesson", "lessonId": "eg.l211", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
