insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l212.e10', 'eg', 'eg.l212', 'eg.g212.bilan', array['eg.g212.bilan','eg.v.c02_siege_rome','eg.v.c02_siege_alexandrie']::text[], 'match', 'lesson', 'Les quatre sièges : quel apôtre pour quelle ville ?', '{}'::text[], 'Chaque siège apostolique remonte à un apôtre.', 2, '{"type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Les quatre sièges : quel apôtre pour quelle ville ?", "acceptedAnswers": [], "explanation": "Chaque siège apostolique remonte à un apôtre.", "pairs": [{"left": "Rome", "right": "Pierre et Paul"}, {"left": "Alexandrie", "right": "Marc"}, {"left": "Antioche", "right": "Pierre"}, {"left": "Jérusalem", "right": "Jacques"}], "id": "eg.l212.e10", "promptLanguage": "fr", "unitIds": ["eg.g212.bilan", "eg.v.c02_siege_rome", "eg.v.c02_siege_alexandrie"], "pool": "lesson", "lessonId": "eg.l212", "skill": "recognition", "answer": "Rome = Pierre et Paul ; Alexandrie = Marc ; Antioche = Pierre ; Jérusalem = Jacques"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l212.e11', 'eg', 'eg.l212', 'eg.g212.bilan', array['eg.g212.bilan','eg.v.c02_clement','eg.v.c02_ignace','eg.v.c02_polycarpe','eg.v.c02_justin','eg.v.c02_irenee']::text[], 'match', 'lesson', 'Les Pères du siècle : qui a fait quoi ?', '{}'::text[], 'Trois Pères apostoliques, un apologiste et un défenseur contre les gnostiques.', 2, '{"type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Les Pères du siècle : qui a fait quoi ?", "acceptedAnswers": [], "explanation": "Trois Pères apostoliques, un apologiste et un défenseur contre les gnostiques.", "pairs": [{"left": "Clément", "right": "lettre aux Corinthiens"}, {"left": "Ignace", "right": "sept lettres en route vers Rome"}, {"left": "Polycarpe", "right": "disciple de Jean"}, {"left": "Justin", "right": "Apologies à l''empereur"}, {"left": "Irénée", "right": "Contre les hérésies"}], "id": "eg.l212.e11", "promptLanguage": "fr", "unitIds": ["eg.g212.bilan", "eg.v.c02_clement", "eg.v.c02_ignace", "eg.v.c02_polycarpe", "eg.v.c02_justin", "eg.v.c02_irenee"], "pool": "lesson", "lessonId": "eg.l212", "skill": "recognition", "answer": "Clément = lettre aux Corinthiens ; Ignace = sept lettres en route vers Rome ; Polycarpe = disciple de Jean ; Justin = Apologies à l''empereur ; Irénée = Contre les hérésies"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l212.e12', 'eg', 'eg.l212', 'eg.g212.bilan', array['eg.g212.bilan']::text[], 'reorder', 'lesson', 'Remets ces cinq repères du siècle dans l''ordre.', array['Ignace Marcion Montan Lyon Démétrios']::text[], 'Ignace 110, Marcion 140, Montan 170, Lyon 177, Démétrios 189.', 2, '{"type": "reorder", "difficulty": 2, "instruction": "Remets dans l''ordre.", "prompt": "Remets ces cinq repères du siècle dans l''ordre.", "answer": "Ignace Marcion Montan Lyon Démétrios", "acceptedAnswers": ["Ignace Marcion Montan Lyon Démétrios"], "explanation": "Ignace 110, Marcion 140, Montan 170, Lyon 177, Démétrios 189.", "tokens": ["Marcion", "Montan", "Lyon", "Démétrios", "Ignace"], "id": "eg.l212.e12", "promptLanguage": "fr", "unitIds": ["eg.g212.bilan"], "pool": "lesson", "lessonId": "eg.l212", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l212.e13', 'eg', 'eg.l212', 'eg.g212.bilan', array['eg.g212.bilan','eg.v.c02_marcion']::text[], 'mcq', 'lesson', 'Quelle hérésie rejette l''Ancien Testament et coupe la Bible ?', array['Marcionisme']::text[], 'Rappel de la leçon sur Marcion.', 2, '{"type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle hérésie rejette l''Ancien Testament et coupe la Bible ?", "answer": "Marcionisme", "acceptedAnswers": ["Marcionisme"], "explanation": "Rappel de la leçon sur Marcion.", "options": ["Montanisme", "Docétisme", "Marcionisme"], "id": "eg.l212.e13", "promptLanguage": "fr", "unitIds": ["eg.g212.bilan", "eg.v.c02_marcion"], "pool": "lesson", "lessonId": "eg.l212", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l212.e14', 'eg', 'eg.l212', 'eg.g212.bilan', array['eg.g212.bilan','eg.g201.releve']::text[], 'mcq', 'lesson', 'Pourquoi les Écritures seules ne suffisaient-elles pas contre les hérésies ?', array['Chacun pouvait citer un verset à sa façon']::text[], 'Il fallait des gardiens vivants : les évêques successeurs des apôtres, et la règle de foi.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi les Écritures seules ne suffisaient-elles pas contre les hérésies ?", "answer": "Chacun pouvait citer un verset à sa façon", "acceptedAnswers": ["Chacun pouvait citer un verset à sa façon"], "explanation": "Il fallait des gardiens vivants : les évêques successeurs des apôtres, et la règle de foi.", "options": ["Chacun pouvait citer un verset à sa façon", "Elles n''étaient pas encore écrites", "Elles étaient interdites par l''empereur"], "id": "eg.l212.e14", "promptLanguage": "fr", "unitIds": ["eg.g212.bilan", "eg.g201.releve"], "pool": "lesson", "lessonId": "eg.l212", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l212.e15', 'eg', 'eg.l212', 'eg.g212.bilan', array['eg.g212.bilan']::text[], 'mcq', 'lesson', 'Quelle réponse commune l''Église donne-t-elle aux quatre hérésies ?', array['S''appuyer sur les Écritures, la tradition et les évêques']::text[], 'Écritures fixées par le canon, tradition reçue, évêques successeurs : trois remparts.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle réponse commune l''Église donne-t-elle aux quatre hérésies ?", "answer": "S''appuyer sur les Écritures, la tradition et les évêques", "acceptedAnswers": ["S''appuyer sur les Écritures, la tradition et les évêques"], "explanation": "Écritures fixées par le canon, tradition reçue, évêques successeurs : trois remparts.", "options": ["Inventer une nouvelle prophétie au nom de l''Esprit", "S''appuyer sur les Écritures, la tradition et les évêques", "Garder la foi secrète, réservée à quelques initiés choisis"], "id": "eg.l212.e15", "promptLanguage": "fr", "unitIds": ["eg.g212.bilan"], "pool": "lesson", "lessonId": "eg.l212", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l212.e16', 'eg', 'eg.l212', 'eg.g212.bilan', array['eg.g212.bilan','eg.v.c02_apologiste']::text[], 'mcq', 'lesson', 'Pourquoi les apologistes écrivent-ils aux païens plutôt qu''aux chrétiens ?', array['Pour répondre à leurs accusations et défendre la foi']::text[], 'Ils parlent « à la place publique », là où les rumeurs naissent.', 3, '{"type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi les apologistes écrivent-ils aux païens plutôt qu''aux chrétiens ?", "answer": "Pour répondre à leurs accusations et défendre la foi", "acceptedAnswers": ["Pour répondre à leurs accusations et défendre la foi"], "explanation": "Ils parlent « à la place publique », là où les rumeurs naissent.", "options": ["Pour répondre à leurs accusations et défendre la foi", "Pour leur apprendre le baptême et la liturgie secrète", "Pour choisir de nouveaux évêques parmi les païens"], "id": "eg.l212.e16", "promptLanguage": "fr", "unitIds": ["eg.g212.bilan", "eg.v.c02_apologiste"], "pool": "lesson", "lessonId": "eg.l212", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l301.e01', 'eg', 'eg.l301', 'eg.g301.rumeurs', array['eg.g301.rumeurs','eg.v.c03_sacrifice_public']::text[], 'mcq', 'lesson', 'Quel geste prouve la loyauté d''un citoyen romain ?', array['un sacrifice public']::text[], 'Le sacrifice public est le test de loyauté de l''Empire.', 1, '{"id": "eg.l301.e01", "unitIds": ["eg.g301.rumeurs", "eg.v.c03_sacrifice_public"], "type": "mcq", "difficulty": 1, "prompt": "Quel geste prouve la loyauté d''un citoyen romain ?", "promptLanguage": "fr", "answer": "un sacrifice public", "acceptedAnswers": ["un sacrifice public"], "explanation": "Le sacrifice public est le test de loyauté de l''Empire.", "instruction": "Choisis la bonne réponse.", "step": 1, "options": ["un impôt spécial", "un sacrifice public", "un long pèlerinage à Rome"], "pool": "lesson", "lessonId": "eg.l301", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l301.e02', 'eg', 'eg.l301', 'eg.g301.rumeurs', array['eg.g301.rumeurs','eg.v.c03_mauvais_citoyens']::text[], 'mcq', 'lesson', 'Aux yeux des Romains, les chrétiens sont…', array['de mauvais citoyens']::text[], 'Ils refusent le geste de loyauté, donc on les croit déloyaux.', 1, '{"id": "eg.l301.e02", "unitIds": ["eg.g301.rumeurs", "eg.v.c03_mauvais_citoyens"], "type": "mcq", "difficulty": 1, "prompt": "Aux yeux des Romains, les chrétiens sont…", "promptLanguage": "fr", "answer": "de mauvais citoyens", "acceptedAnswers": ["de mauvais citoyens"], "explanation": "Ils refusent le geste de loyauté, donc on les croit déloyaux.", "instruction": "Choisis la bonne réponse.", "step": 2, "options": ["des soldats rebelles", "des marchands étrangers", "de mauvais citoyens"], "pool": "lesson", "lessonId": "eg.l301", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l301.e03', 'eg', 'eg.l301', 'eg.g301.rumeurs', array['eg.g301.rumeurs','eg.v.c03_mauvais_citoyens']::text[], 'mcq', 'lesson', 'Vrai ou faux : les chrétiens refusent de sacrifier pour se révolter contre Rome.', array['Faux']::text[], 'Ils refusent par fidélité à leur Dieu, pas par rébellion.', 1, '{"id": "eg.l301.e03", "unitIds": ["eg.g301.rumeurs", "eg.v.c03_mauvais_citoyens"], "type": "mcq", "difficulty": 1, "prompt": "Vrai ou faux : les chrétiens refusent de sacrifier pour se révolter contre Rome.", "promptLanguage": "fr", "answer": "Faux", "acceptedAnswers": ["Faux"], "explanation": "Ils refusent par fidélité à leur Dieu, pas par rébellion.", "instruction": "Choisis la bonne réponse.", "step": 2, "options": ["Vrai", "Faux"], "pool": "lesson", "lessonId": "eg.l301", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
