insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l301.e06', 'eg', 'eg.l301', 'eg.g301.rumeurs', array['eg.g301.rumeurs','eg.v.c03_anthropophagie']::text[], 'mcq', 'lesson', 'D''où viennent sans doute ces rumeurs ?', array['de paroles mal comprises']::text[], 'On avait entendu parler du corps et du sang du Christ sans comprendre.', 2, '{"id": "eg.l301.e06", "unitIds": ["eg.g301.rumeurs", "eg.v.c03_anthropophagie"], "type": "mcq", "difficulty": 2, "prompt": "D''où viennent sans doute ces rumeurs ?", "promptLanguage": "fr", "answer": "de paroles mal comprises", "acceptedAnswers": ["de paroles mal comprises"], "explanation": "On avait entendu parler du corps et du sang du Christ sans comprendre.", "instruction": "Choisis la bonne réponse.", "step": 4, "options": ["d''un procès célèbre", "d''un ordre de l''empereur", "de paroles mal comprises"], "pool": "lesson", "lessonId": "eg.l301", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l301.e07', 'eg', 'eg.l301', 'eg.g301.rumeurs', array['eg.g301.rumeurs','eg.v.c03_atheisme']::text[], 'fill_blank', 'lesson', 'Les chrétiens n''ont ni ___ ni temples.', array['statues']::text[], 'Sans statues ni temples, ils semblaient sans dieu.', 2, '{"id": "eg.l301.e07", "unitIds": ["eg.g301.rumeurs", "eg.v.c03_atheisme"], "type": "fill_blank", "difficulty": 2, "prompt": "Les chrétiens n''ont ni ___ ni temples.", "promptLanguage": "fr", "answer": "statues", "acceptedAnswers": ["statues"], "explanation": "Sans statues ni temples, ils semblaient sans dieu.", "instruction": "Complète la phrase.", "step": 5, "options": ["prêtres", "statues", "livres"], "pool": "lesson", "lessonId": "eg.l301", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l301.e08', 'eg', 'eg.l301', 'eg.g301.rumeurs', array['eg.g301.rumeurs']::text[], 'mcq', 'lesson', 'Comment un édit est-il appliqué dans une ville ?', array['tout dépend du gouverneur de la ville']::text[], 'D''où les vagues : un édit, mais des applications très différentes.', 2, '{"id": "eg.l301.e08", "unitIds": ["eg.g301.rumeurs"], "type": "mcq", "difficulty": 2, "prompt": "Comment un édit est-il appliqué dans une ville ?", "promptLanguage": "fr", "answer": "tout dépend du gouverneur de la ville", "acceptedAnswers": ["tout dépend du gouverneur de la ville"], "explanation": "D''où les vagues : un édit, mais des applications très différentes.", "instruction": "Choisis la bonne réponse.", "step": 6, "options": ["tout dépend du gouverneur de la ville", "toujours de la même façon", "tout dépend du nombre de chrétiens présents"], "pool": "lesson", "lessonId": "eg.l301", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l301.e09', 'eg', 'eg.l301', 'eg.g301.rumeurs', array['eg.g301.rumeurs','eg.v.c03_atheisme','eg.v.c03_anthropophagie','eg.v.c03_mauvais_citoyens']::text[], 'match', 'lesson', 'Qui reproche quoi aux chrétiens ?', '{}'::text[], 'Trois voix, trois reproches : l''incroyance, le crime imaginaire, la déloyauté.', 2, '{"id": "eg.l301.e09", "unitIds": ["eg.g301.rumeurs", "eg.v.c03_atheisme", "eg.v.c03_anthropophagie", "eg.v.c03_mauvais_citoyens"], "type": "match", "difficulty": 2, "prompt": "Qui reproche quoi aux chrétiens ?", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Trois voix, trois reproches : l''incroyance, le crime imaginaire, la déloyauté.", "instruction": "Associe.", "pairs": [{"left": "Les philosophes", "right": "Ils sont athées"}, {"left": "La foule", "right": "Ils mangent de la chair humaine"}, {"left": "Rome", "right": "Ils sont de mauvais citoyens"}], "pool": "lesson", "lessonId": "eg.l301", "skill": "recognition", "answer": "Les philosophes = Ils sont athées ; La foule = Ils mangent de la chair humaine ; Rome = Ils sont de mauvais citoyens"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l301.e10', 'eg', 'eg.l301', 'eg.g301.rumeurs', array['eg.g301.rumeurs','eg.v.c03_sacrifice_public','eg.v.c03_anthropophagie','eg.v.c03_mauvais_citoyens']::text[], 'match', 'lesson', 'Chaque mot de la leçon a son sens.', '{}'::text[], 'Quatre mots à garder en tête pour comprendre ce siècle.', 2, '{"id": "eg.l301.e10", "unitIds": ["eg.g301.rumeurs", "eg.v.c03_sacrifice_public", "eg.v.c03_anthropophagie", "eg.v.c03_mauvais_citoyens"], "type": "match", "difficulty": 2, "prompt": "Chaque mot de la leçon a son sens.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Quatre mots à garder en tête pour comprendre ce siècle.", "instruction": "Associe.", "pairs": [{"left": "le sacrifice public", "right": "un geste qui prouve la loyauté"}, {"left": "l''anthropophagie", "right": "manger de la chair humaine"}, {"left": "un cercle vicieux", "right": "plus on se méfie, plus on se cache"}, {"left": "les mauvais citoyens", "right": "ceux qui évitent les fêtes de la cité"}], "pool": "lesson", "lessonId": "eg.l301", "skill": "recognition", "answer": "le sacrifice public = un geste qui prouve la loyauté ; l''anthropophagie = manger de la chair humaine ; un cercle vicieux = plus on se méfie, plus on se cache ; les mauvais citoyens = ceux qui évitent les fêtes de la cité"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l301.e11', 'eg', 'eg.l301', 'eg.g301.rumeurs', array['eg.g301.rumeurs','eg.v.c03_sacrifice_public']::text[], 'reorder', 'lesson', 'Remets la chaîne qui mène à la colère de la foule.', array['refus secret rumeurs colère']::text[], 'On refuse le sacrifice, on se cache, on invente des rumeurs, et la colère monte.', 2, '{"id": "eg.l301.e11", "unitIds": ["eg.g301.rumeurs", "eg.v.c03_sacrifice_public"], "type": "reorder", "difficulty": 2, "prompt": "Remets la chaîne qui mène à la colère de la foule.", "promptLanguage": "fr", "answer": "refus secret rumeurs colère", "acceptedAnswers": ["refus secret rumeurs colère"], "explanation": "On refuse le sacrifice, on se cache, on invente des rumeurs, et la colère monte.", "instruction": "Remets dans l''ordre.", "tokens": ["colère", "refus", "secret", "rumeurs"], "pool": "lesson", "lessonId": "eg.l301", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l301.e12', 'eg', 'eg.l301', 'eg.g301.rumeurs', array['eg.g301.rumeurs','eg.v.c03_atheisme']::text[], 'free_answer', 'lesson', 'Quel mot les philosophes utilisent-ils pour dire « sans dieu » ?', array['athées','athée','les athées','athees']::text[], 'Athée = sans dieu. Pourtant les chrétiens croient en Dieu.', 2, '{"id": "eg.l301.e12", "unitIds": ["eg.g301.rumeurs", "eg.v.c03_atheisme"], "type": "free_answer", "difficulty": 2, "prompt": "Quel mot les philosophes utilisent-ils pour dire « sans dieu » ?", "promptLanguage": "fr", "answer": "athées", "acceptedAnswers": ["athées", "athée", "les athées", "athees"], "explanation": "Athée = sans dieu. Pourtant les chrétiens croient en Dieu.", "instruction": "Écris la réponse.", "hint": "Il commence par « a ».", "pool": "lesson", "lessonId": "eg.l301", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l301.e13', 'eg', 'eg.l301', 'eg.g301.rumeurs', array['eg.g301.rumeurs']::text[], 'mcq', 'lesson', 'Pourquoi le secret des chrétiens aggrave-t-il les choses ?', array['On imagine le pire derrière les portes fermées']::text[], 'Quand on ne sait pas, on invente. Le mystère fait naître la peur.', 3, '{"id": "eg.l301.e13", "unitIds": ["eg.g301.rumeurs"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi le secret des chrétiens aggrave-t-il les choses ?", "promptLanguage": "fr", "answer": "On imagine le pire derrière les portes fermées", "acceptedAnswers": ["On imagine le pire derrière les portes fermées"], "explanation": "Quand on ne sait pas, on invente. Le mystère fait naître la peur.", "instruction": "Choisis la bonne réponse.", "options": ["L''empereur leur ordonne de se cacher dans les maisons", "On imagine le pire derrière les portes fermées", "Les voisins veulent les imiter"], "pool": "lesson", "lessonId": "eg.l301", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l301.e14', 'eg', 'eg.l301', 'eg.g301.rumeurs', array['eg.g301.rumeurs','eg.v.c03_atheisme']::text[], 'mcq', 'lesson', 'Pourquoi dit-on que l''accusation d''athéisme est un paradoxe ?', array['Ils croient en Dieu, mais on dit qu''ils n''en ont aucun']::text[], 'Persécutés pour trop croire en Dieu, accusés de n''en avoir aucun.', 3, '{"id": "eg.l301.e14", "unitIds": ["eg.g301.rumeurs", "eg.v.c03_atheisme"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi dit-on que l''accusation d''athéisme est un paradoxe ?", "promptLanguage": "fr", "answer": "Ils croient en Dieu, mais on dit qu''ils n''en ont aucun", "acceptedAnswers": ["Ils croient en Dieu, mais on dit qu''ils n''en ont aucun"], "explanation": "Persécutés pour trop croire en Dieu, accusés de n''en avoir aucun.", "instruction": "Choisis la bonne réponse.", "options": ["Les philosophes sont eux-mêmes chrétiens", "Ils croient en Dieu, mais on dit qu''ils n''en ont aucun", "Ils adorent plusieurs dieux romains en cachette de tous"], "pool": "lesson", "lessonId": "eg.l301", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
