insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l302.e06', 'eg', 'eg.l302', 'eg.g302.edit_de_dece', array['eg.g302.edit_de_dece']::text[], 'mcq', 'lesson', 'Quel est le risque pour celui qui refuse ?', array['la mort']::text[], 'Refuser de sacrifier, c''est risquer sa vie.', 1, '{"id": "eg.l302.e06", "unitIds": ["eg.g302.edit_de_dece"], "type": "mcq", "difficulty": 1, "prompt": "Quel est le risque pour celui qui refuse ?", "promptLanguage": "fr", "answer": "la mort", "acceptedAnswers": ["la mort"], "explanation": "Refuser de sacrifier, c''est risquer sa vie.", "instruction": "Choisis la bonne réponse.", "step": 5, "options": ["un nouveau nom", "un cadeau", "la mort"], "pool": "lesson", "lessonId": "eg.l302", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
