insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l302.e08', 'eg', 'eg.l302', 'eg.g302.edit_de_dece', array['eg.g302.edit_de_dece','eg.v.c03_maximin','eg.v.c03_dece','eg.v.c03_edit_250']::text[], 'match', 'lesson', 'Empereur, numéro et date de la persécution.', '{}'::text[], 'Six, sept : les numéros se suivent comme les empereurs.', 2, '{"id": "eg.l302.e08", "unitIds": ["eg.g302.edit_de_dece", "eg.v.c03_maximin", "eg.v.c03_dece", "eg.v.c03_edit_250"], "type": "match", "difficulty": 2, "prompt": "Empereur, numéro et date de la persécution.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Six, sept : les numéros se suivent comme les empereurs.", "instruction": "Associe.", "pairs": [{"left": "Maximin", "right": "sixième persécution, vers 235"}, {"left": "Dèce", "right": "septième persécution, vers 249"}, {"left": "l''édit de 250", "right": "tout le monde doit sacrifier"}], "pool": "lesson", "lessonId": "eg.l302", "skill": "recognition", "answer": "Maximin = sixième persécution, vers 235 ; Dèce = septième persécution, vers 249 ; l''édit de 250 = tout le monde doit sacrifier"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l302.e09', 'eg', 'eg.l302', 'eg.g302.edit_de_dece', array['eg.g302.edit_de_dece','eg.v.c03_libellus']::text[], 'match', 'lesson', 'Trois façons de réagir à l''édit.', '{}'::text[], 'Aucun choix n''est facile : c''est ce qui rend l''épreuve si dure.', 2, '{"id": "eg.l302.e09", "unitIds": ["eg.g302.edit_de_dece", "eg.v.c03_libellus"], "type": "match", "difficulty": 2, "prompt": "Trois façons de réagir à l''édit.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Aucun choix n''est facile : c''est ce qui rend l''épreuve si dure.", "instruction": "Associe.", "pairs": [{"left": "Refuser", "right": "risquer la mort"}, {"left": "Sacrifier", "right": "recevoir le libellus"}, {"left": "Se procurer un faux libellus", "right": "ne pas sacrifier vraiment"}], "pool": "lesson", "lessonId": "eg.l302", "skill": "recognition", "answer": "Refuser = risquer la mort ; Sacrifier = recevoir le libellus ; Se procurer un faux libellus = ne pas sacrifier vraiment"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l302.e10', 'eg', 'eg.l302', 'eg.g302.edit_de_dece', array['eg.g302.edit_de_dece','eg.v.c03_maximin','eg.v.c03_dece','eg.v.c03_edit_250','eg.v.c03_libellus']::text[], 'reorder', 'lesson', 'Remets les événements dans l''ordre.', array['Maximin Dèce édit libellus']::text[], 'Maximin (235), Dèce (249), l''édit (250), puis le libellus pour ceux qui sacrifient.', 2, '{"id": "eg.l302.e10", "unitIds": ["eg.g302.edit_de_dece", "eg.v.c03_maximin", "eg.v.c03_dece", "eg.v.c03_edit_250", "eg.v.c03_libellus"], "type": "reorder", "difficulty": 2, "prompt": "Remets les événements dans l''ordre.", "promptLanguage": "fr", "answer": "Maximin Dèce édit libellus", "acceptedAnswers": ["Maximin Dèce édit libellus"], "explanation": "Maximin (235), Dèce (249), l''édit (250), puis le libellus pour ceux qui sacrifient.", "instruction": "Remets dans l''ordre.", "tokens": ["Dèce", "libellus", "Maximin", "édit"], "pool": "lesson", "lessonId": "eg.l302", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l302.e11', 'eg', 'eg.l302', 'eg.g302.edit_de_dece', array['eg.g302.edit_de_dece','eg.v.c03_libellus']::text[], 'free_answer', 'lesson', 'Comment s''appelle le certificat reçu après avoir sacrifié ?', array['libellus','le libellus']::text[], 'Libellus, un petit document : la preuve du sacrifice.', 2, '{"id": "eg.l302.e11", "unitIds": ["eg.g302.edit_de_dece", "eg.v.c03_libellus"], "type": "free_answer", "difficulty": 2, "prompt": "Comment s''appelle le certificat reçu après avoir sacrifié ?", "promptLanguage": "fr", "answer": "libellus", "acceptedAnswers": ["libellus", "le libellus"], "explanation": "Libellus, un petit document : la preuve du sacrifice.", "instruction": "Écris la réponse.", "pool": "lesson", "lessonId": "eg.l302", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
