insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l302.e13', 'eg', 'eg.l302', 'eg.g302.edit_de_dece', array['eg.g302.edit_de_dece']::text[], 'mcq', 'lesson', 'Pourquoi l''édit de Dèce met-il les chrétiens en danger ?', array['Ils refusent d''honorer les dieux de l''Empire']::text[], 'Le sacrifice était obligatoire pour tous, et eux seuls disent non par conviction.', 3, '{"id": "eg.l302.e13", "unitIds": ["eg.g302.edit_de_dece"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi l''édit de Dèce met-il les chrétiens en danger ?", "promptLanguage": "fr", "answer": "Ils refusent d''honorer les dieux de l''Empire", "acceptedAnswers": ["Ils refusent d''honorer les dieux de l''Empire"], "explanation": "Le sacrifice était obligatoire pour tous, et eux seuls disent non par conviction.", "instruction": "Choisis la bonne réponse.", "options": ["Ils refusent d''honorer les dieux de l''Empire", "Ils parlent une autre langue", "Ils ne payent pas leurs impôts à l''empereur romain"], "pool": "lesson", "lessonId": "eg.l302", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
