insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l303.e05', 'eg', 'eg.l303', 'eg.g303.tombes_et_novatien', array['eg.g303.tombes_et_novatien','eg.v.c03_penitence']::text[], 'mcq', 'lesson', 'À quelle condition l''Église reçoit-elle les tombés ?', array['après une pénitence sincère']::text[], 'Un vrai repentir, pas un simple mot.', 1, '{"id": "eg.l303.e05", "unitIds": ["eg.g303.tombes_et_novatien", "eg.v.c03_penitence"], "type": "mcq", "difficulty": 1, "prompt": "À quelle condition l''Église reçoit-elle les tombés ?", "promptLanguage": "fr", "answer": "après une pénitence sincère", "acceptedAnswers": ["après une pénitence sincère"], "explanation": "Un vrai repentir, pas un simple mot.", "instruction": "Choisis la bonne réponse.", "step": 4, "options": ["après une pénitence sincère", "après un nouveau sacrifice", "après dix longues années de silence"], "pool": "lesson", "lessonId": "eg.l303", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
