insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l303.e08', 'eg', 'eg.l303', 'eg.g303.tombes_et_novatien', array['eg.g303.tombes_et_novatien','eg.v.c03_penitence']::text[], 'mcq', 'lesson', 'Quelle est la réponse de l''Église aux tombés ?', array['la pénitence']::text[], 'Ni pardon facile, ni porte fermée.', 1, '{"id": "eg.l303.e08", "unitIds": ["eg.g303.tombes_et_novatien", "eg.v.c03_penitence"], "type": "mcq", "difficulty": 1, "prompt": "Quelle est la réponse de l''Église aux tombés ?", "promptLanguage": "fr", "answer": "la pénitence", "acceptedAnswers": ["la pénitence"], "explanation": "Ni pardon facile, ni porte fermée.", "instruction": "Choisis la bonne réponse.", "step": 6, "options": ["l''exil définitif", "la pénitence", "l''oubli"], "pool": "lesson", "lessonId": "eg.l303", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l303.e09', 'eg', 'eg.l303', 'eg.g303.tombes_et_novatien', array['eg.g303.tombes_et_novatien','eg.v.c03_novatien','eg.v.c03_tombes']::text[], 'match', 'lesson', 'Qui est qui dans la querelle ?', '{}'::text[], 'Corneille et Novatien se disputent le siège de Rome en 251.', 2, '{"id": "eg.l303.e09", "unitIds": ["eg.g303.tombes_et_novatien", "eg.v.c03_novatien", "eg.v.c03_tombes"], "type": "match", "difficulty": 2, "prompt": "Qui est qui dans la querelle ?", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Corneille et Novatien se disputent le siège de Rome en 251.", "instruction": "Associe.", "pairs": [{"left": "Novatien", "right": "veut une Église pure"}, {"left": "Corneille", "right": "évêque de Rome, rival de Novatien"}, {"left": "Cyprien", "right": "évêque de Carthage"}, {"left": "les tombés", "right": "ont sacrifié par peur"}], "pool": "lesson", "lessonId": "eg.l303", "skill": "recognition", "answer": "Novatien = veut une Église pure ; Corneille = évêque de Rome, rival de Novatien ; Cyprien = évêque de Carthage ; les tombés = ont sacrifié par peur"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l303.e10', 'eg', 'eg.l303', 'eg.g303.tombes_et_novatien', array['eg.g303.tombes_et_novatien','eg.v.c03_penitence','eg.v.c03_excommunication','eg.v.c03_libellus']::text[], 'match', 'lesson', 'Chaque mot a son sens.', '{}'::text[], 'Le libellus est le papier de la chute, la pénitence le chemin du retour.', 2, '{"id": "eg.l303.e10", "unitIds": ["eg.g303.tombes_et_novatien", "eg.v.c03_penitence", "eg.v.c03_excommunication", "eg.v.c03_libellus"], "type": "match", "difficulty": 2, "prompt": "Chaque mot a son sens.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Le libellus est le papier de la chute, la pénitence le chemin du retour.", "instruction": "Associe.", "pairs": [{"left": "la pénitence", "right": "chemin de repentir pour revenir"}, {"left": "l''excommunication", "right": "exclusion de la communion de l''Église"}, {"left": "le libellus", "right": "certificat de sacrifice"}], "pool": "lesson", "lessonId": "eg.l303", "skill": "recognition", "answer": "la pénitence = chemin de repentir pour revenir ; l''excommunication = exclusion de la communion de l''Église ; le libellus = certificat de sacrifice"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
