insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l305.e13', 'eg', 'eg.l305', 'eg.g305.diocletien_284', array['eg.g305.diocletien_284','eg.v.c03_calendrier_copte']::text[], 'mcq', 'lesson', 'Si Dioclétien n''avait pas persécuté l''Église, qu''est-ce qui aurait changé ?', array['284 ne serait pas l''an 1 des Coptes']::text[], 'Le calendrier copte est né du souvenir des martyrs de son règne.', 3, '{"id": "eg.l305.e13", "unitIds": ["eg.g305.diocletien_284", "eg.v.c03_calendrier_copte"], "type": "mcq", "difficulty": 3, "prompt": "Si Dioclétien n''avait pas persécuté l''Église, qu''est-ce qui aurait changé ?", "promptLanguage": "fr", "answer": "284 ne serait pas l''an 1 des Coptes", "acceptedAnswers": ["284 ne serait pas l''an 1 des Coptes"], "explanation": "Le calendrier copte est né du souvenir des martyrs de son règne.", "instruction": "Choisis la bonne réponse.", "options": ["284 ne serait pas l''an 1 des Coptes", "Le Nayrouz n''existerait plus du tout", "L''Église n''aurait aucun martyr à honorer"], "pool": "lesson", "lessonId": "eg.l305", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
