insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l306.e08', 'eg', 'eg.l306', 'eg.g306.desert_paul_antoine', array['eg.g306.desert_paul_antoine','eg.v.c03_paul_de_thebes','eg.v.c03_antoine','eg.v.c03_dece']::text[], 'match', 'lesson', 'Qui est qui au désert ?', '{}'::text[], 'Paul ouvre le chemin, Antoine le fait connaître.', 2, '{"id": "eg.l306.e08", "unitIds": ["eg.g306.desert_paul_antoine", "eg.v.c03_paul_de_thebes", "eg.v.c03_antoine", "eg.v.c03_dece"], "type": "match", "difficulty": 2, "prompt": "Qui est qui au désert ?", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Paul ouvre le chemin, Antoine le fait connaître.", "instruction": "Associe.", "pairs": [{"left": "Paul de Thèbes", "right": "le premier des ermites"}, {"left": "Antoine", "right": "le père des moines"}, {"left": "le corbeau", "right": "apporte le pain"}, {"left": "Dèce", "right": "l''empereur qui fait fuir Paul"}], "pool": "lesson", "lessonId": "eg.l306", "skill": "recognition", "answer": "Paul de Thèbes = le premier des ermites ; Antoine = le père des moines ; le corbeau = apporte le pain ; Dèce = l''empereur qui fait fuir Paul"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
