insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l308.e09', 'eg', 'eg.l308', 'eg.g308.deux_pieges_trinite', array['eg.g308.deux_pieges_trinite','eg.v.c03_paul_de_samosate','eg.v.c03_sabellius','eg.v.c03_sainte_trinite']::text[], 'match', 'lesson', 'Deux pièges, une foi.', '{}'::text[], 'L''Église évite les deux pièges : le Fils est vraiment Dieu, et les trois sont vraiment trois.', 2, '{"id": "eg.l308.e09", "unitIds": ["eg.g308.deux_pieges_trinite", "eg.v.c03_paul_de_samosate", "eg.v.c03_sabellius", "eg.v.c03_sainte_trinite"], "type": "match", "difficulty": 2, "prompt": "Deux pièges, une foi.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "L''Église évite les deux pièges : le Fils est vraiment Dieu, et les trois sont vraiment trois.", "instruction": "Associe.", "pairs": [{"left": "Paul de Samosate", "right": "le Christ n''est qu''un homme"}, {"left": "Sabellius", "right": "trois personnes confondues en un acteur"}, {"left": "la Sainte Trinité", "right": "trois personnes, une seule divinité"}], "pool": "lesson", "lessonId": "eg.l308", "skill": "recognition", "answer": "Paul de Samosate = le Christ n''est qu''un homme ; Sabellius = trois personnes confondues en un acteur ; la Sainte Trinité = trois personnes, une seule divinité"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
