insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l309.e05', 'eg', 'eg.l309', 'eg.g309.mani_manicheisme', array['eg.g309.mani_manicheisme','eg.v.c03_manicheisme']::text[], 'fill_blank', 'lesson', 'Le manichéisme est incompatible avec l''___.', array['Incarnation']::text[], 'Si le corps est mauvais, Dieu ne peut pas se faire homme.', 2, '{"id": "eg.l309.e05", "unitIds": ["eg.g309.mani_manicheisme", "eg.v.c03_manicheisme"], "type": "fill_blank", "difficulty": 2, "prompt": "Le manichéisme est incompatible avec l''___.", "promptLanguage": "fr", "answer": "Incarnation", "acceptedAnswers": ["Incarnation"], "explanation": "Si le corps est mauvais, Dieu ne peut pas se faire homme.", "instruction": "Complète la phrase.", "step": 4, "options": ["Intercession", "Incarnation", "Ascension"], "pool": "lesson", "lessonId": "eg.l309", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l309.e06', 'eg', 'eg.l309', 'eg.g309.mani_manicheisme', array['eg.g309.mani_manicheisme','eg.v.c03_augustin']::text[], 'mcq', 'lesson', 'Qui a été manichéen avant de se convertir ?', array['saint Augustin']::text[], 'Augustin, qui sera un grand Père de l''Église.', 1, '{"id": "eg.l309.e06", "unitIds": ["eg.g309.mani_manicheisme", "eg.v.c03_augustin"], "type": "mcq", "difficulty": 1, "prompt": "Qui a été manichéen avant de se convertir ?", "promptLanguage": "fr", "answer": "saint Augustin", "acceptedAnswers": ["saint Augustin"], "explanation": "Augustin, qui sera un grand Père de l''Église.", "instruction": "Choisis la bonne réponse.", "step": 5, "options": ["saint Antoine", "saint Augustin", "Origène d''Alexandrie"], "pool": "lesson", "lessonId": "eg.l309", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l309.e07', 'eg', 'eg.l309', 'eg.g309.mani_manicheisme', array['eg.g309.mani_manicheisme','eg.v.c03_manicheisme','eg.v.c03_mani']::text[], 'match', 'lesson', 'Deux principes, deux créations.', '{}'::text[], 'Esprit d''un côté, matière de l''autre : la logique du manichéisme.', 2, '{"id": "eg.l309.e07", "unitIds": ["eg.g309.mani_manicheisme", "eg.v.c03_manicheisme", "eg.v.c03_mani"], "type": "match", "difficulty": 2, "prompt": "Deux principes, deux créations.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Esprit d''un côté, matière de l''autre : la logique du manichéisme.", "instruction": "Associe.", "pairs": [{"left": "Un Dieu bon", "right": "les anges et les âmes"}, {"left": "Un démiurge mauvais", "right": "les corps et la matière"}, {"left": "Mani", "right": "fonde le manichéisme"}], "pool": "lesson", "lessonId": "eg.l309", "skill": "recognition", "answer": "Un Dieu bon = les anges et les âmes ; Un démiurge mauvais = les corps et la matière ; Mani = fonde le manichéisme"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l309.e08', 'eg', 'eg.l309', 'eg.g309.mani_manicheisme', array['eg.g309.mani_manicheisme','eg.v.c03_paul_de_samosate','eg.v.c03_sabellius','eg.v.c03_novatien']::text[], 'match', 'lesson', 'Quatre erreurs du siècle : qui défend quoi ?', '{}'::text[], 'Trois erreurs sur Dieu et le Christ, une sur le pardon.', 3, '{"id": "eg.l309.e08", "unitIds": ["eg.g309.mani_manicheisme", "eg.v.c03_paul_de_samosate", "eg.v.c03_sabellius", "eg.v.c03_novatien"], "type": "match", "difficulty": 3, "prompt": "Quatre erreurs du siècle : qui défend quoi ?", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Trois erreurs sur Dieu et le Christ, une sur le pardon.", "instruction": "Associe.", "pairs": [{"left": "Paul de Samosate", "right": "le Christ est un homme"}, {"left": "Sabellius", "right": "un seul Dieu, trois masques"}, {"left": "Mani", "right": "un Dieu bon et un démiurge mauvais"}, {"left": "Novatien", "right": "pas de pardon pour les tombés"}], "pool": "lesson", "lessonId": "eg.l309", "skill": "recognition", "answer": "Paul de Samosate = le Christ est un homme ; Sabellius = un seul Dieu, trois masques ; Mani = un Dieu bon et un démiurge mauvais ; Novatien = pas de pardon pour les tombés"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l309.e09', 'eg', 'eg.l309', 'eg.g309.mani_manicheisme', array['eg.g309.mani_manicheisme','eg.v.c03_manicheisme']::text[], 'reorder', 'lesson', 'Une phrase à retenir sur le manichéisme.', array['Le manichéisme est incompatible avec l''Incarnation']::text[], 'Si le corps est mauvais, Dieu ne peut pas s''y incarner.', 2, '{"id": "eg.l309.e09", "unitIds": ["eg.g309.mani_manicheisme", "eg.v.c03_manicheisme"], "type": "reorder", "difficulty": 2, "prompt": "Une phrase à retenir sur le manichéisme.", "promptLanguage": "fr", "answer": "Le manichéisme est incompatible avec l''Incarnation", "acceptedAnswers": ["Le manichéisme est incompatible avec l''Incarnation"], "explanation": "Si le corps est mauvais, Dieu ne peut pas s''y incarner.", "instruction": "Remets dans l''ordre.", "tokens": ["Le", "est", "l''Incarnation", "avec", "incompatible", "manichéisme"], "pool": "lesson", "lessonId": "eg.l309", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l309.e10', 'eg', 'eg.l309', 'eg.g309.mani_manicheisme', array['eg.g309.mani_manicheisme','eg.v.c03_augustin']::text[], 'free_answer', 'lesson', 'Quel grand saint a d''abord été manichéen ?', array['Augustin','saint Augustin']::text[], 'Saint Augustin, avant sa conversion.', 2, '{"id": "eg.l309.e10", "unitIds": ["eg.g309.mani_manicheisme", "eg.v.c03_augustin"], "type": "free_answer", "difficulty": 2, "prompt": "Quel grand saint a d''abord été manichéen ?", "promptLanguage": "fr", "answer": "Augustin", "acceptedAnswers": ["Augustin", "saint Augustin"], "explanation": "Saint Augustin, avant sa conversion.", "instruction": "Écris la réponse.", "pool": "lesson", "lessonId": "eg.l309", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l309.e11', 'eg', 'eg.l309', 'eg.g309.mani_manicheisme', array['eg.g309.mani_manicheisme','eg.v.c03_manicheisme']::text[], 'mcq', 'lesson', 'Pourquoi le manichéisme est-il incompatible avec l''Incarnation ?', array['Un corps mauvais ne peut pas être celui de Dieu']::text[], 'On ne peut pas dire que Dieu se fait homme si l''on pense que la chair est mauvaise.', 3, '{"id": "eg.l309.e11", "unitIds": ["eg.g309.mani_manicheisme", "eg.v.c03_manicheisme"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi le manichéisme est-il incompatible avec l''Incarnation ?", "promptLanguage": "fr", "answer": "Un corps mauvais ne peut pas être celui de Dieu", "acceptedAnswers": ["Un corps mauvais ne peut pas être celui de Dieu"], "explanation": "On ne peut pas dire que Dieu se fait homme si l''on pense que la chair est mauvaise.", "instruction": "Choisis la bonne réponse.", "options": ["Il refuse de croire à tous les prophètes de l''histoire", "Un corps mauvais ne peut pas être celui de Dieu", "Il interdit les religions voisines dans tout l''Empire"], "pool": "lesson", "lessonId": "eg.l309", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
