insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l310.e08', 'eg', 'eg.l310', 'eg.g310.sainte_tradition', array['eg.g310.sainte_tradition','eg.v.c03_apocryphes','eg.v.c02_canon']::text[], 'match', 'lesson', 'Les trois familles d''écrits.', '{}'::text[], 'Trois familles, trois statuts.', 2, '{"id": "eg.l310.e08", "unitIds": ["eg.g310.sainte_tradition", "eg.v.c03_apocryphes", "eg.v.c02_canon"], "type": "match", "difficulty": 2, "prompt": "Les trois familles d''écrits.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Trois familles, trois statuts.", "instruction": "Associe.", "pairs": [{"left": "les apocryphes", "right": "écartés du canon"}, {"left": "les écrits canoniques", "right": "font autorité"}, {"left": "les écrits honorables", "right": "utiles mais non inspirés"}], "pool": "lesson", "lessonId": "eg.l310", "skill": "recognition", "answer": "les apocryphes = écartés du canon ; les écrits canoniques = font autorité ; les écrits honorables = utiles mais non inspirés"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
