insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l401.e09', 'eg', 'eg.l401', 'eg.g401.grande_persecution', array['eg.g401.grande_persecution']::text[], 'mcq', 'lesson', 'Quel édit donnera la pleine liberté aux chrétiens ?', array['L''édit de Milan']::text[], 'Milan, en 313 : on passe de la tolérance à la liberté.', 1, '{"id": "eg.l401.e09", "unitIds": ["eg.g401.grande_persecution"], "type": "mcq", "difficulty": 1, "prompt": "Quel édit donnera la pleine liberté aux chrétiens ?", "promptLanguage": "fr", "answer": "L''édit de Milan", "acceptedAnswers": ["L''édit de Milan"], "explanation": "Milan, en 313 : on passe de la tolérance à la liberté.", "instruction": "Choisis la bonne réponse.", "step": 5, "options": ["Le concile de Nicée", "L''édit de Milan", "Le premier édit de Dioclétien"], "pool": "lesson", "lessonId": "eg.l401", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l401.e10', 'eg', 'eg.l401', 'eg.g401.grande_persecution', array['eg.g401.grande_persecution']::text[], 'reorder', 'lesson', 'Remets la grande persécution dans l''ordre.', array['Édits Galère Tolérance Milan']::text[], '303 les édits, 305 Galère, 311 la tolérance, 313 Milan : en dix ans, de la persécution à la liberté.', 2, '{"id": "eg.l401.e10", "unitIds": ["eg.g401.grande_persecution"], "type": "reorder", "difficulty": 2, "prompt": "Remets la grande persécution dans l''ordre.", "promptLanguage": "fr", "answer": "Édits Galère Tolérance Milan", "acceptedAnswers": ["Édits Galère Tolérance Milan"], "explanation": "303 les édits, 305 Galère, 311 la tolérance, 313 Milan : en dix ans, de la persécution à la liberté.", "instruction": "Remets dans l''ordre.", "tokens": ["Tolérance", "Galère", "Milan", "Édits"], "pool": "lesson", "lessonId": "eg.l401", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l401.e11', 'eg', 'eg.l401', 'eg.g401.grande_persecution', array['eg.g401.grande_persecution']::text[], 'match', 'lesson', 'Encore une fois : chacun son rôle dans cette histoire.', '{}'::text[], 'Deux empereurs, un pape et un soldat : les quatre noms à garder.', 2, '{"id": "eg.l401.e11", "unitIds": ["eg.g401.grande_persecution"], "type": "match", "difficulty": 2, "prompt": "Encore une fois : chacun son rôle dans cette histoire.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Deux empereurs, un pape et un soldat : les quatre noms à garder.", "instruction": "Associe.", "pairs": [{"left": "Dioclétien", "right": "publie les quatre édits"}, {"left": "Galère", "right": "signe l''édit de tolérance"}, {"left": "le pape Pierre", "right": "est le sceau des martyrs"}, {"left": "saint Georges", "right": "est martyrisé vers 303"}], "pool": "lesson", "lessonId": "eg.l401", "skill": "recognition", "answer": "Dioclétien = publie les quatre édits ; Galère = signe l''édit de tolérance ; le pape Pierre = est le sceau des martyrs ; saint Georges = est martyrisé vers 303"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l401.e12', 'eg', 'eg.l401', 'eg.g401.grande_persecution', array['eg.g401.grande_persecution']::text[], 'mcq', 'lesson', 'Vrai ou faux : l''édit de 311 donne aux chrétiens la pleine liberté.', array['Faux']::text[], 'Il tolère seulement. La pleine liberté vient en 313.', 2, '{"id": "eg.l401.e12", "unitIds": ["eg.g401.grande_persecution"], "type": "mcq", "difficulty": 2, "prompt": "Vrai ou faux : l''édit de 311 donne aux chrétiens la pleine liberté.", "promptLanguage": "fr", "answer": "Faux", "acceptedAnswers": ["Faux"], "explanation": "Il tolère seulement. La pleine liberté vient en 313.", "instruction": "Choisis la bonne réponse.", "options": ["Vrai", "Faux"], "pool": "lesson", "lessonId": "eg.l401", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l401.e13', 'eg', 'eg.l401', 'eg.g401.grande_persecution', array['eg.g401.grande_persecution']::text[], 'mcq', 'lesson', 'Pourquoi un empereur cruel comme Galère finit-il par tolérer les chrétiens ?', array['Il constate que sa violence a échoué']::text[], 'Trois ans de tortures n''ont pas détruit l''Église : la force a perdu.', 3, '{"id": "eg.l401.e13", "unitIds": ["eg.g401.grande_persecution"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi un empereur cruel comme Galère finit-il par tolérer les chrétiens ?", "promptLanguage": "fr", "answer": "Il constate que sa violence a échoué", "acceptedAnswers": ["Il constate que sa violence a échoué"], "explanation": "Trois ans de tortures n''ont pas détruit l''Église : la force a perdu.", "instruction": "Choisis la bonne réponse.", "options": ["Il est devenu chrétien en secret", "Il constate que sa violence a échoué", "Les évêques l''ont menacé de guerre"], "pool": "lesson", "lessonId": "eg.l401", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
