insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l402.e11', 'eg', 'eg.l402', 'eg.g402.constantin', array['eg.g402.constantin','eg.g401.grande_persecution']::text[], 'match', 'lesson', 'Chacun sa place dans l''histoire de la paix.', '{}'::text[], 'Trois hommes pour 312-313, et Galère pour 311.', 2, '{"id": "eg.l402.e11", "unitIds": ["eg.g402.constantin", "eg.g401.grande_persecution"], "type": "match", "difficulty": 2, "prompt": "Chacun sa place dans l''histoire de la paix.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Trois hommes pour 312-313, et Galère pour 311.", "instruction": "Associe.", "pairs": [{"left": "Constantin", "right": "voit une croix dans le ciel"}, {"left": "Maxence", "right": "se noie dans le Tibre"}, {"left": "Licinius", "right": "signe l''édit de Milan avec Constantin"}, {"left": "Galère", "right": "signe l''édit de tolérance de 311"}], "pool": "lesson", "lessonId": "eg.l402", "skill": "recognition", "answer": "Constantin = voit une croix dans le ciel ; Maxence = se noie dans le Tibre ; Licinius = signe l''édit de Milan avec Constantin ; Galère = signe l''édit de tolérance de 311"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l402.e12', 'eg', 'eg.l402', 'eg.g401.grande_persecution', array['eg.g401.grande_persecution','eg.v.c04_galere']::text[], 'mcq', 'lesson', 'Lequel de ces deux empereurs a signé l''édit de 311, avant celui de Milan ?', array['Galère']::text[], 'Galère, malade, avait seulement toléré les chrétiens.', 2, '{"id": "eg.l402.e12", "unitIds": ["eg.g401.grande_persecution", "eg.v.c04_galere"], "type": "mcq", "difficulty": 2, "prompt": "Lequel de ces deux empereurs a signé l''édit de 311, avant celui de Milan ?", "promptLanguage": "fr", "answer": "Galère", "acceptedAnswers": ["Galère"], "explanation": "Galère, malade, avait seulement toléré les chrétiens.", "instruction": "Choisis la bonne réponse.", "options": ["Licinius", "Constantin", "Galère"], "pool": "lesson", "lessonId": "eg.l402", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
