insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l403.e10', 'eg', 'eg.l403', 'eg.g403.empereur_et_eglise', array['eg.g403.empereur_et_eglise']::text[], 'match', 'lesson', 'Qui ou quoi ? Chaque nom a sa description.', '{}'::text[], 'Une reine, une ville, un pays et un titre.', 2, '{"id": "eg.l403.e10", "unitIds": ["eg.g403.empereur_et_eglise"], "type": "match", "difficulty": 2, "prompt": "Qui ou quoi ? Chaque nom a sa description.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Une reine, une ville, un pays et un titre.", "instruction": "Associe.", "pairs": [{"left": "Hélène", "right": "retrouve la Sainte Croix"}, {"left": "Constantinople", "right": "capitale de l''empire d''Orient"}, {"left": "l''Arménie", "right": "premier pays chrétien"}, {"left": "évêque du dehors", "right": "titre que Constantin se donne"}], "pool": "lesson", "lessonId": "eg.l403", "skill": "recognition", "answer": "Hélène = retrouve la Sainte Croix ; Constantinople = capitale de l''empire d''Orient ; l''Arménie = premier pays chrétien ; évêque du dehors = titre que Constantin se donne"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
