insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l404.e11', 'eg', 'eg.l404', 'eg.g404.arius', array['eg.g404.arius']::text[], 'match', 'lesson', 'Qui est qui dans cette querelle ?', '{}'::text[], 'Un prêtre, un pape, un protecteur et une doctrine.', 2, '{"id": "eg.l404.e11", "unitIds": ["eg.g404.arius"], "type": "match", "difficulty": 2, "prompt": "Qui est qui dans cette querelle ?", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Un prêtre, un pape, un protecteur et une doctrine.", "instruction": "Associe.", "pairs": [{"left": "Arius", "right": "le prêtre qui dit que le Fils est créé"}, {"left": "le pape Alexandre", "right": "le chef de l''Église qui résiste"}, {"left": "Eusèbe de Nicomédie", "right": "l''évêque puissant qui le protège"}, {"left": "l''arianisme", "right": "la doctrine qui naît de sa phrase"}], "pool": "lesson", "lessonId": "eg.l404", "skill": "recognition", "answer": "Arius = le prêtre qui dit que le Fils est créé ; le pape Alexandre = le chef de l''Église qui résiste ; Eusèbe de Nicomédie = l''évêque puissant qui le protège ; l''arianisme = la doctrine qui naît de sa phrase"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l404.e12', 'eg', 'eg.l404', 'eg.g402.constantin', array['eg.g402.constantin','eg.g404.arius']::text[], 'mcq', 'lesson', 'Quel empereur, ami de l''Église depuis 313, voudra mettre fin à la querelle ?', array['Constantin']::text[], 'Constantin, qui a fait la paix avec l''Église, veut maintenant la paix dans l''Église.', 2, '{"id": "eg.l404.e12", "unitIds": ["eg.g402.constantin", "eg.g404.arius"], "type": "mcq", "difficulty": 2, "prompt": "Quel empereur, ami de l''Église depuis 313, voudra mettre fin à la querelle ?", "promptLanguage": "fr", "answer": "Constantin", "acceptedAnswers": ["Constantin"], "explanation": "Constantin, qui a fait la paix avec l''Église, veut maintenant la paix dans l''Église.", "instruction": "Choisis la bonne réponse.", "options": ["Galère", "Maxence", "Constantin"], "pool": "lesson", "lessonId": "eg.l404", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l404.e13', 'eg', 'eg.l404', 'eg.g404.arius', array['eg.g404.arius','eg.v.c04_alexandre']::text[], 'fill_blank', 'lesson', 'Le pape ___ essaie d''abord de ramener Arius à la raison.', array['Alexandre']::text[], 'Alexandre tente la douceur avant le synode.', 2, '{"id": "eg.l404.e13", "unitIds": ["eg.g404.arius", "eg.v.c04_alexandre"], "type": "fill_blank", "difficulty": 2, "prompt": "Le pape ___ essaie d''abord de ramener Arius à la raison.", "promptLanguage": "fr", "answer": "Alexandre", "acceptedAnswers": ["Alexandre"], "explanation": "Alexandre tente la douceur avant le synode.", "instruction": "Complète la phrase.", "options": ["Constantin", "Pierre", "Alexandre"], "pool": "lesson", "lessonId": "eg.l404", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l404.e14', 'eg', 'eg.l404', 'eg.g404.arius', array['eg.g404.arius']::text[], 'mcq', 'lesson', 'Pourquoi les chansons rendent-elles Arius dangereux ?', array['Ses idées se retiennent et se répandent vite']::text[], 'Une idée chantée passe de bouche en bouche, même chez ceux qui n''ont rien lu.', 3, '{"id": "eg.l404.e14", "unitIds": ["eg.g404.arius"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi les chansons rendent-elles Arius dangereux ?", "promptLanguage": "fr", "answer": "Ses idées se retiennent et se répandent vite", "acceptedAnswers": ["Ses idées se retiennent et se répandent vite"], "explanation": "Une idée chantée passe de bouche en bouche, même chez ceux qui n''ont rien lu.", "instruction": "Choisis la bonne réponse.", "options": ["Elles sont interdites par l''empereur", "Ses idées se retiennent et se répandent vite", "Elles remplacent la messe"], "pool": "lesson", "lessonId": "eg.l404", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l404.e15', 'eg', 'eg.l404', 'eg.g404.arius', array['eg.g404.arius']::text[], 'mcq', 'lesson', 'Quelle phrase Arius n''aurait jamais dite ?', array['Le Fils est de même essence que le Père']::text[], 'C''est précisément ce qu''il refuse : pour lui, le Fils est créé.', 3, '{"id": "eg.l404.e15", "unitIds": ["eg.g404.arius"], "type": "mcq", "difficulty": 3, "prompt": "Quelle phrase Arius n''aurait jamais dite ?", "promptLanguage": "fr", "answer": "Le Fils est de même essence que le Père", "acceptedAnswers": ["Le Fils est de même essence que le Père"], "explanation": "C''est précisément ce qu''il refuse : pour lui, le Fils est créé.", "instruction": "Choisis la bonne réponse.", "options": ["Le Fils est de même essence que le Père", "Le Fils a été créé", "Il fut un temps où le Fils n''était pas"], "pool": "lesson", "lessonId": "eg.l404", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
