insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l405.e02', 'eg', 'eg.l405', 'eg.g405.divinite', array['eg.g405.divinite']::text[], 'mcq', 'lesson', 'Vrai ou faux : un homme qui se noie peut en sauver un autre qui se noie.', array['Faux']::text[], 'Il faut quelqu''un qui n''est pas pris dans le naufrage : Dieu.', 1, '{"id": "eg.l405.e02", "unitIds": ["eg.g405.divinite"], "type": "mcq", "difficulty": 1, "prompt": "Vrai ou faux : un homme qui se noie peut en sauver un autre qui se noie.", "promptLanguage": "fr", "answer": "Faux", "acceptedAnswers": ["Faux"], "explanation": "Il faut quelqu''un qui n''est pas pris dans le naufrage : Dieu.", "instruction": "Choisis la bonne réponse.", "step": 1, "options": ["Vrai", "Faux"], "pool": "lesson", "lessonId": "eg.l405", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l405.e03', 'eg', 'eg.l405', 'eg.g405.divinite', array['eg.g405.divinite']::text[], 'mcq', 'lesson', 'Que perdent leur sens si le Fils est une créature ?', array['l''incarnation, la croix et la résurrection']::text[], 'Tout ce que le Christ a fait pour nous reposerait sur une créature.', 1, '{"id": "eg.l405.e03", "unitIds": ["eg.g405.divinite"], "type": "mcq", "difficulty": 1, "prompt": "Que perdent leur sens si le Fils est une créature ?", "promptLanguage": "fr", "answer": "l''incarnation, la croix et la résurrection", "acceptedAnswers": ["l''incarnation, la croix et la résurrection"], "explanation": "Tout ce que le Christ a fait pour nous reposerait sur une créature.", "instruction": "Choisis la bonne réponse.", "step": 2, "options": ["les chants, les couleurs et les fêtes", "l''incarnation, la croix et la résurrection", "les voyages, les marchés et les ports"], "pool": "lesson", "lessonId": "eg.l405", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
