insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l405.e06', 'eg', 'eg.l405', 'eg.g405.divinite', array['eg.g405.divinite']::text[], 'fill_blank', 'lesson', 'Quand le Christ se dit moindre, c''est dans son ___.', array['humanité']::text[], 'Dans son humanité, il est inférieur au Père ; dans sa divinité, il lui est égal.', 1, '{"id": "eg.l405.e06", "unitIds": ["eg.g405.divinite"], "type": "fill_blank", "difficulty": 1, "prompt": "Quand le Christ se dit moindre, c''est dans son ___.", "promptLanguage": "fr", "answer": "humanité", "acceptedAnswers": ["humanité"], "explanation": "Dans son humanité, il est inférieur au Père ; dans sa divinité, il lui est égal.", "instruction": "Complète la phrase.", "step": 3, "options": ["royaume", "humanité", "silence"], "pool": "lesson", "lessonId": "eg.l405", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
