insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l409.e12', 'eg', 'eg.l409', 'eg.g409.athanase_exils', array['eg.g409.athanase_exils']::text[], 'match', 'lesson', 'Athanase en quatre éléments.', '{}'::text[], 'Des livres, un surnom et un destin.', 2, '{"id": "eg.l409.e12", "unitIds": ["eg.g409.athanase_exils"], "type": "match", "difficulty": 2, "prompt": "Athanase en quatre éléments.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Des livres, un surnom et un destin.", "instruction": "Associe.", "pairs": [{"left": "les 27 livres", "right": "la lettre de 367"}, {"left": "La Vie d''Antoine", "right": "le portrait du père des moines"}, {"left": "le défenseur de la foi", "right": "le surnom d''Athanase"}, {"left": "les exils", "right": "il se cache chez les moines"}], "pool": "lesson", "lessonId": "eg.l409", "skill": "recognition", "answer": "les 27 livres = la lettre de 367 ; La Vie d''Antoine = le portrait du père des moines ; le défenseur de la foi = le surnom d''Athanase ; les exils = il se cache chez les moines"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
