insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l501.e14', 'eg', 'eg.l501', 'eg.g501.cinq_sieges', array['eg.g501.cinq_sieges','eg.v.c04_athanase']::text[], 'mcq', 'lesson', 'Quel Alexandrin défend la foi à Nicée ?', array['Athanase']::text[], 'Athanase à Nicée, Cyrille à Éphèse : Alexandrie en tête.', 2, '{"id": "eg.l501.e14", "unitIds": ["eg.g501.cinq_sieges", "eg.v.c04_athanase"], "type": "mcq", "difficulty": 2, "prompt": "Quel Alexandrin défend la foi à Nicée ?", "promptLanguage": "fr", "answer": "Athanase", "acceptedAnswers": ["Athanase"], "explanation": "Athanase à Nicée, Cyrille à Éphèse : Alexandrie en tête.", "instruction": "Choisis la bonne réponse.", "options": ["Cyrille", "Athanase", "Dioscore"], "pool": "lesson", "lessonId": "eg.l501", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l501.e15', 'eg', 'eg.l501', 'eg.g501.cinq_sieges', array['eg.g501.cinq_sieges']::text[], 'mcq', 'lesson', 'Pourquoi Alexandrie refuse-t-elle que le rang d''un siège dépende de la capitale ?', array['Son siège remonte à un apôtre, pas à un empereur']::text[], 'Pour Alexandrie, la valeur d''un siège vient des apôtres, pas du pouvoir politique.', 3, '{"id": "eg.l501.e15", "unitIds": ["eg.g501.cinq_sieges"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi Alexandrie refuse-t-elle que le rang d''un siège dépende de la capitale ?", "promptLanguage": "fr", "answer": "Son siège remonte à un apôtre, pas à un empereur", "acceptedAnswers": ["Son siège remonte à un apôtre, pas à un empereur"], "explanation": "Pour Alexandrie, la valeur d''un siège vient des apôtres, pas du pouvoir politique.", "instruction": "Choisis la bonne réponse.", "options": ["Elle aurait voulu devenir elle-même la capitale de l''empire", "Elle préfère que Rome décide à sa place pour tout le monde", "Son siège remonte à un apôtre, pas à un empereur"], "pool": "lesson", "lessonId": "eg.l501", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l501.e16', 'eg', 'eg.l501', 'eg.g501.cinq_sieges', array['eg.g501.cinq_sieges']::text[], 'mcq', 'lesson', 'Pourquoi la crise qui vient n''est-elle pas qu''une dispute de théologie ?', array['Les rivalités entre sièges s''y mêlent']::text[], 'La jalousie autour du rang de Constantinople pèsera sur les décisions.', 3, '{"id": "eg.l501.e16", "unitIds": ["eg.g501.cinq_sieges"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi la crise qui vient n''est-elle pas qu''une dispute de théologie ?", "promptLanguage": "fr", "answer": "Les rivalités entre sièges s''y mêlent", "acceptedAnswers": ["Les rivalités entre sièges s''y mêlent"], "explanation": "La jalousie autour du rang de Constantinople pèsera sur les décisions.", "instruction": "Choisis la bonne réponse.", "options": ["Les rivalités entre sièges s''y mêlent", "Personne ne s''intéresse vraiment à la foi", "Les évêques ne savent pas lire le grec"], "pool": "lesson", "lessonId": "eg.l501", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l502.e01', 'eg', 'eg.l502', 'eg.g502.nestorius_chaire', array['eg.g502.nestorius_chaire','eg.v.c05_nestorius']::text[], 'mcq', 'lesson', 'En quelle année Nestorius devient-il patriarche de Constantinople ?', array['428']::text[], '428 : à retenir comme le point de départ de la crise.', 1, '{"id": "eg.l502.e01", "unitIds": ["eg.g502.nestorius_chaire", "eg.v.c05_nestorius"], "type": "mcq", "difficulty": 1, "prompt": "En quelle année Nestorius devient-il patriarche de Constantinople ?", "promptLanguage": "fr", "answer": "428", "acceptedAnswers": ["428"], "explanation": "428 : à retenir comme le point de départ de la crise.", "instruction": "Choisis la bonne réponse.", "step": 1, "options": ["33", "428", "1054"], "pool": "lesson", "lessonId": "eg.l502", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l502.e02', 'eg', 'eg.l502', 'eg.g502.nestorius_chaire', array['eg.g502.nestorius_chaire','eg.v.c05_nestorius']::text[], 'mcq', 'lesson', 'Dans quelle ville Nestorius a-t-il été formé ?', array['Antioche']::text[], 'Il vient de l''école d''Antioche, nous y reviendrons.', 1, '{"id": "eg.l502.e02", "unitIds": ["eg.g502.nestorius_chaire", "eg.v.c05_nestorius"], "type": "mcq", "difficulty": 1, "prompt": "Dans quelle ville Nestorius a-t-il été formé ?", "promptLanguage": "fr", "answer": "Antioche", "acceptedAnswers": ["Antioche"], "explanation": "Il vient de l''école d''Antioche, nous y reviendrons.", "instruction": "Choisis la bonne réponse.", "step": 1, "options": ["Rome", "Jérusalem", "Antioche"], "pool": "lesson", "lessonId": "eg.l502", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l502.e03', 'eg', 'eg.l502', 'eg.g502.nestorius_chaire', array['eg.g502.nestorius_chaire','eg.v.c05_theotokos']::text[], 'mcq', 'lesson', 'Que veut dire Théotokos ?', array['celle qui enfante Dieu']::text[], 'Théo = Dieu, tokos = enfanter.', 1, '{"id": "eg.l502.e03", "unitIds": ["eg.g502.nestorius_chaire", "eg.v.c05_theotokos"], "type": "mcq", "difficulty": 1, "prompt": "Que veut dire Théotokos ?", "promptLanguage": "fr", "answer": "celle qui enfante Dieu", "acceptedAnswers": ["celle qui enfante Dieu"], "explanation": "Théo = Dieu, tokos = enfanter.", "instruction": "Choisis la bonne réponse.", "step": 2, "options": ["celle qui enfante Dieu", "celle qui prie pour nous", "celle qui garde le Temple"], "pool": "lesson", "lessonId": "eg.l502", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l502.e04', 'eg', 'eg.l502', 'eg.g502.nestorius_chaire', array['eg.g502.nestorius_chaire','eg.v.c05_nestorius','eg.v.c05_theotokos']::text[], 'mcq', 'lesson', 'Face au titre Théotokos, Nestorius...', array['refuse ce titre']::text[], 'C''est son refus, du haut de la chaire, qui lance la crise.', 1, '{"id": "eg.l502.e04", "unitIds": ["eg.g502.nestorius_chaire", "eg.v.c05_nestorius", "eg.v.c05_theotokos"], "type": "mcq", "difficulty": 1, "prompt": "Face au titre Théotokos, Nestorius...", "promptLanguage": "fr", "answer": "refuse ce titre", "acceptedAnswers": ["refuse ce titre"], "explanation": "C''est son refus, du haut de la chaire, qui lance la crise.", "instruction": "Choisis la bonne réponse.", "step": 2, "options": ["approuve ce titre", "refuse ce titre", "traduit ce titre"], "pool": "lesson", "lessonId": "eg.l502", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l502.e05', 'eg', 'eg.l502', 'eg.g502.nestorius_chaire', array['eg.g502.nestorius_chaire','eg.v.c05_nestorius','eg.v.c05_theotokos','eg.v.c05_christotokos']::text[], 'mcq', 'lesson', 'Quel titre Nestorius propose-t-il à la place ?', array['Christotokos']::text[], 'Christo = Christ. Mère du Christ, non mère de Dieu.', 1, '{"id": "eg.l502.e05", "unitIds": ["eg.g502.nestorius_chaire", "eg.v.c05_nestorius", "eg.v.c05_theotokos", "eg.v.c05_christotokos"], "type": "mcq", "difficulty": 1, "prompt": "Quel titre Nestorius propose-t-il à la place ?", "promptLanguage": "fr", "answer": "Christotokos", "acceptedAnswers": ["Christotokos"], "explanation": "Christo = Christ. Mère du Christ, non mère de Dieu.", "instruction": "Choisis la bonne réponse.", "step": 3, "options": ["Théotokos", "Kyrios", "Christotokos"], "pool": "lesson", "lessonId": "eg.l502", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l502.e06', 'eg', 'eg.l502', 'eg.g502.nestorius_chaire', array['eg.g502.nestorius_chaire','eg.v.c05_nestorius']::text[], 'mcq', 'lesson', 'Quel malentendu Nestorius veut-il éviter ?', array['Dieu aurait commencé d''exister']::text[], 'Sa crainte est de faire croire que Dieu a une naissance comme nous.', 2, '{"id": "eg.l502.e06", "unitIds": ["eg.g502.nestorius_chaire", "eg.v.c05_nestorius"], "type": "mcq", "difficulty": 2, "prompt": "Quel malentendu Nestorius veut-il éviter ?", "promptLanguage": "fr", "answer": "Dieu aurait commencé d''exister", "acceptedAnswers": ["Dieu aurait commencé d''exister"], "explanation": "Sa crainte est de faire croire que Dieu a une naissance comme nous.", "instruction": "Choisis la bonne réponse.", "step": 3, "options": ["Dieu aurait commencé d''exister", "Marie serait adorée comme Dieu", "Jésus n''aurait pas eu de corps"], "pool": "lesson", "lessonId": "eg.l502", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
