insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l503.e12', 'eg', 'eg.l503', 'eg.g503.protege_christ', array['eg.g503.protege_christ','eg.v.c05_le_verbe','eg.v.c05_incarnation','eg.v.c05_nestorianisme']::text[], 'match', 'lesson', 'Quatre mots, quatre sens.', '{}'::text[], 'Chaque mot répond à une étape du raisonnement.', 2, '{"id": "eg.l503.e12", "unitIds": ["eg.g503.protege_christ", "eg.v.c05_le_verbe", "eg.v.c05_incarnation", "eg.v.c05_nestorianisme"], "type": "match", "difficulty": 2, "prompt": "Quatre mots, quatre sens.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Chaque mot répond à une étape du raisonnement.", "instruction": "Associe.", "pairs": [{"left": "le Verbe", "right": "le Fils de Dieu éternel"}, {"left": "l''incarnation", "right": "le Verbe devient vraiment homme"}, {"left": "Théotokos", "right": "celle qui enfante Dieu"}, {"left": "le nestorianisme", "right": "sépare le Verbe et l''homme Jésus"}], "pool": "lesson", "lessonId": "eg.l503", "skill": "recognition", "answer": "le Verbe = le Fils de Dieu éternel ; l''incarnation = le Verbe devient vraiment homme ; Théotokos = celle qui enfante Dieu ; le nestorianisme = sépare le Verbe et l''homme Jésus"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
