insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l504.e11', 'eg', 'eg.l504', 'eg.g504.nature_personne', array['eg.g504.nature_personne','eg.v.c05_personne']::text[], 'mcq', 'lesson', 'Sur quel point Cyrille et Léon seront-ils d''accord ?', array['le Christ est une seule personne']::text[], 'Ils divergeront sur les mots pour la nature, mais pas sur l''unité de la personne.', 2, '{"id": "eg.l504.e11", "unitIds": ["eg.g504.nature_personne", "eg.v.c05_personne"], "type": "mcq", "difficulty": 2, "prompt": "Sur quel point Cyrille et Léon seront-ils d''accord ?", "promptLanguage": "fr", "answer": "le Christ est une seule personne", "acceptedAnswers": ["le Christ est une seule personne"], "explanation": "Ils divergeront sur les mots pour la nature, mais pas sur l''unité de la personne.", "instruction": "Choisis la bonne réponse.", "step": 6, "options": ["Marie n''est pas vraiment Théotokos pour eux", "Éphèse fut un échec pour tout le monde", "le Christ est une seule personne"], "pool": "lesson", "lessonId": "eg.l504", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l504.e12', 'eg', 'eg.l504', 'eg.g504.nature_personne', array['eg.g504.nature_personne','eg.v.c05_nature','eg.v.c05_personne']::text[], 'match', 'lesson', 'Nature ou personne ? Associe chaque mot à sa question.', '{}'::text[], 'Nature = quoi ? Personne = qui ?', 2, '{"id": "eg.l504.e12", "unitIds": ["eg.g504.nature_personne", "eg.v.c05_nature", "eg.v.c05_personne"], "type": "match", "difficulty": 2, "prompt": "Nature ou personne ? Associe chaque mot à sa question.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Nature = quoi ? Personne = qui ?", "instruction": "Associe.", "pairs": [{"left": "la nature", "right": "ce qu''on est"}, {"left": "la personne", "right": "qui on est"}, {"left": "Toi, qui dis « je »", "right": "une personne"}, {"left": "Humain", "right": "une nature"}], "pool": "lesson", "lessonId": "eg.l504", "skill": "recognition", "answer": "la nature = ce qu''on est ; la personne = qui on est ; Toi, qui dis « je » = une personne ; Humain = une nature"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
