insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l505.e11', 'eg', 'eg.l505', 'eg.g505.cyrille', array['eg.g505.cyrille']::text[], 'mcq', 'lesson', 'Quel évêque de Rome soutient Cyrille ?', array['Célestin Ier']::text[], 'Rome et Alexandrie condamnent ensemble Nestorius en 430.', 1, '{"id": "eg.l505.e11", "unitIds": ["eg.g505.cyrille"], "type": "mcq", "difficulty": 1, "prompt": "Quel évêque de Rome soutient Cyrille ?", "promptLanguage": "fr", "answer": "Célestin Ier", "acceptedAnswers": ["Célestin Ier"], "explanation": "Rome et Alexandrie condamnent ensemble Nestorius en 430.", "instruction": "Choisis la bonne réponse.", "step": 6, "options": ["Célestin Ier", "Léon Ier", "Athanase"], "pool": "lesson", "lessonId": "eg.l505", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l505.e12', 'eg', 'eg.l505', 'eg.g505.cyrille', array['eg.g505.cyrille']::text[], 'match', 'lesson', 'Les quatre acteurs de 430 : qui est qui ?', '{}'::text[], 'Alexandrie et Rome d''un côté, Nestorius de l''autre, l''empereur au-dessus.', 2, '{"id": "eg.l505.e12", "unitIds": ["eg.g505.cyrille"], "type": "match", "difficulty": 2, "prompt": "Les quatre acteurs de 430 : qui est qui ?", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Alexandrie et Rome d''un côté, Nestorius de l''autre, l''empereur au-dessus.", "instruction": "Associe.", "pairs": [{"left": "Cyrille", "right": "24e pape d''Alexandrie"}, {"left": "Nestorius", "right": "patriarche de Constantinople"}, {"left": "Célestin Ier", "right": "évêque de Rome"}, {"left": "Théodose II", "right": "l''empereur qui convoque le concile"}], "pool": "lesson", "lessonId": "eg.l505", "skill": "recognition", "answer": "Cyrille = 24e pape d''Alexandrie ; Nestorius = patriarche de Constantinople ; Célestin Ier = évêque de Rome ; Théodose II = l''empereur qui convoque le concile"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l505.e13', 'eg', 'eg.l505', 'eg.g505.cyrille', array['eg.g505.cyrille']::text[], 'reorder', 'lesson', 'Remets les gestes de Cyrille dans l''ordre.', array['Moines Nestorius Anathèmes Concile']::text[], 'Il écrit aux moines, puis à Nestorius, joint les anathèmes, et le concile est convoqué.', 2, '{"id": "eg.l505.e13", "unitIds": ["eg.g505.cyrille"], "type": "reorder", "difficulty": 2, "prompt": "Remets les gestes de Cyrille dans l''ordre.", "promptLanguage": "fr", "answer": "Moines Nestorius Anathèmes Concile", "acceptedAnswers": ["Moines Nestorius Anathèmes Concile"], "explanation": "Il écrit aux moines, puis à Nestorius, joint les anathèmes, et le concile est convoqué.", "instruction": "Remets dans l''ordre.", "tokens": ["Nestorius", "Anathèmes", "Concile", "Moines"], "pool": "lesson", "lessonId": "eg.l505", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
