insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l506.e10', 'eg', 'eg.l506', 'eg.g506.ephese_431', array['eg.g506.ephese_431','eg.v.c05_ephese']::text[], 'reorder', 'lesson', 'Remets la journée d''Éphèse dans l''ordre.', array['Convocation Ouverture Condamnation Rivalité']::text[], 'L''empereur convoque, Cyrille ouvre, Nestorius est condamné, puis le concile rival se forme.', 2, '{"id": "eg.l506.e10", "unitIds": ["eg.g506.ephese_431", "eg.v.c05_ephese"], "type": "reorder", "difficulty": 2, "prompt": "Remets la journée d''Éphèse dans l''ordre.", "promptLanguage": "fr", "answer": "Convocation Ouverture Condamnation Rivalité", "acceptedAnswers": ["Convocation Ouverture Condamnation Rivalité"], "explanation": "L''empereur convoque, Cyrille ouvre, Nestorius est condamné, puis le concile rival se forme.", "instruction": "Remets dans l''ordre.", "tokens": ["Ouverture", "Condamnation", "Rivalité", "Convocation"], "pool": "lesson", "lessonId": "eg.l506", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l506.e11', 'eg', 'eg.l506', 'eg.g506.ephese_431', array['eg.g506.ephese_431','eg.v.c05_ephese','eg.v.c05_jean_d_antioche']::text[], 'match', 'lesson', 'Éphèse 431 : qui est qui ?', '{}'::text[], 'Quatre rôles pour une journée tendue.', 2, '{"id": "eg.l506.e11", "unitIds": ["eg.g506.ephese_431", "eg.v.c05_ephese", "eg.v.c05_jean_d_antioche"], "type": "match", "difficulty": 2, "prompt": "Éphèse 431 : qui est qui ?", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Quatre rôles pour une journée tendue.", "instruction": "Associe.", "pairs": [{"left": "Théodose II", "right": "convoque le concile"}, {"left": "Cyrille", "right": "préside"}, {"left": "Nestorius", "right": "refuse de comparaître"}, {"left": "Jean d''Antioche", "right": "arrive en retard"}], "pool": "lesson", "lessonId": "eg.l506", "skill": "recognition", "answer": "Théodose II = convoque le concile ; Cyrille = préside ; Nestorius = refuse de comparaître ; Jean d''Antioche = arrive en retard"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
