insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l507.e09', 'eg', 'eg.l507', 'eg.g507.decisions_ephese', array['eg.g507.decisions_ephese']::text[], 'match', 'lesson', 'Éphèse en quatre décisions.', '{}'::text[], 'Quatre décisions, un seul concile.', 2, '{"id": "eg.l507.e09", "unitIds": ["eg.g507.decisions_ephese"], "type": "match", "difficulty": 2, "prompt": "Éphèse en quatre décisions.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Quatre décisions, un seul concile.", "instruction": "Associe.", "pairs": [{"left": "Nestorius", "right": "déposé"}, {"left": "Marie", "right": "Théotokos"}, {"left": "le credo de Nicée", "right": "confirmé"}, {"left": "Pélage", "right": "condamné aussi"}], "pool": "lesson", "lessonId": "eg.l507", "skill": "recognition", "answer": "Nestorius = déposé ; Marie = Théotokos ; le credo de Nicée = confirmé ; Pélage = condamné aussi"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l507.e10', 'eg', 'eg.l507', 'eg.g507.decisions_ephese', array['eg.g507.decisions_ephese']::text[], 'mcq', 'lesson', 'Nestorius et Pélage sont condamnés. Qui nie la nécessité de la grâce ?', array['Pélage']::text[], 'Pélage pense que l''homme se sauve seul. Nestorius est condamné pour une autre raison.', 2, '{"id": "eg.l507.e10", "unitIds": ["eg.g507.decisions_ephese"], "type": "mcq", "difficulty": 2, "prompt": "Nestorius et Pélage sont condamnés. Qui nie la nécessité de la grâce ?", "promptLanguage": "fr", "answer": "Pélage", "acceptedAnswers": ["Pélage"], "explanation": "Pélage pense que l''homme se sauve seul. Nestorius est condamné pour une autre raison.", "instruction": "Choisis la bonne réponse.", "options": ["Nestorius", "Jean d''Antioche", "Pélage"], "pool": "lesson", "lessonId": "eg.l507", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
