insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l509.e11', 'eg', 'eg.l509', 'eg.g509.eutyches', array['eg.g509.eutyches','eg.v.c05_eutyches','eg.v.c05_monophysisme']::text[], 'match', 'lesson', 'Deux erreurs opposées : à chacune son image.', '{}'::text[], 'Nestorius coupe en deux, Eutychès fait disparaître l''humanité.', 2, '{"id": "eg.l509.e11", "unitIds": ["eg.g509.eutyches", "eg.v.c05_eutyches", "eg.v.c05_monophysisme"], "type": "match", "difficulty": 2, "prompt": "Deux erreurs opposées : à chacune son image.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Nestorius coupe en deux, Eutychès fait disparaître l''humanité.", "instruction": "Associe.", "pairs": [{"left": "Nestorius", "right": "il sépare"}, {"left": "Eutychès", "right": "il mélange"}, {"left": "une goutte de miel", "right": "l''humanité est absorbée"}, {"left": "le monophysisme", "right": "une seule nature, la divine"}], "pool": "lesson", "lessonId": "eg.l509", "skill": "recognition", "answer": "Nestorius = il sépare ; Eutychès = il mélange ; une goutte de miel = l''humanité est absorbée ; le monophysisme = une seule nature, la divine"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
