insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l509.e13', 'eg', 'eg.l509', 'eg.g509.eutyches', array['eg.g509.eutyches','eg.v.c05_eutyches']::text[], 'mcq', 'lesson', 'Pourquoi Eutychès et Cyrille n''ont-ils pas la même foi, malgré des mots semblables ?', array['Chez Cyrille l''humanité reste entière ; chez Eutychès elle disparaît']::text[], 'Les mêmes mots peuvent cacher deux sens opposés : c''est ce qui rend la dispute subtile.', 3, '{"id": "eg.l509.e13", "unitIds": ["eg.g509.eutyches", "eg.v.c05_eutyches"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi Eutychès et Cyrille n''ont-ils pas la même foi, malgré des mots semblables ?", "promptLanguage": "fr", "answer": "Chez Cyrille l''humanité reste entière ; chez Eutychès elle disparaît", "acceptedAnswers": ["Chez Cyrille l''humanité reste entière ; chez Eutychès elle disparaît"], "explanation": "Les mêmes mots peuvent cacher deux sens opposés : c''est ce qui rend la dispute subtile.", "instruction": "Choisis la bonne réponse.", "options": ["Cyrille écrit en grec, tandis qu''Eutychès écrit en latin à Rome", "Chez Cyrille l''humanité reste entière ; chez Eutychès elle disparaît", "Eutychès n''a jamais entendu parler de Cyrille de sa vie ni de ses lettres"], "pool": "lesson", "lessonId": "eg.l509", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
