insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l510.e04', 'eg', 'eg.l510', 'eg.g510.fer_feu', array['eg.g510.fer_feu']::text[], 'mcq', 'lesson', 'Uni au feu, le fer...', array['ne cesse pas d''être du fer']::text[], 'L''humanité du Christ reste vraiment humaine.', 1, '{"id": "eg.l510.e04", "unitIds": ["eg.g510.fer_feu"], "type": "mcq", "difficulty": 1, "prompt": "Uni au feu, le fer...", "promptLanguage": "fr", "answer": "ne cesse pas d''être du fer", "acceptedAnswers": ["ne cesse pas d''être du fer"], "explanation": "L''humanité du Christ reste vraiment humaine.", "instruction": "Choisis la bonne réponse.", "step": 2, "options": ["disparaît dans le feu", "devient du feu pur", "ne cesse pas d''être du fer"], "pool": "lesson", "lessonId": "eg.l510", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l510.e05', 'eg', 'eg.l510', 'eg.g510.fer_feu', array['eg.g510.fer_feu']::text[], 'mcq', 'lesson', 'Que devient la goutte de miel dans la mer ?', array['elle est absorbée']::text[], 'Elle n''existe plus : c''est l''erreur d''Eutychès.', 1, '{"id": "eg.l510.e05", "unitIds": ["eg.g510.fer_feu"], "type": "mcq", "difficulty": 1, "prompt": "Que devient la goutte de miel dans la mer ?", "promptLanguage": "fr", "answer": "elle est absorbée", "acceptedAnswers": ["elle est absorbée"], "explanation": "Elle n''existe plus : c''est l''erreur d''Eutychès.", "instruction": "Choisis la bonne réponse.", "step": 3, "options": ["elle est absorbée", "elle brille comme le feu", "elle reste intacte"], "pool": "lesson", "lessonId": "eg.l510", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l510.e06', 'eg', 'eg.l510', 'eg.g510.fer_feu', array['eg.g510.fer_feu']::text[], 'mcq', 'lesson', 'Quelle image garde l''humanité du Christ intacte ?', array['le fer chauffé au rouge']::text[], 'Le fer reste du fer.', 2, '{"id": "eg.l510.e06", "unitIds": ["eg.g510.fer_feu"], "type": "mcq", "difficulty": 2, "prompt": "Quelle image garde l''humanité du Christ intacte ?", "promptLanguage": "fr", "answer": "le fer chauffé au rouge", "acceptedAnswers": ["le fer chauffé au rouge"], "explanation": "Le fer reste du fer.", "instruction": "Choisis la bonne réponse.", "step": 3, "options": ["la goutte de miel dans l''eau", "le fer chauffé au rouge", "la fumée qui sort d''un feu"], "pool": "lesson", "lessonId": "eg.l510", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
