insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l510.e08', 'eg', 'eg.l510', 'eg.g510.fer_feu', array['eg.g510.fer_feu']::text[], 'mcq', 'lesson', 'Que veut dire « sans division » ?', array['le Christ n''est pas coupé en deux']::text[], 'Le fer et le feu ne se séparent plus.', 1, '{"id": "eg.l510.e08", "unitIds": ["eg.g510.fer_feu"], "type": "mcq", "difficulty": 1, "prompt": "Que veut dire « sans division » ?", "promptLanguage": "fr", "answer": "le Christ n''est pas coupé en deux", "acceptedAnswers": ["le Christ n''est pas coupé en deux"], "explanation": "Le fer et le feu ne se séparent plus.", "instruction": "Choisis la bonne réponse.", "step": 4, "options": ["le Christ n''est pas coupé en deux", "l''humanité est absorbée par le feu", "Marie n''est pas Théotokos pour nous"], "pool": "lesson", "lessonId": "eg.l510", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l510.e09', 'eg', 'eg.l510', 'eg.g510.fer_feu', array['eg.g510.fer_feu']::text[], 'mcq', 'lesson', 'Quand l''Église copte proclame-t-elle cette foi ?', array['avant la communion']::text[], 'Dans la confession, juste avant de communier.', 1, '{"id": "eg.l510.e09", "unitIds": ["eg.g510.fer_feu"], "type": "mcq", "difficulty": 1, "prompt": "Quand l''Église copte proclame-t-elle cette foi ?", "promptLanguage": "fr", "answer": "avant la communion", "acceptedAnswers": ["avant la communion"], "explanation": "Dans la confession, juste avant de communier.", "instruction": "Choisis la bonne réponse.", "step": 5, "options": ["avant le baptême", "avant la communion", "après la bénédiction"], "pool": "lesson", "lessonId": "eg.l510", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l510.e10', 'eg', 'eg.l510', 'eg.g510.fer_feu', array['eg.g510.fer_feu']::text[], 'match', 'lesson', 'Quatre images à bien distinguer.', '{}'::text[], 'Trois images pour l''unité, une seule pour l''erreur.', 2, '{"id": "eg.l510.e10", "unitIds": ["eg.g510.fer_feu"], "type": "match", "difficulty": 2, "prompt": "Quatre images à bien distinguer.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Trois images pour l''unité, une seule pour l''erreur.", "instruction": "Associe.", "pairs": [{"left": "le fer chauffé au rouge", "right": "l''humanité reste entière"}, {"left": "la goutte de miel", "right": "l''humanité est absorbée"}, {"left": "l''âme et le corps", "right": "deux réalités, un seul homme"}, {"left": "sans division", "right": "pas deux personnes"}], "pool": "lesson", "lessonId": "eg.l510", "skill": "recognition", "answer": "le fer chauffé au rouge = l''humanité reste entière ; la goutte de miel = l''humanité est absorbée ; l''âme et le corps = deux réalités, un seul homme ; sans division = pas deux personnes"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l510.e11', 'eg', 'eg.l510', 'eg.g510.fer_feu', array['eg.g510.fer_feu']::text[], 'mcq', 'lesson', 'Ne pas confondre : quelle image sert à Eutychès, et non à Cyrille ?', array['une goutte de miel dans la mer']::text[], 'Le miel disparaît : c''est l''humanité absorbée.', 2, '{"id": "eg.l510.e11", "unitIds": ["eg.g510.fer_feu"], "type": "mcq", "difficulty": 2, "prompt": "Ne pas confondre : quelle image sert à Eutychès, et non à Cyrille ?", "promptLanguage": "fr", "answer": "une goutte de miel dans la mer", "acceptedAnswers": ["une goutte de miel dans la mer"], "explanation": "Le miel disparaît : c''est l''humanité absorbée.", "instruction": "Choisis la bonne réponse.", "options": ["le fer chauffé au rouge dans le feu", "l''âme et le corps d''un seul homme", "une goutte de miel dans la mer"], "pool": "lesson", "lessonId": "eg.l510", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l510.e12', 'eg', 'eg.l510', 'eg.g510.fer_feu', array['eg.g510.fer_feu']::text[], 'fill_blank', 'lesson', 'Sans ___ : le Christ n''est pas coupé en deux.', array['division']::text[], 'Sans mélange protège l''humanité, sans division protège l''unité.', 2, '{"id": "eg.l510.e12", "unitIds": ["eg.g510.fer_feu"], "type": "fill_blank", "difficulty": 2, "prompt": "Sans ___ : le Christ n''est pas coupé en deux.", "promptLanguage": "fr", "answer": "division", "acceptedAnswers": ["division"], "explanation": "Sans mélange protège l''humanité, sans division protège l''unité.", "instruction": "Complète la phrase.", "options": ["division", "mélange", "pardon"], "pool": "lesson", "lessonId": "eg.l510", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l510.e13', 'eg', 'eg.l510', 'eg.g510.fer_feu', array['eg.g510.fer_feu']::text[], 'mcq', 'lesson', 'Pourquoi l''image du fer défend-elle mieux Cyrille que celle du miel ?', array['Le fer reste du fer, alors que le miel disparaît']::text[], 'L''humanité du Christ n''est pas détruite : elle est unie.', 3, '{"id": "eg.l510.e13", "unitIds": ["eg.g510.fer_feu"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi l''image du fer défend-elle mieux Cyrille que celle du miel ?", "promptLanguage": "fr", "answer": "Le fer reste du fer, alors que le miel disparaît", "acceptedAnswers": ["Le fer reste du fer, alors que le miel disparaît"], "explanation": "L''humanité du Christ n''est pas détruite : elle est unie.", "instruction": "Choisis la bonne réponse.", "options": ["Le fer est bien plus cher et plus rare que le miel", "Le fer reste du fer, alors que le miel disparaît", "Le miel vient d''un autre pays que celui du fer"], "pool": "lesson", "lessonId": "eg.l510", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
