insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l511.e12', 'eg', 'eg.l511', 'eg.g511.mono_dyo_mia', array['eg.g511.mono_dyo_mia']::text[], 'mcq', 'lesson', 'Ne pas confondre : les coptes sont...', array['miaphysites']::text[], 'Miaphysites, comme Cyrille.', 2, '{"id": "eg.l511.e12", "unitIds": ["eg.g511.mono_dyo_mia"], "type": "mcq", "difficulty": 2, "prompt": "Ne pas confondre : les coptes sont...", "promptLanguage": "fr", "answer": "miaphysites", "acceptedAnswers": ["miaphysites"], "explanation": "Miaphysites, comme Cyrille.", "instruction": "Choisis la bonne réponse.", "options": ["monophysites", "miaphysites", "nestoriens"], "pool": "lesson", "lessonId": "eg.l511", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l511.e13', 'eg', 'eg.l511', 'eg.g511.mono_dyo_mia', array['eg.g511.mono_dyo_mia']::text[], 'mcq', 'lesson', 'Un ami catholique te dit : « Vous croyez à une seule nature, donc vous niez l''humanité du Christ. » Que réponds-tu ?', array['Nous disons une nature unie, humaine et divine, sans mélange']::text[], 'Le miaphysisme n''est pas le monophysisme : l''humanité reste entière.', 3, '{"id": "eg.l511.e13", "unitIds": ["eg.g511.mono_dyo_mia"], "type": "mcq", "difficulty": 3, "prompt": "Un ami catholique te dit : « Vous croyez à une seule nature, donc vous niez l''humanité du Christ. » Que réponds-tu ?", "promptLanguage": "fr", "answer": "Nous disons une nature unie, humaine et divine, sans mélange", "acceptedAnswers": ["Nous disons une nature unie, humaine et divine, sans mélange"], "explanation": "Le miaphysisme n''est pas le monophysisme : l''humanité reste entière.", "instruction": "Choisis la bonne réponse.", "options": ["Oui, l''humanité disparaît dans la divinité comme le miel", "Non, nous ne parlons jamais de nature dans notre foi", "Nous disons une nature unie, humaine et divine, sans mélange"], "pool": "lesson", "lessonId": "eg.l511", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l511.e14', 'eg', 'eg.l511', 'eg.g511.mono_dyo_mia', array['eg.g511.mono_dyo_mia','eg.v.c05_miaphysisme','eg.v.c05_physis','eg.g510.fer_feu']::text[], 'mcq', 'lesson', 'Quelle image illustre le miaphysisme : le fer chauffé au rouge ou la goutte de miel ?', array['le fer chauffé au rouge']::text[], 'Le fer reste du fer, uni au feu.', 2, '{"id": "eg.l511.e14", "unitIds": ["eg.g511.mono_dyo_mia", "eg.v.c05_miaphysisme", "eg.v.c05_physis", "eg.g510.fer_feu"], "type": "mcq", "difficulty": 2, "prompt": "Quelle image illustre le miaphysisme : le fer chauffé au rouge ou la goutte de miel ?", "promptLanguage": "fr", "answer": "le fer chauffé au rouge", "acceptedAnswers": ["le fer chauffé au rouge"], "explanation": "Le fer reste du fer, uni au feu.", "instruction": "Choisis la bonne réponse.", "options": ["le fer chauffé au rouge", "la goutte de miel", "la barque sur le lac"], "pool": "lesson", "lessonId": "eg.l511", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
