insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l512.e11', 'eg', 'eg.l512', 'eg.g512.ephese_449', array['eg.g512.ephese_449','eg.v.c05_leon_ier']::text[], 'match', 'lesson', 'Éphèse II : qui est qui ?', '{}'::text[], 'Quatre rôles en août 449.', 2, '{"id": "eg.l512.e11", "unitIds": ["eg.g512.ephese_449", "eg.v.c05_leon_ier"], "type": "match", "difficulty": 2, "prompt": "Éphèse II : qui est qui ?", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Quatre rôles en août 449.", "instruction": "Associe.", "pairs": [{"left": "Théodose II", "right": "convoque le concile"}, {"left": "Dioscore", "right": "préside"}, {"left": "Flavien", "right": "est déposé"}, {"left": "Léon Ier", "right": "envoie le Tome par ses légats"}], "pool": "lesson", "lessonId": "eg.l512", "skill": "recognition", "answer": "Théodose II = convoque le concile ; Dioscore = préside ; Flavien = est déposé ; Léon Ier = envoie le Tome par ses légats"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
