insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l513.e12', 'eg', 'eg.l513', 'eg.g513.chalcedoine', array['eg.g513.chalcedoine','eg.v.c05_canon_28']::text[], 'match', 'lesson', 'Chalcédoine, quatre repères.', '{}'::text[], 'Chacun a son rôle dans ce concile.', 2, '{"id": "eg.l513.e12", "unitIds": ["eg.g513.chalcedoine", "eg.v.c05_canon_28"], "type": "match", "difficulty": 2, "prompt": "Chalcédoine, quatre repères.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Chacun a son rôle dans ce concile.", "instruction": "Associe.", "pairs": [{"left": "Marcien", "right": "l''empereur qui convoque"}, {"left": "Léon", "right": "absent, représenté par ses légats"}, {"left": "le Tome de Léon", "right": "lu et ratifié"}, {"left": "le canon 28", "right": "Constantinople deuxième"}], "pool": "lesson", "lessonId": "eg.l513", "skill": "recognition", "answer": "Marcien = l''empereur qui convoque ; Léon = absent, représenté par ses légats ; le Tome de Léon = lu et ratifié ; le canon 28 = Constantinople deuxième"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l513.e13', 'eg', 'eg.l513', 'eg.g513.chalcedoine', array['eg.g513.chalcedoine']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : Eutychès condamné, Éphèse II, mort de Théodose II, Chalcédoine.', array['448 449 450 451']::text[], 'Quatre années qui se suivent.', 2, '{"id": "eg.l513.e13", "unitIds": ["eg.g513.chalcedoine"], "type": "reorder", "difficulty": 2, "prompt": "Remets dans l''ordre : Eutychès condamné, Éphèse II, mort de Théodose II, Chalcédoine.", "promptLanguage": "fr", "answer": "448 449 450 451", "acceptedAnswers": ["448 449 450 451"], "explanation": "Quatre années qui se suivent.", "instruction": "Remets dans l''ordre.", "tokens": ["449", "450", "451", "448"], "pool": "lesson", "lessonId": "eg.l513", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l513.e14', 'eg', 'eg.l513', 'eg.g513.chalcedoine', array['eg.g513.chalcedoine','eg.g511.mono_dyo_mia']::text[], 'mcq', 'lesson', 'Ne pas confondre : qui parle de « deux natures » : la formule de Cyrille ou Chalcédoine ?', array['Chalcédoine']::text[], 'Cyrille disait une seule nature du Verbe incarné.', 2, '{"id": "eg.l513.e14", "unitIds": ["eg.g513.chalcedoine", "eg.g511.mono_dyo_mia"], "type": "mcq", "difficulty": 2, "prompt": "Ne pas confondre : qui parle de « deux natures » : la formule de Cyrille ou Chalcédoine ?", "promptLanguage": "fr", "answer": "Chalcédoine", "acceptedAnswers": ["Chalcédoine"], "explanation": "Cyrille disait une seule nature du Verbe incarné.", "instruction": "Choisis la bonne réponse.", "options": ["la formule de Cyrille", "Chalcédoine"], "pool": "lesson", "lessonId": "eg.l513", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l513.e15', 'eg', 'eg.l513', 'eg.g513.chalcedoine', array['eg.g513.chalcedoine']::text[], 'mcq', 'lesson', 'Pourquoi les coptes disent-ils que « deux natures » ressemble au nestorianisme ?', array['Elle semble séparer ce que Cyrille a uni']::text[], 'Pour eux, parler de deux natures risque de couper le Christ en deux.', 3, '{"id": "eg.l513.e15", "unitIds": ["eg.g513.chalcedoine"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi les coptes disent-ils que « deux natures » ressemble au nestorianisme ?", "promptLanguage": "fr", "answer": "Elle semble séparer ce que Cyrille a uni", "acceptedAnswers": ["Elle semble séparer ce que Cyrille a uni"], "explanation": "Pour eux, parler de deux natures risque de couper le Christ en deux.", "instruction": "Choisis la bonne réponse.", "options": ["Elle semble séparer ce que Cyrille a uni", "Elle a été écrite par Nestorius lui-même à Éphèse", "Elle supprime le credo de Nicée dans les églises"], "pool": "lesson", "lessonId": "eg.l513", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
