insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l514.e12', 'eg', 'eg.l514', 'eg.g514.dioscore', array['eg.g514.dioscore','eg.v.c05_dioscore']::text[], 'match', 'lesson', 'Les trois accusations contre Dioscore et leurs réponses.', '{}'::text[], 'Chaque accusation a sa réponse, selon la tradition copte.', 2, '{"id": "eg.l514.e12", "unitIds": ["eg.g514.dioscore", "eg.v.c05_dioscore"], "type": "match", "difficulty": 2, "prompt": "Les trois accusations contre Dioscore et leurs réponses.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Chaque accusation a sa réponse, selon la tradition copte.", "instruction": "Associe.", "pairs": [{"left": "avoir accepté Eutychès", "right": "le Christ est UN"}, {"left": "avoir condamné Flavien", "right": "Flavien avait enfreint Nicée et Éphèse I"}, {"left": "ne pas avoir lu le Tome", "right": "faute de temps"}], "pool": "lesson", "lessonId": "eg.l514", "skill": "recognition", "answer": "avoir accepté Eutychès = le Christ est UN ; avoir condamné Flavien = Flavien avait enfreint Nicée et Éphèse I ; ne pas avoir lu le Tome = faute de temps"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
