insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l514.e14', 'eg', 'eg.l514', 'eg.g514.dioscore', array['eg.g514.dioscore']::text[], 'mcq', 'lesson', 'Pourquoi l''Église copte insiste-t-elle sur « déposé pour sa conduite, non pour hérésie » ?', array['Cela montre que sa foi n''a pas été jugée fausse']::text[], 'La foi de Dioscore n''a pas été condamnée : c''est sa conduite qui l''a été.', 3, '{"id": "eg.l514.e14", "unitIds": ["eg.g514.dioscore"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi l''Église copte insiste-t-elle sur « déposé pour sa conduite, non pour hérésie » ?", "promptLanguage": "fr", "answer": "Cela montre que sa foi n''a pas été jugée fausse", "acceptedAnswers": ["Cela montre que sa foi n''a pas été jugée fausse"], "explanation": "La foi de Dioscore n''a pas été condamnée : c''est sa conduite qui l''a été.", "instruction": "Choisis la bonne réponse.", "options": ["Cela montre que sa foi n''a pas été jugée fausse", "Cela prouve qu''il a toujours obéi aux ordres de Léon", "Cela prouve que le concile s''est tenu en secret"], "pool": "lesson", "lessonId": "eg.l514", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
