insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l517.e06', 'eg', 'eg.l517', 'eg.g517.bilan', array['eg.g517.bilan']::text[], 'match', 'lesson', 'Les acteurs du Ve siècle : qui est qui ?', '{}'::text[], 'Quatre portraits à garder en tête.', 2, '{"id": "eg.l517.e06", "unitIds": ["eg.g517.bilan"], "type": "match", "difficulty": 2, "prompt": "Les acteurs du Ve siècle : qui est qui ?", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Quatre portraits à garder en tête.", "instruction": "Associe.", "pairs": [{"left": "Nestorius", "right": "patriarche qui refuse Théotokos"}, {"left": "Cyrille", "right": "le Pilier de la foi"}, {"left": "Eutychès", "right": "archimandrite, humanité absorbée"}, {"left": "Dioscore", "right": "25e pape, préside Éphèse II"}], "pool": "lesson", "lessonId": "eg.l517", "skill": "recognition", "answer": "Nestorius = patriarche qui refuse Théotokos ; Cyrille = le Pilier de la foi ; Eutychès = archimandrite, humanité absorbée ; Dioscore = 25e pape, préside Éphèse II"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l517.e07', 'eg', 'eg.l517', 'eg.g517.bilan', array['eg.g517.bilan']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : Nestorius patriarche, Éphèse I, Éphèse II, Chalcédoine.', array['428 431 449 451']::text[], 'Vingt-trois années qui changent l''Église.', 2, '{"id": "eg.l517.e07", "unitIds": ["eg.g517.bilan"], "type": "reorder", "difficulty": 2, "prompt": "Remets dans l''ordre : Nestorius patriarche, Éphèse I, Éphèse II, Chalcédoine.", "promptLanguage": "fr", "answer": "428 431 449 451", "acceptedAnswers": ["428 431 449 451"], "explanation": "Vingt-trois années qui changent l''Église.", "instruction": "Remets dans l''ordre.", "tokens": ["431", "449", "451", "428"], "pool": "lesson", "lessonId": "eg.l517", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
