insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l517.e12', 'eg', 'eg.l517', 'eg.g517.bilan', array['eg.g517.bilan']::text[], 'mcq', 'lesson', 'Quelle image protège l''humanité du Christ ?', array['le fer chauffé au rouge']::text[], 'Le fer reste du fer, uni au feu.', 2, '{"id": "eg.l517.e12", "unitIds": ["eg.g517.bilan"], "type": "mcq", "difficulty": 2, "prompt": "Quelle image protège l''humanité du Christ ?", "promptLanguage": "fr", "answer": "le fer chauffé au rouge", "acceptedAnswers": ["le fer chauffé au rouge"], "explanation": "Le fer reste du fer, uni au feu.", "instruction": "Choisis la bonne réponse.", "options": ["une goutte de miel dans la mer", "le fer chauffé au rouge", "une feuille dans le vent"], "pool": "lesson", "lessonId": "eg.l517", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
