insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l517.e14', 'eg', 'eg.l517', 'eg.g517.bilan', array['eg.g517.bilan']::text[], 'mcq', 'lesson', 'Pourquoi Théotokos protège-t-il d''abord le Christ ?', array['Il garantit que celui qui naît de Marie est Dieu le Verbe']::text[], 'Si le Verbe ne naît pas de Marie, ce n''est plus Dieu qui a souffert pour nous.', 3, '{"id": "eg.l517.e14", "unitIds": ["eg.g517.bilan"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi Théotokos protège-t-il d''abord le Christ ?", "promptLanguage": "fr", "answer": "Il garantit que celui qui naît de Marie est Dieu le Verbe", "acceptedAnswers": ["Il garantit que celui qui naît de Marie est Dieu le Verbe"], "explanation": "Si le Verbe ne naît pas de Marie, ce n''est plus Dieu qui a souffert pour nous.", "instruction": "Choisis la bonne réponse.", "options": ["Il garantit que celui qui naît de Marie est Dieu le Verbe", "Il rend Marie plus ancienne que le Verbe lui-même, dit-on", "Il interdit de parler du Christ dans les églises du pays"], "pool": "lesson", "lessonId": "eg.l517", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l517.e15', 'eg', 'eg.l517', 'eg.g517.bilan', array['eg.g517.bilan']::text[], 'mcq', 'lesson', 'Quelle différence essentielle sépare l''Église copte d''Eutychès, malgré « une nature » ?', array['Les coptes gardent l''humanité entière ; Eutychès la fait disparaître']::text[], 'Même vocabulaire, sens opposés.', 3, '{"id": "eg.l517.e15", "unitIds": ["eg.g517.bilan"], "type": "mcq", "difficulty": 3, "prompt": "Quelle différence essentielle sépare l''Église copte d''Eutychès, malgré « une nature » ?", "promptLanguage": "fr", "answer": "Les coptes gardent l''humanité entière ; Eutychès la fait disparaître", "acceptedAnswers": ["Les coptes gardent l''humanité entière ; Eutychès la fait disparaître"], "explanation": "Même vocabulaire, sens opposés.", "instruction": "Choisis la bonne réponse.", "options": ["Les coptes parlent le grec alors qu''Eutychès parlait le copte", "Les coptes gardent l''humanité entière ; Eutychès la fait disparaître", "Eutychès n''a jamais cité Cyrille, qu''il ne connaissait pas du tout"], "pool": "lesson", "lessonId": "eg.l517", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l517.e16', 'eg', 'eg.l517', 'eg.g517.bilan', array['eg.g517.bilan','eg.v.c05_christologie']::text[], 'mcq', 'lesson', 'Un ami byzantin dit : « Vous avez quitté l''Église en 451 ». Que réponds-tu ?', array['Nous gardons la foi de Cyrille, et nos Églises ont la même christologie']::text[], 'Les mots diffèrent, mais l''accord de 1989 constate la même foi.', 3, '{"id": "eg.l517.e16", "unitIds": ["eg.g517.bilan", "eg.v.c05_christologie"], "type": "mcq", "difficulty": 3, "prompt": "Un ami byzantin dit : « Vous avez quitté l''Église en 451 ». Que réponds-tu ?", "promptLanguage": "fr", "answer": "Nous gardons la foi de Cyrille, et nos Églises ont la même christologie", "acceptedAnswers": ["Nous gardons la foi de Cyrille, et nos Églises ont la même christologie"], "explanation": "Les mots diffèrent, mais l''accord de 1989 constate la même foi.", "instruction": "Choisis la bonne réponse.", "options": ["Nous reconnaissons sept conciles, comme vous, depuis l''origine de l''Église", "Nous avons toujours suivi Eutychès et refusé Cyrille", "Nous gardons la foi de Cyrille, et nos Églises ont la même christologie"], "pool": "lesson", "lessonId": "eg.l517", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
