insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l601.e04', 'eg', 'eg.l601', 'eg.g601.logique_concile', array['eg.g601.logique_concile','eg.v.c01_concile_de_jerusalem']::text[], 'mcq', 'lesson', 'Quel concile sert de modèle à tous les autres, vers l''an 49 ?', array['Jérusalem']::text[], 'Jérusalem : on écoute les témoins, l''Écriture, puis on décide ensemble.', 1, '{"id": "eg.l601.e04", "unitIds": ["eg.g601.logique_concile", "eg.v.c01_concile_de_jerusalem"], "type": "mcq", "difficulty": 1, "prompt": "Quel concile sert de modèle à tous les autres, vers l''an 49 ?", "promptLanguage": "fr", "answer": "Jérusalem", "acceptedAnswers": ["Jérusalem"], "explanation": "Jérusalem : on écoute les témoins, l''Écriture, puis on décide ensemble.", "instruction": "Choisis la bonne réponse.", "step": 2, "options": ["Jérusalem", "Nicée", "Éphèse"], "pool": "lesson", "lessonId": "eg.l601", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l601.e05', 'eg', 'eg.l601', 'eg.g601.logique_concile', array['eg.g601.logique_concile','eg.v.c04_anathemes']::text[], 'mcq', 'lesson', 'Tu te souviens ? Que sont les anathèmes ?', array['des condamnations solennelles']::text[], 'Anathème : on condamne l''erreur, pas la personne qui se repent.', 1, '{"id": "eg.l601.e05", "unitIds": ["eg.g601.logique_concile", "eg.v.c04_anathemes"], "type": "mcq", "difficulty": 1, "prompt": "Tu te souviens ? Que sont les anathèmes ?", "promptLanguage": "fr", "answer": "des condamnations solennelles", "acceptedAnswers": ["des condamnations solennelles"], "explanation": "Anathème : on condamne l''erreur, pas la personne qui se repent.", "instruction": "Choisis la bonne réponse.", "step": 3, "options": ["des règles pour la vie courante", "des condamnations solennelles", "des chants pour la liturgie du soir"], "pool": "lesson", "lessonId": "eg.l601", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
