insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l601.e07', 'eg', 'eg.l601', 'eg.g601.logique_concile', array['eg.g601.logique_concile','eg.v.c05_nestorius']::text[], 'mcq', 'lesson', 'Qui, selon ses adversaires, sépare le Christ en deux ?', array['Nestorius']::text[], 'Nestorius sépare ; Eutychès, en face, mélange.', 1, '{"id": "eg.l601.e07", "unitIds": ["eg.g601.logique_concile", "eg.v.c05_nestorius"], "type": "mcq", "difficulty": 1, "prompt": "Qui, selon ses adversaires, sépare le Christ en deux ?", "promptLanguage": "fr", "answer": "Nestorius", "acceptedAnswers": ["Nestorius"], "explanation": "Nestorius sépare ; Eutychès, en face, mélange.", "instruction": "Choisis la bonne réponse.", "step": 4, "options": ["Nestorius", "Eutychès", "Cyrille"], "pool": "lesson", "lessonId": "eg.l601", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l601.e08', 'eg', 'eg.l601', 'eg.g601.logique_concile', array['eg.g601.logique_concile','eg.v.c05_trois_premiers_conciles']::text[], 'mcq', 'lesson', 'Tu te souviens ? Combien de conciles l''Église copte reconnaît-elle ?', array['trois']::text[], 'Nicée, Constantinople, Éphèse : trois, comme les trois premiers siècles de crises.', 1, '{"id": "eg.l601.e08", "unitIds": ["eg.g601.logique_concile", "eg.v.c05_trois_premiers_conciles"], "type": "mcq", "difficulty": 1, "prompt": "Tu te souviens ? Combien de conciles l''Église copte reconnaît-elle ?", "promptLanguage": "fr", "answer": "trois", "acceptedAnswers": ["trois"], "explanation": "Nicée, Constantinople, Éphèse : trois, comme les trois premiers siècles de crises.", "instruction": "Choisis la bonne réponse.", "step": 5, "options": ["sept", "trois", "douze"], "pool": "lesson", "lessonId": "eg.l601", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l601.e09', 'eg', 'eg.l601', 'eg.g601.logique_concile', array['eg.g601.logique_concile']::text[], 'mcq', 'lesson', 'Quelle est l''année du concile de Nicée ?', array['325']::text[], '325 : Constantin, Arius, homoousios.', 2, '{"id": "eg.l601.e09", "unitIds": ["eg.g601.logique_concile"], "type": "mcq", "difficulty": 2, "prompt": "Quelle est l''année du concile de Nicée ?", "promptLanguage": "fr", "answer": "325", "acceptedAnswers": ["325"], "explanation": "325 : Constantin, Arius, homoousios.", "instruction": "Choisis la bonne réponse.", "step": 5, "options": ["33", "1054", "325"], "pool": "lesson", "lessonId": "eg.l601", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l601.e10', 'eg', 'eg.l601', 'eg.g601.logique_concile', array['eg.g601.logique_concile','eg.v.c04_arius','eg.v.c04_macedonius','eg.v.c05_nestorius','eg.v.c03_paul_de_samosate']::text[], 'match', 'lesson', 'Chaque erreur a son concile.', '{}'::text[], 'Une erreur, un lieu de réponse. Antioche est un synode, les trois autres sont œcuméniques.', 2, '{"id": "eg.l601.e10", "unitIds": ["eg.g601.logique_concile", "eg.v.c04_arius", "eg.v.c04_macedonius", "eg.v.c05_nestorius", "eg.v.c03_paul_de_samosate"], "type": "match", "difficulty": 2, "prompt": "Chaque erreur a son concile.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Une erreur, un lieu de réponse. Antioche est un synode, les trois autres sont œcuméniques.", "instruction": "Associe.", "pairs": [{"left": "Arius", "right": "Nicée"}, {"left": "Macédonius", "right": "Constantinople"}, {"left": "Nestorius", "right": "Éphèse"}, {"left": "Paul de Samosate", "right": "Antioche"}], "pool": "lesson", "lessonId": "eg.l601", "skill": "recognition", "answer": "Arius = Nicée ; Macédonius = Constantinople ; Nestorius = Éphèse ; Paul de Samosate = Antioche"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l601.e11', 'eg', 'eg.l601', 'eg.g601.logique_concile', array['eg.g601.logique_concile','eg.v.c06_reception_d_un_concile']::text[], 'reorder', 'lesson', 'Remets le cycle d''un concile dans l''ordre.', array['Erreur Concile Formule Réception']::text[], 'On répond à l''erreur par un concile, on fixe une formule, puis l''Église la reçoit.', 2, '{"id": "eg.l601.e11", "unitIds": ["eg.g601.logique_concile", "eg.v.c06_reception_d_un_concile"], "type": "reorder", "difficulty": 2, "prompt": "Remets le cycle d''un concile dans l''ordre.", "promptLanguage": "fr", "answer": "Erreur Concile Formule Réception", "acceptedAnswers": ["Erreur Concile Formule Réception"], "explanation": "On répond à l''erreur par un concile, on fixe une formule, puis l''Église la reçoit.", "instruction": "Remets dans l''ordre.", "tokens": ["Formule", "Erreur", "Réception", "Concile"], "pool": "lesson", "lessonId": "eg.l601", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l601.e12', 'eg', 'eg.l601', 'eg.g601.logique_concile', array['eg.g601.logique_concile','eg.v.c05_canon_3_de_381']::text[], 'mcq', 'lesson', 'Quel produit d''un concile règle la place des sièges, comme Constantinople après Rome ?', array['canon']::text[], 'Le canon 3 de 381 fixe un rang : c''est une règle de vie, pas une formule de foi.', 2, '{"id": "eg.l601.e12", "unitIds": ["eg.g601.logique_concile", "eg.v.c05_canon_3_de_381"], "type": "mcq", "difficulty": 2, "prompt": "Quel produit d''un concile règle la place des sièges, comme Constantinople après Rome ?", "promptLanguage": "fr", "answer": "canon", "acceptedAnswers": ["canon"], "explanation": "Le canon 3 de 381 fixe un rang : c''est une règle de vie, pas une formule de foi.", "instruction": "Choisis la bonne réponse.", "options": ["anathème", "credo", "canon"], "pool": "lesson", "lessonId": "eg.l601", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
