insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l603.e09', 'eg', 'eg.l603', 'eg.g603.erreurs_trinite', array['eg.g603.erreurs_trinite','eg.v.c03_paul_de_samosate','eg.v.c03_sabellius','eg.v.c04_arius','eg.v.c04_macedonius']::text[], 'match', 'lesson', 'Chaque erreur, sa phrase.', '{}'::text[], 'Quatre phrases-repères sur la Trinité.', 2, '{"id": "eg.l603.e09", "unitIds": ["eg.g603.erreurs_trinite", "eg.v.c03_paul_de_samosate", "eg.v.c03_sabellius", "eg.v.c04_arius", "eg.v.c04_macedonius"], "type": "match", "difficulty": 2, "prompt": "Chaque erreur, sa phrase.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Quatre phrases-repères sur la Trinité.", "instruction": "Associe.", "pairs": [{"left": "Paul de Samosate", "right": "un homme ordinaire"}, {"left": "Sabellius", "right": "trois masques"}, {"left": "Arius", "right": "le Fils est créé"}, {"left": "Macédonius", "right": "l''Esprit est créé"}], "pool": "lesson", "lessonId": "eg.l603", "skill": "recognition", "answer": "Paul de Samosate = un homme ordinaire ; Sabellius = trois masques ; Arius = le Fils est créé ; Macédonius = l''Esprit est créé"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l603.e10', 'eg', 'eg.l603', 'eg.g603.erreurs_trinite', array['eg.g603.erreurs_trinite','eg.v.c03_paul_de_samosate','eg.v.c04_arius','eg.v.c04_macedonius','eg.v.c05_nestorius']::text[], 'match', 'lesson', 'Chaque erreur, le concile qui répond.', '{}'::text[], 'Antioche est un synode ; les trois autres sont les conciles reçus par les coptes.', 2, '{"id": "eg.l603.e10", "unitIds": ["eg.g603.erreurs_trinite", "eg.v.c03_paul_de_samosate", "eg.v.c04_arius", "eg.v.c04_macedonius", "eg.v.c05_nestorius"], "type": "match", "difficulty": 2, "prompt": "Chaque erreur, le concile qui répond.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Antioche est un synode ; les trois autres sont les conciles reçus par les coptes.", "instruction": "Associe.", "pairs": [{"left": "Paul de Samosate", "right": "Antioche"}, {"left": "Arius", "right": "Nicée"}, {"left": "Macédonius", "right": "Constantinople"}, {"left": "Nestorius", "right": "Éphèse"}], "pool": "lesson", "lessonId": "eg.l603", "skill": "recognition", "answer": "Paul de Samosate = Antioche ; Arius = Nicée ; Macédonius = Constantinople ; Nestorius = Éphèse"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l603.e11', 'eg', 'eg.l603', 'eg.g603.erreurs_trinite', array['eg.g603.erreurs_trinite','eg.v.c03_paul_de_samosate','eg.v.c04_arius']::text[], 'reorder', 'lesson', 'Remets dans l''ordre, du plus ancien au plus récent.', array['Paul-de-Samosate Arius Nicée Constantinople']::text[], '269, vers 318, 325, 381 : l''erreur appelle le concile.', 2, '{"id": "eg.l603.e11", "unitIds": ["eg.g603.erreurs_trinite", "eg.v.c03_paul_de_samosate", "eg.v.c04_arius"], "type": "reorder", "difficulty": 2, "prompt": "Remets dans l''ordre, du plus ancien au plus récent.", "promptLanguage": "fr", "answer": "Paul-de-Samosate Arius Nicée Constantinople", "acceptedAnswers": ["Paul-de-Samosate Arius Nicée Constantinople"], "explanation": "269, vers 318, 325, 381 : l''erreur appelle le concile.", "instruction": "Remets dans l''ordre.", "tokens": ["Nicée", "Paul-de-Samosate", "Constantinople", "Arius"], "pool": "lesson", "lessonId": "eg.l603", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
