insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l603.e13', 'eg', 'eg.l603', 'eg.g603.erreurs_trinite', array['eg.g603.erreurs_trinite','eg.v.c06_adoptianisme']::text[], 'mcq', 'lesson', 'Quel mot désigne l''idée que le Christ est un homme « adopté » par Dieu ?', array['l''adoptianisme']::text[], 'Adopter : Dieu aurait seulement choisi un homme.', 2, '{"id": "eg.l603.e13", "unitIds": ["eg.g603.erreurs_trinite", "eg.v.c06_adoptianisme"], "type": "mcq", "difficulty": 2, "prompt": "Quel mot désigne l''idée que le Christ est un homme « adopté » par Dieu ?", "promptLanguage": "fr", "answer": "l''adoptianisme", "acceptedAnswers": ["l''adoptianisme"], "explanation": "Adopter : Dieu aurait seulement choisi un homme.", "instruction": "Choisis la bonne réponse.", "options": ["l''adoptianisme", "le docétisme", "le modalisme"], "pool": "lesson", "lessonId": "eg.l603", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l603.e14', 'eg', 'eg.l603', 'eg.g603.erreurs_trinite', array['eg.g603.erreurs_trinite','eg.v.c04_divinite_du_christ']::text[], 'mcq', 'lesson', 'Pourquoi l''Église ne peut-elle pas accepter un Fils créé ?', array['Seul Dieu peut sauver l''homme']::text[], 'Une créature ne peut pas sauver une autre créature : le salut est en jeu.', 3, '{"id": "eg.l603.e14", "unitIds": ["eg.g603.erreurs_trinite", "eg.v.c04_divinite_du_christ"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi l''Église ne peut-elle pas accepter un Fils créé ?", "promptLanguage": "fr", "answer": "Seul Dieu peut sauver l''homme", "acceptedAnswers": ["Seul Dieu peut sauver l''homme"], "explanation": "Une créature ne peut pas sauver une autre créature : le salut est en jeu.", "instruction": "Choisis la bonne réponse.", "options": ["Les créatures sont toutes mauvaises", "Seul Dieu peut sauver l''homme", "L''empereur l''a interdit"], "pool": "lesson", "lessonId": "eg.l603", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l603.e15', 'eg', 'eg.l603', 'eg.g603.erreurs_trinite', array['eg.g603.erreurs_trinite','eg.v.c04_macedonius']::text[], 'mcq', 'lesson', 'Qu''ont en commun Arius et Macédonius ?', array['Chacun dit qu''une personne divine est créée']::text[], 'Même schéma : l''un pour le Fils, l''autre pour l''Esprit.', 3, '{"id": "eg.l603.e15", "unitIds": ["eg.g603.erreurs_trinite", "eg.v.c04_macedonius"], "type": "mcq", "difficulty": 3, "prompt": "Qu''ont en commun Arius et Macédonius ?", "promptLanguage": "fr", "answer": "Chacun dit qu''une personne divine est créée", "acceptedAnswers": ["Chacun dit qu''une personne divine est créée"], "explanation": "Même schéma : l''un pour le Fils, l''autre pour l''Esprit.", "instruction": "Choisis la bonne réponse.", "options": ["Chacun nie complètement l''existence du Père", "Chacun veut supprimer toute l''Église", "Chacun dit qu''une personne divine est créée"], "pool": "lesson", "lessonId": "eg.l603", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
