insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l604.e08', 'eg', 'eg.l604', 'eg.g604.erreurs_christ', array['eg.g604.erreurs_christ','eg.v.c05_sans_melange_ni_division']::text[], 'fill_blank', 'lesson', 'Cyrille dit : sans mélange et sans ___.', array['division']::text[], 'Sans mélange (contre Eutychès), sans division (contre Nestorius).', 1, '{"id": "eg.l604.e08", "unitIds": ["eg.g604.erreurs_christ", "eg.v.c05_sans_melange_ni_division"], "type": "fill_blank", "difficulty": 1, "prompt": "Cyrille dit : sans mélange et sans ___.", "promptLanguage": "fr", "answer": "division", "acceptedAnswers": ["division"], "explanation": "Sans mélange (contre Eutychès), sans division (contre Nestorius).", "instruction": "Complète la phrase.", "step": 5, "options": ["fin", "division", "nom"], "pool": "lesson", "lessonId": "eg.l604", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l604.e09', 'eg', 'eg.l604', 'eg.g604.erreurs_christ', array['eg.g604.erreurs_christ','eg.v.c05_eutyches']::text[], 'fill_blank', 'lesson', 'Contre Eutychès : une humanité non ___.', array['absorbée']::text[], 'L''union ne détruit rien, ni la divinité ni l''humanité.', 1, '{"id": "eg.l604.e09", "unitIds": ["eg.g604.erreurs_christ", "eg.v.c05_eutyches"], "type": "fill_blank", "difficulty": 1, "prompt": "Contre Eutychès : une humanité non ___.", "promptLanguage": "fr", "answer": "absorbée", "acceptedAnswers": ["absorbée"], "explanation": "L''union ne détruit rien, ni la divinité ni l''humanité.", "instruction": "Complète la phrase.", "step": 6, "options": ["baptisée", "créée", "absorbée"], "pool": "lesson", "lessonId": "eg.l604", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l604.e10', 'eg', 'eg.l604', 'eg.g604.erreurs_christ', array['eg.g604.erreurs_christ','eg.v.c01_docetisme','eg.v.c04_apollinaire','eg.v.c05_nestorius','eg.v.c05_eutyches']::text[], 'match', 'lesson', 'Chaque erreur, ce qu''elle déforme.', '{}'::text[], 'Une pièce oubliée par erreur : corps, âme, unité, humanité.', 2, '{"id": "eg.l604.e10", "unitIds": ["eg.g604.erreurs_christ", "eg.v.c01_docetisme", "eg.v.c04_apollinaire", "eg.v.c05_nestorius", "eg.v.c05_eutyches"], "type": "match", "difficulty": 2, "prompt": "Chaque erreur, ce qu''elle déforme.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Une pièce oubliée par erreur : corps, âme, unité, humanité.", "instruction": "Associe.", "pairs": [{"left": "le docétisme", "right": "le vrai corps"}, {"left": "Apollinaire", "right": "l''âme humaine"}, {"left": "Nestorius", "right": "l''unité de la personne"}, {"left": "Eutychès", "right": "l''humanité du Christ"}], "pool": "lesson", "lessonId": "eg.l604", "skill": "recognition", "answer": "le docétisme = le vrai corps ; Apollinaire = l''âme humaine ; Nestorius = l''unité de la personne ; Eutychès = l''humanité du Christ"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l604.e11', 'eg', 'eg.l604', 'eg.g604.erreurs_christ', array['eg.g604.erreurs_christ','eg.v.c01_docetisme','eg.v.c04_apollinaire','eg.v.c05_nestorius','eg.v.c05_eutyches']::text[], 'reorder', 'lesson', 'Remets ces quatre erreurs dans l''ordre où elles apparaissent.', array['Docétisme Apollinaire Nestorius Eutychès']::text[], 'Ier siècle, puis 362-381, puis 428, puis 448.', 2, '{"id": "eg.l604.e11", "unitIds": ["eg.g604.erreurs_christ", "eg.v.c01_docetisme", "eg.v.c04_apollinaire", "eg.v.c05_nestorius", "eg.v.c05_eutyches"], "type": "reorder", "difficulty": 2, "prompt": "Remets ces quatre erreurs dans l''ordre où elles apparaissent.", "promptLanguage": "fr", "answer": "Docétisme Apollinaire Nestorius Eutychès", "acceptedAnswers": ["Docétisme Apollinaire Nestorius Eutychès"], "explanation": "Ier siècle, puis 362-381, puis 428, puis 448.", "instruction": "Remets dans l''ordre.", "tokens": ["Nestorius", "Docétisme", "Eutychès", "Apollinaire"], "pool": "lesson", "lessonId": "eg.l604", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l604.e12', 'eg', 'eg.l604', 'eg.g604.erreurs_christ', array['eg.g604.erreurs_christ','eg.v.c05_monophysisme']::text[], 'mcq', 'lesson', 'Qui aurait pu dire : « Après l''union, l''humanité du Christ est absorbée par la divinité » ?', array['Eutychès']::text[], 'C''est le monophysisme : Eutychès, le vieux moine qui mélange tout.', 3, '{"id": "eg.l604.e12", "unitIds": ["eg.g604.erreurs_christ", "eg.v.c05_monophysisme"], "type": "mcq", "difficulty": 3, "prompt": "Qui aurait pu dire : « Après l''union, l''humanité du Christ est absorbée par la divinité » ?", "promptLanguage": "fr", "answer": "Eutychès", "acceptedAnswers": ["Eutychès"], "explanation": "C''est le monophysisme : Eutychès, le vieux moine qui mélange tout.", "instruction": "Choisis la bonne réponse.", "options": ["Nestorius", "Apollinaire", "Eutychès"], "pool": "lesson", "lessonId": "eg.l604", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l604.e13', 'eg', 'eg.l604', 'eg.g604.erreurs_christ', array['eg.g604.erreurs_christ','eg.v.c05_theotokos']::text[], 'mcq', 'lesson', 'Qui aurait pu dire : « Marie ne peut pas être appelée mère de Dieu » ?', array['Nestorius']::text[], 'Nestorius préfère « mère du Christ » ; Cyrille et Eutychès disent Théotokos.', 3, '{"id": "eg.l604.e13", "unitIds": ["eg.g604.erreurs_christ", "eg.v.c05_theotokos"], "type": "mcq", "difficulty": 3, "prompt": "Qui aurait pu dire : « Marie ne peut pas être appelée mère de Dieu » ?", "promptLanguage": "fr", "answer": "Nestorius", "acceptedAnswers": ["Nestorius"], "explanation": "Nestorius préfère « mère du Christ » ; Cyrille et Eutychès disent Théotokos.", "instruction": "Choisis la bonne réponse.", "options": ["Nestorius", "Cyrille", "Eutychès"], "pool": "lesson", "lessonId": "eg.l604", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l604.e14', 'eg', 'eg.l604', 'eg.g604.erreurs_christ', array['eg.g604.erreurs_christ','eg.v.c05_eutyches']::text[], 'mcq', 'lesson', 'Quelle image décrit l''erreur d''Eutychès ?', array['une goutte de miel dans la mer']::text[], 'Le miel disparaît : voilà ce qu''il croit de l''humanité du Christ.', 2, '{"id": "eg.l604.e14", "unitIds": ["eg.g604.erreurs_christ", "eg.v.c05_eutyches"], "type": "mcq", "difficulty": 2, "prompt": "Quelle image décrit l''erreur d''Eutychès ?", "promptLanguage": "fr", "answer": "une goutte de miel dans la mer", "acceptedAnswers": ["une goutte de miel dans la mer"], "explanation": "Le miel disparaît : voilà ce qu''il croit de l''humanité du Christ.", "instruction": "Choisis la bonne réponse.", "options": ["le fer chauffé au rouge dans le feu", "une goutte de miel dans la mer", "deux voisins qui vivent côte à côte"], "pool": "lesson", "lessonId": "eg.l604", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l604.e15', 'eg', 'eg.l604', 'eg.g604.erreurs_christ', array['eg.g604.erreurs_christ','eg.v.c04_apollinaire']::text[], 'mcq', 'lesson', 'Pourquoi un Christ sans âme humaine ne sauverait-il pas l''homme entier ?', array['Il doit prendre l''homme tout entier pour le sauver']::text[], 'Ce qu''il ne prend pas, il ne peut pas le guérir : Timothée répond ainsi à Apollinaire.', 3, '{"id": "eg.l604.e15", "unitIds": ["eg.g604.erreurs_christ", "eg.v.c04_apollinaire"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi un Christ sans âme humaine ne sauverait-il pas l''homme entier ?", "promptLanguage": "fr", "answer": "Il doit prendre l''homme tout entier pour le sauver", "acceptedAnswers": ["Il doit prendre l''homme tout entier pour le sauver"], "explanation": "Ce qu''il ne prend pas, il ne peut pas le guérir : Timothée répond ainsi à Apollinaire.", "instruction": "Choisis la bonne réponse.", "options": ["L''âme n''a vraiment pas besoin d''être sauvée du tout", "Le corps seul suffit à sauver l''homme tout entier", "Il doit prendre l''homme tout entier pour le sauver"], "pool": "lesson", "lessonId": "eg.l604", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
