insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l605.e09', 'eg', 'eg.l605', 'eg.g605.fiche_nicee', array['eg.g605.fiche_nicee','eg.v.c04_concile_de_nicee']::text[], 'match', 'lesson', 'Nicée en fiche : chaque case.', '{}'::text[], 'La grille complète de Nicée.', 2, '{"id": "eg.l605.e09", "unitIds": ["eg.g605.fiche_nicee", "eg.v.c04_concile_de_nicee"], "type": "match", "difficulty": 2, "prompt": "Nicée en fiche : chaque case.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "La grille complète de Nicée.", "instruction": "Associe.", "pairs": [{"left": "Qui convoque ?", "right": "Constantin"}, {"left": "Où ?", "right": "Nicée"}, {"left": "Quand ?", "right": "325"}, {"left": "Contre qui ?", "right": "Arius"}, {"left": "Les héros", "right": "Alexandre et Athanase"}], "pool": "lesson", "lessonId": "eg.l605", "skill": "recognition", "answer": "Qui convoque ? = Constantin ; Où ? = Nicée ; Quand ? = 325 ; Contre qui ? = Arius ; Les héros = Alexandre et Athanase"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l605.e10', 'eg', 'eg.l605', 'eg.g605.fiche_nicee', array['eg.g605.fiche_nicee','eg.v.c04_alexandre','eg.v.c04_athanase','eg.v.c04_eusebe_nicomedie','eg.v.c04_constantin']::text[], 'match', 'lesson', 'Nicée : qui joue quel rôle ?', '{}'::text[], 'Quatre noms, quatre rôles.', 2, '{"id": "eg.l605.e10", "unitIds": ["eg.g605.fiche_nicee", "eg.v.c04_alexandre", "eg.v.c04_athanase", "eg.v.c04_eusebe_nicomedie", "eg.v.c04_constantin"], "type": "match", "difficulty": 2, "prompt": "Nicée : qui joue quel rôle ?", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Quatre noms, quatre rôles.", "instruction": "Associe.", "pairs": [{"left": "Alexandre", "right": "préside, selon la tradition copte"}, {"left": "Athanase", "right": "le jeune diacre"}, {"left": "Eusèbe de Nicomédie", "right": "ami d''Arius"}, {"left": "Constantin", "right": "l''empereur qui convoque"}], "pool": "lesson", "lessonId": "eg.l605", "skill": "recognition", "answer": "Alexandre = préside, selon la tradition copte ; Athanase = le jeune diacre ; Eusèbe de Nicomédie = ami d''Arius ; Constantin = l''empereur qui convoque"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
