insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l606.e03', 'eg', 'eg.l606', 'eg.g606.fiche_constantinople', array['eg.g606.fiche_constantinople','eg.v.c04_macedonius']::text[], 'mcq', 'lesson', 'Quelle est l''erreur de Macédonius ?', array['un Saint-Esprit créé']::text[], 'Macédonius fait pour l''Esprit ce qu''Arius a fait pour le Fils.', 1, '{"id": "eg.l606.e03", "unitIds": ["eg.g606.fiche_constantinople", "eg.v.c04_macedonius"], "type": "mcq", "difficulty": 1, "prompt": "Quelle est l''erreur de Macédonius ?", "promptLanguage": "fr", "answer": "un Saint-Esprit créé", "acceptedAnswers": ["un Saint-Esprit créé"], "explanation": "Macédonius fait pour l''Esprit ce qu''Arius a fait pour le Fils.", "instruction": "Choisis la bonne réponse.", "step": 2, "options": ["un Fils qui est créé", "un Christ sans aucun corps", "un Saint-Esprit créé"], "pool": "lesson", "lessonId": "eg.l606", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
