insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l606.e05', 'eg', 'eg.l606', 'eg.g606.fiche_constantinople', array['eg.g606.fiche_constantinople','eg.v.c04_credo_nicee_constantinople']::text[], 'fill_blank', 'lesson', 'À Constantinople, les Pères développent l''article sur l''___ Saint.', array['Esprit']::text[], 'Nicée n''en disait qu''une ligne ; 381 en dit beaucoup plus.', 1, '{"id": "eg.l606.e05", "unitIds": ["eg.g606.fiche_constantinople", "eg.v.c04_credo_nicee_constantinople"], "type": "fill_blank", "difficulty": 1, "prompt": "À Constantinople, les Pères développent l''article sur l''___ Saint.", "promptLanguage": "fr", "answer": "Esprit", "acceptedAnswers": ["Esprit"], "explanation": "Nicée n''en disait qu''une ligne ; 381 en dit beaucoup plus.", "instruction": "Complète la phrase.", "step": 3, "options": ["Église", "Esprit", "Fils"], "pool": "lesson", "lessonId": "eg.l606", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
