insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l607.e15', 'eg', 'eg.l607', 'eg.g607.fiche_ephese', array['eg.g607.fiche_ephese','eg.v.c05_concile_chalcedoine']::text[], 'mcq', 'lesson', 'Pourquoi les coptes disent-ils que Chalcédoine désobéit à Éphèse ?', array['Elle ajoute une définition à un credo qu''Éphèse interdit de changer']::text[], 'Éphèse a fermé la porte à toute nouvelle définition ; Chalcédoine en ajoute une.', 3, '{"id": "eg.l607.e15", "unitIds": ["eg.g607.fiche_ephese", "eg.v.c05_concile_chalcedoine"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi les coptes disent-ils que Chalcédoine désobéit à Éphèse ?", "promptLanguage": "fr", "answer": "Elle ajoute une définition à un credo qu''Éphèse interdit de changer", "acceptedAnswers": ["Elle ajoute une définition à un credo qu''Éphèse interdit de changer"], "explanation": "Éphèse a fermé la porte à toute nouvelle définition ; Chalcédoine en ajoute une.", "instruction": "Choisis la bonne réponse.", "options": ["Elle supprime le titre Théotokos de Marie", "Elle condamne solennellement le pape Cyrille", "Elle ajoute une définition à un credo qu''Éphèse interdit de changer"], "pool": "lesson", "lessonId": "eg.l607", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
