insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l608.e10', 'eg', 'eg.l608', 'eg.g608.fiches_ephese2_chalcedoine', array['eg.g608.fiches_ephese2_chalcedoine','eg.v.c05_concile_ephese_431','eg.v.c05_concile_ephese_449','eg.v.c05_concile_chalcedoine']::text[], 'match', 'lesson', 'Qui convoque ou préside quel concile ?', '{}'::text[], 'Quatre conciles, quatre noms.', 2, '{"id": "eg.l608.e10", "unitIds": ["eg.g608.fiches_ephese2_chalcedoine", "eg.v.c05_concile_ephese_431", "eg.v.c05_concile_ephese_449", "eg.v.c05_concile_chalcedoine"], "type": "match", "difficulty": 2, "prompt": "Qui convoque ou préside quel concile ?", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Quatre conciles, quatre noms.", "instruction": "Associe.", "pairs": [{"left": "Éphèse (431)", "right": "Cyrille préside"}, {"left": "Éphèse II (449)", "right": "Dioscore préside"}, {"left": "Chalcédoine (451)", "right": "Marcien convoque"}, {"left": "Nicée (325)", "right": "Constantin convoque"}], "pool": "lesson", "lessonId": "eg.l608", "skill": "recognition", "answer": "Éphèse (431) = Cyrille préside ; Éphèse II (449) = Dioscore préside ; Chalcédoine (451) = Marcien convoque ; Nicée (325) = Constantin convoque"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
