insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l610.e09', 'eg', 'eg.l610', 'eg.g610.homonymes', array['eg.g610.homonymes','eg.v.c05_macaire_d_edkou','eg.v.c04_saint_macaire']::text[], 'mcq', 'lesson', 'Quel Macaire est évêque et martyr ?', array['Macaire d''Edkou']::text[], 'Edkou : l''évêque martyr. Le Grand : le moine de Scété.', 1, '{"id": "eg.l610.e09", "unitIds": ["eg.g610.homonymes", "eg.v.c05_macaire_d_edkou", "eg.v.c04_saint_macaire"], "type": "mcq", "difficulty": 1, "prompt": "Quel Macaire est évêque et martyr ?", "promptLanguage": "fr", "answer": "Macaire d''Edkou", "acceptedAnswers": ["Macaire d''Edkou"], "explanation": "Edkou : l''évêque martyr. Le Grand : le moine de Scété.", "instruction": "Choisis la bonne réponse.", "step": 6, "options": ["Macaire le Grand", "Macaire de Rome", "Macaire d''Edkou"], "pool": "lesson", "lessonId": "eg.l610", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l610.e10', 'eg', 'eg.l610', 'eg.g610.homonymes', array['eg.g610.homonymes','eg.v.c03_paul_de_thebes','eg.v.c03_paul_de_samosate','eg.v.c04_eusebe_cesaree','eg.v.c04_eusebe_nicomedie']::text[], 'match', 'lesson', 'Qui est qui parmi les Paul et les Eusèbe ?', '{}'::text[], 'Une marque par nom.', 2, '{"id": "eg.l610.e10", "unitIds": ["eg.g610.homonymes", "eg.v.c03_paul_de_thebes", "eg.v.c03_paul_de_samosate", "eg.v.c04_eusebe_cesaree", "eg.v.c04_eusebe_nicomedie"], "type": "match", "difficulty": 2, "prompt": "Qui est qui parmi les Paul et les Eusèbe ?", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Une marque par nom.", "instruction": "Associe.", "pairs": [{"left": "Paul de Thèbes", "right": "l''ermite au corbeau"}, {"left": "Paul de Samosate", "right": "évêque d''Antioche"}, {"left": "Eusèbe de Césarée", "right": "l''historien"}, {"left": "Eusèbe de Nicomédie", "right": "protecteur d''Arius"}], "pool": "lesson", "lessonId": "eg.l610", "skill": "recognition", "answer": "Paul de Thèbes = l''ermite au corbeau ; Paul de Samosate = évêque d''Antioche ; Eusèbe de Césarée = l''historien ; Eusèbe de Nicomédie = protecteur d''Arius"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l610.e11', 'eg', 'eg.l610', 'eg.g610.homonymes', array['eg.g610.homonymes','eg.v.c05_cyrille','eg.v.c03_cyprien','eg.v.c03_clement']::text[], 'match', 'lesson', 'Cyrille, Cyprien, Clément : qui est qui ?', '{}'::text[], 'Quatre noms qui se ressemblent.', 2, '{"id": "eg.l610.e11", "unitIds": ["eg.g610.homonymes", "eg.v.c05_cyrille", "eg.v.c03_cyprien", "eg.v.c03_clement"], "type": "match", "difficulty": 2, "prompt": "Cyrille, Cyprien, Clément : qui est qui ?", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Quatre noms qui se ressemblent.", "instruction": "Associe.", "pairs": [{"left": "Cyrille d''Alexandrie", "right": "Éphèse en 431"}, {"left": "Cyrille de Jérusalem", "right": "père des catéchumènes"}, {"left": "Cyprien", "right": "évêque de Carthage"}, {"left": "Clément d''Alexandrie", "right": "maître de l''École"}], "pool": "lesson", "lessonId": "eg.l610", "skill": "recognition", "answer": "Cyrille d''Alexandrie = Éphèse en 431 ; Cyrille de Jérusalem = père des catéchumènes ; Cyprien = évêque de Carthage ; Clément d''Alexandrie = maître de l''École"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
