insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l612.e08', 'eg', 'eg.l612', 'eg.g612.trois_formules', array['eg.g612.trois_formules','eg.v.c06_les_trois_formules','eg.v.c04_homoousios','eg.v.c05_theotokos','eg.v.c05_formule_de_cyrille']::text[], 'match', 'lesson', 'Chaque formule, son concile ou son auteur.', '{}'::text[], 'Une formule, un lieu ou un nom.', 2, '{"id": "eg.l612.e08", "unitIds": ["eg.g612.trois_formules", "eg.v.c06_les_trois_formules", "eg.v.c04_homoousios", "eg.v.c05_theotokos", "eg.v.c05_formule_de_cyrille"], "type": "match", "difficulty": 2, "prompt": "Chaque formule, son concile ou son auteur.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Une formule, un lieu ou un nom.", "instruction": "Associe.", "pairs": [{"left": "homoousios", "right": "Nicée"}, {"left": "Théotokos", "right": "Éphèse"}, {"left": "une seule nature du Verbe incarné", "right": "Cyrille"}], "pool": "lesson", "lessonId": "eg.l612", "skill": "recognition", "answer": "homoousios = Nicée ; Théotokos = Éphèse ; une seule nature du Verbe incarné = Cyrille"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
