insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l613.e14', 'eg', 'eg.l613', 'eg.g613.bilan', array['eg.g613.bilan','eg.v.c05_miaphysisme']::text[], 'mcq', 'lesson', 'Que réponds-tu à quelqu''un qui dit que les coptes sont monophysites ?', array['Non : ils condamnent Eutychès, ils sont miaphysites']::text[], 'Mia unit, mono absorbe.', 3, '{"id": "eg.l613.e14", "unitIds": ["eg.g613.bilan", "eg.v.c05_miaphysisme"], "type": "mcq", "difficulty": 3, "prompt": "Que réponds-tu à quelqu''un qui dit que les coptes sont monophysites ?", "promptLanguage": "fr", "answer": "Non : ils condamnent Eutychès, ils sont miaphysites", "acceptedAnswers": ["Non : ils condamnent Eutychès, ils sont miaphysites"], "explanation": "Mia unit, mono absorbe.", "instruction": "Choisis la bonne réponse.", "options": ["Oui, ils suivent Eutychès", "Non : ils condamnent Eutychès, ils sont miaphysites", "Oui, ils comptent deux natures"], "pool": "lesson", "lessonId": "eg.l613", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l613.e15', 'eg', 'eg.l613', 'eg.g613.bilan', array['eg.g613.bilan','eg.v.c05_eutyches']::text[], 'mcq', 'lesson', 'Pourquoi une erreur appelle-t-elle souvent l''erreur inverse ?', array['En répondant trop fort, on oublie l''autre côté de la vérité']::text[], 'Eutychès, en combattant Nestorius, tombe de l''autre côté.', 3, '{"id": "eg.l613.e15", "unitIds": ["eg.g613.bilan", "eg.v.c05_eutyches"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi une erreur appelle-t-elle souvent l''erreur inverse ?", "promptLanguage": "fr", "answer": "En répondant trop fort, on oublie l''autre côté de la vérité", "acceptedAnswers": ["En répondant trop fort, on oublie l''autre côté de la vérité"], "explanation": "Eutychès, en combattant Nestorius, tombe de l''autre côté.", "instruction": "Choisis la bonne réponse.", "options": ["Les évêques aiment les disputes", "Les empereurs inventent des erreurs", "En répondant trop fort, on oublie l''autre côté de la vérité"], "pool": "lesson", "lessonId": "eg.l613", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l613.e16', 'eg', 'eg.l613', 'eg.g613.bilan', array['eg.g613.bilan','eg.v.c05_concile_ephese_449']::text[], 'mcq', 'lesson', 'Vrai ou faux : Éphèse II (449) fait partie des trois conciles des coptes.', array['Faux']::text[], 'Les trois sont Nicée, Constantinople, Éphèse (431).', 2, '{"id": "eg.l613.e16", "unitIds": ["eg.g613.bilan", "eg.v.c05_concile_ephese_449"], "type": "mcq", "difficulty": 2, "prompt": "Vrai ou faux : Éphèse II (449) fait partie des trois conciles des coptes.", "promptLanguage": "fr", "answer": "Faux", "acceptedAnswers": ["Faux"], "explanation": "Les trois sont Nicée, Constantinople, Éphèse (431).", "instruction": "Choisis la bonne réponse.", "options": ["Vrai", "Faux"], "pool": "lesson", "lessonId": "eg.l613", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
