insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l701.e02', 'eg', 'eg.l701', 'eg.g701.quatre_familles', array['eg.g701.quatre_familles','eg.v.c05_concile_chalcedoine']::text[], 'mcq', 'lesson', 'Quel concile les orthodoxes orientaux n''ont-ils pas reçu ?', array['Chalcédoine']::text[], 'Chalcédoine, en 451, est le point de rupture. Nicée et Éphèse, nous les recevons.', 1, '{"id": "eg.l701.e02", "unitIds": ["eg.g701.quatre_familles", "eg.v.c05_concile_chalcedoine"], "type": "mcq", "difficulty": 1, "prompt": "Quel concile les orthodoxes orientaux n''ont-ils pas reçu ?", "promptLanguage": "fr", "answer": "Chalcédoine", "acceptedAnswers": ["Chalcédoine"], "explanation": "Chalcédoine, en 451, est le point de rupture. Nicée et Éphèse, nous les recevons.", "instruction": "Choisis la bonne réponse.", "step": 2, "options": ["Nicée", "Chalcédoine", "Éphèse"], "pool": "lesson", "lessonId": "eg.l701", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
