insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l701.e05', 'eg', 'eg.l701', 'eg.g701.quatre_familles', array['eg.g701.quatre_familles','eg.v.c07_patriarcat_grec']::text[], 'mcq', 'lesson', 'Vrai ou faux : en Égypte, il existe un patriarche grec d''Alexandrie distinct de notre pape.', array['Vrai']::text[], 'Deux Églises, deux patriarches : le pape copte et le patriarche grec orthodoxe.', 1, '{"id": "eg.l701.e05", "unitIds": ["eg.g701.quatre_familles", "eg.v.c07_patriarcat_grec"], "type": "mcq", "difficulty": 1, "prompt": "Vrai ou faux : en Égypte, il existe un patriarche grec d''Alexandrie distinct de notre pape.", "promptLanguage": "fr", "answer": "Vrai", "acceptedAnswers": ["Vrai"], "explanation": "Deux Églises, deux patriarches : le pape copte et le patriarche grec orthodoxe.", "instruction": "Choisis la bonne réponse.", "step": 3, "options": ["Vrai", "Faux"], "pool": "lesson", "lessonId": "eg.l701", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
