insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l701.e07', 'eg', 'eg.l701', 'eg.g701.quatre_familles', array['eg.g701.quatre_familles','eg.v.c07_protestantisme']::text[], 'fill_blank', 'lesson', 'Les protestants naissent de la ___ du XVIe siècle.', array['Réforme']::text[], 'La Réforme commence en 1517 avec Luther.', 1, '{"id": "eg.l701.e07", "unitIds": ["eg.g701.quatre_familles", "eg.v.c07_protestantisme"], "type": "fill_blank", "difficulty": 1, "prompt": "Les protestants naissent de la ___ du XVIe siècle.", "promptLanguage": "fr", "answer": "Réforme", "acceptedAnswers": ["Réforme"], "explanation": "La Réforme commence en 1517 avec Luther.", "instruction": "Complète la phrase.", "step": 5, "options": ["Pentecôte", "Persécution", "Réforme"], "pool": "lesson", "lessonId": "eg.l701", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l701.e08', 'eg', 'eg.l701', 'eg.g701.quatre_familles', array['eg.g701.quatre_familles','eg.v.c07_protestantisme']::text[], 'mcq', 'lesson', 'Quel est le principe des protestants ?', array['La Bible seule suffit']::text[], 'C''est le point qui les distingue des autres familles.', 1, '{"id": "eg.l701.e08", "unitIds": ["eg.g701.quatre_familles", "eg.v.c07_protestantisme"], "type": "mcq", "difficulty": 1, "prompt": "Quel est le principe des protestants ?", "promptLanguage": "fr", "answer": "La Bible seule suffit", "acceptedAnswers": ["La Bible seule suffit"], "explanation": "C''est le point qui les distingue des autres familles.", "instruction": "Choisis la bonne réponse.", "step": 5, "options": ["La Bible seule suffit", "Le pape ne se trompe pas", "Il faut sept conciles"], "pool": "lesson", "lessonId": "eg.l701", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l701.e09', 'eg', 'eg.l701', 'eg.g701.quatre_familles', array['eg.g701.quatre_familles']::text[], 'mcq', 'lesson', 'Pour un copte, que répondent les trois questions : Chalcédoine ? pape ? Bible seule ?', array['non, non, non']::text[], 'Nous ne recevons pas Chalcédoine, nous n''avons pas le pape de Rome, et nous gardons l''Écriture et la Tradition.', 1, '{"id": "eg.l701.e09", "unitIds": ["eg.g701.quatre_familles"], "type": "mcq", "difficulty": 1, "prompt": "Pour un copte, que répondent les trois questions : Chalcédoine ? pape ? Bible seule ?", "promptLanguage": "fr", "answer": "non, non, non", "acceptedAnswers": ["non, non, non"], "explanation": "Nous ne recevons pas Chalcédoine, nous n''avons pas le pape de Rome, et nous gardons l''Écriture et la Tradition.", "instruction": "Choisis la bonne réponse.", "step": 6, "options": ["oui, oui, non", "non, non, non", "oui, non, oui"], "pool": "lesson", "lessonId": "eg.l701", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l701.e10', 'eg', 'eg.l701', 'eg.g701.quatre_familles', array['eg.g701.quatre_familles','eg.v.c07_orthodoxes_byzantins','eg.v.c07_eglise_catholique','eg.v.c07_protestantisme']::text[], 'match', 'lesson', 'Chaque famille a son trait.', '{}'::text[], 'Un trait par famille, c''est assez pour s''y retrouver.', 2, '{"id": "eg.l701.e10", "unitIds": ["eg.g701.quatre_familles", "eg.v.c07_orthodoxes_byzantins", "eg.v.c07_eglise_catholique", "eg.v.c07_protestantisme"], "type": "match", "difficulty": 2, "prompt": "Chaque famille a son trait.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Un trait par famille, c''est assez pour s''y retrouver.", "instruction": "Associe.", "pairs": [{"left": "orthodoxes orientaux", "right": "n''ont pas reçu Chalcédoine"}, {"left": "orthodoxes byzantins", "right": "reçoivent sept conciles"}, {"left": "catholiques", "right": "ont le pape pour chef"}, {"left": "protestants", "right": "la Bible seule suffit"}], "pool": "lesson", "lessonId": "eg.l701", "skill": "recognition", "answer": "orthodoxes orientaux = n''ont pas reçu Chalcédoine ; orthodoxes byzantins = reçoivent sept conciles ; catholiques = ont le pape pour chef ; protestants = la Bible seule suffit"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l701.e11', 'eg', 'eg.l701', 'eg.v.c05_concile_chalcedoine', array['eg.v.c05_concile_chalcedoine']::text[], 'mcq', 'lesson', 'Le concile que nos Églises n''ont pas reçu date de quelle année ?', array['451']::text[], '451 : c''est le concile que nos Églises n''ont pas reçu.', 2, '{"id": "eg.l701.e11", "unitIds": ["eg.v.c05_concile_chalcedoine"], "type": "mcq", "difficulty": 2, "prompt": "Le concile que nos Églises n''ont pas reçu date de quelle année ?", "promptLanguage": "fr", "answer": "451", "acceptedAnswers": ["451"], "explanation": "451 : c''est le concile que nos Églises n''ont pas reçu.", "instruction": "Choisis la bonne réponse.", "options": ["381", "431", "451"], "pool": "lesson", "lessonId": "eg.l701", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l701.e12', 'eg', 'eg.l701', 'eg.g701.quatre_familles', array['eg.g701.quatre_familles']::text[], 'mcq', 'lesson', 'Marc te demande : « Tu es catholique ? » Quelle est la meilleure réponse à lui donner ?', array['Non, je suis copte, des Églises orthodoxes orientales : sans pape de Rome']::text[], 'Une réponse simple, juste et sans reproche : on dit qui on est, sans critiquer l''autre.', 3, '{"id": "eg.l701.e12", "unitIds": ["eg.g701.quatre_familles"], "type": "mcq", "difficulty": 3, "prompt": "Marc te demande : « Tu es catholique ? » Quelle est la meilleure réponse à lui donner ?", "promptLanguage": "fr", "answer": "Non, je suis copte, des Églises orthodoxes orientales : sans pape de Rome", "acceptedAnswers": ["Non, je suis copte, des Églises orthodoxes orientales : sans pape de Rome"], "explanation": "Une réponse simple, juste et sans reproche : on dit qui on est, sans critiquer l''autre.", "instruction": "Choisis la bonne réponse.", "options": ["Non, je suis copte, des Églises orthodoxes orientales : sans pape de Rome", "Oui, tous les chrétiens sont catholiques, donc c''est exactement pareil", "Oui, mais nous parlons une autre langue que vous à l''église"], "pool": "lesson", "lessonId": "eg.l701", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l701.e13', 'eg', 'eg.l701', 'eg.g701.quatre_familles', array['eg.g701.quatre_familles','eg.v.c07_orthodoxes_byzantins']::text[], 'mcq', 'lesson', 'Eleni et toi ne suivez pas le pape de Rome. Qu''est-ce qui vous distingue pourtant ?', array['Elle reçoit Chalcédoine, toi non']::text[], 'Deux familles orthodoxes, deux réponses à la question de Chalcédoine.', 3, '{"id": "eg.l701.e13", "unitIds": ["eg.g701.quatre_familles", "eg.v.c07_orthodoxes_byzantins"], "type": "mcq", "difficulty": 3, "prompt": "Eleni et toi ne suivez pas le pape de Rome. Qu''est-ce qui vous distingue pourtant ?", "promptLanguage": "fr", "answer": "Elle reçoit Chalcédoine, toi non", "acceptedAnswers": ["Elle reçoit Chalcédoine, toi non"], "explanation": "Deux familles orthodoxes, deux réponses à la question de Chalcédoine.", "instruction": "Choisis la bonne réponse.", "options": ["Elle reconnaît le pape, toi non", "Elle reçoit Chalcédoine, toi non", "Elle n''accepte que la Bible seule"], "pool": "lesson", "lessonId": "eg.l701", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l702.e01', 'eg', 'eg.l702', 'eg.g702.chalcedoine_deux_formules', array['eg.g702.chalcedoine_deux_formules','eg.v.c05_nestorius']::text[], 'mcq', 'lesson', 'Qui divise le Christ, selon vos deux Églises ?', array['Nestorius']::text[], 'Nestorius sépare le Christ en deux. Eutychès, lui, mélange les natures.', 1, '{"id": "eg.l702.e01", "unitIds": ["eg.g702.chalcedoine_deux_formules", "eg.v.c05_nestorius"], "type": "mcq", "difficulty": 1, "prompt": "Qui divise le Christ, selon vos deux Églises ?", "promptLanguage": "fr", "answer": "Nestorius", "acceptedAnswers": ["Nestorius"], "explanation": "Nestorius sépare le Christ en deux. Eutychès, lui, mélange les natures.", "instruction": "Choisis la bonne réponse.", "step": 1, "options": ["Eutychès", "Arius", "Nestorius"], "pool": "lesson", "lessonId": "eg.l702", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l702.e02', 'eg', 'eg.l702', 'eg.g702.chalcedoine_deux_formules', array['eg.g702.chalcedoine_deux_formules','eg.v.c05_concile_chalcedoine']::text[], 'mcq', 'lesson', 'En quelle année a lieu le concile de Chalcédoine ?', array['451']::text[], '451 : Chalcédoine, que l''Église copte n''a pas reçu.', 1, '{"id": "eg.l702.e02", "unitIds": ["eg.g702.chalcedoine_deux_formules", "eg.v.c05_concile_chalcedoine"], "type": "mcq", "difficulty": 1, "prompt": "En quelle année a lieu le concile de Chalcédoine ?", "promptLanguage": "fr", "answer": "451", "acceptedAnswers": ["451"], "explanation": "451 : Chalcédoine, que l''Église copte n''a pas reçu.", "instruction": "Choisis la bonne réponse.", "step": 2, "options": ["451", "33", "1054"], "pool": "lesson", "lessonId": "eg.l702", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l702.e03', 'eg', 'eg.l702', 'eg.g702.chalcedoine_deux_formules', array['eg.g702.chalcedoine_deux_formules','eg.v.c05_tome_de_leon']::text[], 'mcq', 'lesson', 'Quelle lettre le concile de Chalcédoine reçoit-il ?', array['le Tome de Léon']::text[], 'Le Tome de Léon, lettre du pape de Rome sur les deux natures.', 1, '{"id": "eg.l702.e03", "unitIds": ["eg.g702.chalcedoine_deux_formules", "eg.v.c05_tome_de_leon"], "type": "mcq", "difficulty": 1, "prompt": "Quelle lettre le concile de Chalcédoine reçoit-il ?", "promptLanguage": "fr", "answer": "le Tome de Léon", "acceptedAnswers": ["le Tome de Léon"], "explanation": "Le Tome de Léon, lettre du pape de Rome sur les deux natures.", "instruction": "Choisis la bonne réponse.", "step": 2, "options": ["la lettre de Cyrille à Nestorius", "le Tome de Léon", "le Credo de Nicée"], "pool": "lesson", "lessonId": "eg.l702", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l702.e04', 'eg', 'eg.l702', 'eg.g702.chalcedoine_deux_formules', array['eg.g702.chalcedoine_deux_formules','eg.v.c07_de_deux_natures']::text[], 'mcq', 'lesson', 'Pourquoi Alexandrie se méfie-t-elle de « en deux natures » ?', array['Elle craint de diviser le Christ']::text[], 'Pour elle, deux natures « après l''union » rappellent Nestorius.', 1, '{"id": "eg.l702.e04", "unitIds": ["eg.g702.chalcedoine_deux_formules", "eg.v.c07_de_deux_natures"], "type": "mcq", "difficulty": 1, "prompt": "Pourquoi Alexandrie se méfie-t-elle de « en deux natures » ?", "promptLanguage": "fr", "answer": "Elle craint de diviser le Christ", "acceptedAnswers": ["Elle craint de diviser le Christ"], "explanation": "Pour elle, deux natures « après l''union » rappellent Nestorius.", "instruction": "Choisis la bonne réponse.", "step": 3, "options": ["Elle refuse la divinité du Christ", "Elle veut changer le Credo", "Elle craint de diviser le Christ"], "pool": "lesson", "lessonId": "eg.l702", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l702.e05', 'eg', 'eg.l702', 'eg.g702.chalcedoine_deux_formules', array['eg.g702.chalcedoine_deux_formules','eg.v.c07_de_deux_natures']::text[], 'fill_blank', 'lesson', 'Alexandrie préfère dire que le Christ est « ___ deux natures ».', array['de']::text[], '« De deux natures » : le Christ vient de deux natures, unies en un seul.', 1, '{"id": "eg.l702.e05", "unitIds": ["eg.g702.chalcedoine_deux_formules", "eg.v.c07_de_deux_natures"], "type": "fill_blank", "difficulty": 1, "prompt": "Alexandrie préfère dire que le Christ est « ___ deux natures ».", "promptLanguage": "fr", "answer": "de", "acceptedAnswers": ["de"], "explanation": "« De deux natures » : le Christ vient de deux natures, unies en un seul.", "instruction": "Complète la phrase.", "step": 3, "options": ["de", "en", "sans"], "pool": "lesson", "lessonId": "eg.l702", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l702.e06', 'eg', 'eg.l702', 'eg.g702.chalcedoine_deux_formules', array['eg.g702.chalcedoine_deux_formules','eg.v.c05_monophysisme']::text[], 'fill_blank', 'lesson', 'Eutychès ___ l''humanité du Christ dans sa divinité.', array['absorbait']::text[], 'Il mélangeait : c''est le monophysisme, condamné aussi par l''Église copte.', 1, '{"id": "eg.l702.e06", "unitIds": ["eg.g702.chalcedoine_deux_formules", "eg.v.c05_monophysisme"], "type": "fill_blank", "difficulty": 1, "prompt": "Eutychès ___ l''humanité du Christ dans sa divinité.", "promptLanguage": "fr", "answer": "absorbait", "acceptedAnswers": ["absorbait"], "explanation": "Il mélangeait : c''est le monophysisme, condamné aussi par l''Église copte.", "instruction": "Complète la phrase.", "step": 4, "options": ["vénérait", "absorbait", "défendait"], "pool": "lesson", "lessonId": "eg.l702", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l702.e07', 'eg', 'eg.l702', 'eg.g702.chalcedoine_deux_formules', array['eg.g702.chalcedoine_deux_formules','eg.v.c07_sept_conciles']::text[], 'mcq', 'lesson', 'Combien de conciles l''Église copte reçoit-elle ?', array['trois']::text[], 'Nicée, Constantinople et Éphèse. Les byzantins en reçoivent sept.', 1, '{"id": "eg.l702.e07", "unitIds": ["eg.g702.chalcedoine_deux_formules", "eg.v.c07_sept_conciles"], "type": "mcq", "difficulty": 1, "prompt": "Combien de conciles l''Église copte reçoit-elle ?", "promptLanguage": "fr", "answer": "trois", "acceptedAnswers": ["trois"], "explanation": "Nicée, Constantinople et Éphèse. Les byzantins en reçoivent sept.", "instruction": "Choisis la bonne réponse.", "step": 5, "options": ["deux", "sept", "trois"], "pool": "lesson", "lessonId": "eg.l702", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l702.e08', 'eg', 'eg.l702', 'eg.g702.chalcedoine_deux_formules', array['eg.g702.chalcedoine_deux_formules','eg.v.c07_sept_conciles']::text[], 'mcq', 'lesson', 'Quel concile de 787 défend les icônes ?', array['Nicée II']::text[], 'Nicée II est le septième concile des orthodoxes byzantins.', 1, '{"id": "eg.l702.e08", "unitIds": ["eg.g702.chalcedoine_deux_formules", "eg.v.c07_sept_conciles"], "type": "mcq", "difficulty": 1, "prompt": "Quel concile de 787 défend les icônes ?", "promptLanguage": "fr", "answer": "Nicée II", "acceptedAnswers": ["Nicée II"], "explanation": "Nicée II est le septième concile des orthodoxes byzantins.", "instruction": "Choisis la bonne réponse.", "step": 5, "options": ["Nicée II", "Éphèse", "Chalcédoine"], "pool": "lesson", "lessonId": "eg.l702", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l702.e09', 'eg', 'eg.l702', 'eg.g702.chalcedoine_deux_formules', array['eg.g702.chalcedoine_deux_formules','eg.v.c05_accord_de_1989']::text[], 'mcq', 'lesson', 'Que constatent les théologiens en 1989 ?', array['Ils confessent la même foi']::text[], 'Même foi, mots différents. Le dialogue continue.', 1, '{"id": "eg.l702.e09", "unitIds": ["eg.g702.chalcedoine_deux_formules", "eg.v.c05_accord_de_1989"], "type": "mcq", "difficulty": 1, "prompt": "Que constatent les théologiens en 1989 ?", "promptLanguage": "fr", "answer": "Ils confessent la même foi", "acceptedAnswers": ["Ils confessent la même foi"], "explanation": "Même foi, mots différents. Le dialogue continue.", "instruction": "Choisis la bonne réponse.", "step": 6, "options": ["Ils fusionnent les deux Églises", "Ils confessent la même foi", "Ils ne se comprennent plus"], "pool": "lesson", "lessonId": "eg.l702", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l702.e10', 'eg', 'eg.l702', 'eg.g702.chalcedoine_deux_formules', array['eg.g702.chalcedoine_deux_formules','eg.v.c05_formule_de_cyrille']::text[], 'match', 'lesson', 'Chaque formule, son auteur ou son erreur.', '{}'::text[], 'Deux formules orthodoxes, deux erreurs que tout le monde condamne.', 2, '{"id": "eg.l702.e10", "unitIds": ["eg.g702.chalcedoine_deux_formules", "eg.v.c05_formule_de_cyrille"], "type": "match", "difficulty": 2, "prompt": "Chaque formule, son auteur ou son erreur.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Deux formules orthodoxes, deux erreurs que tout le monde condamne.", "instruction": "Associe.", "pairs": [{"left": "« en deux natures »", "right": "formule de Chalcédoine"}, {"left": "« une seule nature du Verbe incarné »", "right": "formule de saint Cyrille"}, {"left": "Eutychès", "right": "absorbe l''humanité du Christ"}, {"left": "Nestorius", "right": "divise le Christ"}], "pool": "lesson", "lessonId": "eg.l702", "skill": "recognition", "answer": "« en deux natures » = formule de Chalcédoine ; « une seule nature du Verbe incarné » = formule de saint Cyrille ; Eutychès = absorbe l''humanité du Christ ; Nestorius = divise le Christ"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l702.e11', 'eg', 'eg.l702', 'eg.v.c05_trois_premiers_conciles', array['eg.v.c05_trois_premiers_conciles']::text[], 'reorder', 'lesson', 'Remets les quatre conciles dans l''ordre.', array['Nicée Constantinople Éphèse Chalcédoine']::text[], '325, 381, 431, 451 : trois conciles que nous recevons, puis Chalcédoine.', 2, '{"id": "eg.l702.e11", "unitIds": ["eg.v.c05_trois_premiers_conciles"], "type": "reorder", "difficulty": 2, "prompt": "Remets les quatre conciles dans l''ordre.", "promptLanguage": "fr", "answer": "Nicée Constantinople Éphèse Chalcédoine", "acceptedAnswers": ["Nicée Constantinople Éphèse Chalcédoine"], "explanation": "325, 381, 431, 451 : trois conciles que nous recevons, puis Chalcédoine.", "instruction": "Remets dans l''ordre.", "tokens": ["Éphèse", "Chalcédoine", "Nicée", "Constantinople"], "pool": "lesson", "lessonId": "eg.l702", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l702.e12', 'eg', 'eg.l702', 'eg.v.c05_dioscore', array['eg.v.c05_dioscore']::text[], 'mcq', 'lesson', 'Quel pape d''Alexandrie, mort en exil à Gangra en 454, les Coptes vénèrent-ils comme confesseur ?', array['Dioscore']::text[], 'Dioscore refuse Chalcédoine et reste fidèle à son maître Cyrille.', 2, '{"id": "eg.l702.e12", "unitIds": ["eg.v.c05_dioscore"], "type": "mcq", "difficulty": 2, "prompt": "Quel pape d''Alexandrie, mort en exil à Gangra en 454, les Coptes vénèrent-ils comme confesseur ?", "promptLanguage": "fr", "answer": "Dioscore", "acceptedAnswers": ["Dioscore"], "explanation": "Dioscore refuse Chalcédoine et reste fidèle à son maître Cyrille.", "instruction": "Choisis la bonne réponse.", "options": ["Cyrille", "Athanase", "Dioscore"], "pool": "lesson", "lessonId": "eg.l702", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l702.e13', 'eg', 'eg.l702', 'eg.g702.chalcedoine_deux_formules', array['eg.g702.chalcedoine_deux_formules']::text[], 'mcq', 'lesson', 'Eleni dit « deux natures », toi « une nature unie ». Que peux-tu lui répondre ?', array['Nous disons le même Christ avec d''autres mots']::text[], 'Depuis 1989, nos Églises constatent la même christologie : on le dit avec douceur, sans accuser.', 3, '{"id": "eg.l702.e13", "unitIds": ["eg.g702.chalcedoine_deux_formules"], "type": "mcq", "difficulty": 3, "prompt": "Eleni dit « deux natures », toi « une nature unie ». Que peux-tu lui répondre ?", "promptLanguage": "fr", "answer": "Nous disons le même Christ avec d''autres mots", "acceptedAnswers": ["Nous disons le même Christ avec d''autres mots"], "explanation": "Depuis 1989, nos Églises constatent la même christologie : on le dit avec douceur, sans accuser.", "instruction": "Choisis la bonne réponse.", "options": ["Nous disons le même Christ avec d''autres mots", "Nous croyons en deux Christs bien différents l''un de l''autre", "Votre foi est celle de Nestorius, que nous condamnons tous"], "pool": "lesson", "lessonId": "eg.l702", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l702.e14', 'eg', 'eg.l702', 'eg.g702.chalcedoine_deux_formules', array['eg.g702.chalcedoine_deux_formules','eg.v.c05_christologie']::text[], 'mcq', 'lesson', 'Pourquoi dit-on que le désaccord est « en grande partie verbal » ?', array['Les deux familles confessent le même Christ avec des mots différents']::text[], 'Le sens est commun ; ce qui reste à régler, c''est surtout la réception des conciles.', 3, '{"id": "eg.l702.e14", "unitIds": ["eg.g702.chalcedoine_deux_formules", "eg.v.c05_christologie"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi dit-on que le désaccord est « en grande partie verbal » ?", "promptLanguage": "fr", "answer": "Les deux familles confessent le même Christ avec des mots différents", "acceptedAnswers": ["Les deux familles confessent le même Christ avec des mots différents"], "explanation": "Le sens est commun ; ce qui reste à régler, c''est surtout la réception des conciles.", "instruction": "Choisis la bonne réponse.", "options": ["Il n''a jamais existé de vrai désaccord entre les deux familles", "Les deux familles confessent le même Christ avec des mots différents", "Les deux familles ont fini par adopter la même formule"], "pool": "lesson", "lessonId": "eg.l702", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
