insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l703.e10', 'eg', 'eg.l703', 'eg.g703.pape_primaute', array['eg.g703.pape_primaute','eg.v.c07_primaute','eg.v.c07_infaillibilite','eg.v.c07_vatican_i']::text[], 'match', 'lesson', 'Chaque mot et son sens.', '{}'::text[], 'Quatre mots pour comprendre la question de Marc.', 2, '{"id": "eg.l703.e10", "unitIds": ["eg.g703.pape_primaute", "eg.v.c07_primaute", "eg.v.c07_infaillibilite", "eg.v.c07_vatican_i"], "type": "match", "difficulty": 2, "prompt": "Chaque mot et son sens.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Quatre mots pour comprendre la question de Marc.", "instruction": "Associe.", "pairs": [{"left": "primauté", "right": "autorité du pape sur toute l''Église"}, {"left": "ex cathedra", "right": "enseignement solennel du pape"}, {"left": "Vatican I", "right": "concile de 1870"}, {"left": "concile", "right": "où les Coptes règlent les grandes questions"}], "pool": "lesson", "lessonId": "eg.l703", "skill": "recognition", "answer": "primauté = autorité du pape sur toute l''Église ; ex cathedra = enseignement solennel du pape ; Vatican I = concile de 1870 ; concile = où les Coptes règlent les grandes questions"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l703.e11', 'eg', 'eg.l703', 'eg.v.c03_heraclas', array['eg.v.c03_heraclas']::text[], 'mcq', 'lesson', 'Quel évêque d''Alexandrie est le premier appelé pape ?', array['Héraclas']::text[], 'Héraclas, 13e évêque d''Alexandrie, au IIIe siècle.', 2, '{"id": "eg.l703.e11", "unitIds": ["eg.v.c03_heraclas"], "type": "mcq", "difficulty": 2, "prompt": "Quel évêque d''Alexandrie est le premier appelé pape ?", "promptLanguage": "fr", "answer": "Héraclas", "acceptedAnswers": ["Héraclas"], "explanation": "Héraclas, 13e évêque d''Alexandrie, au IIIe siècle.", "instruction": "Choisis la bonne réponse.", "options": ["Athanase", "Héraclas", "Cyrille"], "pool": "lesson", "lessonId": "eg.l703", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l703.e12', 'eg', 'eg.l703', 'eg.v.c01_succession_apostolique', array['eg.v.c01_succession_apostolique']::text[], 'fill_blank', 'lesson', 'Pour les Coptes, tous les évêques sont ___ des apôtres.', array['successeurs']::text[], 'C''est la succession apostolique : une chaîne d''évêques jusqu''aux apôtres.', 2, '{"id": "eg.l703.e12", "unitIds": ["eg.v.c01_succession_apostolique"], "type": "fill_blank", "difficulty": 2, "prompt": "Pour les Coptes, tous les évêques sont ___ des apôtres.", "promptLanguage": "fr", "answer": "successeurs", "acceptedAnswers": ["successeurs"], "explanation": "C''est la succession apostolique : une chaîne d''évêques jusqu''aux apôtres.", "instruction": "Complète la phrase.", "options": ["disciples", "voisins", "successeurs"], "pool": "lesson", "lessonId": "eg.l703", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l703.e13', 'eg', 'eg.l703', 'eg.g703.pape_primaute', array['eg.g703.pape_primaute']::text[], 'mcq', 'lesson', 'Marc dit : « Le pape ne peut jamais se tromper ! » Quelle est la réponse la plus juste et la plus calme ?', array['Je sais : seulement quand il enseigne solennellement ; chez nous, on décide en concile']::text[], 'On reprend ce que croit Marc avec exactitude, puis on dit simplement ce que nous croyons.', 3, '{"id": "eg.l703.e13", "unitIds": ["eg.g703.pape_primaute"], "type": "mcq", "difficulty": 3, "prompt": "Marc dit : « Le pape ne peut jamais se tromper ! » Quelle est la réponse la plus juste et la plus calme ?", "promptLanguage": "fr", "answer": "Je sais : seulement quand il enseigne solennellement ; chez nous, on décide en concile", "acceptedAnswers": ["Je sais : seulement quand il enseigne solennellement ; chez nous, on décide en concile"], "explanation": "On reprend ce que croit Marc avec exactitude, puis on dit simplement ce que nous croyons.", "instruction": "Choisis la bonne réponse.", "options": ["Je sais : seulement quand il enseigne solennellement ; chez nous, on décide en concile", "Vous avez inventé le pape en 1870, c''est une erreur historique", "Le pape n''est qu''un homme, donc il n''a aucune autorité à Rome"], "pool": "lesson", "lessonId": "eg.l703", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l703.e14', 'eg', 'eg.l703', 'eg.g703.pape_primaute', array['eg.g703.pape_primaute']::text[], 'mcq', 'lesson', 'Pourquoi un copte peut-il honorer Rome sans suivre le pape comme chef ?', array['Pour lui, le Christ seul est le chef, et les évêques décident ensemble']::text[], 'L''honneur n''est pas l''autorité : c''est la différence entre primauté d''honneur et primauté de pouvoir.', 3, '{"id": "eg.l703.e14", "unitIds": ["eg.g703.pape_primaute"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi un copte peut-il honorer Rome sans suivre le pape comme chef ?", "promptLanguage": "fr", "answer": "Pour lui, le Christ seul est le chef, et les évêques décident ensemble", "acceptedAnswers": ["Pour lui, le Christ seul est le chef, et les évêques décident ensemble"], "explanation": "L''honneur n''est pas l''autorité : c''est la différence entre primauté d''honneur et primauté de pouvoir.", "instruction": "Choisis la bonne réponse.", "options": ["Parce qu''il ne croit pas aux évêques ni à leur ordination", "Pour lui, le Christ seul est le chef, et les évêques décident ensemble", "Parce que Rome n''a jamais eu d''évêque depuis les apôtres"], "pool": "lesson", "lessonId": "eg.l703", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
