insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l704.e11', 'eg', 'eg.l704', 'eg.g704.filioque_1054', array['eg.g704.filioque_1054','eg.v.c07_filioque','eg.v.c07_schisme_1054','eg.v.c07_declaration_1973']::text[], 'match', 'lesson', 'Les dates de l''histoire du Credo.', '{}'::text[], 'Quatre repères pour suivre l''histoire du Credo.', 2, '{"id": "eg.l704.e11", "unitIds": ["eg.g704.filioque_1054", "eg.v.c07_filioque", "eg.v.c07_schisme_1054", "eg.v.c07_declaration_1973"], "type": "match", "difficulty": 2, "prompt": "Les dates de l''histoire du Credo.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Quatre repères pour suivre l''histoire du Credo.", "instruction": "Associe.", "pairs": [{"left": "381", "right": "le Credo de Nicée-Constantinople"}, {"left": "589", "right": "le Filioque à Tolède"}, {"left": "1054", "right": "Rome et Constantinople se séparent"}, {"left": "1973", "right": "déclaration de Chenouda III et Paul VI"}], "pool": "lesson", "lessonId": "eg.l704", "skill": "recognition", "answer": "381 = le Credo de Nicée-Constantinople ; 589 = le Filioque à Tolède ; 1054 = Rome et Constantinople se séparent ; 1973 = déclaration de Chenouda III et Paul VI"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l704.e12', 'eg', 'eg.l704', 'eg.v.c05_credo_intouchable', array['eg.v.c05_credo_intouchable']::text[], 'fill_blank', 'lesson', 'À Éphèse, on interdit de composer un autre ___ que celui de Nicée.', array['credo']::text[], 'C''est la règle d''Éphèse : le credo ne se change plus. Elle éclaire notre réponse sur le Filioque.', 2, '{"id": "eg.l704.e12", "unitIds": ["eg.v.c05_credo_intouchable"], "type": "fill_blank", "difficulty": 2, "prompt": "À Éphèse, on interdit de composer un autre ___ que celui de Nicée.", "promptLanguage": "fr", "answer": "credo", "acceptedAnswers": ["credo"], "explanation": "C''est la règle d''Éphèse : le credo ne se change plus. Elle éclaire notre réponse sur le Filioque.", "instruction": "Complète la phrase.", "options": ["calendrier", "évangile", "credo"], "pool": "lesson", "lessonId": "eg.l704", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l704.e13', 'eg', 'eg.l704', 'eg.g704.filioque_1054', array['eg.g704.filioque_1054','eg.v.c07_filioque']::text[], 'mcq', 'lesson', 'Marc demande : « Pourquoi vous ne dites pas “et du Fils” ? » Quelle réponse est la plus juste ?', array['Nous gardons le texte de 381 : le modifier demande un concile, et le Père est l''unique source']::text[], 'On ne reproche rien à Marc : on dit pourquoi nous gardons le texte tel qu''il est.', 3, '{"id": "eg.l704.e13", "unitIds": ["eg.g704.filioque_1054", "eg.v.c07_filioque"], "type": "mcq", "difficulty": 3, "prompt": "Marc demande : « Pourquoi vous ne dites pas “et du Fils” ? » Quelle réponse est la plus juste ?", "promptLanguage": "fr", "answer": "Nous gardons le texte de 381 : le modifier demande un concile, et le Père est l''unique source", "acceptedAnswers": ["Nous gardons le texte de 381 : le modifier demande un concile, et le Père est l''unique source"], "explanation": "On ne reproche rien à Marc : on dit pourquoi nous gardons le texte tel qu''il est.", "instruction": "Choisis la bonne réponse.", "options": ["Nous gardons le texte de 381 : le modifier demande un concile, et le Père est l''unique source", "Parce que nous ne croyons pas au Saint-Esprit comme les catholiques", "Parce que notre Credo est plus ancien que celui de Nicée et de 381"], "pool": "lesson", "lessonId": "eg.l704", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l704.e14', 'eg', 'eg.l704', 'eg.g704.filioque_1054', array['eg.g704.filioque_1054','eg.v.c07_schisme_1054']::text[], 'mcq', 'lesson', 'Pourquoi le schisme de 1054 ne sépare-t-il pas Rome des Coptes ?', array['Il oppose Rome et Constantinople ; notre séparation date de 451']::text[], 'Deux ruptures, deux dates : 451 pour nous, 1054 pour les byzantins.', 3, '{"id": "eg.l704.e14", "unitIds": ["eg.g704.filioque_1054", "eg.v.c07_schisme_1054"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi le schisme de 1054 ne sépare-t-il pas Rome des Coptes ?", "promptLanguage": "fr", "answer": "Il oppose Rome et Constantinople ; notre séparation date de 451", "acceptedAnswers": ["Il oppose Rome et Constantinople ; notre séparation date de 451"], "explanation": "Deux ruptures, deux dates : 451 pour nous, 1054 pour les byzantins.", "instruction": "Choisis la bonne réponse.", "options": ["Les Coptes ont signé la bulle d''excommunication de 1054 avec Rome", "Il oppose Rome et Constantinople ; notre séparation date de 451", "Les Coptes n''étaient pas encore chrétiens à l''époque de 1054"], "pool": "lesson", "lessonId": "eg.l704", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
