insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l705.e08', 'eg', 'eg.l705', 'eg.g705.marie_purgatoire', array['eg.g705.marie_purgatoire','eg.v.c07_purgatoire']::text[], 'mcq', 'lesson', 'Quelle Église n''enseigne pas le purgatoire ?', array['l''Église copte']::text[], 'Nous ne l''enseignons pas, mais nous prions pour les défunts.', 1, '{"id": "eg.l705.e08", "unitIds": ["eg.g705.marie_purgatoire", "eg.v.c07_purgatoire"], "type": "mcq", "difficulty": 1, "prompt": "Quelle Église n''enseigne pas le purgatoire ?", "promptLanguage": "fr", "answer": "l''Église copte", "acceptedAnswers": ["l''Église copte"], "explanation": "Nous ne l''enseignons pas, mais nous prions pour les défunts.", "instruction": "Choisis la bonne réponse.", "step": 4, "options": ["l''Église catholique", "l''Église latine", "l''Église copte"], "pool": "lesson", "lessonId": "eg.l705", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l705.e09', 'eg', 'eg.l705', 'eg.g705.marie_purgatoire', array['eg.g705.marie_purgatoire','eg.v.c07_prieres_defunts']::text[], 'mcq', 'lesson', 'À quels jours prie-t-on pour les défunts ?', array['aux 3e, 7e et 40e jours']::text[], 'Trois rendez-vous de prière pour confier le défunt à Dieu.', 1, '{"id": "eg.l705.e09", "unitIds": ["eg.g705.marie_purgatoire", "eg.v.c07_prieres_defunts"], "type": "mcq", "difficulty": 1, "prompt": "À quels jours prie-t-on pour les défunts ?", "promptLanguage": "fr", "answer": "aux 3e, 7e et 40e jours", "acceptedAnswers": ["aux 3e, 7e et 40e jours"], "explanation": "Trois rendez-vous de prière pour confier le défunt à Dieu.", "instruction": "Choisis la bonne réponse.", "step": 5, "options": ["aux 3e, 7e et 40e jours", "au 1er et au 10e jour", "aux 12e et 100e jours"], "pool": "lesson", "lessonId": "eg.l705", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l705.e10', 'eg', 'eg.l705', 'eg.g705.marie_purgatoire', array['eg.g705.marie_purgatoire','eg.v.c07_prieres_defunts']::text[], 'mcq', 'lesson', 'Qui juge les défunts, pour les Coptes ?', array['Dieu seul']::text[], 'Nous prions, et nous laissons le jugement à Dieu.', 1, '{"id": "eg.l705.e10", "unitIds": ["eg.g705.marie_purgatoire", "eg.v.c07_prieres_defunts"], "type": "mcq", "difficulty": 1, "prompt": "Qui juge les défunts, pour les Coptes ?", "promptLanguage": "fr", "answer": "Dieu seul", "acceptedAnswers": ["Dieu seul"], "explanation": "Nous prions, et nous laissons le jugement à Dieu.", "instruction": "Choisis la bonne réponse.", "step": 5, "options": ["le pape", "Dieu seul", "les saints"], "pool": "lesson", "lessonId": "eg.l705", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l705.e11', 'eg', 'eg.l705', 'eg.g705.marie_purgatoire', array['eg.g705.marie_purgatoire','eg.v.c07_immaculee_conception','eg.v.c07_purgatoire']::text[], 'match', 'lesson', 'Chaque date ou verset, sa doctrine.', '{}'::text[], 'Quatre repères pour parler de Marie avec Marc.', 2, '{"id": "eg.l705.e11", "unitIds": ["eg.g705.marie_purgatoire", "eg.v.c07_immaculee_conception", "eg.v.c07_purgatoire"], "type": "match", "difficulty": 2, "prompt": "Chaque date ou verset, sa doctrine.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Quatre repères pour parler de Marie avec Marc.", "instruction": "Associe.", "pairs": [{"left": "1854", "right": "Immaculée Conception"}, {"left": "1274", "right": "purgatoire précisé"}, {"left": "431", "right": "Marie, Mère de Dieu"}, {"left": "Luc 1, 47", "right": "Marie a un Sauveur"}], "pool": "lesson", "lessonId": "eg.l705", "skill": "recognition", "answer": "1854 = Immaculée Conception ; 1274 = purgatoire précisé ; 431 = Marie, Mère de Dieu ; Luc 1, 47 = Marie a un Sauveur"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l705.e12', 'eg', 'eg.l705', 'eg.v.c05_theotokos', array['eg.v.c05_theotokos']::text[], 'mcq', 'lesson', 'Quel titre grec exprime « Mère de Dieu » ?', array['Théotokos']::text[], 'Théotokos, « celle qui enfante Dieu » : un titre que protège l''unité du Christ.', 2, '{"id": "eg.l705.e12", "unitIds": ["eg.v.c05_theotokos"], "type": "mcq", "difficulty": 2, "prompt": "Quel titre grec exprime « Mère de Dieu » ?", "promptLanguage": "fr", "answer": "Théotokos", "acceptedAnswers": ["Théotokos"], "explanation": "Théotokos, « celle qui enfante Dieu » : un titre que protège l''unité du Christ.", "instruction": "Choisis la bonne réponse.", "options": ["Christotokos", "Homoousios", "Théotokos"], "pool": "lesson", "lessonId": "eg.l705", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l705.e13', 'eg', 'eg.l705', 'eg.v.c03_augustin', array['eg.v.c03_augustin','eg.v.c07_peche_originel']::text[], 'mcq', 'lesson', 'Quel grand Père latin est à l''origine de la logique de l''Immaculée Conception ?', array['saint Augustin']::text[], 'Pour Augustin, le péché originel se transmet dès la conception.', 2, '{"id": "eg.l705.e13", "unitIds": ["eg.v.c03_augustin", "eg.v.c07_peche_originel"], "type": "mcq", "difficulty": 2, "prompt": "Quel grand Père latin est à l''origine de la logique de l''Immaculée Conception ?", "promptLanguage": "fr", "answer": "saint Augustin", "acceptedAnswers": ["saint Augustin"], "explanation": "Pour Augustin, le péché originel se transmet dès la conception.", "instruction": "Choisis la bonne réponse.", "options": ["saint Augustin", "saint Athanase", "saint Cyrille"], "pool": "lesson", "lessonId": "eg.l705", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l705.e14', 'eg', 'eg.l705', 'eg.g705.marie_purgatoire', array['eg.g705.marie_purgatoire','eg.v.c07_immaculee_conception']::text[], 'mcq', 'lesson', 'Marc te dit : « L''Immaculée Conception, c''est Jésus né d''une vierge. » Que corriges-tu, avec douceur ?', array['Elle concerne Marie, conçue sans péché originel']::text[], 'On corrige sans reproche : la naissance virginale est celle de Jésus, l''Immaculée Conception est celle de Marie.', 3, '{"id": "eg.l705.e14", "unitIds": ["eg.g705.marie_purgatoire", "eg.v.c07_immaculee_conception"], "type": "mcq", "difficulty": 3, "prompt": "Marc te dit : « L''Immaculée Conception, c''est Jésus né d''une vierge. » Que corriges-tu, avec douceur ?", "promptLanguage": "fr", "answer": "Elle concerne Marie, conçue sans péché originel", "acceptedAnswers": ["Elle concerne Marie, conçue sans péché originel"], "explanation": "On corrige sans reproche : la naissance virginale est celle de Jésus, l''Immaculée Conception est celle de Marie.", "instruction": "Choisis la bonne réponse.", "options": ["Elle concerne Joseph, l''époux de Marie, né sans péché", "Elle concerne Marie, conçue sans péché originel", "Elle concerne le jour de l''Annonciation, au printemps"], "pool": "lesson", "lessonId": "eg.l705", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l705.e15', 'eg', 'eg.l705', 'eg.g705.marie_purgatoire', array['eg.g705.marie_purgatoire','eg.v.c07_prieres_defunts']::text[], 'mcq', 'lesson', 'Pourquoi les Coptes prient-ils pour leurs défunts sans enseigner le purgatoire ?', array['Ils les confient à Dieu, seul juge, sans décrire l''après-mort']::text[], 'La prière est un geste d''amour ; la description de l''après-mort reste le secret de Dieu.', 3, '{"id": "eg.l705.e15", "unitIds": ["eg.g705.marie_purgatoire", "eg.v.c07_prieres_defunts"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi les Coptes prient-ils pour leurs défunts sans enseigner le purgatoire ?", "promptLanguage": "fr", "answer": "Ils les confient à Dieu, seul juge, sans décrire l''après-mort", "acceptedAnswers": ["Ils les confient à Dieu, seul juge, sans décrire l''après-mort"], "explanation": "La prière est un geste d''amour ; la description de l''après-mort reste le secret de Dieu.", "instruction": "Choisis la bonne réponse.", "options": ["Ils pensent que les défunts n''ont plus besoin de la miséricorde de Dieu", "Ils croient que le pape décide seul du sort de chaque défunt", "Ils les confient à Dieu, seul juge, sans décrire l''après-mort"], "pool": "lesson", "lessonId": "eg.l705", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
