insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l706.e02', 'eg', 'eg.l706', 'eg.g706.pain_celibat', array['eg.g706.pain_celibat','eg.v.c07_azymes']::text[], 'mcq', 'lesson', 'Que veut dire « azyme » ?', array['sans levain']::text[], 'A-zyme : sans levain. L''hostie latine est un pain azyme.', 1, '{"id": "eg.l706.e02", "unitIds": ["eg.g706.pain_celibat", "eg.v.c07_azymes"], "type": "mcq", "difficulty": 1, "prompt": "Que veut dire « azyme » ?", "promptLanguage": "fr", "answer": "sans levain", "acceptedAnswers": ["sans levain"], "explanation": "A-zyme : sans levain. L''hostie latine est un pain azyme.", "instruction": "Choisis la bonne réponse.", "step": 2, "options": ["bénit", "sans levain", "rond"], "pool": "lesson", "lessonId": "eg.l706", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l706.e03', 'eg', 'eg.l706', 'eg.g706.pain_celibat', array['eg.g706.pain_celibat','eg.v.c07_pain_leve']::text[], 'mcq', 'lesson', 'Quel pain l''Église copte utilise-t-elle ?', array['du pain levé']::text[], 'Un pain vivant, signe de la Résurrection.', 1, '{"id": "eg.l706.e03", "unitIds": ["eg.g706.pain_celibat", "eg.v.c07_pain_leve"], "type": "mcq", "difficulty": 1, "prompt": "Quel pain l''Église copte utilise-t-elle ?", "promptLanguage": "fr", "answer": "du pain levé", "acceptedAnswers": ["du pain levé"], "explanation": "Un pain vivant, signe de la Résurrection.", "instruction": "Choisis la bonne réponse.", "step": 2, "options": ["du pain azyme", "du pain d''orge", "du pain levé"], "pool": "lesson", "lessonId": "eg.l706", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
