insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l706.e09', 'eg', 'eg.l706', 'eg.g706.pain_celibat', array['eg.g706.pain_celibat','eg.v.c07_azymes','eg.v.c07_pain_leve','eg.v.c07_celibat']::text[], 'match', 'lesson', 'Chaque mot et son Église.', '{}'::text[], 'Deux pratiques, deux traditions : aucune ne touche la foi en la Trinité.', 2, '{"id": "eg.l706.e09", "unitIds": ["eg.g706.pain_celibat", "eg.v.c07_azymes", "eg.v.c07_pain_leve", "eg.v.c07_celibat"], "type": "match", "difficulty": 2, "prompt": "Chaque mot et son Église.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Deux pratiques, deux traditions : aucune ne touche la foi en la Trinité.", "instruction": "Associe.", "pairs": [{"left": "azymes", "right": "pain sans levain des latins"}, {"left": "pain levé", "right": "pain des Coptes"}, {"left": "célibat", "right": "règle de l''Église latine"}, {"left": "saint Pierre", "right": "un apôtre marié"}], "pool": "lesson", "lessonId": "eg.l706", "skill": "recognition", "answer": "azymes = pain sans levain des latins ; pain levé = pain des Coptes ; célibat = règle de l''Église latine ; saint Pierre = un apôtre marié"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
