insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l706.e12', 'eg', 'eg.l706', 'eg.g706.pain_celibat', array['eg.g706.pain_celibat','eg.v.c07_celibat']::text[], 'mcq', 'lesson', 'Marc dit : « Chez vous, les prêtres se marient ? » Quelle est la réponse la plus juste ?', array['Ils peuvent l''être s''ils se marient avant l''ordination, mais nos évêques sont moines']::text[], 'On précise avec exactitude, sans critiquer la discipline de Marc.', 3, '{"id": "eg.l706.e12", "unitIds": ["eg.g706.pain_celibat", "eg.v.c07_celibat"], "type": "mcq", "difficulty": 3, "prompt": "Marc dit : « Chez vous, les prêtres se marient ? » Quelle est la réponse la plus juste ?", "promptLanguage": "fr", "answer": "Ils peuvent l''être s''ils se marient avant l''ordination, mais nos évêques sont moines", "acceptedAnswers": ["Ils peuvent l''être s''ils se marient avant l''ordination, mais nos évêques sont moines"], "explanation": "On précise avec exactitude, sans critiquer la discipline de Marc.", "instruction": "Choisis la bonne réponse.", "options": ["Oui, ils se marient quand ils veulent, même après l''ordination, comme tout le monde", "Non, jamais : ils sont tous célibataires, exactement comme chez vous", "Ils peuvent l''être s''ils se marient avant l''ordination, mais nos évêques sont moines"], "pool": "lesson", "lessonId": "eg.l706", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
