insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l707.e06', 'eg', 'eg.l707', 'eg.g707.reforme_ecriture', array['eg.g707.reforme_ecriture','eg.v.c07_sola_scriptura']::text[], 'mcq', 'lesson', 'Pour l''Église copte, la foi repose sur l''Écriture et sur quoi ?', array['la Sainte Tradition']::text[], 'Paul dit : gardez les traditions que vous avez reçues.', 1, '{"id": "eg.l707.e06", "unitIds": ["eg.g707.reforme_ecriture", "eg.v.c07_sola_scriptura"], "type": "mcq", "difficulty": 1, "prompt": "Pour l''Église copte, la foi repose sur l''Écriture et sur quoi ?", "promptLanguage": "fr", "answer": "la Sainte Tradition", "acceptedAnswers": ["la Sainte Tradition"], "explanation": "Paul dit : gardez les traditions que vous avez reçues.", "instruction": "Choisis la bonne réponse.", "step": 3, "options": ["la Sainte Tradition", "le pape de Rome", "la seule raison"], "pool": "lesson", "lessonId": "eg.l707", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l707.e07', 'eg', 'eg.l707', 'eg.g707.reforme_ecriture', array['eg.g707.reforme_ecriture','eg.v.c04_livres_27']::text[], 'mcq', 'lesson', 'Qui donne la liste des 27 livres du Nouveau Testament, en 367 ?', array['Athanase']::text[], 'Athanase, le grand pape d''Alexandrie, dans sa lettre pascale de 367.', 1, '{"id": "eg.l707.e07", "unitIds": ["eg.g707.reforme_ecriture", "eg.v.c04_livres_27"], "type": "mcq", "difficulty": 1, "prompt": "Qui donne la liste des 27 livres du Nouveau Testament, en 367 ?", "promptLanguage": "fr", "answer": "Athanase", "acceptedAnswers": ["Athanase"], "explanation": "Athanase, le grand pape d''Alexandrie, dans sa lettre pascale de 367.", "instruction": "Choisis la bonne réponse.", "step": 4, "options": ["Origène", "Athanase", "Luther"], "pool": "lesson", "lessonId": "eg.l707", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l707.e08', 'eg', 'eg.l707', 'eg.g707.reforme_ecriture', array['eg.g707.reforme_ecriture','eg.v.c02_canon']::text[], 'mcq', 'lesson', 'Que veut dire « canon » pour la Bible ?', array['la liste des livres de la Bible']::text[], 'Le canon est la liste des livres reconnus par l''Église.', 1, '{"id": "eg.l707.e08", "unitIds": ["eg.g707.reforme_ecriture", "eg.v.c02_canon"], "type": "mcq", "difficulty": 1, "prompt": "Que veut dire « canon » pour la Bible ?", "promptLanguage": "fr", "answer": "la liste des livres de la Bible", "acceptedAnswers": ["la liste des livres de la Bible"], "explanation": "Le canon est la liste des livres reconnus par l''Église.", "instruction": "Choisis la bonne réponse.", "step": 4, "options": ["le chant principal de la messe", "une règle de jeûne du Carême", "la liste des livres de la Bible"], "pool": "lesson", "lessonId": "eg.l707", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l707.e09', 'eg', 'eg.l707', 'eg.g707.reforme_ecriture', array['eg.g707.reforme_ecriture','eg.v.c07_deuterocanoniques']::text[], 'mcq', 'lesson', 'D''où viennent les livres deutérocanoniques ?', array['de la Septante']::text[], 'La Septante, la Bible grecque traduite à Alexandrie.', 1, '{"id": "eg.l707.e09", "unitIds": ["eg.g707.reforme_ecriture", "eg.v.c07_deuterocanoniques"], "type": "mcq", "difficulty": 1, "prompt": "D''où viennent les livres deutérocanoniques ?", "promptLanguage": "fr", "answer": "de la Septante", "acceptedAnswers": ["de la Septante"], "explanation": "La Septante, la Bible grecque traduite à Alexandrie.", "instruction": "Choisis la bonne réponse.", "step": 5, "options": ["de la Septante", "de la Réforme", "du Coran"], "pool": "lesson", "lessonId": "eg.l707", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l707.e10', 'eg', 'eg.l707', 'eg.g707.reforme_ecriture', array['eg.g707.reforme_ecriture','eg.v.c07_deuterocanoniques']::text[], 'mcq', 'lesson', 'Combien de livres de l''Ancien Testament les protestants gardent-ils ?', array['39']::text[], 'Ils gardent la Bible hébraïque. Nous gardons aussi les livres de la Septante.', 1, '{"id": "eg.l707.e10", "unitIds": ["eg.g707.reforme_ecriture", "eg.v.c07_deuterocanoniques"], "type": "mcq", "difficulty": 1, "prompt": "Combien de livres de l''Ancien Testament les protestants gardent-ils ?", "promptLanguage": "fr", "answer": "39", "acceptedAnswers": ["39"], "explanation": "Ils gardent la Bible hébraïque. Nous gardons aussi les livres de la Septante.", "instruction": "Choisis la bonne réponse.", "step": 5, "options": ["27", "39", "150"], "pool": "lesson", "lessonId": "eg.l707", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l707.e11', 'eg', 'eg.l707', 'eg.g707.reforme_ecriture', array['eg.g707.reforme_ecriture','eg.v.c07_reforme','eg.v.c07_95_theses','eg.v.c04_athanase']::text[], 'match', 'lesson', 'Chaque réformateur, son geste.', '{}'::text[], 'Trois réformateurs, et un Père d''Alexandrie qui a fixé le canon bien avant eux.', 2, '{"id": "eg.l707.e11", "unitIds": ["eg.g707.reforme_ecriture", "eg.v.c07_reforme", "eg.v.c07_95_theses", "eg.v.c04_athanase"], "type": "match", "difficulty": 2, "prompt": "Chaque réformateur, son geste.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Trois réformateurs, et un Père d''Alexandrie qui a fixé le canon bien avant eux.", "instruction": "Associe.", "pairs": [{"left": "Luther", "right": "les 95 thèses (1517)"}, {"left": "Calvin", "right": "l''Institution de la religion chrétienne (1536)"}, {"left": "Henri VIII", "right": "rupture avec Rome (1534)"}, {"left": "Athanase", "right": "les 27 livres du Nouveau Testament (367)"}], "pool": "lesson", "lessonId": "eg.l707", "skill": "recognition", "answer": "Luther = les 95 thèses (1517) ; Calvin = l''Institution de la religion chrétienne (1536) ; Henri VIII = rupture avec Rome (1534) ; Athanase = les 27 livres du Nouveau Testament (367)"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l707.e12', 'eg', 'eg.l707', 'eg.v.c07_schisme_1054', array['eg.v.c07_schisme_1054','eg.v.c07_reforme']::text[], 'reorder', 'lesson', 'Remets dans l''ordre, du schisme à la Réforme.', array['Schisme-de-1054 Luther Henri-VIII Calvin']::text[], '1054, 1517, 1534, 1536.', 2, '{"id": "eg.l707.e12", "unitIds": ["eg.v.c07_schisme_1054", "eg.v.c07_reforme"], "type": "reorder", "difficulty": 2, "prompt": "Remets dans l''ordre, du schisme à la Réforme.", "promptLanguage": "fr", "answer": "Schisme-de-1054 Luther Henri-VIII Calvin", "acceptedAnswers": ["Schisme-de-1054 Luther Henri-VIII Calvin"], "explanation": "1054, 1517, 1534, 1536.", "instruction": "Remets dans l''ordre.", "tokens": ["Henri-VIII", "Calvin", "Schisme-de-1054", "Luther"], "pool": "lesson", "lessonId": "eg.l707", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l707.e13', 'eg', 'eg.l707', 'eg.v.c02_tradition', array['eg.v.c02_tradition']::text[], 'mcq', 'lesson', 'Qu''est-ce que la sainte tradition ?', array['ce que les apôtres ont transmis de vive voix et par la vie de l''Église']::text[], 'La Tradition est la vie de l''Église depuis les apôtres : elle a produit et reconnu la Bible.', 2, '{"id": "eg.l707.e13", "unitIds": ["eg.v.c02_tradition"], "type": "mcq", "difficulty": 2, "prompt": "Qu''est-ce que la sainte tradition ?", "promptLanguage": "fr", "answer": "ce que les apôtres ont transmis de vive voix et par la vie de l''Église", "acceptedAnswers": ["ce que les apôtres ont transmis de vive voix et par la vie de l''Église"], "explanation": "La Tradition est la vie de l''Église depuis les apôtres : elle a produit et reconnu la Bible.", "instruction": "Choisis la bonne réponse.", "options": ["un livre secret réservé aux évêques de l''Église copte", "les coutumes locales d''un pays et de sa culture", "ce que les apôtres ont transmis de vive voix et par la vie de l''Église"], "pool": "lesson", "lessonId": "eg.l707", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l707.e14', 'eg', 'eg.l707', 'eg.g707.reforme_ecriture', array['eg.g707.reforme_ecriture','eg.v.c07_sola_scriptura']::text[], 'mcq', 'lesson', 'Sarah dit : « La Bible suffit, pas besoin de Tradition. » Quelle réponse est la plus juste et la plus respectueuse ?', array['J''aime ton amour de la Bible ; mais elle est née dans l''Église, qui en a reconnu les livres']::text[], 'On honore l''amour de l''Écriture, puis on dit pourquoi nous gardons aussi la Tradition.', 3, '{"id": "eg.l707.e14", "unitIds": ["eg.g707.reforme_ecriture", "eg.v.c07_sola_scriptura"], "type": "mcq", "difficulty": 3, "prompt": "Sarah dit : « La Bible suffit, pas besoin de Tradition. » Quelle réponse est la plus juste et la plus respectueuse ?", "promptLanguage": "fr", "answer": "J''aime ton amour de la Bible ; mais elle est née dans l''Église, qui en a reconnu les livres", "acceptedAnswers": ["J''aime ton amour de la Bible ; mais elle est née dans l''Église, qui en a reconnu les livres"], "explanation": "On honore l''amour de l''Écriture, puis on dit pourquoi nous gardons aussi la Tradition.", "instruction": "Choisis la bonne réponse.", "options": ["J''aime ton amour de la Bible ; mais elle est née dans l''Église, qui en a reconnu les livres", "Les protestants ne lisent pas la Bible comme il faut, voyons", "La Tradition compte plus que la Bible, qui n''est qu''un livre parmi d''autres"], "pool": "lesson", "lessonId": "eg.l707", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l707.e15', 'eg', 'eg.l707', 'eg.g707.reforme_ecriture', array['eg.g707.reforme_ecriture','eg.v.c01_septante','eg.v.c07_deuterocanoniques']::text[], 'mcq', 'lesson', 'Pourquoi les Coptes ont-ils plus de livres que les protestants dans l''Ancien Testament ?', array['Ils suivent la Septante, la Bible grecque d''Alexandrie']::text[], 'Notre héritage d''Alexandrie : la Septante contient ces livres.', 3, '{"id": "eg.l707.e15", "unitIds": ["eg.g707.reforme_ecriture", "eg.v.c01_septante", "eg.v.c07_deuterocanoniques"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi les Coptes ont-ils plus de livres que les protestants dans l''Ancien Testament ?", "promptLanguage": "fr", "answer": "Ils suivent la Septante, la Bible grecque d''Alexandrie", "acceptedAnswers": ["Ils suivent la Septante, la Bible grecque d''Alexandrie"], "explanation": "Notre héritage d''Alexandrie : la Septante contient ces livres.", "instruction": "Choisis la bonne réponse.", "options": ["Ils ont écrit ces livres eux-mêmes après la Réforme de Luther", "Ils suivent la Septante, la Bible grecque d''Alexandrie", "Ils ont ajouté ces livres à la Bible au Ve siècle, à Chalcédoine"], "pool": "lesson", "lessonId": "eg.l707", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
