insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l708.e14', 'eg', 'eg.l708', 'eg.g708.foi_oeuvres', array['eg.g708.foi_oeuvres','eg.v.c07_sola_fide']::text[], 'mcq', 'lesson', 'Sarah dit : « Nous sommes sauvés par la foi seule. » Quelle réponse est la plus juste ?', array['Moi aussi, je crois que la grâce précède tout ; les œuvres en sont le fruit']::text[], 'On part de ce qui nous unit, la grâce, avant de dire la nuance.', 3, '{"id": "eg.l708.e14", "unitIds": ["eg.g708.foi_oeuvres", "eg.v.c07_sola_fide"], "type": "mcq", "difficulty": 3, "prompt": "Sarah dit : « Nous sommes sauvés par la foi seule. » Quelle réponse est la plus juste ?", "promptLanguage": "fr", "answer": "Moi aussi, je crois que la grâce précède tout ; les œuvres en sont le fruit", "acceptedAnswers": ["Moi aussi, je crois que la grâce précède tout ; les œuvres en sont le fruit"], "explanation": "On part de ce qui nous unit, la grâce, avant de dire la nuance.", "instruction": "Choisis la bonne réponse.", "options": ["Tu crois donc qu''on peut acheter le salut avec de l''argent, comme avant", "Moi aussi, je crois que la grâce précède tout ; les œuvres en sont le fruit", "Vous refusez toute bonne action, et c''est une grave erreur de votre part"], "pool": "lesson", "lessonId": "eg.l708", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
