insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l709.e14', 'eg', 'eg.l709', 'eg.g709.sacrements_saints_icones', array['eg.g709.sacrements_saints_icones','eg.v.c07_intercession']::text[], 'mcq', 'lesson', 'Sarah demande : « Pourquoi priez-vous les saints, alors qu''il n''y a qu''un médiateur ? » Quelle réponse est la plus juste ?', array['Le Christ est seul médiateur ; aux saints, on demande de prier pour nous, comme à un frère']::text[], 'On est d''accord sur 1 Timothée 2, 5, puis on explique la prière des saints.', 3, '{"id": "eg.l709.e14", "unitIds": ["eg.g709.sacrements_saints_icones", "eg.v.c07_intercession"], "type": "mcq", "difficulty": 3, "prompt": "Sarah demande : « Pourquoi priez-vous les saints, alors qu''il n''y a qu''un médiateur ? » Quelle réponse est la plus juste ?", "promptLanguage": "fr", "answer": "Le Christ est seul médiateur ; aux saints, on demande de prier pour nous, comme à un frère", "acceptedAnswers": ["Le Christ est seul médiateur ; aux saints, on demande de prier pour nous, comme à un frère"], "explanation": "On est d''accord sur 1 Timothée 2, 5, puis on explique la prière des saints.", "instruction": "Choisis la bonne réponse.", "options": ["Le Christ est seul médiateur ; aux saints, on demande de prier pour nous, comme à un frère", "Les saints sont nos médiateurs à la place du Christ, qui reste très loin de nous", "Les saints sont morts et ne peuvent rien faire pour nous, comme pour tout le monde"], "pool": "lesson", "lessonId": "eg.l709", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l709.e15', 'eg', 'eg.l709', 'eg.g709.sacrements_saints_icones', array['eg.g709.sacrements_saints_icones','eg.v.c07_icone','eg.v.c05_incarnation']::text[], 'mcq', 'lesson', 'Pourquoi l''incarnation sert-elle de fondement aux icônes ?', array['Parce que Dieu s''est rendu visible en Jésus-Christ']::text[], 'Le Verbe s''est fait chair : on peut représenter celui qui s''est montré.', 3, '{"id": "eg.l709.e15", "unitIds": ["eg.g709.sacrements_saints_icones", "eg.v.c07_icone", "eg.v.c05_incarnation"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi l''incarnation sert-elle de fondement aux icônes ?", "promptLanguage": "fr", "answer": "Parce que Dieu s''est rendu visible en Jésus-Christ", "acceptedAnswers": ["Parce que Dieu s''est rendu visible en Jésus-Christ"], "explanation": "Le Verbe s''est fait chair : on peut représenter celui qui s''est montré.", "instruction": "Choisis la bonne réponse.", "options": ["Parce que Moïse a sculpté des images de Dieu dans le désert", "Parce que Dieu s''est rendu visible en Jésus-Christ", "Parce que les saints sont des dieux qu''on peut représenter"], "pool": "lesson", "lessonId": "eg.l709", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
