insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l710.e05', 'eg', 'eg.l710', 'eg.g710.mormons', array['eg.g710.mormons','eg.v.c07_mormons']::text[], 'mcq', 'lesson', 'Pour les mormons, le Père, le Fils et l''Esprit sont :', array['trois êtres distincts']::text[], 'C''est là que leur doctrine diffère de la Trinité.', 1, '{"id": "eg.l710.e05", "unitIds": ["eg.g710.mormons", "eg.v.c07_mormons"], "type": "mcq", "difficulty": 1, "prompt": "Pour les mormons, le Père, le Fils et l''Esprit sont :", "promptLanguage": "fr", "answer": "trois êtres distincts", "acceptedAnswers": ["trois êtres distincts"], "explanation": "C''est là que leur doctrine diffère de la Trinité.", "instruction": "Choisis la bonne réponse.", "step": 3, "options": ["trois êtres distincts", "un seul être sous trois noms", "deux êtres seulement, le Père et le Fils"], "pool": "lesson", "lessonId": "eg.l710", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
