insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l710.e10', 'eg', 'eg.l710', 'eg.v.c04_homoousios', array['eg.v.c04_homoousios']::text[], 'mcq', 'lesson', 'Quel mot grec de Nicée dit que le Fils est de même substance que le Père ?', array['homoousios']::text[], 'Homoousios : de même substance que le Père.', 2, '{"id": "eg.l710.e10", "unitIds": ["eg.v.c04_homoousios"], "type": "mcq", "difficulty": 2, "prompt": "Quel mot grec de Nicée dit que le Fils est de même substance que le Père ?", "promptLanguage": "fr", "answer": "homoousios", "acceptedAnswers": ["homoousios"], "explanation": "Homoousios : de même substance que le Père.", "instruction": "Choisis la bonne réponse.", "options": ["Théotokos", "homoousios", "physis"], "pool": "lesson", "lessonId": "eg.l710", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l710.e11', 'eg', 'eg.l710', 'eg.g710.mormons', array['eg.g710.mormons','eg.v.c07_mormons']::text[], 'mcq', 'lesson', 'Lucas te dit : « Nous croyons en Jésus-Christ aussi. » Quelle réponse est juste et douce ?', array['Je respecte ta foi en Jésus ; notre différence porte sur Dieu : un seul Dieu en trois personnes']::text[], 'On reconnaît ce qui est commun, puis on nomme la vraie différence, sans blesser.', 3, '{"id": "eg.l710.e11", "unitIds": ["eg.g710.mormons", "eg.v.c07_mormons"], "type": "mcq", "difficulty": 3, "prompt": "Lucas te dit : « Nous croyons en Jésus-Christ aussi. » Quelle réponse est juste et douce ?", "promptLanguage": "fr", "answer": "Je respecte ta foi en Jésus ; notre différence porte sur Dieu : un seul Dieu en trois personnes", "acceptedAnswers": ["Je respecte ta foi en Jésus ; notre différence porte sur Dieu : un seul Dieu en trois personnes"], "explanation": "On reconnaît ce qui est commun, puis on nomme la vraie différence, sans blesser.", "instruction": "Choisis la bonne réponse.", "options": ["Alors nous croyons exactement la même chose que toi sur Dieu", "Votre livre est un faux, point final, il n''y a rien à discuter", "Je respecte ta foi en Jésus ; notre différence porte sur Dieu : un seul Dieu en trois personnes"], "pool": "lesson", "lessonId": "eg.l710", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l710.e12', 'eg', 'eg.l710', 'eg.g710.mormons', array['eg.g710.mormons','eg.v.c07_livre_de_mormon']::text[], 'mcq', 'lesson', 'Pourquoi un livre apparu en 1830 ne peut-il pas être Écriture, pour les Coptes ?', array['Parce que la foi a été transmise une fois pour toutes par les apôtres']::text[], 'Les livres de la Bible viennent des apôtres ou de leur contrôle ; on n''y ajoute rien.', 3, '{"id": "eg.l710.e12", "unitIds": ["eg.g710.mormons", "eg.v.c07_livre_de_mormon"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi un livre apparu en 1830 ne peut-il pas être Écriture, pour les Coptes ?", "promptLanguage": "fr", "answer": "Parce que la foi a été transmise une fois pour toutes par les apôtres", "acceptedAnswers": ["Parce que la foi a été transmise une fois pour toutes par les apôtres"], "explanation": "Les livres de la Bible viennent des apôtres ou de leur contrôle ; on n''y ajoute rien.", "instruction": "Choisis la bonne réponse.", "options": ["Parce que la foi a été transmise une fois pour toutes par les apôtres", "Parce qu''il est écrit en anglais, une langue que les apôtres ne parlaient pas", "Parce qu''il est beaucoup trop long pour être lu à la messe"], "pool": "lesson", "lessonId": "eg.l710", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
