insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l714.e11', 'eg', 'eg.l714', 'eg.g714.bilan', array['eg.g714.bilan','eg.v.c07_adventistes']::text[], 'fill_blank', 'lesson', 'Les adventistes croient à la ___.', array['Trinité']::text[], 'Ils gardent la Trinité, contrairement aux témoins de Jéhovah.', 2, '{"id": "eg.l714.e11", "unitIds": ["eg.g714.bilan", "eg.v.c07_adventistes"], "type": "fill_blank", "difficulty": 2, "prompt": "Les adventistes croient à la ___.", "promptLanguage": "fr", "answer": "Trinité", "acceptedAnswers": ["Trinité"], "explanation": "Ils gardent la Trinité, contrairement aux témoins de Jéhovah.", "instruction": "Complète la phrase.", "options": ["Trinité", "transfusion", "Réforme"], "pool": "lesson", "lessonId": "eg.l714", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l714.e12', 'eg', 'eg.l714', 'eg.g714.bilan', array['eg.g714.bilan','eg.v.c07_trois_questions']::text[], 'mcq', 'lesson', 'Marc demande : « Pourquoi vous n''avez pas le même pape ? » Quelle est la meilleure réponse à lui donner ?', array['Nous avons beaucoup en commun ; chez nous, les évêques décident ensemble en concile, et nous avons aussi un pape à Alexandrie']::text[], 'Le commun, la différence, le pourquoi : une réponse calme, sans reproche.', 3, '{"id": "eg.l714.e12", "unitIds": ["eg.g714.bilan", "eg.v.c07_trois_questions"], "type": "mcq", "difficulty": 3, "prompt": "Marc demande : « Pourquoi vous n''avez pas le même pape ? » Quelle est la meilleure réponse à lui donner ?", "promptLanguage": "fr", "answer": "Nous avons beaucoup en commun ; chez nous, les évêques décident ensemble en concile, et nous avons aussi un pape à Alexandrie", "acceptedAnswers": ["Nous avons beaucoup en commun ; chez nous, les évêques décident ensemble en concile, et nous avons aussi un pape à Alexandrie"], "explanation": "Le commun, la différence, le pourquoi : une réponse calme, sans reproche.", "instruction": "Choisis la bonne réponse.", "options": ["Parce que le pape s''est trompé en 1870, ce qui prouve que votre Église ne vaut rien", "Nous avons beaucoup en commun ; chez nous, les évêques décident ensemble en concile, et nous avons aussi un pape à Alexandrie", "Parce que votre Église n''est pas la vraie Église du Christ, tout simplement"], "pool": "lesson", "lessonId": "eg.l714", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l714.e13', 'eg', 'eg.l714', 'eg.g714.bilan', array['eg.g714.bilan','eg.v.c05_miaphysisme']::text[], 'mcq', 'lesson', 'Eleni demande : « Pourquoi dites-vous une seule nature ? » Quelle est la meilleure réponse à lui donner ?', array['Nous confessons le même Christ, vrai Dieu et vrai homme ; nous suivons saint Cyrille']::text[], 'Même Christ, autres mots : la réponse d''un miaphysite, pas d''un monophysite.', 3, '{"id": "eg.l714.e13", "unitIds": ["eg.g714.bilan", "eg.v.c05_miaphysisme"], "type": "mcq", "difficulty": 3, "prompt": "Eleni demande : « Pourquoi dites-vous une seule nature ? » Quelle est la meilleure réponse à lui donner ?", "promptLanguage": "fr", "answer": "Nous confessons le même Christ, vrai Dieu et vrai homme ; nous suivons saint Cyrille", "acceptedAnswers": ["Nous confessons le même Christ, vrai Dieu et vrai homme ; nous suivons saint Cyrille"], "explanation": "Même Christ, autres mots : la réponse d''un miaphysite, pas d''un monophysite.", "instruction": "Choisis la bonne réponse.", "options": ["Parce que le Christ n''est pas vraiment homme, seulement Dieu en apparence", "Parce que Chalcédoine a condamné Cyrille et tous les Pères d''Alexandrie", "Nous confessons le même Christ, vrai Dieu et vrai homme ; nous suivons saint Cyrille"], "pool": "lesson", "lessonId": "eg.l714", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l714.e14', 'eg', 'eg.l714', 'eg.g714.bilan', array['eg.g714.bilan','eg.v.c07_trois_questions']::text[], 'mcq', 'lesson', 'Sarah demande : « Pourquoi priez-vous les saints ? » Quelle est la meilleure réponse à lui donner ?', array['Les saints sont vivants en Christ ; on leur demande de prier pour nous, comme à un frère']::text[], 'On accepte « un seul médiateur », puis on explique la prière des saints.', 3, '{"id": "eg.l714.e14", "unitIds": ["eg.g714.bilan", "eg.v.c07_trois_questions"], "type": "mcq", "difficulty": 3, "prompt": "Sarah demande : « Pourquoi priez-vous les saints ? » Quelle est la meilleure réponse à lui donner ?", "promptLanguage": "fr", "answer": "Les saints sont vivants en Christ ; on leur demande de prier pour nous, comme à un frère", "acceptedAnswers": ["Les saints sont vivants en Christ ; on leur demande de prier pour nous, comme à un frère"], "explanation": "On accepte « un seul médiateur », puis on explique la prière des saints.", "instruction": "Choisis la bonne réponse.", "options": ["Les saints sont vivants en Christ ; on leur demande de prier pour nous, comme à un frère", "Les saints remplacent le Christ, qui n''écoute plus nos prières", "Les saints sont plus puissants que Dieu, qui leur a tout laissé"], "pool": "lesson", "lessonId": "eg.l714", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l714.e15', 'eg', 'eg.l714', 'eg.g714.bilan', array['eg.g714.bilan','eg.v.c07_trois_questions']::text[], 'mcq', 'lesson', 'Daniel dit : « Jésus est un être créé. » Quelle est la meilleure réponse à lui donner ?', array['Jean 1, 1 dit : le Verbe était Dieu ; nous confessons le Fils de même nature que le Père']::text[], 'Un verset, une phrase simple, aucune moquerie.', 3, '{"id": "eg.l714.e15", "unitIds": ["eg.g714.bilan", "eg.v.c07_trois_questions"], "type": "mcq", "difficulty": 3, "prompt": "Daniel dit : « Jésus est un être créé. » Quelle est la meilleure réponse à lui donner ?", "promptLanguage": "fr", "answer": "Jean 1, 1 dit : le Verbe était Dieu ; nous confessons le Fils de même nature que le Père", "acceptedAnswers": ["Jean 1, 1 dit : le Verbe était Dieu ; nous confessons le Fils de même nature que le Père"], "explanation": "Un verset, une phrase simple, aucune moquerie.", "instruction": "Choisis la bonne réponse.", "options": ["Tu ne sais rien de la Bible, tu n''as jamais lu Jean 1, 1 correctement", "Jean 1, 1 dit : le Verbe était Dieu ; nous confessons le Fils de même nature que le Père", "Ce n''est pas grave, toutes les croyances se valent et il n''y a rien à dire"], "pool": "lesson", "lessonId": "eg.l714", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l801.e01', 'eg', 'eg.l801', 'eg.g801.origine_du_credo', array['eg.g801.origine_du_credo','eg.v.c08_catechumene']::text[], 'mcq', 'lesson', 'Comment appelle-t-on celui qui apprend la foi avant son baptême ?', array['catéchumène']::text[], 'Le catéchumène est en route vers le baptême. Son « je crois » est le germe du Credo.', 1, '{"unitIds": ["eg.g801.origine_du_credo", "eg.v.c08_catechumene"], "type": "mcq", "difficulty": 1, "prompt": "Comment appelle-t-on celui qui apprend la foi avant son baptême ?", "promptLanguage": "fr", "answer": "catéchumène", "acceptedAnswers": ["catéchumène"], "explanation": "Le catéchumène est en route vers le baptême. Son « je crois » est le germe du Credo.", "instruction": "Choisis la bonne réponse.", "options": ["catéchumène", "missionnaire", "prophète", "ermite"], "step": 1, "id": "eg.l801.e01", "pool": "lesson", "lessonId": "eg.l801", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l801.e02', 'eg', 'eg.l801', 'eg.g801.origine_du_credo', array['eg.g801.origine_du_credo','eg.v.c08_catechumene']::text[], 'fill_blank', 'lesson', 'Avant d''être baptisé, il répond trois fois : « ___. »', array['Je crois']::text[], 'Trois questions, trois « je crois » : Père, Fils, Esprit Saint. Déjà le plan du Credo.', 1, '{"unitIds": ["eg.g801.origine_du_credo", "eg.v.c08_catechumene"], "type": "fill_blank", "difficulty": 1, "prompt": "Avant d''être baptisé, il répond trois fois : « ___. »", "promptLanguage": "fr", "answer": "Je crois", "acceptedAnswers": ["Je crois"], "explanation": "Trois questions, trois « je crois » : Père, Fils, Esprit Saint. Déjà le plan du Credo.", "instruction": "Complète la phrase.", "options": ["Je sais", "Je crois", "J''obéis", "Je viens"], "step": 1, "id": "eg.l801.e02", "pool": "lesson", "lessonId": "eg.l801", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l801.e03', 'eg', 'eg.l801', 'eg.g801.origine_du_credo', array['eg.g801.origine_du_credo','eg.v.c08_credo']::text[], 'mcq', 'lesson', 'Que veut dire le mot latin Credo ?', array['je crois']::text[], 'Un seul verbe, et toute la foi derrière.', 1, '{"unitIds": ["eg.g801.origine_du_credo", "eg.v.c08_credo"], "type": "mcq", "difficulty": 1, "prompt": "Que veut dire le mot latin Credo ?", "promptLanguage": "fr", "answer": "je crois", "acceptedAnswers": ["je crois"], "explanation": "Un seul verbe, et toute la foi derrière.", "instruction": "Choisis la bonne réponse.", "options": ["je prie", "je chante", "je crois", "je pardonne"], "step": 2, "id": "eg.l801.e03", "pool": "lesson", "lessonId": "eg.l801", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
