insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l801.e05', 'eg', 'eg.l801', 'eg.g801.origine_du_credo', array['eg.g801.origine_du_credo','eg.v.c04_credo_nicee_constantinople']::text[], 'mcq', 'lesson', 'Quel concile a ajouté tout ce qui suit « et en l''Esprit Saint » ?', array['Constantinople']::text[], 'Constantinople, en 381, a développé l''Esprit Saint et achevé le texte.', 1, '{"unitIds": ["eg.g801.origine_du_credo", "eg.v.c04_credo_nicee_constantinople"], "type": "mcq", "difficulty": 1, "prompt": "Quel concile a ajouté tout ce qui suit « et en l''Esprit Saint » ?", "promptLanguage": "fr", "answer": "Constantinople", "acceptedAnswers": ["Constantinople"], "explanation": "Constantinople, en 381, a développé l''Esprit Saint et achevé le texte.", "instruction": "Choisis la bonne réponse.", "options": ["Constantinople", "Nicée", "Éphèse", "Chalcédoine"], "step": 3, "id": "eg.l801.e05", "pool": "lesson", "lessonId": "eg.l801", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
