insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l801.e15', 'eg', 'eg.l801', 'eg.g801.origine_du_credo', array['eg.g801.origine_du_credo','eg.v.c08_nous_croyons']::text[], 'mcq', 'lesson', 'Pourquoi dit-on « nous croyons » plutôt que « je crois » ?', array['Parce que la foi est celle de toute l''Église']::text[], 'On ne croit pas seul : on confesse avec tous ceux qui nous ont précédés et avec l''assemblée.', 3, '{"unitIds": ["eg.g801.origine_du_credo", "eg.v.c08_nous_croyons"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi dit-on « nous croyons » plutôt que « je crois » ?", "promptLanguage": "fr", "answer": "Parce que la foi est celle de toute l''Église", "acceptedAnswers": ["Parce que la foi est celle de toute l''Église"], "explanation": "On ne croit pas seul : on confesse avec tous ceux qui nous ont précédés et avec l''assemblée.", "instruction": "Choisis la bonne réponse.", "options": ["Parce que c''est plus court à dire", "Parce que seul l''évêque a le droit de parler", "Parce que la foi est celle de toute l''Église", "Parce que le texte est en grec"], "id": "eg.l801.e15", "pool": "lesson", "lessonId": "eg.l801", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
