insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l803.e16', 'eg', 'eg.l803', 'eg.g803.createur_ciel_terre', array['eg.g803.createur_ciel_terre','eg.v.c08_ange']::text[], 'mcq', 'lesson', 'Pourquoi le Credo précise-t-il que Dieu a créé aussi les choses invisibles ?', array['Pour dire que les anges sont des créatures']::text[], 'Si Dieu les a créés, ils ne sont pas Dieu : on n''adore que lui.', 3, '{"unitIds": ["eg.g803.createur_ciel_terre", "eg.v.c08_ange"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi le Credo précise-t-il que Dieu a créé aussi les choses invisibles ?", "promptLanguage": "fr", "answer": "Pour dire que les anges sont des créatures", "acceptedAnswers": ["Pour dire que les anges sont des créatures"], "explanation": "Si Dieu les a créés, ils ne sont pas Dieu : on n''adore que lui.", "instruction": "Choisis la bonne réponse.", "options": ["Pour dire que les anges sont des créatures", "Pour dire que le monde est une illusion sans réalité", "Pour dire que les anges ont créé le monde visible", "Pour dire que la matière est sans aucune valeur"], "id": "eg.l803.e16", "pool": "lesson", "lessonId": "eg.l803", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
