insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l805.e13', 'eg', 'eg.l805', 'eg.g805.lumiere_de_lumiere', array['eg.g805.lumiere_de_lumiere','eg.v.c08_lumiere_de_lumiere','eg.v.c08_engendre_non_cree']::text[], 'match', 'lesson', 'Les trois expressions du Fils, chacune son sens.', '{}'::text[], 'La flamme dit la même lumière, le double « vrai » dit le même Dieu, engendré dit la même nature.', 2, '{"unitIds": ["eg.g805.lumiere_de_lumiere", "eg.v.c08_lumiere_de_lumiere", "eg.v.c08_engendre_non_cree"], "type": "match", "difficulty": 2, "prompt": "Les trois expressions du Fils, chacune son sens.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "La flamme dit la même lumière, le double « vrai » dit le même Dieu, engendré dit la même nature.", "instruction": "Associe.", "pairs": [{"left": "Lumière de Lumière", "right": "une flamme allumée à une autre"}, {"left": "vrai Dieu de vrai Dieu", "right": "pas un Dieu moindre"}, {"left": "engendré non créé", "right": "la nature du Père, pas une œuvre"}], "id": "eg.l805.e13", "pool": "lesson", "lessonId": "eg.l805", "skill": "recognition", "answer": "Lumière de Lumière = une flamme allumée à une autre ; vrai Dieu de vrai Dieu = pas un Dieu moindre ; engendré non créé = la nature du Père, pas une œuvre"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l805.e14', 'eg', 'eg.l805', 'eg.v.c08_fils_unique', array['eg.v.c08_fils_unique','eg.g805.lumiere_de_lumiere']::text[], 'mcq', 'lesson', 'Quel mot de la phrase « le Fils unique de Dieu » dit qu''il est Fils par nature ?', array['unique']::text[], 'Fils unique : le seul qui soit Fils par nature.', 2, '{"unitIds": ["eg.v.c08_fils_unique", "eg.g805.lumiere_de_lumiere"], "type": "mcq", "difficulty": 2, "prompt": "Quel mot de la phrase « le Fils unique de Dieu » dit qu''il est Fils par nature ?", "promptLanguage": "fr", "answer": "unique", "acceptedAnswers": ["unique"], "explanation": "Fils unique : le seul qui soit Fils par nature.", "instruction": "Choisis la bonne réponse.", "options": ["Seigneur", "engendré", "unique", "Dieu"], "id": "eg.l805.e14", "pool": "lesson", "lessonId": "eg.l805", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l805.e15', 'eg', 'eg.l805', 'eg.g805.lumiere_de_lumiere', array['eg.g805.lumiere_de_lumiere','eg.v.c08_lumiere_de_lumiere']::text[], 'mcq', 'lesson', 'Pourquoi l''image de la flamme convient-elle au Père et au Fils ?', array['Elle montre une même lumière sans perte']::text[], 'Allumer une flamme n''enlève rien à l''autre : le Père ne perd rien en engendrant le Fils.', 3, '{"unitIds": ["eg.g805.lumiere_de_lumiere", "eg.v.c08_lumiere_de_lumiere"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi l''image de la flamme convient-elle au Père et au Fils ?", "promptLanguage": "fr", "answer": "Elle montre une même lumière sans perte", "acceptedAnswers": ["Elle montre une même lumière sans perte"], "explanation": "Allumer une flamme n''enlève rien à l''autre : le Père ne perd rien en engendrant le Fils.", "instruction": "Choisis la bonne réponse.", "options": ["Elle montre qu''une flamme s''éteint vite", "Elle montre que la seconde est plus petite", "Elle montre que la première change", "Elle montre une même lumière sans perte"], "id": "eg.l805.e15", "pool": "lesson", "lessonId": "eg.l805", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
