insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l806.e16', 'eg', 'eg.l806', 'eg.g806.consubstantiel', array['eg.g806.consubstantiel','eg.v.c08_seul_dieu_sauve']::text[], 'mcq', 'lesson', 'Si le Fils n''était qu''une créature, que perdrait-on ?', array['Le salut, car seul Dieu peut sauver']::text[], 'Une créature ne peut pas nous sauver : c''est tout l''enjeu de ce mot.', 3, '{"unitIds": ["eg.g806.consubstantiel", "eg.v.c08_seul_dieu_sauve"], "type": "mcq", "difficulty": 3, "prompt": "Si le Fils n''était qu''une créature, que perdrait-on ?", "promptLanguage": "fr", "answer": "Le salut, car seul Dieu peut sauver", "acceptedAnswers": ["Le salut, car seul Dieu peut sauver"], "explanation": "Une créature ne peut pas nous sauver : c''est tout l''enjeu de ce mot.", "instruction": "Choisis la bonne réponse.", "options": ["La création, car Dieu serait seul", "Le baptême, car l''eau serait sans effet", "Le Credo, car il serait trop long", "Le salut, car seul Dieu peut sauver"], "id": "eg.l806.e16", "pool": "lesson", "lessonId": "eg.l806", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
