insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l808.e13', 'eg', 'eg.l808', 'eg.v.c08_lumiere_de_lumiere', array['eg.v.c08_lumiere_de_lumiere','eg.v.c08_pour_notre_salut','eg.g808.incarna_vierge_marie']::text[], 'reorder', 'lesson', 'Remets ces morceaux du Credo dans l''ordre, du Fils éternel à l''homme.', array['Lumière-de-Lumière par-qui-tout-a-été-fait descendit-du-ciel s''incarna se-fit-homme']::text[], 'On passe de la gloire éternelle du Fils à sa venue parmi nous.', 3, '{"unitIds": ["eg.v.c08_lumiere_de_lumiere", "eg.v.c08_pour_notre_salut", "eg.g808.incarna_vierge_marie"], "type": "reorder", "difficulty": 3, "prompt": "Remets ces morceaux du Credo dans l''ordre, du Fils éternel à l''homme.", "promptLanguage": "fr", "answer": "Lumière-de-Lumière par-qui-tout-a-été-fait descendit-du-ciel s''incarna se-fit-homme", "acceptedAnswers": ["Lumière-de-Lumière par-qui-tout-a-été-fait descendit-du-ciel s''incarna se-fit-homme"], "explanation": "On passe de la gloire éternelle du Fils à sa venue parmi nous.", "instruction": "Remets dans l''ordre.", "tokens": ["se-fit-homme", "Lumière-de-Lumière", "s''incarna", "descendit-du-ciel", "par-qui-tout-a-été-fait"], "id": "eg.l808.e13", "pool": "lesson", "lessonId": "eg.l808", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l808.e14', 'eg', 'eg.l808', 'eg.v.c01_docetisme', array['eg.v.c01_docetisme','eg.v.c04_apollinaire','eg.g808.incarna_vierge_marie']::text[], 'match', 'lesson', 'Chaque erreur, son rejet.', '{}'::text[], 'Le Credo écarte les deux erreurs sur l''homme, et Marie protège l''unité du Christ.', 2, '{"unitIds": ["eg.v.c01_docetisme", "eg.v.c04_apollinaire", "eg.g808.incarna_vierge_marie"], "type": "match", "difficulty": 2, "prompt": "Chaque erreur, son rejet.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Le Credo écarte les deux erreurs sur l''homme, et Marie protège l''unité du Christ.", "instruction": "Associe.", "pairs": [{"left": "le docétisme", "right": "un corps de pure apparence"}, {"left": "Apollinaire", "right": "pas d''âme humaine"}, {"left": "Théotokos", "right": "celle qui enfante Dieu"}], "id": "eg.l808.e14", "pool": "lesson", "lessonId": "eg.l808", "skill": "recognition", "answer": "le docétisme = un corps de pure apparence ; Apollinaire = pas d''âme humaine ; Théotokos = celle qui enfante Dieu"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
