insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l808.e16', 'eg', 'eg.l808', 'eg.g808.incarna_vierge_marie', array['eg.g808.incarna_vierge_marie','eg.v.c08_un_seul_sujet','eg.v.c08_vierge_marie']::text[], 'mcq', 'lesson', 'Pourquoi le Credo dit-il que Marie enfante Dieu le Verbe, et pas seulement un homme ?', array['Parce que celui qui naît est le Fils éternel']::text[], 'Si Marie n''enfantait qu''un homme, il y aurait deux personnes dans le Christ.', 3, '{"unitIds": ["eg.g808.incarna_vierge_marie", "eg.v.c08_un_seul_sujet", "eg.v.c08_vierge_marie"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi le Credo dit-il que Marie enfante Dieu le Verbe, et pas seulement un homme ?", "promptLanguage": "fr", "answer": "Parce que celui qui naît est le Fils éternel", "acceptedAnswers": ["Parce que celui qui naît est le Fils éternel"], "explanation": "Si Marie n''enfantait qu''un homme, il y aurait deux personnes dans le Christ.", "instruction": "Choisis la bonne réponse.", "options": ["Parce que Marie est une déesse venue du ciel", "Parce que Jésus n''a pas de vrai corps humain", "Parce que Dieu a besoin de Marie pour exister", "Parce que celui qui naît est le Fils éternel"], "id": "eg.l808.e16", "pool": "lesson", "lessonId": "eg.l808", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
