insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l811.e11', 'eg', 'eg.l811', 'eg.g811.saint_esprit', array['eg.g811.saint_esprit','eg.v.c08_vivificateur']::text[], 'fill_blank', 'lesson', 'Nous croyons au Saint-Esprit, ___ qui donne la vie', array['Seigneur']::text[], 'Seigneur : le titre de Dieu pour l''Esprit.', 2, '{"unitIds": ["eg.g811.saint_esprit", "eg.v.c08_vivificateur"], "type": "fill_blank", "difficulty": 2, "prompt": "Nous croyons au Saint-Esprit, ___ qui donne la vie", "promptLanguage": "fr", "answer": "Seigneur", "acceptedAnswers": ["Seigneur"], "explanation": "Seigneur : le titre de Dieu pour l''Esprit.", "instruction": "Complète la phrase.", "options": ["Père", "Roi", "Seigneur", "Verbe"], "id": "eg.l811.e11", "pool": "lesson", "lessonId": "eg.l811", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l811.e12', 'eg', 'eg.l811', 'eg.g811.saint_esprit', array['eg.g811.saint_esprit','eg.v.c08_procession','eg.v.c08_a_parle_par_les_prophetes']::text[], 'reorder', 'lesson', 'Remets les quatre « qui » de l''Esprit dans l''ordre.', array['qui-donne-la-vie qui-procède-du-Père qui-avec-le-Père-et-le-Fils-est-adoré-et-glorifié qui-a-parlé-par-les-prophètes']::text[], 'Il donne la vie, il procède, il est adoré, il a parlé.', 2, '{"unitIds": ["eg.g811.saint_esprit", "eg.v.c08_procession", "eg.v.c08_a_parle_par_les_prophetes"], "type": "reorder", "difficulty": 2, "prompt": "Remets les quatre « qui » de l''Esprit dans l''ordre.", "promptLanguage": "fr", "answer": "qui-donne-la-vie qui-procède-du-Père qui-avec-le-Père-et-le-Fils-est-adoré-et-glorifié qui-a-parlé-par-les-prophètes", "acceptedAnswers": ["qui-donne-la-vie qui-procède-du-Père qui-avec-le-Père-et-le-Fils-est-adoré-et-glorifié qui-a-parlé-par-les-prophètes"], "explanation": "Il donne la vie, il procède, il est adoré, il a parlé.", "instruction": "Remets dans l''ordre.", "tokens": ["qui-a-parlé-par-les-prophètes", "qui-avec-le-Père-et-le-Fils-est-adoré-et-glorifié", "qui-procède-du-Père", "qui-donne-la-vie"], "id": "eg.l811.e12", "pool": "lesson", "lessonId": "eg.l811", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l811.e13', 'eg', 'eg.l811', 'eg.v.c08_engendre_non_cree', array['eg.v.c08_engendre_non_cree','eg.g811.saint_esprit']::text[], 'fill_blank', 'lesson', 'Le Fils est « engendré, non ___ » : il n''est pas une créature.', array['créé']::text[], 'L''Esprit procède, le Fils est engendré : aucun des deux n''est créé.', 2, '{"unitIds": ["eg.v.c08_engendre_non_cree", "eg.g811.saint_esprit"], "type": "fill_blank", "difficulty": 2, "prompt": "Le Fils est « engendré, non ___ » : il n''est pas une créature.", "promptLanguage": "fr", "answer": "créé", "acceptedAnswers": ["créé"], "explanation": "L''Esprit procède, le Fils est engendré : aucun des deux n''est créé.", "instruction": "Complète la phrase.", "options": ["adopté", "caché", "perdu", "créé"], "id": "eg.l811.e13", "pool": "lesson", "lessonId": "eg.l811", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l811.e14', 'eg', 'eg.l811', 'eg.v.c08_dieu_le_pere', array['eg.v.c08_dieu_le_pere','eg.g811.saint_esprit','eg.v.c08_procession']::text[], 'match', 'lesson', 'Le Père, le Fils, l''Esprit : qui fait quoi ?', '{}'::text[], 'Un Père, un Fils engendré, un Esprit qui procède.', 2, '{"unitIds": ["eg.v.c08_dieu_le_pere", "eg.g811.saint_esprit", "eg.v.c08_procession"], "type": "match", "difficulty": 2, "prompt": "Le Père, le Fils, l''Esprit : qui fait quoi ?", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Un Père, un Fils engendré, un Esprit qui procède.", "instruction": "Associe.", "pairs": [{"left": "le Fils", "right": "est engendré"}, {"left": "l''Esprit", "right": "procède"}, {"left": "le Père", "right": "est la seule source"}], "id": "eg.l811.e14", "pool": "lesson", "lessonId": "eg.l811", "skill": "recognition", "answer": "le Fils = est engendré ; l''Esprit = procède ; le Père = est la seule source"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
