insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l814.e13', 'eg', 'eg.l814', 'eg.v.c04_arius', array['eg.v.c04_arius','eg.v.c04_macedonius','eg.v.c04_apollinaire','eg.v.c01_docetisme','eg.g814.bilan_du_credo']::text[], 'match', 'lesson', 'Chaque erreur, sa phrase du Credo.', '{}'::text[], 'Chaque erreur a sa porte fermée dans le Credo.', 3, '{"unitIds": ["eg.v.c04_arius", "eg.v.c04_macedonius", "eg.v.c04_apollinaire", "eg.v.c01_docetisme", "eg.g814.bilan_du_credo"], "type": "match", "difficulty": 3, "prompt": "Chaque erreur, sa phrase du Credo.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Chaque erreur a sa porte fermée dans le Credo.", "instruction": "Associe.", "pairs": [{"left": "Arius", "right": "le Fils est une créature"}, {"left": "Macédonius", "right": "l''Esprit est une créature"}, {"left": "Apollinaire", "right": "pas d''âme humaine"}, {"left": "les docètes", "right": "un corps apparent"}], "id": "eg.l814.e13", "pool": "lesson", "lessonId": "eg.l814", "skill": "recognition", "answer": "Arius = le Fils est une créature ; Macédonius = l''Esprit est une créature ; Apollinaire = pas d''âme humaine ; les docètes = un corps apparent"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l814.e14', 'eg', 'eg.l814', 'eg.v.c08_regne_sans_fin', array['eg.v.c08_regne_sans_fin','eg.g814.bilan_du_credo']::text[], 'mcq', 'lesson', 'Quelle phrase date de 381 et non de 325 ?', array['Son règne n''aura pas de fin']::text[], 'À Nicée, le texte s''arrêtait à « et en l''Esprit Saint ».', 2, '{"unitIds": ["eg.v.c08_regne_sans_fin", "eg.g814.bilan_du_credo"], "type": "mcq", "difficulty": 2, "prompt": "Quelle phrase date de 381 et non de 325 ?", "promptLanguage": "fr", "answer": "Son règne n''aura pas de fin", "acceptedAnswers": ["Son règne n''aura pas de fin"], "explanation": "À Nicée, le texte s''arrêtait à « et en l''Esprit Saint ».", "instruction": "Choisis la bonne réponse.", "options": ["Lumière de Lumière, vrai Dieu de vrai Dieu", "Son règne n''aura pas de fin", "consubstantiel au Père, par qui tout a été fait", "engendré du Père avant tous les siècles"], "id": "eg.l814.e14", "pool": "lesson", "lessonId": "eg.l814", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l814.e15', 'eg', 'eg.l814', 'eg.g814.bilan_du_credo', array['eg.g814.bilan_du_credo','eg.v.c08_trois_blocs']::text[], 'mcq', 'lesson', 'Pourquoi dit-on que le Credo n''est pas de la poésie ?', array['Parce que chaque phrase ferme une porte à une erreur']::text[], 'Chaque mot a été choisi contre une erreur précise.', 3, '{"unitIds": ["eg.g814.bilan_du_credo", "eg.v.c08_trois_blocs"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi dit-on que le Credo n''est pas de la poésie ?", "promptLanguage": "fr", "answer": "Parce que chaque phrase ferme une porte à une erreur", "acceptedAnswers": ["Parce que chaque phrase ferme une porte à une erreur"], "explanation": "Chaque mot a été choisi contre une erreur précise.", "instruction": "Choisis la bonne réponse.", "options": ["Parce qu''il est trop court pour rimer avec le chant", "Parce qu''il vient seulement de l''Église de Rome", "Parce que chaque phrase ferme une porte à une erreur", "Parce qu''on ne le chante jamais dans l''Église"], "id": "eg.l814.e15", "pool": "lesson", "lessonId": "eg.l814", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l814.e16', 'eg', 'eg.l814', 'eg.v.c04_macedonius', array['eg.v.c04_macedonius','eg.g814.bilan_du_credo']::text[], 'mcq', 'lesson', 'Pourquoi l''article de l''Esprit est-il plus long à Constantinople qu''à Nicée ?', array['Parce que Macédonius niait la divinité de l''Esprit']::text[], 'Comme pour le Fils avec Arius, il fallait dire précisément qui est l''Esprit.', 3, '{"unitIds": ["eg.v.c04_macedonius", "eg.g814.bilan_du_credo"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi l''article de l''Esprit est-il plus long à Constantinople qu''à Nicée ?", "promptLanguage": "fr", "answer": "Parce que Macédonius niait la divinité de l''Esprit", "acceptedAnswers": ["Parce que Macédonius niait la divinité de l''Esprit"], "explanation": "Comme pour le Fils avec Arius, il fallait dire précisément qui est l''Esprit.", "instruction": "Choisis la bonne réponse.", "options": ["Parce que Nicée avait complètement oublié l''Esprit", "Parce que l''empereur le voulait ainsi", "Parce que l''Esprit est plus grand que le Fils", "Parce que Macédonius niait la divinité de l''Esprit"], "id": "eg.l814.e16", "pool": "lesson", "lessonId": "eg.l814", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l901.e01', 'eg', 'eg.l901', 'eg.g901.signe_et_grace', array['eg.g901.signe_et_grace','eg.v.c09_sacrement']::text[], 'mcq', 'lesson', 'Un sacrement est un signe visible qui donne quoi ?', array['une grâce invisible']::text[], 'Visible d''un côté, invisible de l''autre : c''est toute l''idée.', 1, '{"id": "eg.l901.e01", "unitIds": ["eg.g901.signe_et_grace", "eg.v.c09_sacrement"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Un sacrement est un signe visible qui donne quoi ?", "promptLanguage": "fr", "answer": "une grâce invisible", "acceptedAnswers": ["une grâce invisible"], "explanation": "Visible d''un côté, invisible de l''autre : c''est toute l''idée.", "options": ["une grâce invisible", "une récompense visible", "un simple souvenir"], "step": 1, "pool": "lesson", "lessonId": "eg.l901", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l901.e02', 'eg', 'eg.l901', 'eg.g901.signe_et_grace', array['eg.g901.signe_et_grace','eg.v.c09_sacrement']::text[], 'mcq', 'lesson', 'Quel autre nom l''Église copte donne-t-elle à un sacrement ?', array['un mystère']::text[], 'Le mot « mystère » dit que Dieu agit au-delà de ce qu''on voit.', 1, '{"id": "eg.l901.e02", "unitIds": ["eg.g901.signe_et_grace", "eg.v.c09_sacrement"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel autre nom l''Église copte donne-t-elle à un sacrement ?", "promptLanguage": "fr", "answer": "un mystère", "acceptedAnswers": ["un mystère"], "explanation": "Le mot « mystère » dit que Dieu agit au-delà de ce qu''on voit.", "options": ["un symbole", "un mystère", "une fête"], "step": 1, "pool": "lesson", "lessonId": "eg.l901", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l901.e03', 'eg', 'eg.l901', 'eg.g901.signe_et_grace', array['eg.g901.signe_et_grace','eg.v.c09_grace']::text[], 'mcq', 'lesson', 'La grâce, c''est…', array['un don gratuit de Dieu']::text[], 'On ne la gagne pas : on la reçoit, comme un cadeau.', 1, '{"id": "eg.l901.e03", "unitIds": ["eg.g901.signe_et_grace", "eg.v.c09_grace"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "La grâce, c''est…", "promptLanguage": "fr", "answer": "un don gratuit de Dieu", "acceptedAnswers": ["un don gratuit de Dieu"], "explanation": "On ne la gagne pas : on la reçoit, comme un cadeau.", "options": ["un salaire pour nos efforts", "une récompense pour les prêtres", "un don gratuit de Dieu"], "step": 2, "pool": "lesson", "lessonId": "eg.l901", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l901.e04', 'eg', 'eg.l901', 'eg.g901.signe_et_grace', array['eg.g901.signe_et_grace','eg.v.c09_signe_visible']::text[], 'mcq', 'lesson', 'Vrai ou faux : le signe d''un sacrement est seulement décoratif.', array['Faux']::text[], 'Le signe n''est pas décoratif : par lui, Dieu agit vraiment.', 1, '{"id": "eg.l901.e04", "unitIds": ["eg.g901.signe_et_grace", "eg.v.c09_signe_visible"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Vrai ou faux : le signe d''un sacrement est seulement décoratif.", "promptLanguage": "fr", "answer": "Faux", "acceptedAnswers": ["Faux"], "explanation": "Le signe n''est pas décoratif : par lui, Dieu agit vraiment.", "options": ["Vrai", "Faux"], "step": 2, "pool": "lesson", "lessonId": "eg.l901", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l901.e05', 'eg', 'eg.l901', 'eg.g901.signe_et_grace', array['eg.g901.signe_et_grace','eg.v.c09_sacrement']::text[], 'mcq', 'lesson', 'Pourquoi Dieu agit-il par des choses qu''on touche ?', array['Le Christ a pris un corps']::text[], 'Le Christ s''est fait homme : il a gardé cette façon d''agir, avec des choses concrètes.', 1, '{"id": "eg.l901.e05", "unitIds": ["eg.g901.signe_et_grace", "eg.v.c09_sacrement"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi Dieu agit-il par des choses qu''on touche ?", "promptLanguage": "fr", "answer": "Le Christ a pris un corps", "acceptedAnswers": ["Le Christ a pris un corps"], "explanation": "Le Christ s''est fait homme : il a gardé cette façon d''agir, avec des choses concrètes.", "options": ["Le Christ a pris un corps", "L''eau possède un pouvoir magique", "Les prêtres l''ont décidé"], "step": 3, "pool": "lesson", "lessonId": "eg.l901", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l901.e06', 'eg', 'eg.l901', 'eg.g901.signe_et_grace', array['eg.g901.signe_et_grace','eg.v.c09_sacrement']::text[], 'mcq', 'lesson', 'Quelle parole du Christ fonde le baptême ?', array['Baptisez-les au nom du Père, du Fils et du Saint-Esprit']::text[], 'Les deux autres paroles fondent l''eucharistie et le mariage. Chaque sacrement a la sienne.', 1, '{"id": "eg.l901.e06", "unitIds": ["eg.g901.signe_et_grace", "eg.v.c09_sacrement"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle parole du Christ fonde le baptême ?", "promptLanguage": "fr", "answer": "Baptisez-les au nom du Père, du Fils et du Saint-Esprit", "acceptedAnswers": ["Baptisez-les au nom du Père, du Fils et du Saint-Esprit"], "explanation": "Les deux autres paroles fondent l''eucharistie et le mariage. Chaque sacrement a la sienne.", "options": ["Prenez, mangez, ceci est mon corps donné pour vous", "Baptisez-les au nom du Père, du Fils et du Saint-Esprit", "Ce que Dieu a uni, que l''homme ne le sépare pas"], "step": 4, "pool": "lesson", "lessonId": "eg.l901", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l901.e07', 'eg', 'eg.l901', 'eg.g901.signe_et_grace', array['eg.g901.signe_et_grace','eg.v.c09_sacrement']::text[], 'mcq', 'lesson', 'Qui donne la grâce pendant un sacrement ?', array['le Christ']::text[], 'Le prêtre est son serviteur : il célèbre, mais c''est le Christ qui agit.', 1, '{"id": "eg.l901.e07", "unitIds": ["eg.g901.signe_et_grace", "eg.v.c09_sacrement"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui donne la grâce pendant un sacrement ?", "promptLanguage": "fr", "answer": "le Christ", "acceptedAnswers": ["le Christ"], "explanation": "Le prêtre est son serviteur : il célèbre, mais c''est le Christ qui agit.", "options": ["le prêtre", "le diacre", "le Christ"], "step": 5, "pool": "lesson", "lessonId": "eg.l901", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l901.e08', 'eg', 'eg.l901', 'eg.g901.signe_et_grace', array['eg.g901.signe_et_grace','eg.v.c09_sacrement']::text[], 'mcq', 'lesson', 'Combien y a-t-il de sacrements dans l''Église copte ?', array['sept']::text[], 'Sept : trois qui ne se répètent pas, et quatre qui reviennent ou se vivent à part.', 1, '{"id": "eg.l901.e08", "unitIds": ["eg.g901.signe_et_grace", "eg.v.c09_sacrement"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Combien y a-t-il de sacrements dans l''Église copte ?", "promptLanguage": "fr", "answer": "sept", "acceptedAnswers": ["sept"], "explanation": "Sept : trois qui ne se répètent pas, et quatre qui reviennent ou se vivent à part.", "options": ["sept", "deux", "douze"], "step": 6, "pool": "lesson", "lessonId": "eg.l901", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l901.e09', 'eg', 'eg.l901', 'eg.g901.signe_et_grace', array['eg.g901.signe_et_grace','eg.v.c09_grace','eg.v.c09_signe_visible']::text[], 'match', 'lesson', 'Chaque mot a sa définition.', '{}'::text[], 'La grâce se reçoit, le signe se voit, le prêtre sert.', 2, '{"id": "eg.l901.e09", "unitIds": ["eg.g901.signe_et_grace", "eg.v.c09_grace", "eg.v.c09_signe_visible"], "type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Chaque mot a sa définition.", "promptLanguage": "fr", "acceptedAnswers": [], "pairs": [{"left": "la grâce", "right": "un don gratuit de Dieu"}, {"left": "le prêtre", "right": "le serviteur du Christ"}, {"left": "le signe", "right": "l''eau, l''huile, le pain, les mains"}], "explanation": "La grâce se reçoit, le signe se voit, le prêtre sert.", "pool": "lesson", "lessonId": "eg.l901", "skill": "recognition", "answer": "la grâce = un don gratuit de Dieu ; le prêtre = le serviteur du Christ ; le signe = l''eau, l''huile, le pain, les mains"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
