insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l905.e11', 'eg', 'eg.l905', 'eg.g905.myron', array['eg.g905.myron','eg.g902.bapteme_naissance']::text[], 'mcq', 'lesson', 'Baptême : l''eau. Confirmation : quoi ?', array['l''huile']::text[], 'Le premier lave, le second scelle.', 2, '{"id": "eg.l905.e11", "unitIds": ["eg.g905.myron", "eg.g902.bapteme_naissance"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Baptême : l''eau. Confirmation : quoi ?", "promptLanguage": "fr", "answer": "l''huile", "acceptedAnswers": ["l''huile"], "explanation": "Le premier lave, le second scelle.", "options": ["l''huile", "le pain", "le feu"], "pool": "lesson", "lessonId": "eg.l905", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l905.e12', 'eg', 'eg.l905', 'eg.g905.myron', array['eg.g905.myron','eg.v.c09_saint_myron','eg.v.c09_bapteme']::text[], 'mcq', 'lesson', 'Qu''est-ce que le prêtre verse dans l''eau du baptême, en forme de croix ?', array['du saint myron']::text[], 'Le myron sert déjà à bénir l''eau.', 2, '{"id": "eg.l905.e12", "unitIds": ["eg.g905.myron", "eg.v.c09_saint_myron", "eg.v.c09_bapteme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''est-ce que le prêtre verse dans l''eau du baptême, en forme de croix ?", "promptLanguage": "fr", "answer": "du saint myron", "acceptedAnswers": ["du saint myron"], "explanation": "Le myron sert déjà à bénir l''eau.", "options": ["du vin rouge de la messe", "du saint myron", "du sel et de l''encens"], "pool": "lesson", "lessonId": "eg.l905", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l905.e13', 'eg', 'eg.l905', 'eg.g905.myron', array['eg.g905.myron','eg.v.c09_signe_visible','eg.v.c09_confirmation']::text[], 'mcq', 'lesson', 'Le myron est le signe visible. Quelle est la grâce invisible ?', array['le sceau du Saint-Esprit']::text[], 'Comme pour tout sacrement : un signe qu''on voit, une grâce qu''on ne voit pas.', 2, '{"id": "eg.l905.e13", "unitIds": ["eg.g905.myron", "eg.v.c09_signe_visible", "eg.v.c09_confirmation"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Le myron est le signe visible. Quelle est la grâce invisible ?", "promptLanguage": "fr", "answer": "le sceau du Saint-Esprit", "acceptedAnswers": ["le sceau du Saint-Esprit"], "explanation": "Comme pour tout sacrement : un signe qu''on voit, une grâce qu''on ne voit pas.", "options": ["la guérison du corps", "le pardon par le prêtre", "le sceau du Saint-Esprit"], "pool": "lesson", "lessonId": "eg.l905", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
