insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l905.e15', 'eg', 'eg.l905', 'eg.g905.myron', array['eg.g905.myron','eg.v.c09_imposition_des_mains']::text[], 'mcq', 'lesson', 'Pourquoi l''Église utilise-t-elle de l''huile consacrée plutôt que l''imposition des mains de chaque apôtre ?', array['Les apôtres ne pouvaient aller vers chaque fidèle']::text[], 'Il fallait un moyen qui traverse les siècles et les pays : l''huile consacrée.', 3, '{"id": "eg.l905.e15", "unitIds": ["eg.g905.myron", "eg.v.c09_imposition_des_mains"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi l''Église utilise-t-elle de l''huile consacrée plutôt que l''imposition des mains de chaque apôtre ?", "promptLanguage": "fr", "answer": "Les apôtres ne pouvaient aller vers chaque fidèle", "acceptedAnswers": ["Les apôtres ne pouvaient aller vers chaque fidèle"], "explanation": "Il fallait un moyen qui traverse les siècles et les pays : l''huile consacrée.", "options": ["L''imposition des mains a été interdite par un concile", "Les apôtres ne pouvaient aller vers chaque fidèle", "L''huile est plus ancienne que les apôtres eux-mêmes"], "pool": "lesson", "lessonId": "eg.l905", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
