insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l907.e10', 'eg', 'eg.l907', 'eg.g907.derniere_cene', array['eg.g907.derniere_cene']::text[], 'match', 'lesson', 'Les mots de la Cène, un par un.', '{}'::text[], 'Un mot grec, un soir, une foi, une promesse.', 2, '{"id": "eg.l907.e10", "unitIds": ["eg.g907.derniere_cene"], "type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Les mots de la Cène, un par un.", "promptLanguage": "fr", "acceptedAnswers": [], "pairs": [{"left": "eucharistie", "right": "action de grâce"}, {"left": "la dernière Cène", "right": "le soir du Jeudi saint"}, {"left": "présence réelle", "right": "le pain et le vin deviennent le Corps et le Sang"}, {"left": "Jn 6, 35", "right": "le pain de vie"}], "explanation": "Un mot grec, un soir, une foi, une promesse.", "pool": "lesson", "lessonId": "eg.l907", "skill": "recognition", "answer": "eucharistie = action de grâce ; la dernière Cène = le soir du Jeudi saint ; présence réelle = le pain et le vin deviennent le Corps et le Sang ; Jn 6, 35 = le pain de vie"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
