insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l909.e11', 'eg', 'eg.l909', 'eg.g909.confession', array['eg.g909.confession','eg.g902.bapteme_naissance','eg.v.c09_confession']::text[], 'mcq', 'lesson', 'Le baptême pardonne le péché originel. Quel sacrement pardonne ensuite les péchés personnels commis plus tard ?', array['la confession']::text[], 'Le baptême ne se répète pas ; la confession, si.', 2, '{"id": "eg.l909.e11", "unitIds": ["eg.g909.confession", "eg.g902.bapteme_naissance", "eg.v.c09_confession"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Le baptême pardonne le péché originel. Quel sacrement pardonne ensuite les péchés personnels commis plus tard ?", "promptLanguage": "fr", "answer": "la confession", "acceptedAnswers": ["la confession"], "explanation": "Le baptême ne se répète pas ; la confession, si.", "options": ["la confirmation", "la confession", "le mariage"], "pool": "lesson", "lessonId": "eg.l909", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
