insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l909.e14', 'eg', 'eg.l909', 'eg.g909.confession', array['eg.g909.confession','eg.v.c09_confession']::text[], 'mcq', 'lesson', 'Pourquoi la confession se répète-t-elle, alors que le baptême non ?', array['On pèche encore après le baptême']::text[], 'Le baptême est une naissance ; la confession soigne les chutes de la vie.', 3, '{"id": "eg.l909.e14", "unitIds": ["eg.g909.confession", "eg.v.c09_confession"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi la confession se répète-t-elle, alors que le baptême non ?", "promptLanguage": "fr", "answer": "On pèche encore après le baptême", "acceptedAnswers": ["On pèche encore après le baptême"], "explanation": "Le baptême est une naissance ; la confession soigne les chutes de la vie.", "options": ["Le pardon s''use comme un vêtement", "On pèche encore après le baptême", "Le prêtre change d''avis chaque année"], "pool": "lesson", "lessonId": "eg.l909", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
