insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l911.e10', 'eg', 'eg.l911', 'eg.g911.qandil', array['eg.g911.qandil']::text[], 'match', 'lesson', 'La lampe, mot par mot.', '{}'::text[], 'Un nom arabe, un verset, un mot grec, un nombre.', 2, '{"id": "eg.l911.e10", "unitIds": ["eg.g911.qandil"], "type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "La lampe, mot par mot.", "promptLanguage": "fr", "acceptedAnswers": [], "pairs": [{"left": "qandil", "right": "la lampe"}, {"left": "Jc 5, 14-15", "right": "les anciens oignent d''huile"}, {"left": "presbyteroi", "right": "prêtre"}, {"left": "sept", "right": "le nombre de la plénitude"}], "explanation": "Un nom arabe, un verset, un mot grec, un nombre.", "pool": "lesson", "lessonId": "eg.l911", "skill": "recognition", "answer": "qandil = la lampe ; Jc 5, 14-15 = les anciens oignent d''huile ; presbyteroi = prêtre ; sept = le nombre de la plénitude"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
