insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l912.e09', 'eg', 'eg.l912', 'eg.g912.mariage', array['eg.g912.mariage']::text[], 'match', 'lesson', 'Le mariage, mot par mot.', '{}'::text[], 'Un miracle, un rite, un verset, un engagement.', 2, '{"id": "eg.l912.e09", "unitIds": ["eg.g912.mariage"], "type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Le mariage, mot par mot.", "promptLanguage": "fr", "acceptedAnswers": [], "pairs": [{"left": "Cana", "right": "l''eau changée en vin"}, {"left": "les couronnes", "right": "roi et reine du foyer"}, {"left": "Ép 5, 32", "right": "ce mystère est grand"}, {"left": "les fiançailles", "right": "l''échange de bagues"}], "explanation": "Un miracle, un rite, un verset, un engagement.", "pool": "lesson", "lessonId": "eg.l912", "skill": "recognition", "answer": "Cana = l''eau changée en vin ; les couronnes = roi et reine du foyer ; Ép 5, 32 = ce mystère est grand ; les fiançailles = l''échange de bagues"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
