insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1001.e05', 'eg', 'eg.l1001', 'eg.g1001.orientation_est', array['eg.g1001.orientation_est']::text[], 'mcq', 'lesson', 'Quel jardin est planté à l''orient ?', array['l''Éden']::text[], 'L''Éden, le paradis du début : on regarde vers l''est comme on regarde vers lui.', 1, '{"id": "eg.l1001.e05", "unitIds": ["eg.g1001.orientation_est"], "type": "mcq", "difficulty": 1, "prompt": "Quel jardin est planté à l''orient ?", "promptLanguage": "fr", "answer": "l''Éden", "acceptedAnswers": ["l''Éden"], "explanation": "L''Éden, le paradis du début : on regarde vers l''est comme on regarde vers lui.", "instruction": "Choisis la bonne réponse.", "step": 3, "options": ["Gethsémani", "l''Éden", "le jardin des Oliviers"], "pool": "lesson", "lessonId": "eg.l1001", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1001.e06', 'eg', 'eg.l1001', 'eg.g1001.orientation_est', array['eg.g1001.orientation_est']::text[], 'mcq', 'lesson', 'Le Christ reviendra comme...', array['l''éclair']::text[], 'Matthieu 24, 27 : un éclair qui part de l''orient. D''où l''attente vers l''est.', 1, '{"id": "eg.l1001.e06", "unitIds": ["eg.g1001.orientation_est"], "type": "mcq", "difficulty": 1, "prompt": "Le Christ reviendra comme...", "promptLanguage": "fr", "answer": "l''éclair", "acceptedAnswers": ["l''éclair"], "explanation": "Matthieu 24, 27 : un éclair qui part de l''orient. D''où l''attente vers l''est.", "instruction": "Choisis la bonne réponse.", "step": 3, "options": ["la neige", "la rosée", "l''éclair"], "pool": "lesson", "lessonId": "eg.l1001", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
