insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1001.e15', 'eg', 'eg.l1001', 'eg.g1001.orientation_est', array['eg.g1001.orientation_est','eg.v.c10_arche_de_noe']::text[], 'mcq', 'lesson', 'Pourquoi la forme d''arche de Noé convient-elle à une église ?', array['Ceux qui y entrent sont sauvés, comme Noé']::text[], 'Au déluge, l''arche a sauvé ceux qui étaient dedans. Dans l''Église, c''est le Christ qui sauve.', 3, '{"id": "eg.l1001.e15", "unitIds": ["eg.g1001.orientation_est", "eg.v.c10_arche_de_noe"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi la forme d''arche de Noé convient-elle à une église ?", "promptLanguage": "fr", "answer": "Ceux qui y entrent sont sauvés, comme Noé", "acceptedAnswers": ["Ceux qui y entrent sont sauvés, comme Noé"], "explanation": "Au déluge, l''arche a sauvé ceux qui étaient dedans. Dans l''Église, c''est le Christ qui sauve.", "instruction": "Choisis la bonne réponse.", "options": ["Ceux qui y entrent sont sauvés, comme Noé", "Elle flotte toujours au-dessus de l''eau", "Noé a construit la toute première église"], "pool": "lesson", "lessonId": "eg.l1001", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1001.e16', 'eg', 'eg.l1001', 'eg.g1001.orientation_est', array['eg.g1001.orientation_est','eg.v.c10_orientation_est']::text[], 'mcq', 'lesson', 'Un visiteur demande : « Pourquoi l''est et pas le nord ? » Quelle réponse est juste ?', array['Le soleil levant y est une image du Christ']::text[], 'Le soleil levant, c''est le Christ lumière. Rien n''est un hasard dans le plan d''une église.', 3, '{"id": "eg.l1001.e16", "unitIds": ["eg.g1001.orientation_est", "eg.v.c10_orientation_est"], "type": "mcq", "difficulty": 3, "prompt": "Un visiteur demande : « Pourquoi l''est et pas le nord ? » Quelle réponse est juste ?", "promptLanguage": "fr", "answer": "Le soleil levant y est une image du Christ", "acceptedAnswers": ["Le soleil levant y est une image du Christ"], "explanation": "Le soleil levant, c''est le Christ lumière. Rien n''est un hasard dans le plan d''une église.", "instruction": "Choisis la bonne réponse.", "options": ["C''est le côté où se trouve la ville voisine", "Le soleil levant y est une image du Christ", "C''est un simple hasard de construction"], "pool": "lesson", "lessonId": "eg.l1001", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
