insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1004.e15', 'eg', 'eg.l1004', 'eg.g1004.symboles', array['eg.g1004.symboles','eg.v.c10_adoration']::text[], 'mcq', 'lesson', 'Pourquoi l''Église utilise-t-elle des icônes alors que Dieu seul est adoré ?', array['Parce que Dieu s''est rendu visible en Jésus-Christ']::text[], 'Dieu s''est fait voir en Jésus-Christ : l''icône est une fenêtre vers lui, pas une idole.', 3, '{"id": "eg.l1004.e15", "unitIds": ["eg.g1004.symboles", "eg.v.c10_adoration"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi l''Église utilise-t-elle des icônes alors que Dieu seul est adoré ?", "promptLanguage": "fr", "answer": "Parce que Dieu s''est rendu visible en Jésus-Christ", "acceptedAnswers": ["Parce que Dieu s''est rendu visible en Jésus-Christ"], "explanation": "Dieu s''est fait voir en Jésus-Christ : l''icône est une fenêtre vers lui, pas une idole.", "instruction": "Choisis la bonne réponse.", "options": ["Parce que l''icône est une idole très puissante", "Parce que Dieu s''est rendu visible en Jésus-Christ", "Parce que le décor attire beaucoup de visiteurs"], "pool": "lesson", "lessonId": "eg.l1004", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1004.e16', 'eg', 'eg.l1004', 'eg.g1004.symboles', array['eg.g1004.symboles','eg.v.c10_lampe_a_huile']::text[], 'mcq', 'lesson', 'Quelle phrase résume le sens d''une lampe qui reste allumée devant une icône ?', array['Une flamme qui veille, c''est une prière qui continue']::text[], 'La lampe rappelle la lumière du Christ et la prière qui ne s''arrête pas.', 3, '{"id": "eg.l1004.e16", "unitIds": ["eg.g1004.symboles", "eg.v.c10_lampe_a_huile"], "type": "mcq", "difficulty": 3, "prompt": "Quelle phrase résume le sens d''une lampe qui reste allumée devant une icône ?", "promptLanguage": "fr", "answer": "Une flamme qui veille, c''est une prière qui continue", "acceptedAnswers": ["Une flamme qui veille, c''est une prière qui continue"], "explanation": "La lampe rappelle la lumière du Christ et la prière qui ne s''arrête pas.", "instruction": "Choisis la bonne réponse.", "options": ["Une flamme qui s''éteint, c''est un jour qui finit", "Une flamme qui chauffe, c''est une salle qui accueille", "Une flamme qui veille, c''est une prière qui continue"], "pool": "lesson", "lessonId": "eg.l1004", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
