insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1005.e10', 'eg', 'eg.l1005', 'eg.g1005.haikal', array['eg.g1005.haikal']::text[], 'match', 'lesson', 'Encore une fois : chaque mot a sa définition.', '{}'::text[], 'Le haikal, l''autel, le myron, les pieds nus : le cœur de l''église en quatre mots.', 2, '{"id": "eg.l1005.e10", "unitIds": ["eg.g1005.haikal"], "type": "match", "difficulty": 2, "prompt": "Encore une fois : chaque mot a sa définition.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Le haikal, l''autel, le myron, les pieds nus : le cœur de l''église en quatre mots.", "instruction": "Associe.", "pairs": [{"left": "le haikal", "right": "temple"}, {"left": "l''autel", "right": "le tombeau du Christ"}, {"left": "le myron", "right": "l''huile sainte"}, {"left": "entrer déchaussé", "right": "terre sainte"}], "pool": "lesson", "lessonId": "eg.l1005", "skill": "recognition", "answer": "le haikal = temple ; l''autel = le tombeau du Christ ; le myron = l''huile sainte ; entrer déchaussé = terre sainte"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
