insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1007.e13', 'eg', 'eg.l1007', 'eg.g1007.diaconat', array['eg.g1007.diaconat','eg.v.c03_hierarchie']::text[], 'mcq', 'lesson', 'Les trois degrés sont évêque, prêtre, diacre. Les cinq rangs, du psalte à l''archidiacre, forment quoi ?', array['le diaconat']::text[], 'Le diaconat compte cinq rangs : c''est une échelle à l''intérieur du dernier degré.', 2, '{"id": "eg.l1007.e13", "unitIds": ["eg.g1007.diaconat", "eg.v.c03_hierarchie"], "type": "mcq", "difficulty": 2, "prompt": "Les trois degrés sont évêque, prêtre, diacre. Les cinq rangs, du psalte à l''archidiacre, forment quoi ?", "promptLanguage": "fr", "answer": "le diaconat", "acceptedAnswers": ["le diaconat"], "explanation": "Le diaconat compte cinq rangs : c''est une échelle à l''intérieur du dernier degré.", "instruction": "Choisis la bonne réponse.", "options": ["le diaconat", "l''épiscopat", "le sacerdoce"], "pool": "lesson", "lessonId": "eg.l1007", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
