insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1009.e11', 'eg', 'eg.l1009', 'eg.g1009.choisir_pape', array['eg.g1009.choisir_pape']::text[], 'match', 'lesson', 'Qui fait quoi dans le choix du pape ?', '{}'::text[], 'L''homme prépare, l''enfant tire, Dieu désigne.', 2, '{"id": "eg.l1009.e11", "unitIds": ["eg.g1009.choisir_pape"], "type": "match", "difficulty": 2, "prompt": "Qui fait quoi dans le choix du pape ?", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "L''homme prépare, l''enfant tire, Dieu désigne.", "instruction": "Associe.", "pairs": [{"left": "une assemblée d''électeurs", "right": "vote"}, {"left": "un enfant aux yeux bandés", "right": "tire un seul nom"}, {"left": "les trois noms", "right": "placés sur l''autel"}, {"left": "Dieu", "right": "désigne le pape"}], "pool": "lesson", "lessonId": "eg.l1009", "skill": "recognition", "answer": "une assemblée d''électeurs = vote ; un enfant aux yeux bandés = tire un seul nom ; les trois noms = placés sur l''autel ; Dieu = désigne le pape"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
