insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1009.e13', 'eg', 'eg.l1009', 'eg.g1005.haikal', array['eg.g1005.haikal','eg.g1009.choisir_pape']::text[], 'mcq', 'lesson', 'Les trois noms sont placés sur l''autel. Que représente l''autel ?', array['le tombeau du Christ']::text[], 'L''autel est le tombeau du Christ et la table où il se donne : c''est là que Dieu est invité à choisir.', 2, '{"id": "eg.l1009.e13", "unitIds": ["eg.g1005.haikal", "eg.g1009.choisir_pape"], "type": "mcq", "difficulty": 2, "prompt": "Les trois noms sont placés sur l''autel. Que représente l''autel ?", "promptLanguage": "fr", "answer": "le tombeau du Christ", "acceptedAnswers": ["le tombeau du Christ"], "explanation": "L''autel est le tombeau du Christ et la table où il se donne : c''est là que Dieu est invité à choisir.", "instruction": "Choisis la bonne réponse.", "options": ["la tente de Moïse", "le tombeau du Christ", "le ciel"], "pool": "lesson", "lessonId": "eg.l1009", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1009.e14', 'eg', 'eg.l1009', 'eg.g1009.choisir_pape', array['eg.g1009.choisir_pape','eg.v.c01_cathedrale_saint_marc']::text[], 'mcq', 'lesson', 'Dans quelle cathédrale Tawadros II est-il intronisé ?', array['la cathédrale Saint-Marc du Caire']::text[], 'La grande cathédrale de l''Abbassiya, siège du pape.', 2, '{"id": "eg.l1009.e14", "unitIds": ["eg.g1009.choisir_pape", "eg.v.c01_cathedrale_saint_marc"], "type": "mcq", "difficulty": 2, "prompt": "Dans quelle cathédrale Tawadros II est-il intronisé ?", "promptLanguage": "fr", "answer": "la cathédrale Saint-Marc du Caire", "acceptedAnswers": ["la cathédrale Saint-Marc du Caire"], "explanation": "La grande cathédrale de l''Abbassiya, siège du pape.", "instruction": "Choisis la bonne réponse.", "options": ["le monastère Saint-Antoine", "le monastère Saint-Macaire", "la cathédrale Saint-Marc du Caire"], "pool": "lesson", "lessonId": "eg.l1009", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1009.e15', 'eg', 'eg.l1009', 'eg.g1009.choisir_pape', array['eg.g1009.choisir_pape','eg.v.c10_qora_haykaleya']::text[], 'mcq', 'lesson', 'Pourquoi le vote des électeurs ne suffit-il pas à désigner le pape ?', array['Il retient trois noms, et le sort tranche ensuite']::text[], 'Le vote prépare, le sort désigne : c''est ainsi que Dieu choisit.', 3, '{"id": "eg.l1009.e15", "unitIds": ["eg.g1009.choisir_pape", "eg.v.c10_qora_haykaleya"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi le vote des électeurs ne suffit-il pas à désigner le pape ?", "promptLanguage": "fr", "answer": "Il retient trois noms, et le sort tranche ensuite", "acceptedAnswers": ["Il retient trois noms, et le sort tranche ensuite"], "explanation": "Le vote prépare, le sort désigne : c''est ainsi que Dieu choisit.", "instruction": "Choisis la bonne réponse.", "options": ["Il retient trois noms, et le sort tranche ensuite", "Il retient un nom, et le pape le refuse", "Il retient douze noms, et l''empereur choisit"], "pool": "lesson", "lessonId": "eg.l1009", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
