insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1011.e12', 'eg', 'eg.l1011', 'eg.g1009.choisir_pape', array['eg.g1009.choisir_pape','eg.g1011.bilan']::text[], 'mcq', 'lesson', 'Dans le choix du pape, qui tire le nom sur l''autel ?', array['un enfant aux yeux bandés']::text[], 'Un enfant : pour que Dieu choisisse.', 2, '{"id": "eg.l1011.e12", "unitIds": ["eg.g1009.choisir_pape", "eg.g1011.bilan"], "type": "mcq", "difficulty": 2, "prompt": "Dans le choix du pape, qui tire le nom sur l''autel ?", "promptLanguage": "fr", "answer": "un enfant aux yeux bandés", "acceptedAnswers": ["un enfant aux yeux bandés"], "explanation": "Un enfant : pour que Dieu choisisse.", "instruction": "Choisis la bonne réponse.", "options": ["le plus ancien évêque", "un moine du désert", "un enfant aux yeux bandés"], "pool": "lesson", "lessonId": "eg.l1011", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1011.e13', 'eg', 'eg.l1011', 'eg.g1011.bilan', array['eg.g1011.bilan','eg.v.c10_clerge']::text[], 'mcq', 'lesson', 'Un visiteur remarque que le prêtre est marié et l''évêque non. Quelle explication est juste ?', array['Le prêtre se marie avant ; l''évêque est moine']::text[], 'Prêtre : marié avant. Évêque : moine, donc célibataire.', 3, '{"id": "eg.l1011.e13", "unitIds": ["eg.g1011.bilan", "eg.v.c10_clerge"], "type": "mcq", "difficulty": 3, "prompt": "Un visiteur remarque que le prêtre est marié et l''évêque non. Quelle explication est juste ?", "promptLanguage": "fr", "answer": "Le prêtre se marie avant ; l''évêque est moine", "acceptedAnswers": ["Le prêtre se marie avant ; l''évêque est moine"], "explanation": "Prêtre : marié avant. Évêque : moine, donc célibataire.", "instruction": "Choisis la bonne réponse.", "options": ["Le prêtre se marie avant ; l''évêque est moine", "Le prêtre peut se marier après son ordination", "Les évêques ne sont jamais choisis parmi les moines"], "pool": "lesson", "lessonId": "eg.l1011", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1011.e14', 'eg', 'eg.l1011', 'eg.g1010.moines', array['eg.g1010.moines','eg.g1011.bilan','eg.v.c10_moine']::text[], 'mcq', 'lesson', 'Pourquoi dit-on que le monastère nourrit toute la hiérarchie ?', array['Les évêques et le pape sortent des moines']::text[], 'Évêques et pape sont choisis parmi les moines : tout le sommet de l''Église vient du désert.', 3, '{"id": "eg.l1011.e14", "unitIds": ["eg.g1010.moines", "eg.g1011.bilan", "eg.v.c10_moine"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi dit-on que le monastère nourrit toute la hiérarchie ?", "promptLanguage": "fr", "answer": "Les évêques et le pape sortent des moines", "acceptedAnswers": ["Les évêques et le pape sortent des moines"], "explanation": "Évêques et pape sont choisis parmi les moines : tout le sommet de l''Église vient du désert.", "instruction": "Choisis la bonne réponse.", "options": ["Les moines préparent le pain de la liturgie", "Les évêques et le pape sortent des moines", "Les moines ordonnent tous les diacres"], "pool": "lesson", "lessonId": "eg.l1011", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
