insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1102.e11', 'eg', 'eg.l1102', 'eg.g1101.sept_fois', array['eg.g1101.sept_fois','eg.v.c11_heure_biblique','eg.g1102.prime_aube']::text[], 'mcq', 'lesson', 'À quelle heure d''aujourd''hui l''Esprit descend-il sur les apôtres, à la troisième heure ?', array['9 h']::text[], 'Troisième heure + 6 = 9 h.', 2, '{"id": "eg.l1102.e11", "unitIds": ["eg.g1101.sept_fois", "eg.v.c11_heure_biblique", "eg.g1102.prime_aube"], "type": "mcq", "difficulty": 2, "prompt": "À quelle heure d''aujourd''hui l''Esprit descend-il sur les apôtres, à la troisième heure ?", "promptLanguage": "fr", "answer": "9 h", "acceptedAnswers": ["9 h"], "explanation": "Troisième heure + 6 = 9 h.", "instruction": "Choisis la bonne réponse.", "options": ["6 h", "15 h", "9 h"], "pool": "lesson", "lessonId": "eg.l1102", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
