insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1102.e13', 'eg', 'eg.l1102', 'eg.g1102.prime_aube', array['eg.g1102.prime_aube']::text[], 'mcq', 'lesson', 'Il est 6 h du matin et tu te lèves : quelle heure prie-t-on et que rappelle-t-elle ?', array['Prime : la Résurrection']::text[], '6 h, c''est Prime, l''aube de la Résurrection.', 3, '{"id": "eg.l1102.e13", "unitIds": ["eg.g1102.prime_aube"], "type": "mcq", "difficulty": 3, "prompt": "Il est 6 h du matin et tu te lèves : quelle heure prie-t-on et que rappelle-t-elle ?", "promptLanguage": "fr", "answer": "Prime : la Résurrection", "acceptedAnswers": ["Prime : la Résurrection"], "explanation": "6 h, c''est Prime, l''aube de la Résurrection.", "instruction": "Choisis la bonne réponse.", "options": ["None : la mort du Christ", "Prime : la Résurrection", "Sexte : la crucifixion"], "pool": "lesson", "lessonId": "eg.l1102", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1102.e14', 'eg', 'eg.l1102', 'eg.g1102.prime_aube', array['eg.g1102.prime_aube','eg.v.c11_prime']::text[], 'mcq', 'lesson', 'Pourquoi le soleil qui se lève est-il une bonne image pour Prime ?', array['Il rappelle le Christ ressuscité']::text[], 'Comme le soleil sort de la nuit, le Christ sort du tombeau.', 3, '{"id": "eg.l1102.e14", "unitIds": ["eg.g1102.prime_aube", "eg.v.c11_prime"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi le soleil qui se lève est-il une bonne image pour Prime ?", "promptLanguage": "fr", "answer": "Il rappelle le Christ ressuscité", "acceptedAnswers": ["Il rappelle le Christ ressuscité"], "explanation": "Comme le soleil sort de la nuit, le Christ sort du tombeau.", "instruction": "Choisis la bonne réponse.", "options": ["Il annonce le repas du matin", "Il donne l''heure exacte du jour", "Il rappelle le Christ ressuscité"], "pool": "lesson", "lessonId": "eg.l1102", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
