insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1401.e06', 'eg', 'eg.l1401', 'eg.g1401.moise_le_noir', array['eg.g1401.moise_le_noir','eg.v.c14_moise_le_noir']::text[], 'mcq', 'lesson', 'Vrai ou faux : après les paroles de Moïse, les frères punissent le moine fautif.', array['Faux']::text[], 'Ils pardonnent : Moïse leur a rappelé qu''ils ont tous des fautes.', 1, '{"id": "eg.l1401.e06", "unitIds": ["eg.g1401.moise_le_noir", "eg.v.c14_moise_le_noir"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Vrai ou faux : après les paroles de Moïse, les frères punissent le moine fautif.", "promptLanguage": "fr", "answer": "Faux", "acceptedAnswers": ["Faux"], "options": ["Vrai", "Faux"], "explanation": "Ils pardonnent : Moïse leur a rappelé qu''ils ont tous des fautes.", "step": 3, "pool": "lesson", "lessonId": "eg.l1401", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
