insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1401.e10', 'eg', 'eg.l1401', 'eg.g1401.moise_le_noir', array['eg.g1401.moise_le_noir','eg.v.c14_moise_le_noir','eg.v.c04_saint_antoine','eg.v.c04_saint_pacome']::text[], 'match', 'lesson', 'Chaque Père du désert a sa spécialité.', '{}'::text[], 'Moïse ne juge pas, Antoine ouvre la route, Pacôme organise les monastères.', 2, '{"id": "eg.l1401.e10", "unitIds": ["eg.g1401.moise_le_noir", "eg.v.c14_moise_le_noir", "eg.v.c04_saint_antoine", "eg.v.c04_saint_pacome"], "type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Chaque Père du désert a sa spécialité.", "promptLanguage": "fr", "acceptedAnswers": [], "pairs": [{"left": "Moïse le Noir", "right": "le sac de sable troué"}, {"left": "saint Antoine", "right": "premier moine du monde"}, {"left": "Pacôme", "right": "la vie en communauté"}], "explanation": "Moïse ne juge pas, Antoine ouvre la route, Pacôme organise les monastères.", "pool": "lesson", "lessonId": "eg.l1401", "skill": "recognition", "answer": "Moïse le Noir = le sac de sable troué ; saint Antoine = premier moine du monde ; Pacôme = la vie en communauté"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
