insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1402.e09', 'eg', 'eg.l1402', 'eg.g1402.jean_arsene', array['eg.g1402.jean_arsene','eg.v.c14_jean_le_petit','eg.v.c14_arsene','eg.v.c14_moise_le_noir']::text[], 'match', 'lesson', 'Qui a fait quoi, au désert de Scété ?', '{}'::text[], 'Un bâton, un palais, un sac de sable : trois scènes à ne pas mélanger.', 2, '{"id": "eg.l1402.e09", "unitIds": ["eg.g1402.jean_arsene", "eg.v.c14_jean_le_petit", "eg.v.c14_arsene", "eg.v.c14_moise_le_noir"], "type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Qui a fait quoi, au désert de Scété ?", "promptLanguage": "fr", "acceptedAnswers": [], "pairs": [{"left": "Jean le Petit", "right": "arroser un bâton sec"}, {"left": "Arsène", "right": "quitter la cour de l''empereur"}, {"left": "Moïse le Noir", "right": "traîner un sac de sable troué"}], "explanation": "Un bâton, un palais, un sac de sable : trois scènes à ne pas mélanger.", "pool": "lesson", "lessonId": "eg.l1402", "skill": "recognition", "answer": "Jean le Petit = arroser un bâton sec ; Arsène = quitter la cour de l''empereur ; Moïse le Noir = traîner un sac de sable troué"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
