insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1403.e12', 'eg', 'eg.l1403', 'eg.g1403.bishoy_princes', array['eg.g1403.bishoy_princes','eg.v.c14_bishoy','eg.v.c14_maxime_domece','eg.v.c14_jean_le_petit','eg.v.c14_moise_le_noir']::text[], 'match', 'lesson', 'Chaque saint de Scété a son image.', '{}'::text[], 'Quatre histoires, quatre saints du même désert.', 2, '{"id": "eg.l1403.e12", "unitIds": ["eg.g1403.bishoy_princes", "eg.v.c14_bishoy", "eg.v.c14_maxime_domece", "eg.v.c14_jean_le_petit", "eg.v.c14_moise_le_noir"], "type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Chaque saint de Scété a son image.", "promptLanguage": "fr", "acceptedAnswers": [], "pairs": [{"left": "Bishoy", "right": "ses cheveux attachés au plafond"}, {"left": "Maxime et Domèce", "right": "deux princes devenus moines"}, {"left": "Jean le Petit", "right": "un bâton sec arrosé"}, {"left": "Moïse le Noir", "right": "un sac de sable troué"}], "explanation": "Quatre histoires, quatre saints du même désert.", "pool": "lesson", "lessonId": "eg.l1403", "skill": "recognition", "answer": "Bishoy = ses cheveux attachés au plafond ; Maxime et Domèce = deux princes devenus moines ; Jean le Petit = un bâton sec arrosé ; Moïse le Noir = un sac de sable troué"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
