insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1404.e11', 'eg', 'eg.l1404', 'eg.g1404.samuel', array['eg.g1404.samuel','eg.v.c14_samuel','eg.v.c05_dioscore','eg.v.c14_moise_le_noir','eg.v.c14_bishoy']::text[], 'match', 'lesson', 'Qui a subi quoi pour sa foi ?', '{}'::text[], 'Deux confesseurs (Samuel, Dioscore) et deux saints du désert.', 3, '{"id": "eg.l1404.e11", "unitIds": ["eg.g1404.samuel", "eg.v.c14_samuel", "eg.v.c05_dioscore", "eg.v.c14_moise_le_noir", "eg.v.c14_bishoy"], "type": "match", "difficulty": 3, "instruction": "Associe.", "prompt": "Qui a subi quoi pour sa foi ?", "promptLanguage": "fr", "acceptedAnswers": [], "pairs": [{"left": "Samuel", "right": "battu et chassé de Scété"}, {"left": "Dioscore", "right": "exilé à Gangra"}, {"left": "Moïse le Noir", "right": "tué par des Berbères"}, {"left": "Bishoy", "right": "prière de nuit, cheveux attachés"}], "explanation": "Deux confesseurs (Samuel, Dioscore) et deux saints du désert.", "pool": "lesson", "lessonId": "eg.l1404", "skill": "recognition", "answer": "Samuel = battu et chassé de Scété ; Dioscore = exilé à Gangra ; Moïse le Noir = tué par des Berbères ; Bishoy = prière de nuit, cheveux attachés"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1404.e12', 'eg', 'eg.l1404', 'eg.v.c04_athanase', array['eg.v.c04_athanase','eg.v.c14_moise_le_noir','eg.v.c14_samuel']::text[], 'reorder', 'lesson', 'Remets ces trois saints dans l''ordre de leur mort.', array['Athanase Moïse Samuel']::text[], 'Athanase en 373, Moïse vers 405, Samuel vers 695.', 2, '{"id": "eg.l1404.e12", "unitIds": ["eg.v.c04_athanase", "eg.v.c14_moise_le_noir", "eg.v.c14_samuel"], "type": "reorder", "difficulty": 2, "instruction": "Remets dans l''ordre.", "prompt": "Remets ces trois saints dans l''ordre de leur mort.", "promptLanguage": "fr", "answer": "Athanase Moïse Samuel", "acceptedAnswers": ["Athanase Moïse Samuel"], "tokens": ["Moïse", "Samuel", "Athanase"], "explanation": "Athanase en 373, Moïse vers 405, Samuel vers 695.", "pool": "lesson", "lessonId": "eg.l1404", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1404.e13', 'eg', 'eg.l1404', 'eg.g1404.samuel', array['eg.g1404.samuel','eg.v.c14_samuel']::text[], 'mcq', 'lesson', 'Pourquoi appelle-t-on Samuel « confesseur » et non « martyr » ?', array['Il a souffert pour sa foi sans en mourir']::text[], 'Le martyr meurt pour sa foi ; le confesseur la confesse en souffrant.', 3, '{"id": "eg.l1404.e13", "unitIds": ["eg.g1404.samuel", "eg.v.c14_samuel"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi appelle-t-on Samuel « confesseur » et non « martyr » ?", "promptLanguage": "fr", "answer": "Il a souffert pour sa foi sans en mourir", "acceptedAnswers": ["Il a souffert pour sa foi sans en mourir"], "options": ["Il a refusé d''entrer au monastère de Scété", "Il est mort très loin de l''Égypte natale", "Il a souffert pour sa foi sans en mourir"], "explanation": "Le martyr meurt pour sa foi ; le confesseur la confesse en souffrant.", "pool": "lesson", "lessonId": "eg.l1404", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
