insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1405.e10', 'eg', 'eg.l1405', 'eg.g1405.mina', array['eg.g1405.mina','eg.v.c14_saint_mina','eg.v.c14_ampoule','eg.v.c14_abou_mina','eg.v.c14_maryut']::text[], 'match', 'lesson', 'Mina en quatre images.', '{}'::text[], 'Un chameau, un lac, une ville, des ampoules : tout Mina est là.', 2, '{"id": "eg.l1405.e10", "unitIds": ["eg.g1405.mina", "eg.v.c14_saint_mina", "eg.v.c14_ampoule", "eg.v.c14_abou_mina", "eg.v.c14_maryut"], "type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Mina en quatre images.", "promptLanguage": "fr", "acceptedAnswers": [], "pairs": [{"left": "le chameau", "right": "le corps de Mina porté jusqu''au Maryût"}, {"left": "les ampoules", "right": "l''huile bénite des pèlerins"}, {"left": "Abou Mina", "right": "la ville de pèlerinage"}, {"left": "le lac Maryût", "right": "le lieu où repose Mina"}], "explanation": "Un chameau, un lac, une ville, des ampoules : tout Mina est là.", "pool": "lesson", "lessonId": "eg.l1405", "skill": "recognition", "answer": "le chameau = le corps de Mina porté jusqu''au Maryût ; les ampoules = l''huile bénite des pèlerins ; Abou Mina = la ville de pèlerinage ; le lac Maryût = le lieu où repose Mina"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1405.e11', 'eg', 'eg.l1405', 'eg.v.c03_diocletien', array['eg.v.c03_diocletien']::text[], 'mcq', 'lesson', 'Mina est martyrisé vers 309, pendant la grande persécution commencée sous...', array['Dioclétien']::text[], 'Dioclétien lance la grande persécution en 303.', 2, '{"id": "eg.l1405.e11", "unitIds": ["eg.v.c03_diocletien"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Mina est martyrisé vers 309, pendant la grande persécution commencée sous...", "promptLanguage": "fr", "answer": "Dioclétien", "acceptedAnswers": ["Dioclétien"], "options": ["Constantin", "Dioclétien", "Néron"], "explanation": "Dioclétien lance la grande persécution en 303.", "pool": "lesson", "lessonId": "eg.l1405", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1405.e12', 'eg', 'eg.l1405', 'eg.g1405.mina', array['eg.g1405.mina','eg.v.c14_saint_mina']::text[], 'reorder', 'lesson', 'Remets dans l''ordre l''histoire de Mina.', array['Soldat Désert Martyre Pèlerinage']::text[], 'Soldat, puis désert, puis martyre vers 309, et enfin le pèlerinage sur sa tombe.', 2, '{"id": "eg.l1405.e12", "unitIds": ["eg.g1405.mina", "eg.v.c14_saint_mina"], "type": "reorder", "difficulty": 2, "instruction": "Remets dans l''ordre.", "prompt": "Remets dans l''ordre l''histoire de Mina.", "promptLanguage": "fr", "answer": "Soldat Désert Martyre Pèlerinage", "acceptedAnswers": ["Soldat Désert Martyre Pèlerinage"], "tokens": ["Martyre", "Pèlerinage", "Soldat", "Désert"], "explanation": "Soldat, puis désert, puis martyre vers 309, et enfin le pèlerinage sur sa tombe.", "pool": "lesson", "lessonId": "eg.l1405", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
