insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1407.e09', 'eg', 'eg.l1407', 'eg.g1407.abanoub_demiana', array['eg.g1407.abanoub_demiana','eg.v.c14_abanoub']::text[], 'mcq', 'lesson', 'Qui suis-je ? J''ai douze ans quand je refuse les idoles devant le gouverneur.', array['Abanoub']::text[], 'L''enfant martyr de Nehisa.', 1, '{"id": "eg.l1407.e09", "unitIds": ["eg.g1407.abanoub_demiana", "eg.v.c14_abanoub"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui suis-je ? J''ai douze ans quand je refuse les idoles devant le gouverneur.", "promptLanguage": "fr", "answer": "Abanoub", "acceptedAnswers": ["Abanoub"], "options": ["Démiana", "Mina", "Abanoub"], "explanation": "L''enfant martyr de Nehisa.", "pool": "lesson", "lessonId": "eg.l1407", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
