insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1407.e11', 'eg', 'eg.l1407', 'eg.g1407.abanoub_demiana', array['eg.g1407.abanoub_demiana','eg.v.c14_abanoub','eg.v.c14_demiana','eg.v.c14_abou_sefein','eg.v.c14_saint_mina']::text[], 'match', 'lesson', 'Qui est qui, chez les jeunes martyrs ?', '{}'::text[], 'Deux jeunes martyrs et deux saints soldats vus à la leçon précédente.', 2, '{"id": "eg.l1407.e11", "unitIds": ["eg.g1407.abanoub_demiana", "eg.v.c14_abanoub", "eg.v.c14_demiana", "eg.v.c14_abou_sefein", "eg.v.c14_saint_mina"], "type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Qui est qui, chez les jeunes martyrs ?", "promptLanguage": "fr", "acceptedAnswers": [], "pairs": [{"left": "Abanoub", "right": "l''enfant de douze ans"}, {"left": "Démiana", "right": "la fille d''un gouverneur"}, {"left": "Mercure", "right": "le père des deux épées"}, {"left": "Mina", "right": "le soldat du chameau"}], "explanation": "Deux jeunes martyrs et deux saints soldats vus à la leçon précédente.", "pool": "lesson", "lessonId": "eg.l1407", "skill": "recognition", "answer": "Abanoub = l''enfant de douze ans ; Démiana = la fille d''un gouverneur ; Mercure = le père des deux épées ; Mina = le soldat du chameau"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
