insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1414.e12', 'eg', 'eg.l1414', 'eg.g1414.cyrille_iv_habib', array['eg.g1414.cyrille_iv_habib','eg.v.c14_cyrille_iv','eg.v.c14_habib_guirguis','eg.v.c14_anba_abraam','eg.v.c14_barsoum']::text[], 'match', 'lesson', 'Qui a fait quoi, au XIXe et au XXe siècle ?', '{}'::text[], 'Un pape, un laïc, un évêque, un ermite.', 2, '{"id": "eg.l1414.e12", "unitIds": ["eg.g1414.cyrille_iv_habib", "eg.v.c14_cyrille_iv", "eg.v.c14_habib_guirguis", "eg.v.c14_anba_abraam", "eg.v.c14_barsoum"], "type": "match", "difficulty": 2, "instruction": "Associe.", "prompt": "Qui a fait quoi, au XIXe et au XXe siècle ?", "promptLanguage": "fr", "acceptedAnswers": [], "pairs": [{"left": "Cyrille IV", "right": "l''imprimerie"}, {"left": "Habib Guirguis", "right": "les écoles du dimanche"}, {"left": "Anba Abraam", "right": "les revenus donnés aux pauvres"}, {"left": "Barsoum", "right": "la peau de chèvre"}], "explanation": "Un pape, un laïc, un évêque, un ermite.", "pool": "lesson", "lessonId": "eg.l1414", "skill": "recognition", "answer": "Cyrille IV = l''imprimerie ; Habib Guirguis = les écoles du dimanche ; Anba Abraam = les revenus donnés aux pauvres ; Barsoum = la peau de chèvre"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1414.e13', 'eg', 'eg.l1414', 'eg.v.c14_barsoum', array['eg.v.c14_barsoum','eg.v.c14_cyrille_iv','eg.v.c14_anba_abraam','eg.v.c14_habib_guirguis']::text[], 'reorder', 'lesson', 'Remets ces quatre saints, de Barsoum à Habib, dans l''ordre.', array['Barsoum Cyrille-IV Anba-Abraam Habib-Guirguis']::text[], 'Barsoum en 1317, Cyrille IV en 1861, Anba Abraam en 1914, Habib Guirguis en 1951.', 2, '{"id": "eg.l1414.e13", "unitIds": ["eg.v.c14_barsoum", "eg.v.c14_cyrille_iv", "eg.v.c14_anba_abraam", "eg.v.c14_habib_guirguis"], "type": "reorder", "difficulty": 2, "instruction": "Remets dans l''ordre.", "prompt": "Remets ces quatre saints, de Barsoum à Habib, dans l''ordre.", "promptLanguage": "fr", "answer": "Barsoum Cyrille-IV Anba-Abraam Habib-Guirguis", "acceptedAnswers": ["Barsoum Cyrille-IV Anba-Abraam Habib-Guirguis"], "tokens": ["Anba-Abraam", "Habib-Guirguis", "Barsoum", "Cyrille-IV"], "explanation": "Barsoum en 1317, Cyrille IV en 1861, Anba Abraam en 1914, Habib Guirguis en 1951.", "pool": "lesson", "lessonId": "eg.l1414", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
