insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1417.e16', 'eg', 'eg.l1417', 'eg.v.c14_habib_guirguis', array['eg.v.c14_habib_guirguis','eg.v.c14_cyrille_vi']::text[], 'mcq', 'lesson', 'Quel saint a été proclamé saint en 2013, en même temps que Cyrille VI ?', array['Habib Guirguis']::text[], 'Habib Guirguis, fondateur des écoles du dimanche.', 2, '{"id": "eg.l1417.e16", "unitIds": ["eg.v.c14_habib_guirguis", "eg.v.c14_cyrille_vi"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel saint a été proclamé saint en 2013, en même temps que Cyrille VI ?", "promptLanguage": "fr", "answer": "Habib Guirguis", "acceptedAnswers": ["Habib Guirguis"], "options": ["Anba Abraam", "Chenouda III", "Habib Guirguis"], "explanation": "Habib Guirguis, fondateur des écoles du dimanche.", "pool": "lesson", "lessonId": "eg.l1417", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1501.e01', 'eg', 'eg.l1501', 'eg.g1501.langue_des_pharaons', array['eg.g1501.langue_des_pharaons','eg.v.cop_nouti']::text[], 'mcq', 'lesson', 'Le copte est la dernière étape de quelle langue ?', array['la langue des pharaons']::text[], 'Les pharaons parlaient l''égyptien, et le copte en est le dernier visage.', 1, '{"id": "eg.l1501.e01", "unitIds": ["eg.g1501.langue_des_pharaons", "eg.v.cop_nouti"], "type": "mcq", "difficulty": 1, "prompt": "Le copte est la dernière étape de quelle langue ?", "promptLanguage": "fr", "answer": "la langue des pharaons", "acceptedAnswers": ["la langue des pharaons"], "explanation": "Les pharaons parlaient l''égyptien, et le copte en est le dernier visage.", "instruction": "Choisis la bonne réponse.", "step": 1, "options": ["la langue des Romains et des Grecs", "l''arabe des conquérants", "la langue des pharaons"], "pool": "lesson", "lessonId": "eg.l1501", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
