insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1501.e10', 'eg', 'eg.l1501', 'eg.g1501.langue_des_pharaons', array['eg.g1501.langue_des_pharaons','eg.v.cop_nouti','eg.v.cop_ran','eg.v.cop_iot','eg.v.cop_shiri']::text[], 'match', 'lesson', 'Relie chaque mot copte à son sens.', '{}'::text[], 'Ces quatre mots sont égyptiens : tu les retrouveras dans toutes les prières.', 2, '{"id": "eg.l1501.e10", "unitIds": ["eg.g1501.langue_des_pharaons", "eg.v.cop_nouti", "eg.v.cop_ran", "eg.v.cop_iot", "eg.v.cop_shiri"], "type": "match", "difficulty": 2, "prompt": "Relie chaque mot copte à son sens.", "promptLanguage": "cop", "acceptedAnswers": [], "explanation": "Ces quatre mots sont égyptiens : tu les retrouveras dans toutes les prières.", "instruction": "Associe chaque élément de gauche à celui de droite.", "pairs": [{"left": "ⲛⲟⲩϯ", "right": "dieu"}, {"left": "ⲣⲁⲛ", "right": "nom"}, {"left": "ⲓⲱⲧ", "right": "père"}, {"left": "ϣⲏⲣⲓ", "right": "fils"}], "pool": "lesson", "lessonId": "eg.l1501", "skill": "recognition", "answer": "ⲛⲟⲩϯ = dieu ; ⲣⲁⲛ = nom ; ⲓⲱⲧ = père ; ϣⲏⲣⲓ = fils"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1501.e11', 'eg', 'eg.l1501', 'eg.g1501.langue_des_pharaons', array['eg.g1501.langue_des_pharaons','eg.v.cop_ran']::text[], 'fill_blank', 'lesson', 'Un mot qui contient ϩ ou ϧ est un mot ___.', array['égyptien']::text[], 'Ces lettres ont été ajoutées pour des sons que seul l''égyptien avait.', 1, '{"id": "eg.l1501.e11", "unitIds": ["eg.g1501.langue_des_pharaons", "eg.v.cop_ran"], "type": "fill_blank", "difficulty": 1, "prompt": "Un mot qui contient ϩ ou ϧ est un mot ___.", "promptLanguage": "fr", "answer": "égyptien", "acceptedAnswers": ["égyptien"], "explanation": "Ces lettres ont été ajoutées pour des sons que seul l''égyptien avait.", "instruction": "Touche le mot qui manque.", "options": ["grec", "arabe", "égyptien"], "pool": "lesson", "lessonId": "eg.l1501", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1501.e12', 'eg', 'eg.l1501', 'eg.g1501.langue_des_pharaons', array['eg.g1501.langue_des_pharaons']::text[], 'reorder', 'lesson', 'Remets les étapes de l''écriture égyptienne dans l''ordre.', array['hiéroglyphes démotique copte']::text[], 'On commence par les hiéroglyphes, puis le démotique, et le copte clôt l''histoire.', 2, '{"id": "eg.l1501.e12", "unitIds": ["eg.g1501.langue_des_pharaons"], "type": "reorder", "difficulty": 2, "prompt": "Remets les étapes de l''écriture égyptienne dans l''ordre.", "promptLanguage": "fr", "answer": "hiéroglyphes démotique copte", "acceptedAnswers": ["hiéroglyphes démotique copte"], "explanation": "On commence par les hiéroglyphes, puis le démotique, et le copte clôt l''histoire.", "instruction": "Remets dans l''ordre.", "tokens": ["démotique", "hiéroglyphes", "copte"], "pool": "lesson", "lessonId": "eg.l1501", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1501.e13', 'eg', 'eg.l1501', 'eg.g1501.langue_des_pharaons', array['eg.g1501.langue_des_pharaons']::text[], 'fill_blank', 'lesson', 'La liturgie copte est dite en ___.', array['bohaïrique']::text[], 'C''est le dialecte du Nord, celui d''Alexandrie et de Scété.', 2, '{"id": "eg.l1501.e13", "unitIds": ["eg.g1501.langue_des_pharaons"], "type": "fill_blank", "difficulty": 2, "prompt": "La liturgie copte est dite en ___.", "promptLanguage": "fr", "answer": "bohaïrique", "acceptedAnswers": ["bohaïrique"], "explanation": "C''est le dialecte du Nord, celui d''Alexandrie et de Scété.", "instruction": "Touche le mot qui manque.", "options": ["sahidique", "bohaïrique", "démotique"], "pool": "lesson", "lessonId": "eg.l1501", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1501.e14', 'eg', 'eg.l1501', 'eg.g1501.langue_des_pharaons', array['eg.g1501.langue_des_pharaons','eg.v.c01_alexandrie']::text[], 'mcq', 'lesson', 'Pourquoi les chrétiens d''Égypte connaissaient-ils l''alphabet grec ?', array['Alexandrie était une grande ville grecque']::text[], 'L''alphabet grec était partout à Alexandrie : le prendre était naturel.', 3, '{"id": "eg.l1501.e14", "unitIds": ["eg.g1501.langue_des_pharaons", "eg.v.c01_alexandrie"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi les chrétiens d''Égypte connaissaient-ils l''alphabet grec ?", "promptLanguage": "fr", "answer": "Alexandrie était une grande ville grecque", "acceptedAnswers": ["Alexandrie était une grande ville grecque"], "explanation": "L''alphabet grec était partout à Alexandrie : le prendre était naturel.", "instruction": "Choisis la bonne réponse.", "options": ["Les pharaons l''avaient inventé pour leurs temples", "Alexandrie était une grande ville grecque", "Les Arabes l''avaient apporté"], "pool": "lesson", "lessonId": "eg.l1501", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1501.e15', 'eg', 'eg.l1501', 'eg.g1501.langue_des_pharaons', array['eg.g1501.langue_des_pharaons','eg.v.c01_copte']::text[], 'mcq', 'lesson', 'Un ami dit : « le copte, c''est du grec ». Que lui réponds-tu ?', array['C''est de l''égyptien écrit avec des lettres grecques']::text[], 'La langue est celle des pharaons : seul l''alphabet est (presque) grec.', 3, '{"id": "eg.l1501.e15", "unitIds": ["eg.g1501.langue_des_pharaons", "eg.v.c01_copte"], "type": "mcq", "difficulty": 3, "prompt": "Un ami dit : « le copte, c''est du grec ». Que lui réponds-tu ?", "promptLanguage": "fr", "answer": "C''est de l''égyptien écrit avec des lettres grecques", "acceptedAnswers": ["C''est de l''égyptien écrit avec des lettres grecques"], "explanation": "La langue est celle des pharaons : seul l''alphabet est (presque) grec.", "instruction": "Choisis la bonne réponse.", "options": ["C''est de l''égyptien écrit avec des lettres grecques", "C''est de l''arabe ancien, écrit avec des lettres grecques", "C''est du grec écrit à la main avec des lettres égyptiennes"], "pool": "lesson", "lessonId": "eg.l1501", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1501.e16', 'eg', 'eg.l1501', 'eg.g1501.langue_des_pharaons', array['eg.g1501.langue_des_pharaons','eg.v.c01_copte','eg.v.cop_nouti']::text[], 'mcq', 'lesson', 'Le mot « copte » veut dire à l''origine « égyptien ». Quel mot de cette leçon est lui aussi égyptien ?', array['ⲛⲟⲩϯ']::text[], 'Les deux autres sont grecs ; ⲛⲟⲩϯ, lui, est égyptien comme le nom « copte ».', 2, '{"id": "eg.l1501.e16", "unitIds": ["eg.g1501.langue_des_pharaons", "eg.v.c01_copte", "eg.v.cop_nouti"], "type": "mcq", "difficulty": 2, "prompt": "Le mot « copte » veut dire à l''origine « égyptien ». Quel mot de cette leçon est lui aussi égyptien ?", "promptLanguage": "fr", "answer": "ⲛⲟⲩϯ", "acceptedAnswers": ["ⲛⲟⲩϯ"], "explanation": "Les deux autres sont grecs ; ⲛⲟⲩϯ, lui, est égyptien comme le nom « copte ».", "instruction": "Choisis la bonne réponse.", "hint": "Pense au mot « dieu ».", "options": ["ⲁⲅⲅⲉⲗⲟⲥ", "ⲉⲕⲕⲗⲏⲥⲓⲁ", "ⲛⲟⲩϯ"], "pool": "lesson", "lessonId": "eg.l1501", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1502.e01', 'eg', 'eg.l1502', 'eg.g1502.mots_grecs', array['eg.g1502.mots_grecs','eg.v.c01_septante']::text[], 'mcq', 'lesson', 'Quelle Bible lisait-on à Alexandrie ?', array['la Septante']::text[], 'La Septante, c''est la Bible en grec, faite à Alexandrie.', 1, '{"id": "eg.l1502.e01", "unitIds": ["eg.g1502.mots_grecs", "eg.v.c01_septante"], "type": "mcq", "difficulty": 1, "prompt": "Quelle Bible lisait-on à Alexandrie ?", "promptLanguage": "fr", "answer": "la Septante", "acceptedAnswers": ["la Septante"], "explanation": "La Septante, c''est la Bible en grec, faite à Alexandrie.", "instruction": "Choisis la bonne réponse.", "step": 1, "options": ["la Bible en latin", "la Bible en arabe", "la Septante"], "pool": "lesson", "lessonId": "eg.l1502", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
