insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1502.e07', 'eg', 'eg.l1502', 'eg.g1502.mots_grecs', array['eg.g1502.mots_grecs','eg.v.cop_iot']::text[], 'mcq', 'lesson', 'Lequel de ces mots est égyptien ?', array['ⲓⲱⲧ']::text[], 'ⲁⲅⲅⲉⲗⲟⲥ et ⲡⲁⲣⲑⲉⲛⲟⲥ sont grecs ; ⲓⲱⲧ, malgré son apparence, est égyptien.', 1, '{"id": "eg.l1502.e07", "unitIds": ["eg.g1502.mots_grecs", "eg.v.cop_iot"], "type": "mcq", "difficulty": 1, "prompt": "Lequel de ces mots est égyptien ?", "promptLanguage": "cop", "answer": "ⲓⲱⲧ", "acceptedAnswers": ["ⲓⲱⲧ"], "explanation": "ⲁⲅⲅⲉⲗⲟⲥ et ⲡⲁⲣⲑⲉⲛⲟⲥ sont grecs ; ⲓⲱⲧ, malgré son apparence, est égyptien.", "instruction": "Choisis la bonne réponse.", "step": 4, "options": ["ⲁⲅⲅⲉⲗⲟⲥ", "ⲓⲱⲧ", "ⲡⲁⲣⲑⲉⲛⲟⲥ"], "pool": "lesson", "lessonId": "eg.l1502", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1502.e08', 'eg', 'eg.l1502', 'eg.g1502.mots_grecs', array['eg.g1502.mots_grecs','eg.v.cop_iot']::text[], 'mcq', 'lesson', 'Vrai ou faux : sans lettre spéciale, un mot est forcément grec.', array['Faux']::text[], 'ⲓⲱⲧ n''a pas de lettre spéciale et reste un mot égyptien.', 1, '{"id": "eg.l1502.e08", "unitIds": ["eg.g1502.mots_grecs", "eg.v.cop_iot"], "type": "mcq", "difficulty": 1, "prompt": "Vrai ou faux : sans lettre spéciale, un mot est forcément grec.", "promptLanguage": "fr", "answer": "Faux", "acceptedAnswers": ["Faux"], "explanation": "ⲓⲱⲧ n''a pas de lettre spéciale et reste un mot égyptien.", "instruction": "Choisis la bonne réponse.", "step": 4, "options": ["Vrai", "Faux"], "pool": "lesson", "lessonId": "eg.l1502", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1502.e09', 'eg', 'eg.l1502', 'eg.g1502.mots_grecs', array['eg.g1502.mots_grecs','eg.v.cop_angelos','eg.v.cop_euangelion','eg.v.cop_ekklesia','eg.v.cop_parthenos']::text[], 'match', 'lesson', 'Relie chaque mot grec à son sens.', '{}'::text[], 'Quatre mots grecs que le français a presque gardés tels quels.', 2, '{"id": "eg.l1502.e09", "unitIds": ["eg.g1502.mots_grecs", "eg.v.cop_angelos", "eg.v.cop_euangelion", "eg.v.cop_ekklesia", "eg.v.cop_parthenos"], "type": "match", "difficulty": 2, "prompt": "Relie chaque mot grec à son sens.", "promptLanguage": "cop", "acceptedAnswers": [], "explanation": "Quatre mots grecs que le français a presque gardés tels quels.", "instruction": "Associe chaque élément de gauche à celui de droite.", "pairs": [{"left": "ⲁⲅⲅⲉⲗⲟⲥ", "right": "ange"}, {"left": "ⲉⲩⲁⲅⲅⲉⲗⲓⲟⲛ", "right": "évangile"}, {"left": "ⲉⲕⲕⲗⲏⲥⲓⲁ", "right": "assemblée"}, {"left": "ⲡⲁⲣⲑⲉⲛⲟⲥ", "right": "vierge"}], "pool": "lesson", "lessonId": "eg.l1502", "skill": "recognition", "answer": "ⲁⲅⲅⲉⲗⲟⲥ = ange ; ⲉⲩⲁⲅⲅⲉⲗⲓⲟⲛ = évangile ; ⲉⲕⲕⲗⲏⲥⲓⲁ = assemblée ; ⲡⲁⲣⲑⲉⲛⲟⲥ = vierge"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1502.e10', 'eg', 'eg.l1502', 'eg.g1502.mots_grecs', array['eg.g1502.mots_grecs','eg.v.cop_euangelion']::text[], 'fill_blank', 'lesson', 'Le mot « évangile » vient du grec ⲉⲩⲁⲅⲅⲉⲗⲓⲟⲛ, la bonne ___.', array['nouvelle']::text[], 'Évangile = bonne nouvelle.', 1, '{"id": "eg.l1502.e10", "unitIds": ["eg.g1502.mots_grecs", "eg.v.cop_euangelion"], "type": "fill_blank", "difficulty": 1, "prompt": "Le mot « évangile » vient du grec ⲉⲩⲁⲅⲅⲉⲗⲓⲟⲛ, la bonne ___.", "promptLanguage": "fr", "answer": "nouvelle", "acceptedAnswers": ["nouvelle"], "explanation": "Évangile = bonne nouvelle.", "instruction": "Touche le mot qui manque.", "options": ["nouvelle", "année", "route"], "pool": "lesson", "lessonId": "eg.l1502", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1502.e11', 'eg', 'eg.l1502', 'eg.g1502.mots_grecs', array['eg.g1502.mots_grecs','eg.v.cop_shiri']::text[], 'mcq', 'lesson', 'Lequel de ces mots est égyptien et non grec ?', array['ϣⲏⲣⲓ']::text[], 'Le ϣ est un indice : c''est le fils égyptien.', 2, '{"id": "eg.l1502.e11", "unitIds": ["eg.g1502.mots_grecs", "eg.v.cop_shiri"], "type": "mcq", "difficulty": 2, "prompt": "Lequel de ces mots est égyptien et non grec ?", "promptLanguage": "cop", "answer": "ϣⲏⲣⲓ", "acceptedAnswers": ["ϣⲏⲣⲓ"], "explanation": "Le ϣ est un indice : c''est le fils égyptien.", "instruction": "Choisis la bonne réponse.", "options": ["ⲁⲅⲅⲉⲗⲟⲥ", "ⲉⲕⲕⲗⲏⲥⲓⲁ", "ϣⲏⲣⲓ"], "pool": "lesson", "lessonId": "eg.l1502", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1502.e12', 'eg', 'eg.l1502', 'eg.g1502.mots_grecs', array['eg.g1502.mots_grecs','eg.v.cop_nouti','eg.v.cop_angelos']::text[], 'fill_blank', 'lesson', 'ⲛⲟⲩϯ est un mot ___ ; ⲁⲅⲅⲉⲗⲟⲥ est un mot grec.', array['égyptien']::text[], 'ⲛⲟⲩϯ est le « dieu » des anciens Égyptiens.', 2, '{"id": "eg.l1502.e12", "unitIds": ["eg.g1502.mots_grecs", "eg.v.cop_nouti", "eg.v.cop_angelos"], "type": "fill_blank", "difficulty": 2, "prompt": "ⲛⲟⲩϯ est un mot ___ ; ⲁⲅⲅⲉⲗⲟⲥ est un mot grec.", "promptLanguage": "cop", "answer": "égyptien", "acceptedAnswers": ["égyptien"], "explanation": "ⲛⲟⲩϯ est le « dieu » des anciens Égyptiens.", "instruction": "Touche le mot qui manque.", "options": ["hébreu", "arabe", "égyptien"], "pool": "lesson", "lessonId": "eg.l1502", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1502.e13', 'eg', 'eg.l1502', 'eg.g1502.mots_grecs', array['eg.g1502.mots_grecs','eg.v.c01_septante','eg.v.c01_alexandrie']::text[], 'mcq', 'lesson', 'Pourquoi le copte a-t-il autant de mots grecs religieux ?', array['Alexandrie parlait grec et lisait la Septante']::text[], 'La ville et la Bible de l''époque étaient grecques : les mots de la foi sont venus avec.', 3, '{"id": "eg.l1502.e13", "unitIds": ["eg.g1502.mots_grecs", "eg.v.c01_septante", "eg.v.c01_alexandrie"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi le copte a-t-il autant de mots grecs religieux ?", "promptLanguage": "fr", "answer": "Alexandrie parlait grec et lisait la Septante", "acceptedAnswers": ["Alexandrie parlait grec et lisait la Septante"], "explanation": "La ville et la Bible de l''époque étaient grecques : les mots de la foi sont venus avec.", "instruction": "Choisis la bonne réponse.", "options": ["L''Église de Rome l''avait imposé à toute l''Égypte", "Alexandrie parlait grec et lisait la Septante", "Le grec était interdit pour les prières des moines"], "pool": "lesson", "lessonId": "eg.l1502", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1502.e14', 'eg', 'eg.l1502', 'eg.g1502.mots_grecs', array['eg.g1502.mots_grecs','eg.g1501.langue_des_pharaons']::text[], 'mcq', 'lesson', 'Dans quel dialecte la liturgie copte est-elle dite ?', array['le bohaïrique']::text[], 'Rappel de la leçon précédente : le dialecte du Nord.', 2, '{"id": "eg.l1502.e14", "unitIds": ["eg.g1502.mots_grecs", "eg.g1501.langue_des_pharaons"], "type": "mcq", "difficulty": 2, "prompt": "Dans quel dialecte la liturgie copte est-elle dite ?", "promptLanguage": "fr", "answer": "le bohaïrique", "acceptedAnswers": ["le bohaïrique"], "explanation": "Rappel de la leçon précédente : le dialecte du Nord.", "instruction": "Choisis la bonne réponse.", "options": ["le bohaïrique", "le sahidique du Sud", "le grec"], "pool": "lesson", "lessonId": "eg.l1502", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1503.e01', 'eg', 'eg.l1503', 'eg.g1503.jinkim', array['eg.g1503.jinkim','eg.v.cop_jinkim']::text[], 'mcq', 'lesson', 'À quoi sert la jinkim ?', array['elle guide la lecture']::text[], 'C''est un signe de lecture, pas un signe de sens.', 1, '{"id": "eg.l1503.e01", "unitIds": ["eg.g1503.jinkim", "eg.v.cop_jinkim"], "type": "mcq", "difficulty": 1, "prompt": "À quoi sert la jinkim ?", "promptLanguage": "fr", "answer": "elle guide la lecture", "acceptedAnswers": ["elle guide la lecture"], "explanation": "C''est un signe de lecture, pas un signe de sens.", "instruction": "Choisis la bonne réponse.", "step": 1, "options": ["elle guide la lecture", "elle change le sens du mot", "elle abrège un nom sacré"], "pool": "lesson", "lessonId": "eg.l1503", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
