insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1503.e07', 'eg', 'eg.l1503', 'eg.g1503.jinkim', array['eg.g1503.jinkim']::text[], 'mcq', 'lesson', 'Comment se lit ϯⲧ̀ⲣⲓⲁⲥ ?', array['ti-etrias']::text[], 'La jinkim sur ⲧ̀ glisse un petit « e » entre le ϯ et le ⲣ.', 1, '{"id": "eg.l1503.e07", "unitIds": ["eg.g1503.jinkim"], "type": "mcq", "difficulty": 1, "prompt": "Comment se lit ϯⲧ̀ⲣⲓⲁⲥ ?", "promptLanguage": "cop", "answer": "ti-etrias", "acceptedAnswers": ["ti-etrias"], "explanation": "La jinkim sur ⲧ̀ glisse un petit « e » entre le ϯ et le ⲣ.", "instruction": "Choisis la bonne réponse.", "step": 4, "options": ["titrias", "ti-atrias", "ti-etrias"], "pool": "lesson", "lessonId": "eg.l1503", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
