insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1503.e09', 'eg', 'eg.l1503', 'eg.g1503.jinkim', array['eg.g1503.jinkim','eg.v.cop_nte']::text[], 'mcq', 'lesson', 'Vrai ou faux : ⲛ̀ⲧⲉ et ⲛⲧⲉ sont deux mots différents.', array['Faux']::text[], 'Avec ou sans jinkim, c''est le même mot écrit autrement.', 1, '{"id": "eg.l1503.e09", "unitIds": ["eg.g1503.jinkim", "eg.v.cop_nte"], "type": "mcq", "difficulty": 1, "prompt": "Vrai ou faux : ⲛ̀ⲧⲉ et ⲛⲧⲉ sont deux mots différents.", "promptLanguage": "fr", "answer": "Faux", "acceptedAnswers": ["Faux"], "explanation": "Avec ou sans jinkim, c''est le même mot écrit autrement.", "instruction": "Choisis la bonne réponse.", "step": 5, "options": ["Vrai", "Faux"], "pool": "lesson", "lessonId": "eg.l1503", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1503.e10', 'eg', 'eg.l1503', 'eg.g1503.jinkim', array['eg.g1503.jinkim','eg.v.cop_nte','eg.v.cop_phnouti','eg.v.cop_evol']::text[], 'match', 'lesson', 'Relie chaque mot copte à sa lecture.', '{}'::text[], 'Dans chaque cas, la jinkim te dit quelle syllabe prononcer.', 2, '{"id": "eg.l1503.e10", "unitIds": ["eg.g1503.jinkim", "eg.v.cop_nte", "eg.v.cop_phnouti", "eg.v.cop_evol"], "type": "match", "difficulty": 2, "prompt": "Relie chaque mot copte à sa lecture.", "promptLanguage": "cop", "acceptedAnswers": [], "explanation": "Dans chaque cas, la jinkim te dit quelle syllabe prononcer.", "instruction": "Associe chaque élément de gauche à celui de droite.", "pairs": [{"left": "ⲛ̀ⲧⲉ", "right": "ente"}, {"left": "Ⲫ̀ⲛⲟⲩϯ", "right": "efnouti"}, {"left": "ⲉ̀ⲃⲟⲗ", "right": "evol"}], "pool": "lesson", "lessonId": "eg.l1503", "skill": "recognition", "answer": "ⲛ̀ⲧⲉ = ente ; Ⲫ̀ⲛⲟⲩϯ = efnouti ; ⲉ̀ⲃⲟⲗ = evol"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
