insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1503.e14', 'eg', 'eg.l1503', 'eg.g1503.jinkim', array['eg.g1503.jinkim','eg.v.cop_shiri','eg.g1501.langue_des_pharaons']::text[], 'mcq', 'lesson', 'Ⲡ̀ϣⲏⲣⲓ contient ϣⲏⲣⲓ, le « fils » du début. Comment se lit-il ?', array['epshiri']::text[], 'Le ⲡ̀ avec sa jinkim se dit « ep ».', 2, '{"id": "eg.l1503.e14", "unitIds": ["eg.g1503.jinkim", "eg.v.cop_shiri", "eg.g1501.langue_des_pharaons"], "type": "mcq", "difficulty": 2, "prompt": "Ⲡ̀ϣⲏⲣⲓ contient ϣⲏⲣⲓ, le « fils » du début. Comment se lit-il ?", "promptLanguage": "cop", "answer": "epshiri", "acceptedAnswers": ["epshiri"], "explanation": "Le ⲡ̀ avec sa jinkim se dit « ep ».", "instruction": "Choisis la bonne réponse.", "options": ["epeshiri", "epshiri", "pshiri"], "pool": "lesson", "lessonId": "eg.l1503", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1503.e15', 'eg', 'eg.l1503', 'eg.g1503.jinkim', array['eg.g1503.jinkim','eg.v.cop_jinkim']::text[], 'mcq', 'lesson', 'Pourquoi un livre sans jinkim ne change-t-il pas le sens du mot ?', array['Parce qu''elle guide seulement la lecture']::text[], 'La jinkim aide à prononcer, mais le mot et son sens restent les mêmes.', 3, '{"id": "eg.l1503.e15", "unitIds": ["eg.g1503.jinkim", "eg.v.cop_jinkim"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi un livre sans jinkim ne change-t-il pas le sens du mot ?", "promptLanguage": "fr", "answer": "Parce qu''elle guide seulement la lecture", "acceptedAnswers": ["Parce qu''elle guide seulement la lecture"], "explanation": "La jinkim aide à prononcer, mais le mot et son sens restent les mêmes.", "instruction": "Choisis la bonne réponse.", "options": ["Parce qu''on lit alors le mot lettre par lettre", "Parce qu''elle guide seulement la lecture", "Parce que le mot devient alors une abréviation"], "pool": "lesson", "lessonId": "eg.l1503", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
