insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1504.e08', 'eg', 'eg.l1504', 'eg.g1504.nomina_sacra', array['eg.g1504.nomina_sacra']::text[], 'mcq', 'lesson', 'Pourquoi abrège-t-on les noms sacrés ?', array['par respect']::text[], 'Ce n''est pas un gain de place : c''est un geste de respect.', 1, '{"id": "eg.l1504.e08", "unitIds": ["eg.g1504.nomina_sacra"], "type": "mcq", "difficulty": 1, "prompt": "Pourquoi abrège-t-on les noms sacrés ?", "promptLanguage": "fr", "answer": "par respect", "acceptedAnswers": ["par respect"], "explanation": "Ce n''est pas un gain de place : c''est un geste de respect.", "instruction": "Choisis la bonne réponse.", "step": 5, "options": ["par manque de place", "par respect", "par mode"], "pool": "lesson", "lessonId": "eg.l1504", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
