insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1504.e10', 'eg', 'eg.l1504', 'eg.g1504.nomina_sacra', array['eg.g1504.nomina_sacra','eg.v.cop_iesous','eg.v.cop_khristos','eg.v.cop_pchois','eg.v.cop_phnouti']::text[], 'match', 'lesson', 'Relie chaque abréviation au nom qu''elle cache.', '{}'::text[], 'Quatre barres que tu as déjà vues cent fois sur les icônes.', 2, '{"id": "eg.l1504.e10", "unitIds": ["eg.g1504.nomina_sacra", "eg.v.cop_iesous", "eg.v.cop_khristos", "eg.v.cop_pchois", "eg.v.cop_phnouti"], "type": "match", "difficulty": 2, "prompt": "Relie chaque abréviation au nom qu''elle cache.", "promptLanguage": "cop", "acceptedAnswers": [], "explanation": "Quatre barres que tu as déjà vues cent fois sur les icônes.", "instruction": "Associe chaque élément de gauche à celui de droite.", "pairs": [{"left": "ⲓ̅ⲏ̅ⲥ̅", "right": "Jésus"}, {"left": "ⲭ̅ⲥ̅", "right": "le Christ"}, {"left": "ⲡ̅ⲟ̅ⲥ̅", "right": "le Seigneur"}, {"left": "ⲫ̅ϯ̅", "right": "Dieu"}], "pool": "lesson", "lessonId": "eg.l1504", "skill": "recognition", "answer": "ⲓ̅ⲏ̅ⲥ̅ = Jésus ; ⲭ̅ⲥ̅ = le Christ ; ⲡ̅ⲟ̅ⲥ̅ = le Seigneur ; ⲫ̅ϯ̅ = Dieu"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1504.e11', 'eg', 'eg.l1504', 'eg.g1504.nomina_sacra', array['eg.g1504.nomina_sacra','eg.v.cop_iesous']::text[], 'fill_blank', 'lesson', 'ⲓ̅ⲏ̅ⲥ̅ se lit en ___, pas lettre par lettre.', array['entier']::text[], 'La barre dit qu''il manque des lettres : tu lis Ⲓⲏⲥⲟⲩⲥ complet.', 1, '{"id": "eg.l1504.e11", "unitIds": ["eg.g1504.nomina_sacra", "eg.v.cop_iesous"], "type": "fill_blank", "difficulty": 1, "prompt": "ⲓ̅ⲏ̅ⲥ̅ se lit en ___, pas lettre par lettre.", "promptLanguage": "fr", "answer": "entier", "acceptedAnswers": ["entier"], "explanation": "La barre dit qu''il manque des lettres : tu lis Ⲓⲏⲥⲟⲩⲥ complet.", "instruction": "Touche le mot qui manque.", "options": ["entier", "silence", "chantant"], "pool": "lesson", "lessonId": "eg.l1504", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1504.e12', 'eg', 'eg.l1504', 'eg.g1504.nomina_sacra', array['eg.g1504.nomina_sacra','eg.g1503.jinkim','eg.v.cop_phnouti']::text[], 'mcq', 'lesson', 'Ⲫ̀ⲛⲟⲩϯ porte une jinkim ; ⲫ̅ϯ̅ porte une surligne. Laquelle est une abréviation ?', array['la surligne']::text[], 'La surligne couvre plusieurs lettres et abrège le nom.', 2, '{"id": "eg.l1504.e12", "unitIds": ["eg.g1504.nomina_sacra", "eg.g1503.jinkim", "eg.v.cop_phnouti"], "type": "mcq", "difficulty": 2, "prompt": "Ⲫ̀ⲛⲟⲩϯ porte une jinkim ; ⲫ̅ϯ̅ porte une surligne. Laquelle est une abréviation ?", "promptLanguage": "fr", "answer": "la surligne", "acceptedAnswers": ["la surligne"], "explanation": "La surligne couvre plusieurs lettres et abrège le nom.", "instruction": "Choisis la bonne réponse.", "options": ["la surligne", "la jinkim"], "pool": "lesson", "lessonId": "eg.l1504", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1504.e13', 'eg', 'eg.l1504', 'eg.g1504.nomina_sacra', array['eg.g1504.nomina_sacra','eg.v.cop_phnouti','eg.v.cop_nouti']::text[], 'fill_blank', 'lesson', 'ⲫ̅ϯ̅ abrège Ⲫ̀ⲛⲟⲩϯ ; le mot égyptien ⲛⲟⲩϯ veut dire ___.', array['dieu']::text[], 'Rappel de la leçon 1 : ⲛⲟⲩϯ, le dieu égyptien, devient Dieu avec l''article.', 2, '{"id": "eg.l1504.e13", "unitIds": ["eg.g1504.nomina_sacra", "eg.v.cop_phnouti", "eg.v.cop_nouti"], "type": "fill_blank", "difficulty": 2, "prompt": "ⲫ̅ϯ̅ abrège Ⲫ̀ⲛⲟⲩϯ ; le mot égyptien ⲛⲟⲩϯ veut dire ___.", "promptLanguage": "cop", "answer": "dieu", "acceptedAnswers": ["dieu"], "explanation": "Rappel de la leçon 1 : ⲛⲟⲩϯ, le dieu égyptien, devient Dieu avec l''article.", "instruction": "Touche le mot qui manque.", "options": ["nom", "père", "dieu"], "pool": "lesson", "lessonId": "eg.l1504", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1504.e14', 'eg', 'eg.l1504', 'eg.g1504.nomina_sacra', array['eg.g1504.nomina_sacra','eg.v.cop_pchois','eg.v.cop_iesous','eg.v.cop_khristos']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : « notre Seigneur Jésus-Christ ».', array['Ⲡⲉⲛϭⲟⲓⲥ Ⲓⲏⲥⲟⲩⲥ Ⲡⲓⲭ̀ⲣⲓⲥⲧⲟⲥ']::text[], 'Seigneur, Jésus, Christ : l''ordre que tu entends dans les prières.', 2, '{"id": "eg.l1504.e14", "unitIds": ["eg.g1504.nomina_sacra", "eg.v.cop_pchois", "eg.v.cop_iesous", "eg.v.cop_khristos"], "type": "reorder", "difficulty": 2, "prompt": "Remets dans l''ordre : « notre Seigneur Jésus-Christ ».", "promptLanguage": "fr", "answer": "Ⲡⲉⲛϭⲟⲓⲥ Ⲓⲏⲥⲟⲩⲥ Ⲡⲓⲭ̀ⲣⲓⲥⲧⲟⲥ", "acceptedAnswers": ["Ⲡⲉⲛϭⲟⲓⲥ Ⲓⲏⲥⲟⲩⲥ Ⲡⲓⲭ̀ⲣⲓⲥⲧⲟⲥ"], "explanation": "Seigneur, Jésus, Christ : l''ordre que tu entends dans les prières.", "instruction": "Remets dans l''ordre.", "tokens": ["Ⲡⲉⲛϭⲟⲓⲥ", "Ⲡⲓⲭ̀ⲣⲓⲥⲧⲟⲥ", "Ⲓⲏⲥⲟⲩⲥ"], "pool": "lesson", "lessonId": "eg.l1504", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1504.e15', 'eg', 'eg.l1504', 'eg.g1504.nomina_sacra', array['eg.g1504.nomina_sacra','eg.v.cop_jinkim','eg.v.cop_iesous']::text[], 'mcq', 'lesson', 'Un ami dit que la barre de ⲓ̅ⲏ̅ⲥ̅ est une jinkim. Quelle est son erreur ?', array['Elle couvre plusieurs lettres : c''est une abréviation']::text[], 'La jinkim touche une lettre ; la surligne en couvre plusieurs et abrège le mot.', 3, '{"id": "eg.l1504.e15", "unitIds": ["eg.g1504.nomina_sacra", "eg.v.cop_jinkim", "eg.v.cop_iesous"], "type": "mcq", "difficulty": 3, "prompt": "Un ami dit que la barre de ⲓ̅ⲏ̅ⲥ̅ est une jinkim. Quelle est son erreur ?", "promptLanguage": "fr", "answer": "Elle couvre plusieurs lettres : c''est une abréviation", "acceptedAnswers": ["Elle couvre plusieurs lettres : c''est une abréviation"], "explanation": "La jinkim touche une lettre ; la surligne en couvre plusieurs et abrège le mot.", "instruction": "Choisis la bonne réponse.", "options": ["Elle ne couvre qu''une lettre et se lit comme un petit « e »", "Elle couvre plusieurs lettres : c''est une abréviation", "Elle change le sens du nom et guide la lecture du chant"], "pool": "lesson", "lessonId": "eg.l1504", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1505.e01', 'eg', 'eg.l1505', 'eg.g1505.articles', array['eg.g1505.articles']::text[], 'fill_blank', 'lesson', 'Premier réflexe : ___ l''article, puis cherche le nom.', array['détache']::text[], 'Une fois l''article séparé, tu reconnais le nom que tu connais déjà.', 1, '{"id": "eg.l1505.e01", "unitIds": ["eg.g1505.articles"], "type": "fill_blank", "difficulty": 1, "prompt": "Premier réflexe : ___ l''article, puis cherche le nom.", "promptLanguage": "fr", "answer": "détache", "acceptedAnswers": ["détache"], "explanation": "Une fois l''article séparé, tu reconnais le nom que tu connais déjà.", "instruction": "Touche le mot qui manque.", "step": 1, "options": ["détache", "efface", "répète"], "pool": "lesson", "lessonId": "eg.l1505", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1505.e02', 'eg', 'eg.l1505', 'eg.g1505.articles', array['eg.g1505.articles','eg.v.cop_pi','eg.v.cop_euangelion']::text[], 'mcq', 'lesson', 'Que veut dire ⲡⲓⲉⲩⲁⲅⲅⲉⲗⲓⲟⲛ ?', array['l''Évangile']::text[], 'ⲡⲓ (le) + ⲉⲩⲁⲅⲅⲉⲗⲓⲟⲛ (la bonne nouvelle).', 1, '{"id": "eg.l1505.e02", "unitIds": ["eg.g1505.articles", "eg.v.cop_pi", "eg.v.cop_euangelion"], "type": "mcq", "difficulty": 1, "prompt": "Que veut dire ⲡⲓⲉⲩⲁⲅⲅⲉⲗⲓⲟⲛ ?", "promptLanguage": "cop", "answer": "l''Évangile", "acceptedAnswers": ["l''Évangile"], "explanation": "ⲡⲓ (le) + ⲉⲩⲁⲅⲅⲉⲗⲓⲟⲛ (la bonne nouvelle).", "instruction": "Choisis la bonne réponse.", "step": 2, "options": ["l''Évangile", "l''Église sainte", "l''ange du Seigneur"], "pool": "lesson", "lessonId": "eg.l1505", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1505.e03', 'eg', 'eg.l1505', 'eg.g1505.articles', array['eg.g1505.articles','eg.v.cop_ti']::text[], 'mcq', 'lesson', 'Quel article est féminin ?', array['ϯ']::text[], 'ϯ devant ⲉⲕⲕⲗⲏⲥⲓⲁ : l''Église est féminine.', 1, '{"id": "eg.l1505.e03", "unitIds": ["eg.g1505.articles", "eg.v.cop_ti"], "type": "mcq", "difficulty": 1, "prompt": "Quel article est féminin ?", "promptLanguage": "fr", "answer": "ϯ", "acceptedAnswers": ["ϯ"], "explanation": "ϯ devant ⲉⲕⲕⲗⲏⲥⲓⲁ : l''Église est féminine.", "instruction": "Choisis la bonne réponse.", "step": 2, "options": ["ⲡⲓ", "ⲛⲓ", "ϯ"], "pool": "lesson", "lessonId": "eg.l1505", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
