insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1505.e05', 'eg', 'eg.l1505', 'eg.g1505.articles', array['eg.g1505.articles']::text[], 'mcq', 'lesson', 'Où lit-on le genre d''un nom copte ?', array['sur l''article']::text[], 'ⲡⲁⲣⲑⲉⲛⲟⲥ ressemble à ⲁⲅⲅⲉⲗⲟⲥ, mais seul l''article dit qu''il est féminin.', 1, '{"id": "eg.l1505.e05", "unitIds": ["eg.g1505.articles"], "type": "mcq", "difficulty": 1, "prompt": "Où lit-on le genre d''un nom copte ?", "promptLanguage": "fr", "answer": "sur l''article", "acceptedAnswers": ["sur l''article"], "explanation": "ⲡⲁⲣⲑⲉⲛⲟⲥ ressemble à ⲁⲅⲅⲉⲗⲟⲥ, mais seul l''article dit qu''il est féminin.", "instruction": "Choisis la bonne réponse.", "step": 4, "options": ["sur la fin du mot", "sur l''article", "sur la jinkim"], "pool": "lesson", "lessonId": "eg.l1505", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
