insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1505.e10', 'eg', 'eg.l1505', 'eg.g1505.articles', array['eg.g1505.articles','eg.v.cop_pi','eg.v.cop_ti','eg.v.cop_ni','eg.v.cop_ou']::text[], 'match', 'lesson', 'Relie chaque article à son sens.', '{}'::text[], 'Quatre petits mots qui se collent devant presque tous les noms.', 2, '{"id": "eg.l1505.e10", "unitIds": ["eg.g1505.articles", "eg.v.cop_pi", "eg.v.cop_ti", "eg.v.cop_ni", "eg.v.cop_ou"], "type": "match", "difficulty": 2, "prompt": "Relie chaque article à son sens.", "promptLanguage": "cop", "acceptedAnswers": [], "explanation": "Quatre petits mots qui se collent devant presque tous les noms.", "instruction": "Associe chaque élément de gauche à celui de droite.", "pairs": [{"left": "ⲡⲓ", "right": "le (article masculin)"}, {"left": "ϯ", "right": "la (article féminin)"}, {"left": "ⲛⲓ", "right": "les (article pluriel)"}, {"left": "ⲟⲩ", "right": "un, une (article indéfini)"}], "pool": "lesson", "lessonId": "eg.l1505", "skill": "recognition", "answer": "ⲡⲓ = le (article masculin) ; ϯ = la (article féminin) ; ⲛⲓ = les (article pluriel) ; ⲟⲩ = un, une (article indéfini)"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
