insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1505.e13', 'eg', 'eg.l1505', 'eg.g1505.articles', array['eg.g1505.articles','eg.v.cop_iot','eg.g1501.langue_des_pharaons']::text[], 'mcq', 'lesson', 'Dans Ⲫ̀ⲓⲱⲧ, quel mot égyptien se cache derrière l''article ?', array['ⲓⲱⲧ']::text[], 'ⲫ̀ (le) + ⲓⲱⲧ (père) : le Père.', 2, '{"id": "eg.l1505.e13", "unitIds": ["eg.g1505.articles", "eg.v.cop_iot", "eg.g1501.langue_des_pharaons"], "type": "mcq", "difficulty": 2, "prompt": "Dans Ⲫ̀ⲓⲱⲧ, quel mot égyptien se cache derrière l''article ?", "promptLanguage": "cop", "answer": "ⲓⲱⲧ", "acceptedAnswers": ["ⲓⲱⲧ"], "explanation": "ⲫ̀ (le) + ⲓⲱⲧ (père) : le Père.", "instruction": "Choisis la bonne réponse.", "options": ["ⲣⲁⲛ", "ϣⲏⲣⲓ", "ⲓⲱⲧ"], "pool": "lesson", "lessonId": "eg.l1505", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1505.e14', 'eg', 'eg.l1505', 'eg.g1505.articles', array['eg.g1505.articles','eg.v.cop_phnouti','eg.v.cop_nouti','eg.g1504.nomina_sacra']::text[], 'fill_blank', 'lesson', 'ⲫ̅ϯ̅ abrège Ⲫ̀ⲛⲟⲩϯ, c''est-à-dire ⲫ̀ + ___.', array['ⲛⲟⲩϯ']::text[], 'Sous la surligne, tu retrouves le ⲛⲟⲩϯ de la leçon 1.', 2, '{"id": "eg.l1505.e14", "unitIds": ["eg.g1505.articles", "eg.v.cop_phnouti", "eg.v.cop_nouti", "eg.g1504.nomina_sacra"], "type": "fill_blank", "difficulty": 2, "prompt": "ⲫ̅ϯ̅ abrège Ⲫ̀ⲛⲟⲩϯ, c''est-à-dire ⲫ̀ + ___.", "promptLanguage": "cop", "answer": "ⲛⲟⲩϯ", "acceptedAnswers": ["ⲛⲟⲩϯ"], "explanation": "Sous la surligne, tu retrouves le ⲛⲟⲩϯ de la leçon 1.", "instruction": "Touche le mot qui manque.", "options": ["ⲣⲁⲛ", "ⲛⲟⲩϯ", "ⲓⲱⲧ"], "pool": "lesson", "lessonId": "eg.l1505", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1505.e15', 'eg', 'eg.l1505', 'eg.g1505.articles', array['eg.g1505.articles','eg.v.cop_nouti','eg.v.cop_phnouti']::text[], 'mcq', 'lesson', 'Pourquoi ⲛⲟⲩϯ et Ⲫ̀ⲛⲟⲩϯ n''ont-ils pas le même sens ?', array['Le second a un article : c''est Dieu, le seul vrai Dieu']::text[], 'L''article change le sens : un dieu d''un côté, Dieu de l''autre.', 3, '{"id": "eg.l1505.e15", "unitIds": ["eg.g1505.articles", "eg.v.cop_nouti", "eg.v.cop_phnouti"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi ⲛⲟⲩϯ et Ⲫ̀ⲛⲟⲩϯ n''ont-ils pas le même sens ?", "promptLanguage": "fr", "answer": "Le second a un article : c''est Dieu, le seul vrai Dieu", "acceptedAnswers": ["Le second a un article : c''est Dieu, le seul vrai Dieu"], "explanation": "L''article change le sens : un dieu d''un côté, Dieu de l''autre.", "instruction": "Choisis la bonne réponse.", "options": ["Le second est un mot grec emprunté à Alexandrie", "Le second a un article : c''est Dieu, le seul vrai Dieu", "Le second est une abréviation qu''on lit lettre par lettre"], "pool": "lesson", "lessonId": "eg.l1505", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
