insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1506.e13', 'eg', 'eg.l1506', 'eg.g1506.possessifs', array['eg.g1506.possessifs','eg.v.cop_pen','eg.v.cop_pchois','eg.g1504.nomina_sacra']::text[], 'mcq', 'lesson', 'Ⲡⲉⲛϭⲟⲓⲥ (notre Seigneur) cache Ⲡϭⲟⲓⲥ. Quelle abréviation en est faite ?', array['ⲡ̅ⲟ̅ⲥ̅']::text[], 'Ⲡϭⲟⲓⲥ, le Seigneur, s''abrège ⲡ̅ⲟ̅ⲥ̅.', 2, '{"id": "eg.l1506.e13", "unitIds": ["eg.g1506.possessifs", "eg.v.cop_pen", "eg.v.cop_pchois", "eg.g1504.nomina_sacra"], "type": "mcq", "difficulty": 2, "prompt": "Ⲡⲉⲛϭⲟⲓⲥ (notre Seigneur) cache Ⲡϭⲟⲓⲥ. Quelle abréviation en est faite ?", "promptLanguage": "fr", "answer": "ⲡ̅ⲟ̅ⲥ̅", "acceptedAnswers": ["ⲡ̅ⲟ̅ⲥ̅"], "explanation": "Ⲡϭⲟⲓⲥ, le Seigneur, s''abrège ⲡ̅ⲟ̅ⲥ̅.", "instruction": "Choisis la bonne réponse.", "options": ["ⲫ̅ϯ̅", "ⲓ̅ⲏ̅ⲥ̅", "ⲡ̅ⲟ̅ⲥ̅"], "pool": "lesson", "lessonId": "eg.l1506", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1506.e14', 'eg', 'eg.l1506', 'eg.g1506.possessifs', array['eg.g1506.possessifs','eg.v.cop_pa']::text[], 'mcq', 'lesson', 'Pourquoi dit-on ⲡⲁⲛⲟⲩϯ et non ⲡⲁⲫ̀ⲛⲟⲩϯ ?', array['Parce que le possessif remplace l''article']::text[], 'Possessif et article ne vont jamais ensemble : l''un prend la place de l''autre.', 3, '{"id": "eg.l1506.e14", "unitIds": ["eg.g1506.possessifs", "eg.v.cop_pa"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi dit-on ⲡⲁⲛⲟⲩϯ et non ⲡⲁⲫ̀ⲛⲟⲩϯ ?", "promptLanguage": "fr", "answer": "Parce que le possessif remplace l''article", "acceptedAnswers": ["Parce que le possessif remplace l''article"], "explanation": "Possessif et article ne vont jamais ensemble : l''un prend la place de l''autre.", "instruction": "Choisis la bonne réponse.", "options": ["Parce qu''on double toujours l''article devant ce nom", "Parce que le possessif remplace l''article", "Parce que ⲫ̀ est une lettre réservée aux verbes"], "pool": "lesson", "lessonId": "eg.l1506", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1506.e15', 'eg', 'eg.l1506', 'eg.g1506.possessifs', array['eg.g1506.possessifs','eg.v.cop_pa','eg.v.cop_ekklesia']::text[], 'mcq', 'lesson', 'Pourquoi dit-on ⲧⲁⲉⲕⲕⲗⲏⲥⲓⲁ pour « mon Église » alors que « mon père » se dit ⲡⲁⲓⲱⲧ ?', array['Parce que ⲉⲕⲕⲗⲏⲥⲓⲁ est un mot féminin']::text[], 'Le possessif s''accorde avec la chose possédée, pas avec celui qui parle.', 3, '{"id": "eg.l1506.e15", "unitIds": ["eg.g1506.possessifs", "eg.v.cop_pa", "eg.v.cop_ekklesia"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi dit-on ⲧⲁⲉⲕⲕⲗⲏⲥⲓⲁ pour « mon Église » alors que « mon père » se dit ⲡⲁⲓⲱⲧ ?", "promptLanguage": "fr", "answer": "Parce que ⲉⲕⲕⲗⲏⲥⲓⲁ est un mot féminin", "acceptedAnswers": ["Parce que ⲉⲕⲕⲗⲏⲥⲓⲁ est un mot féminin"], "explanation": "Le possessif s''accorde avec la chose possédée, pas avec celui qui parle.", "instruction": "Choisis la bonne réponse.", "options": ["Parce que ⲉⲕⲕⲗⲏⲥⲓⲁ est un mot féminin", "Parce que celui qui parle est une femme", "Parce que ⲧⲁ- veut dire « notre »"], "pool": "lesson", "lessonId": "eg.l1506", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
