insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1507.e09', 'eg', 'eg.l1507', 'eg.g1507.petits_mots', array['eg.g1507.petits_mots','eg.v.cop_hen','eg.v.cop_n_de']::text[], 'mcq', 'lesson', 'Dans ϧⲉⲛ ⲫ̀ⲣⲁⲛ ⲙ̀Ⲫ̀ⲓⲱⲧ, quel mot veut dire « le nom » ?', array['ⲫ̀ⲣⲁⲛ']::text[], 'ⲫ̀ (le) + ⲣⲁⲛ (nom) : tu reconnais le ⲣⲁⲛ de la leçon 1.', 1, '{"id": "eg.l1507.e09", "unitIds": ["eg.g1507.petits_mots", "eg.v.cop_hen", "eg.v.cop_n_de"], "type": "mcq", "difficulty": 1, "prompt": "Dans ϧⲉⲛ ⲫ̀ⲣⲁⲛ ⲙ̀Ⲫ̀ⲓⲱⲧ, quel mot veut dire « le nom » ?", "promptLanguage": "fr", "answer": "ⲫ̀ⲣⲁⲛ", "acceptedAnswers": ["ⲫ̀ⲣⲁⲛ"], "explanation": "ⲫ̀ (le) + ⲣⲁⲛ (nom) : tu reconnais le ⲣⲁⲛ de la leçon 1.", "instruction": "Choisis la bonne réponse.", "step": 5, "options": ["ⲫ̀ⲣⲁⲛ", "Ⲫ̀ⲓⲱⲧ", "ϧⲉⲛ"], "pool": "lesson", "lessonId": "eg.l1507", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1507.e10', 'eg', 'eg.l1507', 'eg.g1507.petits_mots', array['eg.g1507.petits_mots','eg.v.cop_nem','eg.v.cop_hen','eg.v.cop_n_de','eg.v.cop_ethouab']::text[], 'match', 'lesson', 'Relie chaque petit mot à son sens.', '{}'::text[], 'Quatre petits mots qui reviennent dans chaque prière.', 2, '{"id": "eg.l1507.e10", "unitIds": ["eg.g1507.petits_mots", "eg.v.cop_nem", "eg.v.cop_hen", "eg.v.cop_n_de", "eg.v.cop_ethouab"], "type": "match", "difficulty": 2, "prompt": "Relie chaque petit mot à son sens.", "promptLanguage": "cop", "acceptedAnswers": [], "explanation": "Quatre petits mots qui reviennent dans chaque prière.", "instruction": "Associe chaque élément de gauche à celui de droite.", "pairs": [{"left": "ⲛⲉⲙ", "right": "et, avec"}, {"left": "ϧⲉⲛ", "right": "dans, en"}, {"left": "ⲛ̀/ⲙ̀", "right": "de"}, {"left": "ⲉⲑⲟⲩⲁⲃ", "right": "saint (placé après le nom)"}], "pool": "lesson", "lessonId": "eg.l1507", "skill": "recognition", "answer": "ⲛⲉⲙ = et, avec ; ϧⲉⲛ = dans, en ; ⲛ̀/ⲙ̀ = de ; ⲉⲑⲟⲩⲁⲃ = saint (placé après le nom)"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
