insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1508.e04', 'eg', 'eg.l1508', 'eg.g1508.passe_paques', array['eg.g1508.passe_paques','eg.v.cop_af','eg.v.cop_ton']::text[], 'mcq', 'lesson', 'Que veut dire ⲁϥⲧⲱⲛϥ ?', array['il est ressuscité']::text[], 'Il s''est levé lui-même : il est ressuscité.', 1, '{"id": "eg.l1508.e04", "unitIds": ["eg.g1508.passe_paques", "eg.v.cop_af", "eg.v.cop_ton"], "type": "mcq", "difficulty": 1, "prompt": "Que veut dire ⲁϥⲧⲱⲛϥ ?", "promptLanguage": "cop", "answer": "il est ressuscité", "acceptedAnswers": ["il est ressuscité"], "explanation": "Il s''est levé lui-même : il est ressuscité.", "instruction": "Choisis la bonne réponse.", "step": 2, "options": ["il croit en un seul Dieu", "il est ressuscité", "il est venu nous bénir"], "pool": "lesson", "lessonId": "eg.l1508", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
