insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1508.e06', 'eg', 'eg.l1508', 'eg.g1508.passe_paques', array['eg.g1508.passe_paques','eg.v.cop_alithos']::text[], 'mcq', 'lesson', 'Vrai ou faux : ⲁ̀ⲗⲏⲑⲱⲥ est un mot égyptien.', array['Faux']::text[], 'C''est un mot grec, comme ange ou évangile.', 1, '{"id": "eg.l1508.e06", "unitIds": ["eg.g1508.passe_paques", "eg.v.cop_alithos"], "type": "mcq", "difficulty": 1, "prompt": "Vrai ou faux : ⲁ̀ⲗⲏⲑⲱⲥ est un mot égyptien.", "promptLanguage": "fr", "answer": "Faux", "acceptedAnswers": ["Faux"], "explanation": "C''est un mot grec, comme ange ou évangile.", "instruction": "Choisis la bonne réponse.", "step": 3, "options": ["Vrai", "Faux"], "pool": "lesson", "lessonId": "eg.l1508", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1508.e07', 'eg', 'eg.l1508', 'eg.g1508.passe_paques', array['eg.g1508.passe_paques','eg.v.cop_af']::text[], 'mcq', 'lesson', 'Que veut dire ⲁⲥⲧⲱⲛⲥ ?', array['elle s''est levée']::text[], 'ⲁ (passé) + ⲥ (elle) + ⲧⲱⲛ + ⲥ (elle-même).', 2, '{"id": "eg.l1508.e07", "unitIds": ["eg.g1508.passe_paques", "eg.v.cop_af"], "type": "mcq", "difficulty": 2, "prompt": "Que veut dire ⲁⲥⲧⲱⲛⲥ ?", "promptLanguage": "cop", "answer": "elle s''est levée", "acceptedAnswers": ["elle s''est levée"], "explanation": "ⲁ (passé) + ⲥ (elle) + ⲧⲱⲛ + ⲥ (elle-même).", "instruction": "Choisis la bonne réponse.", "step": 4, "options": ["elle s''est levée", "il s''est levé", "ils se sont levés"], "pool": "lesson", "lessonId": "eg.l1508", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1508.e08', 'eg', 'eg.l1508', 'eg.g1508.passe_paques', array['eg.g1508.passe_paques','eg.v.cop_af','eg.v.cop_ton','eg.v.cop_alithos']::text[], 'reorder', 'lesson', 'Remets le salut de Pâques dans l''ordre : « Christ est ressuscité ! Vraiment, il est ressuscité ! »', array['Ⲭ̀ⲣⲓⲥⲧⲟⲥ ⲁϥⲧⲱⲛϥ ⲁ̀ⲗⲏⲑⲱⲥ ⲁϥⲧⲱⲛϥ']::text[], 'On annonce d''abord, puis l''assemblée répond « vraiment ».', 2, '{"id": "eg.l1508.e08", "unitIds": ["eg.g1508.passe_paques", "eg.v.cop_af", "eg.v.cop_ton", "eg.v.cop_alithos"], "type": "reorder", "difficulty": 2, "prompt": "Remets le salut de Pâques dans l''ordre : « Christ est ressuscité ! Vraiment, il est ressuscité ! »", "promptLanguage": "fr", "answer": "Ⲭ̀ⲣⲓⲥⲧⲟⲥ ⲁϥⲧⲱⲛϥ ⲁ̀ⲗⲏⲑⲱⲥ ⲁϥⲧⲱⲛϥ", "acceptedAnswers": ["Ⲭ̀ⲣⲓⲥⲧⲟⲥ ⲁϥⲧⲱⲛϥ ⲁ̀ⲗⲏⲑⲱⲥ ⲁϥⲧⲱⲛϥ"], "explanation": "On annonce d''abord, puis l''assemblée répond « vraiment ».", "instruction": "Remets dans l''ordre.", "tokens": ["ⲁϥⲧⲱⲛϥ", "Ⲭ̀ⲣⲓⲥⲧⲟⲥ", "ⲁϥⲧⲱⲛϥ", "ⲁ̀ⲗⲏⲑⲱⲥ"], "pool": "lesson", "lessonId": "eg.l1508", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1508.e09', 'eg', 'eg.l1508', 'eg.g1508.passe_paques', array['eg.g1508.passe_paques','eg.v.cop_af','eg.v.cop_ton']::text[], 'match', 'lesson', 'Relie chaque début de verbe à son sens.', '{}'::text[], 'Le ⲁ dit le passé ; ϥ, ⲥ, ⲟⲩ disent qui agit.', 2, '{"id": "eg.l1508.e09", "unitIds": ["eg.g1508.passe_paques", "eg.v.cop_af", "eg.v.cop_ton"], "type": "match", "difficulty": 2, "prompt": "Relie chaque début de verbe à son sens.", "promptLanguage": "cop", "acceptedAnswers": [], "explanation": "Le ⲁ dit le passé ; ϥ, ⲥ, ⲟⲩ disent qui agit.", "instruction": "Associe chaque élément de gauche à celui de droite.", "pairs": [{"left": "ⲁϥ-", "right": "il a"}, {"left": "ⲁⲥ-", "right": "elle a"}, {"left": "ⲁⲩ-", "right": "ils ont"}, {"left": "ⲧⲱⲛ", "right": "se lever"}], "pool": "lesson", "lessonId": "eg.l1508", "skill": "recognition", "answer": "ⲁϥ- = il a ; ⲁⲥ- = elle a ; ⲁⲩ- = ils ont ; ⲧⲱⲛ = se lever"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1508.e10', 'eg', 'eg.l1508', 'eg.g1508.passe_paques', array['eg.g1508.passe_paques','eg.v.cop_af','eg.v.cop_pef','eg.g1506.possessifs']::text[], 'mcq', 'lesson', 'Dans ⲡⲉϥⲣⲁⲛ (son nom), ϥ veut dire « lui ». Que veut-il dire dans ⲁϥ- ?', array['il']::text[], 'C''est la même marque de la 3e personne.', 2, '{"id": "eg.l1508.e10", "unitIds": ["eg.g1508.passe_paques", "eg.v.cop_af", "eg.v.cop_pef", "eg.g1506.possessifs"], "type": "mcq", "difficulty": 2, "prompt": "Dans ⲡⲉϥⲣⲁⲛ (son nom), ϥ veut dire « lui ». Que veut-il dire dans ⲁϥ- ?", "promptLanguage": "fr", "answer": "il", "acceptedAnswers": ["il"], "explanation": "C''est la même marque de la 3e personne.", "instruction": "Choisis la bonne réponse.", "options": ["je", "nous", "il"], "pool": "lesson", "lessonId": "eg.l1508", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1508.e11', 'eg', 'eg.l1508', 'eg.g1508.passe_paques', array['eg.g1508.passe_paques','eg.v.cop_af','eg.v.cop_khristos','eg.g1504.nomina_sacra']::text[], 'mcq', 'lesson', 'Ⲭ̀ⲣⲓⲥⲧⲟⲥ ⲁϥⲧⲱⲛϥ : quelle abréviation correspond au premier mot ?', array['ⲭ̅ⲥ̅']::text[], 'ⲭ̅ⲥ̅ abrège le Christ.', 2, '{"id": "eg.l1508.e11", "unitIds": ["eg.g1508.passe_paques", "eg.v.cop_af", "eg.v.cop_khristos", "eg.g1504.nomina_sacra"], "type": "mcq", "difficulty": 2, "prompt": "Ⲭ̀ⲣⲓⲥⲧⲟⲥ ⲁϥⲧⲱⲛϥ : quelle abréviation correspond au premier mot ?", "promptLanguage": "cop", "answer": "ⲭ̅ⲥ̅", "acceptedAnswers": ["ⲭ̅ⲥ̅"], "explanation": "ⲭ̅ⲥ̅ abrège le Christ.", "instruction": "Choisis la bonne réponse.", "options": ["ⲓ̅ⲏ̅ⲥ̅", "ⲭ̅ⲥ̅", "ⲫ̅ϯ̅"], "pool": "lesson", "lessonId": "eg.l1508", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1508.e12', 'eg', 'eg.l1508', 'eg.g1508.passe_paques', array['eg.g1508.passe_paques','eg.v.cop_alithos']::text[], 'fill_blank', 'lesson', 'ⲁ̀ⲗⲏⲑⲱⲥ ⲁϥⲧⲱⲛϥ : ___, il est ressuscité.', array['vraiment']::text[], 'ⲁ̀ⲗⲏⲑⲱⲥ, le mot grec de la certitude.', 1, '{"id": "eg.l1508.e12", "unitIds": ["eg.g1508.passe_paques", "eg.v.cop_alithos"], "type": "fill_blank", "difficulty": 1, "prompt": "ⲁ̀ⲗⲏⲑⲱⲥ ⲁϥⲧⲱⲛϥ : ___, il est ressuscité.", "promptLanguage": "cop", "answer": "vraiment", "acceptedAnswers": ["vraiment"], "explanation": "ⲁ̀ⲗⲏⲑⲱⲥ, le mot grec de la certitude.", "instruction": "Touche le mot qui manque.", "options": ["bientôt", "vraiment", "jamais"], "pool": "lesson", "lessonId": "eg.l1508", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1508.e13', 'eg', 'eg.l1508', 'eg.g1508.passe_paques', array['eg.g1508.passe_paques','eg.v.cop_alithos','eg.v.cop_shiri','eg.g1502.mots_grecs']::text[], 'mcq', 'lesson', 'ⲁ̀ⲗⲏⲑⲱⲥ est un mot grec. Lequel de ces mots est égyptien ?', array['ϣⲏⲣⲓ']::text[], 'Le ϣ est l''indice d''un mot égyptien ; les deux autres sont grecs, comme ⲁ̀ⲗⲏⲑⲱⲥ.', 2, '{"id": "eg.l1508.e13", "unitIds": ["eg.g1508.passe_paques", "eg.v.cop_alithos", "eg.v.cop_shiri", "eg.g1502.mots_grecs"], "type": "mcq", "difficulty": 2, "prompt": "ⲁ̀ⲗⲏⲑⲱⲥ est un mot grec. Lequel de ces mots est égyptien ?", "promptLanguage": "fr", "answer": "ϣⲏⲣⲓ", "acceptedAnswers": ["ϣⲏⲣⲓ"], "explanation": "Le ϣ est l''indice d''un mot égyptien ; les deux autres sont grecs, comme ⲁ̀ⲗⲏⲑⲱⲥ.", "instruction": "Choisis la bonne réponse.", "options": ["ϣⲏⲣⲓ", "ⲁⲅⲅⲉⲗⲟⲥ", "ⲉⲩⲁⲅⲅⲉⲗⲓⲟⲛ"], "pool": "lesson", "lessonId": "eg.l1508", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1508.e14', 'eg', 'eg.l1508', 'eg.g1508.passe_paques', array['eg.g1508.passe_paques','eg.v.cop_af','eg.v.cop_ton']::text[], 'mcq', 'lesson', 'Pourquoi ⲁϥⲧⲱⲛϥ finit-il par un second ϥ ?', array['Il veut dire « lui-même » : il s''est levé']::text[], 'Le premier ϥ est le sujet, le second revient sur lui : « il s''est levé ».', 3, '{"id": "eg.l1508.e14", "unitIds": ["eg.g1508.passe_paques", "eg.v.cop_af", "eg.v.cop_ton"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi ⲁϥⲧⲱⲛϥ finit-il par un second ϥ ?", "promptLanguage": "fr", "answer": "Il veut dire « lui-même » : il s''est levé", "acceptedAnswers": ["Il veut dire « lui-même » : il s''est levé"], "explanation": "Le premier ϥ est le sujet, le second revient sur lui : « il s''est levé ».", "instruction": "Choisis la bonne réponse.", "options": ["C''est une simple faute de frappe des copistes", "Il marque le pluriel du verbe, comme ⲁⲩ-", "Il veut dire « lui-même » : il s''est levé"], "pool": "lesson", "lessonId": "eg.l1508", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
