insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1509.e11', 'eg', 'eg.l1509', 'eg.g1509.je_crois_benis', array['eg.g1509.je_crois_benis','eg.v.cop_ti_je','eg.v.cop_ti','eg.g1505.articles']::text[], 'mcq', 'lesson', 'Dans ϯⲉⲕⲕⲗⲏⲥⲓⲁ, le ϯ veut dire « la ». Dans ϯⲛⲁϩϯ, il veut dire…', array['je']::text[], 'Devant un nom c''est l''article ; devant un verbe, c''est « je ».', 2, '{"id": "eg.l1509.e11", "unitIds": ["eg.g1509.je_crois_benis", "eg.v.cop_ti_je", "eg.v.cop_ti", "eg.g1505.articles"], "type": "mcq", "difficulty": 2, "prompt": "Dans ϯⲉⲕⲕⲗⲏⲥⲓⲁ, le ϯ veut dire « la ». Dans ϯⲛⲁϩϯ, il veut dire…", "promptLanguage": "fr", "answer": "je", "acceptedAnswers": ["je"], "explanation": "Devant un nom c''est l''article ; devant un verbe, c''est « je ».", "instruction": "Choisis la bonne réponse.", "options": ["je", "la", "nous"], "pool": "lesson", "lessonId": "eg.l1509", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
