insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1509.e13', 'eg', 'eg.l1509', 'eg.g1509.je_crois_benis', array['eg.g1509.je_crois_benis','eg.v.cop_ti_je','eg.v.cop_ti']::text[], 'mcq', 'lesson', 'Comment distinguer ϯⲉⲕⲕⲗⲏⲥⲓⲁ de ϯⲛⲁϩϯ, qui commencent tous deux par ϯ ?', array['Devant un nom ϯ est « la », devant un verbe « je »']::text[], 'Il faut regarder ce qui suit : un nom ou un verbe.', 3, '{"id": "eg.l1509.e13", "unitIds": ["eg.g1509.je_crois_benis", "eg.v.cop_ti_je", "eg.v.cop_ti"], "type": "mcq", "difficulty": 3, "prompt": "Comment distinguer ϯⲉⲕⲕⲗⲏⲥⲓⲁ de ϯⲛⲁϩϯ, qui commencent tous deux par ϯ ?", "promptLanguage": "fr", "answer": "Devant un nom ϯ est « la », devant un verbe « je »", "acceptedAnswers": ["Devant un nom ϯ est « la », devant un verbe « je »"], "explanation": "Il faut regarder ce qui suit : un nom ou un verbe.", "instruction": "Choisis la bonne réponse.", "options": ["ϯⲛⲁϩϯ est abrégé par une surligne, comme les noms sacrés", "ϯⲉⲕⲕⲗⲏⲥⲓⲁ porte une jinkim sur le premier ϯ, pas ϯⲛⲁϩϯ", "Devant un nom ϯ est « la », devant un verbe « je »"], "pool": "lesson", "lessonId": "eg.l1509", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
