insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1510.e13', 'eg', 'eg.l1510', 'eg.g1510.formule_trinite', array['eg.g1510.formule_trinite','eg.v.cop_phiot','eg.v.cop_n_de','eg.g1507.petits_mots']::text[], 'mcq', 'lesson', 'Dans la formule, quel petit mot veut dire « de » et devient ⲙ̀ devant Ⲫ̀ⲓⲱⲧ ?', array['ⲛ̀']::text[], 'Le « de » s''écrit ⲛ̀ et devient ⲙ̀ devant ⲫ.', 2, '{"id": "eg.l1510.e13", "unitIds": ["eg.g1510.formule_trinite", "eg.v.cop_phiot", "eg.v.cop_n_de", "eg.g1507.petits_mots"], "type": "mcq", "difficulty": 2, "prompt": "Dans la formule, quel petit mot veut dire « de » et devient ⲙ̀ devant Ⲫ̀ⲓⲱⲧ ?", "promptLanguage": "fr", "answer": "ⲛ̀", "acceptedAnswers": ["ⲛ̀"], "explanation": "Le « de » s''écrit ⲛ̀ et devient ⲙ̀ devant ⲫ.", "instruction": "Choisis la bonne réponse.", "options": ["ⲛ̀", "ⲛⲉⲙ", "ϧⲉⲛ"], "pool": "lesson", "lessonId": "eg.l1510", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
