insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1511.e09', 'eg', 'eg.l1511', 'eg.g1511.titres_de_dieu', array['eg.g1511.titres_de_dieu','eg.v.cop_ouro']::text[], 'mcq', 'lesson', 'Lequel de ces titres est égyptien ?', array['ⲟⲩⲣⲟ']::text[], 'Roi est un mot égyptien ; les deux autres sont grecs.', 1, '{"id": "eg.l1511.e09", "unitIds": ["eg.g1511.titres_de_dieu", "eg.v.cop_ouro"], "type": "mcq", "difficulty": 1, "prompt": "Lequel de ces titres est égyptien ?", "promptLanguage": "cop", "answer": "ⲟⲩⲣⲟ", "acceptedAnswers": ["ⲟⲩⲣⲟ"], "explanation": "Roi est un mot égyptien ; les deux autres sont grecs.", "instruction": "Choisis la bonne réponse.", "step": 5, "options": ["ⲥⲱⲧⲏⲣ", "ϯⲧ̀ⲣⲓⲁⲥ", "ⲟⲩⲣⲟ"], "pool": "lesson", "lessonId": "eg.l1511", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1511.e10', 'eg', 'eg.l1511', 'eg.g1511.titres_de_dieu', array['eg.g1511.titres_de_dieu','eg.v.cop_trias','eg.v.cop_ouro','eg.v.cop_pantokrator','eg.v.cop_soter']::text[], 'match', 'lesson', 'Relie chaque titre divin à son sens.', '{}'::text[], 'Trois titres grecs et un titre égyptien.', 2, '{"id": "eg.l1511.e10", "unitIds": ["eg.g1511.titres_de_dieu", "eg.v.cop_trias", "eg.v.cop_ouro", "eg.v.cop_pantokrator", "eg.v.cop_soter"], "type": "match", "difficulty": 2, "prompt": "Relie chaque titre divin à son sens.", "promptLanguage": "cop", "acceptedAnswers": [], "explanation": "Trois titres grecs et un titre égyptien.", "instruction": "Associe chaque élément de gauche à celui de droite.", "pairs": [{"left": "ϯⲧ̀ⲣⲓⲁⲥ", "right": "la Trinité"}, {"left": "ⲟⲩⲣⲟ", "right": "roi"}, {"left": "Ⲡⲓⲡⲁⲛⲧⲟⲕⲣⲁⲧⲱⲣ", "right": "le Tout-Puissant"}, {"left": "ⲥⲱⲧⲏⲣ", "right": "sauveur"}], "pool": "lesson", "lessonId": "eg.l1511", "skill": "recognition", "answer": "ϯⲧ̀ⲣⲓⲁⲥ = la Trinité ; ⲟⲩⲣⲟ = roi ; Ⲡⲓⲡⲁⲛⲧⲟⲕⲣⲁⲧⲱⲣ = le Tout-Puissant ; ⲥⲱⲧⲏⲣ = sauveur"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1511.e11', 'eg', 'eg.l1511', 'eg.g1511.titres_de_dieu', array['eg.g1511.titres_de_dieu','eg.v.cop_soter','eg.v.cop_pen','eg.g1506.possessifs']::text[], 'mcq', 'lesson', 'Ⲡⲉⲛⲥⲱⲧⲏⲣ et Ⲡⲉⲛⲓⲱⲧ commencent de la même façon. Par quoi ?', array['Ⲡⲉⲛ-']::text[], 'Ⲡⲉⲛ- veut dire « notre » : notre Sauveur, notre Père.', 2, '{"id": "eg.l1511.e11", "unitIds": ["eg.g1511.titres_de_dieu", "eg.v.cop_soter", "eg.v.cop_pen", "eg.g1506.possessifs"], "type": "mcq", "difficulty": 2, "prompt": "Ⲡⲉⲛⲥⲱⲧⲏⲣ et Ⲡⲉⲛⲓⲱⲧ commencent de la même façon. Par quoi ?", "promptLanguage": "fr", "answer": "Ⲡⲉⲛ-", "acceptedAnswers": ["Ⲡⲉⲛ-"], "explanation": "Ⲡⲉⲛ- veut dire « notre » : notre Sauveur, notre Père.", "instruction": "Choisis la bonne réponse.", "options": ["ⲡⲁ-", "Ⲡⲉⲛ-", "ⲡⲉⲕ-"], "pool": "lesson", "lessonId": "eg.l1511", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1511.e12', 'eg', 'eg.l1511', 'eg.g1511.titres_de_dieu', array['eg.g1511.titres_de_dieu','eg.v.cop_trias','eg.v.cop_pnevma','eg.g1510.formule_trinite']::text[], 'mcq', 'lesson', 'Dans la formule du signe de croix, quel nom reçoit le mot ⲉⲑⲟⲩⲁⲃ, « saint » ?', array['Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ']::text[], 'ⲉⲑⲟⲩⲁⲃ suit l''Esprit : Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ ⲉⲑⲟⲩⲁⲃ.', 2, '{"id": "eg.l1511.e12", "unitIds": ["eg.g1511.titres_de_dieu", "eg.v.cop_trias", "eg.v.cop_pnevma", "eg.g1510.formule_trinite"], "type": "mcq", "difficulty": 2, "prompt": "Dans la formule du signe de croix, quel nom reçoit le mot ⲉⲑⲟⲩⲁⲃ, « saint » ?", "promptLanguage": "fr", "answer": "Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ", "acceptedAnswers": ["Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ"], "explanation": "ⲉⲑⲟⲩⲁⲃ suit l''Esprit : Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ ⲉⲑⲟⲩⲁⲃ.", "instruction": "Choisis la bonne réponse.", "options": ["Ⲫ̀ⲓⲱⲧ", "Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ", "Ⲡ̀ϣⲏⲣⲓ"], "pool": "lesson", "lessonId": "eg.l1511", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
