insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1511.e15', 'eg', 'eg.l1511', 'eg.g1511.titres_de_dieu', array['eg.g1511.titres_de_dieu','eg.v.cop_soter','eg.v.cop_iesous','eg.g1504.nomina_sacra']::text[], 'mcq', 'lesson', 'Jésus veut dire « Dieu sauve ». Quel titre rappelle ce sens ?', array['ⲥⲱⲧⲏⲣ, le Sauveur']::text[], 'Celui qui sauve : le sens même du nom de Jésus.', 3, '{"id": "eg.l1511.e15", "unitIds": ["eg.g1511.titres_de_dieu", "eg.v.cop_soter", "eg.v.cop_iesous", "eg.g1504.nomina_sacra"], "type": "mcq", "difficulty": 3, "prompt": "Jésus veut dire « Dieu sauve ». Quel titre rappelle ce sens ?", "promptLanguage": "fr", "answer": "ⲥⲱⲧⲏⲣ, le Sauveur", "acceptedAnswers": ["ⲥⲱⲧⲏⲣ, le Sauveur"], "explanation": "Celui qui sauve : le sens même du nom de Jésus.", "instruction": "Choisis la bonne réponse.", "options": ["ⲟⲩⲣⲟ, le roi", "Ⲡⲓⲡⲁⲛⲧⲟⲕⲣⲁⲧⲱⲣ, le Tout-Puissant", "ⲥⲱⲧⲏⲣ, le Sauveur"], "pool": "lesson", "lessonId": "eg.l1511", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1512.e01', 'eg', 'eg.l1512', 'eg.g1512.vierge_marie', array['eg.g1512.vierge_marie','eg.v.cop_maria','eg.v.cop_parthenos']::text[], 'mcq', 'lesson', 'Que veut dire ϯⲡⲁⲣⲑⲉⲛⲟⲥ Ⲙⲁⲣⲓⲁ ?', array['la Vierge Marie']::text[], 'ϯ (la) + ⲡⲁⲣⲑⲉⲛⲟⲥ (vierge) + Ⲙⲁⲣⲓⲁ.', 1, '{"id": "eg.l1512.e01", "unitIds": ["eg.g1512.vierge_marie", "eg.v.cop_maria", "eg.v.cop_parthenos"], "type": "mcq", "difficulty": 1, "prompt": "Que veut dire ϯⲡⲁⲣⲑⲉⲛⲟⲥ Ⲙⲁⲣⲓⲁ ?", "promptLanguage": "cop", "answer": "la Vierge Marie", "acceptedAnswers": ["la Vierge Marie"], "explanation": "ϯ (la) + ⲡⲁⲣⲑⲉⲛⲟⲥ (vierge) + Ⲙⲁⲣⲓⲁ.", "instruction": "Choisis la bonne réponse.", "step": 1, "options": ["la sainte Église", "la Vierge Marie", "la mère de Dieu"], "pool": "lesson", "lessonId": "eg.l1512", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
