insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1512.e11', 'eg', 'eg.l1512', 'eg.g1512.vierge_marie', array['eg.g1512.vierge_marie','eg.v.cop_khere','eg.v.cop_maria']::text[], 'reorder', 'lesson', 'Remets dans l''ordre la louange : « salut à toi, ô Marie ».', array['ⲭⲉⲣⲉ ⲛⲉ ⲱ̀ Ⲙⲁⲣⲓⲁ']::text[], 'Salut, à toi, ô, Marie : la salutation de l''ange.', 2, '{"id": "eg.l1512.e11", "unitIds": ["eg.g1512.vierge_marie", "eg.v.cop_khere", "eg.v.cop_maria"], "type": "reorder", "difficulty": 2, "prompt": "Remets dans l''ordre la louange : « salut à toi, ô Marie ».", "promptLanguage": "fr", "answer": "ⲭⲉⲣⲉ ⲛⲉ ⲱ̀ Ⲙⲁⲣⲓⲁ", "acceptedAnswers": ["ⲭⲉⲣⲉ ⲛⲉ ⲱ̀ Ⲙⲁⲣⲓⲁ"], "explanation": "Salut, à toi, ô, Marie : la salutation de l''ange.", "instruction": "Remets dans l''ordre.", "tokens": ["ⲛⲉ", "ⲭⲉⲣⲉ", "Ⲙⲁⲣⲓⲁ", "ⲱ̀"], "pool": "lesson", "lessonId": "eg.l1512", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
