insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1513.e10', 'eg', 'eg.l1513', 'eg.g1513.saints_intercession', array['eg.g1513.saints_intercession','eg.v.cop_martyros','eg.v.cop_agios','eg.v.cop_presbia','eg.v.apotre']::text[], 'match', 'lesson', 'Les saints : relie chaque mot grec à son sens.', '{}'::text[], 'Quatre mots des saints, tous venus du grec.', 2, '{"id": "eg.l1513.e10", "unitIds": ["eg.g1513.saints_intercession", "eg.v.cop_martyros", "eg.v.cop_agios", "eg.v.cop_presbia", "eg.v.apotre"], "type": "match", "difficulty": 2, "prompt": "Les saints : relie chaque mot grec à son sens.", "promptLanguage": "cop", "acceptedAnswers": [], "explanation": "Quatre mots des saints, tous venus du grec.", "instruction": "Associe chaque élément de gauche à celui de droite.", "pairs": [{"left": "ⲙⲁⲣⲧⲩⲣⲟⲥ", "right": "témoin"}, {"left": "ⲁ̀ⲡⲟⲥⲧⲟⲗⲟⲥ", "right": "envoyé"}, {"left": "ⲁ̀ⲅⲓⲟⲥ", "right": "saint"}, {"left": "ⲡ̀ⲣⲉⲥⲃⲓⲁ", "right": "intercession"}], "pool": "lesson", "lessonId": "eg.l1513", "skill": "recognition", "answer": "ⲙⲁⲣⲧⲩⲣⲟⲥ = témoin ; ⲁ̀ⲡⲟⲥⲧⲟⲗⲟⲥ = envoyé ; ⲁ̀ⲅⲓⲟⲥ = saint ; ⲡ̀ⲣⲉⲥⲃⲓⲁ = intercession"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1513.e11', 'eg', 'eg.l1513', 'eg.g1513.saints_intercession', array['eg.g1513.saints_intercession','eg.v.cop_hiten','eg.v.cop_presbia','eg.v.cop_nte','eg.v.cop_theotokos','eg.g1512.vierge_marie']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : « par les intercessions de la sainte mère de Dieu, Marie ».', array['ϩⲓⲧⲉⲛ ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ ⲛ̀ⲧⲉ ϯⲑⲉⲟⲧⲟⲕⲟⲥ ⲉⲑⲟⲩⲁⲃ Ⲙⲁⲣⲓⲁ']::text[], 'Par, les intercessions, de, la mère de Dieu, sainte, Marie.', 3, '{"id": "eg.l1513.e11", "unitIds": ["eg.g1513.saints_intercession", "eg.v.cop_hiten", "eg.v.cop_presbia", "eg.v.cop_nte", "eg.v.cop_theotokos", "eg.g1512.vierge_marie"], "type": "reorder", "difficulty": 3, "prompt": "Remets dans l''ordre : « par les intercessions de la sainte mère de Dieu, Marie ».", "promptLanguage": "fr", "answer": "ϩⲓⲧⲉⲛ ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ ⲛ̀ⲧⲉ ϯⲑⲉⲟⲧⲟⲕⲟⲥ ⲉⲑⲟⲩⲁⲃ Ⲙⲁⲣⲓⲁ", "acceptedAnswers": ["ϩⲓⲧⲉⲛ ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ ⲛ̀ⲧⲉ ϯⲑⲉⲟⲧⲟⲕⲟⲥ ⲉⲑⲟⲩⲁⲃ Ⲙⲁⲣⲓⲁ"], "explanation": "Par, les intercessions, de, la mère de Dieu, sainte, Marie.", "instruction": "Remets dans l''ordre.", "tokens": ["Ⲙⲁⲣⲓⲁ", "ϩⲓⲧⲉⲛ", "ⲉⲑⲟⲩⲁⲃ", "ϯⲑⲉⲟⲧⲟⲕⲟⲥ", "ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ", "ⲛ̀ⲧⲉ"], "pool": "lesson", "lessonId": "eg.l1513", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1513.e12', 'eg', 'eg.l1513', 'eg.g1513.saints_intercession', array['eg.g1513.saints_intercession','eg.v.cop_hiten','eg.v.cop_ethouab','eg.g1507.petits_mots']::text[], 'fill_blank', 'lesson', 'ϩⲓⲧⲉⲛ ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ ⲛ̀ⲧⲉ ϯⲑⲉⲟⲧⲟⲕⲟⲥ ___ Ⲙⲁⲣⲓⲁ', array['ⲉⲑⲟⲩⲁⲃ']::text[], 'L''adjectif « saint » suit le nom qu''il qualifie.', 3, '{"id": "eg.l1513.e12", "unitIds": ["eg.g1513.saints_intercession", "eg.v.cop_hiten", "eg.v.cop_ethouab", "eg.g1507.petits_mots"], "type": "fill_blank", "difficulty": 3, "prompt": "ϩⲓⲧⲉⲛ ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ ⲛ̀ⲧⲉ ϯⲑⲉⲟⲧⲟⲕⲟⲥ ___ Ⲙⲁⲣⲓⲁ", "promptLanguage": "cop", "answer": "ⲉⲑⲟⲩⲁⲃ", "acceptedAnswers": ["ⲉⲑⲟⲩⲁⲃ"], "explanation": "L''adjectif « saint » suit le nom qu''il qualifie.", "instruction": "Touche le mot qui manque.", "options": ["ⲛⲉⲙ", "ⲉⲑⲟⲩⲁⲃ", "ϧⲉⲛ"], "pool": "lesson", "lessonId": "eg.l1513", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1513.e13', 'eg', 'eg.l1513', 'eg.g1513.saints_intercession', array['eg.g1513.saints_intercession','eg.v.cop_martyros','eg.v.c01_martyr']::text[], 'mcq', 'lesson', 'Un martyr est d''abord un témoin. Quel mot copte le dit ?', array['ⲙⲁⲣⲧⲩⲣⲟⲥ']::text[], 'Même racine que « martyr » en français.', 2, '{"id": "eg.l1513.e13", "unitIds": ["eg.g1513.saints_intercession", "eg.v.cop_martyros", "eg.v.c01_martyr"], "type": "mcq", "difficulty": 2, "prompt": "Un martyr est d''abord un témoin. Quel mot copte le dit ?", "promptLanguage": "fr", "answer": "ⲙⲁⲣⲧⲩⲣⲟⲥ", "acceptedAnswers": ["ⲙⲁⲣⲧⲩⲣⲟⲥ"], "explanation": "Même racine que « martyr » en français.", "instruction": "Choisis la bonne réponse.", "options": ["ⲁ̀ⲅⲓⲟⲥ", "ⲙⲁⲣⲧⲩⲣⲟⲥ", "ⲁ̀ⲡⲟⲥⲧⲟⲗⲟⲥ"], "pool": "lesson", "lessonId": "eg.l1513", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1513.e14', 'eg', 'eg.l1513', 'eg.g1513.saints_intercession', array['eg.g1513.saints_intercession','eg.v.cop_hiten','eg.v.cop_hen','eg.g1507.petits_mots']::text[], 'mcq', 'lesson', 'Pour dire « dans le nom du Père », on emploie ϧⲉⲛ. Pour « par les intercessions », on emploie…', array['ϩⲓⲧⲉⲛ']::text[], 'ϧⲉⲛ pour le lieu, ϩⲓⲧⲉⲛ pour le moyen.', 2, '{"id": "eg.l1513.e14", "unitIds": ["eg.g1513.saints_intercession", "eg.v.cop_hiten", "eg.v.cop_hen", "eg.g1507.petits_mots"], "type": "mcq", "difficulty": 2, "prompt": "Pour dire « dans le nom du Père », on emploie ϧⲉⲛ. Pour « par les intercessions », on emploie…", "promptLanguage": "fr", "answer": "ϩⲓⲧⲉⲛ", "acceptedAnswers": ["ϩⲓⲧⲉⲛ"], "explanation": "ϧⲉⲛ pour le lieu, ϩⲓⲧⲉⲛ pour le moyen.", "instruction": "Choisis la bonne réponse.", "options": ["ϩⲓⲧⲉⲛ", "ⲛⲉⲙ", "ⲛ̀ⲧⲉ"], "pool": "lesson", "lessonId": "eg.l1513", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1513.e15', 'eg', 'eg.l1513', 'eg.g1513.saints_intercession', array['eg.g1513.saints_intercession','eg.v.cop_agios','eg.v.cop_ethouab']::text[], 'mcq', 'lesson', 'Pourquoi trouve-t-on deux mots pour « saint » côte à côte ?', array['Le copte emprunte souvent un mot grec à côté du sien']::text[], 'Le copte a souvent deux mots pour une même idée, l''un grec et l''autre copte.', 3, '{"id": "eg.l1513.e15", "unitIds": ["eg.g1513.saints_intercession", "eg.v.cop_agios", "eg.v.cop_ethouab"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi trouve-t-on deux mots pour « saint » côte à côte ?", "promptLanguage": "fr", "answer": "Le copte emprunte souvent un mot grec à côté du sien", "acceptedAnswers": ["Le copte emprunte souvent un mot grec à côté du sien"], "explanation": "Le copte a souvent deux mots pour une même idée, l''un grec et l''autre copte.", "instruction": "Choisis la bonne réponse.", "options": ["L''un des deux est une faute de copiste", "L''un est pour les hommes, l''autre pour les anges", "Le copte emprunte souvent un mot grec à côté du sien"], "pool": "lesson", "lessonId": "eg.l1513", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
