insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1514.e07', 'eg', 'eg.l1514', 'eg.g1514.amen_paix', array['eg.g1514.amen_paix','eg.v.cop_sha_enah']::text[], 'mcq', 'lesson', 'Mot à mot, ϣⲁ ⲉ̀ⲛⲉϩ veut dire…', array['jusqu''à l''éternité']::text[], 'ϣⲁ, « jusqu''à » ; ⲉ̀ⲛⲉϩ, « l''éternité ».', 2, '{"id": "eg.l1514.e07", "unitIds": ["eg.g1514.amen_paix", "eg.v.cop_sha_enah"], "type": "mcq", "difficulty": 2, "prompt": "Mot à mot, ϣⲁ ⲉ̀ⲛⲉϩ veut dire…", "promptLanguage": "cop", "answer": "jusqu''à l''éternité", "acceptedAnswers": ["jusqu''à l''éternité"], "explanation": "ϣⲁ, « jusqu''à » ; ⲉ̀ⲛⲉϩ, « l''éternité ».", "instruction": "Choisis la bonne réponse.", "step": 4, "options": ["avant le temps", "jusqu''à l''éternité", "au nom du Père"], "pool": "lesson", "lessonId": "eg.l1514", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1514.e08', 'eg', 'eg.l1514', 'eg.g1514.amen_paix', array['eg.g1514.amen_paix','eg.v.cop_irini']::text[], 'mcq', 'lesson', 'Que veut dire Ⲓ̀ⲣⲏⲛⲏ ⲡⲁⲥⲓ ?', array['la paix à tous']::text[], 'ⲓ̀ⲣⲏⲛⲏ (paix) + ⲡⲁⲥⲓ (à tous).', 1, '{"id": "eg.l1514.e08", "unitIds": ["eg.g1514.amen_paix", "eg.v.cop_irini"], "type": "mcq", "difficulty": 1, "prompt": "Que veut dire Ⲓ̀ⲣⲏⲛⲏ ⲡⲁⲥⲓ ?", "promptLanguage": "cop", "answer": "la paix à tous", "acceptedAnswers": ["la paix à tous"], "explanation": "ⲓ̀ⲣⲏⲛⲏ (paix) + ⲡⲁⲥⲓ (à tous).", "instruction": "Choisis la bonne réponse.", "step": 5, "options": ["aie pitié de nous", "la paix à tous", "c''est vrai"], "pool": "lesson", "lessonId": "eg.l1514", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1514.e09', 'eg', 'eg.l1514', 'eg.g1514.amen_paix', array['eg.g1514.amen_paix','eg.v.cop_irini']::text[], 'mcq', 'lesson', 'Quel prénom veut dire « la paix » ?', array['Irène']::text[], 'Irène vient de ⲓ̀ⲣⲏⲛⲏ.', 1, '{"id": "eg.l1514.e09", "unitIds": ["eg.g1514.amen_paix", "eg.v.cop_irini"], "type": "mcq", "difficulty": 1, "prompt": "Quel prénom veut dire « la paix » ?", "promptLanguage": "fr", "answer": "Irène", "acceptedAnswers": ["Irène"], "explanation": "Irène vient de ⲓ̀ⲣⲏⲛⲏ.", "instruction": "Choisis la bonne réponse.", "step": 5, "options": ["Irène", "Marie", "Marc"], "pool": "lesson", "lessonId": "eg.l1514", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1514.e10', 'eg', 'eg.l1514', 'eg.g1514.amen_paix', array['eg.g1514.amen_paix','eg.v.cop_amin','eg.v.cop_alleluia','eg.v.cop_sha_enah','eg.v.cop_irini']::text[], 'match', 'lesson', 'Relie chaque réponse de la messe à son sens.', '{}'::text[], 'Quatre mots que tu réponds sans y penser, et que tu comprends maintenant.', 2, '{"id": "eg.l1514.e10", "unitIds": ["eg.g1514.amen_paix", "eg.v.cop_amin", "eg.v.cop_alleluia", "eg.v.cop_sha_enah", "eg.v.cop_irini"], "type": "match", "difficulty": 2, "prompt": "Relie chaque réponse de la messe à son sens.", "promptLanguage": "cop", "acceptedAnswers": [], "explanation": "Quatre mots que tu réponds sans y penser, et que tu comprends maintenant.", "instruction": "Associe chaque élément de gauche à celui de droite.", "pairs": [{"left": "ⲁ̀ⲙⲏⲛ", "right": "c''est vrai"}, {"left": "ⲁ̀ⲗⲗⲏⲗⲟⲩⲓⲁ", "right": "louez Dieu"}, {"left": "ϣⲁ ⲉ̀ⲛⲉϩ", "right": "pour toujours"}, {"left": "ⲓ̀ⲣⲏⲛⲏ", "right": "paix"}], "pool": "lesson", "lessonId": "eg.l1514", "skill": "recognition", "answer": "ⲁ̀ⲙⲏⲛ = c''est vrai ; ⲁ̀ⲗⲗⲏⲗⲟⲩⲓⲁ = louez Dieu ; ϣⲁ ⲉ̀ⲛⲉϩ = pour toujours ; ⲓ̀ⲣⲏⲛⲏ = paix"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1514.e11', 'eg', 'eg.l1514', 'eg.g1514.amen_paix', array['eg.g1514.amen_paix','eg.v.cop_amin','eg.v.cop_alleluia']::text[], 'mcq', 'lesson', 'Lequel de ces mots de la messe vient de l''hébreu ?', array['ⲁ̀ⲙⲏⲛ']::text[], 'Amen et alléluia sont hébreux ; ⲓ̀ⲣⲏⲛⲏ est grec et ϣⲁ ⲉ̀ⲛⲉϩ égyptien.', 2, '{"id": "eg.l1514.e11", "unitIds": ["eg.g1514.amen_paix", "eg.v.cop_amin", "eg.v.cop_alleluia"], "type": "mcq", "difficulty": 2, "prompt": "Lequel de ces mots de la messe vient de l''hébreu ?", "promptLanguage": "cop", "answer": "ⲁ̀ⲙⲏⲛ", "acceptedAnswers": ["ⲁ̀ⲙⲏⲛ"], "explanation": "Amen et alléluia sont hébreux ; ⲓ̀ⲣⲏⲛⲏ est grec et ϣⲁ ⲉ̀ⲛⲉϩ égyptien.", "instruction": "Choisis la bonne réponse.", "options": ["ⲓ̀ⲣⲏⲛⲏ", "ϣⲁ ⲉ̀ⲛⲉϩ", "ⲁ̀ⲙⲏⲛ"], "pool": "lesson", "lessonId": "eg.l1514", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1514.e12', 'eg', 'eg.l1514', 'eg.g1514.amen_paix', array['eg.g1514.amen_paix','eg.v.cop_irini','eg.g1502.mots_grecs']::text[], 'fill_blank', 'lesson', 'Ⲓ̀ⲣⲏⲛⲏ ⲡⲁⲥⲓ est un mot ___.', array['grec']::text[], 'ⲓ̀ⲣⲏⲛⲏ est grec, comme ⲁⲅⲅⲉⲗⲟⲥ.', 2, '{"id": "eg.l1514.e12", "unitIds": ["eg.g1514.amen_paix", "eg.v.cop_irini", "eg.g1502.mots_grecs"], "type": "fill_blank", "difficulty": 2, "prompt": "Ⲓ̀ⲣⲏⲛⲏ ⲡⲁⲥⲓ est un mot ___.", "promptLanguage": "cop", "answer": "grec", "acceptedAnswers": ["grec"], "explanation": "ⲓ̀ⲣⲏⲛⲏ est grec, comme ⲁⲅⲅⲉⲗⲟⲥ.", "instruction": "Touche le mot qui manque.", "options": ["copte", "hébreu", "grec"], "pool": "lesson", "lessonId": "eg.l1514", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1514.e13', 'eg', 'eg.l1514', 'eg.g1514.amen_paix', array['eg.g1514.amen_paix','eg.v.cop_irini','eg.v.cop_ouro','eg.v.cop_nte','eg.g1511.titres_de_dieu']::text[], 'mcq', 'lesson', 'Dans ⲡⲓⲟⲩⲣⲟ ⲛ̀ⲧⲉ ϯⲓ̀ⲣⲏⲛⲏ, que veut dire ϯⲓ̀ⲣⲏⲛⲏ ?', array['la paix']::text[], 'ⲡⲓⲟⲩⲣⲟ (le roi) + ⲛ̀ⲧⲉ (de) + ϯⲓ̀ⲣⲏⲛⲏ (la paix).', 2, '{"id": "eg.l1514.e13", "unitIds": ["eg.g1514.amen_paix", "eg.v.cop_irini", "eg.v.cop_ouro", "eg.v.cop_nte", "eg.g1511.titres_de_dieu"], "type": "mcq", "difficulty": 2, "prompt": "Dans ⲡⲓⲟⲩⲣⲟ ⲛ̀ⲧⲉ ϯⲓ̀ⲣⲏⲛⲏ, que veut dire ϯⲓ̀ⲣⲏⲛⲏ ?", "promptLanguage": "cop", "answer": "la paix", "acceptedAnswers": ["la paix"], "explanation": "ⲡⲓⲟⲩⲣⲟ (le roi) + ⲛ̀ⲧⲉ (de) + ϯⲓ̀ⲣⲏⲛⲏ (la paix).", "instruction": "Choisis la bonne réponse.", "options": ["le roi", "la paix", "le Père"], "pool": "lesson", "lessonId": "eg.l1514", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
