insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1515.e08', 'eg', 'eg.l1515', 'eg.g1515.pitie_gloire', array['eg.g1515.pitie_gloire','eg.v.cop_iwou','eg.v.cop_doxa']::text[], 'mcq', 'lesson', 'Lequel est le mot copte pour la gloire ?', array['ⲡⲓⲱⲟⲩ']::text[], 'ⲇⲟⲝⲁ est grec ; ⲡⲓⲱⲟⲩ est copte.', 2, '{"id": "eg.l1515.e08", "unitIds": ["eg.g1515.pitie_gloire", "eg.v.cop_iwou", "eg.v.cop_doxa"], "type": "mcq", "difficulty": 2, "prompt": "Lequel est le mot copte pour la gloire ?", "promptLanguage": "cop", "answer": "ⲡⲓⲱⲟⲩ", "acceptedAnswers": ["ⲡⲓⲱⲟⲩ"], "explanation": "ⲇⲟⲝⲁ est grec ; ⲡⲓⲱⲟⲩ est copte.", "instruction": "Choisis la bonne réponse.", "step": 4, "options": ["ⲇⲟⲝⲁ", "ⲡⲓⲱⲟⲩ", "ⲓ̀ⲣⲏⲛⲏ"], "pool": "lesson", "lessonId": "eg.l1515", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1515.e09', 'eg', 'eg.l1515', 'eg.g1515.pitie_gloire', array['eg.g1515.pitie_gloire','eg.v.cop_kyrie','eg.v.cop_nai']::text[], 'mcq', 'lesson', 'ⲛⲁⲓ ⲛⲁⲛ est la version copte de quelle formule grecque ?', array['Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ']::text[], 'Les deux demandent la pitié : l''une en grec, l''autre en copte.', 1, '{"id": "eg.l1515.e09", "unitIds": ["eg.g1515.pitie_gloire", "eg.v.cop_kyrie", "eg.v.cop_nai"], "type": "mcq", "difficulty": 1, "prompt": "ⲛⲁⲓ ⲛⲁⲛ est la version copte de quelle formule grecque ?", "promptLanguage": "cop", "answer": "Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ", "acceptedAnswers": ["Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ"], "explanation": "Les deux demandent la pitié : l''une en grec, l''autre en copte.", "instruction": "Choisis la bonne réponse.", "step": 5, "options": ["Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ", "Ⲇⲟⲝⲁ ⲥⲓ Ⲕⲩⲣⲓⲉ", "Ⲓ̀ⲣⲏⲛⲏ ⲡⲁⲥⲓ"], "pool": "lesson", "lessonId": "eg.l1515", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1515.e10', 'eg', 'eg.l1515', 'eg.g1515.pitie_gloire', array['eg.g1515.pitie_gloire','eg.v.cop_kyrie','eg.v.cop_nai','eg.v.cop_doxa','eg.v.cop_iwou']::text[], 'match', 'lesson', 'Relie chaque formule à son sens.', '{}'::text[], 'Pitié et gloire, en grec puis en copte.', 2, '{"id": "eg.l1515.e10", "unitIds": ["eg.g1515.pitie_gloire", "eg.v.cop_kyrie", "eg.v.cop_nai", "eg.v.cop_doxa", "eg.v.cop_iwou"], "type": "match", "difficulty": 2, "prompt": "Relie chaque formule à son sens.", "promptLanguage": "cop", "acceptedAnswers": [], "explanation": "Pitié et gloire, en grec puis en copte.", "instruction": "Associe chaque élément de gauche à celui de droite.", "pairs": [{"left": "Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ", "right": "Seigneur, aie pitié"}, {"left": "ⲛⲁⲓ ⲛⲁⲛ", "right": "aie pitié de nous"}, {"left": "Ⲇⲟⲝⲁ ⲥⲓ Ⲕⲩⲣⲓⲉ", "right": "gloire à toi, Seigneur"}, {"left": "ⲡⲓⲱⲟⲩ", "right": "la gloire"}], "pool": "lesson", "lessonId": "eg.l1515", "skill": "recognition", "answer": "Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ = Seigneur, aie pitié ; ⲛⲁⲓ ⲛⲁⲛ = aie pitié de nous ; Ⲇⲟⲝⲁ ⲥⲓ Ⲕⲩⲣⲓⲉ = gloire à toi, Seigneur ; ⲡⲓⲱⲟⲩ = la gloire"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1515.e11', 'eg', 'eg.l1515', 'eg.g1515.pitie_gloire', array['eg.g1515.pitie_gloire','eg.v.cop_doxa','eg.v.cop_kyrie']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : « gloire à toi, Seigneur ».', array['Ⲇⲟⲝⲁ ⲥⲓ Ⲕⲩⲣⲓⲉ']::text[], 'Gloire, à toi, Seigneur : trois mots grecs.', 2, '{"id": "eg.l1515.e11", "unitIds": ["eg.g1515.pitie_gloire", "eg.v.cop_doxa", "eg.v.cop_kyrie"], "type": "reorder", "difficulty": 2, "prompt": "Remets dans l''ordre : « gloire à toi, Seigneur ».", "promptLanguage": "fr", "answer": "Ⲇⲟⲝⲁ ⲥⲓ Ⲕⲩⲣⲓⲉ", "acceptedAnswers": ["Ⲇⲟⲝⲁ ⲥⲓ Ⲕⲩⲣⲓⲉ"], "explanation": "Gloire, à toi, Seigneur : trois mots grecs.", "instruction": "Remets dans l''ordre.", "tokens": ["Ⲕⲩⲣⲓⲉ", "ⲥⲓ", "Ⲇⲟⲝⲁ"], "pool": "lesson", "lessonId": "eg.l1515", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1515.e12', 'eg', 'eg.l1515', 'eg.g1515.pitie_gloire', array['eg.g1515.pitie_gloire','eg.v.cop_nai','eg.v.cop_pen','eg.g1506.possessifs']::text[], 'mcq', 'lesson', 'Le ⲛ de ⲛⲁⲛ est le même que dans ⲡⲉⲛ-. Que veut dire ⲡⲉⲛ- ?', array['notre']::text[], 'Le ⲛ est toujours le « nous ».', 2, '{"id": "eg.l1515.e12", "unitIds": ["eg.g1515.pitie_gloire", "eg.v.cop_nai", "eg.v.cop_pen", "eg.g1506.possessifs"], "type": "mcq", "difficulty": 2, "prompt": "Le ⲛ de ⲛⲁⲛ est le même que dans ⲡⲉⲛ-. Que veut dire ⲡⲉⲛ- ?", "promptLanguage": "fr", "answer": "notre", "acceptedAnswers": ["notre"], "explanation": "Le ⲛ est toujours le « nous ».", "instruction": "Choisis la bonne réponse.", "options": ["notre", "votre", "leur"], "pool": "lesson", "lessonId": "eg.l1515", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
