insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1515.e14', 'eg', 'eg.l1515', 'eg.g1515.pitie_gloire', array['eg.g1515.pitie_gloire','eg.v.cop_kyrie','eg.g1504.nomina_sacra']::text[], 'mcq', 'lesson', 'Ⲕⲩⲣⲓⲉ veut dire Seigneur. Quel mot copte, abrégé en ⲡ̅ⲟ̅ⲥ̅, dit aussi « le Seigneur » ?', array['Ⲡϭⲟⲓⲥ']::text[], 'Ⲡϭⲟⲓⲥ s''abrège ⲡ̅ⲟ̅ⲥ̅ : le Seigneur en copte.', 2, '{"id": "eg.l1515.e14", "unitIds": ["eg.g1515.pitie_gloire", "eg.v.cop_kyrie", "eg.g1504.nomina_sacra"], "type": "mcq", "difficulty": 2, "prompt": "Ⲕⲩⲣⲓⲉ veut dire Seigneur. Quel mot copte, abrégé en ⲡ̅ⲟ̅ⲥ̅, dit aussi « le Seigneur » ?", "promptLanguage": "fr", "answer": "Ⲡϭⲟⲓⲥ", "acceptedAnswers": ["Ⲡϭⲟⲓⲥ"], "explanation": "Ⲡϭⲟⲓⲥ s''abrège ⲡ̅ⲟ̅ⲥ̅ : le Seigneur en copte.", "instruction": "Choisis la bonne réponse.", "options": ["Ⲫ̀ⲛⲟⲩϯ", "Ⲡϭⲟⲓⲥ", "Ⲡ̀ϣⲏⲣⲓ"], "pool": "lesson", "lessonId": "eg.l1515", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1515.e15', 'eg', 'eg.l1515', 'eg.g1515.pitie_gloire', array['eg.g1515.pitie_gloire','eg.v.cop_kyrie','eg.v.cop_nai']::text[], 'mcq', 'lesson', 'Pourquoi la messe garde-t-elle ⲛⲁⲓ ⲛⲁⲛ à côté de Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ ?', array['Le copte dit la même demande avec ses propres mots']::text[], 'Le copte a souvent deux mots, l''un grec, l''autre copte, pour la même idée.', 3, '{"id": "eg.l1515.e15", "unitIds": ["eg.g1515.pitie_gloire", "eg.v.cop_kyrie", "eg.v.cop_nai"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi la messe garde-t-elle ⲛⲁⲓ ⲛⲁⲛ à côté de Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ ?", "promptLanguage": "fr", "answer": "Le copte dit la même demande avec ses propres mots", "acceptedAnswers": ["Le copte dit la même demande avec ses propres mots"], "explanation": "Le copte a souvent deux mots, l''un grec, l''autre copte, pour la même idée.", "instruction": "Choisis la bonne réponse.", "options": ["Le copte a oublié le grec", "Le copte dit la même demande avec ses propres mots", "Les deux disent des choses opposées"], "pool": "lesson", "lessonId": "eg.l1515", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
