insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1516.e13', 'eg', 'eg.l1516', 'eg.g1516.copte_dans_arabe', array['eg.g1516.copte_dans_arabe','eg.v.cop_fayoum','eg.g1505.articles']::text[], 'mcq', 'lesson', 'Dans ⲫⲓⲟⲙ, le ⲫ est un article. Quel autre mot de la leçon sur les articles commence par ce même ⲫ̀ ?', array['Ⲫ̀ⲛⲟⲩϯ']::text[], 'Ⲫ̀ⲛⲟⲩϯ = ⲫ̀ + ⲛⲟⲩϯ : le même article.', 2, '{"id": "eg.l1516.e13", "unitIds": ["eg.g1516.copte_dans_arabe", "eg.v.cop_fayoum", "eg.g1505.articles"], "type": "mcq", "difficulty": 2, "prompt": "Dans ⲫⲓⲟⲙ, le ⲫ est un article. Quel autre mot de la leçon sur les articles commence par ce même ⲫ̀ ?", "promptLanguage": "fr", "answer": "Ⲫ̀ⲛⲟⲩϯ", "acceptedAnswers": ["Ⲫ̀ⲛⲟⲩϯ"], "explanation": "Ⲫ̀ⲛⲟⲩϯ = ⲫ̀ + ⲛⲟⲩϯ : le même article.", "instruction": "Choisis la bonne réponse.", "options": ["Ⲫ̀ⲛⲟⲩϯ", "Ⲡϭⲟⲓⲥ", "ϯⲉⲕⲕⲗⲏⲥⲓⲁ"], "pool": "lesson", "lessonId": "eg.l1516", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1516.e14', 'eg', 'eg.l1516', 'eg.g1516.copte_dans_arabe', array['eg.g1516.copte_dans_arabe','eg.v.cop_toub']::text[], 'mcq', 'lesson', 'Pourquoi طوب et طوبة ne sont-ils pas le même mot ?', array['Ils viennent de deux mots coptes différents']::text[], 'ⲧⲱⲃⲉ (brique) et ⲧⲱⲃⲓ (mois) se ressemblent, mais restent deux mots.', 3, '{"id": "eg.l1516.e14", "unitIds": ["eg.g1516.copte_dans_arabe", "eg.v.cop_toub"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi طوب et طوبة ne sont-ils pas le même mot ?", "promptLanguage": "fr", "answer": "Ils viennent de deux mots coptes différents", "acceptedAnswers": ["Ils viennent de deux mots coptes différents"], "explanation": "ⲧⲱⲃⲉ (brique) et ⲧⲱⲃⲓ (mois) se ressemblent, mais restent deux mots.", "instruction": "Choisis la bonne réponse.", "options": ["L''un est arabe, l''autre grec", "طوبة est le pluriel de طوب", "Ils viennent de deux mots coptes différents"], "pool": "lesson", "lessonId": "eg.l1516", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
