insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1517.e10', 'eg', 'eg.l1517', 'eg.g1517.prenoms_coptes', array['eg.g1517.prenoms_coptes','eg.v.cop_shenouda','eg.v.cop_bishoy','eg.v.cop_tawadros','eg.v.cop_anba']::text[], 'match', 'lesson', 'Relie chaque prénom à son sens.', '{}'::text[], 'Chaque prénom est un petit texte en copte ou en grec.', 2, '{"id": "eg.l1517.e10", "unitIds": ["eg.g1517.prenoms_coptes", "eg.v.cop_shenouda", "eg.v.cop_bishoy", "eg.v.cop_tawadros", "eg.v.cop_anba"], "type": "match", "difficulty": 2, "prompt": "Relie chaque prénom à son sens.", "promptLanguage": "fr", "acceptedAnswers": [], "explanation": "Chaque prénom est un petit texte en copte ou en grec.", "instruction": "Associe chaque élément de gauche à celui de droite.", "pairs": [{"left": "شنودة", "right": "enfant de Dieu"}, {"left": "بيشوي", "right": "le haut"}, {"left": "تاوضروس", "right": "don de Dieu"}, {"left": "أنبا", "right": "père"}], "pool": "lesson", "lessonId": "eg.l1517", "skill": "recognition", "answer": "شنودة = enfant de Dieu ; بيشوي = le haut ; تاوضروس = don de Dieu ; أنبا = père"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1517.e11', 'eg', 'eg.l1517', 'eg.g1517.prenoms_coptes', array['eg.g1517.prenoms_coptes','eg.v.cop_bishoy','eg.v.cop_pi','eg.g1505.articles']::text[], 'mcq', 'lesson', 'Dans Ⲡⲓϣⲱⲓ, ⲡⲓ est l''article « le ». Quel autre mot a le même article ?', array['ⲡⲓⲁⲅⲅⲉⲗⲟⲥ']::text[], 'ⲡⲓⲁⲅⲅⲉⲗⲟⲥ : l''ange, au masculin singulier.', 2, '{"id": "eg.l1517.e11", "unitIds": ["eg.g1517.prenoms_coptes", "eg.v.cop_bishoy", "eg.v.cop_pi", "eg.g1505.articles"], "type": "mcq", "difficulty": 2, "prompt": "Dans Ⲡⲓϣⲱⲓ, ⲡⲓ est l''article « le ». Quel autre mot a le même article ?", "promptLanguage": "fr", "answer": "ⲡⲓⲁⲅⲅⲉⲗⲟⲥ", "acceptedAnswers": ["ⲡⲓⲁⲅⲅⲉⲗⲟⲥ"], "explanation": "ⲡⲓⲁⲅⲅⲉⲗⲟⲥ : l''ange, au masculin singulier.", "instruction": "Choisis la bonne réponse.", "options": ["ϯⲉⲕⲕⲗⲏⲥⲓⲁ", "ⲛⲓⲁⲅⲅⲉⲗⲟⲥ", "ⲡⲓⲁⲅⲅⲉⲗⲟⲥ"], "pool": "lesson", "lessonId": "eg.l1517", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1517.e12', 'eg', 'eg.l1517', 'eg.g1517.prenoms_coptes', array['eg.g1517.prenoms_coptes','eg.v.cop_tawadros','eg.v.cop_theotokos','eg.g1512.vierge_marie']::text[], 'fill_blank', 'lesson', 'Tawadros contient ⲑⲉⲟ, comme ϯⲑⲉⲟⲧⲟⲕⲟⲥ : ⲑⲉⲟ veut dire ___.', array['Dieu']::text[], 'ⲑⲉⲟ : Dieu, en grec.', 2, '{"id": "eg.l1517.e12", "unitIds": ["eg.g1517.prenoms_coptes", "eg.v.cop_tawadros", "eg.v.cop_theotokos", "eg.g1512.vierge_marie"], "type": "fill_blank", "difficulty": 2, "prompt": "Tawadros contient ⲑⲉⲟ, comme ϯⲑⲉⲟⲧⲟⲕⲟⲥ : ⲑⲉⲟ veut dire ___.", "promptLanguage": "cop", "answer": "Dieu", "acceptedAnswers": ["Dieu"], "explanation": "ⲑⲉⲟ : Dieu, en grec.", "instruction": "Touche le mot qui manque.", "options": ["don", "mère", "Dieu"], "pool": "lesson", "lessonId": "eg.l1517", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1517.e13', 'eg', 'eg.l1517', 'eg.g1517.prenoms_coptes', array['eg.g1517.prenoms_coptes','eg.v.cop_bishoy','eg.v.cop_fayoum','eg.g1516.copte_dans_arabe']::text[], 'mcq', 'lesson', 'Le Fayoum et Bishoy ont un point commun : un mot copte précédé de…', array['l''article']::text[], 'ⲫ + ⲓⲟⲙ et ⲡⲓ + ϣⲱⲓ : l''article est collé au nom.', 2, '{"id": "eg.l1517.e13", "unitIds": ["eg.g1517.prenoms_coptes", "eg.v.cop_bishoy", "eg.v.cop_fayoum", "eg.g1516.copte_dans_arabe"], "type": "mcq", "difficulty": 2, "prompt": "Le Fayoum et Bishoy ont un point commun : un mot copte précédé de…", "promptLanguage": "fr", "answer": "l''article", "acceptedAnswers": ["l''article"], "explanation": "ⲫ + ⲓⲟⲙ et ⲡⲓ + ϣⲱⲓ : l''article est collé au nom.", "instruction": "Choisis la bonne réponse.", "options": ["la jinkim", "l''article", "un possessif"], "pool": "lesson", "lessonId": "eg.l1517", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1517.e14', 'eg', 'eg.l1517', 'eg.g1517.prenoms_coptes', array['eg.g1517.prenoms_coptes','eg.v.cop_tawadros','eg.v.c01_alexandrie']::text[], 'mcq', 'lesson', 'Pourquoi Tawadros et Boutros sont-ils des prénoms grecs et non égyptiens ?', array['Le grec était très présent dans l''Église d''Alexandrie']::text[], 'Alexandrie était une ville grecque : beaucoup de noms chrétiens viennent du grec.', 3, '{"id": "eg.l1517.e14", "unitIds": ["eg.g1517.prenoms_coptes", "eg.v.cop_tawadros", "eg.v.c01_alexandrie"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi Tawadros et Boutros sont-ils des prénoms grecs et non égyptiens ?", "promptLanguage": "fr", "answer": "Le grec était très présent dans l''Église d''Alexandrie", "acceptedAnswers": ["Le grec était très présent dans l''Église d''Alexandrie"], "explanation": "Alexandrie était une ville grecque : beaucoup de noms chrétiens viennent du grec.", "instruction": "Choisis la bonne réponse.", "options": ["Le grec était très présent dans l''Église d''Alexandrie", "Les Arabes les ont inventés", "Les pharaons parlaient grec"], "pool": "lesson", "lessonId": "eg.l1517", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
