insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1518.e03', 'eg', 'eg.l1518', 'eg.g1518.bilan_copte', array['eg.g1518.bilan_copte','eg.v.cop_phran']::text[], 'mcq', 'lesson', 'Dans la formule de la Trinité, combien y a-t-il de noms ?', array['un seul nom']::text[], 'Le singulier ⲫ̀ⲣⲁⲛ dit : un seul nom pour trois personnes.', 1, '{"id": "eg.l1518.e03", "unitIds": ["eg.g1518.bilan_copte", "eg.v.cop_phran"], "type": "mcq", "difficulty": 1, "prompt": "Dans la formule de la Trinité, combien y a-t-il de noms ?", "promptLanguage": "fr", "answer": "un seul nom", "acceptedAnswers": ["un seul nom"], "explanation": "Le singulier ⲫ̀ⲣⲁⲛ dit : un seul nom pour trois personnes.", "instruction": "Choisis la bonne réponse.", "step": 3, "options": ["trois noms", "un seul nom", "deux noms"], "pool": "lesson", "lessonId": "eg.l1518", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1518.e04', 'eg', 'eg.l1518', 'eg.g1518.bilan_copte', array['eg.g1518.bilan_copte','eg.v.cop_af']::text[], 'mcq', 'lesson', 'Que veut dire Ⲭ̀ⲣⲓⲥⲧⲟⲥ ⲁϥⲧⲱⲛϥ ?', array['le Christ est ressuscité']::text[], 'ⲁ (passé) + ϥ (il) + ⲧⲱⲛ (se lever) + ϥ (lui-même).', 1, '{"id": "eg.l1518.e04", "unitIds": ["eg.g1518.bilan_copte", "eg.v.cop_af"], "type": "mcq", "difficulty": 1, "prompt": "Que veut dire Ⲭ̀ⲣⲓⲥⲧⲟⲥ ⲁϥⲧⲱⲛϥ ?", "promptLanguage": "cop", "answer": "le Christ est ressuscité", "acceptedAnswers": ["le Christ est ressuscité"], "explanation": "ⲁ (passé) + ϥ (il) + ⲧⲱⲛ (se lever) + ϥ (lui-même).", "instruction": "Choisis la bonne réponse.", "step": 4, "options": ["le Christ croit", "le Christ est ressuscité", "le Christ bénit"], "pool": "lesson", "lessonId": "eg.l1518", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1518.e05', 'eg', 'eg.l1518', 'eg.g1518.bilan_copte', array['eg.g1518.bilan_copte','eg.v.cop_pen','eg.v.cop_af','eg.v.cop_hen','eg.v.cop_ni','eg.v.cop_hiten']::text[], 'match', 'lesson', 'Relie chaque petit élément à son sens.', '{}'::text[], 'Possessif, verbe, petits mots, article : les briques de toute formule.', 2, '{"id": "eg.l1518.e05", "unitIds": ["eg.g1518.bilan_copte", "eg.v.cop_pen", "eg.v.cop_af", "eg.v.cop_hen", "eg.v.cop_ni", "eg.v.cop_hiten"], "type": "match", "difficulty": 2, "prompt": "Relie chaque petit élément à son sens.", "promptLanguage": "cop", "acceptedAnswers": [], "explanation": "Possessif, verbe, petits mots, article : les briques de toute formule.", "instruction": "Associe chaque élément de gauche à celui de droite.", "pairs": [{"left": "ⲡⲉⲛ-", "right": "notre"}, {"left": "ⲁϥ-", "right": "il a"}, {"left": "ϧⲉⲛ", "right": "dans, en"}, {"left": "ⲛⲓ", "right": "les (article pluriel)"}, {"left": "ϩⲓⲧⲉⲛ", "right": "par"}], "pool": "lesson", "lessonId": "eg.l1518", "skill": "recognition", "answer": "ⲡⲉⲛ- = notre ; ⲁϥ- = il a ; ϧⲉⲛ = dans, en ; ⲛⲓ = les (article pluriel) ; ϩⲓⲧⲉⲛ = par"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1518.e06', 'eg', 'eg.l1518', 'eg.g1518.bilan_copte', array['eg.g1518.bilan_copte','eg.v.cop_phran','eg.v.cop_phiot','eg.v.cop_pshiri','eg.v.cop_pnevma']::text[], 'reorder', 'lesson', 'Reconstitue, mot à mot, la formule du signe de croix : « dans le nom du Père, du Fils et du Saint-Esprit ».', array['ϧⲉⲛ ⲫ̀ⲣⲁⲛ ⲙ̀Ⲫ̀ⲓⲱⲧ ⲛⲉⲙ Ⲡ̀ϣⲏⲣⲓ ⲛⲉⲙ Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ ⲉⲑⲟⲩⲁⲃ']::text[], 'Un seul nom, trois personnes : tu lis maintenant chaque mot.', 3, '{"id": "eg.l1518.e06", "unitIds": ["eg.g1518.bilan_copte", "eg.v.cop_phran", "eg.v.cop_phiot", "eg.v.cop_pshiri", "eg.v.cop_pnevma"], "type": "reorder", "difficulty": 3, "prompt": "Reconstitue, mot à mot, la formule du signe de croix : « dans le nom du Père, du Fils et du Saint-Esprit ».", "promptLanguage": "fr", "answer": "ϧⲉⲛ ⲫ̀ⲣⲁⲛ ⲙ̀Ⲫ̀ⲓⲱⲧ ⲛⲉⲙ Ⲡ̀ϣⲏⲣⲓ ⲛⲉⲙ Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ ⲉⲑⲟⲩⲁⲃ", "acceptedAnswers": ["ϧⲉⲛ ⲫ̀ⲣⲁⲛ ⲙ̀Ⲫ̀ⲓⲱⲧ ⲛⲉⲙ Ⲡ̀ϣⲏⲣⲓ ⲛⲉⲙ Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ ⲉⲑⲟⲩⲁⲃ"], "explanation": "Un seul nom, trois personnes : tu lis maintenant chaque mot.", "instruction": "Remets dans l''ordre.", "tokens": ["ⲉⲑⲟⲩⲁⲃ", "Ⲡ̀ϣⲏⲣⲓ", "ⲙ̀Ⲫ̀ⲓⲱⲧ", "ⲛⲉⲙ", "ϧⲉⲛ", "Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ", "ⲫ̀ⲣⲁⲛ", "ⲛⲉⲙ"], "pool": "lesson", "lessonId": "eg.l1518", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1518.e07', 'eg', 'eg.l1518', 'eg.g1518.bilan_copte', array['eg.g1518.bilan_copte','eg.v.cop_hiten','eg.v.cop_presbia','eg.v.cop_theotokos']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : « par les intercessions de la sainte mère de Dieu, Marie » (en copte).', array['ϩⲓⲧⲉⲛ ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ ⲛ̀ⲧⲉ ϯⲑⲉⲟⲧⲟⲕⲟⲥ ⲉⲑⲟⲩⲁⲃ Ⲙⲁⲣⲓⲁ']::text[], 'Presque tout est grec, avec des petits mots coptes.', 3, '{"id": "eg.l1518.e07", "unitIds": ["eg.g1518.bilan_copte", "eg.v.cop_hiten", "eg.v.cop_presbia", "eg.v.cop_theotokos"], "type": "reorder", "difficulty": 3, "prompt": "Remets dans l''ordre : « par les intercessions de la sainte mère de Dieu, Marie » (en copte).", "promptLanguage": "fr", "answer": "ϩⲓⲧⲉⲛ ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ ⲛ̀ⲧⲉ ϯⲑⲉⲟⲧⲟⲕⲟⲥ ⲉⲑⲟⲩⲁⲃ Ⲙⲁⲣⲓⲁ", "acceptedAnswers": ["ϩⲓⲧⲉⲛ ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ ⲛ̀ⲧⲉ ϯⲑⲉⲟⲧⲟⲕⲟⲥ ⲉⲑⲟⲩⲁⲃ Ⲙⲁⲣⲓⲁ"], "explanation": "Presque tout est grec, avec des petits mots coptes.", "instruction": "Remets dans l''ordre.", "tokens": ["ⲉⲑⲟⲩⲁⲃ", "ⲛ̀ⲧⲉ", "ϩⲓⲧⲉⲛ", "ϯⲑⲉⲟⲧⲟⲕⲟⲥ", "Ⲙⲁⲣⲓⲁ", "ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ"], "pool": "lesson", "lessonId": "eg.l1518", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1518.e08', 'eg', 'eg.l1518', 'eg.g1518.bilan_copte', array['eg.g1518.bilan_copte','eg.v.cop_alithos','eg.v.cop_af','eg.v.cop_ton']::text[], 'mcq', 'lesson', 'Que veut dire ⲁ̀ⲗⲏⲑⲱⲥ ⲁϥⲧⲱⲛϥ ?', array['vraiment, il est ressuscité']::text[], 'Le grec ⲁ̀ⲗⲏⲑⲱⲥ (vraiment) + ⲁϥⲧⲱⲛϥ (il est ressuscité).', 2, '{"id": "eg.l1518.e08", "unitIds": ["eg.g1518.bilan_copte", "eg.v.cop_alithos", "eg.v.cop_af", "eg.v.cop_ton"], "type": "mcq", "difficulty": 2, "prompt": "Que veut dire ⲁ̀ⲗⲏⲑⲱⲥ ⲁϥⲧⲱⲛϥ ?", "promptLanguage": "cop", "answer": "vraiment, il est ressuscité", "acceptedAnswers": ["vraiment, il est ressuscité"], "explanation": "Le grec ⲁ̀ⲗⲏⲑⲱⲥ (vraiment) + ⲁϥⲧⲱⲛϥ (il est ressuscité).", "instruction": "Choisis la bonne réponse.", "options": ["vraiment, il est ressuscité", "vraiment, il croit", "toujours, il est venu"], "pool": "lesson", "lessonId": "eg.l1518", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
