insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1518.e10', 'eg', 'eg.l1518', 'eg.g1518.bilan_copte', array['eg.g1518.bilan_copte','eg.v.cop_pen','eg.v.cop_soter']::text[], 'mcq', 'lesson', 'Comment traduire Ⲡⲉⲛⲥⲱⲧⲏⲣ dans une prière ?', array['notre Sauveur']::text[], 'Ⲡⲉⲛ- (notre) + ⲥⲱⲧⲏⲣ (sauveur).', 2, '{"id": "eg.l1518.e10", "unitIds": ["eg.g1518.bilan_copte", "eg.v.cop_pen", "eg.v.cop_soter"], "type": "mcq", "difficulty": 2, "prompt": "Comment traduire Ⲡⲉⲛⲥⲱⲧⲏⲣ dans une prière ?", "promptLanguage": "cop", "answer": "notre Sauveur", "acceptedAnswers": ["notre Sauveur"], "explanation": "Ⲡⲉⲛ- (notre) + ⲥⲱⲧⲏⲣ (sauveur).", "instruction": "Choisis la bonne réponse.", "options": ["notre Seigneur", "notre roi", "notre Sauveur"], "pool": "lesson", "lessonId": "eg.l1518", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
