insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1518.e12', 'eg', 'eg.l1518', 'eg.g1518.bilan_copte', array['eg.g1518.bilan_copte','eg.v.cop_nai','eg.v.cop_theotokos','eg.v.cop_irini']::text[], 'mcq', 'lesson', 'Parmi ces mots de la messe, lequel est égyptien ?', array['ⲛⲁⲓ']::text[], 'ⲛⲁⲓ est le mot copte de la pitié ; les deux autres sont grecs.', 2, '{"id": "eg.l1518.e12", "unitIds": ["eg.g1518.bilan_copte", "eg.v.cop_nai", "eg.v.cop_theotokos", "eg.v.cop_irini"], "type": "mcq", "difficulty": 2, "prompt": "Parmi ces mots de la messe, lequel est égyptien ?", "promptLanguage": "cop", "answer": "ⲛⲁⲓ", "acceptedAnswers": ["ⲛⲁⲓ"], "explanation": "ⲛⲁⲓ est le mot copte de la pitié ; les deux autres sont grecs.", "instruction": "Choisis la bonne réponse.", "options": ["ⲛⲁⲓ", "ϯⲑⲉⲟⲧⲟⲕⲟⲥ", "ⲓ̀ⲣⲏⲛⲏ"], "pool": "lesson", "lessonId": "eg.l1518", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1518.e13', 'eg', 'eg.l1518', 'eg.g1518.bilan_copte', array['eg.g1518.bilan_copte','eg.v.cop_angelos','eg.v.cop_ou']::text[], 'mcq', 'lesson', 'Tu entends ϩⲁⲛⲁⲅⲅⲉⲗⲟⲥ. Comment le comprends-tu ?', array['Je détache ϩⲁⲛ (des) : des anges']::text[], 'Détacher l''article ouvre le mot : ϩⲁⲛ + ⲁⲅⲅⲉⲗⲟⲥ.', 3, '{"id": "eg.l1518.e13", "unitIds": ["eg.g1518.bilan_copte", "eg.v.cop_angelos", "eg.v.cop_ou"], "type": "mcq", "difficulty": 3, "prompt": "Tu entends ϩⲁⲛⲁⲅⲅⲉⲗⲟⲥ. Comment le comprends-tu ?", "promptLanguage": "fr", "answer": "Je détache ϩⲁⲛ (des) : des anges", "acceptedAnswers": ["Je détache ϩⲁⲛ (des) : des anges"], "explanation": "Détacher l''article ouvre le mot : ϩⲁⲛ + ⲁⲅⲅⲉⲗⲟⲥ.", "instruction": "Choisis la bonne réponse.", "options": ["Je détache ϩⲁⲛ (des) : des anges", "Je lis ⲁⲅⲅⲉⲗⲟⲥ lettre par lettre", "Je cherche une surligne"], "pool": "lesson", "lessonId": "eg.l1518", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1518.e14', 'eg', 'eg.l1518', 'eg.g1518.bilan_copte', array['eg.g1518.bilan_copte','eg.v.cop_shenouda','eg.v.cop_tawadros']::text[], 'mcq', 'lesson', 'Un prénom comme Shenouda ou Tawadros est un petit texte. Pourquoi ?', array['On y reconnaît des mots coptes ou grecs']::text[], 'Ϣⲉⲛⲟⲩϯ cache ⲛⲟⲩϯ ; ⲑⲉⲟⲇⲱⲣⲟⲥ cache ⲑⲉⲟ et ⲇⲱⲣⲟⲥ.', 3, '{"id": "eg.l1518.e14", "unitIds": ["eg.g1518.bilan_copte", "eg.v.cop_shenouda", "eg.v.cop_tawadros"], "type": "mcq", "difficulty": 3, "prompt": "Un prénom comme Shenouda ou Tawadros est un petit texte. Pourquoi ?", "promptLanguage": "fr", "answer": "On y reconnaît des mots coptes ou grecs", "acceptedAnswers": ["On y reconnaît des mots coptes ou grecs"], "explanation": "Ϣⲉⲛⲟⲩϯ cache ⲛⲟⲩϯ ; ⲑⲉⲟⲇⲱⲣⲟⲥ cache ⲑⲉⲟ et ⲇⲱⲣⲟⲥ.", "instruction": "Choisis la bonne réponse.", "options": ["Il est toujours abrégé par une barre", "Il n''a aucun sens", "On y reconnaît des mots coptes ou grecs"], "pool": "lesson", "lessonId": "eg.l1518", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l1518.e15', 'eg', 'eg.l1518', 'eg.g1518.bilan_copte', array['eg.g1518.bilan_copte','eg.v.cop_nai','eg.v.cop_kyrie']::text[], 'mcq', 'lesson', 'ⲛⲁⲓ ⲛⲁⲛ est la version copte de…', array['Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ']::text[], 'Pitié en copte, pitié en grec.', 2, '{"id": "eg.l1518.e15", "unitIds": ["eg.g1518.bilan_copte", "eg.v.cop_nai", "eg.v.cop_kyrie"], "type": "mcq", "difficulty": 2, "prompt": "ⲛⲁⲓ ⲛⲁⲛ est la version copte de…", "promptLanguage": "cop", "answer": "Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ", "acceptedAnswers": ["Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ"], "explanation": "Pitié en copte, pitié en grec.", "instruction": "Choisis la bonne réponse.", "options": ["Ⲇⲟⲝⲁ ⲥⲓ Ⲕⲩⲣⲓⲉ", "Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ", "Ⲓ̀ⲣⲏⲛⲏ ⲡⲁⲥⲓ"], "pool": "lesson", "lessonId": "eg.l1518", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pentecote', 'eg', 'la Pentecôte', 'le jour où l''Esprit Saint descend sur les apôtres : la naissance de l''Église', 'Cinquante jours après Pâques, à Jérusalem, l''Esprit Saint descend sur les disciples comme des langues de feu. Pierre prêche et trois mille personnes sont baptisées. On y voit la naissance de l''Église.', '[{"text": "À la Pentecôte, les apôtres sortent enfin de la chambre haute.", "translation": "La peur laisse la place au courage."}]'::jsonb, null, '{"id": "eg.d.pentecote", "unitId": "eg.v.pentecote", "word": "la Pentecôte", "translation": "le jour où l''Esprit Saint descend sur les apôtres : la naissance de l''Église", "partOfSpeech": "event", "collection": "date", "explanation": "Cinquante jours après Pâques, à Jérusalem, l''Esprit Saint descend sur les disciples comme des langues de feu. Pierre prêche et trois mille personnes sont baptisées. On y voit la naissance de l''Église.", "examples": [{"text": "À la Pentecôte, les apôtres sortent enfin de la chambre haute.", "translation": "La peur laisse la place au courage."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.chambre_haute', 'eg', 'la chambre haute', 'la salle de Jérusalem où les disciples prient en attendant l''Esprit', 'Une salle à l''étage, à Jérusalem. Environ cent vingt disciples y prient ensemble, avec Marie, entre l''Ascension et la Pentecôte.', '[{"text": "Cent vingt personnes prient dans la chambre haute.", "translation": "Toute l''Église tient alors dans une pièce."}]'::jsonb, null, '{"id": "eg.d.chambre_haute", "unitId": "eg.v.chambre_haute", "word": "la chambre haute", "translation": "la salle de Jérusalem où les disciples prient en attendant l''Esprit", "partOfSpeech": "place", "collection": "lieu", "explanation": "Une salle à l''étage, à Jérusalem. Environ cent vingt disciples y prient ensemble, avec Marie, entre l''Ascension et la Pentecôte.", "examples": [{"text": "Cent vingt personnes prient dans la chambre haute.", "translation": "Toute l''Église tient alors dans une pièce."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.apotre', 'eg', 'l''apôtre', '« envoyé » : disciple choisi par Jésus et envoyé en mission', 'Le mot vient du grec et veut dire « envoyé ». Jésus en choisit douze. Après la Pentecôte, ils partent annoncer l''Évangile et fondent des Églises.', '[{"text": "Pierre est le premier apôtre à prêcher à la Pentecôte.", "translation": "Un apôtre est d''abord quelqu''un qu''on envoie."}]'::jsonb, null, '{"id": "eg.d.apotre", "unitId": "eg.v.apotre", "word": "l''apôtre", "translation": "« envoyé » : disciple choisi par Jésus et envoyé en mission", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le mot vient du grec et veut dire « envoyé ». Jésus en choisit douze. Après la Pentecôte, ils partent annoncer l''Évangile et fondent des Églises.", "examples": [{"text": "Pierre est le premier apôtre à prêcher à la Pentecôte.", "translation": "Un apôtre est d''abord quelqu''un qu''on envoie."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_premiere_communaute', 'eg', 'la première communauté', 'le premier groupe de croyants de Jérusalem, qui met tout en commun', 'Décrite dans les Actes des apôtres, c''est une communauté qui prie, qui écoute les apôtres et qui partage ses biens. Elle compte environ cinq mille croyants. L''Église la garde comme modèle.', '[{"text": "Dans la première communauté, personne ne manque de rien.", "translation": "Le partage fait partie de la vie chrétienne dès le début."}]'::jsonb, null, '{"id": "eg.d.c01_premiere_communaute", "unitId": "eg.v.c01_premiere_communaute", "word": "la première communauté", "translation": "le premier groupe de croyants de Jérusalem, qui met tout en commun", "partOfSpeech": "concept", "collection": "notion", "explanation": "Décrite dans les Actes des apôtres, c''est une communauté qui prie, qui écoute les apôtres et qui partage ses biens. Elle compte environ cinq mille croyants. L''Église la garde comme modèle.", "examples": [{"text": "Dans la première communauté, personne ne manque de rien.", "translation": "Le partage fait partie de la vie chrétienne dès le début."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_fraction_du_pain', 'eg', 'la fraction du pain', 'le nom que les premiers chrétiens donnent à l''eucharistie', 'Rompre le pain, c''est le geste de Jésus à la dernière Cène. Les premiers chrétiens désignent ainsi leur célébration de l''eucharistie, qu''ils vivent chaque jour avec les apôtres.', '[{"text": "Ils se retrouvent pour la fraction du pain.", "translation": "C''est leur façon de dire : on célèbre l''eucharistie."}]'::jsonb, null, '{"id": "eg.d.c01_fraction_du_pain", "unitId": "eg.v.c01_fraction_du_pain", "word": "la fraction du pain", "translation": "le nom que les premiers chrétiens donnent à l''eucharistie", "partOfSpeech": "concept", "collection": "notion", "explanation": "Rompre le pain, c''est le geste de Jésus à la dernière Cène. Les premiers chrétiens désignent ainsi leur célébration de l''eucharistie, qu''ils vivent chaque jour avec les apôtres.", "examples": [{"text": "Ils se retrouvent pour la fraction du pain.", "translation": "C''est leur façon de dire : on célèbre l''eucharistie."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_saint_pierre', 'eg', 'saint Pierre', 'chef des apôtres, premier à prêcher le jour de la Pentecôte', 'Pêcheur de Galilée, Simon reçoit de Jésus le nom de Pierre. Après la Résurrection, il est le porte-parole des apôtres : il prêche à la Pentecôte et il parlera au concile de Jérusalem.', '[{"text": "Pierre est le premier à prêcher devant la foule.", "translation": "Il passe de la peur au courage grâce à l''Esprit."}]'::jsonb, null, '{"id": "eg.d.c01_saint_pierre", "unitId": "eg.v.c01_saint_pierre", "word": "saint Pierre", "translation": "chef des apôtres, premier à prêcher le jour de la Pentecôte", "partOfSpeech": "person", "collection": "saint", "explanation": "Pêcheur de Galilée, Simon reçoit de Jésus le nom de Pierre. Après la Résurrection, il est le porte-parole des apôtres : il prêche à la Pentecôte et il parlera au concile de Jérusalem.", "examples": [{"text": "Pierre est le premier à prêcher devant la foule.", "translation": "Il passe de la peur au courage grâce à l''Esprit."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_helleniste', 'eg', 'les hellénistes', 'les chrétiens de langue grecque de la première communauté', 'Ce sont des Juifs de langue grecque, venus de pays étrangers, qui sont devenus chrétiens. Ils trouvent leurs veuves moins bien servies que les autres : c''est le premier conflit interne de l''Église (Actes 6).', '[{"text": "Les hellénistes se plaignent pour leurs veuves.", "translation": "Un problème de service, réglé en choisissant sept hommes."}]'::jsonb, null, '{"id": "eg.d.c01_helleniste", "unitId": "eg.v.c01_helleniste", "word": "les hellénistes", "translation": "les chrétiens de langue grecque de la première communauté", "partOfSpeech": "concept", "collection": "notion", "explanation": "Ce sont des Juifs de langue grecque, venus de pays étrangers, qui sont devenus chrétiens. Ils trouvent leurs veuves moins bien servies que les autres : c''est le premier conflit interne de l''Église (Actes 6).", "examples": [{"text": "Les hellénistes se plaignent pour leurs veuves.", "translation": "Un problème de service, réglé en choisissant sept hommes."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_saint_etienne', 'eg', 'saint Étienne', 'l''un des sept, lapidé vers 35 : le premier martyr', 'L''un des sept hommes choisis pour le service, plein de foi. Il témoigne du Christ devant les autorités juives et meurt lapidé. L''Église le fête comme le premier martyr.', '[{"text": "Étienne prie pour ceux qui le lapident.", "translation": "Il témoigne jusqu''au bout."}]'::jsonb, null, '{"id": "eg.d.c01_saint_etienne", "unitId": "eg.v.c01_saint_etienne", "word": "saint Étienne", "translation": "l''un des sept, lapidé vers 35 : le premier martyr", "partOfSpeech": "person", "collection": "saint", "explanation": "L''un des sept hommes choisis pour le service, plein de foi. Il témoigne du Christ devant les autorités juives et meurt lapidé. L''Église le fête comme le premier martyr.", "examples": [{"text": "Étienne prie pour ceux qui le lapident.", "translation": "Il témoigne jusqu''au bout."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_martyr', 'eg', 'le martyr', 'chrétien qui meurt pour témoigner de sa foi (du grec « témoin »)', 'Le martyr ne cherche pas la mort : il refuse de renier le Christ. Le mot vient du grec martys, « témoin ». L''Église copte vénère des milliers de martyrs, on y reviendra souvent.', '[{"text": "Étienne est le premier martyr chrétien.", "translation": "Le martyr est un témoin."}]'::jsonb, null, '{"id": "eg.d.c01_martyr", "unitId": "eg.v.c01_martyr", "word": "le martyr", "translation": "chrétien qui meurt pour témoigner de sa foi (du grec « témoin »)", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le martyr ne cherche pas la mort : il refuse de renier le Christ. Le mot vient du grec martys, « témoin ». L''Église copte vénère des milliers de martyrs, on y reviendra souvent.", "examples": [{"text": "Étienne est le premier martyr chrétien.", "translation": "Le martyr est un témoin."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_saint_paul', 'eg', 'saint Paul', 'pharisien devenu l''apôtre des nations, rencontré par le Christ vers 35', 'Juif de Tarse et citoyen romain, Saul persécute l''Église avant de rencontrer le Christ sur la route de Damas, vers 35. Devenu Paul, il fonde des communautés dans tout l''Empire et leur écrit des lettres.', '[{"text": "Paul est l''apôtre des nations.", "translation": "Un persécuteur devenu missionnaire."}]'::jsonb, null, '{"id": "eg.d.c01_saint_paul", "unitId": "eg.v.c01_saint_paul", "word": "saint Paul", "translation": "pharisien devenu l''apôtre des nations, rencontré par le Christ vers 35", "partOfSpeech": "person", "collection": "saint", "explanation": "Juif de Tarse et citoyen romain, Saul persécute l''Église avant de rencontrer le Christ sur la route de Damas, vers 35. Devenu Paul, il fonde des communautés dans tout l''Empire et leur écrit des lettres.", "examples": [{"text": "Paul est l''apôtre des nations.", "translation": "Un persécuteur devenu missionnaire."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_saint_barnabe', 'eg', 'saint Barnabé', 'celui qui accueille Paul et voyage avec lui', 'Juif de Chypre, il accueille Paul à Jérusalem après sa conversion. Il part avec lui en mission et il est le cousin de Marc, le futur fondateur de l''Église d''Alexandrie.', '[{"text": "Barnabé fait confiance à Paul quand les autres hésitent.", "translation": "Sans Barnabé, Paul aurait été seul."}]'::jsonb, null, '{"id": "eg.d.c01_saint_barnabe", "unitId": "eg.v.c01_saint_barnabe", "word": "saint Barnabé", "translation": "celui qui accueille Paul et voyage avec lui", "partOfSpeech": "person", "collection": "saint", "explanation": "Juif de Chypre, il accueille Paul à Jérusalem après sa conversion. Il part avec lui en mission et il est le cousin de Marc, le futur fondateur de l''Église d''Alexandrie.", "examples": [{"text": "Barnabé fait confiance à Paul quand les autres hésitent.", "translation": "Sans Barnabé, Paul aurait été seul."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_antioche', 'eg', 'Antioche', 'grande ville de Syrie où les disciples sont appelés « chrétiens »', 'Troisième ville de l''Empire, mélange de Juifs et de païens. Les disciples y sont appelés chrétiens pour la première fois, et c''est la base des voyages de Paul et Barnabé.', '[{"text": "À Antioche, on dit « chrétiens » pour la première fois.", "translation": "Une ville de Syrie, pas d''Égypte ni de Rome."}]'::jsonb, null, '{"id": "eg.d.c01_antioche", "unitId": "eg.v.c01_antioche", "word": "Antioche", "translation": "grande ville de Syrie où les disciples sont appelés « chrétiens »", "partOfSpeech": "place", "collection": "lieu", "explanation": "Troisième ville de l''Empire, mélange de Juifs et de païens. Les disciples y sont appelés chrétiens pour la première fois, et c''est la base des voyages de Paul et Barnabé.", "examples": [{"text": "À Antioche, on dit « chrétiens » pour la première fois.", "translation": "Une ville de Syrie, pas d''Égypte ni de Rome."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_chretiens', 'eg', 'les chrétiens', '« partisans du Christ » : le nom reçu à Antioche', 'Le mot vient du grec Christianoi, « partisans du Christ ». Ce nom a d''abord été donné aux disciples de l''extérieur, à Antioche, avant d''être adopté par eux.', '[{"text": "À Antioche, les disciples sont appelés chrétiens.", "translation": "Un nom d''abord donné de l''extérieur."}]'::jsonb, null, '{"id": "eg.d.c01_chretiens", "unitId": "eg.v.c01_chretiens", "word": "les chrétiens", "translation": "« partisans du Christ » : le nom reçu à Antioche", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le mot vient du grec Christianoi, « partisans du Christ ». Ce nom a d''abord été donné aux disciples de l''extérieur, à Antioche, avant d''être adopté par eux.", "examples": [{"text": "À Antioche, les disciples sont appelés chrétiens.", "translation": "Un nom d''abord donné de l''extérieur."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_circoncision', 'eg', 'la circoncision', 'le signe de l''alliance de Dieu avec Abraham, dans la Loi de Moïse', 'Pour les Juifs, c''est la marque d''appartenance au peuple de Dieu. Les chrétiens venus du paganisme n''en ont pas besoin : le concile de Jérusalem l''a décidé.', '[{"text": "Le concile décide que la circoncision n''est plus obligatoire.", "translation": "Un signe juif qu''on n''impose pas aux païens."}]'::jsonb, null, '{"id": "eg.d.c01_circoncision", "unitId": "eg.v.c01_circoncision", "word": "la circoncision", "translation": "le signe de l''alliance de Dieu avec Abraham, dans la Loi de Moïse", "partOfSpeech": "concept", "collection": "notion", "explanation": "Pour les Juifs, c''est la marque d''appartenance au peuple de Dieu. Les chrétiens venus du paganisme n''en ont pas besoin : le concile de Jérusalem l''a décidé.", "examples": [{"text": "Le concile décide que la circoncision n''est plus obligatoire.", "translation": "Un signe juif qu''on n''impose pas aux païens."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_judaisants', 'eg', 'les judaïsants', 'chrétiens d''origine juive qui veulent imposer la Loi de Moïse aux païens', 'Souvent d''anciens pharisiens, ils ont peur de perdre l''identité juive. Leur erreur : faire dépendre le salut de la Loi plutôt que du Christ. C''est l''une des deux grandes erreurs du premier siècle.', '[{"text": "Les judaïsants arrivent à Antioche et exigent la circoncision.", "translation": "Ils veulent que les païens deviennent juifs."}]'::jsonb, null, '{"id": "eg.d.c01_judaisants", "unitId": "eg.v.c01_judaisants", "word": "les judaïsants", "translation": "chrétiens d''origine juive qui veulent imposer la Loi de Moïse aux païens", "partOfSpeech": "concept", "collection": "heresie", "explanation": "Souvent d''anciens pharisiens, ils ont peur de perdre l''identité juive. Leur erreur : faire dépendre le salut de la Loi plutôt que du Christ. C''est l''une des deux grandes erreurs du premier siècle.", "examples": [{"text": "Les judaïsants arrivent à Antioche et exigent la circoncision.", "translation": "Ils veulent que les païens deviennent juifs."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_concile', 'eg', 'le concile', 'assemblée de responsables de l''Église qui décident ensemble', 'Du latin concilium, « assemblée ». Les responsables de l''Église se réunissent pour trancher une question de foi ou de discipline. Il y aura de grands conciles : Nicée, Constantinople, Éphèse.', '[{"text": "Un concile se réunit pour trancher une question.", "translation": "Tout un siècle de conciles commence ici."}]'::jsonb, null, '{"id": "eg.d.c01_concile", "unitId": "eg.v.c01_concile", "word": "le concile", "translation": "assemblée de responsables de l''Église qui décident ensemble", "partOfSpeech": "concept", "collection": "concile", "explanation": "Du latin concilium, « assemblée ». Les responsables de l''Église se réunissent pour trancher une question de foi ou de discipline. Il y aura de grands conciles : Nicée, Constantinople, Éphèse.", "examples": [{"text": "Un concile se réunit pour trancher une question.", "translation": "Tout un siècle de conciles commence ici."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_concile_de_jerusalem', 'eg', 'le concile de Jérusalem', 'le premier concile de l''histoire chrétienne, vers 49', 'Il se tient vers l''an 49 pour régler la dispute d''Antioche. Il décide que la circoncision n''est plus obligatoire pour les païens convertis. Sa méthode servira à tous les conciles suivants.', '[{"text": "Au concile de Jérusalem, Pierre, Paul et Jacques prennent la parole.", "translation": "Une dispute tranchée ensemble."}]'::jsonb, null, '{"id": "eg.d.c01_concile_de_jerusalem", "unitId": "eg.v.c01_concile_de_jerusalem", "word": "le concile de Jérusalem", "translation": "le premier concile de l''histoire chrétienne, vers 49", "partOfSpeech": "event", "collection": "concile", "explanation": "Il se tient vers l''an 49 pour régler la dispute d''Antioche. Il décide que la circoncision n''est plus obligatoire pour les païens convertis. Sa méthode servira à tous les conciles suivants.", "examples": [{"text": "Au concile de Jérusalem, Pierre, Paul et Jacques prennent la parole.", "translation": "Une dispute tranchée ensemble."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_jacques_de_zebedee', 'eg', 'Jacques, frère de Jean', 'apôtre décapité vers 44 : le premier des Douze martyr', 'Fils de Zébédée et frère de l''apôtre Jean, il est décapité sur ordre d''Hérode Agrippa. Il est le premier des Douze à mourir pour le Christ. Ne le confonds pas avec Jacques de Jérusalem.', '[{"text": "Jacques, frère de Jean, est décapité vers 44.", "translation": "Le premier apôtre martyr."}]'::jsonb, null, '{"id": "eg.d.c01_jacques_de_zebedee", "unitId": "eg.v.c01_jacques_de_zebedee", "word": "Jacques, frère de Jean", "translation": "apôtre décapité vers 44 : le premier des Douze martyr", "partOfSpeech": "person", "collection": "saint", "explanation": "Fils de Zébédée et frère de l''apôtre Jean, il est décapité sur ordre d''Hérode Agrippa. Il est le premier des Douze à mourir pour le Christ. Ne le confonds pas avec Jacques de Jérusalem.", "examples": [{"text": "Jacques, frère de Jean, est décapité vers 44.", "translation": "Le premier apôtre martyr."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_jacques_de_jerusalem', 'eg', 'saint Jacques de Jérusalem', 'chef de l''Église de Jérusalem, martyrisé en 62', 'Il dirige l''Église de Jérusalem et conclut le débat du concile. Il est martyrisé en 62. Il ne faut pas le confondre avec Jacques, frère de Jean, décapité vers 44.', '[{"text": "Jacques de Jérusalem conclut le concile.", "translation": "Le chef de l''Église de Jérusalem, mort en 62."}]'::jsonb, null, '{"id": "eg.d.c01_jacques_de_jerusalem", "unitId": "eg.v.c01_jacques_de_jerusalem", "word": "saint Jacques de Jérusalem", "translation": "chef de l''Église de Jérusalem, martyrisé en 62", "partOfSpeech": "person", "collection": "saint", "explanation": "Il dirige l''Église de Jérusalem et conclut le débat du concile. Il est martyrisé en 62. Il ne faut pas le confondre avec Jacques, frère de Jean, décapité vers 44.", "examples": [{"text": "Jacques de Jérusalem conclut le concile.", "translation": "Le chef de l''Église de Jérusalem, mort en 62."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_neron', 'eg', 'Néron', 'empereur romain qui accuse les chrétiens après l''incendie de Rome (64)', 'Empereur de 54 à 68, célèbre pour sa cruauté. Après l''incendie de Rome, il détourne les soupçons sur les chrétiens, qui sont arrêtés et torturés. C''est la première grande persécution romaine.', '[{"text": "Néron accuse les chrétiens de l''incendie de Rome.", "translation": "Un empereur qui cherche un coupable."}]'::jsonb, null, '{"id": "eg.d.c01_neron", "unitId": "eg.v.c01_neron", "word": "Néron", "translation": "empereur romain qui accuse les chrétiens après l''incendie de Rome (64)", "partOfSpeech": "person", "collection": "notion", "explanation": "Empereur de 54 à 68, célèbre pour sa cruauté. Après l''incendie de Rome, il détourne les soupçons sur les chrétiens, qui sont arrêtés et torturés. C''est la première grande persécution romaine.", "examples": [{"text": "Néron accuse les chrétiens de l''incendie de Rome.", "translation": "Un empereur qui cherche un coupable."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_empire_romain', 'eg', 'l''Empire romain', 'la puissance qui domine toute la Méditerranée au temps des apôtres', 'Au Ier siècle, Rome contrôle la Méditerranée, dont la Judée et l''Égypte. Ses routes et sa paix aident l''Évangile à voyager, mais ses empereurs persécutent parfois les chrétiens, qui refusent de les adorer.', '[{"text": "L''Empire romain exige qu''on honore l''empereur.", "translation": "Le décor de toute l''histoire."}]'::jsonb, null, '{"id": "eg.d.c01_empire_romain", "unitId": "eg.v.c01_empire_romain", "word": "l''Empire romain", "translation": "la puissance qui domine toute la Méditerranée au temps des apôtres", "partOfSpeech": "concept", "collection": "notion", "explanation": "Au Ier siècle, Rome contrôle la Méditerranée, dont la Judée et l''Égypte. Ses routes et sa paix aident l''Évangile à voyager, mais ses empereurs persécutent parfois les chrétiens, qui refusent de les adorer.", "examples": [{"text": "L''Empire romain exige qu''on honore l''empereur.", "translation": "Le décor de toute l''histoire."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_revolte_juive', 'eg', 'la révolte juive', 'le soulèvement des Juifs contre Rome, en 66', 'En 66, les Juifs de Judée se soulèvent contre l''occupant romain. La guerre dure quatre ans et finit par la destruction de Jérusalem.', '[{"text": "En 66, la révolte juive éclate.", "translation": "Quatre ans de guerre contre Rome."}]'::jsonb, null, '{"id": "eg.d.c01_revolte_juive", "unitId": "eg.v.c01_revolte_juive", "word": "la révolte juive", "translation": "le soulèvement des Juifs contre Rome, en 66", "partOfSpeech": "event", "collection": "date", "explanation": "En 66, les Juifs de Judée se soulèvent contre l''occupant romain. La guerre dure quatre ans et finit par la destruction de Jérusalem.", "examples": [{"text": "En 66, la révolte juive éclate.", "translation": "Quatre ans de guerre contre Rome."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_chute_de_jerusalem', 'eg', 'la chute de Jérusalem', 'la prise de la ville par Titus en 70, et la destruction du Temple', 'En 70, après un siège terrible, les légions de Titus prennent Jérusalem. Le Temple est détruit, les Juifs sont dispersés dans le monde, et les chrétiens de la ville se dispersent aussi.', '[{"text": "La chute de Jérusalem a lieu en 70.", "translation": "Un tournant pour les Juifs comme pour les chrétiens."}]'::jsonb, null, '{"id": "eg.d.c01_chute_de_jerusalem", "unitId": "eg.v.c01_chute_de_jerusalem", "word": "la chute de Jérusalem", "translation": "la prise de la ville par Titus en 70, et la destruction du Temple", "partOfSpeech": "event", "collection": "date", "explanation": "En 70, après un siège terrible, les légions de Titus prennent Jérusalem. Le Temple est détruit, les Juifs sont dispersés dans le monde, et les chrétiens de la ville se dispersent aussi.", "examples": [{"text": "La chute de Jérusalem a lieu en 70.", "translation": "Un tournant pour les Juifs comme pour les chrétiens."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_temple_de_jerusalem', 'eg', 'le Temple de Jérusalem', 'le grand sanctuaire juif, détruit en 70', 'Le centre du culte juif, où l''on offre des sacrifices. Jésus y enseigne, les premiers chrétiens y prient. Après 70, il n''en reste que des pierres.', '[{"text": "Le Temple est détruit en 70.", "translation": "Le cœur religieux de Jérusalem disparaît."}]'::jsonb, null, '{"id": "eg.d.c01_temple_de_jerusalem", "unitId": "eg.v.c01_temple_de_jerusalem", "word": "le Temple de Jérusalem", "translation": "le grand sanctuaire juif, détruit en 70", "partOfSpeech": "place", "collection": "lieu", "explanation": "Le centre du culte juif, où l''on offre des sacrifices. Jésus y enseigne, les premiers chrétiens y prient. Après 70, il n''en reste que des pierres.", "examples": [{"text": "Le Temple est détruit en 70.", "translation": "Le cœur religieux de Jérusalem disparaît."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_domitien', 'eg', 'Domitien', 'empereur romain (81-96), lié à une persécution des chrétiens', 'Il se fait appeler « seigneur et dieu ». Les chrétiens qui refusent de l''adorer sont inquiétés, surtout vers la fin de son règne. La tradition place alors l''exil de saint Jean à Patmos.', '[{"text": "Sous Domitien, saint Jean est exilé à Patmos.", "translation": "Une persécution de fin de siècle."}]'::jsonb, null, '{"id": "eg.d.c01_domitien", "unitId": "eg.v.c01_domitien", "word": "Domitien", "translation": "empereur romain (81-96), lié à une persécution des chrétiens", "partOfSpeech": "person", "collection": "notion", "explanation": "Il se fait appeler « seigneur et dieu ». Les chrétiens qui refusent de l''adorer sont inquiétés, surtout vers la fin de son règne. La tradition place alors l''exil de saint Jean à Patmos.", "examples": [{"text": "Sous Domitien, saint Jean est exilé à Patmos.", "translation": "Une persécution de fin de siècle."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_evangile', 'eg', 'l''Évangile', '« bonne nouvelle » : l''annonce du salut, et le livre qui raconte la vie de Jésus', 'Le mot grec euangelion veut dire « bonne nouvelle ». Il y a quatre évangiles : Matthieu, Marc, Luc et Jean. Avec les épîtres, ils forment le Nouveau Testament.', '[{"text": "Il y a quatre évangiles.", "translation": "Quatre récits d''une même bonne nouvelle."}]'::jsonb, null, '{"id": "eg.d.c01_evangile", "unitId": "eg.v.c01_evangile", "word": "l''Évangile", "translation": "« bonne nouvelle » : l''annonce du salut, et le livre qui raconte la vie de Jésus", "partOfSpeech": "work", "collection": "livre", "explanation": "Le mot grec euangelion veut dire « bonne nouvelle ». Il y a quatre évangiles : Matthieu, Marc, Luc et Jean. Avec les épîtres, ils forment le Nouveau Testament.", "examples": [{"text": "Il y a quatre évangiles.", "translation": "Quatre récits d''une même bonne nouvelle."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_heresie', 'eg', 'l''hérésie', 'un enseignement qui s''écarte de la foi reçue des apôtres', 'Le mot grec signifie « choix » : l''hérétique choisit une partie de la doctrine à sa façon. L''Église répond à une hérésie en précisant sa foi, souvent grâce à un concile.', '[{"text": "Face à une hérésie, l''Église précise sa foi.", "translation": "Chaque erreur fait grandir la clarté de la foi."}]'::jsonb, null, '{"id": "eg.d.c01_heresie", "unitId": "eg.v.c01_heresie", "word": "l''hérésie", "translation": "un enseignement qui s''écarte de la foi reçue des apôtres", "partOfSpeech": "concept", "collection": "heresie", "explanation": "Le mot grec signifie « choix » : l''hérétique choisit une partie de la doctrine à sa façon. L''Église répond à une hérésie en précisant sa foi, souvent grâce à un concile.", "examples": [{"text": "Face à une hérésie, l''Église précise sa foi.", "translation": "Chaque erreur fait grandir la clarté de la foi."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_gnosticisme', 'eg', 'le gnosticisme', 'courant qui prétend sauver par une connaissance secrète et méprise le corps', 'Du grec gnosis, « connaissance ». Il sépare le monde en deux : un Dieu bon, un mauvais dieu créateur. Le corps est une prison dont il faut s''échapper. La gnose reviendra au IIe siècle, notamment à Alexandrie.', '[{"text": "Les gnostiques croient sauver l''âme par une connaissance secrète.", "translation": "Une fausse connaissance."}]'::jsonb, null, '{"id": "eg.d.c01_gnosticisme", "unitId": "eg.v.c01_gnosticisme", "word": "le gnosticisme", "translation": "courant qui prétend sauver par une connaissance secrète et méprise le corps", "partOfSpeech": "concept", "collection": "heresie", "explanation": "Du grec gnosis, « connaissance ». Il sépare le monde en deux : un Dieu bon, un mauvais dieu créateur. Le corps est une prison dont il faut s''échapper. La gnose reviendra au IIe siècle, notamment à Alexandrie.", "examples": [{"text": "Les gnostiques croient sauver l''âme par une connaissance secrète.", "translation": "Une fausse connaissance."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_docetisme', 'eg', 'le docétisme', 'l''idée que Jésus n''aurait eu que l''apparence d''un corps', 'Du grec dokein, « paraître ». Si le corps est mauvais, Dieu ne peut pas s''incarner : Jésus ne serait qu''un fantôme. Cela supprime la croix et la Résurrection réelles. Saint Jean répond : « Le Verbe s''est fait chair ».', '[{"text": "Le docétisme dit que Jésus n''avait que l''apparence d''un corps.", "translation": "Un Jésus fantôme."}]'::jsonb, null, '{"id": "eg.d.c01_docetisme", "unitId": "eg.v.c01_docetisme", "word": "le docétisme", "translation": "l''idée que Jésus n''aurait eu que l''apparence d''un corps", "partOfSpeech": "concept", "collection": "heresie", "explanation": "Du grec dokein, « paraître ». Si le corps est mauvais, Dieu ne peut pas s''incarner : Jésus ne serait qu''un fantôme. Cela supprime la croix et la Résurrection réelles. Saint Jean répond : « Le Verbe s''est fait chair ».", "examples": [{"text": "Le docétisme dit que Jésus n''avait que l''apparence d''un corps.", "translation": "Un Jésus fantôme."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_saint_jean', 'eg', 'saint Jean', 'l''apôtre qui meurt vers l''an 100 : le dernier apôtre vivant', 'Frère de Jacques, il écrit l''évangile le plus théologique et lutte contre la gnose : « Le Verbe s''est fait chair ». Il vit à Éphèse et, selon la tradition, reçoit l''Apocalypse à Patmos. Il meurt vers l''an 100.', '[{"text": "Avec saint Jean se ferme l''âge des apôtres.", "translation": "Le dernier témoin direct de Jésus."}]'::jsonb, null, '{"id": "eg.d.c01_saint_jean", "unitId": "eg.v.c01_saint_jean", "word": "saint Jean", "translation": "l''apôtre qui meurt vers l''an 100 : le dernier apôtre vivant", "partOfSpeech": "person", "collection": "saint", "explanation": "Frère de Jacques, il écrit l''évangile le plus théologique et lutte contre la gnose : « Le Verbe s''est fait chair ». Il vit à Éphèse et, selon la tradition, reçoit l''Apocalypse à Patmos. Il meurt vers l''an 100.", "examples": [{"text": "Avec saint Jean se ferme l''âge des apôtres.", "translation": "Le dernier témoin direct de Jésus."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_saint_thomas', 'eg', 'saint Thomas', 'l''apôtre qui, selon la tradition, porte l''Évangile jusqu''en Inde', 'Celui qui a douté avant de dire « Mon Seigneur et mon Dieu ». Selon la tradition, il porte l''Évangile jusqu''en Inde, où des chrétiens l''honorent comme leur fondateur.', '[{"text": "Thomas porte l''Évangile jusqu''en Inde.", "translation": "Un apôtre qui va très loin."}]'::jsonb, null, '{"id": "eg.d.c01_saint_thomas", "unitId": "eg.v.c01_saint_thomas", "word": "saint Thomas", "translation": "l''apôtre qui, selon la tradition, porte l''Évangile jusqu''en Inde", "partOfSpeech": "person", "collection": "saint", "explanation": "Celui qui a douté avant de dire « Mon Seigneur et mon Dieu ». Selon la tradition, il porte l''Évangile jusqu''en Inde, où des chrétiens l''honorent comme leur fondateur.", "examples": [{"text": "Thomas porte l''Évangile jusqu''en Inde.", "translation": "Un apôtre qui va très loin."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_siege_apostolique', 'eg', 'le siège apostolique', 'une Église fondée par un apôtre ou un proche, dirigée par un évêque', 'Le « siège » est le fauteuil de l''évêque, symbole de son autorité d''enseignement. Jérusalem, Antioche, Rome, Éphèse et Alexandrie sont des sièges apostoliques du Ier siècle.', '[{"text": "Alexandrie est un siège apostolique.", "translation": "Une Église qui garde la foi des origines."}]'::jsonb, null, '{"id": "eg.d.c01_siege_apostolique", "unitId": "eg.v.c01_siege_apostolique", "word": "le siège apostolique", "translation": "une Église fondée par un apôtre ou un proche, dirigée par un évêque", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le « siège » est le fauteuil de l''évêque, symbole de son autorité d''enseignement. Jérusalem, Antioche, Rome, Éphèse et Alexandrie sont des sièges apostoliques du Ier siècle.", "examples": [{"text": "Alexandrie est un siège apostolique.", "translation": "Une Église qui garde la foi des origines."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_succession_apostolique', 'eg', 'la succession apostolique', 'la chaîne ininterrompue d''évêques qui remonte aux apôtres', 'Les apôtres ont transmis leur mission à des évêques par l''imposition des mains, et ceux-ci l''ont transmise à d''autres. L''Église copte y tient fermement.', '[{"text": "La succession apostolique relie chaque évêque aux apôtres.", "translation": "Une chaîne qui garantit la foi."}]'::jsonb, null, '{"id": "eg.d.c01_succession_apostolique", "unitId": "eg.v.c01_succession_apostolique", "word": "la succession apostolique", "translation": "la chaîne ininterrompue d''évêques qui remonte aux apôtres", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les apôtres ont transmis leur mission à des évêques par l''imposition des mains, et ceux-ci l''ont transmise à d''autres. L''Église copte y tient fermement.", "examples": [{"text": "La succession apostolique relie chaque évêque aux apôtres.", "translation": "Une chaîne qui garantit la foi."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_alexandrie', 'eg', 'Alexandrie', 'grand port grec d''Égypte, fondé par Alexandre le Grand', 'Grand port de la Méditerranée, ville de savants et de bibliothèques, elle compte au Ier siècle une forte communauté juive. C''est le berceau de l''Église copte.', '[{"text": "Marc arrive à Alexandrie.", "translation": "Une ville de mélange où l''Évangile trouve sa place."}]'::jsonb, null, '{"id": "eg.d.c01_alexandrie", "unitId": "eg.v.c01_alexandrie", "word": "Alexandrie", "translation": "grand port grec d''Égypte, fondé par Alexandre le Grand", "partOfSpeech": "place", "collection": "lieu", "explanation": "Grand port de la Méditerranée, ville de savants et de bibliothèques, elle compte au Ier siècle une forte communauté juive. C''est le berceau de l''Église copte.", "examples": [{"text": "Marc arrive à Alexandrie.", "translation": "Une ville de mélange où l''Évangile trouve sa place."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_septante', 'eg', 'la Septante', 'la traduction grecque de la Bible hébraïque, faite à Alexandrie', 'Commencée au IIIe siècle avant J.-C., elle permet aux Juifs de langue grecque de lire l''Écriture. Les premiers chrétiens la citent souvent.', '[{"text": "La Septante est la Bible en grec.", "translation": "Une Bible pour ceux qui parlent grec."}]'::jsonb, null, '{"id": "eg.d.c01_septante", "unitId": "eg.v.c01_septante", "word": "la Septante", "translation": "la traduction grecque de la Bible hébraïque, faite à Alexandrie", "partOfSpeech": "work", "collection": "livre", "explanation": "Commencée au IIIe siècle avant J.-C., elle permet aux Juifs de langue grecque de lire l''Écriture. Les premiers chrétiens la citent souvent.", "examples": [{"text": "La Septante est la Bible en grec.", "translation": "Une Bible pour ceux qui parlent grec."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_saint_marc', 'eg', 'saint Marc', 'évangéliste, fondateur de l''Église d''Alexandrie, martyr vers 68', 'Jean, surnommé Marc, est cousin de Barnabé et compagnon de Paul puis de Pierre. Il écrit le deuxième évangile. La tradition copte le tient pour le premier évêque d''Alexandrie : l''Église d''Égypte le vénère comme son fondateur.', '[{"text": "Saint Marc fonde l''Église d''Alexandrie.", "translation": "Le fondateur de ton Église."}]'::jsonb, null, '{"id": "eg.d.c01_saint_marc", "unitId": "eg.v.c01_saint_marc", "word": "saint Marc", "translation": "évangéliste, fondateur de l''Église d''Alexandrie, martyr vers 68", "partOfSpeech": "person", "collection": "saint", "explanation": "Jean, surnommé Marc, est cousin de Barnabé et compagnon de Paul puis de Pierre. Il écrit le deuxième évangile. La tradition copte le tient pour le premier évêque d''Alexandrie : l''Église d''Égypte le vénère comme son fondateur.", "examples": [{"text": "Saint Marc fonde l''Église d''Alexandrie.", "translation": "Le fondateur de ton Église."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_anianos', 'eg', 'Anianos', 'le cordonnier d''Alexandrie, premier converti de Marc', 'Appelé aussi Anianus, ou Hananiya en arabe. Guéri par Marc, il devient son premier converti, puis le deuxième évêque d''Alexandrie, après la mort du saint.', '[{"text": "Anianos accueille Marc chez lui.", "translation": "Un cordonnier devenu évêque."}]'::jsonb, null, '{"id": "eg.d.c01_anianos", "unitId": "eg.v.c01_anianos", "word": "Anianos", "translation": "le cordonnier d''Alexandrie, premier converti de Marc", "partOfSpeech": "person", "collection": "pape", "explanation": "Appelé aussi Anianus, ou Hananiya en arabe. Guéri par Marc, il devient son premier converti, puis le deuxième évêque d''Alexandrie, après la mort du saint.", "examples": [{"text": "Anianos accueille Marc chez lui.", "translation": "Un cordonnier devenu évêque."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_eglise_d_alexandrie', 'eg', 'l''Église d''Alexandrie', 'l''Église d''Égypte fondée par saint Marc, à l''origine de l''Église copte', 'Un des grands sièges apostoliques du monde chrétien. Elle sera le foyer d''une école de théologie célèbre et la mère de milliers de martyrs et de moines.', '[{"text": "Saint Marc est le premier pape de l''Église d''Alexandrie.", "translation": "Ton Église, à ses origines."}]'::jsonb, null, '{"id": "eg.d.c01_eglise_d_alexandrie", "unitId": "eg.v.c01_eglise_d_alexandrie", "word": "l''Église d''Alexandrie", "translation": "l''Église d''Égypte fondée par saint Marc, à l''origine de l''Église copte", "partOfSpeech": "organization", "collection": "eglise", "explanation": "Un des grands sièges apostoliques du monde chrétien. Elle sera le foyer d''une école de théologie célèbre et la mère de milliers de martyrs et de moines.", "examples": [{"text": "Saint Marc est le premier pape de l''Église d''Alexandrie.", "translation": "Ton Église, à ses origines."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_copte', 'eg', 'copte', '« égyptien » : du grec Aigyptios, le nom de l''Église d''Égypte', 'Le grec Aigyptios (égyptien) est devenu qibt en arabe, puis « copte ». Au début, il veut simplement dire égyptien ; il désigne ensuite les chrétiens d''Égypte.', '[{"text": "Être copte, c''est être de l''Église d''Égypte.", "translation": "Le mot vient du nom même de l''Égypte."}]'::jsonb, null, '{"id": "eg.d.c01_copte", "unitId": "eg.v.c01_copte", "word": "copte", "translation": "« égyptien » : du grec Aigyptios, le nom de l''Église d''Égypte", "partOfSpeech": "concept", "collection": "copte", "explanation": "Le grec Aigyptios (égyptien) est devenu qibt en arabe, puis « copte ». Au début, il veut simplement dire égyptien ; il désigne ensuite les chrétiens d''Égypte.", "examples": [{"text": "Être copte, c''est être de l''Église d''Égypte.", "translation": "Le mot vient du nom même de l''Égypte."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_reliques_de_saint_marc', 'eg', 'les reliques de saint Marc', 'le corps du saint, emporté à Venise en 828, en partie revenu au Caire en 1968', 'En 828, des marchands vénitiens emportent le corps du saint à Venise. En 1968, une partie des reliques est rendue à l''Église copte et revient au Caire.', '[{"text": "En 1968, les reliques reviennent au Caire.", "translation": "Un retour attendu depuis plus de mille ans."}]'::jsonb, null, '{"id": "eg.d.c01_reliques_de_saint_marc", "unitId": "eg.v.c01_reliques_de_saint_marc", "word": "les reliques de saint Marc", "translation": "le corps du saint, emporté à Venise en 828, en partie revenu au Caire en 1968", "partOfSpeech": "concept", "collection": "objet", "explanation": "En 828, des marchands vénitiens emportent le corps du saint à Venise. En 1968, une partie des reliques est rendue à l''Église copte et revient au Caire.", "examples": [{"text": "En 1968, les reliques reviennent au Caire.", "translation": "Un retour attendu depuis plus de mille ans."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c01_cathedrale_saint_marc', 'eg', 'la cathédrale Saint-Marc du Caire', 'la grande cathédrale copte de l''Abbassiya, consacrée en 1968', 'Siège du pape copte au Caire, elle a été consacrée en 1968, au moment du retour des reliques. C''est le centre de l''Église copte orthodoxe.', '[{"text": "Le pape copte siège à la cathédrale Saint-Marc.", "translation": "Le cœur de l''Église copte aujourd''hui."}]'::jsonb, null, '{"id": "eg.d.c01_cathedrale_saint_marc", "unitId": "eg.v.c01_cathedrale_saint_marc", "word": "la cathédrale Saint-Marc du Caire", "translation": "la grande cathédrale copte de l''Abbassiya, consacrée en 1968", "partOfSpeech": "place", "collection": "lieu", "explanation": "Siège du pape copte au Caire, elle a été consacrée en 1968, au moment du retour des reliques. C''est le centre de l''Église copte orthodoxe.", "examples": [{"text": "Le pape copte siège à la cathédrale Saint-Marc.", "translation": "Le cœur de l''Église copte aujourd''hui."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_depot', 'eg', 'le dépôt de la foi', 'la foi reçue des apôtres, confiée à l''Église pour qu''elle la garde', 'Comme un trésor confié à un gardien, la foi n''est pas à inventer mais à transmettre fidèlement. L''Église la garde intacte grâce aux Écritures, à la tradition et aux évêques.', '[{"text": "Les évêques sont les gardiens du dépôt de la foi.", "translation": "On ne l''invente pas, on le transmet."}]'::jsonb, null, '{"id": "eg.d.c02_depot", "unitId": "eg.v.c02_depot", "word": "le dépôt de la foi", "translation": "la foi reçue des apôtres, confiée à l''Église pour qu''elle la garde", "partOfSpeech": "concept", "collection": "notion", "explanation": "Comme un trésor confié à un gardien, la foi n''est pas à inventer mais à transmettre fidèlement. L''Église la garde intacte grâce aux Écritures, à la tradition et aux évêques.", "examples": [{"text": "Les évêques sont les gardiens du dépôt de la foi.", "translation": "On ne l''invente pas, on le transmet."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_tradition', 'eg', 'la sainte tradition', 'ce que les apôtres ont transmis de vive voix et par la vie de l''Église', 'La tradition n''est pas une simple habitude : c''est la foi vivante transmise par la prière, l''enseignement et les sacrements. Elle accompagne les Écritures et ne les contredit jamais.', '[{"text": "La façon de baptiser vient de la tradition des apôtres.", "translation": "Elle se transmet par l''Église entière."}]'::jsonb, null, '{"id": "eg.d.c02_tradition", "unitId": "eg.v.c02_tradition", "word": "la sainte tradition", "translation": "ce que les apôtres ont transmis de vive voix et par la vie de l''Église", "partOfSpeech": "concept", "collection": "notion", "explanation": "La tradition n''est pas une simple habitude : c''est la foi vivante transmise par la prière, l''enseignement et les sacrements. Elle accompagne les Écritures et ne les contredit jamais.", "examples": [{"text": "La façon de baptiser vient de la tradition des apôtres.", "translation": "Elle se transmet par l''Église entière."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_eveque', 'eg', 'un évêque', 'responsable d''une Église locale, successeur des apôtres', 'Du grec episkopos, « surveillant ». Il enseigne, ordonne les prêtres et garde l''unité de son diocèse. Il est le maillon vivant de la succession apostolique.', '[{"text": "L''évêque de Smyrne enseigne les chrétiens de sa ville.", "translation": "Il garde la foi reçue des apôtres."}]'::jsonb, null, '{"id": "eg.d.c02_eveque", "unitId": "eg.v.c02_eveque", "word": "un évêque", "translation": "responsable d''une Église locale, successeur des apôtres", "partOfSpeech": "person", "collection": "notion", "explanation": "Du grec episkopos, « surveillant ». Il enseigne, ordonne les prêtres et garde l''unité de son diocèse. Il est le maillon vivant de la succession apostolique.", "examples": [{"text": "L''évêque de Smyrne enseigne les chrétiens de sa ville.", "translation": "Il garde la foi reçue des apôtres."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_siege_alexandrie', 'eg', 'le siège d''Alexandrie', 'Église fondée par saint Marc : c''est l''Église copte', 'Le siège de saint Marc, l''évangéliste, en Égypte. C''est notre Église copte orthodoxe, dirigée par le pape d''Alexandrie. Alexandrie est aussi un grand centre intellectuel.', '[{"text": "Saint Marc a fondé le siège d''Alexandrie.", "translation": "C''est l''origine de l''Église copte."}]'::jsonb, null, '{"id": "eg.d.c02_siege_alexandrie", "unitId": "eg.v.c02_siege_alexandrie", "word": "le siège d''Alexandrie", "translation": "Église fondée par saint Marc : c''est l''Église copte", "partOfSpeech": "place", "collection": "lieu", "explanation": "Le siège de saint Marc, l''évangéliste, en Égypte. C''est notre Église copte orthodoxe, dirigée par le pape d''Alexandrie. Alexandrie est aussi un grand centre intellectuel.", "examples": [{"text": "Saint Marc a fondé le siège d''Alexandrie.", "translation": "C''est l''origine de l''Église copte."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_siege_rome', 'eg', 'le siège de Rome', 'Église fondée par les apôtres Pierre et Paul', 'Rome est la capitale de l''Empire. Pierre et Paul y sont morts martyrs au temps de Néron. Des chrétiens de tous les pays y passent, d''où le prestige de son évêque.', '[{"text": "Pierre et Paul ont fondé le siège de Rome.", "translation": "Deux apôtres, une Église."}]'::jsonb, null, '{"id": "eg.d.c02_siege_rome", "unitId": "eg.v.c02_siege_rome", "word": "le siège de Rome", "translation": "Église fondée par les apôtres Pierre et Paul", "partOfSpeech": "place", "collection": "lieu", "explanation": "Rome est la capitale de l''Empire. Pierre et Paul y sont morts martyrs au temps de Néron. Des chrétiens de tous les pays y passent, d''où le prestige de son évêque.", "examples": [{"text": "Pierre et Paul ont fondé le siège de Rome.", "translation": "Deux apôtres, une Église."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_siege_antioche', 'eg', 'le siège d''Antioche', 'Église de Syrie rattachée à l''apôtre Pierre', 'C''est à Antioche que les disciples sont appelés chrétiens pour la première fois. Ignace en sera un des premiers évêques.', '[{"text": "À Antioche, on a dit « chrétiens » pour la première fois.", "translation": "Le nom de notre foi vient de là."}]'::jsonb, null, '{"id": "eg.d.c02_siege_antioche", "unitId": "eg.v.c02_siege_antioche", "word": "le siège d''Antioche", "translation": "Église de Syrie rattachée à l''apôtre Pierre", "partOfSpeech": "place", "collection": "lieu", "explanation": "C''est à Antioche que les disciples sont appelés chrétiens pour la première fois. Ignace en sera un des premiers évêques.", "examples": [{"text": "À Antioche, on a dit « chrétiens » pour la première fois.", "translation": "Le nom de notre foi vient de là."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_siege_jerusalem', 'eg', 'le siège de Jérusalem', 'la première Église, née autour des apôtres, avec saint Jacques', 'Jérusalem est la mère des Églises. Saint Jacques en est le premier évêque. C''est là que les apôtres se réunissent, comme le raconte le chapitre 15 des Actes.', '[{"text": "Jacques dirige l''Église de Jérusalem.", "translation": "La première Église a son premier évêque."}]'::jsonb, null, '{"id": "eg.d.c02_siege_jerusalem", "unitId": "eg.v.c02_siege_jerusalem", "word": "le siège de Jérusalem", "translation": "la première Église, née autour des apôtres, avec saint Jacques", "partOfSpeech": "place", "collection": "lieu", "explanation": "Jérusalem est la mère des Églises. Saint Jacques en est le premier évêque. C''est là que les apôtres se réunissent, comme le raconte le chapitre 15 des Actes.", "examples": [{"text": "Jacques dirige l''Église de Jérusalem.", "translation": "La première Église a son premier évêque."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_peres_apostoliques', 'eg', 'les Pères apostoliques', 'premiers Pères de l''Église, proches des apôtres', 'On les appelle ainsi car ils ont reçu la tradition directement des apôtres ou de leurs disciples. Les trois grands noms sont Clément de Rome, Ignace d''Antioche et Polycarpe de Smyrne. Ils écrivent surtout des lettres à des chrétiens.', '[{"text": "Clément, Ignace et Polycarpe sont des Pères apostoliques.", "translation": "Ils font le pont entre les apôtres et l''Église."}]'::jsonb, null, '{"id": "eg.d.c02_peres_apostoliques", "unitId": "eg.v.c02_peres_apostoliques", "word": "les Pères apostoliques", "translation": "premiers Pères de l''Église, proches des apôtres", "partOfSpeech": "concept", "collection": "pere", "explanation": "On les appelle ainsi car ils ont reçu la tradition directement des apôtres ou de leurs disciples. Les trois grands noms sont Clément de Rome, Ignace d''Antioche et Polycarpe de Smyrne. Ils écrivent surtout des lettres à des chrétiens.", "examples": [{"text": "Clément, Ignace et Polycarpe sont des Pères apostoliques.", "translation": "Ils font le pont entre les apôtres et l''Église."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_clement', 'eg', 'Clément de Rome', 'évêque de Rome, auteur d''une lettre aux Corinthiens vers 96', 'Pour calmer les divisions de l''Église de Corinthe, il rappelle que les apôtres ont prévu la relève des évêques. Sa lettre montre que l''ordre dans l''Église n''est pas un hasard.', '[{"text": "Clément écrit aux Corinthiens divisés.", "translation": "Il rappelle l''ordre établi par les apôtres."}]'::jsonb, null, '{"id": "eg.d.c02_clement", "unitId": "eg.v.c02_clement", "word": "Clément de Rome", "translation": "évêque de Rome, auteur d''une lettre aux Corinthiens vers 96", "partOfSpeech": "person", "collection": "pere", "explanation": "Pour calmer les divisions de l''Église de Corinthe, il rappelle que les apôtres ont prévu la relève des évêques. Sa lettre montre que l''ordre dans l''Église n''est pas un hasard.", "examples": [{"text": "Clément écrit aux Corinthiens divisés.", "translation": "Il rappelle l''ordre établi par les apôtres."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_ignace', 'eg', 'Ignace d''Antioche', 'évêque d''Antioche, martyr à Rome vers 110', 'Arrêté sous Trajan, il écrit sept lettres en route vers Rome, où il est livré aux bêtes. Il insiste sur l''unité autour de l''évêque et sur le vrai corps du Christ.', '[{"text": "Ignace écrit sept lettres avant son martyre.", "translation": "Il parle de l''unité de l''Église."}]'::jsonb, null, '{"id": "eg.d.c02_ignace", "unitId": "eg.v.c02_ignace", "word": "Ignace d''Antioche", "translation": "évêque d''Antioche, martyr à Rome vers 110", "partOfSpeech": "person", "collection": "saint", "explanation": "Arrêté sous Trajan, il écrit sept lettres en route vers Rome, où il est livré aux bêtes. Il insiste sur l''unité autour de l''évêque et sur le vrai corps du Christ.", "examples": [{"text": "Ignace écrit sept lettres avant son martyre.", "translation": "Il parle de l''unité de l''Église."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_catholique', 'eg', '« catholique » au sens premier', 'du grec katholikos : « selon le tout », universel', 'Ignace est le premier à parler de l''Église catholique. Pour lui, cela veut dire l''Église entière, universelle, et non une Église locale. Nous le confessons dans le Credo.', '[{"text": "L''Église catholique d''Ignace, c''est l''Église universelle.", "translation": "Le mot ne désigne pas encore une Église particulière."}]'::jsonb, null, '{"id": "eg.d.c02_catholique", "unitId": "eg.v.c02_catholique", "word": "« catholique » au sens premier", "translation": "du grec katholikos : « selon le tout », universel", "partOfSpeech": "concept", "collection": "notion", "explanation": "Ignace est le premier à parler de l''Église catholique. Pour lui, cela veut dire l''Église entière, universelle, et non une Église locale. Nous le confessons dans le Credo.", "examples": [{"text": "L''Église catholique d''Ignace, c''est l''Église universelle.", "translation": "Le mot ne désigne pas encore une Église particulière."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_polycarpe', 'eg', 'Polycarpe de Smyrne', 'évêque de Smyrne, disciple de l''apôtre Jean, martyr', 'Disciple direct de Jean, il fait le lien entre l''apôtre et Irénée. Arrêté à Smyrne, il refuse de renier le Christ et meurt martyr vers le milieu du IIe siècle. Sa lettre aux Philippiens est conservée.', '[{"text": "Polycarpe répond au proconsul : « Voilà 86 ans que je le sers. »", "translation": "Il préfère mourir que renier son Roi."}]'::jsonb, null, '{"id": "eg.d.c02_polycarpe", "unitId": "eg.v.c02_polycarpe", "word": "Polycarpe de Smyrne", "translation": "évêque de Smyrne, disciple de l''apôtre Jean, martyr", "partOfSpeech": "person", "collection": "saint", "explanation": "Disciple direct de Jean, il fait le lien entre l''apôtre et Irénée. Arrêté à Smyrne, il refuse de renier le Christ et meurt martyr vers le milieu du IIe siècle. Sa lettre aux Philippiens est conservée.", "examples": [{"text": "Polycarpe répond au proconsul : « Voilà 86 ans que je le sers. »", "translation": "Il préfère mourir que renier son Roi."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_smyrne', 'eg', 'Smyrne', 'ville d''Asie Mineure (Izmir) dont Polycarpe est l''évêque', 'Smyrne est l''une des sept Églises de l''Apocalypse. Polycarpe y est évêque et y meurt martyr. Aujourd''hui, la ville s''appelle Izmir, en Turquie.', '[{"text": "Polycarpe est arrêté à Smyrne.", "translation": "Une grande ville d''Asie Mineure."}]'::jsonb, null, '{"id": "eg.d.c02_smyrne", "unitId": "eg.v.c02_smyrne", "word": "Smyrne", "translation": "ville d''Asie Mineure (Izmir) dont Polycarpe est l''évêque", "partOfSpeech": "place", "collection": "lieu", "explanation": "Smyrne est l''une des sept Églises de l''Apocalypse. Polycarpe y est évêque et y meurt martyr. Aujourd''hui, la ville s''appelle Izmir, en Turquie.", "examples": [{"text": "Polycarpe est arrêté à Smyrne.", "translation": "Une grande ville d''Asie Mineure."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_ichthys', 'eg', 'ICHTHYS (le poisson)', '« poisson » en grec : Jésus Christ, Fils de Dieu, Sauveur', 'Chaque lettre du mot grec est l''initiale d''un mot : Jésus, Christ, de Dieu, Fils, Sauveur. Le poisson devient un signe de reconnaissance entre chrétiens persécutés, tracé d''un trait sur un mur ou dans le sable.', '[{"text": "Un chrétien trace une courbe, l''autre dessine le poisson.", "translation": "Un signe secret qui dit toute la foi."}]'::jsonb, null, '{"id": "eg.d.c02_ichthys", "unitId": "eg.v.c02_ichthys", "word": "ICHTHYS (le poisson)", "translation": "« poisson » en grec : Jésus Christ, Fils de Dieu, Sauveur", "partOfSpeech": "concept", "collection": "objet", "explanation": "Chaque lettre du mot grec est l''initiale d''un mot : Jésus, Christ, de Dieu, Fils, Sauveur. Le poisson devient un signe de reconnaissance entre chrétiens persécutés, tracé d''un trait sur un mur ou dans le sable.", "examples": [{"text": "Un chrétien trace une courbe, l''autre dessine le poisson.", "translation": "Un signe secret qui dit toute la foi."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_culte_empereur', 'eg', 'le culte de l''empereur', 'rite public où l''on offre de l''encens à l''empereur', 'Les citoyens offrent de l''encens devant l''empereur. Les chrétiens refusent : ils prient pour lui sans l''adorer. On les accuse alors d''être de mauvais citoyens.', '[{"text": "Refuser le culte de l''empereur, c''est risquer sa vie.", "translation": "C''est la cause profonde des persécutions."}]'::jsonb, null, '{"id": "eg.d.c02_culte_empereur", "unitId": "eg.v.c02_culte_empereur", "word": "le culte de l''empereur", "translation": "rite public où l''on offre de l''encens à l''empereur", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les citoyens offrent de l''encens devant l''empereur. Les chrétiens refusent : ils prient pour lui sans l''adorer. On les accuse alors d''être de mauvais citoyens.", "examples": [{"text": "Refuser le culte de l''empereur, c''est risquer sa vie.", "translation": "C''est la cause profonde des persécutions."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_persecution', 'eg', 'une persécution', 'période où l''Empire punit les chrétiens qui refusent le culte', 'L''Empire punit ceux qui refusent le culte de l''empereur. Selon la tradition, on compte dix grandes persécutions : Trajan est la troisième, Marc Aurèle la quatrième et Septime Sévère la cinquième.', '[{"text": "Sous Marc Aurèle, une persécution frappe Lyon.", "translation": "Les martyrs sont nombreux."}]'::jsonb, null, '{"id": "eg.d.c02_persecution", "unitId": "eg.v.c02_persecution", "word": "une persécution", "translation": "période où l''Empire punit les chrétiens qui refusent le culte", "partOfSpeech": "concept", "collection": "notion", "explanation": "L''Empire punit ceux qui refusent le culte de l''empereur. Selon la tradition, on compte dix grandes persécutions : Trajan est la troisième, Marc Aurèle la quatrième et Septime Sévère la cinquième.", "examples": [{"text": "Sous Marc Aurèle, une persécution frappe Lyon.", "translation": "Les martyrs sont nombreux."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_blandine', 'eg', 'Blandine', 'jeune esclave, martyre de Lyon en 177', 'Blandine est une jeune esclave de Lyon. En 177, elle résiste jusqu''au bout et meurt martyre avec l''évêque Pothin. Son courage marque les chrétiens, comme le raconte Eusèbe.', '[{"text": "Blandine résiste jusqu''au bout.", "translation": "Une esclave devenue modèle de courage."}]'::jsonb, null, '{"id": "eg.d.c02_blandine", "unitId": "eg.v.c02_blandine", "word": "Blandine", "translation": "jeune esclave, martyre de Lyon en 177", "partOfSpeech": "person", "collection": "saint", "explanation": "Blandine est une jeune esclave de Lyon. En 177, elle résiste jusqu''au bout et meurt martyre avec l''évêque Pothin. Son courage marque les chrétiens, comme le raconte Eusèbe.", "examples": [{"text": "Blandine résiste jusqu''au bout.", "translation": "Une esclave devenue modèle de courage."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_justin', 'eg', 'Justin Martyr', 'philosophe converti, apologiste, martyr à Rome vers 165', 'Né à Naplouse, philosophe, il devient chrétien vers 130. Il écrit les Apologies à l''empereur et le Dialogue avec Tryphon. Il est martyrisé à Rome, d''où son surnom.', '[{"text": "Justin écrit à l''empereur pour défendre les chrétiens.", "translation": "Il montre que la foi est raisonnable."}]'::jsonb, null, '{"id": "eg.d.c02_justin", "unitId": "eg.v.c02_justin", "word": "Justin Martyr", "translation": "philosophe converti, apologiste, martyr à Rome vers 165", "partOfSpeech": "person", "collection": "pere", "explanation": "Né à Naplouse, philosophe, il devient chrétien vers 130. Il écrit les Apologies à l''empereur et le Dialogue avec Tryphon. Il est martyrisé à Rome, d''où son surnom.", "examples": [{"text": "Justin écrit à l''empereur pour défendre les chrétiens.", "translation": "Il montre que la foi est raisonnable."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_apologiste', 'eg', 'un apologiste', 'écrivain chrétien qui défend la foi devant le monde païen', 'Du grec apologia, « défense ». Il s''adresse aux empereurs, aux magistrats, aux philosophes pour répondre aux accusations. Justin et Tertullien sont les plus célèbres.', '[{"text": "Un apologiste écrit pour ceux qui sont hors de l''Église.", "translation": "Il défend la foi, il n''attaque pas."}]'::jsonb, null, '{"id": "eg.d.c02_apologiste", "unitId": "eg.v.c02_apologiste", "word": "un apologiste", "translation": "écrivain chrétien qui défend la foi devant le monde païen", "partOfSpeech": "concept", "collection": "notion", "explanation": "Du grec apologia, « défense ». Il s''adresse aux empereurs, aux magistrats, aux philosophes pour répondre aux accusations. Justin et Tertullien sont les plus célèbres.", "examples": [{"text": "Un apologiste écrit pour ceux qui sont hors de l''Église.", "translation": "Il défend la foi, il n''attaque pas."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_tertullien', 'eg', 'Tertullien', 'juriste de Carthage, auteur de l''Apologétique en 197', 'Premier grand écrivain chrétien de langue latine. Dans l''Apologétique, il défend les chrétiens devant les magistrats. Il écrit aussi Contre Marcion, mais il finira par rejoindre le montanisme.', '[{"text": "Tertullien écrit : « Le sang des martyrs est une semence de chrétiens. »", "translation": "Un avocat au service de la foi."}]'::jsonb, null, '{"id": "eg.d.c02_tertullien", "unitId": "eg.v.c02_tertullien", "word": "Tertullien", "translation": "juriste de Carthage, auteur de l''Apologétique en 197", "partOfSpeech": "person", "collection": "pere", "explanation": "Premier grand écrivain chrétien de langue latine. Dans l''Apologétique, il défend les chrétiens devant les magistrats. Il écrit aussi Contre Marcion, mais il finira par rejoindre le montanisme.", "examples": [{"text": "Tertullien écrit : « Le sang des martyrs est une semence de chrétiens. »", "translation": "Un avocat au service de la foi."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_semences', 'eg', 'les semences du Verbe', 'parts de vérité que Justin voit chez les philosophes', 'Le Verbe (Logos) éclaire tout homme. Les philosophes ont donc entrevu des parts de vérité, comme des graines semées par le Verbe. Seul le christianisme possède la vérité entière.', '[{"text": "Platon a trouvé une semence du Verbe, dirait Justin.", "translation": "La vérité existe déjà en partie hors de l''Église."}]'::jsonb, null, '{"id": "eg.d.c02_semences", "unitId": "eg.v.c02_semences", "word": "les semences du Verbe", "translation": "parts de vérité que Justin voit chez les philosophes", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le Verbe (Logos) éclaire tout homme. Les philosophes ont donc entrevu des parts de vérité, comme des graines semées par le Verbe. Seul le christianisme possède la vérité entière.", "examples": [{"text": "Platon a trouvé une semence du Verbe, dirait Justin.", "translation": "La vérité existe déjà en partie hors de l''Église."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_gnose', 'eg', 'la gnose', 'du grec gnosis : « connaissance » secrète réservée aux initiés', 'Pour les gnostiques, la connaissance libère l''âme de la matière et sauve une élite. Pour l''Église, c''est la foi qui sauve, et le salut est offert à tous. Valentin et Basilide enseignent à Alexandrie.', '[{"text": "La gnose promet un savoir secret.", "translation": "L''Église répond : la foi sauve tous les baptisés."}]'::jsonb, null, '{"id": "eg.d.c02_gnose", "unitId": "eg.v.c02_gnose", "word": "la gnose", "translation": "du grec gnosis : « connaissance » secrète réservée aux initiés", "partOfSpeech": "concept", "collection": "heresie", "explanation": "Pour les gnostiques, la connaissance libère l''âme de la matière et sauve une élite. Pour l''Église, c''est la foi qui sauve, et le salut est offert à tous. Valentin et Basilide enseignent à Alexandrie.", "examples": [{"text": "La gnose promet un savoir secret.", "translation": "L''Église répond : la foi sauve tous les baptisés."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_irenee', 'eg', 'Irénée de Lyon', 'évêque de Lyon, disciple de Polycarpe, auteur de Contre les hérésies', 'Il relie Jean à Lyon par Polycarpe. Vers 180, il réfute les gnostiques en opposant l''enseignement public des évêques, reçu des apôtres, à leurs doctrines secrètes.', '[{"text": "Irénée répond aux gnostiques dans Contre les hérésies.", "translation": "Il défend la succession apostolique."}]'::jsonb, null, '{"id": "eg.d.c02_irenee", "unitId": "eg.v.c02_irenee", "word": "Irénée de Lyon", "translation": "évêque de Lyon, disciple de Polycarpe, auteur de Contre les hérésies", "partOfSpeech": "person", "collection": "pere", "explanation": "Il relie Jean à Lyon par Polycarpe. Vers 180, il réfute les gnostiques en opposant l''enseignement public des évêques, reçu des apôtres, à leurs doctrines secrètes.", "examples": [{"text": "Irénée répond aux gnostiques dans Contre les hérésies.", "translation": "Il défend la succession apostolique."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_nag_hammadi', 'eg', 'Nag Hammadi', 'lieu d''Égypte où l''on a retrouvé des textes gnostiques en copte', 'En 1945, en Haute-Égypte, on a découvert à Nag Hammadi une bibliothèque de textes gnostiques en copte, enterrés dans des jarres. Elle permet de lire les gnostiques directement.', '[{"text": "Les jarres de Nag Hammadi contenaient des livres en copte.", "translation": "Un trésor découvert en 1945."}]'::jsonb, null, '{"id": "eg.d.c02_nag_hammadi", "unitId": "eg.v.c02_nag_hammadi", "word": "Nag Hammadi", "translation": "lieu d''Égypte où l''on a retrouvé des textes gnostiques en copte", "partOfSpeech": "place", "collection": "lieu", "explanation": "En 1945, en Haute-Égypte, on a découvert à Nag Hammadi une bibliothèque de textes gnostiques en copte, enterrés dans des jarres. Elle permet de lire les gnostiques directement.", "examples": [{"text": "Les jarres de Nag Hammadi contenaient des livres en copte.", "translation": "Un trésor découvert en 1945."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_marcion', 'eg', 'Marcion', 'armateur de Sinope, exclu de l''Église de Rome vers 144', 'Il rejette l''Ancien Testament et ne garde que Luc et dix lettres de Paul. Il croit que le Dieu créateur n''est pas le Père de Jésus. Polycarpe et Tertullien le combattent.', '[{"text": "Marcion croit à deux dieux.", "translation": "L''Église lui répond : un seul Dieu, deux Testaments."}]'::jsonb, null, '{"id": "eg.d.c02_marcion", "unitId": "eg.v.c02_marcion", "word": "Marcion", "translation": "armateur de Sinope, exclu de l''Église de Rome vers 144", "partOfSpeech": "person", "collection": "heresie", "explanation": "Il rejette l''Ancien Testament et ne garde que Luc et dix lettres de Paul. Il croit que le Dieu créateur n''est pas le Père de Jésus. Polycarpe et Tertullien le combattent.", "examples": [{"text": "Marcion croit à deux dieux.", "translation": "L''Église lui répond : un seul Dieu, deux Testaments."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_contre_marcion', 'eg', 'Contre Marcion', 'livre de Tertullien qui réfute Marcion', 'Tertullien y défend l''unité de Dieu et des deux Testaments contre Marcion. C''est l''un des grands écrits du IIe siècle contre une hérésie.', '[{"text": "Tertullien écrit Contre Marcion.", "translation": "Un livre pour défendre l''Ancien Testament."}]'::jsonb, null, '{"id": "eg.d.c02_contre_marcion", "unitId": "eg.v.c02_contre_marcion", "word": "Contre Marcion", "translation": "livre de Tertullien qui réfute Marcion", "partOfSpeech": "work", "collection": "livre", "explanation": "Tertullien y défend l''unité de Dieu et des deux Testaments contre Marcion. C''est l''un des grands écrits du IIe siècle contre une hérésie.", "examples": [{"text": "Tertullien écrit Contre Marcion.", "translation": "Un livre pour défendre l''Ancien Testament."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_ancien_testament', 'eg', 'l''Ancien Testament', 'les livres saints d''avant la venue du Christ', 'Les Écritures reçues d''Israël, que Jésus cite et accomplit. Marcion voulait les jeter ; l''Église les garde, car le même Dieu parle dans les deux Testaments.', '[{"text": "Jésus cite l''Ancien Testament.", "translation": "Le Christ l''accomplit, il ne le supprime pas."}]'::jsonb, null, '{"id": "eg.d.c02_ancien_testament", "unitId": "eg.v.c02_ancien_testament", "word": "l''Ancien Testament", "translation": "les livres saints d''avant la venue du Christ", "partOfSpeech": "work", "collection": "livre", "explanation": "Les Écritures reçues d''Israël, que Jésus cite et accomplit. Marcion voulait les jeter ; l''Église les garde, car le même Dieu parle dans les deux Testaments.", "examples": [{"text": "Jésus cite l''Ancien Testament.", "translation": "Le Christ l''accomplit, il ne le supprime pas."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_montanus', 'eg', 'Montanus', 'prophète de Phrygie qui annonce un nouvel âge de l''Esprit vers 170', 'Il se dit l''organe du Paraclet et annonce la fin des temps imminente. Il exige continence parfaite et recherche du martyre. L''Église condamne son mouvement, qui finit par disparaître.', '[{"text": "Montanus prophétise en transe en Phrygie.", "translation": "L''Église refuse sa « nouvelle prophétie »."}]'::jsonb, null, '{"id": "eg.d.c02_montanus", "unitId": "eg.v.c02_montanus", "word": "Montanus", "translation": "prophète de Phrygie qui annonce un nouvel âge de l''Esprit vers 170", "partOfSpeech": "person", "collection": "heresie", "explanation": "Il se dit l''organe du Paraclet et annonce la fin des temps imminente. Il exige continence parfaite et recherche du martyre. L''Église condamne son mouvement, qui finit par disparaître.", "examples": [{"text": "Montanus prophétise en transe en Phrygie.", "translation": "L''Église refuse sa « nouvelle prophétie »."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_paraclet', 'eg', 'le Paraclet', 'titre de l''Esprit Saint promis par Jésus (Jean 14, 26)', 'Du grec paraklêtos, « consolateur, défenseur ». Jésus annonce l''envoi du Paraclet. Montanus prétend être son porte-parole, ce que l''Église refuse.', '[{"text": "Jésus promet l''envoi du Paraclet.", "translation": "C''est un nom de l''Esprit Saint."}]'::jsonb, null, '{"id": "eg.d.c02_paraclet", "unitId": "eg.v.c02_paraclet", "word": "le Paraclet", "translation": "titre de l''Esprit Saint promis par Jésus (Jean 14, 26)", "partOfSpeech": "concept", "collection": "notion", "explanation": "Du grec paraklêtos, « consolateur, défenseur ». Jésus annonce l''envoi du Paraclet. Montanus prétend être son porte-parole, ce que l''Église refuse.", "examples": [{"text": "Jésus promet l''envoi du Paraclet.", "translation": "C''est un nom de l''Esprit Saint."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_priscilla', 'eg', 'Priscilla et Maximilla', 'les deux prophétesses qui suivent Montanus', 'Elles prophétisent en transe, comme Montanus. L''Église ne reconnaît pas leurs oracles : la Révélation est déjà complète.', '[{"text": "Priscilla et Maximilla accompagnent Montanus.", "translation": "Leur « nouvelle prophétie » est refusée."}]'::jsonb, null, '{"id": "eg.d.c02_priscilla", "unitId": "eg.v.c02_priscilla", "word": "Priscilla et Maximilla", "translation": "les deux prophétesses qui suivent Montanus", "partOfSpeech": "person", "collection": "heresie", "explanation": "Elles prophétisent en transe, comme Montanus. L''Église ne reconnaît pas leurs oracles : la Révélation est déjà complète.", "examples": [{"text": "Priscilla et Maximilla accompagnent Montanus.", "translation": "Leur « nouvelle prophétie » est refusée."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_canon', 'eg', 'le canon des Écritures', 'du grec kanôn, « règle » : la liste des livres reconnus par l''Église', 'Marcion a poussé l''Église à préciser sa liste. Trois critères guident : l''origine apostolique, l''accord avec la foi et l''usage constant dans les Églises. En 367, Athanase donne la liste des 27 livres du Nouveau Testament.', '[{"text": "Le canon dit quels livres sont des Écritures.", "translation": "Une règle pour mesurer les livres."}]'::jsonb, null, '{"id": "eg.d.c02_canon", "unitId": "eg.v.c02_canon", "word": "le canon des Écritures", "translation": "du grec kanôn, « règle » : la liste des livres reconnus par l''Église", "partOfSpeech": "concept", "collection": "livre", "explanation": "Marcion a poussé l''Église à préciser sa liste. Trois critères guident : l''origine apostolique, l''accord avec la foi et l''usage constant dans les Églises. En 367, Athanase donne la liste des 27 livres du Nouveau Testament.", "examples": [{"text": "Le canon dit quels livres sont des Écritures.", "translation": "Une règle pour mesurer les livres."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_regle_foi', 'eg', 'la règle de foi', 'résumé de la foi du baptême, racine du Credo', 'Un seul Dieu, le Christ vraiment homme, mort et ressuscité, l''Esprit Saint. Elle donne la clé de lecture des Écritures, comme le plan du roi pour la mosaïque d''Irénée.', '[{"text": "La règle de foi précède le Credo.", "translation": "On lit la Bible dans la foi de l''Église."}]'::jsonb, null, '{"id": "eg.d.c02_regle_foi", "unitId": "eg.v.c02_regle_foi", "word": "la règle de foi", "translation": "résumé de la foi du baptême, racine du Credo", "partOfSpeech": "concept", "collection": "notion", "explanation": "Un seul Dieu, le Christ vraiment homme, mort et ressuscité, l''Esprit Saint. Elle donne la clé de lecture des Écritures, comme le plan du roi pour la mosaïque d''Irénée.", "examples": [{"text": "La règle de foi précède le Credo.", "translation": "On lit la Bible dans la foi de l''Église."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_muratori', 'eg', 'le Fragment de Muratori', 'ancienne liste romaine de livres du Nouveau Testament', 'Une liste écrite à Rome entre 170 et 200. Elle montre que, dès le IIe siècle, les Évangiles et les lettres de Paul sont reçus par l''Église.', '[{"text": "Le Fragment de Muratori date du IIe siècle.", "translation": "L''un des plus anciens catalogues du Nouveau Testament."}]'::jsonb, null, '{"id": "eg.d.c02_muratori", "unitId": "eg.v.c02_muratori", "word": "le Fragment de Muratori", "translation": "ancienne liste romaine de livres du Nouveau Testament", "partOfSpeech": "work", "collection": "livre", "explanation": "Une liste écrite à Rome entre 170 et 200. Elle montre que, dès le IIe siècle, les Évangiles et les lettres de Paul sont reçus par l''Église.", "examples": [{"text": "Le Fragment de Muratori date du IIe siècle.", "translation": "L''un des plus anciens catalogues du Nouveau Testament."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_demetrios', 'eg', 'saint Démétrios', 'XIIe pape d''Alexandrie, élu en 189, surnommé le vigneron', 'Selon la tradition, un paysan sans instruction à qui Dieu donne d''apprendre à lire. Il organise le calendrier des fêtes, place le carême avant la semaine sainte et soutient l''école d''Alexandrie.', '[{"text": "Démétrios est élu après le signe de la grappe de raisin.", "translation": "Un homme simple choisi par Dieu."}]'::jsonb, null, '{"id": "eg.d.c02_demetrios", "unitId": "eg.v.c02_demetrios", "word": "saint Démétrios", "translation": "XIIe pape d''Alexandrie, élu en 189, surnommé le vigneron", "partOfSpeech": "person", "collection": "pape", "explanation": "Selon la tradition, un paysan sans instruction à qui Dieu donne d''apprendre à lire. Il organise le calendrier des fêtes, place le carême avant la semaine sainte et soutient l''école d''Alexandrie.", "examples": [{"text": "Démétrios est élu après le signe de la grappe de raisin.", "translation": "Un homme simple choisi par Dieu."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_pape_alexandrie', 'eg', 'le pape d''Alexandrie', 'titre de l''évêque d''Alexandrie, chef de l''Église copte', 'Chez les Coptes, l''évêque d''Alexandrie porte le titre de pape, « père », depuis l''Antiquité. Il est le successeur de saint Marc. Démétrios en est le XIIe.', '[{"text": "Le pape d''Alexandrie dirige l''Église copte.", "translation": "Il est le successeur de saint Marc."}]'::jsonb, null, '{"id": "eg.d.c02_pape_alexandrie", "unitId": "eg.v.c02_pape_alexandrie", "word": "le pape d''Alexandrie", "translation": "titre de l''évêque d''Alexandrie, chef de l''Église copte", "partOfSpeech": "concept", "collection": "pape", "explanation": "Chez les Coptes, l''évêque d''Alexandrie porte le titre de pape, « père », depuis l''Antiquité. Il est le successeur de saint Marc. Démétrios en est le XIIe.", "examples": [{"text": "Le pape d''Alexandrie dirige l''Église copte.", "translation": "Il est le successeur de saint Marc."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_date_paques', 'eg', 'la date de Pâques', 'débat du IIe siècle : le 14 Nisan ou le dimanche suivant', 'Certaines Églises, en Asie Mineure, fêtent Pâques le 14 Nisan. Rome et Alexandrie préfèrent le dimanche suivant. Polycarpe en discute à Rome vers 155. Alexandrie fixe des règles de calcul.', '[{"text": "On se dispute sur la date de Pâques dès le IIe siècle.", "translation": "Deux usages, mais la même foi."}]'::jsonb, null, '{"id": "eg.d.c02_date_paques", "unitId": "eg.v.c02_date_paques", "word": "la date de Pâques", "translation": "débat du IIe siècle : le 14 Nisan ou le dimanche suivant", "partOfSpeech": "event", "collection": "date", "explanation": "Certaines Églises, en Asie Mineure, fêtent Pâques le 14 Nisan. Rome et Alexandrie préfèrent le dimanche suivant. Polycarpe en discute à Rome vers 155. Alexandrie fixe des règles de calcul.", "examples": [{"text": "On se dispute sur la date de Pâques dès le IIe siècle.", "translation": "Deux usages, mais la même foi."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c02_epacte', 'eg', 'l''épacte', 'calcul lunaire d''Alexandrie pour dater Pâques', 'Alexandrie, ville d''astronomes, perfectionne ce calcul lunaire que Démétrios promeut. Il sert à fixer Pâques et le carême.', '[{"text": "Démétrios promeut l''épacte.", "translation": "Un calcul pour savoir quand fêter Pâques."}]'::jsonb, null, '{"id": "eg.d.c02_epacte", "unitId": "eg.v.c02_epacte", "word": "l''épacte", "translation": "calcul lunaire d''Alexandrie pour dater Pâques", "partOfSpeech": "concept", "collection": "notion", "explanation": "Alexandrie, ville d''astronomes, perfectionne ce calcul lunaire que Démétrios promeut. Il sert à fixer Pâques et le carême.", "examples": [{"text": "Démétrios promeut l''épacte.", "translation": "Un calcul pour savoir quand fêter Pâques."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_sacrifice_public', 'eg', 'le sacrifice public', 'offrande aux dieux et à l''empereur, preuve de loyauté à Rome', 'À Rome, offrir un sacrifice devant tous prouve qu''on est loyal. Les chrétiens n''adorent que Dieu : refuser, c''est risquer la prison, l''exil ou la mort.', '[{"text": "Il refuse le sacrifice public, donc on se méfie de lui.", "translation": "Le geste de loyauté que les chrétiens ne font pas."}]'::jsonb, null, '{"id": "eg.d.c03_sacrifice_public", "unitId": "eg.v.c03_sacrifice_public", "word": "le sacrifice public", "translation": "offrande aux dieux et à l''empereur, preuve de loyauté à Rome", "partOfSpeech": "concept", "collection": "notion", "explanation": "À Rome, offrir un sacrifice devant tous prouve qu''on est loyal. Les chrétiens n''adorent que Dieu : refuser, c''est risquer la prison, l''exil ou la mort.", "examples": [{"text": "Il refuse le sacrifice public, donc on se méfie de lui.", "translation": "Le geste de loyauté que les chrétiens ne font pas."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_mauvais_citoyens', 'eg', 'les mauvais citoyens', 'aux yeux de Rome, ceux qui refusent le culte de la cité', 'Pour l''Empire, religion et politique vont ensemble. Celui qui ne participe pas au culte passe pour déloyal, même s''il veut seulement rester fidèle à son Dieu.', '[{"text": "Les voisins prennent les chrétiens pour de mauvais citoyens.", "translation": "Un reproche injuste : ils sont fidèles à Dieu, pas rebelles."}]'::jsonb, null, '{"id": "eg.d.c03_mauvais_citoyens", "unitId": "eg.v.c03_mauvais_citoyens", "word": "les mauvais citoyens", "translation": "aux yeux de Rome, ceux qui refusent le culte de la cité", "partOfSpeech": "concept", "collection": "notion", "explanation": "Pour l''Empire, religion et politique vont ensemble. Celui qui ne participe pas au culte passe pour déloyal, même s''il veut seulement rester fidèle à son Dieu.", "examples": [{"text": "Les voisins prennent les chrétiens pour de mauvais citoyens.", "translation": "Un reproche injuste : ils sont fidèles à Dieu, pas rebelles."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_anthropophagie', 'eg', 'l''anthropophagie', 'accusation fausse : manger de la chair humaine', 'Une rumeur sans aucun fondement contre les chrétiens, avec celle du meurtre rituel. Elle vient sans doute de paroles mal comprises sur le corps et le sang du Christ.', '[{"text": "La foule accuse les chrétiens d''anthropophagie.", "translation": "Une fausse rumeur née d''un malentendu."}]'::jsonb, null, '{"id": "eg.d.c03_anthropophagie", "unitId": "eg.v.c03_anthropophagie", "word": "l''anthropophagie", "translation": "accusation fausse : manger de la chair humaine", "partOfSpeech": "concept", "collection": "notion", "explanation": "Une rumeur sans aucun fondement contre les chrétiens, avec celle du meurtre rituel. Elle vient sans doute de paroles mal comprises sur le corps et le sang du Christ.", "examples": [{"text": "La foule accuse les chrétiens d''anthropophagie.", "translation": "Une fausse rumeur née d''un malentendu."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_atheisme', 'eg', 'l''accusation d''athéisme', 'reproche fait aux chrétiens de n''avoir aucun dieu', 'Les chrétiens n''ont ni statues ni temples païens et rejettent les dieux de l''Empire. Pour les philosophes, ce sont donc des athées. Paradoxe : on les accuse de n''avoir aucun dieu, eux qui croient en Dieu.', '[{"text": "Pour les philosophes, les chrétiens sont des athées.", "translation": "On les accuse de n''avoir aucun dieu."}]'::jsonb, null, '{"id": "eg.d.c03_atheisme", "unitId": "eg.v.c03_atheisme", "word": "l''accusation d''athéisme", "translation": "reproche fait aux chrétiens de n''avoir aucun dieu", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les chrétiens n''ont ni statues ni temples païens et rejettent les dieux de l''Empire. Pour les philosophes, ce sont donc des athées. Paradoxe : on les accuse de n''avoir aucun dieu, eux qui croient en Dieu.", "examples": [{"text": "Pour les philosophes, les chrétiens sont des athées.", "translation": "On les accuse de n''avoir aucun dieu."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_maximin', 'eg', 'Maximin', 'empereur romain vers 235 : sixième persécution', 'Empereur à partir de 235. Il s''en prend d''abord aux chefs de l''Église, évêques et prêtres, pour décapiter la communauté. Sa persécution est courte, mais elle ouvre la série du IIIe siècle.', '[{"text": "Maximin frappe d''abord les évêques et les prêtres.", "translation": "Sans chefs, pense-t-il, l''Église tombera."}]'::jsonb, null, '{"id": "eg.d.c03_maximin", "unitId": "eg.v.c03_maximin", "word": "Maximin", "translation": "empereur romain vers 235 : sixième persécution", "partOfSpeech": "person", "collection": "notion", "explanation": "Empereur à partir de 235. Il s''en prend d''abord aux chefs de l''Église, évêques et prêtres, pour décapiter la communauté. Sa persécution est courte, mais elle ouvre la série du IIIe siècle.", "examples": [{"text": "Maximin frappe d''abord les évêques et les prêtres.", "translation": "Sans chefs, pense-t-il, l''Église tombera."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_dece', 'eg', 'Dèce', 'empereur romain vers 249 : septième persécution', 'Dans un Empire en crise, il veut souder tout le monde derrière un même culte. Son édit de 250 oblige chacun à sacrifier. Les chrétiens, qui refusent, deviennent les suspects numéro un.', '[{"text": "Sous Dèce, tout le monde doit sacrifier.", "translation": "L''édit touche tous les habitants de l''Empire."}]'::jsonb, null, '{"id": "eg.d.c03_dece", "unitId": "eg.v.c03_dece", "word": "Dèce", "translation": "empereur romain vers 249 : septième persécution", "partOfSpeech": "person", "collection": "notion", "explanation": "Dans un Empire en crise, il veut souder tout le monde derrière un même culte. Son édit de 250 oblige chacun à sacrifier. Les chrétiens, qui refusent, deviennent les suspects numéro un.", "examples": [{"text": "Sous Dèce, tout le monde doit sacrifier.", "translation": "L''édit touche tous les habitants de l''Empire."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_edit_250', 'eg', 'l''édit de 250', 'édit de Dèce qui oblige tout le monde à sacrifier', 'Publié par Dèce en 250. Il rend le culte impérial obligatoire pour souder la population contre les dangers extérieurs. Tout citoyen doit sacrifier aux dieux de l''Empire.', '[{"text": "En 250, l''édit de Dèce ordonne à tous de sacrifier.", "translation": "Une date à retenir : 250."}]'::jsonb, null, '{"id": "eg.d.c03_edit_250", "unitId": "eg.v.c03_edit_250", "word": "l''édit de 250", "translation": "édit de Dèce qui oblige tout le monde à sacrifier", "partOfSpeech": "event", "collection": "date", "explanation": "Publié par Dèce en 250. Il rend le culte impérial obligatoire pour souder la population contre les dangers extérieurs. Tout citoyen doit sacrifier aux dieux de l''Empire.", "examples": [{"text": "En 250, l''édit de Dèce ordonne à tous de sacrifier.", "translation": "Une date à retenir : 250."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_libellus', 'eg', 'le libellus', 'certificat prouvant qu''on a sacrifié aux dieux sous Dèce', 'Celui qui a sacrifié reçoit ce certificat. Certains chrétiens cèdent vraiment, d''autres se procurent un faux libellus. Pour un chrétien, ce papier veut dire : j''ai renié ma foi.', '[{"text": "Il a un libellus : il a donc sacrifié.", "translation": "Le certificat est la preuve du sacrifice."}]'::jsonb, null, '{"id": "eg.d.c03_libellus", "unitId": "eg.v.c03_libellus", "word": "le libellus", "translation": "certificat prouvant qu''on a sacrifié aux dieux sous Dèce", "partOfSpeech": "concept", "collection": "objet", "explanation": "Celui qui a sacrifié reçoit ce certificat. Certains chrétiens cèdent vraiment, d''autres se procurent un faux libellus. Pour un chrétien, ce papier veut dire : j''ai renié ma foi.", "examples": [{"text": "Il a un libellus : il a donc sacrifié.", "translation": "Le certificat est la preuve du sacrifice."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_tombes', 'eg', 'les « tombés »', 'chrétiens qui ont renié la foi pendant la persécution', 'Sous Dèce, certains ont sacrifié par peur. Une fois la tempête passée, ils veulent revenir. L''Église doit décider comment les recevoir : c''est un des grands débats du siècle.', '[{"text": "Les tombés frappent à la porte de l''église.", "translation": "Ils regrettent et demandent à revenir."}]'::jsonb, null, '{"id": "eg.d.c03_tombes", "unitId": "eg.v.c03_tombes", "word": "les « tombés »", "translation": "chrétiens qui ont renié la foi pendant la persécution", "partOfSpeech": "concept", "collection": "notion", "explanation": "Sous Dèce, certains ont sacrifié par peur. Une fois la tempête passée, ils veulent revenir. L''Église doit décider comment les recevoir : c''est un des grands débats du siècle.", "examples": [{"text": "Les tombés frappent à la porte de l''église.", "translation": "Ils regrettent et demandent à revenir."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_penitence', 'eg', 'la pénitence', 'chemin sincère de repentir pour obtenir le pardon', 'C''est la réponse de l''Église aux tombés : un temps de repentir, puis le retour dans la communion. Ni pardon facile, ni porte fermée.', '[{"text": "Après une pénitence sincère, il est reçu à nouveau.", "translation": "Le repentir se vit, il ne s''improvise pas."}]'::jsonb, null, '{"id": "eg.d.c03_penitence", "unitId": "eg.v.c03_penitence", "word": "la pénitence", "translation": "chemin sincère de repentir pour obtenir le pardon", "partOfSpeech": "concept", "collection": "notion", "explanation": "C''est la réponse de l''Église aux tombés : un temps de repentir, puis le retour dans la communion. Ni pardon facile, ni porte fermée.", "examples": [{"text": "Après une pénitence sincère, il est reçu à nouveau.", "translation": "Le repentir se vit, il ne s''improvise pas."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_novatien', 'eg', 'Novatien', 'théologien romain qui refuse tout pardon aux tombés (251)', 'Théologien très instruit, consacré évêque de Rome en 251 contre Corneille. Pour lui l''Église doit rester pure, sans pardon pour les tombés. Il est excommunié ; ses partisans, les novatiens, forment une secte qui dure plusieurs siècles.', '[{"text": "Novatien veut une Église pure, sans pardon.", "translation": "Mais fermer la porte aux repentants contredit le Christ."}]'::jsonb, null, '{"id": "eg.d.c03_novatien", "unitId": "eg.v.c03_novatien", "word": "Novatien", "translation": "théologien romain qui refuse tout pardon aux tombés (251)", "partOfSpeech": "person", "collection": "heresie", "explanation": "Théologien très instruit, consacré évêque de Rome en 251 contre Corneille. Pour lui l''Église doit rester pure, sans pardon pour les tombés. Il est excommunié ; ses partisans, les novatiens, forment une secte qui dure plusieurs siècles.", "examples": [{"text": "Novatien veut une Église pure, sans pardon.", "translation": "Mais fermer la porte aux repentants contredit le Christ."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_excommunication', 'eg', 'l''excommunication', 'exclusion d''un baptisé de la communion de l''Église', 'C''est la sanction de l''Église contre celui qui s''obstine dans l''erreur. Novatien est excommunié en 251, Paul de Samosate en 269.', '[{"text": "Novatien est excommunié en 251.", "translation": "Il est exclu de la communion de l''Église."}]'::jsonb, null, '{"id": "eg.d.c03_excommunication", "unitId": "eg.v.c03_excommunication", "word": "l''excommunication", "translation": "exclusion d''un baptisé de la communion de l''Église", "partOfSpeech": "concept", "collection": "notion", "explanation": "C''est la sanction de l''Église contre celui qui s''obstine dans l''erreur. Novatien est excommunié en 251, Paul de Samosate en 269.", "examples": [{"text": "Novatien est excommunié en 251.", "translation": "Il est exclu de la communion de l''Église."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_valerien', 'eg', 'Valérien', 'empereur romain vers 257 : huitième persécution', 'Il interdit les assemblées chrétiennes et frappe surtout le clergé. Il est capturé par les Perses en 260, et son fils Gallien arrête la persécution.', '[{"text": "Valérien interdit les assemblées chrétiennes.", "translation": "Il vise surtout le clergé."}]'::jsonb, null, '{"id": "eg.d.c03_valerien", "unitId": "eg.v.c03_valerien", "word": "Valérien", "translation": "empereur romain vers 257 : huitième persécution", "partOfSpeech": "person", "collection": "notion", "explanation": "Il interdit les assemblées chrétiennes et frappe surtout le clergé. Il est capturé par les Perses en 260, et son fils Gallien arrête la persécution.", "examples": [{"text": "Valérien interdit les assemblées chrétiennes.", "translation": "Il vise surtout le clergé."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_cyprien', 'eg', 'Cyprien de Carthage', 'évêque de Carthage, défenseur du pardon, décapité en 258', 'Il combat Novatien avec Denys d''Alexandrie et défend le retour des vrais pénitents. Sous Valérien, il est décapité en 258.', '[{"text": "Cyprien est décapité en 258.", "translation": "Un évêque qui pardonne, et qui tient bon jusqu''au bout."}]'::jsonb, null, '{"id": "eg.d.c03_cyprien", "unitId": "eg.v.c03_cyprien", "word": "Cyprien de Carthage", "translation": "évêque de Carthage, défenseur du pardon, décapité en 258", "partOfSpeech": "person", "collection": "saint", "explanation": "Il combat Novatien avec Denys d''Alexandrie et défend le retour des vrais pénitents. Sous Valérien, il est décapité en 258.", "examples": [{"text": "Cyprien est décapité en 258.", "translation": "Un évêque qui pardonne, et qui tient bon jusqu''au bout."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_semence', 'eg', 'la semence de chrétiens', 'formule de Tertullien : le sang des martyrs fait naître des chrétiens', 'Les violences ont l''effet contraire à celui qu''on attendait : le courage des martyrs impressionne les spectateurs et entraîne des conversions. Tertullien le résume : « Le sang des martyrs est semence de chrétiens. »', '[{"text": "Le sang des martyrs est semence de chrétiens.", "translation": "Plus on les frappe, plus ils sont nombreux."}]'::jsonb, null, '{"id": "eg.d.c03_semence", "unitId": "eg.v.c03_semence", "word": "la semence de chrétiens", "translation": "formule de Tertullien : le sang des martyrs fait naître des chrétiens", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les violences ont l''effet contraire à celui qu''on attendait : le courage des martyrs impressionne les spectateurs et entraîne des conversions. Tertullien le résume : « Le sang des martyrs est semence de chrétiens. »", "examples": [{"text": "Le sang des martyrs est semence de chrétiens.", "translation": "Plus on les frappe, plus ils sont nombreux."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_diocletien', 'eg', 'Dioclétien', 'empereur dès 284 : dixième persécution, début de l''ère des martyrs', 'Empereur à partir de 284, il règne longtemps. Sous lui, la persécution touche pour la première fois tout l''Empire, Égypte comprise. Son accession devient l''an 1 du calendrier copte.', '[{"text": "Dioclétien devient empereur en 284.", "translation": "Pour les Coptes, c''est l''an 1."}]'::jsonb, null, '{"id": "eg.d.c03_diocletien", "unitId": "eg.v.c03_diocletien", "word": "Dioclétien", "translation": "empereur dès 284 : dixième persécution, début de l''ère des martyrs", "partOfSpeech": "person", "collection": "notion", "explanation": "Empereur à partir de 284, il règne longtemps. Sous lui, la persécution touche pour la première fois tout l''Empire, Égypte comprise. Son accession devient l''an 1 du calendrier copte.", "examples": [{"text": "Dioclétien devient empereur en 284.", "translation": "Pour les Coptes, c''est l''an 1."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_persecution_303', 'eg', 'la grande persécution de 303', 'édits de 303 : églises détruites, livres brûlés, clergé emprisonné', 'En 303, des édits très durs ordonnent de détruire les églises, brûler les livres saints, emprisonner le clergé et forcer chacun à sacrifier. C''est la dixième persécution, la plus générale.', '[{"text": "En 303 éclate la grande persécution.", "translation": "Le sommet de l''épreuve sous Dioclétien."}]'::jsonb, null, '{"id": "eg.d.c03_persecution_303", "unitId": "eg.v.c03_persecution_303", "word": "la grande persécution de 303", "translation": "édits de 303 : églises détruites, livres brûlés, clergé emprisonné", "partOfSpeech": "event", "collection": "date", "explanation": "En 303, des édits très durs ordonnent de détruire les églises, brûler les livres saints, emprisonner le clergé et forcer chacun à sacrifier. C''est la dixième persécution, la plus générale.", "examples": [{"text": "En 303 éclate la grande persécution.", "translation": "Le sommet de l''épreuve sous Dioclétien."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_calendrier_copte', 'eg', 'le calendrier copte', 'calendrier dont l''an 1 est l''année 284 : l''ère des martyrs', 'Les Coptes comptent leurs années à partir de l''accession de Dioclétien, en 284, pour garder la mémoire des martyrs. On l''appelle aussi l''ère des martyrs. C''est un calendrier de fidélité, pas de gloire humaine.', '[{"text": "Le calendrier copte commence en 284.", "translation": "Chaque année rappelle le témoignage des martyrs."}]'::jsonb, null, '{"id": "eg.d.c03_calendrier_copte", "unitId": "eg.v.c03_calendrier_copte", "word": "le calendrier copte", "translation": "calendrier dont l''an 1 est l''année 284 : l''ère des martyrs", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les Coptes comptent leurs années à partir de l''accession de Dioclétien, en 284, pour garder la mémoire des martyrs. On l''appelle aussi l''ère des martyrs. C''est un calendrier de fidélité, pas de gloire humaine.", "examples": [{"text": "Le calendrier copte commence en 284.", "translation": "Chaque année rappelle le témoignage des martyrs."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_nayrouz', 'eg', 'le Nayrouz', 'le jour de l''an copte, en septembre', 'Le Nayrouz ouvre l''année copte, en septembre. Pour trouver l''année copte, on retire 283 à l''année actuelle après le Nayrouz (284 avant).', '[{"text": "Après le Nayrouz de septembre 2026, c''est l''an 1743.", "translation": "2026 moins 283 égale 1743."}]'::jsonb, null, '{"id": "eg.d.c03_nayrouz", "unitId": "eg.v.c03_nayrouz", "word": "le Nayrouz", "translation": "le jour de l''an copte, en septembre", "partOfSpeech": "event", "collection": "date", "explanation": "Le Nayrouz ouvre l''année copte, en septembre. Pour trouver l''année copte, on retire 283 à l''année actuelle après le Nayrouz (284 avant).", "examples": [{"text": "Après le Nayrouz de septembre 2026, c''est l''an 1743.", "translation": "2026 moins 283 égale 1743."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_paul_de_thebes', 'eg', 'saint Paul de Thèbes', 'le premier des ermites, au désert d''Égypte vers 250', 'Il fuit la persécution de Dèce et vit seul dans une grotte pendant des décennies. Selon la tradition, un corbeau lui apporte chaque jour du pain. L''Église le tient pour le premier des ermites.', '[{"text": "Paul de Thèbes fuit au désert sous Dèce.", "translation": "Le premier ermite, bien avant Antoine."}]'::jsonb, null, '{"id": "eg.d.c03_paul_de_thebes", "unitId": "eg.v.c03_paul_de_thebes", "word": "saint Paul de Thèbes", "translation": "le premier des ermites, au désert d''Égypte vers 250", "partOfSpeech": "person", "collection": "saint", "explanation": "Il fuit la persécution de Dèce et vit seul dans une grotte pendant des décennies. Selon la tradition, un corbeau lui apporte chaque jour du pain. L''Église le tient pour le premier des ermites.", "examples": [{"text": "Paul de Thèbes fuit au désert sous Dèce.", "translation": "Le premier ermite, bien avant Antoine."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_antoine', 'eg', 'saint Antoine', 'le père des moines, parti au désert vers 270', 'Jeune Égyptien riche, il entend l''Évangile (Mt 19, 21), donne ses biens aux pauvres et part au désert vers 270. Il devient le maître de ceux qui viendront après lui.', '[{"text": "Antoine donne ses biens et part au désert.", "translation": "On l''appelle le père des moines."}]'::jsonb, null, '{"id": "eg.d.c03_antoine", "unitId": "eg.v.c03_antoine", "word": "saint Antoine", "translation": "le père des moines, parti au désert vers 270", "partOfSpeech": "person", "collection": "saint", "explanation": "Jeune Égyptien riche, il entend l''Évangile (Mt 19, 21), donne ses biens aux pauvres et part au désert vers 270. Il devient le maître de ceux qui viendront après lui.", "examples": [{"text": "Antoine donne ses biens et part au désert.", "translation": "On l''appelle le père des moines."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_ermite', 'eg', 'l''ermite', 'celui qui vit seul au désert pour prier', 'Du grec « eremos », désert. L''ermite prie, jeûne et travaille de ses mains. Le mot anachorète (du grec « anachôrein », se retirer) désigne celui qui se retire du monde : même chemin.', '[{"text": "Paul est un ermite : il vit seul au désert.", "translation": "Eremos veut dire désert en grec."}]'::jsonb, null, '{"id": "eg.d.c03_ermite", "unitId": "eg.v.c03_ermite", "word": "l''ermite", "translation": "celui qui vit seul au désert pour prier", "partOfSpeech": "concept", "collection": "notion", "explanation": "Du grec « eremos », désert. L''ermite prie, jeûne et travaille de ses mains. Le mot anachorète (du grec « anachôrein », se retirer) désigne celui qui se retire du monde : même chemin.", "examples": [{"text": "Paul est un ermite : il vit seul au désert.", "translation": "Eremos veut dire désert en grec."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_desert_egypte', 'eg', 'le désert d''Égypte', 'terre aride proche du Nil où les premiers ermites se retirent', 'À quelques jours du Nil et des villes, le désert offre le silence. D''abord refuge contre les persécutions, il devient le berceau du monachisme.', '[{"text": "Antoine part vivre au désert d''Égypte.", "translation": "Un refuge qui devient une vocation."}]'::jsonb, null, '{"id": "eg.d.c03_desert_egypte", "unitId": "eg.v.c03_desert_egypte", "word": "le désert d''Égypte", "translation": "terre aride proche du Nil où les premiers ermites se retirent", "partOfSpeech": "place", "collection": "lieu", "explanation": "À quelques jours du Nil et des villes, le désert offre le silence. D''abord refuge contre les persécutions, il devient le berceau du monachisme.", "examples": [{"text": "Antoine part vivre au désert d''Égypte.", "translation": "Un refuge qui devient une vocation."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_ecole_alexandrie', 'eg', 'l''École d''Alexandrie', 'la première école de théologie chrétienne', 'Fondée selon la tradition par saint Marc. Elle instruit d''abord les catéchumènes, puis on y étudie la Bible, la philosophie et la théologie. Elle forme aussi des chefs de l''Église : Héraclas et Denys la dirigent avant de devenir papes.', '[{"text": "L''École d''Alexandrie forme les catéchumènes.", "translation": "Ceux qui préparent leur baptême."}]'::jsonb, null, '{"id": "eg.d.c03_ecole_alexandrie", "unitId": "eg.v.c03_ecole_alexandrie", "word": "l''École d''Alexandrie", "translation": "la première école de théologie chrétienne", "partOfSpeech": "organization", "collection": "notion", "explanation": "Fondée selon la tradition par saint Marc. Elle instruit d''abord les catéchumènes, puis on y étudie la Bible, la philosophie et la théologie. Elle forme aussi des chefs de l''Église : Héraclas et Denys la dirigent avant de devenir papes.", "examples": [{"text": "L''École d''Alexandrie forme les catéchumènes.", "translation": "Ceux qui préparent leur baptême."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_pantene', 'eg', 'Pantène', 'philosophe converti, maître de Clément', 'Ancien philosophe stoïcien devenu chrétien, il dirige l''École vers 180. Il montre qu''on peut aimer la sagesse grecque sans quitter la foi. Selon Eusèbe, il serait allé prêcher jusqu''en Inde.', '[{"text": "Pantène dirige l''École vers 180.", "translation": "Un philosophe devenu maître chrétien."}]'::jsonb, null, '{"id": "eg.d.c03_pantene", "unitId": "eg.v.c03_pantene", "word": "Pantène", "translation": "philosophe converti, maître de Clément", "partOfSpeech": "person", "collection": "pere", "explanation": "Ancien philosophe stoïcien devenu chrétien, il dirige l''École vers 180. Il montre qu''on peut aimer la sagesse grecque sans quitter la foi. Selon Eusèbe, il serait allé prêcher jusqu''en Inde.", "examples": [{"text": "Pantène dirige l''École vers 180.", "translation": "Un philosophe devenu maître chrétien."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_clement', 'eg', 'Clément d''Alexandrie', 'maître de l''École, auteur du Pédagogue et des Stromates', 'Vers 150-215. Il succède à Pantène. Pour lui, la philosophie grecque est une préparation à l''Évangile, comme la Loi l''était pour les Juifs. Il aide ainsi des gens instruits à devenir chrétiens.', '[{"text": "Clément écrit le Pédagogue.", "translation": "Un livre sur la conduite chrétienne."}]'::jsonb, null, '{"id": "eg.d.c03_clement", "unitId": "eg.v.c03_clement", "word": "Clément d''Alexandrie", "translation": "maître de l''École, auteur du Pédagogue et des Stromates", "partOfSpeech": "person", "collection": "pere", "explanation": "Vers 150-215. Il succède à Pantène. Pour lui, la philosophie grecque est une préparation à l''Évangile, comme la Loi l''était pour les Juifs. Il aide ainsi des gens instruits à devenir chrétiens.", "examples": [{"text": "Clément écrit le Pédagogue.", "translation": "Un livre sur la conduite chrétienne."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_origene', 'eg', 'Origène', 'grand savant d''Alexandrie, auteur des Hexaples', 'Vers 185-253. Fils du martyr Léonide, il enseigne dès 18 ans, compose les Hexaples (la Bible en six colonnes) et cherche le sens spirituel de l''Écriture. Torturé sous Dèce, il meurt vers 253. Certaines de ses idées ont été rejetées plus tard.', '[{"text": "Origène compose les Hexaples.", "translation": "La Bible en six colonnes, pour comparer les textes."}]'::jsonb, null, '{"id": "eg.d.c03_origene", "unitId": "eg.v.c03_origene", "word": "Origène", "translation": "grand savant d''Alexandrie, auteur des Hexaples", "partOfSpeech": "person", "collection": "pere", "explanation": "Vers 185-253. Fils du martyr Léonide, il enseigne dès 18 ans, compose les Hexaples (la Bible en six colonnes) et cherche le sens spirituel de l''Écriture. Torturé sous Dèce, il meurt vers 253. Certaines de ses idées ont été rejetées plus tard.", "examples": [{"text": "Origène compose les Hexaples.", "translation": "La Bible en six colonnes, pour comparer les textes."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_paul_de_samosate', 'eg', 'Paul de Samosate', 'évêque d''Antioche, excommunié en 269 : pour lui le Christ est un homme', 'Soutenu par la reine Zénobie, il enseigne que le Christ est un homme ordinaire et que Dieu n''est qu''une seule personne. Un concile à Antioche le condamne en 269.', '[{"text": "Paul de Samosate nie la Trinité.", "translation": "Pour lui, le Christ n''est qu''un homme."}]'::jsonb, null, '{"id": "eg.d.c03_paul_de_samosate", "unitId": "eg.v.c03_paul_de_samosate", "word": "Paul de Samosate", "translation": "évêque d''Antioche, excommunié en 269 : pour lui le Christ est un homme", "partOfSpeech": "person", "collection": "heresie", "explanation": "Soutenu par la reine Zénobie, il enseigne que le Christ est un homme ordinaire et que Dieu n''est qu''une seule personne. Un concile à Antioche le condamne en 269.", "examples": [{"text": "Paul de Samosate nie la Trinité.", "translation": "Pour lui, le Christ n''est qu''un homme."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_sabellius', 'eg', 'Sabellius', 'évêque de Ptolémaïs : Père, Fils et Esprit sont un seul Dieu sous trois masques', 'Il confond les trois personnes : pour lui, ce ne sont que des manifestations successives d''une seule réalité divine, comme un acteur qui change de masque. Cette erreur s''appelle le modalisme ou sabellianisme.', '[{"text": "Sabellius compare Dieu à un acteur.", "translation": "Trois masques, une seule personne : c''est le modalisme."}]'::jsonb, null, '{"id": "eg.d.c03_sabellius", "unitId": "eg.v.c03_sabellius", "word": "Sabellius", "translation": "évêque de Ptolémaïs : Père, Fils et Esprit sont un seul Dieu sous trois masques", "partOfSpeech": "person", "collection": "heresie", "explanation": "Il confond les trois personnes : pour lui, ce ne sont que des manifestations successives d''une seule réalité divine, comme un acteur qui change de masque. Cette erreur s''appelle le modalisme ou sabellianisme.", "examples": [{"text": "Sabellius compare Dieu à un acteur.", "translation": "Trois masques, une seule personne : c''est le modalisme."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_sainte_trinite', 'eg', 'la Sainte Trinité', 'un seul Dieu en trois personnes : le Père, le Fils et le Saint-Esprit', 'C''est le cœur de la foi chrétienne : trois personnes, une seule divinité. Ni trois dieux, ni un seul Dieu qui change de masque.', '[{"text": "Le Père, le Fils et le Saint-Esprit sont trois personnes.", "translation": "Mais une seule divinité."}]'::jsonb, null, '{"id": "eg.d.c03_sainte_trinite", "unitId": "eg.v.c03_sainte_trinite", "word": "la Sainte Trinité", "translation": "un seul Dieu en trois personnes : le Père, le Fils et le Saint-Esprit", "partOfSpeech": "concept", "collection": "notion", "explanation": "C''est le cœur de la foi chrétienne : trois personnes, une seule divinité. Ni trois dieux, ni un seul Dieu qui change de masque.", "examples": [{"text": "Le Père, le Fils et le Saint-Esprit sont trois personnes.", "translation": "Mais une seule divinité."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_denys', 'eg', 'Denys d''Alexandrie', '14e pape d''Alexandrie, défenseur de la foi trinitaire', 'Trop âgé pour aller à Antioche, il écrit une lettre : le Fils est consubstantiel au Père. Il combat aussi Sabellius et Novatien. Il succède à Héraclas.', '[{"text": "Denys écrit une lettre à Antioche.", "translation": "Il défend la foi trinitaire."}]'::jsonb, null, '{"id": "eg.d.c03_denys", "unitId": "eg.v.c03_denys", "word": "Denys d''Alexandrie", "translation": "14e pape d''Alexandrie, défenseur de la foi trinitaire", "partOfSpeech": "person", "collection": "pape", "explanation": "Trop âgé pour aller à Antioche, il écrit une lettre : le Fils est consubstantiel au Père. Il combat aussi Sabellius et Novatien. Il succède à Héraclas.", "examples": [{"text": "Denys écrit une lettre à Antioche.", "translation": "Il défend la foi trinitaire."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_mani', 'eg', 'Mani', 'Perse du IIIe siècle, fondateur du manichéisme', 'Il fonde un mouvement religieux influencé par la gnose, présenté comme une variante du mazdéisme, la religion des Perses. Pour lui, le monde est une lutte du Bien contre le Mal.', '[{"text": "Mani est un Perse du IIIe siècle.", "translation": "Il fonde le manichéisme."}]'::jsonb, null, '{"id": "eg.d.c03_mani", "unitId": "eg.v.c03_mani", "word": "Mani", "translation": "Perse du IIIe siècle, fondateur du manichéisme", "partOfSpeech": "person", "collection": "heresie", "explanation": "Il fonde un mouvement religieux influencé par la gnose, présenté comme une variante du mazdéisme, la religion des Perses. Pour lui, le monde est une lutte du Bien contre le Mal.", "examples": [{"text": "Mani est un Perse du IIIe siècle.", "translation": "Il fonde le manichéisme."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_manicheisme', 'eg', 'le manichéisme', 'doctrine de Mani : un Dieu bon, un démiurge mauvais, toutes religions valides', 'Un Dieu bon crée l''esprit, un démiurge mauvais crée la matière et les corps. Toutes les religions sont valides et on croit à la réincarnation. Incompatible avec l''Incarnation : si le corps est mauvais, Dieu ne peut pas se faire homme.', '[{"text": "Pour le manichéisme, le corps est l''œuvre du mal.", "translation": "D''où son incompatibilité avec l''Incarnation."}]'::jsonb, null, '{"id": "eg.d.c03_manicheisme", "unitId": "eg.v.c03_manicheisme", "word": "le manichéisme", "translation": "doctrine de Mani : un Dieu bon, un démiurge mauvais, toutes religions valides", "partOfSpeech": "concept", "collection": "heresie", "explanation": "Un Dieu bon crée l''esprit, un démiurge mauvais crée la matière et les corps. Toutes les religions sont valides et on croit à la réincarnation. Incompatible avec l''Incarnation : si le corps est mauvais, Dieu ne peut pas se faire homme.", "examples": [{"text": "Pour le manichéisme, le corps est l''œuvre du mal.", "translation": "D''où son incompatibilité avec l''Incarnation."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_augustin', 'eg', 'saint Augustin', 'grand Père latin, manichéen avant sa conversion', 'Esprit brillant, il a adhéré au manichéisme avant de se convertir au christianisme. Son parcours montre que cette doctrine séduisait des intelligences et que l''Église savait répondre.', '[{"text": "Augustin a été manichéen avant de se convertir.", "translation": "Il savait donc de quoi il parlait."}]'::jsonb, null, '{"id": "eg.d.c03_augustin", "unitId": "eg.v.c03_augustin", "word": "saint Augustin", "translation": "grand Père latin, manichéen avant sa conversion", "partOfSpeech": "person", "collection": "pere", "explanation": "Esprit brillant, il a adhéré au manichéisme avant de se convertir au christianisme. Son parcours montre que cette doctrine séduisait des intelligences et que l''Église savait répondre.", "examples": [{"text": "Augustin a été manichéen avant de se convertir.", "translation": "Il savait donc de quoi il parlait."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_hermas', 'eg', 'le Pasteur d''Hermas', 'écrit du IIe siècle fait de visions, jugé trop incontrôlable pour le canon', 'Un Père apostolique honorable, mais son livre raconte des visions que rien ne permet de contrôler. Il reste donc hors du canon : vénérable, pas inspiré.', '[{"text": "Le Pasteur d''Hermas reste hors du canon.", "translation": "Honorable, mais fait de visions incontrôlables."}]'::jsonb, null, '{"id": "eg.d.c03_hermas", "unitId": "eg.v.c03_hermas", "word": "le Pasteur d''Hermas", "translation": "écrit du IIe siècle fait de visions, jugé trop incontrôlable pour le canon", "partOfSpeech": "work", "collection": "livre", "explanation": "Un Père apostolique honorable, mais son livre raconte des visions que rien ne permet de contrôler. Il reste donc hors du canon : vénérable, pas inspiré.", "examples": [{"text": "Le Pasteur d''Hermas reste hors du canon.", "translation": "Honorable, mais fait de visions incontrôlables."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_approbation_apostolique', 'eg', 'l''approbation apostolique', 'principal test du canon : le livre vient des apôtres ou de leur contrôle', 'Les apôtres sont les fondateurs et les dirigeants de l''Église. Il est donc logique que la Parole qui la gouverne vienne d''eux, qui sont les mieux placés pour la transmettre fidèlement.', '[{"text": "Marc écrit sous le contrôle de Pierre.", "translation": "Son évangile a l''approbation apostolique."}]'::jsonb, null, '{"id": "eg.d.c03_approbation_apostolique", "unitId": "eg.v.c03_approbation_apostolique", "word": "l''approbation apostolique", "translation": "principal test du canon : le livre vient des apôtres ou de leur contrôle", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les apôtres sont les fondateurs et les dirigeants de l''Église. Il est donc logique que la Parole qui la gouverne vienne d''eux, qui sont les mieux placés pour la transmettre fidèlement.", "examples": [{"text": "Marc écrit sous le contrôle de Pierre.", "translation": "Son évangile a l''approbation apostolique."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_apocryphes', 'eg', 'les apocryphes', 'écrits écartés du canon, éloignés de la foi des apôtres', 'Des écrits sur Jésus et les apôtres, remplis de légendes. Leur Jésus est souvent un faiseur de miracles gratuits, loin de l''amour du Père montré dans les évangiles.', '[{"text": "Les évangiles apocryphes ne sont pas dans le canon.", "translation": "Ils ne passent pas les quatre critères."}]'::jsonb, null, '{"id": "eg.d.c03_apocryphes", "unitId": "eg.v.c03_apocryphes", "word": "les apocryphes", "translation": "écrits écartés du canon, éloignés de la foi des apôtres", "partOfSpeech": "concept", "collection": "livre", "explanation": "Des écrits sur Jésus et les apôtres, remplis de légendes. Leur Jésus est souvent un faiseur de miracles gratuits, loin de l''amour du Père montré dans les évangiles.", "examples": [{"text": "Les évangiles apocryphes ne sont pas dans le canon.", "translation": "Ils ne passent pas les quatre critères."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_didache', 'eg', 'la Didachè', 'écrit très ancien (vers 100) sur la vie des communautés', 'Un texte vénérable sur la vie des premières communautés, mais hors du canon : il retombe dans le légalisme. Autres sources de la Tradition écrite : la Tradition apostolique d''Hippolyte (vers 215), la Didascalie syriaque (vers 250), les Constitutions apostoliques (vers 380).', '[{"text": "La Didachè date d''environ 100.", "translation": "Utile, mais pas inspirée."}]'::jsonb, null, '{"id": "eg.d.c03_didache", "unitId": "eg.v.c03_didache", "word": "la Didachè", "translation": "écrit très ancien (vers 100) sur la vie des communautés", "partOfSpeech": "work", "collection": "livre", "explanation": "Un texte vénérable sur la vie des premières communautés, mais hors du canon : il retombe dans le légalisme. Autres sources de la Tradition écrite : la Tradition apostolique d''Hippolyte (vers 215), la Didascalie syriaque (vers 250), les Constitutions apostoliques (vers 380).", "examples": [{"text": "La Didachè date d''environ 100.", "translation": "Utile, mais pas inspirée."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_heraclas', 'eg', 'Héraclas', '13e évêque d''Alexandrie, le premier appelé pape', 'Il dirige l''École d''Alexandrie, puis devient le 13e évêque d''Alexandrie, vers 230-250. Depuis lui, l''évêque d''Alexandrie porte le titre de pape, « père ». Son successeur Denys est le 14e. Le titre de patriarche, lui, n''arrive qu''à partir de 451.', '[{"text": "Héraclas est le premier à être appelé pape.", "translation": "Depuis, le pape d''Alexandrie garde ce titre."}]'::jsonb, null, '{"id": "eg.d.c03_heraclas", "unitId": "eg.v.c03_heraclas", "word": "Héraclas", "translation": "13e évêque d''Alexandrie, le premier appelé pape", "partOfSpeech": "person", "collection": "pape", "explanation": "Il dirige l''École d''Alexandrie, puis devient le 13e évêque d''Alexandrie, vers 230-250. Depuis lui, l''évêque d''Alexandrie porte le titre de pape, « père ». Son successeur Denys est le 14e. Le titre de patriarche, lui, n''arrive qu''à partir de 451.", "examples": [{"text": "Héraclas est le premier à être appelé pape.", "translation": "Depuis, le pape d''Alexandrie garde ce titre."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_hierarchie', 'eg', 'la hiérarchie à trois degrés', 'évêque, prêtre, diacre : l''organisation de l''Église dès le IIIe siècle', 'Au début, la direction est collégiale. À partir du IIe siècle, un évêque unique, successeur des apôtres. Au IIIe siècle, les trois degrés s''affirment : évêque, prêtre, diacre.', '[{"text": "Évêque, prêtre, diacre : trois degrés.", "translation": "Les trois fonctions sont déjà dans le Nouveau Testament."}]'::jsonb, null, '{"id": "eg.d.c03_hierarchie", "unitId": "eg.v.c03_hierarchie", "word": "la hiérarchie à trois degrés", "translation": "évêque, prêtre, diacre : l''organisation de l''Église dès le IIIe siècle", "partOfSpeech": "concept", "collection": "notion", "explanation": "Au début, la direction est collégiale. À partir du IIe siècle, un évêque unique, successeur des apôtres. Au IIIe siècle, les trois degrés s''affirment : évêque, prêtre, diacre.", "examples": [{"text": "Évêque, prêtre, diacre : trois degrés.", "translation": "Les trois fonctions sont déjà dans le Nouveau Testament."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_confesseur', 'eg', 'le confesseur', 'chrétien qui a souffert pour sa foi sans mourir martyr', 'Les persécutions font naître ce titre. Le confesseur est respecté et dirige souvent les offices, sans imposition des mains. Mais pour devenir évêque, il doit être ordonné (d''après la Tradition apostolique d''Hippolyte).', '[{"text": "Un confesseur a survécu à la torture.", "translation": "Mais il doit être ordonné pour devenir évêque."}]'::jsonb, null, '{"id": "eg.d.c03_confesseur", "unitId": "eg.v.c03_confesseur", "word": "le confesseur", "translation": "chrétien qui a souffert pour sa foi sans mourir martyr", "partOfSpeech": "person", "collection": "notion", "explanation": "Les persécutions font naître ce titre. Le confesseur est respecté et dirige souvent les offices, sans imposition des mains. Mais pour devenir évêque, il doit être ordonné (d''après la Tradition apostolique d''Hippolyte).", "examples": [{"text": "Un confesseur a survécu à la torture.", "translation": "Mais il doit être ordonné pour devenir évêque."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_clercs_laics', 'eg', 'les clercs et les laïcs', 'les clercs sont ordonnés ; les laïcs sont les autres fidèles', 'Cette distinction apparaît au IIIe siècle. Les clercs reçoivent l''ordination ; les laïcs sont tous les autres baptisés, qui forment aussi l''Église.', '[{"text": "Le diacre est un clerc.", "translation": "Un simple baptisé est un laïc."}]'::jsonb, null, '{"id": "eg.d.c03_clercs_laics", "unitId": "eg.v.c03_clercs_laics", "word": "les clercs et les laïcs", "translation": "les clercs sont ordonnés ; les laïcs sont les autres fidèles", "partOfSpeech": "concept", "collection": "notion", "explanation": "Cette distinction apparaît au IIIe siècle. Les clercs reçoivent l''ordination ; les laïcs sont tous les autres baptisés, qui forment aussi l''Église.", "examples": [{"text": "Le diacre est un clerc.", "translation": "Un simple baptisé est un laïc."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_dix_persecutions', 'eg', 'les dix persécutions', 'liste traditionnelle des dix grandes persécutions, de Néron à Dioclétien', 'L''Église numérote dix grandes persécutions. Au IIIe siècle tombent la sixième (Maximin), la septième (Dèce), la huitième (Valérien) et la neuvième. La dixième, sous Dioclétien, est générale.', '[{"text": "Dèce ordonne la septième des dix persécutions.", "translation": "On les compte, de Néron à Dioclétien."}]'::jsonb, null, '{"id": "eg.d.c03_dix_persecutions", "unitId": "eg.v.c03_dix_persecutions", "word": "les dix persécutions", "translation": "liste traditionnelle des dix grandes persécutions, de Néron à Dioclétien", "partOfSpeech": "event", "collection": "date", "explanation": "L''Église numérote dix grandes persécutions. Au IIIe siècle tombent la sixième (Maximin), la septième (Dèce), la huitième (Valérien) et la neuvième. La dixième, sous Dioclétien, est générale.", "examples": [{"text": "Dèce ordonne la septième des dix persécutions.", "translation": "On les compte, de Néron à Dioclétien."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c03_ere_martyrs', 'eg', 'l''ère des martyrs', 'autre nom du calendrier copte, compté depuis 284', 'Les Coptes datent leurs années depuis 284, l''accession de Dioclétien, pour garder la mémoire des martyrs. Après le Nayrouz de septembre 2026, on est en l''an 1743 de l''ère des martyrs.', '[{"text": "Nous sommes en l''an 1743 de l''ère des martyrs.", "translation": "Année actuelle moins 283 après le Nayrouz."}]'::jsonb, null, '{"id": "eg.d.c03_ere_martyrs", "unitId": "eg.v.c03_ere_martyrs", "word": "l''ère des martyrs", "translation": "autre nom du calendrier copte, compté depuis 284", "partOfSpeech": "concept", "collection": "date", "explanation": "Les Coptes datent leurs années depuis 284, l''accession de Dioclétien, pour garder la mémoire des martyrs. Après le Nayrouz de septembre 2026, on est en l''an 1743 de l''ère des martyrs.", "examples": [{"text": "Nous sommes en l''an 1743 de l''ère des martyrs.", "translation": "Année actuelle moins 283 après le Nayrouz."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_galere', 'eg', 'Galère', 'empereur après Dioclétien (305), plus cruel encore', 'Second de Dioclétien, il lui succède en 305 et invente sans cesse de nouvelles tortures. Gravement malade, il signe en 311 l''édit de tolérance.', '[{"text": "Galère succède à Dioclétien en 305.", "translation": "Il prend la place de l''empereur qui avait publié les quatre édits."}]'::jsonb, null, '{"id": "eg.d.c04_galere", "unitId": "eg.v.c04_galere", "word": "Galère", "translation": "empereur après Dioclétien (305), plus cruel encore", "partOfSpeech": "person", "collection": "notion", "explanation": "Second de Dioclétien, il lui succède en 305 et invente sans cesse de nouvelles tortures. Gravement malade, il signe en 311 l''édit de tolérance.", "examples": [{"text": "Galère succède à Dioclétien en 305.", "translation": "Il prend la place de l''empereur qui avait publié les quatre édits."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_edit_311', 'eg', 'l''édit de tolérance (311)', 'édit de Galère : les chrétiens peuvent exister et prier', 'Signé en 311 par Galère malade, il met fin à la grande persécution de 303-311. Ce n''est pas encore la pleine liberté : elle viendra avec l''édit de Milan, en 313.', '[{"text": "En 311, Galère autorise les chrétiens à prier.", "translation": "Il tolère l''Église, sans lui donner encore la liberté."}]'::jsonb, null, '{"id": "eg.d.c04_edit_311", "unitId": "eg.v.c04_edit_311", "word": "l''édit de tolérance (311)", "translation": "édit de Galère : les chrétiens peuvent exister et prier", "partOfSpeech": "event", "collection": "date", "explanation": "Signé en 311 par Galère malade, il met fin à la grande persécution de 303-311. Ce n''est pas encore la pleine liberté : elle viendra avec l''édit de Milan, en 313.", "examples": [{"text": "En 311, Galère autorise les chrétiens à prier.", "translation": "Il tolère l''Église, sans lui donner encore la liberté."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_pierre_sceau', 'eg', 'le pape Pierre, sceau des martyrs', 'pape d''Alexandrie martyrisé en 311', 'Pape d''Alexandrie, il est martyrisé en 311, à la fin de la grande persécution. On l''appelle « le sceau des martyrs » parce qu''il ferme la liste des martyrs de cette épreuve.', '[{"text": "Le pape Pierre meurt martyr en 311.", "translation": "Un sceau ferme une lettre ; lui ferme la liste."}]'::jsonb, null, '{"id": "eg.d.c04_pierre_sceau", "unitId": "eg.v.c04_pierre_sceau", "word": "le pape Pierre, sceau des martyrs", "translation": "pape d''Alexandrie martyrisé en 311", "partOfSpeech": "person", "collection": "pape", "explanation": "Pape d''Alexandrie, il est martyrisé en 311, à la fin de la grande persécution. On l''appelle « le sceau des martyrs » parce qu''il ferme la liste des martyrs de cette épreuve.", "examples": [{"text": "Le pape Pierre meurt martyr en 311.", "translation": "Un sceau ferme une lettre ; lui ferme la liste."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_saint_georges', 'eg', 'saint Georges', 'soldat et martyr de la grande persécution, vers 303', 'Soldat martyrisé vers 303, au début de la persécution de Dioclétien. Il est très vénéré en Égypte.', '[{"text": "Saint Georges est martyrisé vers 303.", "translation": "Il fait partie des premiers martyrs de cette persécution."}]'::jsonb, null, '{"id": "eg.d.c04_saint_georges", "unitId": "eg.v.c04_saint_georges", "word": "saint Georges", "translation": "soldat et martyr de la grande persécution, vers 303", "partOfSpeech": "person", "collection": "saint", "explanation": "Soldat martyrisé vers 303, au début de la persécution de Dioclétien. Il est très vénéré en Égypte.", "examples": [{"text": "Saint Georges est martyrisé vers 303.", "translation": "Il fait partie des premiers martyrs de cette persécution."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_constantin', 'eg', 'Constantin', 'empereur romain (306-337), protecteur de l''Église', 'Fils d''Hélène, empereur dès 306, il voit la croix en 312, signe l''édit de Milan en 313 et fonde Constantinople en 330. Il convoque le concile de Nicée.', '[{"text": "Constantin voit la croix avant la bataille de 312.", "translation": "Avec lui, l''Église passe de la persécution à la protection de l''empereur."}]'::jsonb, null, '{"id": "eg.d.c04_constantin", "unitId": "eg.v.c04_constantin", "word": "Constantin", "translation": "empereur romain (306-337), protecteur de l''Église", "partOfSpeech": "person", "collection": "notion", "explanation": "Fils d''Hélène, empereur dès 306, il voit la croix en 312, signe l''édit de Milan en 313 et fonde Constantinople en 330. Il convoque le concile de Nicée.", "examples": [{"text": "Constantin voit la croix avant la bataille de 312.", "translation": "Avec lui, l''Église passe de la persécution à la protection de l''empereur."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_maxence', 'eg', 'Maxence', 'rival de Constantin, vaincu à Rome en 312', 'Empereur à Rome, il est battu par Constantin en 312 et meurt noyé quand le pont sur le Tibre s''écroule.', '[{"text": "Maxence se noie dans le Tibre.", "translation": "Sa défaite écarte le risque d''une nouvelle persécution."}]'::jsonb, null, '{"id": "eg.d.c04_maxence", "unitId": "eg.v.c04_maxence", "word": "Maxence", "translation": "rival de Constantin, vaincu à Rome en 312", "partOfSpeech": "person", "collection": "notion", "explanation": "Empereur à Rome, il est battu par Constantin en 312 et meurt noyé quand le pont sur le Tibre s''écroule.", "examples": [{"text": "Maxence se noie dans le Tibre.", "translation": "Sa défaite écarte le risque d''une nouvelle persécution."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_edit_milan', 'eg', 'l''édit de Milan (313)', 'édit de liberté signé par Constantin et Licinius', 'Signé en 313, il met définitivement fin aux persécutions romaines, rend aux chrétiens leurs biens et ouvre un siècle de paix.', '[{"text": "L''édit de Milan date de 313.", "translation": "C''est la vraie liberté, après la simple tolérance de 311."}]'::jsonb, null, '{"id": "eg.d.c04_edit_milan", "unitId": "eg.v.c04_edit_milan", "word": "l''édit de Milan (313)", "translation": "édit de liberté signé par Constantin et Licinius", "partOfSpeech": "event", "collection": "date", "explanation": "Signé en 313, il met définitivement fin aux persécutions romaines, rend aux chrétiens leurs biens et ouvre un siècle de paix.", "examples": [{"text": "L''édit de Milan date de 313.", "translation": "C''est la vraie liberté, après la simple tolérance de 311."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_licinius', 'eg', 'Licinius', 'empereur, co-signataire de l''édit de Milan', 'Collègue de Constantin, il signe avec lui l''édit de Milan en 313.', '[{"text": "Licinius signe l''édit de Milan avec Constantin.", "translation": "Il est le deuxième nom au bas du texte."}]'::jsonb, null, '{"id": "eg.d.c04_licinius", "unitId": "eg.v.c04_licinius", "word": "Licinius", "translation": "empereur, co-signataire de l''édit de Milan", "partOfSpeech": "person", "collection": "notion", "explanation": "Collègue de Constantin, il signe avec lui l''édit de Milan en 313.", "examples": [{"text": "Licinius signe l''édit de Milan avec Constantin.", "translation": "Il est le deuxième nom au bas du texte."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_helene', 'eg', 'Hélène', 'mère de Constantin, qui retrouve la Sainte Croix', 'Mère de Constantin, elle part à Jérusalem, retrouve la Sainte Croix et fait bâtir la basilique de la Résurrection et d''autres églises. Les Coptes la vénèrent comme sainte.', '[{"text": "Hélène fait bâtir la basilique de la Résurrection.", "translation": "Une reine qui travaille pour la foi."}]'::jsonb, null, '{"id": "eg.d.c04_helene", "unitId": "eg.v.c04_helene", "word": "Hélène", "translation": "mère de Constantin, qui retrouve la Sainte Croix", "partOfSpeech": "person", "collection": "saint", "explanation": "Mère de Constantin, elle part à Jérusalem, retrouve la Sainte Croix et fait bâtir la basilique de la Résurrection et d''autres églises. Les Coptes la vénèrent comme sainte.", "examples": [{"text": "Hélène fait bâtir la basilique de la Résurrection.", "translation": "Une reine qui travaille pour la foi."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_constantinople', 'eg', 'Constantinople', 'capitale de l''empire d''Orient, fondée en 330', 'Byzance, au bord du Bosphore, est rebaptisée « ville de Constantin » en 330. Elle devient la capitale de l''empire d''Orient et un siège majeur de l''Église.', '[{"text": "Constantinople est fondée en 330.", "translation": "Le centre du monde se déplace vers l''est."}]'::jsonb, null, '{"id": "eg.d.c04_constantinople", "unitId": "eg.v.c04_constantinople", "word": "Constantinople", "translation": "capitale de l''empire d''Orient, fondée en 330", "partOfSpeech": "place", "collection": "lieu", "explanation": "Byzance, au bord du Bosphore, est rebaptisée « ville de Constantin » en 330. Elle devient la capitale de l''empire d''Orient et un siège majeur de l''Église.", "examples": [{"text": "Constantinople est fondée en 330.", "translation": "Le centre du monde se déplace vers l''est."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_eveque_du_dehors', 'eg', 'l''évêque du dehors', 'titre que Constantin se donne pour les affaires extérieures de l''Église', 'Constantin se dit chargé des affaires extérieures de l''Église. Cela l''amène à convoquer des conciles, mais crée un danger : l''État intervient dans les débats de foi.', '[{"text": "Constantin se dit « évêque du dehors ».", "translation": "Un titre qui montre la faveur, et le danger."}]'::jsonb, null, '{"id": "eg.d.c04_eveque_du_dehors", "unitId": "eg.v.c04_eveque_du_dehors", "word": "l''évêque du dehors", "translation": "titre que Constantin se donne pour les affaires extérieures de l''Église", "partOfSpeech": "concept", "collection": "notion", "explanation": "Constantin se dit chargé des affaires extérieures de l''Église. Cela l''amène à convoquer des conciles, mais crée un danger : l''État intervient dans les débats de foi.", "examples": [{"text": "Constantin se dit « évêque du dehors ».", "translation": "Un titre qui montre la faveur, et le danger."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_armenie', 'eg', 'l''Arménie', 'premier pays chrétien, en 301', 'En 301, l''Arménie est le premier pays du monde à adopter le christianisme comme religion d''État, avant même Rome.', '[{"text": "L''Arménie devient chrétienne en 301.", "translation": "Un petit royaume qui devance l''Empire."}]'::jsonb, null, '{"id": "eg.d.c04_armenie", "unitId": "eg.v.c04_armenie", "word": "l''Arménie", "translation": "premier pays chrétien, en 301", "partOfSpeech": "place", "collection": "lieu", "explanation": "En 301, l''Arménie est le premier pays du monde à adopter le christianisme comme religion d''État, avant même Rome.", "examples": [{"text": "L''Arménie devient chrétienne en 301.", "translation": "Un petit royaume qui devance l''Empire."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_arius', 'eg', 'Arius', 'prêtre d''Alexandrie, auteur de l''hérésie arienne', 'Prêtre libyen d''origine berbère, ordonné diacre en 311 par le pape Pierre. Vers 318, il enseigne que le Fils n''est pas de la même essence que le Père.', '[{"text": "Arius enseigne vers 318 à Alexandrie.", "translation": "Un prêtre aimé dont l''erreur fait trembler l''Empire."}]'::jsonb, null, '{"id": "eg.d.c04_arius", "unitId": "eg.v.c04_arius", "word": "Arius", "translation": "prêtre d''Alexandrie, auteur de l''hérésie arienne", "partOfSpeech": "person", "collection": "heresie", "explanation": "Prêtre libyen d''origine berbère, ordonné diacre en 311 par le pape Pierre. Vers 318, il enseigne que le Fils n''est pas de la même essence que le Père.", "examples": [{"text": "Arius enseigne vers 318 à Alexandrie.", "translation": "Un prêtre aimé dont l''erreur fait trembler l''Empire."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_arianisme', 'eg', 'l''arianisme', 'hérésie : le Fils aurait été créé', 'Pour l''arianisme, le Fils est créé et n''est pas de la même essence que le Père. Cette doctrine nie la divinité du Christ. Elle a survécu sous diverses formes.', '[{"text": "L''arianisme nie la divinité du Christ.", "translation": "Une erreur qui touche au cœur de la foi."}]'::jsonb, null, '{"id": "eg.d.c04_arianisme", "unitId": "eg.v.c04_arianisme", "word": "l''arianisme", "translation": "hérésie : le Fils aurait été créé", "partOfSpeech": "concept", "collection": "heresie", "explanation": "Pour l''arianisme, le Fils est créé et n''est pas de la même essence que le Père. Cette doctrine nie la divinité du Christ. Elle a survécu sous diverses formes.", "examples": [{"text": "L''arianisme nie la divinité du Christ.", "translation": "Une erreur qui touche au cœur de la foi."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_alexandre', 'eg', 'le pape Alexandre', '19e pape d''Alexandrie, adversaire d''Arius', 'Pape d''Alexandrie quand Arius enseigne. Il tente de le ramener à la raison, le fait condamner par un synode, puis préside le concile de Nicée, selon la tradition copte.', '[{"text": "Le pape Alexandre affronte Arius.", "translation": "Il défend la foi reçue du Seigneur."}]'::jsonb, null, '{"id": "eg.d.c04_alexandre", "unitId": "eg.v.c04_alexandre", "word": "le pape Alexandre", "translation": "19e pape d''Alexandrie, adversaire d''Arius", "partOfSpeech": "person", "collection": "pape", "explanation": "Pape d''Alexandrie quand Arius enseigne. Il tente de le ramener à la raison, le fait condamner par un synode, puis préside le concile de Nicée, selon la tradition copte.", "examples": [{"text": "Le pape Alexandre affronte Arius.", "translation": "Il défend la foi reçue du Seigneur."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_eusebe_nicomedie', 'eg', 'Eusèbe de Nicomédie', 'évêque puissant, grand protecteur d''Arius', 'Évêque proche de la cour impériale, il adopte les idées d''Arius et devient son grand protecteur.', '[{"text": "Eusèbe de Nicomédie soutient Arius.", "translation": "Sans lui, Arius n''aurait pas eu tant d''écho."}]'::jsonb, null, '{"id": "eg.d.c04_eusebe_nicomedie", "unitId": "eg.v.c04_eusebe_nicomedie", "word": "Eusèbe de Nicomédie", "translation": "évêque puissant, grand protecteur d''Arius", "partOfSpeech": "person", "collection": "heresie", "explanation": "Évêque proche de la cour impériale, il adopte les idées d''Arius et devient son grand protecteur.", "examples": [{"text": "Eusèbe de Nicomédie soutient Arius.", "translation": "Sans lui, Arius n''aurait pas eu tant d''écho."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_divinite_du_christ', 'eg', 'la divinité du Christ', 'vérité centrale : Jésus est Dieu', 'L''Église croit que le Christ est vrai Dieu et vrai homme. Sans sa divinité, il ne pourrait pas sauver l''homme : seul Dieu peut le faire.', '[{"text": "Arius nie la divinité du Christ.", "translation": "Tout le salut repose sur ce point."}]'::jsonb, null, '{"id": "eg.d.c04_divinite_du_christ", "unitId": "eg.v.c04_divinite_du_christ", "word": "la divinité du Christ", "translation": "vérité centrale : Jésus est Dieu", "partOfSpeech": "concept", "collection": "notion", "explanation": "L''Église croit que le Christ est vrai Dieu et vrai homme. Sans sa divinité, il ne pourrait pas sauver l''homme : seul Dieu peut le faire.", "examples": [{"text": "Arius nie la divinité du Christ.", "translation": "Tout le salut repose sur ce point."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_homoousios', 'eg', 'homoousios', 'mot grec : de même substance que le Père', 'Mot-clé de Nicée : le Fils est consubstantiel au Père, c''est-à-dire de même substance. Les ariens refusent ce mot.', '[{"text": "Le Fils est homoousios au Père.", "translation": "Un seul mot pour dire : le Fils est Dieu comme le Père."}]'::jsonb, null, '{"id": "eg.d.c04_homoousios", "unitId": "eg.v.c04_homoousios", "word": "homoousios", "translation": "mot grec : de même substance que le Père", "partOfSpeech": "concept", "collection": "notion", "explanation": "Mot-clé de Nicée : le Fils est consubstantiel au Père, c''est-à-dire de même substance. Les ariens refusent ce mot.", "examples": [{"text": "Le Fils est homoousios au Père.", "translation": "Un seul mot pour dire : le Fils est Dieu comme le Père."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_semi_arianisme', 'eg', 'le semi-arianisme', 'position du milieu : le Fils aurait une substance semblable', 'Les semi-ariens disent que le Christ a une substance semblable (homoiousios) à celle du Père, mais pas la même. Le cours copte associe cette position à Eusèbe de Césarée.', '[{"text": "Le semi-arianisme est une voie du milieu.", "translation": "« Semblable » ne suffit pas : il faut « même »."}]'::jsonb, null, '{"id": "eg.d.c04_semi_arianisme", "unitId": "eg.v.c04_semi_arianisme", "word": "le semi-arianisme", "translation": "position du milieu : le Fils aurait une substance semblable", "partOfSpeech": "concept", "collection": "heresie", "explanation": "Les semi-ariens disent que le Christ a une substance semblable (homoiousios) à celle du Père, mais pas la même. Le cours copte associe cette position à Eusèbe de Césarée.", "examples": [{"text": "Le semi-arianisme est une voie du milieu.", "translation": "« Semblable » ne suffit pas : il faut « même »."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_concile_de_nicee', 'eg', 'le concile de Nicée', 'premier concile œcuménique (325), contre l''arianisme', 'Convoqué par Constantin, il réunit selon la tradition 318 évêques, condamne Arius, définit le Fils comme homoousios et établit le credo et vingt canons.', '[{"text": "Le concile de Nicée a lieu en 325.", "translation": "Le premier grand rendez-vous de toute l''Église."}]'::jsonb, null, '{"id": "eg.d.c04_concile_de_nicee", "unitId": "eg.v.c04_concile_de_nicee", "word": "le concile de Nicée", "translation": "premier concile œcuménique (325), contre l''arianisme", "partOfSpeech": "event", "collection": "concile", "explanation": "Convoqué par Constantin, il réunit selon la tradition 318 évêques, condamne Arius, définit le Fils comme homoousios et établit le credo et vingt canons.", "examples": [{"text": "Le concile de Nicée a lieu en 325.", "translation": "Le premier grand rendez-vous de toute l''Église."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_concile_oecumenique', 'eg', 'le concile œcuménique', 'assemblée d''évêques de toute l''Église', 'Œcuménique veut dire « de toute la terre habitée » : les évêques de toute l''Église sont invités à décider ensemble. Nicée est le premier.', '[{"text": "Nicée est le premier concile œcuménique.", "translation": "Un concile pour toute l''Église, pas pour une seule ville."}]'::jsonb, null, '{"id": "eg.d.c04_concile_oecumenique", "unitId": "eg.v.c04_concile_oecumenique", "word": "le concile œcuménique", "translation": "assemblée d''évêques de toute l''Église", "partOfSpeech": "concept", "collection": "notion", "explanation": "Œcuménique veut dire « de toute la terre habitée » : les évêques de toute l''Église sont invités à décider ensemble. Nicée est le premier.", "examples": [{"text": "Nicée est le premier concile œcuménique.", "translation": "Un concile pour toute l''Église, pas pour une seule ville."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_nicee', 'eg', 'Nicée', 'ville de l''actuelle Turquie, où s''est tenu le premier concile', 'Ville proche de Nicomédie, aujourd''hui İznik en Turquie. Elle donne son nom au concile de 325 et au credo.', '[{"text": "Nicée accueille les évêques en 325.", "translation": "Une petite ville devenue célèbre dans toute l''Église."}]'::jsonb, null, '{"id": "eg.d.c04_nicee", "unitId": "eg.v.c04_nicee", "word": "Nicée", "translation": "ville de l''actuelle Turquie, où s''est tenu le premier concile", "partOfSpeech": "place", "collection": "lieu", "explanation": "Ville proche de Nicomédie, aujourd''hui İznik en Turquie. Elle donne son nom au concile de 325 et au credo.", "examples": [{"text": "Nicée accueille les évêques en 325.", "translation": "Une petite ville devenue célèbre dans toute l''Église."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_eusebe_cesaree', 'eg', 'Eusèbe de Césarée', 'évêque historien, ami de Constantin', 'Évêque de Césarée en Palestine, il est le père de l''histoire ecclésiastique : ses écrits sont essentiels pour connaître les premiers siècles. Le cours copte le range du côté semi-arien.', '[{"text": "Eusèbe de Césarée raconte les martyrs.", "translation": "Un historien précieux, mais pas un héros de la foi de Nicée."}]'::jsonb, null, '{"id": "eg.d.c04_eusebe_cesaree", "unitId": "eg.v.c04_eusebe_cesaree", "word": "Eusèbe de Césarée", "translation": "évêque historien, ami de Constantin", "partOfSpeech": "person", "collection": "pere", "explanation": "Évêque de Césarée en Palestine, il est le père de l''histoire ecclésiastique : ses écrits sont essentiels pour connaître les premiers siècles. Le cours copte le range du côté semi-arien.", "examples": [{"text": "Eusèbe de Césarée raconte les martyrs.", "translation": "Un historien précieux, mais pas un héros de la foi de Nicée."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_credo_de_nicee', 'eg', 'le credo de Nicée', 'texte de foi de 325 : le Fils est de même substance que le Père', 'Il parle du Père et du Fils et finit par « et en l''Esprit Saint ». Complété en 381, il devient le Credo récité à la messe.', '[{"text": "Le credo de Nicée est rédigé en 325.", "translation": "Le cœur de notre Credo."}]'::jsonb, null, '{"id": "eg.d.c04_credo_de_nicee", "unitId": "eg.v.c04_credo_de_nicee", "word": "le credo de Nicée", "translation": "texte de foi de 325 : le Fils est de même substance que le Père", "partOfSpeech": "work", "collection": "livre", "explanation": "Il parle du Père et du Fils et finit par « et en l''Esprit Saint ». Complété en 381, il devient le Credo récité à la messe.", "examples": [{"text": "Le credo de Nicée est rédigé en 325.", "translation": "Le cœur de notre Credo."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_anathemes', 'eg', 'les anathèmes', 'condamnations jointes au credo de Nicée', 'Les anathèmes sont des condamnations : ceux de Nicée visent l''enseignement d''Arius. Trois évêques signent le credo mais refusent d''abord les anathèmes.', '[{"text": "Les anathèmes condamnent l''enseignement d''Arius.", "translation": "Le credo affirme, les anathèmes écartent l''erreur."}]'::jsonb, null, '{"id": "eg.d.c04_anathemes", "unitId": "eg.v.c04_anathemes", "word": "les anathèmes", "translation": "condamnations jointes au credo de Nicée", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les anathèmes sont des condamnations : ceux de Nicée visent l''enseignement d''Arius. Trois évêques signent le credo mais refusent d''abord les anathèmes.", "examples": [{"text": "Les anathèmes condamnent l''enseignement d''Arius.", "translation": "Le credo affirme, les anathèmes écartent l''erreur."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_les_318', 'eg', 'les 318 évêques', 'les évêques de Nicée, selon la tradition', 'La tradition retient le nombre de 318 pour les évêques de Nicée. On les appelle aussi les 318 Pères.', '[{"text": "318 évêques se réunissent à Nicée.", "translation": "Un chiffre à retenir avec le nom de Nicée."}]'::jsonb, null, '{"id": "eg.d.c04_les_318", "unitId": "eg.v.c04_les_318", "word": "les 318 évêques", "translation": "les évêques de Nicée, selon la tradition", "partOfSpeech": "concept", "collection": "notion", "explanation": "La tradition retient le nombre de 318 pour les évêques de Nicée. On les appelle aussi les 318 Pères.", "examples": [{"text": "318 évêques se réunissent à Nicée.", "translation": "Un chiffre à retenir avec le nom de Nicée."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_athanase', 'eg', 'saint Athanase', 'XXe pape d''Alexandrie (vers 298-373), défenseur de la foi', 'Diacre du pape Alexandre à Nicée, puis patriarche vers 328, il combat l''arianisme toute sa vie et subit plusieurs exils. L''Église copte le fête comme un grand père de la foi.', '[{"text": "Athanase naît vers 298.", "translation": "Le héros de la foi de Nicée."}]'::jsonb, null, '{"id": "eg.d.c04_athanase", "unitId": "eg.v.c04_athanase", "word": "saint Athanase", "translation": "XXe pape d''Alexandrie (vers 298-373), défenseur de la foi", "partOfSpeech": "person", "collection": "pere", "explanation": "Diacre du pape Alexandre à Nicée, puis patriarche vers 328, il combat l''arianisme toute sa vie et subit plusieurs exils. L''Église copte le fête comme un grand père de la foi.", "examples": [{"text": "Athanase naît vers 298.", "translation": "Le héros de la foi de Nicée."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_sur_incarnation', 'eg', '« Sur l''incarnation du Verbe »', 'livre de jeunesse d''Athanase', 'Écrit avant ses vingt ans, il explique que le Christ est parfaitement Dieu et parfaitement homme, sans division de sa personne. C''est déjà sa réponse à l''arianisme.', '[{"text": "Athanase l''écrit très jeune.", "translation": "Un petit livre qui annonce toute sa vie."}]'::jsonb, null, '{"id": "eg.d.c04_sur_incarnation", "unitId": "eg.v.c04_sur_incarnation", "word": "« Sur l''incarnation du Verbe »", "translation": "livre de jeunesse d''Athanase", "partOfSpeech": "work", "collection": "livre", "explanation": "Écrit avant ses vingt ans, il explique que le Christ est parfaitement Dieu et parfaitement homme, sans division de sa personne. C''est déjà sa réponse à l''arianisme.", "examples": [{"text": "Athanase l''écrit très jeune.", "translation": "Un petit livre qui annonce toute sa vie."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_defenseur_de_la_foi', 'eg', 'le défenseur de la foi', 'surnom d''Athanase', 'L''Église appelle Athanase le défenseur de la foi : on dit que, sans lui, le monde entier aurait suivi Arius.', '[{"text": "Athanase est le défenseur de la foi.", "translation": "Un titre gagné par sa fermeté."}]'::jsonb, null, '{"id": "eg.d.c04_defenseur_de_la_foi", "unitId": "eg.v.c04_defenseur_de_la_foi", "word": "le défenseur de la foi", "translation": "surnom d''Athanase", "partOfSpeech": "concept", "collection": "notion", "explanation": "L''Église appelle Athanase le défenseur de la foi : on dit que, sans lui, le monde entier aurait suivi Arius.", "examples": [{"text": "Athanase est le défenseur de la foi.", "translation": "Un titre gagné par sa fermeté."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_exils_athanase', 'eg', 'les exils d''Athanase', 'expulsions répétées d''Athanase par les ariens', 'Plusieurs fois, environ six selon le cours, Athanase est chassé de son siège. Il se réfugie en Occident ou chez les moines du désert, puis revient.', '[{"text": "Athanase est exilé plusieurs fois.", "translation": "L''exil ne le fait pas changer d''avis."}]'::jsonb, null, '{"id": "eg.d.c04_exils_athanase", "unitId": "eg.v.c04_exils_athanase", "word": "les exils d''Athanase", "translation": "expulsions répétées d''Athanase par les ariens", "partOfSpeech": "event", "collection": "date", "explanation": "Plusieurs fois, environ six selon le cours, Athanase est chassé de son siège. Il se réfugie en Occident ou chez les moines du désert, puis revient.", "examples": [{"text": "Athanase est exilé plusieurs fois.", "translation": "L''exil ne le fait pas changer d''avis."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_livres_27', 'eg', 'les 27 livres du Nouveau Testament', 'liste donnée par Athanase en 367', 'En 367, Athanase publie une lettre qui donne la liste des 27 livres du Nouveau Testament. Le synode de Carthage la confirme en 397. Le canon est la liste officielle.', '[{"text": "Athanase donne la liste des 27 livres en 367.", "translation": "La Bible du Nouveau Testament fixée."}]'::jsonb, null, '{"id": "eg.d.c04_livres_27", "unitId": "eg.v.c04_livres_27", "word": "les 27 livres du Nouveau Testament", "translation": "liste donnée par Athanase en 367", "partOfSpeech": "work", "collection": "livre", "explanation": "En 367, Athanase publie une lettre qui donne la liste des 27 livres du Nouveau Testament. Le synode de Carthage la confirme en 397. Le canon est la liste officielle.", "examples": [{"text": "Athanase donne la liste des 27 livres en 367.", "translation": "La Bible du Nouveau Testament fixée."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_vie_antoine', 'eg', 'La Vie d''Antoine', 'livre d''Athanase sur saint Antoine', 'Athanase y raconte la vie de saint Antoine. Envoyé à Rome, le livre fait connaître le monachisme à l''Occident.', '[{"text": "La Vie d''Antoine est un livre d''Athanase.", "translation": "Le portrait écrit du père des moines."}]'::jsonb, null, '{"id": "eg.d.c04_vie_antoine", "unitId": "eg.v.c04_vie_antoine", "word": "La Vie d''Antoine", "translation": "livre d''Athanase sur saint Antoine", "partOfSpeech": "work", "collection": "livre", "explanation": "Athanase y raconte la vie de saint Antoine. Envoyé à Rome, le livre fait connaître le monachisme à l''Occident.", "examples": [{"text": "La Vie d''Antoine est un livre d''Athanase.", "translation": "Le portrait écrit du père des moines."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_monachisme', 'eg', 'le monachisme', 'vie de solitude, de prière et de jeûne, née en Égypte', 'Le moine consacre sa vie à chercher Dieu : prière, jeûne, solitude. Trois principes : pauvreté, obéissance, chasteté. Cette vie commence en Égypte.', '[{"text": "Le monachisme commence en Égypte.", "translation": "Une vie « angélique » loin de la gloire."}]'::jsonb, null, '{"id": "eg.d.c04_monachisme", "unitId": "eg.v.c04_monachisme", "word": "le monachisme", "translation": "vie de solitude, de prière et de jeûne, née en Égypte", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le moine consacre sa vie à chercher Dieu : prière, jeûne, solitude. Trois principes : pauvreté, obéissance, chasteté. Cette vie commence en Égypte.", "examples": [{"text": "Le monachisme commence en Égypte.", "translation": "Une vie « angélique » loin de la gloire."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_saint_antoine', 'eg', 'saint Antoine le Grand', 'père des moines (251-356)', 'Copte de Haute-Égypte, né en 251 et mort en 356, il quitte tout pour vivre seul au désert. Il est le premier moine du monde, et Athanase raconte sa vie.', '[{"text": "Antoine est né en 251.", "translation": "Plus d''un siècle de vie, presque toute au désert."}]'::jsonb, null, '{"id": "eg.d.c04_saint_antoine", "unitId": "eg.v.c04_saint_antoine", "word": "saint Antoine le Grand", "translation": "père des moines (251-356)", "partOfSpeech": "person", "collection": "saint", "explanation": "Copte de Haute-Égypte, né en 251 et mort en 356, il quitte tout pour vivre seul au désert. Il est le premier moine du monde, et Athanase raconte sa vie.", "examples": [{"text": "Antoine est né en 251.", "translation": "Plus d''un siècle de vie, presque toute au désert."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_saint_paul_ermite', 'eg', 'saint Paul l''ermite', 'premier ermite, mort vers 342', 'La tradition le tient pour le premier ermite du désert d''Égypte : il fuit les villes et reste seul avec Dieu. Il meurt vers 342.', '[{"text": "Paul vit seul au désert.", "translation": "Un ermite vit seul, pour Dieu seul."}]'::jsonb, null, '{"id": "eg.d.c04_saint_paul_ermite", "unitId": "eg.v.c04_saint_paul_ermite", "word": "saint Paul l''ermite", "translation": "premier ermite, mort vers 342", "partOfSpeech": "person", "collection": "saint", "explanation": "La tradition le tient pour le premier ermite du désert d''Égypte : il fuit les villes et reste seul avec Dieu. Il meurt vers 342.", "examples": [{"text": "Paul vit seul au désert.", "translation": "Un ermite vit seul, pour Dieu seul."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_saint_pacome', 'eg', 'saint Pacôme', 'fondateur des premiers monastères communautaires', 'Il fonde en Haute-Égypte les premiers monastères cénobitiques et en écrit les premières règles. En Europe, des ordres suivent encore aujourd''hui ces règles.', '[{"text": "Pacôme vit en Haute-Égypte.", "translation": "Il transforme des ermites en communautés."}]'::jsonb, null, '{"id": "eg.d.c04_saint_pacome", "unitId": "eg.v.c04_saint_pacome", "word": "saint Pacôme", "translation": "fondateur des premiers monastères communautaires", "partOfSpeech": "person", "collection": "saint", "explanation": "Il fonde en Haute-Égypte les premiers monastères cénobitiques et en écrit les premières règles. En Europe, des ordres suivent encore aujourd''hui ces règles.", "examples": [{"text": "Pacôme vit en Haute-Égypte.", "translation": "Il transforme des ermites en communautés."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_vie_cenobitique', 'eg', 'la vie cénobitique', 'vie des moines en communauté', 'Cénobitique veut dire vie en communauté, par opposition à la vie d''ermite, solitaire. Les moines prient, travaillent et mangent ensemble.', '[{"text": "Pacôme invente la vie cénobitique.", "translation": "Le contraire de la vie d''ermite."}]'::jsonb, null, '{"id": "eg.d.c04_vie_cenobitique", "unitId": "eg.v.c04_vie_cenobitique", "word": "la vie cénobitique", "translation": "vie des moines en communauté", "partOfSpeech": "concept", "collection": "notion", "explanation": "Cénobitique veut dire vie en communauté, par opposition à la vie d''ermite, solitaire. Les moines prient, travaillent et mangent ensemble.", "examples": [{"text": "Pacôme invente la vie cénobitique.", "translation": "Le contraire de la vie d''ermite."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_saint_macaire', 'eg', 'saint Macaire le Grand', 'père de Scété (mort en 391)', 'Moine du désert de Scété, il a de nombreux disciples. Il meurt en 391.', '[{"text": "Macaire a de nombreux disciples.", "translation": "Autour de lui, le désert se peuple."}]'::jsonb, null, '{"id": "eg.d.c04_saint_macaire", "unitId": "eg.v.c04_saint_macaire", "word": "saint Macaire le Grand", "translation": "père de Scété (mort en 391)", "partOfSpeech": "person", "collection": "saint", "explanation": "Moine du désert de Scété, il a de nombreux disciples. Il meurt en 391.", "examples": [{"text": "Macaire a de nombreux disciples.", "translation": "Autour de lui, le désert se peuple."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_scete', 'eg', 'Scété', 'désert de saint Macaire', 'Désert d''Égypte où saint Macaire rassemble des moines. Il accueille encore des monastères aujourd''hui.', '[{"text": "Macaire vit à Scété.", "translation": "Un des lieux les plus sacrés de l''Église copte."}]'::jsonb, null, '{"id": "eg.d.c04_scete", "unitId": "eg.v.c04_scete", "word": "Scété", "translation": "désert de saint Macaire", "partOfSpeech": "place", "collection": "lieu", "explanation": "Désert d''Égypte où saint Macaire rassemble des moines. Il accueille encore des monastères aujourd''hui.", "examples": [{"text": "Macaire vit à Scété.", "translation": "Un des lieux les plus sacrés de l''Église copte."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_frumentius', 'eg', 'Frumentius', 'premier évêque d''Éthiopie, ordonné par Athanase', 'Athanase l''ordonne premier évêque d''Éthiopie vers 341. L''Église éthiopienne dépendra de celle d''Alexandrie pendant des siècles. La tradition éthiopienne l''appelle Abba Salama.', '[{"text": "Frumentius est évêque d''Éthiopie.", "translation": "Un seul témoin fidèle fait naître une Église."}]'::jsonb, null, '{"id": "eg.d.c04_frumentius", "unitId": "eg.v.c04_frumentius", "word": "Frumentius", "translation": "premier évêque d''Éthiopie, ordonné par Athanase", "partOfSpeech": "person", "collection": "saint", "explanation": "Athanase l''ordonne premier évêque d''Éthiopie vers 341. L''Église éthiopienne dépendra de celle d''Alexandrie pendant des siècles. La tradition éthiopienne l''appelle Abba Salama.", "examples": [{"text": "Frumentius est évêque d''Éthiopie.", "translation": "Un seul témoin fidèle fait naître une Église."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_ethiopie', 'eg', 'l''Éthiopie', 'pays d''Afrique dont l''Église est fille d''Alexandrie', 'Royaume chrétien dès le IVe siècle, avec Axoum pour capitale. Son Église reçoit ses évêques d''Alexandrie pendant des siècles.', '[{"text": "L''Éthiopie dépend d''Alexandrie.", "translation": "Une Église sœur de l''Église copte."}]'::jsonb, null, '{"id": "eg.d.c04_ethiopie", "unitId": "eg.v.c04_ethiopie", "word": "l''Éthiopie", "translation": "pays d''Afrique dont l''Église est fille d''Alexandrie", "partOfSpeech": "place", "collection": "lieu", "explanation": "Royaume chrétien dès le IVe siècle, avec Axoum pour capitale. Son Église reçoit ses évêques d''Alexandrie pendant des siècles.", "examples": [{"text": "L''Éthiopie dépend d''Alexandrie.", "translation": "Une Église sœur de l''Église copte."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_apollinaire', 'eg', 'Apollinaire de Laodicée', 'évêque qui retire au Christ son âme humaine', 'Évêque de Laodicée, il enseigne que le Fils a pris un corps humain mais pas d''âme humaine. Athanase l''excommunie en 362, puis le concile de 381.', '[{"text": "Apollinaire est évêque de Laodicée.", "translation": "Un Christ sans âme humaine ne sauverait pas l''homme entier."}]'::jsonb, null, '{"id": "eg.d.c04_apollinaire", "unitId": "eg.v.c04_apollinaire", "word": "Apollinaire de Laodicée", "translation": "évêque qui retire au Christ son âme humaine", "partOfSpeech": "person", "collection": "heresie", "explanation": "Évêque de Laodicée, il enseigne que le Fils a pris un corps humain mais pas d''âme humaine. Athanase l''excommunie en 362, puis le concile de 381.", "examples": [{"text": "Apollinaire est évêque de Laodicée.", "translation": "Un Christ sans âme humaine ne sauverait pas l''homme entier."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_macedonius', 'eg', 'Macédonius', 'évêque de Constantinople : l''Esprit Saint serait créé', 'Évêque de Constantinople, il enseigne que le Saint-Esprit est une créature. Le pape Timothée le presse de revenir à la vraie foi ; le concile de 381 condamne son enseignement.', '[{"text": "Macédonius nie la divinité de l''Esprit Saint.", "translation": "Pour l''Esprit, la même erreur qu''Arius pour le Fils."}]'::jsonb, null, '{"id": "eg.d.c04_macedonius", "unitId": "eg.v.c04_macedonius", "word": "Macédonius", "translation": "évêque de Constantinople : l''Esprit Saint serait créé", "partOfSpeech": "person", "collection": "heresie", "explanation": "Évêque de Constantinople, il enseigne que le Saint-Esprit est une créature. Le pape Timothée le presse de revenir à la vraie foi ; le concile de 381 condamne son enseignement.", "examples": [{"text": "Macédonius nie la divinité de l''Esprit Saint.", "translation": "Pour l''Esprit, la même erreur qu''Arius pour le Fils."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_theodose', 'eg', 'Théodose Ier', 'empereur (379-395), qui convoque le concile de 381', 'Empereur dès 379, il proclame le christianisme religion de l''État en 380 et convoque le concile de Constantinople en 381.', '[{"text": "Théodose Ier convoque le concile.", "translation": "Pour Constantinople, ce que Constantin fut pour Nicée."}]'::jsonb, null, '{"id": "eg.d.c04_theodose", "unitId": "eg.v.c04_theodose", "word": "Théodose Ier", "translation": "empereur (379-395), qui convoque le concile de 381", "partOfSpeech": "person", "collection": "notion", "explanation": "Empereur dès 379, il proclame le christianisme religion de l''État en 380 et convoque le concile de Constantinople en 381.", "examples": [{"text": "Théodose Ier convoque le concile.", "translation": "Pour Constantinople, ce que Constantin fut pour Nicée."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_religion_etat_380', 'eg', '380 : religion de l''État', 'année où le christianisme devient religion de l''État', 'En 380, le christianisme est proclamé religion de l''État dans l''empire romain, sous Théodose Ier.', '[{"text": "En 380, le christianisme devient religion de l''État.", "translation": "De la persécution de 303 à la religion d''État, en moins de quatre-vingts ans."}]'::jsonb, null, '{"id": "eg.d.c04_religion_etat_380", "unitId": "eg.v.c04_religion_etat_380", "word": "380 : religion de l''État", "translation": "année où le christianisme devient religion de l''État", "partOfSpeech": "event", "collection": "date", "explanation": "En 380, le christianisme est proclamé religion de l''État dans l''empire romain, sous Théodose Ier.", "examples": [{"text": "En 380, le christianisme devient religion de l''État.", "translation": "De la persécution de 303 à la religion d''État, en moins de quatre-vingts ans."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_concile_de_constantinople', 'eg', 'le concile de Constantinople', 'deuxième concile œcuménique (381), contre Apollinaire et Macédonius', 'Convoqué par Théodose Ier, il réunit 150 évêques, excommunie Apollinaire et Macédonius, complète le credo et établit sept canons.', '[{"text": "Le concile de Constantinople a lieu en 381.", "translation": "Le deuxième grand rendez-vous de toute l''Église."}]'::jsonb, null, '{"id": "eg.d.c04_concile_de_constantinople", "unitId": "eg.v.c04_concile_de_constantinople", "word": "le concile de Constantinople", "translation": "deuxième concile œcuménique (381), contre Apollinaire et Macédonius", "partOfSpeech": "event", "collection": "concile", "explanation": "Convoqué par Théodose Ier, il réunit 150 évêques, excommunie Apollinaire et Macédonius, complète le credo et établit sept canons.", "examples": [{"text": "Le concile de Constantinople a lieu en 381.", "translation": "Le deuxième grand rendez-vous de toute l''Église."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_credo_nicee_constantinople', 'eg', 'le Credo de Nicée-Constantinople', 'credo complété en 381, récité à la messe', 'Il reprend le credo de Nicée, développe l''article sur l''Esprit Saint et ajoute toute la suite : l''Église, le baptême, la résurrection, la vie éternelle.', '[{"text": "Le Credo est complété en 381.", "translation": "Celui que tu récites à la messe."}]'::jsonb, null, '{"id": "eg.d.c04_credo_nicee_constantinople", "unitId": "eg.v.c04_credo_nicee_constantinople", "word": "le Credo de Nicée-Constantinople", "translation": "credo complété en 381, récité à la messe", "partOfSpeech": "work", "collection": "livre", "explanation": "Il reprend le credo de Nicée, développe l''article sur l''Esprit Saint et ajoute toute la suite : l''Église, le baptême, la résurrection, la vie éternelle.", "examples": [{"text": "Le Credo est complété en 381.", "translation": "Celui que tu récites à la messe."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_pape_timothee', 'eg', 'le pape Timothée', 'pape d''Alexandrie présent au concile de 381', 'Le pape d''Alexandrie participe au concile et, selon le cours copte, débat avec Apollinaire et Macédonius.', '[{"text": "Timothée d''Alexandrie est au concile.", "translation": "Alexandrie est de nouveau en première ligne."}]'::jsonb, null, '{"id": "eg.d.c04_pape_timothee", "unitId": "eg.v.c04_pape_timothee", "word": "le pape Timothée", "translation": "pape d''Alexandrie présent au concile de 381", "partOfSpeech": "person", "collection": "pape", "explanation": "Le pape d''Alexandrie participe au concile et, selon le cours copte, débat avec Apollinaire et Macédonius.", "examples": [{"text": "Timothée d''Alexandrie est au concile.", "translation": "Alexandrie est de nouveau en première ligne."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_gregoire_theologien', 'eg', 'saint Grégoire le Théologien', 'évêque de Nazianze (mort en 390)', 'Ami de saint Basile, il défend la foi de Nicée, est évêque de Constantinople pour une courte durée et meurt en 390. On lui attribue la liturgie grégorienne.', '[{"text": "Grégoire est évêque de Nazianze.", "translation": "Sa liturgie est une des trois liturgies coptes."}]'::jsonb, null, '{"id": "eg.d.c04_gregoire_theologien", "unitId": "eg.v.c04_gregoire_theologien", "word": "saint Grégoire le Théologien", "translation": "évêque de Nazianze (mort en 390)", "partOfSpeech": "person", "collection": "pere", "explanation": "Ami de saint Basile, il défend la foi de Nicée, est évêque de Constantinople pour une courte durée et meurt en 390. On lui attribue la liturgie grégorienne.", "examples": [{"text": "Grégoire est évêque de Nazianze.", "translation": "Sa liturgie est une des trois liturgies coptes."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_saint_basile', 'eg', 'saint Basile le Grand', 'évêque de Césarée de Cappadoce (mort en 379)', 'Ami de Grégoire de Nazianze, il est l''auteur de la liturgie de saint Basile, la plus célébrée dans l''Église copte.', '[{"text": "Basile meurt en 379.", "translation": "Sa voix résonne à la messe."}]'::jsonb, null, '{"id": "eg.d.c04_saint_basile", "unitId": "eg.v.c04_saint_basile", "word": "saint Basile le Grand", "translation": "évêque de Césarée de Cappadoce (mort en 379)", "partOfSpeech": "person", "collection": "pere", "explanation": "Ami de Grégoire de Nazianze, il est l''auteur de la liturgie de saint Basile, la plus célébrée dans l''Église copte.", "examples": [{"text": "Basile meurt en 379.", "translation": "Sa voix résonne à la messe."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c04_trois_liturgies', 'eg', 'les trois liturgies', 'liturgies de saint Basile, de saint Grégoire et de saint Cyrille', 'Les trois liturgies de l''Église copte portent le nom de saint Basile le Grand, saint Grégoire le Théologien et saint Cyrille. Les deux premiers sont des Pères du IVe siècle.', '[{"text": "On célèbre la liturgie de saint Basile.", "translation": "À la messe, on entend la voix des Pères des conciles."}]'::jsonb, null, '{"id": "eg.d.c04_trois_liturgies", "unitId": "eg.v.c04_trois_liturgies", "word": "les trois liturgies", "translation": "liturgies de saint Basile, de saint Grégoire et de saint Cyrille", "partOfSpeech": "concept", "collection": "priere", "explanation": "Les trois liturgies de l''Église copte portent le nom de saint Basile le Grand, saint Grégoire le Théologien et saint Cyrille. Les deux premiers sont des Pères du IVe siècle.", "examples": [{"text": "On célèbre la liturgie de saint Basile.", "translation": "À la messe, on entend la voix des Pères des conciles."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_patriarche', 'eg', 'le patriarche', 'évêque d''un grand siège, appelé pape à Rome et à Alexandrie', 'Le patriarche est l''évêque d''un des grands sièges de l''Église. À Rome et à Alexandrie, on l''appelle aussi le pape. Le pape copte est donc le patriarche d''Alexandrie.', '[{"text": "Cyrille est le patriarche d''Alexandrie.", "translation": "Il dirige l''un des cinq grands sièges."}]'::jsonb, null, '{"id": "eg.d.c05_patriarche", "unitId": "eg.v.c05_patriarche", "word": "le patriarche", "translation": "évêque d''un grand siège, appelé pape à Rome et à Alexandrie", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le patriarche est l''évêque d''un des grands sièges de l''Église. À Rome et à Alexandrie, on l''appelle aussi le pape. Le pape copte est donc le patriarche d''Alexandrie.", "examples": [{"text": "Cyrille est le patriarche d''Alexandrie.", "translation": "Il dirige l''un des cinq grands sièges."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_nouvelle_rome', 'eg', 'la nouvelle Rome', 'surnom de Constantinople, la capitale de l''empereur', 'Constantinople, fondée en 330 par Constantin, reçoit ce surnom car l''empereur y siège comme à Rome autrefois. Sa grandeur vient de la capitale, non d''un apôtre.', '[{"text": "Constantinople est la nouvelle Rome.", "translation": "Un siège jeune, mais très proche du pouvoir."}]'::jsonb, null, '{"id": "eg.d.c05_nouvelle_rome", "unitId": "eg.v.c05_nouvelle_rome", "word": "la nouvelle Rome", "translation": "surnom de Constantinople, la capitale de l''empereur", "partOfSpeech": "place", "collection": "lieu", "explanation": "Constantinople, fondée en 330 par Constantin, reçoit ce surnom car l''empereur y siège comme à Rome autrefois. Sa grandeur vient de la capitale, non d''un apôtre.", "examples": [{"text": "Constantinople est la nouvelle Rome.", "translation": "Un siège jeune, mais très proche du pouvoir."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_trois_premiers_conciles', 'eg', 'les trois premiers conciles', 'Nicée (325), Constantinople (381), Éphèse (431)', 'Ce sont les trois conciles œcuméniques que l''Église copte reconnaît : Nicée, Constantinople et Éphèse. Elle n''en reconnaît pas d''autres.', '[{"text": "325, 381, 431 : les trois premiers conciles.", "translation": "Les trois dates à connaître par cœur."}]'::jsonb, null, '{"id": "eg.d.c05_trois_premiers_conciles", "unitId": "eg.v.c05_trois_premiers_conciles", "word": "les trois premiers conciles", "translation": "Nicée (325), Constantinople (381), Éphèse (431)", "partOfSpeech": "event", "collection": "concile", "explanation": "Ce sont les trois conciles œcuméniques que l''Église copte reconnaît : Nicée, Constantinople et Éphèse. Elle n''en reconnaît pas d''autres.", "examples": [{"text": "325, 381, 431 : les trois premiers conciles.", "translation": "Les trois dates à connaître par cœur."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_canon_3_de_381', 'eg', 'le canon 3 de 381', 'règle qui place Constantinople juste après Rome', 'Voté à Constantinople en 381, ce canon donne à l''évêque de la nouvelle Rome la deuxième place d''honneur. Alexandrie le refuse : le rang d''une Église ne doit pas dépendre de la capitale.', '[{"text": "Alexandrie refuse le canon 3 de 381.", "translation": "Les germes du conflit de 451 sont déjà là."}]'::jsonb, null, '{"id": "eg.d.c05_canon_3_de_381", "unitId": "eg.v.c05_canon_3_de_381", "word": "le canon 3 de 381", "translation": "règle qui place Constantinople juste après Rome", "partOfSpeech": "concept", "collection": "concile", "explanation": "Voté à Constantinople en 381, ce canon donne à l''évêque de la nouvelle Rome la deuxième place d''honneur. Alexandrie le refuse : le rang d''une Église ne doit pas dépendre de la capitale.", "examples": [{"text": "Alexandrie refuse le canon 3 de 381.", "translation": "Les germes du conflit de 451 sont déjà là."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_nestorius', 'eg', 'Nestorius', 'patriarche de Constantinople (428-431), condamné à Éphèse', 'Moine formé à Antioche et prédicateur célèbre, Nestorius devient patriarche de Constantinople en 428. Il refuse le titre Théotokos, et ses adversaires lui reprochent de séparer le Verbe de l''homme Jésus. Il est condamné à Éphèse en 431.', '[{"text": "Nestorius monte en chaire à Constantinople.", "translation": "Son sermon déclenche la crise."}]'::jsonb, null, '{"id": "eg.d.c05_nestorius", "unitId": "eg.v.c05_nestorius", "word": "Nestorius", "translation": "patriarche de Constantinople (428-431), condamné à Éphèse", "partOfSpeech": "person", "collection": "heresie", "explanation": "Moine formé à Antioche et prédicateur célèbre, Nestorius devient patriarche de Constantinople en 428. Il refuse le titre Théotokos, et ses adversaires lui reprochent de séparer le Verbe de l''homme Jésus. Il est condamné à Éphèse en 431.", "examples": [{"text": "Nestorius monte en chaire à Constantinople.", "translation": "Son sermon déclenche la crise."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_theotokos', 'eg', 'Théotokos', '« celle qui enfante Dieu » : titre de la Vierge Marie, mère de Dieu', 'Titre grec de la Vierge Marie : celle qui enfante Dieu. Il affirme que celui qu''elle enfante est Dieu le Verbe fait chair. Le concile d''Éphèse le confirme en 431, et l''Église copte le chante encore aujourd''hui.', '[{"text": "Marie est Théotokos.", "translation": "Celui qu''elle enfante est Dieu le Verbe."}]'::jsonb, null, '{"id": "eg.d.c05_theotokos", "unitId": "eg.v.c05_theotokos", "word": "Théotokos", "translation": "« celle qui enfante Dieu » : titre de la Vierge Marie, mère de Dieu", "partOfSpeech": "concept", "collection": "notion", "explanation": "Titre grec de la Vierge Marie : celle qui enfante Dieu. Il affirme que celui qu''elle enfante est Dieu le Verbe fait chair. Le concile d''Éphèse le confirme en 431, et l''Église copte le chante encore aujourd''hui.", "examples": [{"text": "Marie est Théotokos.", "translation": "Celui qu''elle enfante est Dieu le Verbe."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_christotokos', 'eg', 'Christotokos', '« mère du Christ » : titre préféré par Nestorius', 'Nestorius propose ce titre à la place de Théotokos. Il paraît prudent, mais ses adversaires y voient un danger : il laisse entendre que Marie n''est pas la mère de Dieu.', '[{"text": "Nestorius dit « Christotokos ».", "translation": "Mère du Christ, mais pas mère de Dieu."}]'::jsonb, null, '{"id": "eg.d.c05_christotokos", "unitId": "eg.v.c05_christotokos", "word": "Christotokos", "translation": "« mère du Christ » : titre préféré par Nestorius", "partOfSpeech": "concept", "collection": "notion", "explanation": "Nestorius propose ce titre à la place de Théotokos. Il paraît prudent, mais ses adversaires y voient un danger : il laisse entendre que Marie n''est pas la mère de Dieu.", "examples": [{"text": "Nestorius dit « Christotokos ».", "translation": "Mère du Christ, mais pas mère de Dieu."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_le_verbe', 'eg', 'le Verbe', 'le Fils de Dieu, éternel avec le Père', 'Le Verbe (Logos en grec) est le Fils de Dieu, éternel comme le Père. L''évangile de Jean commence par lui : « Au commencement était le Verbe ». C''est lui qui devient homme en Jésus.', '[{"text": "Au commencement était le Verbe.", "translation": "Jean parle du Fils de Dieu, avant sa naissance à Bethléem."}]'::jsonb, null, '{"id": "eg.d.c05_le_verbe", "unitId": "eg.v.c05_le_verbe", "word": "le Verbe", "translation": "le Fils de Dieu, éternel avec le Père", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le Verbe (Logos en grec) est le Fils de Dieu, éternel comme le Père. L''évangile de Jean commence par lui : « Au commencement était le Verbe ». C''est lui qui devient homme en Jésus.", "examples": [{"text": "Au commencement était le Verbe.", "translation": "Jean parle du Fils de Dieu, avant sa naissance à Bethléem."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_incarnation', 'eg', 'l''incarnation', 'le moment où le Verbe de Dieu se fait homme en Marie', 'Incarnation vient de « chair ». Le Fils de Dieu devient vraiment homme en Marie, sans cesser d''être Dieu. C''est le cœur du mystère de Noël.', '[{"text": "Le Verbe s''est fait chair : voilà l''incarnation.", "translation": "Dieu entre dans l''histoire humaine."}]'::jsonb, null, '{"id": "eg.d.c05_incarnation", "unitId": "eg.v.c05_incarnation", "word": "l''incarnation", "translation": "le moment où le Verbe de Dieu se fait homme en Marie", "partOfSpeech": "event", "collection": "notion", "explanation": "Incarnation vient de « chair ». Le Fils de Dieu devient vraiment homme en Marie, sans cesser d''être Dieu. C''est le cœur du mystère de Noël.", "examples": [{"text": "Le Verbe s''est fait chair : voilà l''incarnation.", "translation": "Dieu entre dans l''histoire humaine."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_nestorianisme', 'eg', 'le nestorianisme', 'enseignement qui sépare le Verbe et l''homme Jésus', 'On appelle ainsi l''enseignement qui sépare le Verbe de l''homme Jésus, comme si Dieu habitait en lui comme dans un temple. L''Église le rejette au concile d''Éphèse en 431.', '[{"text": "Le nestorianisme coupe le Christ en deux.", "translation": "L''Église copte rejette cette séparation."}]'::jsonb, null, '{"id": "eg.d.c05_nestorianisme", "unitId": "eg.v.c05_nestorianisme", "word": "le nestorianisme", "translation": "enseignement qui sépare le Verbe et l''homme Jésus", "partOfSpeech": "concept", "collection": "heresie", "explanation": "On appelle ainsi l''enseignement qui sépare le Verbe de l''homme Jésus, comme si Dieu habitait en lui comme dans un temple. L''Église le rejette au concile d''Éphèse en 431.", "examples": [{"text": "Le nestorianisme coupe le Christ en deux.", "translation": "L''Église copte rejette cette séparation."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_ecole_d_antioche', 'eg', 'l''école d''Antioche', 'courant théologique qui distingue soigneusement divin et humain', 'Cette école, née à Antioche, insiste sur l''humanité de Jésus et distingue avec soin ce qui est divin et ce qui est humain. Nestorius en vient. Alexandrie, au contraire, insiste sur l''unité.', '[{"text": "L''école d''Antioche distingue le divin et l''humain.", "translation": "Son souci : ne rien mélanger."}]'::jsonb, null, '{"id": "eg.d.c05_ecole_d_antioche", "unitId": "eg.v.c05_ecole_d_antioche", "word": "l''école d''Antioche", "translation": "courant théologique qui distingue soigneusement divin et humain", "partOfSpeech": "organization", "collection": "notion", "explanation": "Cette école, née à Antioche, insiste sur l''humanité de Jésus et distingue avec soin ce qui est divin et ce qui est humain. Nestorius en vient. Alexandrie, au contraire, insiste sur l''unité.", "examples": [{"text": "L''école d''Antioche distingue le divin et l''humain.", "translation": "Son souci : ne rien mélanger."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_nature', 'eg', 'la nature', 'ce qu''on est (par exemple : humain)', 'En théologie, la nature dit CE QU''on est : une nature humaine, une nature divine. Tous les humains ont la même nature. Le mot deviendra le centre de la dispute : le Christ a-t-il une ou deux natures ?', '[{"text": "Pierre et Paul ont la même nature humaine.", "translation": "La nature est ce qu''on partage avec les autres."}]'::jsonb, null, '{"id": "eg.d.c05_nature", "unitId": "eg.v.c05_nature", "word": "la nature", "translation": "ce qu''on est (par exemple : humain)", "partOfSpeech": "concept", "collection": "notion", "explanation": "En théologie, la nature dit CE QU''on est : une nature humaine, une nature divine. Tous les humains ont la même nature. Le mot deviendra le centre de la dispute : le Christ a-t-il une ou deux natures ?", "examples": [{"text": "Pierre et Paul ont la même nature humaine.", "translation": "La nature est ce qu''on partage avec les autres."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_personne', 'eg', 'la personne', 'qui on est : quelqu''un qui dit « je »', 'La personne dit QUI on est : un sujet unique, qui dit « je ». Pierre et Paul partagent la nature humaine, mais sont deux personnes. Jésus est une seule personne : le Verbe fait chair.', '[{"text": "Le Christ est une seule personne.", "translation": "Un seul « je » dans le Christ."}]'::jsonb, null, '{"id": "eg.d.c05_personne", "unitId": "eg.v.c05_personne", "word": "la personne", "translation": "qui on est : quelqu''un qui dit « je »", "partOfSpeech": "concept", "collection": "notion", "explanation": "La personne dit QUI on est : un sujet unique, qui dit « je ». Pierre et Paul partagent la nature humaine, mais sont deux personnes. Jésus est une seule personne : le Verbe fait chair.", "examples": [{"text": "Le Christ est une seule personne.", "translation": "Un seul « je » dans le Christ."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_unite_du_christ', 'eg', 'l''unité du Christ', 'un seul Christ, une seule personne, Dieu et homme', 'Pour Cyrille, le Christ n''est pas deux personnes, mais un seul : le Verbe fait chair. L''unité du Christ n''enlève rien à sa divinité ni à son humanité. C''est le cœur de la foi copte.', '[{"text": "Cyrille défend l''unité du Christ.", "translation": "Pas de Christ coupé en deux."}]'::jsonb, null, '{"id": "eg.d.c05_unite_du_christ", "unitId": "eg.v.c05_unite_du_christ", "word": "l''unité du Christ", "translation": "un seul Christ, une seule personne, Dieu et homme", "partOfSpeech": "concept", "collection": "notion", "explanation": "Pour Cyrille, le Christ n''est pas deux personnes, mais un seul : le Verbe fait chair. L''unité du Christ n''enlève rien à sa divinité ni à son humanité. C''est le cœur de la foi copte.", "examples": [{"text": "Cyrille défend l''unité du Christ.", "translation": "Pas de Christ coupé en deux."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_cyrille', 'eg', 'saint Cyrille d''Alexandrie', '24e pape d''Alexandrie (412-444), le Pilier de la foi', 'Théologien et prédicateur énergique, Cyrille défend Théotokos et l''unité du Christ contre Nestorius. L''Église copte l''appelle le Pilier de la foi, et l''une de ses trois liturgies porte son nom. Il préside le concile d''Éphèse en 431.', '[{"text": "Cyrille écrit à Nestorius.", "translation": "Le pape d''Alexandrie prend la plume."}]'::jsonb, null, '{"id": "eg.d.c05_cyrille", "unitId": "eg.v.c05_cyrille", "word": "saint Cyrille d''Alexandrie", "translation": "24e pape d''Alexandrie (412-444), le Pilier de la foi", "partOfSpeech": "person", "collection": "pape", "explanation": "Théologien et prédicateur énergique, Cyrille défend Théotokos et l''unité du Christ contre Nestorius. L''Église copte l''appelle le Pilier de la foi, et l''une de ses trois liturgies porte son nom. Il préside le concile d''Éphèse en 431.", "examples": [{"text": "Cyrille écrit à Nestorius.", "translation": "Le pape d''Alexandrie prend la plume."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_formule_de_cyrille', 'eg', 'la formule de Cyrille', '« une seule nature du Verbe incarné »', 'En grec : mia physis tou Theou Logou sesarkomene, « une seule nature du Dieu Verbe incarné ». Le Verbe est l''unique sujet : il naît de Marie et meurt sur la croix. C''est la base de la foi copte, appelée miaphysisme.', '[{"text": "« Une seule nature du Verbe incarné. »", "translation": "Cyrille résume sa foi en une phrase."}]'::jsonb, null, '{"id": "eg.d.c05_formule_de_cyrille", "unitId": "eg.v.c05_formule_de_cyrille", "word": "la formule de Cyrille", "translation": "« une seule nature du Verbe incarné »", "partOfSpeech": "expression", "collection": "notion", "explanation": "En grec : mia physis tou Theou Logou sesarkomene, « une seule nature du Dieu Verbe incarné ». Le Verbe est l''unique sujet : il naît de Marie et meurt sur la croix. C''est la base de la foi copte, appelée miaphysisme.", "examples": [{"text": "« Une seule nature du Verbe incarné. »", "translation": "Cyrille résume sa foi en une phrase."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_douze_anathemes', 'eg', 'les douze anathèmes', 'douze condamnations jointes à la lettre de Cyrille à Nestorius', 'Un anathème est une condamnation solennelle. En 430, Cyrille joint douze anathèmes à sa troisième lettre à Nestorius : douze propositions condamnant ce que dit le nestorianisme. Très fermes, ils crispent l''école d''Antioche.', '[{"text": "Cyrille joint douze anathèmes à sa lettre.", "translation": "Douze condamnations, très fermes."}]'::jsonb, null, '{"id": "eg.d.c05_douze_anathemes", "unitId": "eg.v.c05_douze_anathemes", "word": "les douze anathèmes", "translation": "douze condamnations jointes à la lettre de Cyrille à Nestorius", "partOfSpeech": "work", "collection": "livre", "explanation": "Un anathème est une condamnation solennelle. En 430, Cyrille joint douze anathèmes à sa troisième lettre à Nestorius : douze propositions condamnant ce que dit le nestorianisme. Très fermes, ils crispent l''école d''Antioche.", "examples": [{"text": "Cyrille joint douze anathèmes à sa lettre.", "translation": "Douze condamnations, très fermes."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_concile_ephese_431', 'eg', 'le concile d''Éphèse (431)', 'troisième concile œcuménique, qui condamne Nestorius', 'Réuni en 431 par l''empereur Théodose II, il proclame Marie Théotokos et condamne Nestorius. C''est le troisième des trois conciles que l''Église copte reconnaît, et son pape Cyrille y a joué le rôle principal.', '[{"text": "Le concile d''Éphèse a lieu en 431.", "translation": "Le troisième concile œcuménique."}]'::jsonb, null, '{"id": "eg.d.c05_concile_ephese_431", "unitId": "eg.v.c05_concile_ephese_431", "word": "le concile d''Éphèse (431)", "translation": "troisième concile œcuménique, qui condamne Nestorius", "partOfSpeech": "event", "collection": "concile", "explanation": "Réuni en 431 par l''empereur Théodose II, il proclame Marie Théotokos et condamne Nestorius. C''est le troisième des trois conciles que l''Église copte reconnaît, et son pape Cyrille y a joué le rôle principal.", "examples": [{"text": "Le concile d''Éphèse a lieu en 431.", "translation": "Le troisième concile œcuménique."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_ephese', 'eg', 'Éphèse', 'grande ville d''Asie Mineure, lieu de deux conciles (431 et 449)', 'Éphèse est une grande ville d''Asie Mineure, sur la côte de l''actuelle Turquie. On y tient deux conciles, en 431 et en 449. Celui de 431 se réunit dans l''église dédiée à Marie.', '[{"text": "Deux conciles se tiennent à Éphèse.", "translation": "En 431, puis en 449."}]'::jsonb, null, '{"id": "eg.d.c05_ephese", "unitId": "eg.v.c05_ephese", "word": "Éphèse", "translation": "grande ville d''Asie Mineure, lieu de deux conciles (431 et 449)", "partOfSpeech": "place", "collection": "lieu", "explanation": "Éphèse est une grande ville d''Asie Mineure, sur la côte de l''actuelle Turquie. On y tient deux conciles, en 431 et en 449. Celui de 431 se réunit dans l''église dédiée à Marie.", "examples": [{"text": "Deux conciles se tiennent à Éphèse.", "translation": "En 431, puis en 449."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_jean_d_antioche', 'eg', 'Jean d''Antioche', 'patriarche d''Antioche, arrivé en retard à Éphèse en 431', 'Patriarche d''Antioche et ami de Nestorius, il arrive à Éphèse après l''ouverture du concile et tient un concile rival avec les évêques d''Orient. Il se réconcilie ensuite avec Cyrille par la formule d''union de 433.', '[{"text": "Jean d''Antioche arrive trop tard.", "translation": "Il tient alors un concile rival."}]'::jsonb, null, '{"id": "eg.d.c05_jean_d_antioche", "unitId": "eg.v.c05_jean_d_antioche", "word": "Jean d''Antioche", "translation": "patriarche d''Antioche, arrivé en retard à Éphèse en 431", "partOfSpeech": "person", "collection": "pape", "explanation": "Patriarche d''Antioche et ami de Nestorius, il arrive à Éphèse après l''ouverture du concile et tient un concile rival avec les évêques d''Orient. Il se réconcilie ensuite avec Cyrille par la formule d''union de 433.", "examples": [{"text": "Jean d''Antioche arrive trop tard.", "translation": "Il tient alors un concile rival."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_pelagianisme', 'eg', 'le pélagianisme', 'enseignement de Pélage : l''homme se sauve seul, sans la grâce', 'Pour Pélage, l''homme n''hérite pas du péché originel et peut atteindre la sainteté par ses propres forces, sans avoir besoin de la grâce de Dieu. Éphèse le condamne en rappelant que la grâce est nécessaire au salut.', '[{"text": "Éphèse condamne aussi le pélagianisme.", "translation": "La grâce de Dieu est nécessaire."}]'::jsonb, null, '{"id": "eg.d.c05_pelagianisme", "unitId": "eg.v.c05_pelagianisme", "word": "le pélagianisme", "translation": "enseignement de Pélage : l''homme se sauve seul, sans la grâce", "partOfSpeech": "concept", "collection": "heresie", "explanation": "Pour Pélage, l''homme n''hérite pas du péché originel et peut atteindre la sainteté par ses propres forces, sans avoir besoin de la grâce de Dieu. Éphèse le condamne en rappelant que la grâce est nécessaire au salut.", "examples": [{"text": "Éphèse condamne aussi le pélagianisme.", "translation": "La grâce de Dieu est nécessaire."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_credo_intouchable', 'eg', 'le credo qu''on ne change plus', 'règle d''Éphèse : interdit de composer un autre credo que celui de Nicée', 'Éphèse confirme le credo de Nicée et interdit d''en composer un autre. C''est un argument que l''Église copte reprendra contre Chalcédoine : une nouvelle définition de la foi ajoute à ce qu''Éphèse avait interdit de changer.', '[{"text": "Éphèse interdit de composer un autre credo.", "translation": "Le credo de Nicée suffit."}]'::jsonb, null, '{"id": "eg.d.c05_credo_intouchable", "unitId": "eg.v.c05_credo_intouchable", "word": "le credo qu''on ne change plus", "translation": "règle d''Éphèse : interdit de composer un autre credo que celui de Nicée", "partOfSpeech": "concept", "collection": "notion", "explanation": "Éphèse confirme le credo de Nicée et interdit d''en composer un autre. C''est un argument que l''Église copte reprendra contre Chalcédoine : une nouvelle définition de la foi ajoute à ce qu''Éphèse avait interdit de changer.", "examples": [{"text": "Éphèse interdit de composer un autre credo.", "translation": "Le credo de Nicée suffit."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_akhmim', 'eg', 'Akhmim', 'ville de Haute-Égypte, lieu où finit Nestorius selon la tradition copte', 'Akhmim est une ville de Haute-Égypte. Selon la tradition copte, le patriarche déposé Nestorius y finit ses jours, en exil, dans le pays même de Cyrille.', '[{"text": "Nestorius est exilé à Akhmim.", "translation": "Il meurt en Égypte, terre de Cyrille."}]'::jsonb, null, '{"id": "eg.d.c05_akhmim", "unitId": "eg.v.c05_akhmim", "word": "Akhmim", "translation": "ville de Haute-Égypte, lieu où finit Nestorius selon la tradition copte", "partOfSpeech": "place", "collection": "lieu", "explanation": "Akhmim est une ville de Haute-Égypte. Selon la tradition copte, le patriarche déposé Nestorius y finit ses jours, en exil, dans le pays même de Cyrille.", "examples": [{"text": "Nestorius est exilé à Akhmim.", "translation": "Il meurt en Égypte, terre de Cyrille."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_formule_d_union', 'eg', 'la formule d''union (433)', 'compromis de 433 entre Cyrille et Jean d''Antioche', 'En 433, un texte de compromis réconcilie Alexandrie et Antioche : Jean accepte la déposition de Nestorius et le titre Théotokos, Cyrille accepte un vocabulaire plus nuancé. La question du nombre de natures reste ouverte.', '[{"text": "La formule d''union date de 433.", "translation": "Une paix qui n''a pas tout réglé."}]'::jsonb, null, '{"id": "eg.d.c05_formule_d_union", "unitId": "eg.v.c05_formule_d_union", "word": "la formule d''union (433)", "translation": "compromis de 433 entre Cyrille et Jean d''Antioche", "partOfSpeech": "event", "collection": "date", "explanation": "En 433, un texte de compromis réconcilie Alexandrie et Antioche : Jean accepte la déposition de Nestorius et le titre Théotokos, Cyrille accepte un vocabulaire plus nuancé. La question du nombre de natures reste ouverte.", "examples": [{"text": "La formule d''union date de 433.", "translation": "Une paix qui n''a pas tout réglé."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_eglise_de_l_orient', 'eg', 'l''Église de l''Orient', 'Église née en Perse chez des partisans de Nestorius', 'Chassés de l''Empire romain, de nombreux partisans de Nestorius gagnent la Perse. Là naît l''Église de l''Orient, qui se répand loin vers l''est et existe encore aujourd''hui. Elle n''est pas l''Église copte.', '[{"text": "L''Église de l''Orient naît en Perse.", "translation": "Elle adopte la théologie de Nestorius."}]'::jsonb, null, '{"id": "eg.d.c05_eglise_de_l_orient", "unitId": "eg.v.c05_eglise_de_l_orient", "word": "l''Église de l''Orient", "translation": "Église née en Perse chez des partisans de Nestorius", "partOfSpeech": "organization", "collection": "eglise", "explanation": "Chassés de l''Empire romain, de nombreux partisans de Nestorius gagnent la Perse. Là naît l''Église de l''Orient, qui se répand loin vers l''est et existe encore aujourd''hui. Elle n''est pas l''Église copte.", "examples": [{"text": "L''Église de l''Orient naît en Perse.", "translation": "Elle adopte la théologie de Nestorius."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_flavien', 'eg', 'Flavien', 'patriarche de Constantinople (446-449)', 'Patriarche de Constantinople à partir de 446, il veut affirmer le rôle de son siège, la nouvelle Rome. Il condamne Eutychès en 448 puis est déposé à Éphèse en 449.', '[{"text": "Flavien devient patriarche en 446.", "translation": "Il agira bientôt contre un moine nommé Eutychès."}]'::jsonb, null, '{"id": "eg.d.c05_flavien", "unitId": "eg.v.c05_flavien", "word": "Flavien", "translation": "patriarche de Constantinople (446-449)", "partOfSpeech": "person", "collection": "pape", "explanation": "Patriarche de Constantinople à partir de 446, il veut affirmer le rôle de son siège, la nouvelle Rome. Il condamne Eutychès en 448 puis est déposé à Éphèse en 449.", "examples": [{"text": "Flavien devient patriarche en 446.", "translation": "Il agira bientôt contre un moine nommé Eutychès."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_eutyches', 'eg', 'Eutychès', 'moine de Constantinople, condamné en 448 pour monophysisme', 'Archimandrite âgé et respecté, ardent adversaire de Nestorius, il tombe dans l''erreur inverse en disant que l''humanité du Christ est absorbée par la divinité. Condamné par Flavien en 448, il fait appel à l''empereur et à Dioscore.', '[{"text": "Eutychès combat Nestorius.", "translation": "Mais il va trop loin dans l''autre sens."}]'::jsonb, null, '{"id": "eg.d.c05_eutyches", "unitId": "eg.v.c05_eutyches", "word": "Eutychès", "translation": "moine de Constantinople, condamné en 448 pour monophysisme", "partOfSpeech": "person", "collection": "heresie", "explanation": "Archimandrite âgé et respecté, ardent adversaire de Nestorius, il tombe dans l''erreur inverse en disant que l''humanité du Christ est absorbée par la divinité. Condamné par Flavien en 448, il fait appel à l''empereur et à Dioscore.", "examples": [{"text": "Eutychès combat Nestorius.", "translation": "Mais il va trop loin dans l''autre sens."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_monophysisme', 'eg', 'le monophysisme', 'doctrine d''Eutychès : une seule nature, la divine, qui absorbe l''humanité', 'Du grec mono (un seul) et physis (nature) : le Christ n''aurait qu''une nature, la divine, qui absorbe l''humanité. L''Église copte condamne aussi cette erreur : elle n''est pas monophysite, mais miaphysite.', '[{"text": "Le monophysisme fait disparaître l''humanité.", "translation": "Les coptes le condamnent."}]'::jsonb, null, '{"id": "eg.d.c05_monophysisme", "unitId": "eg.v.c05_monophysisme", "word": "le monophysisme", "translation": "doctrine d''Eutychès : une seule nature, la divine, qui absorbe l''humanité", "partOfSpeech": "concept", "collection": "heresie", "explanation": "Du grec mono (un seul) et physis (nature) : le Christ n''aurait qu''une nature, la divine, qui absorbe l''humanité. L''Église copte condamne aussi cette erreur : elle n''est pas monophysite, mais miaphysite.", "examples": [{"text": "Le monophysisme fait disparaître l''humanité.", "translation": "Les coptes le condamnent."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_archimandrite', 'eg', 'un archimandrite', 'chef d''un grand monastère', 'Titre donné au supérieur d''un grand monastère, un homme souvent très influent. Eutychès l''est près de Constantinople.', '[{"text": "Eutychès est un archimandrite.", "translation": "Il dirige un grand monastère."}]'::jsonb, null, '{"id": "eg.d.c05_archimandrite", "unitId": "eg.v.c05_archimandrite", "word": "un archimandrite", "translation": "chef d''un grand monastère", "partOfSpeech": "person", "collection": "notion", "explanation": "Titre donné au supérieur d''un grand monastère, un homme souvent très influent. Eutychès l''est près de Constantinople.", "examples": [{"text": "Eutychès est un archimandrite.", "translation": "Il dirige un grand monastère."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_fer_et_feu', 'eg', 'l''image du fer et du feu', 'le fer chauffé au rouge : l''union réelle du divin et de l''humain', 'Les Pères comparent le Christ à une barre de fer chauffée au rouge dans le feu : le fer reste du fer, et il brille et brûle comme le feu. Fer et feu ne forment plus qu''un seul tout, mais rien n''est détruit.', '[{"text": "Le fer chauffé au rouge reste du fer.", "translation": "Une image pour l''union du Verbe et de la chair."}]'::jsonb, null, '{"id": "eg.d.c05_fer_et_feu", "unitId": "eg.v.c05_fer_et_feu", "word": "l''image du fer et du feu", "translation": "le fer chauffé au rouge : l''union réelle du divin et de l''humain", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les Pères comparent le Christ à une barre de fer chauffée au rouge dans le feu : le fer reste du fer, et il brille et brûle comme le feu. Fer et feu ne forment plus qu''un seul tout, mais rien n''est détruit.", "examples": [{"text": "Le fer chauffé au rouge reste du fer.", "translation": "Une image pour l''union du Verbe et de la chair."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_sans_melange_ni_division', 'eg', 'sans mélange ni division', 'l''union réelle : l''humanité ne disparaît pas, le Christ n''est pas coupé en deux', 'Deux petites expressions résument la foi copte. Sans mélange : l''humanité n''est pas absorbée. Sans division : le Christ n''est pas coupé en deux. L''Église copte les proclame à la confession, avant la communion.', '[{"text": "Le Christ est uni sans mélange ni division.", "translation": "Une union réelle, rien n''est détruit."}]'::jsonb, null, '{"id": "eg.d.c05_sans_melange_ni_division", "unitId": "eg.v.c05_sans_melange_ni_division", "word": "sans mélange ni division", "translation": "l''union réelle : l''humanité ne disparaît pas, le Christ n''est pas coupé en deux", "partOfSpeech": "expression", "collection": "notion", "explanation": "Deux petites expressions résument la foi copte. Sans mélange : l''humanité n''est pas absorbée. Sans division : le Christ n''est pas coupé en deux. L''Église copte les proclame à la confession, avant la communion.", "examples": [{"text": "Le Christ est uni sans mélange ni division.", "translation": "Une union réelle, rien n''est détruit."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_miaphysisme', 'eg', 'le miaphysisme', 'foi en une seule nature unie du Verbe incarné, sans mélange ni division', 'Du grec mia (une seule, unie) et physis (nature). Foi de Cyrille et de l''Église copte : le Christ est pleinement humain et pleinement divin, le divin et l''humain n''étant ni mélangés ni divisés. Ce n''est pas le monophysisme d''Eutychès.', '[{"text": "L''Église copte est miaphysite.", "translation": "Une seule nature unie, sans mélange ni division."}]'::jsonb, null, '{"id": "eg.d.c05_miaphysisme", "unitId": "eg.v.c05_miaphysisme", "word": "le miaphysisme", "translation": "foi en une seule nature unie du Verbe incarné, sans mélange ni division", "partOfSpeech": "concept", "collection": "notion", "explanation": "Du grec mia (une seule, unie) et physis (nature). Foi de Cyrille et de l''Église copte : le Christ est pleinement humain et pleinement divin, le divin et l''humain n''étant ni mélangés ni divisés. Ce n''est pas le monophysisme d''Eutychès.", "examples": [{"text": "L''Église copte est miaphysite.", "translation": "Une seule nature unie, sans mélange ni division."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_dyophysisme', 'eg', 'le dyophysisme', 'foi en deux natures du Christ, chacune gardant son caractère', 'Du grec dyo (deux). Après l''union, le Christ a deux natures, la divine et l''humaine, chacune gardant son caractère. C''est la foi de Chalcédoine, des Églises orthodoxes chalcédoniennes et de l''Église catholique.', '[{"text": "Chalcédoine professe le dyophysisme.", "translation": "Deux natures, un seul Christ."}]'::jsonb, null, '{"id": "eg.d.c05_dyophysisme", "unitId": "eg.v.c05_dyophysisme", "word": "le dyophysisme", "translation": "foi en deux natures du Christ, chacune gardant son caractère", "partOfSpeech": "concept", "collection": "notion", "explanation": "Du grec dyo (deux). Après l''union, le Christ a deux natures, la divine et l''humaine, chacune gardant son caractère. C''est la foi de Chalcédoine, des Églises orthodoxes chalcédoniennes et de l''Église catholique.", "examples": [{"text": "Chalcédoine professe le dyophysisme.", "translation": "Deux natures, un seul Christ."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_physis', 'eg', 'physis', 'mot grec pour « nature » : mono-physisme, dyo-physisme, mia-physisme', 'Physis veut dire « nature » en grec. On le retrouve dans trois mots : mono-physisme (un seul), dyo-physisme (deux) et mia-physisme (une seule, unie). C''est la clé de toute la dispute.', '[{"text": "Physis veut dire nature.", "translation": "Le mot qui se cache dans mono, dyo et mia."}]'::jsonb, null, '{"id": "eg.d.c05_physis", "unitId": "eg.v.c05_physis", "word": "physis", "translation": "mot grec pour « nature » : mono-physisme, dyo-physisme, mia-physisme", "partOfSpeech": "concept", "collection": "copte", "explanation": "Physis veut dire « nature » en grec. On le retrouve dans trois mots : mono-physisme (un seul), dyo-physisme (deux) et mia-physisme (une seule, unie). C''est la clé de toute la dispute.", "examples": [{"text": "Physis veut dire nature.", "translation": "Le mot qui se cache dans mono, dyo et mia."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_concile_ephese_449', 'eg', 'le deuxième concile d''Éphèse (449)', 'concile présidé par Dioscore, qui réhabilite Eutychès et dépose Flavien', 'Convoqué par Théodose II, il se tient en août 449. Dioscore le préside, réhabilite Eutychès et dépose Flavien. Le Tome de Léon n''est pas lu. Les chalcédoniens le rejettent ; l''Église copte défend Dioscore.', '[{"text": "Éphèse II se tient en 449.", "translation": "Dioscore le préside."}]'::jsonb, null, '{"id": "eg.d.c05_concile_ephese_449", "unitId": "eg.v.c05_concile_ephese_449", "word": "le deuxième concile d''Éphèse (449)", "translation": "concile présidé par Dioscore, qui réhabilite Eutychès et dépose Flavien", "partOfSpeech": "event", "collection": "concile", "explanation": "Convoqué par Théodose II, il se tient en août 449. Dioscore le préside, réhabilite Eutychès et dépose Flavien. Le Tome de Léon n''est pas lu. Les chalcédoniens le rejettent ; l''Église copte défend Dioscore.", "examples": [{"text": "Éphèse II se tient en 449.", "translation": "Dioscore le préside."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_tome_de_leon', 'eg', 'le Tome de Léon', 'lettre dogmatique de Léon Ier sur les deux natures du Christ', 'Dans cette lettre, Léon Ier affirme les deux natures du Christ. Elle n''est pas lue à Éphèse II, mais elle sera lue et ratifiée à Chalcédoine en 451.', '[{"text": "Le Tome de Léon n''est pas lu en 449.", "translation": "Il le sera à Chalcédoine."}]'::jsonb, null, '{"id": "eg.d.c05_tome_de_leon", "unitId": "eg.v.c05_tome_de_leon", "word": "le Tome de Léon", "translation": "lettre dogmatique de Léon Ier sur les deux natures du Christ", "partOfSpeech": "work", "collection": "livre", "explanation": "Dans cette lettre, Léon Ier affirme les deux natures du Christ. Elle n''est pas lue à Éphèse II, mais elle sera lue et ratifiée à Chalcédoine en 451.", "examples": [{"text": "Le Tome de Léon n''est pas lu en 449.", "translation": "Il le sera à Chalcédoine."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_leon_ier', 'eg', 'Léon Ier', 'évêque de Rome (440-461), auteur du Tome de Léon', 'Évêque de Rome, Léon estime avoir autorité sur toute l''Église. Il écrit le Tome de Léon, appelle Éphèse II le « brigandage d''Éphèse » et obtient que Marcien convoque Chalcédoine.', '[{"text": "Léon Ier envoie des légats à Éphèse.", "translation": "Lui-même ne vient pas."}]'::jsonb, null, '{"id": "eg.d.c05_leon_ier", "unitId": "eg.v.c05_leon_ier", "word": "Léon Ier", "translation": "évêque de Rome (440-461), auteur du Tome de Léon", "partOfSpeech": "person", "collection": "pape", "explanation": "Évêque de Rome, Léon estime avoir autorité sur toute l''Église. Il écrit le Tome de Léon, appelle Éphèse II le « brigandage d''Éphèse » et obtient que Marcien convoque Chalcédoine.", "examples": [{"text": "Léon Ier envoie des légats à Éphèse.", "translation": "Lui-même ne vient pas."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_brigandage_d_ephese', 'eg', 'le brigandage d''Éphèse', 'nom donné par Léon à Éphèse II (latrocinium)', 'Léon Ier et les chalcédoniens appellent Éphèse II le « brigandage d''Éphèse » (latrocinium). L''Église copte, elle, défend Dioscore et conteste ce nom.', '[{"text": "Léon parle de brigandage d''Éphèse.", "translation": "Un nom polémique pour Éphèse II."}]'::jsonb, null, '{"id": "eg.d.c05_brigandage_d_ephese", "unitId": "eg.v.c05_brigandage_d_ephese", "word": "le brigandage d''Éphèse", "translation": "nom donné par Léon à Éphèse II (latrocinium)", "partOfSpeech": "event", "collection": "date", "explanation": "Léon Ier et les chalcédoniens appellent Éphèse II le « brigandage d''Éphèse » (latrocinium). L''Église copte, elle, défend Dioscore et conteste ce nom.", "examples": [{"text": "Léon parle de brigandage d''Éphèse.", "translation": "Un nom polémique pour Éphèse II."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_concile_chalcedoine', 'eg', 'le concile de Chalcédoine (451)', 'concile qui définit « deux natures », rejeté par l''Église copte', 'Réuni en 451 par l''empereur Marcien, il ratifie le Tome de Léon et définit un seul Christ en deux natures. Reconnu comme quatrième concile par les Églises chalcédoniennes, il n''est pas reconnu par l''Église copte.', '[{"text": "Le concile de Chalcédoine se tient en 451.", "translation": "Les coptes ne le reconnaissent pas."}]'::jsonb, null, '{"id": "eg.d.c05_concile_chalcedoine", "unitId": "eg.v.c05_concile_chalcedoine", "word": "le concile de Chalcédoine (451)", "translation": "concile qui définit « deux natures », rejeté par l''Église copte", "partOfSpeech": "event", "collection": "concile", "explanation": "Réuni en 451 par l''empereur Marcien, il ratifie le Tome de Léon et définit un seul Christ en deux natures. Reconnu comme quatrième concile par les Églises chalcédoniennes, il n''est pas reconnu par l''Église copte.", "examples": [{"text": "Le concile de Chalcédoine se tient en 451.", "translation": "Les coptes ne le reconnaissent pas."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_definition_de_chalcedoine', 'eg', 'la définition de Chalcédoine', 'un seul Christ reconnu en deux natures, sans confusion ni séparation', 'Le Christ est reconnu « en deux natures », sans confusion, sans changement, sans division, sans séparation. Les deux natures sont distinguées après l''union. Ce langage rappelle celui d''Antioche et choque Alexandrie.', '[{"text": "Un seul Christ en deux natures.", "translation": "C''est la définition de Chalcédoine."}]'::jsonb, null, '{"id": "eg.d.c05_definition_de_chalcedoine", "unitId": "eg.v.c05_definition_de_chalcedoine", "word": "la définition de Chalcédoine", "translation": "un seul Christ reconnu en deux natures, sans confusion ni séparation", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le Christ est reconnu « en deux natures », sans confusion, sans changement, sans division, sans séparation. Les deux natures sont distinguées après l''union. Ce langage rappelle celui d''Antioche et choque Alexandrie.", "examples": [{"text": "Un seul Christ en deux natures.", "translation": "C''est la définition de Chalcédoine."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_canon_28', 'eg', 'le canon 28', 'règle donnant à Constantinople la seconde place après Rome', 'Voté à Chalcédoine, il donne à Constantinople la seconde place, juste après Rome. Léon le refuse, car Rome veut garder le premier rang sans partage. Alexandrie y perd aussi un rang.', '[{"text": "Le canon 28 relance la dispute des rangs.", "translation": "Léon refuse ce canon."}]'::jsonb, null, '{"id": "eg.d.c05_canon_28", "unitId": "eg.v.c05_canon_28", "word": "le canon 28", "translation": "règle donnant à Constantinople la seconde place après Rome", "partOfSpeech": "concept", "collection": "concile", "explanation": "Voté à Chalcédoine, il donne à Constantinople la seconde place, juste après Rome. Léon le refuse, car Rome veut garder le premier rang sans partage. Alexandrie y perd aussi un rang.", "examples": [{"text": "Le canon 28 relance la dispute des rangs.", "translation": "Léon refuse ce canon."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_premier_schisme', 'eg', 'le premier schisme', 'la rupture de l''Église après Chalcédoine (451)', 'Après 451, l''Église se divise entre l''Est non-chalcédonien (Alexandrie, Antioche) et l''Ouest chalcédonien (Rome, Constantinople). Haines nationales, rivalités et jalousies aggravent la rupture. C''est un schisme distinct de celui de 1054.', '[{"text": "451 ouvre le premier schisme.", "translation": "Il dure encore aujourd''hui, même si le dialogue avance."}]'::jsonb, null, '{"id": "eg.d.c05_premier_schisme", "unitId": "eg.v.c05_premier_schisme", "word": "le premier schisme", "translation": "la rupture de l''Église après Chalcédoine (451)", "partOfSpeech": "event", "collection": "date", "explanation": "Après 451, l''Église se divise entre l''Est non-chalcédonien (Alexandrie, Antioche) et l''Ouest chalcédonien (Rome, Constantinople). Haines nationales, rivalités et jalousies aggravent la rupture. C''est un schisme distinct de celui de 1054.", "examples": [{"text": "451 ouvre le premier schisme.", "translation": "Il dure encore aujourd''hui, même si le dialogue avance."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_dioscore', 'eg', 'saint Dioscore', '25e pape d''Alexandrie (444-454), confesseur de la foi', 'Successeur de Cyrille, dont il a été l''archidiacre, il préside le deuxième concile d''Éphèse en 449 et refuse Chalcédoine. Exilé à Gangra, il meurt en 454. L''Église copte l''honore comme confesseur de la foi.', '[{"text": "Dioscore reste fidèle à Cyrille.", "translation": "Même seul face à tout un concile."}]'::jsonb, null, '{"id": "eg.d.c05_dioscore", "unitId": "eg.v.c05_dioscore", "word": "saint Dioscore", "translation": "25e pape d''Alexandrie (444-454), confesseur de la foi", "partOfSpeech": "person", "collection": "pape", "explanation": "Successeur de Cyrille, dont il a été l''archidiacre, il préside le deuxième concile d''Éphèse en 449 et refuse Chalcédoine. Exilé à Gangra, il meurt en 454. L''Église copte l''honore comme confesseur de la foi.", "examples": [{"text": "Dioscore reste fidèle à Cyrille.", "translation": "Même seul face à tout un concile."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_gangra', 'eg', 'Gangra', 'ville d''Asie Mineure où Dioscore est exilé', 'Gangra est une ville d''Asie Mineure, au nord de l''actuelle Turquie. L''empereur Marcien y exile Dioscore, qui y reste jusqu''à sa mort en 454.', '[{"text": "Dioscore est exilé à Gangra.", "translation": "Il y meurt en 454."}]'::jsonb, null, '{"id": "eg.d.c05_gangra", "unitId": "eg.v.c05_gangra", "word": "Gangra", "translation": "ville d''Asie Mineure où Dioscore est exilé", "partOfSpeech": "place", "collection": "lieu", "explanation": "Gangra est une ville d''Asie Mineure, au nord de l''actuelle Turquie. L''empereur Marcien y exile Dioscore, qui y reste jusqu''à sa mort en 454.", "examples": [{"text": "Dioscore est exilé à Gangra.", "translation": "Il y meurt en 454."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_confesseur_de_la_foi', 'eg', 'un confesseur de la foi', 'celui qui souffre pour sa foi sans mourir martyr', 'Un confesseur de la foi souffre pour sa foi (exil, prison, torture) sans mourir martyr. L''Église copte vénère saint Dioscore comme un confesseur : il a payé le prix de la fidélité à saint Cyrille.', '[{"text": "Dioscore est un confesseur de la foi.", "translation": "Il a souffert l''exil sans renier sa foi."}]'::jsonb, null, '{"id": "eg.d.c05_confesseur_de_la_foi", "unitId": "eg.v.c05_confesseur_de_la_foi", "word": "un confesseur de la foi", "translation": "celui qui souffre pour sa foi sans mourir martyr", "partOfSpeech": "concept", "collection": "notion", "explanation": "Un confesseur de la foi souffre pour sa foi (exil, prison, torture) sans mourir martyr. L''Église copte vénère saint Dioscore comme un confesseur : il a payé le prix de la fidélité à saint Cyrille.", "examples": [{"text": "Dioscore est un confesseur de la foi.", "translation": "Il a souffert l''exil sans renier sa foi."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_henotikon', 'eg', 'l''Hénotikon (482)', 'édit d''union de l''empereur Zénon, silencieux sur le nombre de natures', 'Texte de 482 publié par l''empereur Zénon avec le patriarche Acace. Il réaffirme Nicée et Constantinople, condamne Nestorius et Eutychès, mais ne dit rien de la ou des natures du Christ et interdit de poser la question. Il ne satisfait personne.', '[{"text": "L''Hénotikon date de 482.", "translation": "Un édit d''union qui n''unit personne."}]'::jsonb, null, '{"id": "eg.d.c05_henotikon", "unitId": "eg.v.c05_henotikon", "word": "l''Hénotikon (482)", "translation": "édit d''union de l''empereur Zénon, silencieux sur le nombre de natures", "partOfSpeech": "event", "collection": "date", "explanation": "Texte de 482 publié par l''empereur Zénon avec le patriarche Acace. Il réaffirme Nicée et Constantinople, condamne Nestorius et Eutychès, mais ne dit rien de la ou des natures du Christ et interdit de poser la question. Il ne satisfait personne.", "examples": [{"text": "L''Hénotikon date de 482.", "translation": "Un édit d''union qui n''unit personne."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_melkites', 'eg', 'les melkites', '« gens du roi » : chrétiens qui acceptent Chalcédoine et suivent l''empereur', 'Du syriaque malka, « roi » : chrétiens de Jérusalem, d''Alexandrie et d''Antioche qui acceptent Chalcédoine et restent fidèles à l''empereur de Constantinople. Les coptes, eux, restent fidèles à Dioscore.', '[{"text": "Les melkites suivent l''empereur.", "translation": "Ils acceptent Chalcédoine."}]'::jsonb, null, '{"id": "eg.d.c05_melkites", "unitId": "eg.v.c05_melkites", "word": "les melkites", "translation": "« gens du roi » : chrétiens qui acceptent Chalcédoine et suivent l''empereur", "partOfSpeech": "organization", "collection": "eglise", "explanation": "Du syriaque malka, « roi » : chrétiens de Jérusalem, d''Alexandrie et d''Antioche qui acceptent Chalcédoine et restent fidèles à l''empereur de Constantinople. Les coptes, eux, restent fidèles à Dioscore.", "examples": [{"text": "Les melkites suivent l''empereur.", "translation": "Ils acceptent Chalcédoine."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_macaire_d_edkou', 'eg', 'saint Macaire d''Edkou', 'évêque d''Edkou, martyr des persécutions contre les non-chalcédoniens', 'Évêque d''Edkou, il est l''un des martyrs des persécutions qui frappent les non-chalcédoniens à partir de 527. L''Église copte le vénère.', '[{"text": "Macaire d''Edkou est martyr.", "translation": "Il est resté fidèle à la foi d''Alexandrie."}]'::jsonb, null, '{"id": "eg.d.c05_macaire_d_edkou", "unitId": "eg.v.c05_macaire_d_edkou", "word": "saint Macaire d''Edkou", "translation": "évêque d''Edkou, martyr des persécutions contre les non-chalcédoniens", "partOfSpeech": "person", "collection": "saint", "explanation": "Évêque d''Edkou, il est l''un des martyrs des persécutions qui frappent les non-chalcédoniens à partir de 527. L''Église copte le vénère.", "examples": [{"text": "Macaire d''Edkou est martyr.", "translation": "Il est resté fidèle à la foi d''Alexandrie."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_eglises_soeurs', 'eg', 'les Églises sœurs', 'les six Églises orthodoxes orientales en intercommunion', 'L''Église copte, la syriaque, l''éthiopienne, l''indienne, l''érythréenne et l''arménienne refusent toutes Chalcédoine et sont en intercommunion : elles se reconnaissent mutuellement. On les appelle les Églises orthodoxes orientales.', '[{"text": "Les six Églises sœurs sont en intercommunion.", "translation": "Leurs fidèles peuvent se marier entre eux."}]'::jsonb, null, '{"id": "eg.d.c05_eglises_soeurs", "unitId": "eg.v.c05_eglises_soeurs", "word": "les Églises sœurs", "translation": "les six Églises orthodoxes orientales en intercommunion", "partOfSpeech": "organization", "collection": "eglise", "explanation": "L''Église copte, la syriaque, l''éthiopienne, l''indienne, l''érythréenne et l''arménienne refusent toutes Chalcédoine et sont en intercommunion : elles se reconnaissent mutuellement. On les appelle les Églises orthodoxes orientales.", "examples": [{"text": "Les six Églises sœurs sont en intercommunion.", "translation": "Leurs fidèles peuvent se marier entre eux."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_chalcedoniens', 'eg', 'les Églises chalcédoniennes', 'Églises qui acceptent Chalcédoine et reconnaissent sept conciles', 'Ce sont les Églises de rite byzantin (Constantinople, Grèce, Russie, Roumanie, Serbie…) et l''Église catholique. Elles acceptent Chalcédoine et reconnaissent sept conciles. Les coptes partagent aujourd''hui avec elles la même christologie, avec d''autres mots.', '[{"text": "Les chalcédoniens reconnaissent sept conciles.", "translation": "Ils disent « deux natures »."}]'::jsonb, null, '{"id": "eg.d.c05_chalcedoniens", "unitId": "eg.v.c05_chalcedoniens", "word": "les Églises chalcédoniennes", "translation": "Églises qui acceptent Chalcédoine et reconnaissent sept conciles", "partOfSpeech": "organization", "collection": "eglise", "explanation": "Ce sont les Églises de rite byzantin (Constantinople, Grèce, Russie, Roumanie, Serbie…) et l''Église catholique. Elles acceptent Chalcédoine et reconnaissent sept conciles. Les coptes partagent aujourd''hui avec elles la même christologie, avec d''autres mots.", "examples": [{"text": "Les chalcédoniens reconnaissent sept conciles.", "translation": "Ils disent « deux natures »."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_accord_de_1989', 'eg', 'l''accord de 1989 à Amba Bichoï', 'accord de foi entre orthodoxes orientaux et byzantins', 'En 1989, au monastère d''Amba Bichoï à Scété, des accords de foi sont signés entre les Églises orthodoxes byzantines et les Églises orientales. Ils constatent la même christologie, avec des mots différents.', '[{"text": "L''accord de 1989 date d''Amba Bichoï.", "translation": "Même foi, mots différents."}]'::jsonb, null, '{"id": "eg.d.c05_accord_de_1989", "unitId": "eg.v.c05_accord_de_1989", "word": "l''accord de 1989 à Amba Bichoï", "translation": "accord de foi entre orthodoxes orientaux et byzantins", "partOfSpeech": "event", "collection": "date", "explanation": "En 1989, au monastère d''Amba Bichoï à Scété, des accords de foi sont signés entre les Églises orthodoxes byzantines et les Églises orientales. Ils constatent la même christologie, avec des mots différents.", "examples": [{"text": "L''accord de 1989 date d''Amba Bichoï.", "translation": "Même foi, mots différents."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_frise', 'eg', 'la frise du Ve siècle', '428 Nestorius, 431 Éphèse, 449 Éphèse II, 451 Chalcédoine', 'Les repères du siècle : 428 Nestorius patriarche, 431 Éphèse, 433 formule d''union, 444 mort de Cyrille, 448 Eutychès condamné, 449 Éphèse II, 451 Chalcédoine, 482 Hénotikon, 538 deux patriarches à Alexandrie.', '[{"text": "431, 449, 451 : trois dates à ne pas mélanger.", "translation": "Éphèse I, Éphèse II, Chalcédoine."}]'::jsonb, null, '{"id": "eg.d.c05_frise", "unitId": "eg.v.c05_frise", "word": "la frise du Ve siècle", "translation": "428 Nestorius, 431 Éphèse, 449 Éphèse II, 451 Chalcédoine", "partOfSpeech": "date", "collection": "date", "explanation": "Les repères du siècle : 428 Nestorius patriarche, 431 Éphèse, 433 formule d''union, 444 mort de Cyrille, 448 Eutychès condamné, 449 Éphèse II, 451 Chalcédoine, 482 Hénotikon, 538 deux patriarches à Alexandrie.", "examples": [{"text": "431, 449, 451 : trois dates à ne pas mélanger.", "translation": "Éphèse I, Éphèse II, Chalcédoine."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c05_christologie', 'eg', 'la christologie', 'la partie de la foi qui dit qui est le Christ', 'La christologie est l''enseignement sur qui est le Christ : Dieu et homme, en une seule personne. Chaque Église en donne sa formule (une nature unie, deux natures), et l''accord de 1989 reconnaît que leur christologie est la même.', '[{"text": "Les deux familles ont la même christologie.", "translation": "Même foi, mots différents."}]'::jsonb, null, '{"id": "eg.d.c05_christologie", "unitId": "eg.v.c05_christologie", "word": "la christologie", "translation": "la partie de la foi qui dit qui est le Christ", "partOfSpeech": "concept", "collection": "notion", "explanation": "La christologie est l''enseignement sur qui est le Christ : Dieu et homme, en une seule personne. Chaque Église en donne sa formule (une nature unie, deux natures), et l''accord de 1989 reconnaît que leur christologie est la même.", "examples": [{"text": "Les deux familles ont la même christologie.", "translation": "Même foi, mots différents."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c06_reception_d_un_concile', 'eg', 'la réception d''un concile', 'l''acceptation d''un concile par l''ensemble de l''Église', 'Un concile ne compte pas seulement parce qu''il s''est réuni : il compte quand l''Église entière le reçoit, le prie et le garde. C''est pourquoi les coptes, qui n''ont pas reçu Chalcédoine, ne le comptent pas parmi leurs conciles.', '[{"text": "Les coptes ont reçu Nicée, Constantinople et Éphèse.", "translation": "Recevoir un concile, c''est le faire sien."}]'::jsonb, null, '{"id": "eg.d.c06_reception_d_un_concile", "unitId": "eg.v.c06_reception_d_un_concile", "word": "la réception d''un concile", "translation": "l''acceptation d''un concile par l''ensemble de l''Église", "partOfSpeech": "concept", "collection": "notion", "explanation": "Un concile ne compte pas seulement parce qu''il s''est réuni : il compte quand l''Église entière le reçoit, le prie et le garde. C''est pourquoi les coptes, qui n''ont pas reçu Chalcédoine, ne le comptent pas parmi leurs conciles.", "examples": [{"text": "Les coptes ont reçu Nicée, Constantinople et Éphèse.", "translation": "Recevoir un concile, c''est le faire sien."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c06_adoptianisme', 'eg', 'l''adoptianisme', 'le Christ serait un homme « adopté » par Dieu, pas le Fils éternel', 'Du latin « adopter » : Dieu aurait choisi un homme et l''aurait adopté comme Fils. C''est l''enseignement de Paul de Samosate, condamné à Antioche en 269. L''Église répond que le Fils est Dieu de toute éternité.', '[{"text": "Pour Paul de Samosate, le Christ est un homme ordinaire choisi par Dieu.", "translation": "C''est l''adoptianisme."}]'::jsonb, null, '{"id": "eg.d.c06_adoptianisme", "unitId": "eg.v.c06_adoptianisme", "word": "l''adoptianisme", "translation": "le Christ serait un homme « adopté » par Dieu, pas le Fils éternel", "partOfSpeech": "concept", "collection": "heresie", "explanation": "Du latin « adopter » : Dieu aurait choisi un homme et l''aurait adopté comme Fils. C''est l''enseignement de Paul de Samosate, condamné à Antioche en 269. L''Église répond que le Fils est Dieu de toute éternité.", "examples": [{"text": "Pour Paul de Samosate, le Christ est un homme ordinaire choisi par Dieu.", "translation": "C''est l''adoptianisme."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c06_modalisme', 'eg', 'le modalisme', 'un seul Dieu à trois masques : Père, Fils, Esprit ne seraient que des rôles', 'Du mot « mode » : Père, Fils et Esprit ne seraient que trois manières d''apparaître d''un seul Dieu, comme un acteur change de masque. Sabellius en est le nom le plus connu. L''Église répond : trois personnes réelles, une seule divinité.', '[{"text": "Sabellius compare Dieu à un acteur qui change de masque.", "translation": "C''est le modalisme, ou sabellianisme."}]'::jsonb, null, '{"id": "eg.d.c06_modalisme", "unitId": "eg.v.c06_modalisme", "word": "le modalisme", "translation": "un seul Dieu à trois masques : Père, Fils, Esprit ne seraient que des rôles", "partOfSpeech": "concept", "collection": "heresie", "explanation": "Du mot « mode » : Père, Fils et Esprit ne seraient que trois manières d''apparaître d''un seul Dieu, comme un acteur change de masque. Sabellius en est le nom le plus connu. L''Église répond : trois personnes réelles, une seule divinité.", "examples": [{"text": "Sabellius compare Dieu à un acteur qui change de masque.", "translation": "C''est le modalisme, ou sabellianisme."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c06_les_trois_formules', 'eg', 'les trois formules', 'homoousios, Théotokos, « une seule nature du Verbe incarné »', 'Trois phrases-clés de la foi copte : homoousios (Nicée, le Fils est Dieu comme le Père), Théotokos (Éphèse, Marie est mère de Dieu), « une seule nature du Verbe incarné » (Cyrille, un seul Christ sans mélange ni division). Elles se tiennent comme une chaîne.', '[{"text": "Homoousios, Théotokos, une seule nature : les trois formules.", "translation": "Trois mots pour dire le même Christ."}]'::jsonb, null, '{"id": "eg.d.c06_les_trois_formules", "unitId": "eg.v.c06_les_trois_formules", "word": "les trois formules", "translation": "homoousios, Théotokos, « une seule nature du Verbe incarné »", "partOfSpeech": "concept", "collection": "notion", "explanation": "Trois phrases-clés de la foi copte : homoousios (Nicée, le Fils est Dieu comme le Père), Théotokos (Éphèse, Marie est mère de Dieu), « une seule nature du Verbe incarné » (Cyrille, un seul Christ sans mélange ni division). Elles se tiennent comme une chaîne.", "examples": [{"text": "Homoousios, Théotokos, une seule nature : les trois formules.", "translation": "Trois mots pour dire le même Christ."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_orthodoxes_byzantins', 'eg', 'les orthodoxes byzantins', 'Églises grecque, russe, serbe, roumaine… qui reçoivent Chalcédoine', 'Ce sont les orthodoxes grecs, russes, serbes, roumains… Ils reçoivent sept conciles, dont Chalcédoine, et ne reconnaissent pas le pape de Rome. Ils sont plus de 200 millions.', '[{"text": "Eleni est orthodoxe grecque : elle appartient aux orthodoxes byzantins.", "translation": "Elle n''est ni copte ni catholique."}]'::jsonb, null, '{"id": "eg.d.c07_orthodoxes_byzantins", "unitId": "eg.v.c07_orthodoxes_byzantins", "word": "les orthodoxes byzantins", "translation": "Églises grecque, russe, serbe, roumaine… qui reçoivent Chalcédoine", "partOfSpeech": "organization", "collection": "eglise", "explanation": "Ce sont les orthodoxes grecs, russes, serbes, roumains… Ils reçoivent sept conciles, dont Chalcédoine, et ne reconnaissent pas le pape de Rome. Ils sont plus de 200 millions.", "examples": [{"text": "Eleni est orthodoxe grecque : elle appartient aux orthodoxes byzantins.", "translation": "Elle n''est ni copte ni catholique."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_eglise_catholique', 'eg', 'l''Église catholique', 'la plus grande Église chrétienne, dirigée par le pape à Rome', 'Environ 1,4 milliard de fidèles. Son chef est le pape, évêque de Rome. À côté de l''Église latine, il existe des Églises catholiques orientales qui reconnaissent aussi le pape.', '[{"text": "Marc fait partie de l''Église catholique.", "translation": "Il reconnaît le pape comme chef de son Église."}]'::jsonb, null, '{"id": "eg.d.c07_eglise_catholique", "unitId": "eg.v.c07_eglise_catholique", "word": "l''Église catholique", "translation": "la plus grande Église chrétienne, dirigée par le pape à Rome", "partOfSpeech": "organization", "collection": "eglise", "explanation": "Environ 1,4 milliard de fidèles. Son chef est le pape, évêque de Rome. À côté de l''Église latine, il existe des Églises catholiques orientales qui reconnaissent aussi le pape.", "examples": [{"text": "Marc fait partie de l''Église catholique.", "translation": "Il reconnaît le pape comme chef de son Église."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_protestantisme', 'eg', 'le protestantisme', 'ensemble d''Églises nées de la Réforme du XVIe siècle', 'Luthériens, réformés, anglicans, baptistes, pentecôtistes… Les protestants n''ont pas de chef unique. Leur principe : la Bible seule suffit. Tous confessent la Trinité.', '[{"text": "Sarah est protestante, mais elle n''appartient pas à « l''Église protestante ».", "translation": "Il existe de nombreuses Églises protestantes."}]'::jsonb, null, '{"id": "eg.d.c07_protestantisme", "unitId": "eg.v.c07_protestantisme", "word": "le protestantisme", "translation": "ensemble d''Églises nées de la Réforme du XVIe siècle", "partOfSpeech": "organization", "collection": "eglise", "explanation": "Luthériens, réformés, anglicans, baptistes, pentecôtistes… Les protestants n''ont pas de chef unique. Leur principe : la Bible seule suffit. Tous confessent la Trinité.", "examples": [{"text": "Sarah est protestante, mais elle n''appartient pas à « l''Église protestante ».", "translation": "Il existe de nombreuses Églises protestantes."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_patriarcat_grec', 'eg', 'le patriarcat grec d''Alexandrie', 'Église orthodoxe byzantine d''Égypte, distincte de l''Église copte', 'En Égypte, il y a deux patriarches d''Alexandrie : le pape copte et le patriarche grec orthodoxe. Le second appartient aux orthodoxes byzantins et reçoit Chalcédoine.', '[{"text": "Le patriarche grec d''Alexandrie n''est pas notre pape.", "translation": "Les deux Églises sont distinctes."}]'::jsonb, null, '{"id": "eg.d.c07_patriarcat_grec", "unitId": "eg.v.c07_patriarcat_grec", "word": "le patriarcat grec d''Alexandrie", "translation": "Église orthodoxe byzantine d''Égypte, distincte de l''Église copte", "partOfSpeech": "organization", "collection": "eglise", "explanation": "En Égypte, il y a deux patriarches d''Alexandrie : le pape copte et le patriarche grec orthodoxe. Le second appartient aux orthodoxes byzantins et reçoit Chalcédoine.", "examples": [{"text": "Le patriarche grec d''Alexandrie n''est pas notre pape.", "translation": "Les deux Églises sont distinctes."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_de_deux_natures', 'eg', '« de deux natures »', 'formule d''Alexandrie : le Christ vient de deux natures, unies en une', 'Alexandrie accepte de dire que le Christ est « de deux natures », la divine et l''humaine, mais refuse « en deux natures » après l''union, qui lui paraît diviser le Christ.', '[{"text": "Nous disons « de deux natures » : le Christ est un seul.", "translation": "La divinité et l''humanité sont unies sans mélange."}]'::jsonb, null, '{"id": "eg.d.c07_de_deux_natures", "unitId": "eg.v.c07_de_deux_natures", "word": "« de deux natures »", "translation": "formule d''Alexandrie : le Christ vient de deux natures, unies en une", "partOfSpeech": "concept", "collection": "notion", "explanation": "Alexandrie accepte de dire que le Christ est « de deux natures », la divine et l''humaine, mais refuse « en deux natures » après l''union, qui lui paraît diviser le Christ.", "examples": [{"text": "Nous disons « de deux natures » : le Christ est un seul.", "translation": "La divinité et l''humanité sont unies sans mélange."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_sept_conciles', 'eg', 'les sept conciles', 'les conciles reçus par les orthodoxes byzantins, jusqu''à Nicée II (787)', 'Les orthodoxes byzantins reçoivent sept conciles : Nicée, Constantinople, Éphèse, Chalcédoine, Constantinople II, Constantinople III et Nicée II (787), qui défend les icônes. Nous en recevons trois.', '[{"text": "Eleni reçoit sept conciles, et nous trois.", "translation": "Les listes diffèrent, mais les icônes nous sont chères aussi."}]'::jsonb, null, '{"id": "eg.d.c07_sept_conciles", "unitId": "eg.v.c07_sept_conciles", "word": "les sept conciles", "translation": "les conciles reçus par les orthodoxes byzantins, jusqu''à Nicée II (787)", "partOfSpeech": "event", "collection": "concile", "explanation": "Les orthodoxes byzantins reçoivent sept conciles : Nicée, Constantinople, Éphèse, Chalcédoine, Constantinople II, Constantinople III et Nicée II (787), qui défend les icônes. Nous en recevons trois.", "examples": [{"text": "Eleni reçoit sept conciles, et nous trois.", "translation": "Les listes diffèrent, mais les icônes nous sont chères aussi."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_pape_de_rome', 'eg', 'le pape de Rome', 'pour les catholiques, évêque de Rome et successeur de saint Pierre', 'Les catholiques voient dans l''évêque de Rome le successeur de saint Pierre, à qui Jésus dit « sur cette pierre je bâtirai mon Église » (Matthieu 16, 18). Il est pour eux le chef visible de toute l''Église.', '[{"text": "Marc reconnaît le pape de Rome comme chef de l''Église.", "translation": "Nous honorons Rome, mais nous ne le suivons pas comme chef."}]'::jsonb, null, '{"id": "eg.d.c07_pape_de_rome", "unitId": "eg.v.c07_pape_de_rome", "word": "le pape de Rome", "translation": "pour les catholiques, évêque de Rome et successeur de saint Pierre", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les catholiques voient dans l''évêque de Rome le successeur de saint Pierre, à qui Jésus dit « sur cette pierre je bâtirai mon Église » (Matthieu 16, 18). Il est pour eux le chef visible de toute l''Église.", "examples": [{"text": "Marc reconnaît le pape de Rome comme chef de l''Église.", "translation": "Nous honorons Rome, mais nous ne le suivons pas comme chef."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_primaute', 'eg', 'la primauté du pape', 'autorité que les catholiques reconnaissent au pape sur toute l''Église', 'Pour les catholiques, la primauté du pape est une vraie autorité sur toute l''Église, pas seulement un honneur. C''est la différence la plus visible avec les orthodoxes.', '[{"text": "Les catholiques parlent de primauté, pas seulement d''honneur.", "translation": "Nous, nous parlons de décisions prises en concile."}]'::jsonb, null, '{"id": "eg.d.c07_primaute", "unitId": "eg.v.c07_primaute", "word": "la primauté du pape", "translation": "autorité que les catholiques reconnaissent au pape sur toute l''Église", "partOfSpeech": "concept", "collection": "notion", "explanation": "Pour les catholiques, la primauté du pape est une vraie autorité sur toute l''Église, pas seulement un honneur. C''est la différence la plus visible avec les orthodoxes.", "examples": [{"text": "Les catholiques parlent de primauté, pas seulement d''honneur.", "translation": "Nous, nous parlons de décisions prises en concile."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_infaillibilite', 'eg', 'l''infaillibilité pontificale', 'dogme de 1870 : le pape ne se trompe pas quand il enseigne ex cathedra', 'Ex cathedra veut dire « depuis la chaire » : quand le pape enseigne solennellement sur la foi et la morale. Cela ne veut pas dire qu''il ne peut pas pécher.', '[{"text": "L''infaillibilité ne concerne que l''enseignement solennel.", "translation": "Un pape reste un homme qui peut pécher."}]'::jsonb, null, '{"id": "eg.d.c07_infaillibilite", "unitId": "eg.v.c07_infaillibilite", "word": "l''infaillibilité pontificale", "translation": "dogme de 1870 : le pape ne se trompe pas quand il enseigne ex cathedra", "partOfSpeech": "concept", "collection": "notion", "explanation": "Ex cathedra veut dire « depuis la chaire » : quand le pape enseigne solennellement sur la foi et la morale. Cela ne veut pas dire qu''il ne peut pas pécher.", "examples": [{"text": "L''infaillibilité ne concerne que l''enseignement solennel.", "translation": "Un pape reste un homme qui peut pécher."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_vatican_i', 'eg', 'Vatican I', 'concile catholique de 1869-1870 qui définit l''infaillibilité du pape', 'Vatican I est le concile de l''Église catholique tenu à Rome en 1869-1870. Il y définit l''infaillibilité pontificale. L''Église copte n''y a pas pris part.', '[{"text": "Vatican I a lieu en 1869-1870.", "translation": "L''infaillibilité date donc de 1870."}]'::jsonb, null, '{"id": "eg.d.c07_vatican_i", "unitId": "eg.v.c07_vatican_i", "word": "Vatican I", "translation": "concile catholique de 1869-1870 qui définit l''infaillibilité du pape", "partOfSpeech": "event", "collection": "concile", "explanation": "Vatican I est le concile de l''Église catholique tenu à Rome en 1869-1870. Il y définit l''infaillibilité pontificale. L''Église copte n''y a pas pris part.", "examples": [{"text": "Vatican I a lieu en 1869-1870.", "translation": "L''infaillibilité date donc de 1870."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_filioque', 'eg', 'Filioque', 'ajout latin « et du Fils » au Credo de Nicée-Constantinople', 'Filioque veut dire « et du Fils ». Cet ajout apparaît en Occident, à Tolède en 589, et Rome l''accepte en 1014. L''Église copte, comme les orthodoxes byzantins, garde le texte de 381.', '[{"text": "Le Credo de 381 ne contient pas le Filioque.", "translation": "L''Esprit procède du Père, selon Jean 15, 26."}]'::jsonb, null, '{"id": "eg.d.c07_filioque", "unitId": "eg.v.c07_filioque", "word": "Filioque", "translation": "ajout latin « et du Fils » au Credo de Nicée-Constantinople", "partOfSpeech": "concept", "collection": "notion", "explanation": "Filioque veut dire « et du Fils ». Cet ajout apparaît en Occident, à Tolède en 589, et Rome l''accepte en 1014. L''Église copte, comme les orthodoxes byzantins, garde le texte de 381.", "examples": [{"text": "Le Credo de 381 ne contient pas le Filioque.", "translation": "L''Esprit procède du Père, selon Jean 15, 26."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_schisme_1054', 'eg', 'le schisme de 1054', 'rupture entre l''Église de Rome et celle de Constantinople', 'Le 16 juillet 1054, un légat du pape dépose à Sainte-Sophie une bulle d''excommunication contre le patriarche de Constantinople, qui répond de même. Les excommunications sont levées en 1965.', '[{"text": "Le schisme de 1054 est la rupture entre Rome et Constantinople.", "translation": "Il ne concerne pas directement l''Église copte."}]'::jsonb, null, '{"id": "eg.d.c07_schisme_1054", "unitId": "eg.v.c07_schisme_1054", "word": "le schisme de 1054", "translation": "rupture entre l''Église de Rome et celle de Constantinople", "partOfSpeech": "date", "collection": "date", "explanation": "Le 16 juillet 1054, un légat du pape dépose à Sainte-Sophie une bulle d''excommunication contre le patriarche de Constantinople, qui répond de même. Les excommunications sont levées en 1965.", "examples": [{"text": "Le schisme de 1054 est la rupture entre Rome et Constantinople.", "translation": "Il ne concerne pas directement l''Église copte."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_declaration_1973', 'eg', 'la déclaration de 1973', 'texte signé par Chenouda III et Paul VI sur la foi dans le Christ', 'En 1973, le pape copte Chenouda III visite le pape Paul VI. Ils signent une déclaration commune sur le Christ, parfait Dieu et parfait homme. En 2017, François et Tawadros II reconnaissent mutuellement leur baptême.', '[{"text": "En 1973, Chenouda III et Paul VI signent une déclaration commune.", "translation": "Il y a dialogue et amitié, pas encore communion."}]'::jsonb, null, '{"id": "eg.d.c07_declaration_1973", "unitId": "eg.v.c07_declaration_1973", "word": "la déclaration de 1973", "translation": "texte signé par Chenouda III et Paul VI sur la foi dans le Christ", "partOfSpeech": "date", "collection": "date", "explanation": "En 1973, le pape copte Chenouda III visite le pape Paul VI. Ils signent une déclaration commune sur le Christ, parfait Dieu et parfait homme. En 2017, François et Tawadros II reconnaissent mutuellement leur baptême.", "examples": [{"text": "En 1973, Chenouda III et Paul VI signent une déclaration commune.", "translation": "Il y a dialogue et amitié, pas encore communion."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_immaculee_conception', 'eg', 'l''Immaculée Conception', 'dogme catholique de 1854 : Marie conçue sans péché originel', 'En 1854, le pape Pie IX définit que Marie a été conçue sans péché originel. Cela concerne Marie, pas Jésus. L''Église copte vénère Marie toute pure mais ne suit pas ce dogme.', '[{"text": "L''Immaculée Conception est un dogme catholique de 1854.", "translation": "Il concerne la conception de Marie."}]'::jsonb, null, '{"id": "eg.d.c07_immaculee_conception", "unitId": "eg.v.c07_immaculee_conception", "word": "l''Immaculée Conception", "translation": "dogme catholique de 1854 : Marie conçue sans péché originel", "partOfSpeech": "concept", "collection": "notion", "explanation": "En 1854, le pape Pie IX définit que Marie a été conçue sans péché originel. Cela concerne Marie, pas Jésus. L''Église copte vénère Marie toute pure mais ne suit pas ce dogme.", "examples": [{"text": "L''Immaculée Conception est un dogme catholique de 1854.", "translation": "Il concerne la conception de Marie."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_peche_originel', 'eg', 'le péché originel', 'faute d''Adam dont les catholiques disent qu''elle touche chacun dès sa conception', 'Pour la tradition latine, héritée de saint Augustin, le péché d''Adam se transmet dès la conception. Les orthodoxes ne suivent pas cette doctrine du péché transmis.', '[{"text": "Pour Augustin, le péché originel se transmet à la conception.", "translation": "De là vient la logique de l''Immaculée Conception."}]'::jsonb, null, '{"id": "eg.d.c07_peche_originel", "unitId": "eg.v.c07_peche_originel", "word": "le péché originel", "translation": "faute d''Adam dont les catholiques disent qu''elle touche chacun dès sa conception", "partOfSpeech": "concept", "collection": "notion", "explanation": "Pour la tradition latine, héritée de saint Augustin, le péché d''Adam se transmet dès la conception. Les orthodoxes ne suivent pas cette doctrine du péché transmis.", "examples": [{"text": "Pour Augustin, le péché originel se transmet à la conception.", "translation": "De là vient la logique de l''Immaculée Conception."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_purgatoire', 'eg', 'le purgatoire', 'dans la foi catholique, purification après la mort avant d''entrer au ciel', 'Les catholiques disent que ceux qui meurent en grâce, mais pas totalement purifiés, passent par le purgatoire avant le ciel. Précisé au concile de Lyon II (1274). L''Église copte ne l''enseigne pas.', '[{"text": "Le purgatoire est une doctrine catholique de 1274.", "translation": "Les Coptes n''enseignent pas cette doctrine."}]'::jsonb, null, '{"id": "eg.d.c07_purgatoire", "unitId": "eg.v.c07_purgatoire", "word": "le purgatoire", "translation": "dans la foi catholique, purification après la mort avant d''entrer au ciel", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les catholiques disent que ceux qui meurent en grâce, mais pas totalement purifiés, passent par le purgatoire avant le ciel. Précisé au concile de Lyon II (1274). L''Église copte ne l''enseigne pas.", "examples": [{"text": "Le purgatoire est une doctrine catholique de 1274.", "translation": "Les Coptes n''enseignent pas cette doctrine."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_prieres_defunts', 'eg', 'les prières pour les défunts', 'prières de l''Église pour les morts, aux 3e, 7e et 40e jours', 'L''Église copte prie pour ceux qui sont morts, aux 3e, 7e et 40e jours. Elle les confie à la miséricorde de Dieu et lui laisse le jugement.', '[{"text": "On prie pour le défunt au 40e jour.", "translation": "Dieu seul juge."}]'::jsonb, null, '{"id": "eg.d.c07_prieres_defunts", "unitId": "eg.v.c07_prieres_defunts", "word": "les prières pour les défunts", "translation": "prières de l''Église pour les morts, aux 3e, 7e et 40e jours", "partOfSpeech": "concept", "collection": "priere", "explanation": "L''Église copte prie pour ceux qui sont morts, aux 3e, 7e et 40e jours. Elle les confie à la miséricorde de Dieu et lui laisse le jugement.", "examples": [{"text": "On prie pour le défunt au 40e jour.", "translation": "Dieu seul juge."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_azymes', 'eg', 'les azymes', 'pain sans levain utilisé par l''Église latine pour l''eucharistie', 'Les catholiques latins consacrent du pain azyme, sans levain : l''hostie, mince et ronde. Ce point a pesé dans la rupture de 1054.', '[{"text": "Marc reçoit une hostie, du pain azyme.", "translation": "C''est un pain sans levain."}]'::jsonb, null, '{"id": "eg.d.c07_azymes", "unitId": "eg.v.c07_azymes", "word": "les azymes", "translation": "pain sans levain utilisé par l''Église latine pour l''eucharistie", "partOfSpeech": "concept", "collection": "objet", "explanation": "Les catholiques latins consacrent du pain azyme, sans levain : l''hostie, mince et ronde. Ce point a pesé dans la rupture de 1054.", "examples": [{"text": "Marc reçoit une hostie, du pain azyme.", "translation": "C''est un pain sans levain."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_pain_leve', 'eg', 'le pain levé', 'pain fait avec du levain, utilisé dans l''Église copte pour l''eucharistie', 'L''Église copte, comme les orthodoxes byzantins, consacre un pain levé, préparé pour la messe et estampillé d''une croix. Il est vivant : il évoque la Résurrection.', '[{"text": "Chez nous, le pain de l''offrande est levé.", "translation": "Le levain fait gonfler le pain, signe de vie."}]'::jsonb, null, '{"id": "eg.d.c07_pain_leve", "unitId": "eg.v.c07_pain_leve", "word": "le pain levé", "translation": "pain fait avec du levain, utilisé dans l''Église copte pour l''eucharistie", "partOfSpeech": "concept", "collection": "objet", "explanation": "L''Église copte, comme les orthodoxes byzantins, consacre un pain levé, préparé pour la messe et estampillé d''une croix. Il est vivant : il évoque la Résurrection.", "examples": [{"text": "Chez nous, le pain de l''offrande est levé.", "translation": "Le levain fait gonfler le pain, signe de vie."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_celibat', 'eg', 'le célibat des prêtres', 'règle de l''Église latine : les prêtres ne se marient pas', 'Dans l''Église latine, les prêtres sont en général célibataires, règle affermie au XIIe siècle. Chez les Coptes, un homme peut devenir prêtre s''il est marié avant l''ordination ; les évêques sont choisis parmi les moines.', '[{"text": "Le célibat des prêtres est la règle de l''Église latine.", "translation": "Chez les Coptes, un prêtre peut être marié."}]'::jsonb, null, '{"id": "eg.d.c07_celibat", "unitId": "eg.v.c07_celibat", "word": "le célibat des prêtres", "translation": "règle de l''Église latine : les prêtres ne se marient pas", "partOfSpeech": "concept", "collection": "notion", "explanation": "Dans l''Église latine, les prêtres sont en général célibataires, règle affermie au XIIe siècle. Chez les Coptes, un homme peut devenir prêtre s''il est marié avant l''ordination ; les évêques sont choisis parmi les moines.", "examples": [{"text": "Le célibat des prêtres est la règle de l''Église latine.", "translation": "Chez les Coptes, un prêtre peut être marié."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_catholique_copte', 'eg', 'l''Église catholique copte', 'Église copte en communion avec le pape de Rome, distincte de la nôtre', 'Elle garde la liturgie copte mais reconnaît le pape de Rome. C''est une Église catholique orientale, distincte de l''Église copte orthodoxe. Ses prêtres peuvent être mariés.', '[{"text": "L''Église catholique copte reconnaît le pape.", "translation": "Elle n''est pas la même Église que la nôtre."}]'::jsonb, null, '{"id": "eg.d.c07_catholique_copte", "unitId": "eg.v.c07_catholique_copte", "word": "l''Église catholique copte", "translation": "Église copte en communion avec le pape de Rome, distincte de la nôtre", "partOfSpeech": "organization", "collection": "eglise", "explanation": "Elle garde la liturgie copte mais reconnaît le pape de Rome. C''est une Église catholique orientale, distincte de l''Église copte orthodoxe. Ses prêtres peuvent être mariés.", "examples": [{"text": "L''Église catholique copte reconnaît le pape.", "translation": "Elle n''est pas la même Église que la nôtre."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_95_theses', 'eg', 'les 95 thèses (1517)', 'texte de Luther contre les indulgences, traditionnellement affiché le 31 octobre 1517', 'Martin Luther, moine et professeur à Wittenberg, écrit 95 thèses contre la vente des indulgences. Selon la tradition, il les affiche le 31 octobre 1517. L''imprimerie les diffuse vite.', '[{"text": "En 1517, Luther publie ses 95 thèses.", "translation": "C''est le début de la Réforme."}]'::jsonb, null, '{"id": "eg.d.c07_95_theses", "unitId": "eg.v.c07_95_theses", "word": "les 95 thèses (1517)", "translation": "texte de Luther contre les indulgences, traditionnellement affiché le 31 octobre 1517", "partOfSpeech": "date", "collection": "date", "explanation": "Martin Luther, moine et professeur à Wittenberg, écrit 95 thèses contre la vente des indulgences. Selon la tradition, il les affiche le 31 octobre 1517. L''imprimerie les diffuse vite.", "examples": [{"text": "En 1517, Luther publie ses 95 thèses.", "translation": "C''est le début de la Réforme."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_reforme', 'eg', 'la Réforme', 'mouvement religieux du XVIe siècle qui crée le protestantisme', 'Commencée avec Luther en 1517, elle se prolonge avec Calvin à Genève et avec Henri VIII en Angleterre (1534). Le mot « protestant » vient de la protestation de Spire, en 1529.', '[{"text": "La Réforme donne naissance aux luthériens, aux réformés et aux anglicans.", "translation": "Les protestants viennent tous de ce mouvement."}]'::jsonb, null, '{"id": "eg.d.c07_reforme", "unitId": "eg.v.c07_reforme", "word": "la Réforme", "translation": "mouvement religieux du XVIe siècle qui crée le protestantisme", "partOfSpeech": "concept", "collection": "notion", "explanation": "Commencée avec Luther en 1517, elle se prolonge avec Calvin à Genève et avec Henri VIII en Angleterre (1534). Le mot « protestant » vient de la protestation de Spire, en 1529.", "examples": [{"text": "La Réforme donne naissance aux luthériens, aux réformés et aux anglicans.", "translation": "Les protestants viennent tous de ce mouvement."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_sola_scriptura', 'eg', 'sola scriptura', 'principe protestant : l''Écriture seule est l''autorité de la foi', 'Mots latins pour « l''Écriture seule ». Les réformateurs veulent revenir à la Bible. L''Église copte répond que la Bible est née dans l''Église et s''accompagne de la Sainte Tradition (2 Thessaloniciens 2, 15).', '[{"text": "Sarah défend sola scriptura.", "translation": "Pour elle, la Bible suffit."}]'::jsonb, null, '{"id": "eg.d.c07_sola_scriptura", "unitId": "eg.v.c07_sola_scriptura", "word": "sola scriptura", "translation": "principe protestant : l''Écriture seule est l''autorité de la foi", "partOfSpeech": "concept", "collection": "notion", "explanation": "Mots latins pour « l''Écriture seule ». Les réformateurs veulent revenir à la Bible. L''Église copte répond que la Bible est née dans l''Église et s''accompagne de la Sainte Tradition (2 Thessaloniciens 2, 15).", "examples": [{"text": "Sarah défend sola scriptura.", "translation": "Pour elle, la Bible suffit."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_deuterocanoniques', 'eg', 'les livres deutérocanoniques', 'livres de l''Ancien Testament gardés par les Coptes, absents de la Bible protestante', 'Tobie, Judith, la Sagesse, le Siracide, Baruch, les Maccabées… Ils viennent de la Septante, la Bible grecque traduite à Alexandrie. Les protestants n''en gardent pas.', '[{"text": "L''Église copte lit Judith et Tobie.", "translation": "Ce sont des livres deutérocanoniques."}]'::jsonb, null, '{"id": "eg.d.c07_deuterocanoniques", "unitId": "eg.v.c07_deuterocanoniques", "word": "les livres deutérocanoniques", "translation": "livres de l''Ancien Testament gardés par les Coptes, absents de la Bible protestante", "partOfSpeech": "work", "collection": "livre", "explanation": "Tobie, Judith, la Sagesse, le Siracide, Baruch, les Maccabées… Ils viennent de la Septante, la Bible grecque traduite à Alexandrie. Les protestants n''en gardent pas.", "examples": [{"text": "L''Église copte lit Judith et Tobie.", "translation": "Ce sont des livres deutérocanoniques."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_sola_fide', 'eg', 'sola fide', 'principe protestant : le salut vient par la foi seule', 'Mots latins pour « par la foi seule ». Luther lit Romains 3, 28 et refuse qu''on achète le salut. L''Église copte cite Jacques 2, 24 et voit les œuvres comme le fruit de la grâce.', '[{"text": "Pour Luther, sola fide est le cœur de l''Évangile.", "translation": "Nous répondons : la foi et les œuvres vont ensemble."}]'::jsonb, null, '{"id": "eg.d.c07_sola_fide", "unitId": "eg.v.c07_sola_fide", "word": "sola fide", "translation": "principe protestant : le salut vient par la foi seule", "partOfSpeech": "concept", "collection": "notion", "explanation": "Mots latins pour « par la foi seule ». Luther lit Romains 3, 28 et refuse qu''on achète le salut. L''Église copte cite Jacques 2, 24 et voit les œuvres comme le fruit de la grâce.", "examples": [{"text": "Pour Luther, sola fide est le cœur de l''Évangile.", "translation": "Nous répondons : la foi et les œuvres vont ensemble."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_anglicans', 'eg', 'les anglicans', 'protestants d''Angleterre, nés de la rupture d''Henri VIII avec Rome (1534)', 'Les anglicans naissent quand le roi Henri VIII rompt avec Rome en 1534. Ils baptisent les enfants et gardent une organisation en évêques.', '[{"text": "Les anglicans viennent de la rupture de 1534.", "translation": "Ils ne viennent pas de Luther."}]'::jsonb, null, '{"id": "eg.d.c07_anglicans", "unitId": "eg.v.c07_anglicans", "word": "les anglicans", "translation": "protestants d''Angleterre, nés de la rupture d''Henri VIII avec Rome (1534)", "partOfSpeech": "organization", "collection": "eglise", "explanation": "Les anglicans naissent quand le roi Henri VIII rompt avec Rome en 1534. Ils baptisent les enfants et gardent une organisation en évêques.", "examples": [{"text": "Les anglicans viennent de la rupture de 1534.", "translation": "Ils ne viennent pas de Luther."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_baptistes', 'eg', 'les baptistes', 'protestants qui ne baptisent que les adultes qui croient', 'Les baptistes pensent que le baptême suppose une foi personnelle. Ils ne baptisent donc pas les petits enfants, contrairement aux luthériens, aux anglicans et à l''Église copte.', '[{"text": "Les baptistes baptisent les adultes qui croient.", "translation": "Ils sont une des Églises protestantes."}]'::jsonb, null, '{"id": "eg.d.c07_baptistes", "unitId": "eg.v.c07_baptistes", "word": "les baptistes", "translation": "protestants qui ne baptisent que les adultes qui croient", "partOfSpeech": "organization", "collection": "eglise", "explanation": "Les baptistes pensent que le baptême suppose une foi personnelle. Ils ne baptisent donc pas les petits enfants, contrairement aux luthériens, aux anglicans et à l''Église copte.", "examples": [{"text": "Les baptistes baptisent les adultes qui croient.", "translation": "Ils sont une des Églises protestantes."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_eglise_evangelique', 'eg', 'l''Église évangélique d''Égypte', 'Église presbytérienne d''Égypte, née de la mission américaine de 1854', 'En 1854, la mission presbytérienne américaine s''installe en Égypte, ouvre des écoles et des hôpitaux. L''Église évangélique d''Égypte en est née : c''est la plus grande Église protestante du pays.', '[{"text": "L''Église évangélique d''Égypte est née en 1854.", "translation": "Évangéliques et Coptes sont frères en Christ."}]'::jsonb, null, '{"id": "eg.d.c07_eglise_evangelique", "unitId": "eg.v.c07_eglise_evangelique", "word": "l''Église évangélique d''Égypte", "translation": "Église presbytérienne d''Égypte, née de la mission américaine de 1854", "partOfSpeech": "organization", "collection": "eglise", "explanation": "En 1854, la mission presbytérienne américaine s''installe en Égypte, ouvre des écoles et des hôpitaux. L''Église évangélique d''Égypte en est née : c''est la plus grande Église protestante du pays.", "examples": [{"text": "L''Église évangélique d''Égypte est née en 1854.", "translation": "Évangéliques et Coptes sont frères en Christ."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_sept_sacrements', 'eg', 'les sept sacrements', 'baptême, chrismation, eucharistie, confession, onction des malades, mariage, sacerdoce', 'Un sacrement est un signe visible par lequel Dieu donne sa grâce. L''Église copte en compte sept. La plupart des protestants n''en gardent que deux : le baptême et la Cène.', '[{"text": "L''Église copte a sept sacrements.", "translation": "La plupart des protestants en ont deux."}]'::jsonb, null, '{"id": "eg.d.c07_sept_sacrements", "unitId": "eg.v.c07_sept_sacrements", "word": "les sept sacrements", "translation": "baptême, chrismation, eucharistie, confession, onction des malades, mariage, sacerdoce", "partOfSpeech": "concept", "collection": "notion", "explanation": "Un sacrement est un signe visible par lequel Dieu donne sa grâce. L''Église copte en compte sept. La plupart des protestants n''en gardent que deux : le baptême et la Cène.", "examples": [{"text": "L''Église copte a sept sacrements.", "translation": "La plupart des protestants en ont deux."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_intercession', 'eg', 'l''intercession des saints', 'prière des saints pour nous, qu''on leur demande comme à des frères', 'Les saints sont vivants en Christ (Luc 20, 38). On leur demande de prier pour nous, comme on demande à un frère. Cela n''ôte rien au Christ, seul médiateur.', '[{"text": "Nous demandons aux saints de prier pour nous.", "translation": "Ce n''est pas les adorer."}]'::jsonb, null, '{"id": "eg.d.c07_intercession", "unitId": "eg.v.c07_intercession", "word": "l''intercession des saints", "translation": "prière des saints pour nous, qu''on leur demande comme à des frères", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les saints sont vivants en Christ (Luc 20, 38). On leur demande de prier pour nous, comme on demande à un frère. Cela n''ôte rien au Christ, seul médiateur.", "examples": [{"text": "Nous demandons aux saints de prier pour nous.", "translation": "Ce n''est pas les adorer."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_veneration', 'eg', 'la vénération', 'honneur rendu aux saints et aux icônes, différent de l''adoration', 'L''adoration est due à Dieu seul. Vénérer, c''est honorer, comme Paul le demande en Romains 13, 7. L''honneur rendu à l''image passe à celui qu''elle représente.', '[{"text": "On vénère un saint, on adore Dieu seul.", "translation": "Cette distinction répond au reproche d''idolâtrie."}]'::jsonb, null, '{"id": "eg.d.c07_veneration", "unitId": "eg.v.c07_veneration", "word": "la vénération", "translation": "honneur rendu aux saints et aux icônes, différent de l''adoration", "partOfSpeech": "concept", "collection": "notion", "explanation": "L''adoration est due à Dieu seul. Vénérer, c''est honorer, comme Paul le demande en Romains 13, 7. L''honneur rendu à l''image passe à celui qu''elle représente.", "examples": [{"text": "On vénère un saint, on adore Dieu seul.", "translation": "Cette distinction répond au reproche d''idolâtrie."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_icone', 'eg', 'l''icône', 'image sacrée qui représente le Christ, Marie ou un saint', 'Dieu s''est rendu visible en Jésus-Christ : c''est le fondement des icônes. Saint Basile dit que l''honneur rendu à l''image passe au modèle. L''icône est une fenêtre, jamais une idole.', '[{"text": "Une icône du Christ est au cœur de l''église.", "translation": "Elle montre celui qu''elle représente, elle ne le remplace pas."}]'::jsonb, null, '{"id": "eg.d.c07_icone", "unitId": "eg.v.c07_icone", "word": "l''icône", "translation": "image sacrée qui représente le Christ, Marie ou un saint", "partOfSpeech": "concept", "collection": "objet", "explanation": "Dieu s''est rendu visible en Jésus-Christ : c''est le fondement des icônes. Saint Basile dit que l''honneur rendu à l''image passe au modèle. L''icône est une fenêtre, jamais une idole.", "examples": [{"text": "Une icône du Christ est au cœur de l''église.", "translation": "Elle montre celui qu''elle représente, elle ne le remplace pas."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_mormons', 'eg', 'les mormons', 'membres de l''Église de Jésus-Christ des saints des derniers jours, fondée en 1830', 'Ils suivent Joseph Smith (1805-1844). Ils lisent la Bible, le Livre de Mormon et d''autres textes, bâtissent des temples et sont plus de 15 millions. Pour l''Église copte, leur doctrine de Dieu diffère de la Trinité.', '[{"text": "Lucas est mormon.", "translation": "Son Église est née aux États-Unis en 1830."}]'::jsonb, null, '{"id": "eg.d.c07_mormons", "unitId": "eg.v.c07_mormons", "word": "les mormons", "translation": "membres de l''Église de Jésus-Christ des saints des derniers jours, fondée en 1830", "partOfSpeech": "organization", "collection": "eglise", "explanation": "Ils suivent Joseph Smith (1805-1844). Ils lisent la Bible, le Livre de Mormon et d''autres textes, bâtissent des temples et sont plus de 15 millions. Pour l''Église copte, leur doctrine de Dieu diffère de la Trinité.", "examples": [{"text": "Lucas est mormon.", "translation": "Son Église est née aux États-Unis en 1830."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_livre_de_mormon', 'eg', 'le Livre de Mormon', 'livre sacré mormon, présenté comme traduit de plaques d''or', 'Joseph Smith le publie en 1830 et dit l''avoir traduit de plaques d''or. Les mormons le lisent à côté de la Bible. Pour nous, la foi a été transmise une fois pour toutes (Jude 3) : un livre nouveau n''est pas Écriture.', '[{"text": "Lucas lit le Livre de Mormon.", "translation": "Pour les mormons, il s''ajoute à la Bible."}]'::jsonb, null, '{"id": "eg.d.c07_livre_de_mormon", "unitId": "eg.v.c07_livre_de_mormon", "word": "le Livre de Mormon", "translation": "livre sacré mormon, présenté comme traduit de plaques d''or", "partOfSpeech": "work", "collection": "livre", "explanation": "Joseph Smith le publie en 1830 et dit l''avoir traduit de plaques d''or. Les mormons le lisent à côté de la Bible. Pour nous, la foi a été transmise une fois pour toutes (Jude 3) : un livre nouveau n''est pas Écriture.", "examples": [{"text": "Lucas lit le Livre de Mormon.", "translation": "Pour les mormons, il s''ajoute à la Bible."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_plaques_d_or', 'eg', 'les plaques d''or', 'objet que l''ange Moroni aurait indiqué à Joseph Smith', 'Selon les mormons, l''ange Moroni indique à Joseph Smith des plaques d''or enterrées. Il dit les avoir traduites : cela donne le Livre de Mormon. Les mormons les présentent comme la source du Livre de Mormon.', '[{"text": "Joseph Smith dit avoir traduit des plaques d''or.", "translation": "C''est l''origine du Livre de Mormon, selon les mormons."}]'::jsonb, null, '{"id": "eg.d.c07_plaques_d_or", "unitId": "eg.v.c07_plaques_d_or", "word": "les plaques d''or", "translation": "objet que l''ange Moroni aurait indiqué à Joseph Smith", "partOfSpeech": "concept", "collection": "objet", "explanation": "Selon les mormons, l''ange Moroni indique à Joseph Smith des plaques d''or enterrées. Il dit les avoir traduites : cela donne le Livre de Mormon. Les mormons les présentent comme la source du Livre de Mormon.", "examples": [{"text": "Joseph Smith dit avoir traduit des plaques d''or.", "translation": "C''est l''origine du Livre de Mormon, selon les mormons."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_adventistes', 'eg', 'les adventistes', 'chrétiens qui attendent le retour (l''avènement) du Christ et observent le samedi', 'Église adventiste du septième jour, organisée en 1863 à Battle Creek, dans le Michigan, avec Ellen White. Environ 22 millions de membres, des écoles et des hôpitaux. Ils croient à la Trinité.', '[{"text": "Anna est adventiste.", "translation": "Elle observe le samedi et croit à la Trinité."}]'::jsonb, null, '{"id": "eg.d.c07_adventistes", "unitId": "eg.v.c07_adventistes", "word": "les adventistes", "translation": "chrétiens qui attendent le retour (l''avènement) du Christ et observent le samedi", "partOfSpeech": "organization", "collection": "eglise", "explanation": "Église adventiste du septième jour, organisée en 1863 à Battle Creek, dans le Michigan, avec Ellen White. Environ 22 millions de membres, des écoles et des hôpitaux. Ils croient à la Trinité.", "examples": [{"text": "Anna est adventiste.", "translation": "Elle observe le samedi et croit à la Trinité."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_grande_deception', 'eg', 'la Grande Déception', 'échec de la prédiction du retour du Christ le 22 octobre 1844', 'William Miller, pasteur baptiste américain, avait calculé le retour du Christ pour le 22 octobre 1844. Rien ne se passe. Matthieu 24, 36 dit que nul ne connaît le jour ni l''heure.', '[{"text": "Après la Grande Déception, beaucoup quittent Miller.", "translation": "Un petit groupe continue et devient l''Église adventiste."}]'::jsonb, null, '{"id": "eg.d.c07_grande_deception", "unitId": "eg.v.c07_grande_deception", "word": "la Grande Déception", "translation": "échec de la prédiction du retour du Christ le 22 octobre 1844", "partOfSpeech": "date", "collection": "date", "explanation": "William Miller, pasteur baptiste américain, avait calculé le retour du Christ pour le 22 octobre 1844. Rien ne se passe. Matthieu 24, 36 dit que nul ne connaît le jour ni l''heure.", "examples": [{"text": "Après la Grande Déception, beaucoup quittent Miller.", "translation": "Un petit groupe continue et devient l''Église adventiste."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_sabbat_samedi', 'eg', 'le sabbat du samedi', 'jour de repos observé par les adventistes du septième jour', 'Les adventistes observent le sabbat le samedi, septième jour de la semaine. L''Église copte célèbre le jour du Seigneur le dimanche, jour de la Résurrection (Actes 20, 7).', '[{"text": "Anna garde le sabbat le samedi.", "translation": "Nous, nous célébrons le dimanche."}]'::jsonb, null, '{"id": "eg.d.c07_sabbat_samedi", "unitId": "eg.v.c07_sabbat_samedi", "word": "le sabbat du samedi", "translation": "jour de repos observé par les adventistes du septième jour", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les adventistes observent le sabbat le samedi, septième jour de la semaine. L''Église copte célèbre le jour du Seigneur le dimanche, jour de la Résurrection (Actes 20, 7).", "examples": [{"text": "Anna garde le sabbat le samedi.", "translation": "Nous, nous célébrons le dimanche."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_temoins_de_jehovah', 'eg', 'les témoins de Jéhovah', 'mouvement né dans les années 1870 autour de Charles Taze Russell', 'Fondé à Pittsburgh par Charles Taze Russell (1852-1916), il prend le nom de « témoins de Jéhovah » en 1931. Environ 8 millions de membres, connus pour leur porte-à-porte. Ils rejettent la Trinité.', '[{"text": "Daniel est témoin de Jéhovah.", "translation": "Il vient te parler de la Bible avec politesse."}]'::jsonb, null, '{"id": "eg.d.c07_temoins_de_jehovah", "unitId": "eg.v.c07_temoins_de_jehovah", "word": "les témoins de Jéhovah", "translation": "mouvement né dans les années 1870 autour de Charles Taze Russell", "partOfSpeech": "organization", "collection": "eglise", "explanation": "Fondé à Pittsburgh par Charles Taze Russell (1852-1916), il prend le nom de « témoins de Jéhovah » en 1931. Environ 8 millions de membres, connus pour leur porte-à-porte. Ils rejettent la Trinité.", "examples": [{"text": "Daniel est témoin de Jéhovah.", "translation": "Il vient te parler de la Bible avec politesse."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_traduction_monde_nouveau', 'eg', 'la Traduction du monde nouveau', 'Bible des témoins de Jéhovah', 'Publiée en 1961, c''est la Bible utilisée par les témoins de Jéhovah. Elle traduit Jean 1, 1 par « un dieu », alors que le grec ne le permet pas : « le Verbe était Dieu ».', '[{"text": "Daniel lit la Traduction du monde nouveau.", "translation": "C''est sa Bible, qui diffère de la nôtre sur Jean 1, 1."}]'::jsonb, null, '{"id": "eg.d.c07_traduction_monde_nouveau", "unitId": "eg.v.c07_traduction_monde_nouveau", "word": "la Traduction du monde nouveau", "translation": "Bible des témoins de Jéhovah", "partOfSpeech": "work", "collection": "livre", "explanation": "Publiée en 1961, c''est la Bible utilisée par les témoins de Jéhovah. Elle traduit Jean 1, 1 par « un dieu », alors que le grec ne le permet pas : « le Verbe était Dieu ».", "examples": [{"text": "Daniel lit la Traduction du monde nouveau.", "translation": "C''est sa Bible, qui diffère de la nôtre sur Jean 1, 1."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_144000', 'eg', 'les 144 000', 'nombre de ceux qui, selon les témoins de Jéhovah, vivent au ciel avec le Christ', 'Les témoins de Jéhovah lisent Apocalypse 7, 4 au sens propre : 144 000 fidèles vivent au ciel, les autres sur une terre paradisiaque. Nous y voyons un nombre symbolique de plénitude.', '[{"text": "Pour Daniel, seuls 144 000 vont au ciel.", "translation": "Nous y voyons un nombre de plénitude."}]'::jsonb, null, '{"id": "eg.d.c07_144000", "unitId": "eg.v.c07_144000", "word": "les 144 000", "translation": "nombre de ceux qui, selon les témoins de Jéhovah, vivent au ciel avec le Christ", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les témoins de Jéhovah lisent Apocalypse 7, 4 au sens propre : 144 000 fidèles vivent au ciel, les autres sur une terre paradisiaque. Nous y voyons un nombre symbolique de plénitude.", "examples": [{"text": "Pour Daniel, seuls 144 000 vont au ciel.", "translation": "Nous y voyons un nombre de plénitude."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_refus_transfusion', 'eg', 'le refus de la transfusion', 'pratique des témoins de Jéhovah fondée sur Actes 15, 20', 'Les témoins de Jéhovah refusent la transfusion sanguine en s''appuyant sur Actes 15, 20, mais acceptent les autres soins médicaux. Pour nous, la vie est un don de Dieu : on sauve une vie.', '[{"text": "Daniel refuse la transfusion, mais va chez le médecin.", "translation": "Il ne refuse pas tous les soins."}]'::jsonb, null, '{"id": "eg.d.c07_refus_transfusion", "unitId": "eg.v.c07_refus_transfusion", "word": "le refus de la transfusion", "translation": "pratique des témoins de Jéhovah fondée sur Actes 15, 20", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les témoins de Jéhovah refusent la transfusion sanguine en s''appuyant sur Actes 15, 20, mais acceptent les autres soins médicaux. Pour nous, la vie est un don de Dieu : on sauve une vie.", "examples": [{"text": "Daniel refuse la transfusion, mais va chez le médecin.", "translation": "Il ne refuse pas tous les soins."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_science_chretienne', 'eg', 'la Science chrétienne', 'mouvement fondé par Mary Baker Eddy en 1879 à Boston', 'Mary Baker Eddy (1821-1910) tombe sur la glace en 1866, lit Matthieu 9, 2 et se relève guérie. Elle fonde son Église à Boston en 1879. Pour elle, la matière et la maladie sont des illusions. Aucun rapport avec la scientologie.', '[{"text": "Claire est scientiste chrétienne.", "translation": "Son Église est née à Boston en 1879."}]'::jsonb, null, '{"id": "eg.d.c07_science_chretienne", "unitId": "eg.v.c07_science_chretienne", "word": "la Science chrétienne", "translation": "mouvement fondé par Mary Baker Eddy en 1879 à Boston", "partOfSpeech": "organization", "collection": "eglise", "explanation": "Mary Baker Eddy (1821-1910) tombe sur la glace en 1866, lit Matthieu 9, 2 et se relève guérie. Elle fonde son Église à Boston en 1879. Pour elle, la matière et la maladie sont des illusions. Aucun rapport avec la scientologie.", "examples": [{"text": "Claire est scientiste chrétienne.", "translation": "Son Église est née à Boston en 1879."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_science_et_sante', 'eg', 'Science et Santé', 'livre de Mary Baker Eddy publié en 1875, lu à côté de la Bible', 'Mary Baker Eddy le publie en 1875. Les fidèles de la Science chrétienne le lisent à côté de la Bible. Il enseigne que la matière, la maladie et la mort sont des illusions.', '[{"text": "Claire lit Science et Santé.", "translation": "C''est le livre qui s''ajoute à la Bible pour elle."}]'::jsonb, null, '{"id": "eg.d.c07_science_et_sante", "unitId": "eg.v.c07_science_et_sante", "word": "Science et Santé", "translation": "livre de Mary Baker Eddy publié en 1875, lu à côté de la Bible", "partOfSpeech": "work", "collection": "livre", "explanation": "Mary Baker Eddy le publie en 1875. Les fidèles de la Science chrétienne le lisent à côté de la Bible. Il enseigne que la matière, la maladie et la mort sont des illusions.", "examples": [{"text": "Claire lit Science et Santé.", "translation": "C''est le livre qui s''ajoute à la Bible pour elle."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_grande_apostasie', 'eg', 'la grande apostasie', 'idée de plusieurs groupes : l''Église des apôtres aurait disparu, il faudrait la restaurer', 'Plusieurs groupes récents disent que l''Église des apôtres a disparu et qu''ils la restaurent. L''Église copte répond par la promesse du Christ : « les portes du séjour des morts ne prévaudront point » (Matthieu 16, 18).', '[{"text": "Daniel et Lucas parlent d''une grande apostasie.", "translation": "Nous répondons : l''Église n''a jamais disparu."}]'::jsonb, null, '{"id": "eg.d.c07_grande_apostasie", "unitId": "eg.v.c07_grande_apostasie", "word": "la grande apostasie", "translation": "idée de plusieurs groupes : l''Église des apôtres aurait disparu, il faudrait la restaurer", "partOfSpeech": "concept", "collection": "notion", "explanation": "Plusieurs groupes récents disent que l''Église des apôtres a disparu et qu''ils la restaurent. L''Église copte répond par la promesse du Christ : « les portes du séjour des morts ne prévaudront point » (Matthieu 16, 18).", "examples": [{"text": "Daniel et Lucas parlent d''une grande apostasie.", "translation": "Nous répondons : l''Église n''a jamais disparu."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_douceur_respect', 'eg', 'la douceur et le respect', 'la manière de répondre demandée par saint Pierre (1 Pierre 3, 15)', 'Pierre demande de rendre compte de son espérance avec douceur et respect. On écoute, on dit ce que l''Église enseigne, sans moquerie, et on prie pour ses interlocuteurs.', '[{"text": "Nous répondons avec douceur et respect.", "translation": "On aime les personnes, même quand on ne partage pas leur foi."}]'::jsonb, null, '{"id": "eg.d.c07_douceur_respect", "unitId": "eg.v.c07_douceur_respect", "word": "la douceur et le respect", "translation": "la manière de répondre demandée par saint Pierre (1 Pierre 3, 15)", "partOfSpeech": "concept", "collection": "notion", "explanation": "Pierre demande de rendre compte de son espérance avec douceur et respect. On écoute, on dit ce que l''Église enseigne, sans moquerie, et on prie pour ses interlocuteurs.", "examples": [{"text": "Nous répondons avec douceur et respect.", "translation": "On aime les personnes, même quand on ne partage pas leur foi."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_trois_questions', 'eg', 'le test des trois questions', 'Chalcédoine ? pape ? Bible seule ? pour situer une Église', 'Pour situer une Église : reçoit-elle Chalcédoine ? Reconnaît-elle le pape ? La Bible seule suffit-elle ? Copte : non, non, non. Byzantin : oui, non, non. Catholique : oui, oui, non. Protestant : oui, non, oui.', '[{"text": "Avec le test des trois questions, tu situes une Église en dix secondes.", "translation": "Copte : non, non, non."}]'::jsonb, null, '{"id": "eg.d.c07_trois_questions", "unitId": "eg.v.c07_trois_questions", "word": "le test des trois questions", "translation": "Chalcédoine ? pape ? Bible seule ? pour situer une Église", "partOfSpeech": "concept", "collection": "notion", "explanation": "Pour situer une Église : reçoit-elle Chalcédoine ? Reconnaît-elle le pape ? La Bible seule suffit-elle ? Copte : non, non, non. Byzantin : oui, non, non. Catholique : oui, oui, non. Protestant : oui, non, oui.", "examples": [{"text": "Avec le test des trois questions, tu situes une Église en dix secondes.", "translation": "Copte : non, non, non."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c07_ce_qui_nous_unit', 'eg', 'ce qui nous unit', 'la Trinité et le Christ, vrai Dieu et vrai homme', 'Avec les catholiques, les orthodoxes byzantins et les protestants, nous confessons la Trinité et le Christ, vrai Dieu et vrai homme. On commence toujours une conversation par ce qu''on a en commun.', '[{"text": "Commence par ce qui nous unit.", "translation": "Ensuite seulement, tu diras la différence."}]'::jsonb, null, '{"id": "eg.d.c07_ce_qui_nous_unit", "unitId": "eg.v.c07_ce_qui_nous_unit", "word": "ce qui nous unit", "translation": "la Trinité et le Christ, vrai Dieu et vrai homme", "partOfSpeech": "concept", "collection": "notion", "explanation": "Avec les catholiques, les orthodoxes byzantins et les protestants, nous confessons la Trinité et le Christ, vrai Dieu et vrai homme. On commence toujours une conversation par ce qu''on a en commun.", "examples": [{"text": "Commence par ce qui nous unit.", "translation": "Ensuite seulement, tu diras la différence."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_credo', 'eg', 'le Credo', '« je crois » : le texte court qui résume la foi de l''Église', 'Credo est un mot latin qui veut dire « je crois ». C''est le texte que l''Église récite pour confesser sa foi. On l''appelle aussi symbole : un signe de reconnaissance entre chrétiens.', '[{"text": "Le Credo tient en quelques lignes.", "translation": "Toute la foi de l''Église y est résumée."}]'::jsonb, null, '{"id": "eg.d.c08_credo", "unitId": "eg.v.c08_credo", "word": "le Credo", "translation": "« je crois » : le texte court qui résume la foi de l''Église", "partOfSpeech": "concept", "collection": "notion", "explanation": "Credo est un mot latin qui veut dire « je crois ». C''est le texte que l''Église récite pour confesser sa foi. On l''appelle aussi symbole : un signe de reconnaissance entre chrétiens.", "examples": [{"text": "Le Credo tient en quelques lignes.", "translation": "Toute la foi de l''Église y est résumée."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_nous_croyons', 'eg', '« nous croyons »', 'le pluriel du Credo : la foi de toute l''Église', 'Le texte des conciles et la prière copte disent « nous croyons ». Celui qui le récite confesse avec les martyrs, les Pères et toute l''assemblée.', '[{"text": "Nous croyons en un seul Dieu.", "translation": "On ne croit pas seul : on croit avec toute l''Église."}]'::jsonb, null, '{"id": "eg.d.c08_nous_croyons", "unitId": "eg.v.c08_nous_croyons", "word": "« nous croyons »", "translation": "le pluriel du Credo : la foi de toute l''Église", "partOfSpeech": "expression", "collection": "priere", "explanation": "Le texte des conciles et la prière copte disent « nous croyons ». Celui qui le récite confesse avec les martyrs, les Pères et toute l''assemblée.", "examples": [{"text": "Nous croyons en un seul Dieu.", "translation": "On ne croit pas seul : on croit avec toute l''Église."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_catechumene', 'eg', 'le catéchumène', 'celui qui apprend la foi avant d''être baptisé', 'Le catéchumène est instruit dans la foi avant son baptême. Il la confesse en répondant à des questions : de ces confessions sont nés les credos.', '[{"text": "Le catéchumène répond : « Je crois ».", "translation": "Avant le baptême, on confesse sa foi."}]'::jsonb, null, '{"id": "eg.d.c08_catechumene", "unitId": "eg.v.c08_catechumene", "word": "le catéchumène", "translation": "celui qui apprend la foi avant d''être baptisé", "partOfSpeech": "person", "collection": "notion", "explanation": "Le catéchumène est instruit dans la foi avant son baptême. Il la confesse en répondant à des questions : de ces confessions sont nés les credos.", "examples": [{"text": "Le catéchumène répond : « Je crois ».", "translation": "Avant le baptême, on confesse sa foi."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_mere_de_la_vraie_lumiere', 'eg', 'Mère de la vraie lumière', 'titre de Marie dans l''introduction copte du Credo', 'Avant le Credo, l''Église copte prie : « Nous t''exaltons, Mère de la vraie lumière ». La tradition rattache cette introduction au concile d''Éphèse. Marie a enfanté le Christ, la Lumière venue du Père.', '[{"text": "Nous t''exaltons, Mère de la vraie lumière.", "translation": "On honore Marie avant de confesser la foi en son Fils."}]'::jsonb, null, '{"id": "eg.d.c08_mere_de_la_vraie_lumiere", "unitId": "eg.v.c08_mere_de_la_vraie_lumiere", "word": "Mère de la vraie lumière", "translation": "titre de Marie dans l''introduction copte du Credo", "partOfSpeech": "expression", "collection": "priere", "explanation": "Avant le Credo, l''Église copte prie : « Nous t''exaltons, Mère de la vraie lumière ». La tradition rattache cette introduction au concile d''Éphèse. Marie a enfanté le Christ, la Lumière venue du Père.", "examples": [{"text": "Nous t''exaltons, Mère de la vraie lumière.", "translation": "On honore Marie avant de confesser la foi en son Fils."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_monotheisme', 'eg', 'le monothéisme', 'la foi en un seul Dieu', 'Le monothéisme est la foi en un seul Dieu. Le Credo l''affirme dès sa première phrase, contre les dieux multiples du paganisme, contre Marcion et contre les gnostiques.', '[{"text": "Nous croyons en un seul Dieu.", "translation": "C''est la première affirmation du Credo."}]'::jsonb, null, '{"id": "eg.d.c08_monotheisme", "unitId": "eg.v.c08_monotheisme", "word": "le monothéisme", "translation": "la foi en un seul Dieu", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le monothéisme est la foi en un seul Dieu. Le Credo l''affirme dès sa première phrase, contre les dieux multiples du paganisme, contre Marcion et contre les gnostiques.", "examples": [{"text": "Nous croyons en un seul Dieu.", "translation": "C''est la première affirmation du Credo."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_dieu_le_pere', 'eg', 'Dieu le Père', 'la source de la Trinité : le Fils naît de lui, l''Esprit procède de lui', 'Dieu est Père d''abord parce qu''il a, de toute éternité, un Fils. Dans la Trinité, le Père est la source, sans être plus Dieu que le Fils et l''Esprit.', '[{"text": "Le Credo commence par le Père.", "translation": "Il commence par la source, avant le Fils et l''Esprit."}]'::jsonb, null, '{"id": "eg.d.c08_dieu_le_pere", "unitId": "eg.v.c08_dieu_le_pere", "word": "Dieu le Père", "translation": "la source de la Trinité : le Fils naît de lui, l''Esprit procède de lui", "partOfSpeech": "concept", "collection": "notion", "explanation": "Dieu est Père d''abord parce qu''il a, de toute éternité, un Fils. Dans la Trinité, le Père est la source, sans être plus Dieu que le Fils et l''Esprit.", "examples": [{"text": "Le Credo commence par le Père.", "translation": "Il commence par la source, avant le Fils et l''Esprit."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_pantocrator', 'eg', 'Pantocrator', 'mot grec : Tout-Puissant, celui qui tient tout', 'Pantocrator vient du grec pan (tout) et kratos (pouvoir). Il dit que Dieu tient toute chose dans l''être, à chaque instant. Ce n''est pas un tyran : sa puissance garde ce qui existe.', '[{"text": "Dieu le Père, Pantocrator.", "translation": "Le Père est le Tout-Puissant."}]'::jsonb, null, '{"id": "eg.d.c08_pantocrator", "unitId": "eg.v.c08_pantocrator", "word": "Pantocrator", "translation": "mot grec : Tout-Puissant, celui qui tient tout", "partOfSpeech": "concept", "collection": "notion", "explanation": "Pantocrator vient du grec pan (tout) et kratos (pouvoir). Il dit que Dieu tient toute chose dans l''être, à chaque instant. Ce n''est pas un tyran : sa puissance garde ce qui existe.", "examples": [{"text": "Dieu le Père, Pantocrator.", "translation": "Le Père est le Tout-Puissant."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_creation_a_partir_de_rien', 'eg', 'la création à partir de rien', 'Dieu crée le monde par sa parole, sans matière d''avant', 'Dieu a créé le monde par sa seule parole, sans matière d''avant. Le monde n''est donc ni éternel, ni un morceau de Dieu. Et il est bon : « cela était très bon » (Genèse 1, 31).', '[{"text": "Dieu crée le ciel et la terre à partir de rien.", "translation": "Il n''a besoin d''aucune matière."}]'::jsonb, null, '{"id": "eg.d.c08_creation_a_partir_de_rien", "unitId": "eg.v.c08_creation_a_partir_de_rien", "word": "la création à partir de rien", "translation": "Dieu crée le monde par sa parole, sans matière d''avant", "partOfSpeech": "concept", "collection": "notion", "explanation": "Dieu a créé le monde par sa seule parole, sans matière d''avant. Le monde n''est donc ni éternel, ni un morceau de Dieu. Et il est bon : « cela était très bon » (Genèse 1, 31).", "examples": [{"text": "Dieu crée le ciel et la terre à partir de rien.", "translation": "Il n''a besoin d''aucune matière."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_visibles_et_invisibles', 'eg', 'les choses visibles et invisibles', 'le monde matériel et le monde spirituel, créés par Dieu', 'Les choses visibles sont le monde que l''on voit : la terre, les astres, les corps. Les choses invisibles sont les créatures spirituelles, les anges. Dieu a tout créé.', '[{"text": "Dieu a créé les choses visibles et invisibles.", "translation": "Même ce qu''on ne voit pas vient de lui."}]'::jsonb, null, '{"id": "eg.d.c08_visibles_et_invisibles", "unitId": "eg.v.c08_visibles_et_invisibles", "word": "les choses visibles et invisibles", "translation": "le monde matériel et le monde spirituel, créés par Dieu", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les choses visibles sont le monde que l''on voit : la terre, les astres, les corps. Les choses invisibles sont les créatures spirituelles, les anges. Dieu a tout créé.", "examples": [{"text": "Dieu a créé les choses visibles et invisibles.", "translation": "Même ce qu''on ne voit pas vient de lui."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_ange', 'eg', 'un ange', 'créature spirituelle qui sert Dieu et les hommes', 'Un ange est une créature spirituelle créée par Dieu. Il adore Dieu et sert les hommes. Il reste une créature : on n''adore que Dieu.', '[{"text": "L''ange porte un message de Dieu.", "translation": "Il sert, il n''est pas l''auteur du message."}]'::jsonb, null, '{"id": "eg.d.c08_ange", "unitId": "eg.v.c08_ange", "word": "un ange", "translation": "créature spirituelle qui sert Dieu et les hommes", "partOfSpeech": "concept", "collection": "notion", "explanation": "Un ange est une créature spirituelle créée par Dieu. Il adore Dieu et sert les hommes. Il reste une créature : on n''adore que Dieu.", "examples": [{"text": "L''ange porte un message de Dieu.", "translation": "Il sert, il n''est pas l''auteur du message."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_kyrios', 'eg', 'Seigneur (Kyrios)', 'mot grec : Seigneur, nom que la Bible grecque donne à Dieu', 'Kyrios veut dire « Seigneur ». La Bible grecque l''emploie pour Dieu lui-même. Confesser « Jésus est Seigneur », c''est confesser qu''il est Dieu.', '[{"text": "Et en un seul Seigneur Jésus-Christ.", "translation": "Le Credo donne au Christ le titre de Dieu."}]'::jsonb, null, '{"id": "eg.d.c08_kyrios", "unitId": "eg.v.c08_kyrios", "word": "Seigneur (Kyrios)", "translation": "mot grec : Seigneur, nom que la Bible grecque donne à Dieu", "partOfSpeech": "concept", "collection": "notion", "explanation": "Kyrios veut dire « Seigneur ». La Bible grecque l''emploie pour Dieu lui-même. Confesser « Jésus est Seigneur », c''est confesser qu''il est Dieu.", "examples": [{"text": "Et en un seul Seigneur Jésus-Christ.", "translation": "Le Credo donne au Christ le titre de Dieu."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_fils_unique', 'eg', 'le Fils unique', 'le seul qui soit Fils de Dieu par nature', 'Le Christ est le Fils unique : le seul qui soit Fils par nature. Nous devenons fils de Dieu par grâce, au baptême.', '[{"text": "Le Fils unique de Dieu.", "translation": "Fils par nature, depuis toujours."}]'::jsonb, null, '{"id": "eg.d.c08_fils_unique", "unitId": "eg.v.c08_fils_unique", "word": "le Fils unique", "translation": "le seul qui soit Fils de Dieu par nature", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le Christ est le Fils unique : le seul qui soit Fils par nature. Nous devenons fils de Dieu par grâce, au baptême.", "examples": [{"text": "Le Fils unique de Dieu.", "translation": "Fils par nature, depuis toujours."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_avant_tous_les_siecles', 'eg', 'avant tous les siècles', 'hors du temps, de toute éternité', 'Le Fils est engendré du Père avant tous les siècles : il n''a pas de commencement. Le temps a été créé, et le Fils est avant lui. Il n''y a jamais eu un moment où le Père était sans Fils.', '[{"text": "Engendré du Père avant tous les siècles.", "translation": "Le Fils est éternel."}]'::jsonb, null, '{"id": "eg.d.c08_avant_tous_les_siecles", "unitId": "eg.v.c08_avant_tous_les_siecles", "word": "avant tous les siècles", "translation": "hors du temps, de toute éternité", "partOfSpeech": "expression", "collection": "notion", "explanation": "Le Fils est engendré du Père avant tous les siècles : il n''a pas de commencement. Le temps a été créé, et le Fils est avant lui. Il n''y a jamais eu un moment où le Père était sans Fils.", "examples": [{"text": "Engendré du Père avant tous les siècles.", "translation": "Le Fils est éternel."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_lumiere_de_lumiere', 'eg', 'Lumière de Lumière', 'le Fils vient du Père comme une flamme allumée à une autre flamme', 'Les Pères comparent le Père et le Fils à une flamme allumée à une autre flamme : même lumière, et la première n''a rien perdu. Le Fils vient du Père sans le diminuer.', '[{"text": "Lumière de Lumière, vrai Dieu de vrai Dieu.", "translation": "Le Fils partage la lumière du Père."}]'::jsonb, null, '{"id": "eg.d.c08_lumiere_de_lumiere", "unitId": "eg.v.c08_lumiere_de_lumiere", "word": "Lumière de Lumière", "translation": "le Fils vient du Père comme une flamme allumée à une autre flamme", "partOfSpeech": "expression", "collection": "priere", "explanation": "Les Pères comparent le Père et le Fils à une flamme allumée à une autre flamme : même lumière, et la première n''a rien perdu. Le Fils vient du Père sans le diminuer.", "examples": [{"text": "Lumière de Lumière, vrai Dieu de vrai Dieu.", "translation": "Le Fils partage la lumière du Père."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_vrai_dieu_de_vrai_dieu', 'eg', 'vrai Dieu de vrai Dieu', 'le Fils est Dieu en vérité, comme le Père', 'Le Fils n''est pas Dieu par titre d''honneur ni à moitié : il est vrai Dieu, de vrai Dieu, comme le Père.', '[{"text": "Vrai Dieu de vrai Dieu.", "translation": "Le Fils n''est pas un Dieu de second rang."}]'::jsonb, null, '{"id": "eg.d.c08_vrai_dieu_de_vrai_dieu", "unitId": "eg.v.c08_vrai_dieu_de_vrai_dieu", "word": "vrai Dieu de vrai Dieu", "translation": "le Fils est Dieu en vérité, comme le Père", "partOfSpeech": "expression", "collection": "priere", "explanation": "Le Fils n''est pas Dieu par titre d''honneur ni à moitié : il est vrai Dieu, de vrai Dieu, comme le Père.", "examples": [{"text": "Vrai Dieu de vrai Dieu.", "translation": "Le Fils n''est pas un Dieu de second rang."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_engendre_non_cree', 'eg', 'engendré, non créé', 'le Fils a la nature du Père : il est Dieu, pas une œuvre', 'Ce qui est engendré a la nature de celui qui engendre. Ce qui est créé est une œuvre. Le Fils est engendré, non créé : il est Dieu comme le Père et il n''est pas une créature.', '[{"text": "Engendré, non créé.", "translation": "Le Fils est de même nature que le Père."}]'::jsonb, null, '{"id": "eg.d.c08_engendre_non_cree", "unitId": "eg.v.c08_engendre_non_cree", "word": "engendré, non créé", "translation": "le Fils a la nature du Père : il est Dieu, pas une œuvre", "partOfSpeech": "expression", "collection": "notion", "explanation": "Ce qui est engendré a la nature de celui qui engendre. Ce qui est créé est une œuvre. Le Fils est engendré, non créé : il est Dieu comme le Père et il n''est pas une créature.", "examples": [{"text": "Engendré, non créé.", "translation": "Le Fils est de même nature que le Père."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_par_qui_tout_a_ete_fait', 'eg', 'par qui tout a été fait', 'le Fils est Créateur avec le Père, non créature', 'L''évangile de Jean dit : « Tout a été fait par lui » (Jean 1, 3). Celui par qui tout a été fait ne peut pas être fait lui-même : il est Créateur, non créature.', '[{"text": "Par qui tout a été fait.", "translation": "Le Fils est Créateur avec le Père."}]'::jsonb, null, '{"id": "eg.d.c08_par_qui_tout_a_ete_fait", "unitId": "eg.v.c08_par_qui_tout_a_ete_fait", "word": "par qui tout a été fait", "translation": "le Fils est Créateur avec le Père, non créature", "partOfSpeech": "expression", "collection": "priere", "explanation": "L''évangile de Jean dit : « Tout a été fait par lui » (Jean 1, 3). Celui par qui tout a été fait ne peut pas être fait lui-même : il est Créateur, non créature.", "examples": [{"text": "Par qui tout a été fait.", "translation": "Le Fils est Créateur avec le Père."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_seul_dieu_sauve', 'eg', 'seul Dieu peut sauver', 'si le Fils n''était pas Dieu, il ne pourrait pas nous sauver', 'Une créature ne peut pas sauver une autre créature de la mort. Seul Dieu peut sauver. Voilà pourquoi « consubstantiel au Père » n''est pas du vocabulaire : c''est la garantie du salut.', '[{"text": "Seul Dieu peut sauver l''homme.", "translation": "Le Christ doit donc être vrai Dieu."}]'::jsonb, null, '{"id": "eg.d.c08_seul_dieu_sauve", "unitId": "eg.v.c08_seul_dieu_sauve", "word": "seul Dieu peut sauver", "translation": "si le Fils n''était pas Dieu, il ne pourrait pas nous sauver", "partOfSpeech": "concept", "collection": "notion", "explanation": "Une créature ne peut pas sauver une autre créature de la mort. Seul Dieu peut sauver. Voilà pourquoi « consubstantiel au Père » n''est pas du vocabulaire : c''est la garantie du salut.", "examples": [{"text": "Seul Dieu peut sauver l''homme.", "translation": "Le Christ doit donc être vrai Dieu."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_pour_notre_salut', 'eg', 'pour notre salut', 'la raison de l''incarnation : Dieu vient nous sauver', 'Le Fils s''incarne pour nous les hommes et pour notre salut. Ce n''est ni par curiosité ni par devoir. L''homme ne peut pas se sauver seul, et seul Dieu peut le sauver : alors Dieu vient nous chercher.', '[{"text": "Qui, pour nous les hommes et pour notre salut, descendit du ciel.", "translation": "Tout ce que fait le Fils, il le fait pour nous."}]'::jsonb, null, '{"id": "eg.d.c08_pour_notre_salut", "unitId": "eg.v.c08_pour_notre_salut", "word": "pour notre salut", "translation": "la raison de l''incarnation : Dieu vient nous sauver", "partOfSpeech": "expression", "collection": "priere", "explanation": "Le Fils s''incarne pour nous les hommes et pour notre salut. Ce n''est ni par curiosité ni par devoir. L''homme ne peut pas se sauver seul, et seul Dieu peut le sauver : alors Dieu vient nous chercher.", "examples": [{"text": "Qui, pour nous les hommes et pour notre salut, descendit du ciel.", "translation": "Tout ce que fait le Fils, il le fait pour nous."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_descente_du_ciel', 'eg', '« il descendit du ciel »', 'le Fils s''abaisse jusqu''à nous sans cesser d''être Dieu', 'Le ciel n''est pas un étage que le Fils quitterait. Descendre veut dire s''abaisser : il prend notre condition sans cesser d''être Dieu. Il prend ce qu''il n''était pas, sans perdre ce qu''il était.', '[{"text": "Il descendit du ciel.", "translation": "Il vient jusqu''à nous."}]'::jsonb, null, '{"id": "eg.d.c08_descente_du_ciel", "unitId": "eg.v.c08_descente_du_ciel", "word": "« il descendit du ciel »", "translation": "le Fils s''abaisse jusqu''à nous sans cesser d''être Dieu", "partOfSpeech": "expression", "collection": "priere", "explanation": "Le ciel n''est pas un étage que le Fils quitterait. Descendre veut dire s''abaisser : il prend notre condition sans cesser d''être Dieu. Il prend ce qu''il n''était pas, sans perdre ce qu''il était.", "examples": [{"text": "Il descendit du ciel.", "translation": "Il vient jusqu''à nous."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_divinisation', 'eg', 'la divinisation', 'Dieu se fait homme pour que l''homme partage sa vie, par grâce', 'Saint Athanase enseigne que Dieu s''est fait homme pour que l''homme participe à la vie divine, par grâce. Comme le fer dans le feu devient brûlant sans cesser d''être du fer.', '[{"text": "Dieu s''est fait homme pour que l''homme participe à sa vie.", "translation": "L''homme reçoit la vie de Dieu, il ne devient pas Dieu par nature."}]'::jsonb, null, '{"id": "eg.d.c08_divinisation", "unitId": "eg.v.c08_divinisation", "word": "la divinisation", "translation": "Dieu se fait homme pour que l''homme partage sa vie, par grâce", "partOfSpeech": "concept", "collection": "notion", "explanation": "Saint Athanase enseigne que Dieu s''est fait homme pour que l''homme participe à la vie divine, par grâce. Comme le fer dans le feu devient brûlant sans cesser d''être du fer.", "examples": [{"text": "Dieu s''est fait homme pour que l''homme participe à sa vie.", "translation": "L''homme reçoit la vie de Dieu, il ne devient pas Dieu par nature."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_conception_virginale', 'eg', 'la conception virginale', 'Jésus est conçu de l''Esprit Saint, sans père humain, par la Vierge Marie', 'L''ange annonce à Marie : « L''Esprit Saint viendra sur toi » (Luc 1, 35). Jésus est conçu de l''Esprit Saint, sans père humain, de la Vierge Marie.', '[{"text": "S''incarna de l''Esprit Saint et de la Vierge Marie.", "translation": "Le Fils prend chair dans le sein de Marie."}]'::jsonb, null, '{"id": "eg.d.c08_conception_virginale", "unitId": "eg.v.c08_conception_virginale", "word": "la conception virginale", "translation": "Jésus est conçu de l''Esprit Saint, sans père humain, par la Vierge Marie", "partOfSpeech": "concept", "collection": "notion", "explanation": "L''ange annonce à Marie : « L''Esprit Saint viendra sur toi » (Luc 1, 35). Jésus est conçu de l''Esprit Saint, sans père humain, de la Vierge Marie.", "examples": [{"text": "S''incarna de l''Esprit Saint et de la Vierge Marie.", "translation": "Le Fils prend chair dans le sein de Marie."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_vierge_marie', 'eg', 'la Vierge Marie', 'la mère du Fils : le Credo la nomme pour dire que l''incarnation est réelle', 'Marie est la Vierge dont le Fils est né. Elle est une vraie mère, mais celui qu''elle enfante est Dieu le Verbe : c''est le sens du titre Théotokos. Le Credo la nomme pour affirmer que l''incarnation est réelle.', '[{"text": "De la Vierge Marie.", "translation": "Le Fils naît d''une vraie mère."}]'::jsonb, null, '{"id": "eg.d.c08_vierge_marie", "unitId": "eg.v.c08_vierge_marie", "word": "la Vierge Marie", "translation": "la mère du Fils : le Credo la nomme pour dire que l''incarnation est réelle", "partOfSpeech": "person", "collection": "notion", "explanation": "Marie est la Vierge dont le Fils est né. Elle est une vraie mère, mais celui qu''elle enfante est Dieu le Verbe : c''est le sens du titre Théotokos. Le Credo la nomme pour affirmer que l''incarnation est réelle.", "examples": [{"text": "De la Vierge Marie.", "translation": "Le Fils naît d''une vraie mère."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_un_seul_sujet', 'eg', 'un seul sujet', 'dans le Credo, c''est toujours le Fils qui agit : un seul « Il »', 'Dans le Credo, le Fils est le sujet de tous les verbes : il descend, s''incarne, se fait homme, souffre. Il n''y a pas deux personnes dans le Christ. C''est la clé de la foi miaphysite.', '[{"text": "Il descendit, il s''incarna, il se fit homme.", "translation": "Un seul sujet pour tous les verbes."}]'::jsonb, null, '{"id": "eg.d.c08_un_seul_sujet", "unitId": "eg.v.c08_un_seul_sujet", "word": "un seul sujet", "translation": "dans le Credo, c''est toujours le Fils qui agit : un seul « Il »", "partOfSpeech": "concept", "collection": "notion", "explanation": "Dans le Credo, le Fils est le sujet de tous les verbes : il descend, s''incarne, se fait homme, souffre. Il n''y a pas deux personnes dans le Christ. C''est la clé de la foi miaphysite.", "examples": [{"text": "Il descendit, il s''incarna, il se fit homme.", "translation": "Un seul sujet pour tous les verbes."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_ponce_pilate', 'eg', 'Ponce Pilate', 'gouverneur romain de Judée, sous qui Jésus est crucifié', 'Ponce Pilate est le gouverneur romain de Judée. Le Credo le nomme pour ancrer la croix dans l''histoire : ce n''est pas un mythe, mais un événement réel, sous un homme réel.', '[{"text": "Il fut crucifié sous Ponce Pilate.", "translation": "La croix a une date et un lieu."}]'::jsonb, null, '{"id": "eg.d.c08_ponce_pilate", "unitId": "eg.v.c08_ponce_pilate", "word": "Ponce Pilate", "translation": "gouverneur romain de Judée, sous qui Jésus est crucifié", "partOfSpeech": "person", "collection": "notion", "explanation": "Ponce Pilate est le gouverneur romain de Judée. Le Credo le nomme pour ancrer la croix dans l''histoire : ce n''est pas un mythe, mais un événement réel, sous un homme réel.", "examples": [{"text": "Il fut crucifié sous Ponce Pilate.", "translation": "La croix a une date et un lieu."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_troisieme_jour', 'eg', 'le troisième jour', 'le jour de la résurrection du Christ : Pâques', 'Le Christ ressuscite le troisième jour après sa mort : le tombeau est vide et il se montre à ses disciples. C''est la date de Pâques et le fondement de la foi.', '[{"text": "Il ressuscita le troisième jour.", "translation": "Pâques, le cœur de la foi."}]'::jsonb, null, '{"id": "eg.d.c08_troisieme_jour", "unitId": "eg.v.c08_troisieme_jour", "word": "le troisième jour", "translation": "le jour de la résurrection du Christ : Pâques", "partOfSpeech": "event", "collection": "date", "explanation": "Le Christ ressuscite le troisième jour après sa mort : le tombeau est vide et il se montre à ses disciples. C''est la date de Pâques et le fondement de la foi.", "examples": [{"text": "Il ressuscita le troisième jour.", "translation": "Pâques, le cœur de la foi."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_selon_les_ecritures', 'eg', 'selon les Écritures', 'la mort et la résurrection du Messie avaient été annoncées par les prophètes', 'Les prophètes avaient annoncé la mort et la résurrection du Messie. Rien n''est un hasard : le Christ accomplit ce que Dieu avait promis.', '[{"text": "Il ressuscita selon les Écritures.", "translation": "Tout était annoncé."}]'::jsonb, null, '{"id": "eg.d.c08_selon_les_ecritures", "unitId": "eg.v.c08_selon_les_ecritures", "word": "selon les Écritures", "translation": "la mort et la résurrection du Messie avaient été annoncées par les prophètes", "partOfSpeech": "expression", "collection": "notion", "explanation": "Les prophètes avaient annoncé la mort et la résurrection du Messie. Rien n''est un hasard : le Christ accomplit ce que Dieu avait promis.", "examples": [{"text": "Il ressuscita selon les Écritures.", "translation": "Tout était annoncé."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_droite_du_pere', 'eg', 'la droite du Père', 'la place d''honneur : l''honneur et la puissance, pas un endroit', 'S''asseoir à la droite du Père veut dire recevoir l''honneur et la puissance. Dieu n''a pas de côté droit : c''est une image. L''humanité du Christ est glorifiée avec lui.', '[{"text": "Il s''assit à la droite de son Père.", "translation": "Il reçoit l''honneur et la puissance."}]'::jsonb, null, '{"id": "eg.d.c08_droite_du_pere", "unitId": "eg.v.c08_droite_du_pere", "word": "la droite du Père", "translation": "la place d''honneur : l''honneur et la puissance, pas un endroit", "partOfSpeech": "expression", "collection": "notion", "explanation": "S''asseoir à la droite du Père veut dire recevoir l''honneur et la puissance. Dieu n''a pas de côté droit : c''est une image. L''humanité du Christ est glorifiée avec lui.", "examples": [{"text": "Il s''assit à la droite de son Père.", "translation": "Il reçoit l''honneur et la puissance."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_seconde_venue', 'eg', 'la seconde venue', 'le retour du Christ dans la gloire pour juger les vivants et les morts', 'La première fois, le Christ est venu dans l''humilité, comme un enfant. La seconde fois, il reviendra dans la gloire pour juger tous les hommes, vivants et morts. Nul ne connaît le jour (Matthieu 24, 36).', '[{"text": "Il reviendra dans la gloire pour juger les vivants et les morts.", "translation": "Le Christ revient à la fin des temps."}]'::jsonb, null, '{"id": "eg.d.c08_seconde_venue", "unitId": "eg.v.c08_seconde_venue", "word": "la seconde venue", "translation": "le retour du Christ dans la gloire pour juger les vivants et les morts", "partOfSpeech": "event", "collection": "notion", "explanation": "La première fois, le Christ est venu dans l''humilité, comme un enfant. La seconde fois, il reviendra dans la gloire pour juger tous les hommes, vivants et morts. Nul ne connaît le jour (Matthieu 24, 36).", "examples": [{"text": "Il reviendra dans la gloire pour juger les vivants et les morts.", "translation": "Le Christ revient à la fin des temps."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_regne_sans_fin', 'eg', 'son règne n''aura pas de fin', 'dernière phrase sur le Fils, ajoutée en 381 : le Christ est Roi pour toujours', 'Cette phrase appartient au texte de 381, pas à celui de 325. Elle affirme que le Christ est Roi pour toujours, Dieu et homme. Le règne de l''amour demeure.', '[{"text": "Son règne n''aura pas de fin.", "translation": "Le Christ règne pour l''éternité."}]'::jsonb, null, '{"id": "eg.d.c08_regne_sans_fin", "unitId": "eg.v.c08_regne_sans_fin", "word": "son règne n''aura pas de fin", "translation": "dernière phrase sur le Fils, ajoutée en 381 : le Christ est Roi pour toujours", "partOfSpeech": "expression", "collection": "priere", "explanation": "Cette phrase appartient au texte de 381, pas à celui de 325. Elle affirme que le Christ est Roi pour toujours, Dieu et homme. Le règne de l''amour demeure.", "examples": [{"text": "Son règne n''aura pas de fin.", "translation": "Le Christ règne pour l''éternité."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_chaine_des_verbes', 'eg', 'la chaîne des verbes', 'dix verbes du Credo qui racontent toute l''histoire du Fils', 'Pour retenir le bloc du Fils, suis ses verbes : descendit, s''incarna, se fit homme, crucifié, souffrit, enseveli, ressuscita, monta, s''assit, reviendra.', '[{"text": "Descendit, s''incarna, crucifié, ressuscita, monta, reviendra.", "translation": "Les verbes donnent le fil de l''histoire."}]'::jsonb, null, '{"id": "eg.d.c08_chaine_des_verbes", "unitId": "eg.v.c08_chaine_des_verbes", "word": "la chaîne des verbes", "translation": "dix verbes du Credo qui racontent toute l''histoire du Fils", "partOfSpeech": "concept", "collection": "notion", "explanation": "Pour retenir le bloc du Fils, suis ses verbes : descendit, s''incarna, se fit homme, crucifié, souffrit, enseveli, ressuscita, monta, s''assit, reviendra.", "examples": [{"text": "Descendit, s''incarna, crucifié, ressuscita, monta, reviendra.", "translation": "Les verbes donnent le fil de l''histoire."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_vivificateur', 'eg', 'le vivificateur', '« qui donne la vie » : titre de l''Esprit Saint, seul Dieu donne la vie', 'Vivificateur veut dire « qui donne la vie ». L''Esprit plane sur la création, fait renaître au baptême et fera ressusciter. Seul Dieu donne la vie : l''Esprit est donc Dieu.', '[{"text": "Seigneur qui donne la vie.", "translation": "L''Esprit est la source de la vie."}]'::jsonb, null, '{"id": "eg.d.c08_vivificateur", "unitId": "eg.v.c08_vivificateur", "word": "le vivificateur", "translation": "« qui donne la vie » : titre de l''Esprit Saint, seul Dieu donne la vie", "partOfSpeech": "concept", "collection": "notion", "explanation": "Vivificateur veut dire « qui donne la vie ». L''Esprit plane sur la création, fait renaître au baptême et fera ressusciter. Seul Dieu donne la vie : l''Esprit est donc Dieu.", "examples": [{"text": "Seigneur qui donne la vie.", "translation": "L''Esprit est la source de la vie."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_procession', 'eg', '« qui procède du Père »', 'procéder est le mot propre à l''Esprit, comme engendrer pour le Fils', 'Le Fils est engendré, l''Esprit procède : deux façons d''avoir le Père pour source. Le Credo reprend Jean 15, 26. Le Père reste la seule source de la Trinité.', '[{"text": "Qui procède du Père.", "translation": "L''Esprit vient du Père, sans commencement."}]'::jsonb, null, '{"id": "eg.d.c08_procession", "unitId": "eg.v.c08_procession", "word": "« qui procède du Père »", "translation": "procéder est le mot propre à l''Esprit, comme engendrer pour le Fils", "partOfSpeech": "expression", "collection": "priere", "explanation": "Le Fils est engendré, l''Esprit procède : deux façons d''avoir le Père pour source. Le Credo reprend Jean 15, 26. Le Père reste la seule source de la Trinité.", "examples": [{"text": "Qui procède du Père.", "translation": "L''Esprit vient du Père, sans commencement."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_a_parle_par_les_prophetes', 'eg', '« il a parlé par les prophètes »', 'le même Esprit a inspiré l''Ancien et le Nouveau Testament', 'L''Esprit qui agit dans l''Église est celui qui a parlé par les prophètes. C''est l''inspiration des Écritures (2 Pierre 1, 21) : les deux Testaments viennent du même Esprit.', '[{"text": "Qui a parlé par les prophètes.", "translation": "Les Écritures sont inspirées par l''Esprit."}]'::jsonb, null, '{"id": "eg.d.c08_a_parle_par_les_prophetes", "unitId": "eg.v.c08_a_parle_par_les_prophetes", "word": "« il a parlé par les prophètes »", "translation": "le même Esprit a inspiré l''Ancien et le Nouveau Testament", "partOfSpeech": "expression", "collection": "priere", "explanation": "L''Esprit qui agit dans l''Église est celui qui a parlé par les prophètes. C''est l''inspiration des Écritures (2 Pierre 1, 21) : les deux Testaments viennent du même Esprit.", "examples": [{"text": "Qui a parlé par les prophètes.", "translation": "Les Écritures sont inspirées par l''Esprit."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_eglise_une', 'eg', 'l''Église une', 'l''Église est le seul Corps du Christ : un Seigneur, une foi, un baptême', 'L''Église est une parce qu''elle est le seul Corps du Christ : un seul Seigneur, une seule foi, un seul baptême (Éphésiens 4, 5). L''unité, c''est celle de la foi reçue des apôtres.', '[{"text": "Nous croyons en une seule Église.", "translation": "Une seule, malgré les divisions de l''histoire."}]'::jsonb, null, '{"id": "eg.d.c08_eglise_une", "unitId": "eg.v.c08_eglise_une", "word": "l''Église une", "translation": "l''Église est le seul Corps du Christ : un Seigneur, une foi, un baptême", "partOfSpeech": "concept", "collection": "notion", "explanation": "L''Église est une parce qu''elle est le seul Corps du Christ : un seul Seigneur, une seule foi, un seul baptême (Éphésiens 4, 5). L''unité, c''est celle de la foi reçue des apôtres.", "examples": [{"text": "Nous croyons en une seule Église.", "translation": "Une seule, malgré les divisions de l''histoire."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_eglise_sainte', 'eg', 'l''Église sainte', 'sainte parce que le Christ et l''Esprit la sanctifient, non ses membres', 'L''Église est sainte parce que le Christ et l''Esprit la sanctifient, pas parce que ses membres seraient parfaits. Elle est faite de pécheurs qui se repentent : un hôpital avant d''être un club de saints.', '[{"text": "L''Église est sainte et accueille les pécheurs.", "translation": "Sa sainteté vient du Christ."}]'::jsonb, null, '{"id": "eg.d.c08_eglise_sainte", "unitId": "eg.v.c08_eglise_sainte", "word": "l''Église sainte", "translation": "sainte parce que le Christ et l''Esprit la sanctifient, non ses membres", "partOfSpeech": "concept", "collection": "notion", "explanation": "L''Église est sainte parce que le Christ et l''Esprit la sanctifient, pas parce que ses membres seraient parfaits. Elle est faite de pécheurs qui se repentent : un hôpital avant d''être un club de saints.", "examples": [{"text": "L''Église est sainte et accueille les pécheurs.", "translation": "Sa sainteté vient du Christ."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_apostolicite', 'eg', 'l''apostolicité', 'l''Église est fondée sur l''enseignement des apôtres, gardé par les évêques', 'Apostolique veut dire fondée sur l''enseignement des apôtres. Cet enseignement est gardé par la succession apostolique, la chaîne des évêques qui remonte aux apôtres.', '[{"text": "Le pape copte est le successeur de saint Marc.", "translation": "L''Église d''Alexandrie est apostolique."}]'::jsonb, null, '{"id": "eg.d.c08_apostolicite", "unitId": "eg.v.c08_apostolicite", "word": "l''apostolicité", "translation": "l''Église est fondée sur l''enseignement des apôtres, gardé par les évêques", "partOfSpeech": "concept", "collection": "notion", "explanation": "Apostolique veut dire fondée sur l''enseignement des apôtres. Cet enseignement est gardé par la succession apostolique, la chaîne des évêques qui remonte aux apôtres.", "examples": [{"text": "Le pape copte est le successeur de saint Marc.", "translation": "L''Église d''Alexandrie est apostolique."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_un_seul_bapteme', 'eg', 'un seul baptême', 'le baptême ne se répète pas : il pardonne les péchés et donne une vie nouvelle', 'On naît une seule fois : le baptême ne se répète pas. Rémission veut dire pardon : par l''eau et l''Esprit (Jean 3, 5), il pardonne les péchés et donne une vie nouvelle. C''est la porte de l''Église.', '[{"text": "Nous confessons un seul baptême pour la rémission des péchés.", "translation": "Un seul baptême, qui pardonne."}]'::jsonb, null, '{"id": "eg.d.c08_un_seul_bapteme", "unitId": "eg.v.c08_un_seul_bapteme", "word": "un seul baptême", "translation": "le baptême ne se répète pas : il pardonne les péchés et donne une vie nouvelle", "partOfSpeech": "concept", "collection": "notion", "explanation": "On naît une seule fois : le baptême ne se répète pas. Rémission veut dire pardon : par l''eau et l''Esprit (Jean 3, 5), il pardonne les péchés et donne une vie nouvelle. C''est la porte de l''Église.", "examples": [{"text": "Nous confessons un seul baptême pour la rémission des péchés.", "translation": "Un seul baptême, qui pardonne."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_resurrection_des_morts', 'eg', 'la résurrection des morts', 'à la fin, les morts ressusciteront, corps compris', 'Nous attendons la résurrection de l''homme tout entier, corps compris. Le Christ est ressuscité le premier, et nous le serons avec lui (1 Corinthiens 15). Le corps n''est pas une prison.', '[{"text": "Nous attendons la résurrection des morts.", "translation": "L''homme entier ressuscitera."}]'::jsonb, null, '{"id": "eg.d.c08_resurrection_des_morts", "unitId": "eg.v.c08_resurrection_des_morts", "word": "la résurrection des morts", "translation": "à la fin, les morts ressusciteront, corps compris", "partOfSpeech": "concept", "collection": "notion", "explanation": "Nous attendons la résurrection de l''homme tout entier, corps compris. Le Christ est ressuscité le premier, et nous le serons avec lui (1 Corinthiens 15). Le corps n''est pas une prison.", "examples": [{"text": "Nous attendons la résurrection des morts.", "translation": "L''homme entier ressuscitera."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_siecle_a_venir', 'eg', 'la vie du siècle à venir', 'le monde nouveau après le retour du Christ : la vie éternelle avec Dieu', 'Le siècle à venir est le monde nouveau, après le retour du Christ : la vie éternelle avec Dieu. Le Credo finit sur une attente, pas sur un regret.', '[{"text": "Et la vie du siècle à venir.", "translation": "La foi regarde vers l''avant."}]'::jsonb, null, '{"id": "eg.d.c08_siecle_a_venir", "unitId": "eg.v.c08_siecle_a_venir", "word": "la vie du siècle à venir", "translation": "le monde nouveau après le retour du Christ : la vie éternelle avec Dieu", "partOfSpeech": "expression", "collection": "priere", "explanation": "Le siècle à venir est le monde nouveau, après le retour du Christ : la vie éternelle avec Dieu. Le Credo finit sur une attente, pas sur un regret.", "examples": [{"text": "Et la vie du siècle à venir.", "translation": "La foi regarde vers l''avant."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_amen', 'eg', 'Amen', 'mot hébreu : « c''est vrai », « ainsi soit-il »', 'Amen est un mot hébreu qui veut dire « c''est vrai », « ainsi soit-il ». En le disant, tu signes tout ce que tu viens de confesser.', '[{"text": "Amen.", "translation": "Je signe ce que je viens de dire."}]'::jsonb, null, '{"id": "eg.d.c08_amen", "unitId": "eg.v.c08_amen", "word": "Amen", "translation": "mot hébreu : « c''est vrai », « ainsi soit-il »", "partOfSpeech": "expression", "collection": "priere", "explanation": "Amen est un mot hébreu qui veut dire « c''est vrai », « ainsi soit-il ». En le disant, tu signes tout ce que tu viens de confesser.", "examples": [{"text": "Amen.", "translation": "Je signe ce que je viens de dire."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_trois_blocs', 'eg', 'les trois blocs du Credo', 'un bloc pour le Père, un pour le Fils, un pour l''Esprit, puis l''Église', 'Pour retenir le Credo : un bloc pour le Père, un pour le Fils, un pour l''Esprit Saint, puis l''Église et l''attente. Le bloc du Fils est le plus long, car il raconte l''histoire du salut.', '[{"text": "Père, Fils, Esprit, puis l''Église.", "translation": "Quatre pas pour tout retenir."}]'::jsonb, null, '{"id": "eg.d.c08_trois_blocs", "unitId": "eg.v.c08_trois_blocs", "word": "les trois blocs du Credo", "translation": "un bloc pour le Père, un pour le Fils, un pour l''Esprit, puis l''Église", "partOfSpeech": "concept", "collection": "notion", "explanation": "Pour retenir le Credo : un bloc pour le Père, un pour le Fils, un pour l''Esprit Saint, puis l''Église et l''attente. Le bloc du Fils est le plus long, car il raconte l''histoire du salut.", "examples": [{"text": "Père, Fils, Esprit, puis l''Église.", "translation": "Quatre pas pour tout retenir."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c08_confesser', 'eg', 'confesser la foi', 'proclamer ouvertement sa foi, avec toute l''Église', 'Confesser la foi, c''est la proclamer ouvertement. Le Credo est la confession de toute l''Église : en le disant debout, tu confesses avec elle.', '[{"text": "Nous confessons un seul baptême.", "translation": "Nous proclamons notre foi ensemble."}]'::jsonb, null, '{"id": "eg.d.c08_confesser", "unitId": "eg.v.c08_confesser", "word": "confesser la foi", "translation": "proclamer ouvertement sa foi, avec toute l''Église", "partOfSpeech": "expression", "collection": "notion", "explanation": "Confesser la foi, c''est la proclamer ouvertement. Le Credo est la confession de toute l''Église : en le disant debout, tu confesses avec elle.", "examples": [{"text": "Nous confessons un seul baptême.", "translation": "Nous proclamons notre foi ensemble."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_sacrement', 'eg', 'le sacrement (le mystère)', 'signe visible par lequel Dieu donne une grâce invisible', 'Dans l''Église copte, on dit aussi « mystère ». Il y en a sept, et chacun a été institué par le Christ ou donné par ses apôtres.', '[{"text": "Le baptême est un sacrement.", "translation": "Un signe visible, une grâce invisible."}]'::jsonb, null, '{"id": "eg.d.c09_sacrement", "unitId": "eg.v.c09_sacrement", "word": "le sacrement (le mystère)", "translation": "signe visible par lequel Dieu donne une grâce invisible", "partOfSpeech": "concept", "collection": "notion", "explanation": "Dans l''Église copte, on dit aussi « mystère ». Il y en a sept, et chacun a été institué par le Christ ou donné par ses apôtres.", "examples": [{"text": "Le baptême est un sacrement.", "translation": "Un signe visible, une grâce invisible."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_grace', 'eg', 'la grâce', 'don gratuit de Dieu : son aide, son pardon, sa vie en nous', 'La grâce ne se gagne pas : elle est donnée. Les sacrements sont les moyens par lesquels l''Église la reçoit.', '[{"text": "La grâce, on la reçoit comme un cadeau.", "translation": "Personne ne la mérite par ses efforts."}]'::jsonb, null, '{"id": "eg.d.c09_grace", "unitId": "eg.v.c09_grace", "word": "la grâce", "translation": "don gratuit de Dieu : son aide, son pardon, sa vie en nous", "partOfSpeech": "concept", "collection": "notion", "explanation": "La grâce ne se gagne pas : elle est donnée. Les sacrements sont les moyens par lesquels l''Église la reçoit.", "examples": [{"text": "La grâce, on la reçoit comme un cadeau.", "translation": "Personne ne la mérite par ses efforts."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_signe_visible', 'eg', 'le signe visible', 'la matière et le geste du sacrement : eau, huile, pain, mains', 'Le signe est ce qu''on voit et touche dans le sacrement. Il montre la grâce qui est donnée.', '[{"text": "L''huile est le signe visible de l''onction.", "translation": "On voit l''huile ; on ne voit pas la grâce."}]'::jsonb, null, '{"id": "eg.d.c09_signe_visible", "unitId": "eg.v.c09_signe_visible", "word": "le signe visible", "translation": "la matière et le geste du sacrement : eau, huile, pain, mains", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le signe est ce qu''on voit et touche dans le sacrement. Il montre la grâce qui est donnée.", "examples": [{"text": "L''huile est le signe visible de l''onction.", "translation": "On voit l''huile ; on ne voit pas la grâce."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_bapteme', 'eg', 'le baptême', 'premier sacrement : naître d''eau et d''Esprit par la triple immersion', 'Le baptême est la porte de l''Église. Il donne le pardon des péchés et une nouvelle naissance, et il ne se répète jamais.', '[{"text": "Le baptême ouvre la porte aux autres sacrements.", "translation": "Sans lui, on ne reçoit pas les autres."}]'::jsonb, null, '{"id": "eg.d.c09_bapteme", "unitId": "eg.v.c09_bapteme", "word": "le baptême", "translation": "premier sacrement : naître d''eau et d''Esprit par la triple immersion", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le baptême est la porte de l''Église. Il donne le pardon des péchés et une nouvelle naissance, et il ne se répète jamais.", "examples": [{"text": "Le baptême ouvre la porte aux autres sacrements.", "translation": "Sans lui, on ne reçoit pas les autres."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_triple_immersion', 'eg', 'la triple immersion', 'le baptisé est plongé trois fois dans l''eau, au nom de la Trinité', 'Chaque immersion correspond à une Personne de la Trinité et rappelle l''un des trois jours du Christ au tombeau.', '[{"text": "Le prêtre plonge l''enfant trois fois.", "translation": "Père, Fils, Saint-Esprit : une immersion chacun."}]'::jsonb, null, '{"id": "eg.d.c09_triple_immersion", "unitId": "eg.v.c09_triple_immersion", "word": "la triple immersion", "translation": "le baptisé est plongé trois fois dans l''eau, au nom de la Trinité", "partOfSpeech": "concept", "collection": "notion", "explanation": "Chaque immersion correspond à une Personne de la Trinité et rappelle l''un des trois jours du Christ au tombeau.", "examples": [{"text": "Le prêtre plonge l''enfant trois fois.", "translation": "Père, Fils, Saint-Esprit : une immersion chacun."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_nouvelle_naissance', 'eg', 'la nouvelle naissance', 'naître d''eau et d''Esprit (Jn 3, 5), don du baptême', 'Jésus dit à Nicodème qu''il faut naître d''en haut. Le baptême est cette seconde naissance.', '[{"text": "Le baptisé naît une seconde fois.", "translation": "Une vie nouvelle commence."}]'::jsonb, null, '{"id": "eg.d.c09_nouvelle_naissance", "unitId": "eg.v.c09_nouvelle_naissance", "word": "la nouvelle naissance", "translation": "naître d''eau et d''Esprit (Jn 3, 5), don du baptême", "partOfSpeech": "concept", "collection": "notion", "explanation": "Jésus dit à Nicodème qu''il faut naître d''en haut. Le baptême est cette seconde naissance.", "examples": [{"text": "Le baptisé naît une seconde fois.", "translation": "Une vie nouvelle commence."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_renoncement_a_satan', 'eg', 'le renoncement à Satan', 'promesse de rejeter Satan, faite tourné vers l''ouest', 'Avant d''entrer dans l''eau, le baptisé rejette le mal. Il le fait tourné vers l''ouest, le côté des ténèbres.', '[{"text": "Je renonce à Satan, dit le parrain pour l''enfant.", "translation": "On dit non au mal avant de dire oui au Christ."}]'::jsonb, null, '{"id": "eg.d.c09_renoncement_a_satan", "unitId": "eg.v.c09_renoncement_a_satan", "word": "le renoncement à Satan", "translation": "promesse de rejeter Satan, faite tourné vers l''ouest", "partOfSpeech": "concept", "collection": "notion", "explanation": "Avant d''entrer dans l''eau, le baptisé rejette le mal. Il le fait tourné vers l''ouest, le côté des ténèbres.", "examples": [{"text": "Je renonce à Satan, dit le parrain pour l''enfant.", "translation": "On dit non au mal avant de dire oui au Christ."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_profession_de_foi', 'eg', 'la profession de foi', 'confession du Christ et du Credo, faite tourné vers l''est', 'Après avoir renoncé à Satan, le baptisé confesse le Christ. Il le fait tourné vers l''est, là où se lève le soleil.', '[{"text": "On récite le Credo face à l''est.", "translation": "La foi se dit à voix haute."}]'::jsonb, null, '{"id": "eg.d.c09_profession_de_foi", "unitId": "eg.v.c09_profession_de_foi", "word": "la profession de foi", "translation": "confession du Christ et du Credo, faite tourné vers l''est", "partOfSpeech": "concept", "collection": "notion", "explanation": "Après avoir renoncé à Satan, le baptisé confesse le Christ. Il le fait tourné vers l''est, là où se lève le soleil.", "examples": [{"text": "On récite le Credo face à l''est.", "translation": "La foi se dit à voix haute."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_bapteme_des_enfants', 'eg', 'le baptême des enfants', 'l''Église baptise les bébés, avec la foi des parents et du parrain', 'Le baptême prend la place de la circoncision, que l''on faisait aux nouveau-nés. L''enfant est élevé dans la foi.', '[{"text": "On baptise un bébé de quarante jours.", "translation": "Il reçoit la vie de Dieu avant de pouvoir parler."}]'::jsonb, null, '{"id": "eg.d.c09_bapteme_des_enfants", "unitId": "eg.v.c09_bapteme_des_enfants", "word": "le baptême des enfants", "translation": "l''Église baptise les bébés, avec la foi des parents et du parrain", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le baptême prend la place de la circoncision, que l''on faisait aux nouveau-nés. L''enfant est élevé dans la foi.", "examples": [{"text": "On baptise un bébé de quarante jours.", "translation": "Il reçoit la vie de Dieu avant de pouvoir parler."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_parrain', 'eg', 'le parrain', 'celui qui répond pour l''enfant et s''engage à l''élever dans la foi', 'Le parrain est un orthodoxe pratiquant. Il tient l''enfant au baptême et l''accompagne ensuite dans la foi, comme un second père.', '[{"text": "Le parrain renonce à Satan à la place du bébé.", "translation": "Il parle pour celui qui ne peut pas encore parler."}]'::jsonb, null, '{"id": "eg.d.c09_parrain", "unitId": "eg.v.c09_parrain", "word": "le parrain", "translation": "celui qui répond pour l''enfant et s''engage à l''élever dans la foi", "partOfSpeech": "person", "collection": "notion", "explanation": "Le parrain est un orthodoxe pratiquant. Il tient l''enfant au baptême et l''accompagne ensuite dans la foi, comme un second père.", "examples": [{"text": "Le parrain renonce à Satan à la place du bébé.", "translation": "Il parle pour celui qui ne peut pas encore parler."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_quarante_quatre_vingts_jours', 'eg', 'le 40e et le 80e jour', 'usage : le garçon est baptisé vers le 40e jour, la fille vers le 80e', 'Cet usage vient du Lévitique 12. Si l''enfant est en danger, on ne l''attend pas.', '[{"text": "La fille est baptisée vers le 80e jour.", "translation": "C''est l''usage, pas une obligation absolue."}]'::jsonb, null, '{"id": "eg.d.c09_quarante_quatre_vingts_jours", "unitId": "eg.v.c09_quarante_quatre_vingts_jours", "word": "le 40e et le 80e jour", "translation": "usage : le garçon est baptisé vers le 40e jour, la fille vers le 80e", "partOfSpeech": "concept", "collection": "notion", "explanation": "Cet usage vient du Lévitique 12. Si l''enfant est en danger, on ne l''attend pas.", "examples": [{"text": "La fille est baptisée vers le 80e jour.", "translation": "C''est l''usage, pas une obligation absolue."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_confirmation', 'eg', 'la confirmation (la chrismation)', 'sacrement du sceau du Saint-Esprit, donné par le saint myron après le baptême', 'Elle suit le baptême immédiatement. Chez les Coptes, c''est le prêtre qui la donne, même aux bébés.', '[{"text": "La confirmation suit aussitôt le baptême.", "translation": "Les deux forment un seul parcours."}]'::jsonb, null, '{"id": "eg.d.c09_confirmation", "unitId": "eg.v.c09_confirmation", "word": "la confirmation (la chrismation)", "translation": "sacrement du sceau du Saint-Esprit, donné par le saint myron après le baptême", "partOfSpeech": "concept", "collection": "notion", "explanation": "Elle suit le baptême immédiatement. Chez les Coptes, c''est le prêtre qui la donne, même aux bébés.", "examples": [{"text": "La confirmation suit aussitôt le baptême.", "translation": "Les deux forment un seul parcours."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_saint_myron', 'eg', 'le saint myron', 'huile parfumée consacrée par le pape pour la confirmation', 'Le mot « myron » est grec et veut dire parfum. Il sert à la confirmation et à bénir l''eau du baptême.', '[{"text": "Le prêtre verse le saint myron dans l''eau.", "translation": "Une huile parfumée, jamais ordinaire."}]'::jsonb, null, '{"id": "eg.d.c09_saint_myron", "unitId": "eg.v.c09_saint_myron", "word": "le saint myron", "translation": "huile parfumée consacrée par le pape pour la confirmation", "partOfSpeech": "concept", "collection": "objet", "explanation": "Le mot « myron » est grec et veut dire parfum. Il sert à la confirmation et à bénir l''eau du baptême.", "examples": [{"text": "Le prêtre verse le saint myron dans l''eau.", "translation": "Une huile parfumée, jamais ordinaire."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_preparation_du_myron', 'eg', 'la préparation du myron', 'le pape et les évêques préparent et consacrent le saint myron', 'Elle a lieu au monastère Saint-Bishoy du Ouadi Natroun, pendant le Carême, mais pas à date fixe. On ajoute un peu de l''ancien myron au nouveau.', '[{"text": "Le pape préside la préparation du myron.", "translation": "C''est la même huile de génération en génération."}]'::jsonb, null, '{"id": "eg.d.c09_preparation_du_myron", "unitId": "eg.v.c09_preparation_du_myron", "word": "la préparation du myron", "translation": "le pape et les évêques préparent et consacrent le saint myron", "partOfSpeech": "concept", "collection": "notion", "explanation": "Elle a lieu au monastère Saint-Bishoy du Ouadi Natroun, pendant le Carême, mais pas à date fixe. On ajoute un peu de l''ancien myron au nouveau.", "examples": [{"text": "Le pape préside la préparation du myron.", "translation": "C''est la même huile de génération en génération."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_imposition_des_mains', 'eg', 'l''imposition des mains', 'geste par lequel les apôtres donnaient l''Esprit, puis les évêques ordonnent', 'Les apôtres imposent les mains aux baptisés (Ac 8, 14-17). Le même geste sert à ordonner les clercs.', '[{"text": "Pierre et Jean imposent les mains aux Samaritains.", "translation": "Un geste simple qui transmet l''Esprit."}]'::jsonb, null, '{"id": "eg.d.c09_imposition_des_mains", "unitId": "eg.v.c09_imposition_des_mains", "word": "l''imposition des mains", "translation": "geste par lequel les apôtres donnaient l''Esprit, puis les évêques ordonnent", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les apôtres imposent les mains aux baptisés (Ac 8, 14-17). Le même geste sert à ordonner les clercs.", "examples": [{"text": "Pierre et Jean imposent les mains aux Samaritains.", "translation": "Un geste simple qui transmet l''Esprit."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_trente_six_onctions', 'eg', 'les 36 onctions', '36 signes de croix de myron sur les sens et les articulations', 'Le prêtre oint la tête, les sens, la poitrine, le dos et les articulations : tout le corps est consacré.', '[{"text": "Le prêtre trace 36 croix avec le myron.", "translation": "Chaque sens appartient au Christ."}]'::jsonb, null, '{"id": "eg.d.c09_trente_six_onctions", "unitId": "eg.v.c09_trente_six_onctions", "word": "les 36 onctions", "translation": "36 signes de croix de myron sur les sens et les articulations", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le prêtre oint la tête, les sens, la poitrine, le dos et les articulations : tout le corps est consacré.", "examples": [{"text": "Le prêtre trace 36 croix avec le myron.", "translation": "Chaque sens appartient au Christ."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_sceau_du_saint_esprit', 'eg', 'le sceau du Saint-Esprit', 'marque spirituelle donnée par le myron : l''Esprit habite le baptisé', 'Saint Paul dit que Dieu nous a marqués de son sceau (2 Co 1, 22). Ce sceau ne s''efface pas.', '[{"text": "Le baptisé reçoit le sceau du Saint-Esprit.", "translation": "Il appartient désormais au Christ."}]'::jsonb, null, '{"id": "eg.d.c09_sceau_du_saint_esprit", "unitId": "eg.v.c09_sceau_du_saint_esprit", "word": "le sceau du Saint-Esprit", "translation": "marque spirituelle donnée par le myron : l''Esprit habite le baptisé", "partOfSpeech": "concept", "collection": "notion", "explanation": "Saint Paul dit que Dieu nous a marqués de son sceau (2 Co 1, 22). Ce sceau ne s''efface pas.", "examples": [{"text": "Le baptisé reçoit le sceau du Saint-Esprit.", "translation": "Il appartient désormais au Christ."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_habit_blanc', 'eg', 'l''habit blanc', 'vêtement blanc du nouveau baptisé : l''homme nouveau', 'Le blanc dit la pureté et la vie nouvelle. Le prêtre le marque de la croix.', '[{"text": "L''enfant est revêtu d''un habit blanc.", "translation": "Il a revêtu l''homme nouveau."}]'::jsonb, null, '{"id": "eg.d.c09_habit_blanc", "unitId": "eg.v.c09_habit_blanc", "word": "l''habit blanc", "translation": "vêtement blanc du nouveau baptisé : l''homme nouveau", "partOfSpeech": "concept", "collection": "objet", "explanation": "Le blanc dit la pureté et la vie nouvelle. Le prêtre le marque de la croix.", "examples": [{"text": "L''enfant est revêtu d''un habit blanc.", "translation": "Il a revêtu l''homme nouveau."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_zounnar', 'eg', 'le zounnar', 'ceinture ou ruban noué à la taille du nouveau baptisé, selon l''usage', 'Il dit l''appartenance au Christ. Il est dénoué le huitième jour, autrefois à la maison, aujourd''hui souvent à l''église.', '[{"text": "On dénoue le zounnar le huitième jour.", "translation": "Une petite ceinture pour un grand engagement."}]'::jsonb, null, '{"id": "eg.d.c09_zounnar", "unitId": "eg.v.c09_zounnar", "word": "le zounnar", "translation": "ceinture ou ruban noué à la taille du nouveau baptisé, selon l''usage", "partOfSpeech": "concept", "collection": "objet", "explanation": "Il dit l''appartenance au Christ. Il est dénoué le huitième jour, autrefois à la maison, aujourd''hui souvent à l''église.", "examples": [{"text": "On dénoue le zounnar le huitième jour.", "translation": "Une petite ceinture pour un grand engagement."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_eucharistie', 'eg', 'l''eucharistie', 'sacrement du Corps et du Sang du Christ ; mot grec pour « action de grâce »', 'L''eucharistie est célébrée à la messe. Elle se répète : on peut communier souvent.', '[{"text": "On remercie Dieu en communiant.", "translation": "Eucharistie veut dire « merci »."}]'::jsonb, null, '{"id": "eg.d.c09_eucharistie", "unitId": "eg.v.c09_eucharistie", "word": "l''eucharistie", "translation": "sacrement du Corps et du Sang du Christ ; mot grec pour « action de grâce »", "partOfSpeech": "concept", "collection": "notion", "explanation": "L''eucharistie est célébrée à la messe. Elle se répète : on peut communier souvent.", "examples": [{"text": "On remercie Dieu en communiant.", "translation": "Eucharistie veut dire « merci »."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_derniere_cene', 'eg', 'la dernière Cène', 'repas du Jeudi saint où Jésus institue l''eucharistie', 'C''est le dernier repas de Jésus avec ses apôtres, avant sa Passion. Il y prend le pain et la coupe.', '[{"text": "À la dernière Cène, Jésus prend le pain.", "translation": "Ce soir-là naît l''eucharistie."}]'::jsonb, null, '{"id": "eg.d.c09_derniere_cene", "unitId": "eg.v.c09_derniere_cene", "word": "la dernière Cène", "translation": "repas du Jeudi saint où Jésus institue l''eucharistie", "partOfSpeech": "event", "collection": "date", "explanation": "C''est le dernier repas de Jésus avec ses apôtres, avant sa Passion. Il y prend le pain et la coupe.", "examples": [{"text": "À la dernière Cène, Jésus prend le pain.", "translation": "Ce soir-là naît l''eucharistie."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_presence_reelle', 'eg', 'la présence réelle', 'le pain et le vin deviennent vraiment le Corps et le Sang du Christ', 'Nous croyons que le Christ est réellement présent. Beaucoup de protestants parlent plutôt de mémorial.', '[{"text": "Jésus a dit « ceci est », pas « ceci représente ».", "translation": "Pas un symbole : une présence."}]'::jsonb, null, '{"id": "eg.d.c09_presence_reelle", "unitId": "eg.v.c09_presence_reelle", "word": "la présence réelle", "translation": "le pain et le vin deviennent vraiment le Corps et le Sang du Christ", "partOfSpeech": "concept", "collection": "notion", "explanation": "Nous croyons que le Christ est réellement présent. Beaucoup de protestants parlent plutôt de mémorial.", "examples": [{"text": "Jésus a dit « ceci est », pas « ceci représente ».", "translation": "Pas un symbole : une présence."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_pain_de_vie', 'eg', 'le pain de vie', 'titre que Jésus se donne en Jean 6 : il nourrit pour la vie éternelle', 'Jésus dit : « Moi, je suis le pain de vie » (Jn 6, 35). L''eucharistie le rend présent.', '[{"text": "Jésus se nomme le pain de vie.", "translation": "Il nourrit pour l''éternité."}]'::jsonb, null, '{"id": "eg.d.c09_pain_de_vie", "unitId": "eg.v.c09_pain_de_vie", "word": "le pain de vie", "translation": "titre que Jésus se donne en Jean 6 : il nourrit pour la vie éternelle", "partOfSpeech": "concept", "collection": "notion", "explanation": "Jésus dit : « Moi, je suis le pain de vie » (Jn 6, 35). L''eucharistie le rend présent.", "examples": [{"text": "Jésus se nomme le pain de vie.", "translation": "Il nourrit pour l''éternité."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_qorban', 'eg', 'le qorban', 'pain levé de la messe, marqué d''une croix ; veut dire « offrande »', 'Le qorban est préparé spécialement par l''Église. Le levain évoque la vie et la Résurrection.', '[{"text": "Le qorban est un pain rond marqué d''une croix.", "translation": "Un pain préparé pour la messe."}]'::jsonb, null, '{"id": "eg.d.c09_qorban", "unitId": "eg.v.c09_qorban", "word": "le qorban", "translation": "pain levé de la messe, marqué d''une croix ; veut dire « offrande »", "partOfSpeech": "concept", "collection": "objet", "explanation": "Le qorban est préparé spécialement par l''Église. Le levain évoque la vie et la Résurrection.", "examples": [{"text": "Le qorban est un pain rond marqué d''une croix.", "translation": "Un pain préparé pour la messe."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_jeune_eucharistique', 'eg', 'le jeûne eucharistique', 'ni nourriture ni boisson avant la communion', 'Il dure au moins neuf heures pour un adulte, selon l''usage. Le prêtre adapte pour les enfants et les malades.', '[{"text": "On reste à jeun avant de communier.", "translation": "Le Christ est la première nourriture du jour."}]'::jsonb, null, '{"id": "eg.d.c09_jeune_eucharistique", "unitId": "eg.v.c09_jeune_eucharistique", "word": "le jeûne eucharistique", "translation": "ni nourriture ni boisson avant la communion", "partOfSpeech": "concept", "collection": "notion", "explanation": "Il dure au moins neuf heures pour un adulte, selon l''usage. Le prêtre adapte pour les enfants et les malades.", "examples": [{"text": "On reste à jeun avant de communier.", "translation": "Le Christ est la première nourriture du jour."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_communion', 'eg', 'la communion', 'le moment où le fidèle reçoit le Corps et le Sang du Christ', 'Communier, c''est entrer en union avec le Christ et avec toute l''Église.', '[{"text": "On communie après s''être confessé.", "translation": "Recevoir le Christ, c''est être uni aux autres."}]'::jsonb, null, '{"id": "eg.d.c09_communion", "unitId": "eg.v.c09_communion", "word": "la communion", "translation": "le moment où le fidèle reçoit le Corps et le Sang du Christ", "partOfSpeech": "concept", "collection": "notion", "explanation": "Communier, c''est entrer en union avec le Christ et avec toute l''Église.", "examples": [{"text": "On communie après s''être confessé.", "translation": "Recevoir le Christ, c''est être uni aux autres."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_confession', 'eg', 'la confession (la pénitence)', 'sacrement du pardon des péchés commis après le baptême', 'On dit ses péchés à un prêtre, qui prie l''absolution. Elle se répète au fil de la vie.', '[{"text": "Après le baptême, on a la confession.", "translation": "Un pardon qui revient autant de fois que nécessaire."}]'::jsonb, null, '{"id": "eg.d.c09_confession", "unitId": "eg.v.c09_confession", "word": "la confession (la pénitence)", "translation": "sacrement du pardon des péchés commis après le baptême", "partOfSpeech": "concept", "collection": "notion", "explanation": "On dit ses péchés à un prêtre, qui prie l''absolution. Elle se répète au fil de la vie.", "examples": [{"text": "Après le baptême, on a la confession.", "translation": "Un pardon qui revient autant de fois que nécessaire."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_lier_et_delier', 'eg', 'lier et délier', 'retenir ou remettre les péchés (Mt 18, 18 ; Jn 20, 23)', 'Jésus donne aux apôtres le pouvoir de lier et de délier. C''est la source de la confession.', '[{"text": "Lier et délier : remettre ou retenir les péchés.", "translation": "Un pouvoir donné par le Christ aux apôtres."}]'::jsonb, null, '{"id": "eg.d.c09_lier_et_delier", "unitId": "eg.v.c09_lier_et_delier", "word": "lier et délier", "translation": "retenir ou remettre les péchés (Mt 18, 18 ; Jn 20, 23)", "partOfSpeech": "expression", "collection": "notion", "explanation": "Jésus donne aux apôtres le pouvoir de lier et de délier. C''est la source de la confession.", "examples": [{"text": "Lier et délier : remettre ou retenir les péchés.", "translation": "Un pouvoir donné par le Christ aux apôtres."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_absolution', 'eg', 'l''absolution', 'prière où le prêtre, la croix sur la tête, donne le pardon de Dieu', 'Le prêtre prie, mais c''est Dieu qui pardonne. L''absolution est le cœur du sacrement.', '[{"text": "Le prêtre prie l''absolution.", "translation": "Le pénitent est à genoux, la croix sur la tête."}]'::jsonb, null, '{"id": "eg.d.c09_absolution", "unitId": "eg.v.c09_absolution", "word": "l''absolution", "translation": "prière où le prêtre, la croix sur la tête, donne le pardon de Dieu", "partOfSpeech": "concept", "collection": "priere", "explanation": "Le prêtre prie, mais c''est Dieu qui pardonne. L''absolution est le cœur du sacrement.", "examples": [{"text": "Le prêtre prie l''absolution.", "translation": "Le pénitent est à genoux, la croix sur la tête."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_pere_de_confession', 'eg', 'le père de confession', 'prêtre qui reçoit nos confessions et nous guide dans la durée', 'On garde le même père de confession : il connaît notre vie et nous guide. Il est tenu au secret.', '[{"text": "Je vais voir mon père de confession.", "translation": "Un prêtre qui accompagne dans la durée."}]'::jsonb, null, '{"id": "eg.d.c09_pere_de_confession", "unitId": "eg.v.c09_pere_de_confession", "word": "le père de confession", "translation": "prêtre qui reçoit nos confessions et nous guide dans la durée", "partOfSpeech": "person", "collection": "notion", "explanation": "On garde le même père de confession : il connaît notre vie et nous guide. Il est tenu au secret.", "examples": [{"text": "Je vais voir mon père de confession.", "translation": "Un prêtre qui accompagne dans la durée."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_repentance', 'eg', 'la repentance', 'changement du cœur : regret sincère et décision de changer', 'La repentance ne se réduit pas à des paroles. Elle suppose un regret, une décision, la confession et la confiance en Dieu.', '[{"text": "Le fils prodigue est un modèle de repentance.", "translation": "On change vraiment de direction."}]'::jsonb, null, '{"id": "eg.d.c09_repentance", "unitId": "eg.v.c09_repentance", "word": "la repentance", "translation": "changement du cœur : regret sincère et décision de changer", "partOfSpeech": "concept", "collection": "notion", "explanation": "La repentance ne se réduit pas à des paroles. Elle suppose un regret, une décision, la confession et la confiance en Dieu.", "examples": [{"text": "Le fils prodigue est un modèle de repentance.", "translation": "On change vraiment de direction."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_secret_de_la_confession', 'eg', 'le secret de la confession', 'le prêtre ne révèle jamais ce qu''il entend en confession', 'Ce secret est absolu et l''Église punit le prêtre qui le trahirait. Il permet de se confier sans crainte.', '[{"text": "Le prêtre garde le secret de la confession.", "translation": "Rien de ce qui est dit ne sort."}]'::jsonb, null, '{"id": "eg.d.c09_secret_de_la_confession", "unitId": "eg.v.c09_secret_de_la_confession", "word": "le secret de la confession", "translation": "le prêtre ne révèle jamais ce qu''il entend en confession", "partOfSpeech": "concept", "collection": "notion", "explanation": "Ce secret est absolu et l''Église punit le prêtre qui le trahirait. Il permet de se confier sans crainte.", "examples": [{"text": "Le prêtre garde le secret de la confession.", "translation": "Rien de ce qui est dit ne sort."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_contrition', 'eg', 'la contrition', 'regret sincère de ses péchés, premier pas de la repentance', 'Le mot veut dire « cœur brisé ». Sans regret sincère, la confession n''est qu''un récit.', '[{"text": "La contrition ouvre la confession.", "translation": "Un vrai regret, pas une formule."}]'::jsonb, null, '{"id": "eg.d.c09_contrition", "unitId": "eg.v.c09_contrition", "word": "la contrition", "translation": "regret sincère de ses péchés, premier pas de la repentance", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le mot veut dire « cœur brisé ». Sans regret sincère, la confession n''est qu''un récit.", "examples": [{"text": "La contrition ouvre la confession.", "translation": "Un vrai regret, pas une formule."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_onction_des_malades', 'eg', 'l''onction des malades', 'sacrement de l''huile : prière pour la guérison de l''âme et du corps du malade', 'Elle repose sur Jc 5, 14-15. Un prêtre prie et oint le malade d''huile.', '[{"text": "Le prêtre oint le malade d''huile.", "translation": "Un sacrement qui relève."}]'::jsonb, null, '{"id": "eg.d.c09_onction_des_malades", "unitId": "eg.v.c09_onction_des_malades", "word": "l''onction des malades", "translation": "sacrement de l''huile : prière pour la guérison de l''âme et du corps du malade", "partOfSpeech": "concept", "collection": "notion", "explanation": "Elle repose sur Jc 5, 14-15. Un prêtre prie et oint le malade d''huile.", "examples": [{"text": "Le prêtre oint le malade d''huile.", "translation": "Un sacrement qui relève."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_qandil', 'eg', 'le qandil', 'nom arabe de l''onction des malades : « la lampe »', 'Le mot vient des sept mèches allumées pendant les sept prières.', '[{"text": "On célèbre le qandil auprès du malade.", "translation": "Une lampe pour dire : Dieu éclaire la maladie."}]'::jsonb, null, '{"id": "eg.d.c09_qandil", "unitId": "eg.v.c09_qandil", "word": "le qandil", "translation": "nom arabe de l''onction des malades : « la lampe »", "partOfSpeech": "concept", "collection": "objet", "explanation": "Le mot vient des sept mèches allumées pendant les sept prières.", "examples": [{"text": "On célèbre le qandil auprès du malade.", "translation": "Une lampe pour dire : Dieu éclaire la maladie."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_sept_meches', 'eg', 'les sept mèches', 'sept mèches de coton allumées l''une après l''autre pendant les sept prières', 'Avant chaque prière, on allume une mèche. Sept est le nombre de la plénitude dans la Bible.', '[{"text": "On allume une mèche avant chaque prière.", "translation": "Sept mèches, sept prières."}]'::jsonb, null, '{"id": "eg.d.c09_sept_meches", "unitId": "eg.v.c09_sept_meches", "word": "les sept mèches", "translation": "sept mèches de coton allumées l''une après l''autre pendant les sept prières", "partOfSpeech": "concept", "collection": "objet", "explanation": "Avant chaque prière, on allume une mèche. Sept est le nombre de la plénitude dans la Bible.", "examples": [{"text": "On allume une mèche avant chaque prière.", "translation": "Sept mèches, sept prières."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_qandil_general', 'eg', 'le qandil général', 'qandil annuel pour tous les fidèles, avant la semaine de la Passion', 'Selon l''usage, il a lieu le vendredi qui précède la semaine de la Passion.', '[{"text": "On est oint même en bonne santé.", "translation": "On se prépare à la semaine sainte."}]'::jsonb, null, '{"id": "eg.d.c09_qandil_general", "unitId": "eg.v.c09_qandil_general", "word": "le qandil général", "translation": "qandil annuel pour tous les fidèles, avant la semaine de la Passion", "partOfSpeech": "event", "collection": "date", "explanation": "Selon l''usage, il a lieu le vendredi qui précède la semaine de la Passion.", "examples": [{"text": "On est oint même en bonne santé.", "translation": "On se prépare à la semaine sainte."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_mariage', 'eg', 'le mariage (le couronnement)', 'sacrement où Dieu unit un homme et une femme, avec le rite des couronnes', 'Le mariage est un sacrement, célébré à l''église par un prêtre. On l''appelle aussi le couronnement.', '[{"text": "Le mariage est célébré à l''église.", "translation": "Un sacrement, pas seulement un contrat."}]'::jsonb, null, '{"id": "eg.d.c09_mariage", "unitId": "eg.v.c09_mariage", "word": "le mariage (le couronnement)", "translation": "sacrement où Dieu unit un homme et une femme, avec le rite des couronnes", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le mariage est un sacrement, célébré à l''église par un prêtre. On l''appelle aussi le couronnement.", "examples": [{"text": "Le mariage est célébré à l''église.", "translation": "Un sacrement, pas seulement un contrat."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_couronnement', 'eg', 'le couronnement', 'rite où le prêtre place des couronnes sur la tête des époux', 'Les couronnes disent que les époux sont roi et reine de leur nouveau foyer. Le rite donne son nom au mariage.', '[{"text": "Le prêtre couronne les époux.", "translation": "Roi et reine d''un foyer."}]'::jsonb, null, '{"id": "eg.d.c09_couronnement", "unitId": "eg.v.c09_couronnement", "word": "le couronnement", "translation": "rite où le prêtre place des couronnes sur la tête des époux", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les couronnes disent que les époux sont roi et reine de leur nouveau foyer. Le rite donne son nom au mariage.", "examples": [{"text": "Le prêtre couronne les époux.", "translation": "Roi et reine d''un foyer."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_indissolubilite', 'eg', 'l''indissolubilité', 'le mariage ne se défait pas : Dieu a uni les époux', 'Mt 19, 6 : « Que l''homme ne le sépare pas ». L''Église n''admet la rupture que dans des cas très graves, d''abord l''adultère.', '[{"text": "Le mariage est indissoluble.", "translation": "C''est Dieu qui unit."}]'::jsonb, null, '{"id": "eg.d.c09_indissolubilite", "unitId": "eg.v.c09_indissolubilite", "word": "l''indissolubilité", "translation": "le mariage ne se défait pas : Dieu a uni les époux", "partOfSpeech": "concept", "collection": "notion", "explanation": "Mt 19, 6 : « Que l''homme ne le sépare pas ». L''Église n''admet la rupture que dans des cas très graves, d''abord l''adultère.", "examples": [{"text": "Le mariage est indissoluble.", "translation": "C''est Dieu qui unit."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_noces_de_cana', 'eg', 'les noces de Cana', 'mariage où Jésus change l''eau en vin (Jn 2)', 'Jésus y assiste et bénit les noces : le mariage est béni par le Christ dès le début de son ministère.', '[{"text": "À Cana, Jésus change l''eau en vin.", "translation": "Le Christ honore le mariage."}]'::jsonb, null, '{"id": "eg.d.c09_noces_de_cana", "unitId": "eg.v.c09_noces_de_cana", "word": "les noces de Cana", "translation": "mariage où Jésus change l''eau en vin (Jn 2)", "partOfSpeech": "event", "collection": "date", "explanation": "Jésus y assiste et bénit les noces : le mariage est béni par le Christ dès le début de son ministère.", "examples": [{"text": "À Cana, Jésus change l''eau en vin.", "translation": "Le Christ honore le mariage."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_sacerdoce', 'eg', 'le sacerdoce (l''ordination)', 'sacrement où l''évêque ordonne par l''imposition des mains', 'Le sacerdoce est le septième sacrement. Il ne se répète pas pour un même degré.', '[{"text": "Le sacerdoce se transmet par les mains.", "translation": "Une chaîne qui remonte aux apôtres."}]'::jsonb, null, '{"id": "eg.d.c09_sacerdoce", "unitId": "eg.v.c09_sacerdoce", "word": "le sacerdoce (l''ordination)", "translation": "sacrement où l''évêque ordonne par l''imposition des mains", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le sacerdoce est le septième sacrement. Il ne se répète pas pour un même degré.", "examples": [{"text": "Le sacerdoce se transmet par les mains.", "translation": "Une chaîne qui remonte aux apôtres."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_ordination', 'eg', 'l''ordination', 'la célébration du sacerdoce : l''évêque impose les mains au candidat', 'Le mot s''emploie pour chaque degré. Seul un évêque peut ordonner.', '[{"text": "L''évêque impose les mains au candidat.", "translation": "On devient diacre, prêtre ou évêque."}]'::jsonb, null, '{"id": "eg.d.c09_ordination", "unitId": "eg.v.c09_ordination", "word": "l''ordination", "translation": "la célébration du sacerdoce : l''évêque impose les mains au candidat", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le mot s''emploie pour chaque degré. Seul un évêque peut ordonner.", "examples": [{"text": "L''évêque impose les mains au candidat.", "translation": "On devient diacre, prêtre ou évêque."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_sacrements_d_initiation', 'eg', 'les sacrements d''initiation', 'baptême, confirmation et eucharistie : devenir et rester chrétien', 'Pour un enfant, ces trois sacrements se suivent. C''est un regroupement pratique.', '[{"text": "Plongé, scellé, nourri.", "translation": "Trois étapes pour entrer dans l''Église."}]'::jsonb, null, '{"id": "eg.d.c09_sacrements_d_initiation", "unitId": "eg.v.c09_sacrements_d_initiation", "word": "les sacrements d''initiation", "translation": "baptême, confirmation et eucharistie : devenir et rester chrétien", "partOfSpeech": "concept", "collection": "notion", "explanation": "Pour un enfant, ces trois sacrements se suivent. C''est un regroupement pratique.", "examples": [{"text": "Plongé, scellé, nourri.", "translation": "Trois étapes pour entrer dans l''Église."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_sacrements_de_guerison', 'eg', 'les sacrements de guérison', 'confession et onction des malades : le pardon et le soulagement', 'Ces deux sacrements se répètent au fil de la vie. C''est un regroupement pratique.', '[{"text": "Dieu relève chaque fois.", "translation": "On peut tomber plusieurs fois."}]'::jsonb, null, '{"id": "eg.d.c09_sacrements_de_guerison", "unitId": "eg.v.c09_sacrements_de_guerison", "word": "les sacrements de guérison", "translation": "confession et onction des malades : le pardon et le soulagement", "partOfSpeech": "concept", "collection": "notion", "explanation": "Ces deux sacrements se répètent au fil de la vie. C''est un regroupement pratique.", "examples": [{"text": "Dieu relève chaque fois.", "translation": "On peut tomber plusieurs fois."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c09_sacrements_de_vocation', 'eg', 'les sacrements de vocation', 'mariage et sacerdoce : la grâce de servir dans un foyer ou dans l''Église', 'Dans les deux cas, Dieu donne la grâce d''une mission. C''est un regroupement pratique.', '[{"text": "Fonder un foyer ou servir l''Église.", "translation": "Deux manières de se donner."}]'::jsonb, null, '{"id": "eg.d.c09_sacrements_de_vocation", "unitId": "eg.v.c09_sacrements_de_vocation", "word": "les sacrements de vocation", "translation": "mariage et sacerdoce : la grâce de servir dans un foyer ou dans l''Église", "partOfSpeech": "concept", "collection": "notion", "explanation": "Dans les deux cas, Dieu donne la grâce d''une mission. C''est un regroupement pratique.", "examples": [{"text": "Fonder un foyer ou servir l''Église.", "translation": "Deux manières de se donner."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_orientation_est', 'eg', 'l''orientation vers l''est', 'l''église est tournée vers l''est, vers le Christ, soleil de justice', 'Les églises coptes sont bâties vers l''est, et l''on prie tourné vers lui. Le soleil s''y lève, ce qui rappelle le Christ, soleil de justice ; l''Éden est à l''orient et le Christ reviendra comme l''éclair qui part de l''orient.', '[{"text": "Le sanctuaire est à l''extrémité est de l''église.", "translation": "On prie tourné vers le soleil levant."}]'::jsonb, null, '{"id": "eg.d.c10_orientation_est", "unitId": "eg.v.c10_orientation_est", "word": "l''orientation vers l''est", "translation": "l''église est tournée vers l''est, vers le Christ, soleil de justice", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les églises coptes sont bâties vers l''est, et l''on prie tourné vers lui. Le soleil s''y lève, ce qui rappelle le Christ, soleil de justice ; l''Éden est à l''orient et le Christ reviendra comme l''éclair qui part de l''orient.", "examples": [{"text": "Le sanctuaire est à l''extrémité est de l''église.", "translation": "On prie tourné vers le soleil levant."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_arche_de_noe', 'eg', 'l''arche de Noé', 'forme la plus courante d''une église : un navire qui sauve', 'Beaucoup d''églises ont la forme d''un bâtiment allongé comme un navire. Au déluge, l''arche a sauvé ceux qui étaient dedans ; dans l''Église, le Christ sauve son peuple.', '[{"text": "L''église copte a souvent la forme d''une arche.", "translation": "Elle rappelle le navire qui sauve."}]'::jsonb, null, '{"id": "eg.d.c10_arche_de_noe", "unitId": "eg.v.c10_arche_de_noe", "word": "l''arche de Noé", "translation": "forme la plus courante d''une église : un navire qui sauve", "partOfSpeech": "concept", "collection": "objet", "explanation": "Beaucoup d''églises ont la forme d''un bâtiment allongé comme un navire. Au déluge, l''arche a sauvé ceux qui étaient dedans ; dans l''Église, le Christ sauve son peuple.", "examples": [{"text": "L''église copte a souvent la forme d''une arche.", "translation": "Elle rappelle le navire qui sauve."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_nef', 'eg', 'la nef', 'la grande salle où se tiennent les fidèles', 'La nef est la partie centrale de l''église. Son nom vient du latin navis, le navire, car l''église est une arche. Devant elle se tient le chœur des diacres.', '[{"text": "Les fidèles prient dans la nef.", "translation": "La nef est la grande salle de l''assemblée."}]'::jsonb, null, '{"id": "eg.d.c10_nef", "unitId": "eg.v.c10_nef", "word": "la nef", "translation": "la grande salle où se tiennent les fidèles", "partOfSpeech": "place", "collection": "objet", "explanation": "La nef est la partie centrale de l''église. Son nom vient du latin navis, le navire, car l''église est une arche. Devant elle se tient le chœur des diacres.", "examples": [{"text": "Les fidèles prient dans la nef.", "translation": "La nef est la grande salle de l''assemblée."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_narthex', 'eg', 'le narthex', 'l''entrée de l''église, à l''ouest, autrefois pour les catéchumènes', 'Le narthex est le vestibule d''entrée, à l''ouest. Autrefois, les catéchumènes, qui préparent leur baptême, y restaient pendant la liturgie. Il correspond au parvis du Tabernacle.', '[{"text": "On passe par le narthex pour entrer dans l''église.", "translation": "C''est l''entrée."}]'::jsonb, null, '{"id": "eg.d.c10_narthex", "unitId": "eg.v.c10_narthex", "word": "le narthex", "translation": "l''entrée de l''église, à l''ouest, autrefois pour les catéchumènes", "partOfSpeech": "concept", "collection": "objet", "explanation": "Le narthex est le vestibule d''entrée, à l''ouest. Autrefois, les catéchumènes, qui préparent leur baptême, y restaient pendant la liturgie. Il correspond au parvis du Tabernacle.", "examples": [{"text": "On passe par le narthex pour entrer dans l''église.", "translation": "C''est l''entrée."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_tabernacle_de_moise', 'eg', 'le Tabernacle de Moïse', 'la tente de Dieu bâtie au Sinaï sur un modèle montré à Moïse', 'Au Sinaï, Dieu montre à Moïse le modèle d''une tente sacrée. Elle a trois espaces : le parvis, le lieu saint et le saint des saints. La tradition rapproche ces trois espaces des trois parties de l''église.', '[{"text": "Dieu montre le modèle du Tabernacle à Moïse.", "translation": "Le Tabernacle est une tente."}]'::jsonb, null, '{"id": "eg.d.c10_tabernacle_de_moise", "unitId": "eg.v.c10_tabernacle_de_moise", "word": "le Tabernacle de Moïse", "translation": "la tente de Dieu bâtie au Sinaï sur un modèle montré à Moïse", "partOfSpeech": "concept", "collection": "objet", "explanation": "Au Sinaï, Dieu montre à Moïse le modèle d''une tente sacrée. Elle a trois espaces : le parvis, le lieu saint et le saint des saints. La tradition rapproche ces trois espaces des trois parties de l''église.", "examples": [{"text": "Dieu montre le modèle du Tabernacle à Moïse.", "translation": "Le Tabernacle est une tente."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_lieu_saint', 'eg', 'le lieu saint', 'le deuxième espace du Tabernacle ; il correspond à la nef', 'Le lieu saint est la première salle de la tente, où les prêtres servaient. Il correspond à la nef de l''église. Le parvis, la cour en plein air, correspond au narthex.', '[{"text": "Les prêtres servaient dans le lieu saint.", "translation": "C''est le deuxième espace du Tabernacle."}]'::jsonb, null, '{"id": "eg.d.c10_lieu_saint", "unitId": "eg.v.c10_lieu_saint", "word": "le lieu saint", "translation": "le deuxième espace du Tabernacle ; il correspond à la nef", "partOfSpeech": "place", "collection": "objet", "explanation": "Le lieu saint est la première salle de la tente, où les prêtres servaient. Il correspond à la nef de l''église. Le parvis, la cour en plein air, correspond au narthex.", "examples": [{"text": "Les prêtres servaient dans le lieu saint.", "translation": "C''est le deuxième espace du Tabernacle."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_saint_des_saints', 'eg', 'le saint des saints', 'le dernier espace du Tabernacle ; il correspond au sanctuaire', 'Le saint des saints est le lieu le plus sacré du Tabernacle, où se trouvait l''arche de l''alliance. Seul le grand prêtre y entrait, une fois par an. Il correspond au sanctuaire de l''église.', '[{"text": "Le grand prêtre entre dans le saint des saints.", "translation": "C''est l''espace le plus proche de Dieu."}]'::jsonb, null, '{"id": "eg.d.c10_saint_des_saints", "unitId": "eg.v.c10_saint_des_saints", "word": "le saint des saints", "translation": "le dernier espace du Tabernacle ; il correspond au sanctuaire", "partOfSpeech": "place", "collection": "objet", "explanation": "Le saint des saints est le lieu le plus sacré du Tabernacle, où se trouvait l''arche de l''alliance. Seul le grand prêtre y entrait, une fois par an. Il correspond au sanctuaire de l''église.", "examples": [{"text": "Le grand prêtre entre dans le saint des saints.", "translation": "C''est l''espace le plus proche de Dieu."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_iconostase', 'eg', 'l''iconostase (higab)', 'cloison couverte d''icônes qui sépare la nef et le sanctuaire', 'L''iconostase est le mur d''icônes entre la nef et le sanctuaire. En arabe, on l''appelle higab, le voile. Elle n''isole pas : pendant la liturgie, ses rideaux s''ouvrent sur le ciel.', '[{"text": "L''iconostase est couverte d''icônes.", "translation": "Le higab est le mur d''icônes."}]'::jsonb, null, '{"id": "eg.d.c10_iconostase", "unitId": "eg.v.c10_iconostase", "word": "l''iconostase (higab)", "translation": "cloison couverte d''icônes qui sépare la nef et le sanctuaire", "partOfSpeech": "concept", "collection": "objet", "explanation": "L''iconostase est le mur d''icônes entre la nef et le sanctuaire. En arabe, on l''appelle higab, le voile. Elle n''isole pas : pendant la liturgie, ses rideaux s''ouvrent sur le ciel.", "examples": [{"text": "L''iconostase est couverte d''icônes.", "translation": "Le higab est le mur d''icônes."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_porte_royale', 'eg', 'la porte royale', 'la grande porte centrale de l''iconostase, qui mène à l''autel', 'La porte royale est l''ouverture principale de l''iconostase. Le Christ, le Roi, vient à nous par elle dans la liturgie. L''icône de la Cène est souvent juste au-dessus.', '[{"text": "La Cène est au-dessus de la porte royale.", "translation": "Elle est plus grande que les portes latérales."}]'::jsonb, null, '{"id": "eg.d.c10_porte_royale", "unitId": "eg.v.c10_porte_royale", "word": "la porte royale", "translation": "la grande porte centrale de l''iconostase, qui mène à l''autel", "partOfSpeech": "concept", "collection": "objet", "explanation": "La porte royale est l''ouverture principale de l''iconostase. Le Christ, le Roi, vient à nous par elle dans la liturgie. L''icône de la Cène est souvent juste au-dessus.", "examples": [{"text": "La Cène est au-dessus de la porte royale.", "translation": "Elle est plus grande que les portes latérales."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_saint_jean_baptiste', 'eg', 'saint Jean-Baptiste', 'le Précurseur, qui a préparé la venue du Christ', 'Jean-Baptiste est le prophète qui annonce le Christ et le baptise au Jourdain. On l''appelle le Précurseur. Son icône est souvent placée près de celle du Christ.', '[{"text": "Jean-Baptiste baptise Jésus dans le Jourdain.", "translation": "Son icône est près du Christ."}]'::jsonb, null, '{"id": "eg.d.c10_saint_jean_baptiste", "unitId": "eg.v.c10_saint_jean_baptiste", "word": "saint Jean-Baptiste", "translation": "le Précurseur, qui a préparé la venue du Christ", "partOfSpeech": "person", "collection": "saint", "explanation": "Jean-Baptiste est le prophète qui annonce le Christ et le baptise au Jourdain. On l''appelle le Précurseur. Son icône est souvent placée près de celle du Christ.", "examples": [{"text": "Jean-Baptiste baptise Jésus dans le Jourdain.", "translation": "Son icône est près du Christ."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_oeuf_d_autruche', 'eg', 'l''œuf d''autruche', 'œuf suspendu devant l''iconostase : Dieu veille sans cesse, et la résurrection', 'Un œuf d''autruche est suspendu devant l''iconostase, près de la porte royale. Selon la tradition, l''autruche qui veille sur ses œufs rappelle que Dieu veille sur nous sans cesse, et la coquille qui paraît morte annonce la résurrection.', '[{"text": "Un œuf d''autruche est suspendu près de la porte royale.", "translation": "Il parle de la veille de Dieu et de la résurrection."}]'::jsonb, null, '{"id": "eg.d.c10_oeuf_d_autruche", "unitId": "eg.v.c10_oeuf_d_autruche", "word": "l''œuf d''autruche", "translation": "œuf suspendu devant l''iconostase : Dieu veille sans cesse, et la résurrection", "partOfSpeech": "concept", "collection": "objet", "explanation": "Un œuf d''autruche est suspendu devant l''iconostase, près de la porte royale. Selon la tradition, l''autruche qui veille sur ses œufs rappelle que Dieu veille sur nous sans cesse, et la coquille qui paraît morte annonce la résurrection.", "examples": [{"text": "Un œuf d''autruche est suspendu près de la porte royale.", "translation": "Il parle de la veille de Dieu et de la résurrection."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_lampe_a_huile', 'eg', 'la lampe à huile', 'lampe allumée devant les icônes : la lumière du Christ', 'Devant les icônes et dans le sanctuaire brûlent des lampes à huile. Elles représentent la lumière du Christ et rappellent les vierges sages qui gardent leur lampe allumée.', '[{"text": "Une lampe brûle devant l''icône.", "translation": "La lumière du Christ reste allumée."}]'::jsonb, null, '{"id": "eg.d.c10_lampe_a_huile", "unitId": "eg.v.c10_lampe_a_huile", "word": "la lampe à huile", "translation": "lampe allumée devant les icônes : la lumière du Christ", "partOfSpeech": "concept", "collection": "objet", "explanation": "Devant les icônes et dans le sanctuaire brûlent des lampes à huile. Elles représentent la lumière du Christ et rappellent les vierges sages qui gardent leur lampe allumée.", "examples": [{"text": "Une lampe brûle devant l''icône.", "translation": "La lumière du Christ reste allumée."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_encens', 'eg', 'l''encens', 'résine parfumée dont la fumée représente les prières qui montent', 'L''encens est une résine odorante que le prêtre brûle sur du charbon, dans l''encensoir qu''il balance. Sa fumée représente les prières des fidèles qui montent vers Dieu.', '[{"text": "Le prêtre offre l''encens avec l''encensoir.", "translation": "La fumée monte comme la prière."}]'::jsonb, null, '{"id": "eg.d.c10_encens", "unitId": "eg.v.c10_encens", "word": "l''encens", "translation": "résine parfumée dont la fumée représente les prières qui montent", "partOfSpeech": "concept", "collection": "objet", "explanation": "L''encens est une résine odorante que le prêtre brûle sur du charbon, dans l''encensoir qu''il balance. Sa fumée représente les prières des fidèles qui montent vers Dieu.", "examples": [{"text": "Le prêtre offre l''encens avec l''encensoir.", "translation": "La fumée monte comme la prière."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_adoration', 'eg', 'l''adoration', 'honneur suprême, dû à Dieu seul', 'L''adoration est l''hommage qu''on ne rend qu''à Dieu. Les saints et les icônes reçoivent la vénération : on s''incline, on embrasse, on allume une bougie, mais on n''adore jamais.', '[{"text": "L''adoration est due à Dieu seul.", "translation": "On vénère l''icône, on adore Dieu."}]'::jsonb, null, '{"id": "eg.d.c10_adoration", "unitId": "eg.v.c10_adoration", "word": "l''adoration", "translation": "honneur suprême, dû à Dieu seul", "partOfSpeech": "concept", "collection": "notion", "explanation": "L''adoration est l''hommage qu''on ne rend qu''à Dieu. Les saints et les icônes reçoivent la vénération : on s''incline, on embrasse, on allume une bougie, mais on n''adore jamais.", "examples": [{"text": "L''adoration est due à Dieu seul.", "translation": "On vénère l''icône, on adore Dieu."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_haikal', 'eg', 'le haikal', 'le sanctuaire, partie la plus sainte de l''église, à l''est', 'Le haikal est le sanctuaire : on y trouve l''autel. Son nom arabe veut dire « temple ». Il est séparé de la nef par l''iconostase et réservé au clergé et aux diacres ; derrière l''autel, il y a souvent le trône de l''évêque.', '[{"text": "Le prêtre entre dans le haikal.", "translation": "Le haikal est le sanctuaire."}]'::jsonb, null, '{"id": "eg.d.c10_haikal", "unitId": "eg.v.c10_haikal", "word": "le haikal", "translation": "le sanctuaire, partie la plus sainte de l''église, à l''est", "partOfSpeech": "place", "collection": "objet", "explanation": "Le haikal est le sanctuaire : on y trouve l''autel. Son nom arabe veut dire « temple ». Il est séparé de la nef par l''iconostase et réservé au clergé et aux diacres ; derrière l''autel, il y a souvent le trône de l''évêque.", "examples": [{"text": "Le prêtre entre dans le haikal.", "translation": "Le haikal est le sanctuaire."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_autel', 'eg', 'l''autel', 'cube de pierre ou de bois, qui représente le tombeau du Christ', 'L''autel est la table de la liturgie, un cube détaché du mur. Consacré au myron, il représente le tombeau du Christ et la table où il se donne. Il porte parfois des reliques de saints.', '[{"text": "La liturgie est célébrée sur l''autel.", "translation": "Seuls les clercs et les diacres le touchent."}]'::jsonb, null, '{"id": "eg.d.c10_autel", "unitId": "eg.v.c10_autel", "word": "l''autel", "translation": "cube de pierre ou de bois, qui représente le tombeau du Christ", "partOfSpeech": "concept", "collection": "objet", "explanation": "L''autel est la table de la liturgie, un cube détaché du mur. Consacré au myron, il représente le tombeau du Christ et la table où il se donne. Il porte parfois des reliques de saints.", "examples": [{"text": "La liturgie est célébrée sur l''autel.", "translation": "Seuls les clercs et les diacres le touchent."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_entrer_dechausse', 'eg', 'entrer déchaussé', 'ôter ses chaussures pour entrer dans le haikal, comme Moïse', 'Dans le haikal, le clergé et les diacres entrent sans chaussures. Devant le buisson ardent, Dieu dit à Moïse d''ôter ses sandales, car le lieu est une terre sainte : c''est un signe de respect et d''humilité.', '[{"text": "On enlève ses chaussures avant d''entrer dans le haikal.", "translation": "Moïse enlève ses sandales."}]'::jsonb, null, '{"id": "eg.d.c10_entrer_dechausse", "unitId": "eg.v.c10_entrer_dechausse", "word": "entrer déchaussé", "translation": "ôter ses chaussures pour entrer dans le haikal, comme Moïse", "partOfSpeech": "expression", "collection": "notion", "explanation": "Dans le haikal, le clergé et les diacres entrent sans chaussures. Devant le buisson ardent, Dieu dit à Moïse d''ôter ses sandales, car le lieu est une terre sainte : c''est un signe de respect et d''humilité.", "examples": [{"text": "On enlève ses chaussures avant d''entrer dans le haikal.", "translation": "Moïse enlève ses sandales."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_ciborium', 'eg', 'le ciborium', 'coupole sur quatre piliers au-dessus de l''autel', 'Le ciborium est un petit toit à coupole porté par quatre piliers. Il couvre l''autel comme le ciel couvre la terre. Il est souvent peint du Christ, des chérubins, des séraphins et des quatre évangélistes.', '[{"text": "Le ciborium est peint de l''icône du Christ.", "translation": "Les quatre piliers portent les évangélistes."}]'::jsonb, null, '{"id": "eg.d.c10_ciborium", "unitId": "eg.v.c10_ciborium", "word": "le ciborium", "translation": "coupole sur quatre piliers au-dessus de l''autel", "partOfSpeech": "concept", "collection": "objet", "explanation": "Le ciborium est un petit toit à coupole porté par quatre piliers. Il couvre l''autel comme le ciel couvre la terre. Il est souvent peint du Christ, des chérubins, des séraphins et des quatre évangélistes.", "examples": [{"text": "Le ciborium est peint de l''icône du Christ.", "translation": "Les quatre piliers portent les évangélistes."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_calice', 'eg', 'le calice', 'la coupe qui contient le vin mêlé d''eau, sang du Christ', 'Le calice est la coupe sacrée de la liturgie. Il contient le vin mêlé d''un peu d''eau, qui devient le sang du Christ. Il repose sur le coffret de l''autel, que l''on appelle aussi le trône.', '[{"text": "Le calice est posé sur l''autel.", "translation": "Le vin est mêlé d''eau."}]'::jsonb, null, '{"id": "eg.d.c10_calice", "unitId": "eg.v.c10_calice", "word": "le calice", "translation": "la coupe qui contient le vin mêlé d''eau, sang du Christ", "partOfSpeech": "concept", "collection": "objet", "explanation": "Le calice est la coupe sacrée de la liturgie. Il contient le vin mêlé d''un peu d''eau, qui devient le sang du Christ. Il repose sur le coffret de l''autel, que l''on appelle aussi le trône.", "examples": [{"text": "Le calice est posé sur l''autel.", "translation": "Le vin est mêlé d''eau."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_patene', 'eg', 'la patène', 'petit plateau rond qui porte le pain devenu le corps du Christ', 'La patène est un petit plateau plat et rond, en argent ou en or. Elle porte le pain de la liturgie. On dit qu''elle rappelle la crèche et le tombeau.', '[{"text": "La patène porte le pain.", "translation": "C''est le plateau du pain."}]'::jsonb, null, '{"id": "eg.d.c10_patene", "unitId": "eg.v.c10_patene", "word": "la patène", "translation": "petit plateau rond qui porte le pain devenu le corps du Christ", "partOfSpeech": "concept", "collection": "objet", "explanation": "La patène est un petit plateau plat et rond, en argent ou en or. Elle porte le pain de la liturgie. On dit qu''elle rappelle la crèche et le tombeau.", "examples": [{"text": "La patène porte le pain.", "translation": "C''est le plateau du pain."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_asterisque', 'eg', 'l''astérisque', 'l''étoile : deux bandes croisées posées sur la patène, en souvenir de l''étoile des mages', 'L''astérisque, ou étoile, est une petite armature de deux bandes croisées. Elle soutient le voile au-dessus du pain et rappelle l''étoile des mages. La cuillère, elle, sert à donner le sang du Christ aux fidèles.', '[{"text": "L''astérisque est posé sur la patène.", "translation": "Il rappelle l''étoile de Bethléem."}]'::jsonb, null, '{"id": "eg.d.c10_asterisque", "unitId": "eg.v.c10_asterisque", "word": "l''astérisque", "translation": "l''étoile : deux bandes croisées posées sur la patène, en souvenir de l''étoile des mages", "partOfSpeech": "concept", "collection": "objet", "explanation": "L''astérisque, ou étoile, est une petite armature de deux bandes croisées. Elle soutient le voile au-dessus du pain et rappelle l''étoile des mages. La cuillère, elle, sert à donner le sang du Christ aux fidèles.", "examples": [{"text": "L''astérisque est posé sur la patène.", "translation": "Il rappelle l''étoile de Bethléem."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_diaconat', 'eg', 'le diaconat', 'le ministère des diacres, en cinq rangs', 'Le diaconat est l''ensemble des services rendus par les diacres, du chantre à l''archidiacre. C''est un ministère de service, non de sacerdoce : le diacre aide le prêtre mais ne consacre pas.', '[{"text": "Le diaconat compte cinq rangs.", "translation": "On entre souvent dans le diaconat enfant."}]'::jsonb, null, '{"id": "eg.d.c10_diaconat", "unitId": "eg.v.c10_diaconat", "word": "le diaconat", "translation": "le ministère des diacres, en cinq rangs", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le diaconat est l''ensemble des services rendus par les diacres, du chantre à l''archidiacre. C''est un ministère de service, non de sacerdoce : le diacre aide le prêtre mais ne consacre pas.", "examples": [{"text": "Le diaconat compte cinq rangs.", "translation": "On entre souvent dans le diaconat enfant."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_psalte', 'eg', 'le psalte (épsaltos)', 'le chantre, premier rang du diaconat, qui chante les hymnes', 'Le psalte, du grec épsaltos, chante les hymnes et les psaumes pendant les offices. C''est le premier rang du diaconat, souvent reçu dès l''enfance.', '[{"text": "Le psalte chante pendant l''office.", "translation": "Les enfants deviennent souvent psaltes."}]'::jsonb, null, '{"id": "eg.d.c10_psalte", "unitId": "eg.v.c10_psalte", "word": "le psalte (épsaltos)", "translation": "le chantre, premier rang du diaconat, qui chante les hymnes", "partOfSpeech": "person", "collection": "notion", "explanation": "Le psalte, du grec épsaltos, chante les hymnes et les psaumes pendant les offices. C''est le premier rang du diaconat, souvent reçu dès l''enfance.", "examples": [{"text": "Le psalte chante pendant l''office.", "translation": "Les enfants deviennent souvent psaltes."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_lecteur', 'eg', 'le lecteur (anagnostès)', 'deuxième rang du diaconat : il lit les lectures de la Bible', 'Le lecteur, anagnostès en grec, lit les textes de la Bible à l''assemblée pendant la liturgie. Il étudie les Écritures et les Pères de l''Église.', '[{"text": "Le lecteur lit l''Écriture à l''église.", "translation": "L''anagnostès étudie les Pères."}]'::jsonb, null, '{"id": "eg.d.c10_lecteur", "unitId": "eg.v.c10_lecteur", "word": "le lecteur (anagnostès)", "translation": "deuxième rang du diaconat : il lit les lectures de la Bible", "partOfSpeech": "person", "collection": "notion", "explanation": "Le lecteur, anagnostès en grec, lit les textes de la Bible à l''assemblée pendant la liturgie. Il étudie les Écritures et les Pères de l''Église.", "examples": [{"text": "Le lecteur lit l''Écriture à l''église.", "translation": "L''anagnostès étudie les Pères."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_sous_diacre', 'eg', 'le sous-diacre (hypodiacre)', 'troisième rang du diaconat : il aide les diacres et garde les portes', 'Le sous-diacre, hypodiacre en grec, aide les diacres et veille aux portes de l''église pendant les offices.', '[{"text": "Le sous-diacre garde la porte.", "translation": "Hypo veut dire « sous »."}]'::jsonb, null, '{"id": "eg.d.c10_sous_diacre", "unitId": "eg.v.c10_sous_diacre", "word": "le sous-diacre (hypodiacre)", "translation": "troisième rang du diaconat : il aide les diacres et garde les portes", "partOfSpeech": "person", "collection": "notion", "explanation": "Le sous-diacre, hypodiacre en grec, aide les diacres et veille aux portes de l''église pendant les offices.", "examples": [{"text": "Le sous-diacre garde la porte.", "translation": "Hypo veut dire « sous »."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_abouna', 'eg', 'abouna', '« notre père » : nom donné au prêtre en arabe', 'Abouna veut dire « notre père » en arabe. C''est la façon habituelle d''appeler un prêtre copte, qui célèbre les sacrements et visite les familles. Il peut être marié, à condition de l''être avant son ordination.', '[{"text": "Les fidèles disent « Abouna » au prêtre.", "translation": "Abouna bénit la famille."}]'::jsonb, null, '{"id": "eg.d.c10_abouna", "unitId": "eg.v.c10_abouna", "word": "abouna", "translation": "« notre père » : nom donné au prêtre en arabe", "partOfSpeech": "expression", "collection": "notion", "explanation": "Abouna veut dire « notre père » en arabe. C''est la façon habituelle d''appeler un prêtre copte, qui célèbre les sacrements et visite les familles. Il peut être marié, à condition de l''être avant son ordination.", "examples": [{"text": "Les fidèles disent « Abouna » au prêtre.", "translation": "Abouna bénit la famille."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_qommos', 'eg', 'le qommos (hégoumène)', 'archiprêtre : prêtre promu à la tête des prêtres d''une église', 'Le qommos, ou hégoumène, est l''archiprêtre. On lui confie la direction du groupe de prêtres d''une église, souvent parce qu''il est le plus ancien. C''est une promotion, non un nouvel ordre.', '[{"text": "Le qommos dirige les prêtres de l''église.", "translation": "Il est souvent le plus ancien."}]'::jsonb, null, '{"id": "eg.d.c10_qommos", "unitId": "eg.v.c10_qommos", "word": "le qommos (hégoumène)", "translation": "archiprêtre : prêtre promu à la tête des prêtres d''une église", "partOfSpeech": "person", "collection": "notion", "explanation": "Le qommos, ou hégoumène, est l''archiprêtre. On lui confie la direction du groupe de prêtres d''une église, souvent parce qu''il est le plus ancien. C''est une promotion, non un nouvel ordre.", "examples": [{"text": "Le qommos dirige les prêtres de l''église.", "translation": "Il est souvent le plus ancien."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_metropolite', 'eg', 'le métropolite', 'évêque d''un grand diocèse, promu au-dessus des autres évêques', 'Le métropolite est un évêque promu à la tête d''un grand diocèse. Dans les prières, on le nomme avant les évêques.', '[{"text": "Le métropolite dirige un grand diocèse.", "translation": "On le cite avant les évêques."}]'::jsonb, null, '{"id": "eg.d.c10_metropolite", "unitId": "eg.v.c10_metropolite", "word": "le métropolite", "translation": "évêque d''un grand diocèse, promu au-dessus des autres évêques", "partOfSpeech": "person", "collection": "notion", "explanation": "Le métropolite est un évêque promu à la tête d''un grand diocèse. Dans les prières, on le nomme avant les évêques.", "examples": [{"text": "Le métropolite dirige un grand diocèse.", "translation": "On le cite avant les évêques."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_saint_synode', 'eg', 'le saint-synode', 'assemblée des évêques de l''Église, présidée par le pape', 'Le saint-synode réunit les évêques autour du pape d''Alexandrie. Il décide des grandes questions de foi et de discipline : c''est la version moderne des conciles.', '[{"text": "Le pape préside le saint-synode.", "translation": "Les évêques décident ensemble."}]'::jsonb, null, '{"id": "eg.d.c10_saint_synode", "unitId": "eg.v.c10_saint_synode", "word": "le saint-synode", "translation": "assemblée des évêques de l''Église, présidée par le pape", "partOfSpeech": "organization", "collection": "notion", "explanation": "Le saint-synode réunit les évêques autour du pape d''Alexandrie. Il décide des grandes questions de foi et de discipline : c''est la version moderne des conciles.", "examples": [{"text": "Le pape préside le saint-synode.", "translation": "Les évêques décident ensemble."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_qora_haykaleya', 'eg', 'la qor''a haykaleya', 'tirage au sort sur l''autel, par un enfant, pour désigner le pape', 'La qor''a haykaleya est le tirage au sort devant l''autel pendant la liturgie. Un enfant aux yeux bandés tire un nom parmi trois pour que Dieu choisisse le pape, comme les apôtres l''avaient fait pour Matthias.', '[{"text": "Un enfant tire le nom du pape sur l''autel.", "translation": "La qor''a haykaleya désigne le pape."}]'::jsonb, null, '{"id": "eg.d.c10_qora_haykaleya", "unitId": "eg.v.c10_qora_haykaleya", "word": "la qor''a haykaleya", "translation": "tirage au sort sur l''autel, par un enfant, pour désigner le pape", "partOfSpeech": "event", "collection": "notion", "explanation": "La qor''a haykaleya est le tirage au sort devant l''autel pendant la liturgie. Un enfant aux yeux bandés tire un nom parmi trois pour que Dieu choisisse le pape, comme les apôtres l''avaient fait pour Matthias.", "examples": [{"text": "Un enfant tire le nom du pape sur l''autel.", "translation": "La qor''a haykaleya désigne le pape."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_chenouda_iii', 'eg', 'Chenouda III', '117e pape d''Alexandrie, mort en 2012', 'Chenouda III est le 117e pape d''Alexandrie. Il est mort en mars 2012 ; Tawadros II lui a succédé. Il est enterré au monastère Anba Bishoy.', '[{"text": "Chenouda III est le 117e pape.", "translation": "Il est mort en mars 2012."}]'::jsonb, null, '{"id": "eg.d.c10_chenouda_iii", "unitId": "eg.v.c10_chenouda_iii", "word": "Chenouda III", "translation": "117e pape d''Alexandrie, mort en 2012", "partOfSpeech": "person", "collection": "pape", "explanation": "Chenouda III est le 117e pape d''Alexandrie. Il est mort en mars 2012 ; Tawadros II lui a succédé. Il est enterré au monastère Anba Bishoy.", "examples": [{"text": "Chenouda III est le 117e pape.", "translation": "Il est mort en mars 2012."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_tawadros_ii', 'eg', 'Tawadros II', '118e pape d''Alexandrie, choisi par tirage au sort en 2012', 'Tawadros II est le 118e successeur de saint Marc. Évêque, il a été tiré au sort le 4 novembre 2012 et intronisé le 18 novembre à la cathédrale Saint-Marc du Caire.', '[{"text": "Tawadros II est le 118e pape.", "translation": "Il a succédé à Chenouda III."}]'::jsonb, null, '{"id": "eg.d.c10_tawadros_ii", "unitId": "eg.v.c10_tawadros_ii", "word": "Tawadros II", "translation": "118e pape d''Alexandrie, choisi par tirage au sort en 2012", "partOfSpeech": "person", "collection": "pape", "explanation": "Tawadros II est le 118e successeur de saint Marc. Évêque, il a été tiré au sort le 4 novembre 2012 et intronisé le 18 novembre à la cathédrale Saint-Marc du Caire.", "examples": [{"text": "Tawadros II est le 118e pape.", "translation": "Il a succédé à Chenouda III."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_abbe', 'eg', 'l''abbé', 'le père et le chef d''un monastère, aussi appelé higoumène', 'L''abbé dirige le monastère et guide les moines, qui lui obéissent comme à un père spirituel. Il les revêt de l''habit monastique. On l''appelle aussi higoumène, du grec hégoumène.', '[{"text": "L''abbé guide les moines.", "translation": "L''abbé reçoit les moines nouveaux."}]'::jsonb, null, '{"id": "eg.d.c10_abbe", "unitId": "eg.v.c10_abbe", "word": "l''abbé", "translation": "le père et le chef d''un monastère, aussi appelé higoumène", "partOfSpeech": "person", "collection": "notion", "explanation": "L''abbé dirige le monastère et guide les moines, qui lui obéissent comme à un père spirituel. Il les revêt de l''habit monastique. On l''appelle aussi higoumène, du grec hégoumène.", "examples": [{"text": "L''abbé guide les moines.", "translation": "L''abbé reçoit les moines nouveaux."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_eskime', 'eg', 'l''eskime (schème)', 'cordon de cuir orné de croix : l''habit des moines les plus avancés', 'L''eskime est un cordon de cuir tressé orné de croix, porté sur la poitrine et le dos. Son nom, en copte, veut dire « forme » ou « habit ». L''abbé le donne à des moines, souvent des ermites, arrivés à une grande vie de prière.', '[{"text": "L''abbé revêt le moine de l''eskime.", "translation": "C''est le grand habit des moines avancés."}]'::jsonb, null, '{"id": "eg.d.c10_eskime", "unitId": "eg.v.c10_eskime", "word": "l''eskime (schème)", "translation": "cordon de cuir orné de croix : l''habit des moines les plus avancés", "partOfSpeech": "concept", "collection": "objet", "explanation": "L''eskime est un cordon de cuir tressé orné de croix, porté sur la poitrine et le dos. Son nom, en copte, veut dire « forme » ou « habit ». L''abbé le donne à des moines, souvent des ermites, arrivés à une grande vie de prière.", "examples": [{"text": "L''abbé revêt le moine de l''eskime.", "translation": "C''est le grand habit des moines avancés."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_monastere_saint_antoine', 'eg', 'le monastère Saint-Antoine', 'monastère près de la mer Rouge, autour des lieux de saint Antoine', 'Le monastère Saint-Antoine est dans le désert oriental, près de la mer Rouge, au pied du mont Colzim. On le dit le plus ancien monastère chrétien du monde. Tout près, le monastère Saint-Paul s''est formé autour de la grotte de saint Paul l''ermite.', '[{"text": "Saint-Antoine est près de la mer Rouge.", "translation": "Saint-Paul est dans la même montagne."}]'::jsonb, null, '{"id": "eg.d.c10_monastere_saint_antoine", "unitId": "eg.v.c10_monastere_saint_antoine", "word": "le monastère Saint-Antoine", "translation": "monastère près de la mer Rouge, autour des lieux de saint Antoine", "partOfSpeech": "place", "collection": "lieu", "explanation": "Le monastère Saint-Antoine est dans le désert oriental, près de la mer Rouge, au pied du mont Colzim. On le dit le plus ancien monastère chrétien du monde. Tout près, le monastère Saint-Paul s''est formé autour de la grotte de saint Paul l''ermite.", "examples": [{"text": "Saint-Antoine est près de la mer Rouge.", "translation": "Saint-Paul est dans la même montagne."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_wadi_natroun', 'eg', 'Wadi Natroun', 'vallée au nord-ouest du Caire, ancienne Scété, qui garde quatre monastères', 'Wadi Natroun est la vallée de l''ancienne Scété de saint Macaire le Grand, à environ cent kilomètres au nord-ouest du Caire. Quatre monastères y survivent : Saint-Macaire, Baramous (« des Romains »), Anba Bishoy, où est enterré Chenouda III, et celui des Syriens.', '[{"text": "Wadi Natroun est l''ancienne Scété.", "translation": "Quatre monastères y vivent encore."}]'::jsonb, null, '{"id": "eg.d.c10_wadi_natroun", "unitId": "eg.v.c10_wadi_natroun", "word": "Wadi Natroun", "translation": "vallée au nord-ouest du Caire, ancienne Scété, qui garde quatre monastères", "partOfSpeech": "place", "collection": "lieu", "explanation": "Wadi Natroun est la vallée de l''ancienne Scété de saint Macaire le Grand, à environ cent kilomètres au nord-ouest du Caire. Quatre monastères y survivent : Saint-Macaire, Baramous (« des Romains »), Anba Bishoy, où est enterré Chenouda III, et celui des Syriens.", "examples": [{"text": "Wadi Natroun est l''ancienne Scété.", "translation": "Quatre monastères y vivent encore."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_moine', 'eg', 'le moine', 'celui qui quitte le monde pour prier, travailler et jeûner', 'Le moine renonce au mariage, aux biens et à sa propre volonté. Il vit en communauté, dans un monastère, sous la direction de l''abbé. Les évêques et le pape coptes sont choisis parmi les moines.', '[{"text": "Le moine prie, travaille et jeûne.", "translation": "Les évêques coptes sont d''anciens moines."}]'::jsonb, null, '{"id": "eg.d.c10_moine", "unitId": "eg.v.c10_moine", "word": "le moine", "translation": "celui qui quitte le monde pour prier, travailler et jeûner", "partOfSpeech": "person", "collection": "notion", "explanation": "Le moine renonce au mariage, aux biens et à sa propre volonté. Il vit en communauté, dans un monastère, sous la direction de l''abbé. Les évêques et le pape coptes sont choisis parmi les moines.", "examples": [{"text": "Le moine prie, travaille et jeûne.", "translation": "Les évêques coptes sont d''anciens moines."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c10_clerge', 'eg', 'le clergé', 'les ministres ordonnés, du diacre au pape, qui servent l''Église', 'Le clergé réunit ceux qui sont ordonnés pour servir l''Église : les diacres, les prêtres, les évêques et, au sommet, le pape d''Alexandrie. Le diaconat compte cinq rangs, du psalte à l''archidiacre.', '[{"text": "Le sanctuaire est réservé au clergé et aux diacres.", "translation": "Du psalte au pape, tous servent l''Église."}]'::jsonb, null, '{"id": "eg.d.c10_clerge", "unitId": "eg.v.c10_clerge", "word": "le clergé", "translation": "les ministres ordonnés, du diacre au pape, qui servent l''Église", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le clergé réunit ceux qui sont ordonnés pour servir l''Église : les diacres, les prêtres, les évêques et, au sommet, le pape d''Alexandrie. Le diaconat compte cinq rangs, du psalte à l''archidiacre.", "examples": [{"text": "Le sanctuaire est réservé au clergé et aux diacres.", "translation": "Du psalte au pape, tous servent l''Église."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_agpeya', 'eg', 'l''Agpeya', 'le livre des heures : les sept heures de prière de l''Église copte', 'Agpeya vient du copte agp, « heure ». Ce livre rassemble les prières des sept heures du jour et de la nuit, à dire seul ou à plusieurs, à la maison comme à l''église.', '[{"text": "Chaque matin, il ouvre son Agpeya.", "translation": "Il prie l''heure du jour dans le livre des heures."}]'::jsonb, null, '{"id": "eg.d.c11_agpeya", "unitId": "eg.v.c11_agpeya", "word": "l''Agpeya", "translation": "le livre des heures : les sept heures de prière de l''Église copte", "partOfSpeech": "work", "collection": "priere", "explanation": "Agpeya vient du copte agp, « heure ». Ce livre rassemble les prières des sept heures du jour et de la nuit, à dire seul ou à plusieurs, à la maison comme à l''église.", "examples": [{"text": "Chaque matin, il ouvre son Agpeya.", "translation": "Il prie l''heure du jour dans le livre des heures."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_sept_heures', 'eg', 'les sept heures', 'Prime, Tierce, Sexte, None, Vêpres, Complies et Minuit', 'L''Agpeya tire sa règle du psaume 119, 164 : « Sept fois le jour je te loue ». Chaque heure rappelle un moment de la vie du Christ, de l''aube de la Résurrection à son retour.', '[{"text": "Les sept heures forment la journée de prière.", "translation": "De Prime à Minuit, sept rendez-vous avec Dieu."}]'::jsonb, null, '{"id": "eg.d.c11_sept_heures", "unitId": "eg.v.c11_sept_heures", "word": "les sept heures", "translation": "Prime, Tierce, Sexte, None, Vêpres, Complies et Minuit", "partOfSpeech": "concept", "collection": "priere", "explanation": "L''Agpeya tire sa règle du psaume 119, 164 : « Sept fois le jour je te loue ». Chaque heure rappelle un moment de la vie du Christ, de l''aube de la Résurrection à son retour.", "examples": [{"text": "Les sept heures forment la journée de prière.", "translation": "De Prime à Minuit, sept rendez-vous avec Dieu."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_prier_sans_cesse', 'eg', 'prier sans cesse', 'l''appel de saint Paul (1 Th 5, 17) : garder Dieu présent toute la journée', 'Saint Paul demande aux chrétiens de prier sans cesse. Comme on ne peut pas réciter des prières sans arrêt, l''Église donne des repères réguliers : les heures de prière.', '[{"text": "Les heures nous aident à prier sans cesse.", "translation": "Elles sont des alarmes qui ramènent vers Dieu."}]'::jsonb, null, '{"id": "eg.d.c11_prier_sans_cesse", "unitId": "eg.v.c11_prier_sans_cesse", "word": "prier sans cesse", "translation": "l''appel de saint Paul (1 Th 5, 17) : garder Dieu présent toute la journée", "partOfSpeech": "concept", "collection": "notion", "explanation": "Saint Paul demande aux chrétiens de prier sans cesse. Comme on ne peut pas réciter des prières sans arrêt, l''Église donne des repères réguliers : les heures de prière.", "examples": [{"text": "Les heures nous aident à prier sans cesse.", "translation": "Elles sont des alarmes qui ramènent vers Dieu."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_prime', 'eg', 'Prime', 'la première heure (6 h) : l''incarnation et la Résurrection', 'Prime se prie au lever du jour, vers 6 h. Elle rappelle l''incarnation et la Résurrection : les femmes vont au tombeau au lever du soleil. On remercie Dieu pour la nuit et on lui confie la journée.', '[{"text": "Elle prie Prime avant de partir au travail.", "translation": "La première prière du jour, à l''aube."}]'::jsonb, null, '{"id": "eg.d.c11_prime", "unitId": "eg.v.c11_prime", "word": "Prime", "translation": "la première heure (6 h) : l''incarnation et la Résurrection", "partOfSpeech": "concept", "collection": "priere", "explanation": "Prime se prie au lever du jour, vers 6 h. Elle rappelle l''incarnation et la Résurrection : les femmes vont au tombeau au lever du soleil. On remercie Dieu pour la nuit et on lui confie la journée.", "examples": [{"text": "Elle prie Prime avant de partir au travail.", "translation": "La première prière du jour, à l''aube."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_heure_biblique', 'eg', 'l''heure biblique', 'le jour compté depuis le lever du soleil : la 3e heure = 9 h', 'Dans la Bible, la première heure du jour est celle du lever du soleil, vers 6 h. Il suffit d''ajouter 6 à l''heure biblique pour trouver l''heure d''aujourd''hui. Les heures de l''Agpeya suivent ce calendrier.', '[{"text": "La sixième heure, c''est midi.", "translation": "6 + 6 = 12."}]'::jsonb, null, '{"id": "eg.d.c11_heure_biblique", "unitId": "eg.v.c11_heure_biblique", "word": "l''heure biblique", "translation": "le jour compté depuis le lever du soleil : la 3e heure = 9 h", "partOfSpeech": "concept", "collection": "notion", "explanation": "Dans la Bible, la première heure du jour est celle du lever du soleil, vers 6 h. Il suffit d''ajouter 6 à l''heure biblique pour trouver l''heure d''aujourd''hui. Les heures de l''Agpeya suivent ce calendrier.", "examples": [{"text": "La sixième heure, c''est midi.", "translation": "6 + 6 = 12."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_tierce', 'eg', 'Tierce', 'la 3e heure (9 h) : le procès devant Pilate et la Pentecôte', 'Tierce se prie à 9 h. Elle rappelle le procès du Christ devant Pilate, puis la descente de l''Esprit Saint à la Pentecôte. Elle est priée avant chaque messe.', '[{"text": "À 9 h, il prie Tierce.", "translation": "La troisième heure du jour, un tribunal puis une flamme."}]'::jsonb, null, '{"id": "eg.d.c11_tierce", "unitId": "eg.v.c11_tierce", "word": "Tierce", "translation": "la 3e heure (9 h) : le procès devant Pilate et la Pentecôte", "partOfSpeech": "concept", "collection": "priere", "explanation": "Tierce se prie à 9 h. Elle rappelle le procès du Christ devant Pilate, puis la descente de l''Esprit Saint à la Pentecôte. Elle est priée avant chaque messe.", "examples": [{"text": "À 9 h, il prie Tierce.", "translation": "La troisième heure du jour, un tribunal puis une flamme."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_proces_pilate', 'eg', 'le procès devant Pilate', 'le jugement du Christ par le gouverneur romain, rappelé à Tierce', 'Le vendredi matin, Jésus est amené devant Pilate, le gouverneur romain. La foule crie, l''accusé se tait. Tierce, à 9 h, rappelle ce procès : le Christ est jugé à notre place.', '[{"text": "Tierce rappelle le procès devant Pilate.", "translation": "Le Christ est jugé à notre place."}]'::jsonb, null, '{"id": "eg.d.c11_proces_pilate", "unitId": "eg.v.c11_proces_pilate", "word": "le procès devant Pilate", "translation": "le jugement du Christ par le gouverneur romain, rappelé à Tierce", "partOfSpeech": "event", "collection": "notion", "explanation": "Le vendredi matin, Jésus est amené devant Pilate, le gouverneur romain. La foule crie, l''accusé se tait. Tierce, à 9 h, rappelle ce procès : le Christ est jugé à notre place.", "examples": [{"text": "Tierce rappelle le procès devant Pilate.", "translation": "Le Christ est jugé à notre place."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_sexte', 'eg', 'Sexte', 'la 6e heure (midi) : la crucifixion', 'Sexte se prie à midi, la sixième heure. Elle rappelle la crucifixion : à cette heure, les ténèbres couvrent la terre. Elle est priée avant chaque messe, avec Tierce.', '[{"text": "À midi, il prie Sexte.", "translation": "On se tient au pied de la croix."}]'::jsonb, null, '{"id": "eg.d.c11_sexte", "unitId": "eg.v.c11_sexte", "word": "Sexte", "translation": "la 6e heure (midi) : la crucifixion", "partOfSpeech": "concept", "collection": "priere", "explanation": "Sexte se prie à midi, la sixième heure. Elle rappelle la crucifixion : à cette heure, les ténèbres couvrent la terre. Elle est priée avant chaque messe, avec Tierce.", "examples": [{"text": "À midi, il prie Sexte.", "translation": "On se tient au pied de la croix."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_none_heure', 'eg', 'la None', 'la 9e heure (15 h) : la mort du Christ sur la croix', 'La None se prie à 15 h, la neuvième heure. Jésus pousse un grand cri et rend l''esprit. On la prie aussi les jours de jeûne.', '[{"text": "À 15 h, on prie la None.", "translation": "L''heure de la mort du Christ."}]'::jsonb, null, '{"id": "eg.d.c11_none_heure", "unitId": "eg.v.c11_none_heure", "word": "la None", "translation": "la 9e heure (15 h) : la mort du Christ sur la croix", "partOfSpeech": "concept", "collection": "priere", "explanation": "La None se prie à 15 h, la neuvième heure. Jésus pousse un grand cri et rend l''esprit. On la prie aussi les jours de jeûne.", "examples": [{"text": "À 15 h, on prie la None.", "translation": "L''heure de la mort du Christ."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_bon_larron', 'eg', 'le bon larron', 'le condamné crucifié près de Jésus, à qui il promet le paradis', 'À côté de Jésus, un condamné lui dit : « Souviens-toi de moi ». Jésus lui répond : « Aujourd''hui tu seras avec moi dans le paradis ». La None rappelle ce larron repentant.', '[{"text": "Le bon larron reçoit la promesse du paradis.", "translation": "Il n''est jamais trop tard pour se repentir."}]'::jsonb, null, '{"id": "eg.d.c11_bon_larron", "unitId": "eg.v.c11_bon_larron", "word": "le bon larron", "translation": "le condamné crucifié près de Jésus, à qui il promet le paradis", "partOfSpeech": "person", "collection": "notion", "explanation": "À côté de Jésus, un condamné lui dit : « Souviens-toi de moi ». Jésus lui répond : « Aujourd''hui tu seras avec moi dans le paradis ». La None rappelle ce larron repentant.", "examples": [{"text": "Le bon larron reçoit la promesse du paradis.", "translation": "Il n''est jamais trop tard pour se repentir."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_vepres', 'eg', 'Vêpres', 'l''heure du coucher du soleil : la descente de la croix', 'Vêpres vient du latin vesper, « soir ». On les prie au coucher du soleil, vers 17-18 h, pour remercier Dieu de la journée. Elles rappellent la descente de la croix.', '[{"text": "Au coucher du soleil, on prie Vêpres.", "translation": "On remercie Dieu pour la journée."}]'::jsonb, null, '{"id": "eg.d.c11_vepres", "unitId": "eg.v.c11_vepres", "word": "Vêpres", "translation": "l''heure du coucher du soleil : la descente de la croix", "partOfSpeech": "concept", "collection": "priere", "explanation": "Vêpres vient du latin vesper, « soir ». On les prie au coucher du soleil, vers 17-18 h, pour remercier Dieu de la journée. Elles rappellent la descente de la croix.", "examples": [{"text": "Au coucher du soleil, on prie Vêpres.", "translation": "On remercie Dieu pour la journée."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_complies', 'eg', 'Complies', 'la prière de 21 h, avant de dormir : l''ensevelissement et le Jugement dernier', 'Complies vient du latin completorium, « ce qui achève » la journée. On les prie vers 21 h. Elles rappellent l''ensevelissement du Christ et le Jugement dernier.', '[{"text": "Avant de dormir, il prie Complies.", "translation": "Il remet son âme à Dieu pour la nuit."}]'::jsonb, null, '{"id": "eg.d.c11_complies", "unitId": "eg.v.c11_complies", "word": "Complies", "translation": "la prière de 21 h, avant de dormir : l''ensevelissement et le Jugement dernier", "partOfSpeech": "concept", "collection": "priere", "explanation": "Complies vient du latin completorium, « ce qui achève » la journée. On les prie vers 21 h. Elles rappellent l''ensevelissement du Christ et le Jugement dernier.", "examples": [{"text": "Avant de dormir, il prie Complies.", "translation": "Il remet son âme à Dieu pour la nuit."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_descente_de_la_croix', 'eg', 'la descente de la croix', 'Joseph d''Arimathie demande le corps de Jésus à Pilate et le descend de la croix', 'Après la mort de Jésus, Joseph d''Arimathie demande son corps à Pilate (Mc 15, 42-46). Vêpres rappellent cette descente de la croix, au soir du vendredi.', '[{"text": "Vêpres rappellent la descente de la croix.", "translation": "Le corps du Christ est confié à Joseph d''Arimathie."}]'::jsonb, null, '{"id": "eg.d.c11_descente_de_la_croix", "unitId": "eg.v.c11_descente_de_la_croix", "word": "la descente de la croix", "translation": "Joseph d''Arimathie demande le corps de Jésus à Pilate et le descend de la croix", "partOfSpeech": "event", "collection": "notion", "explanation": "Après la mort de Jésus, Joseph d''Arimathie demande son corps à Pilate (Mc 15, 42-46). Vêpres rappellent cette descente de la croix, au soir du vendredi.", "examples": [{"text": "Vêpres rappellent la descente de la croix.", "translation": "Le corps du Christ est confié à Joseph d''Arimathie."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_minuit_heure', 'eg', 'Minuit', 'l''heure de la veille : on se lève la nuit et on attend le retour du Christ', 'Minuit rappelle la seconde venue du Christ. Elle compte trois veilles, avec leurs psaumes. Elle est le point de départ de la tasbeha, la louange de minuit.', '[{"text": "À minuit, il se lève pour prier.", "translation": "La nuit appartient à ceux qui veillent."}]'::jsonb, null, '{"id": "eg.d.c11_minuit_heure", "unitId": "eg.v.c11_minuit_heure", "word": "Minuit", "translation": "l''heure de la veille : on se lève la nuit et on attend le retour du Christ", "partOfSpeech": "concept", "collection": "priere", "explanation": "Minuit rappelle la seconde venue du Christ. Elle compte trois veilles, avec leurs psaumes. Elle est le point de départ de la tasbeha, la louange de minuit.", "examples": [{"text": "À minuit, il se lève pour prier.", "translation": "La nuit appartient à ceux qui veillent."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_dix_vierges', 'eg', 'les dix vierges', 'la parabole (Mt 25, 1-13) de cinq vierges sages et cinq folles qui attendent l''époux', 'Dans la parabole, cinq vierges ont pris de l''huile pour leurs lampes et cinq non. Un cri retentit à minuit : « Voici l''époux ! ». La parabole invite à être prêt pour la seconde venue du Christ.', '[{"text": "Les vierges sages avaient de l''huile.", "translation": "Être prêt, c''est veiller."}]'::jsonb, null, '{"id": "eg.d.c11_dix_vierges", "unitId": "eg.v.c11_dix_vierges", "word": "les dix vierges", "translation": "la parabole (Mt 25, 1-13) de cinq vierges sages et cinq folles qui attendent l''époux", "partOfSpeech": "event", "collection": "notion", "explanation": "Dans la parabole, cinq vierges ont pris de l''huile pour leurs lampes et cinq non. Un cri retentit à minuit : « Voici l''époux ! ». La parabole invite à être prêt pour la seconde venue du Christ.", "examples": [{"text": "Les vierges sages avaient de l''huile.", "translation": "Être prêt, c''est veiller."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_trois_veilles', 'eg', 'les trois veilles', 'les trois parties de la prière de Minuit, comme les trois prières à Gethsémani', 'La prière de Minuit se divise en trois veilles, avec leurs psaumes. Elles rappellent les trois prières du Christ à Gethsémani, où il dit : « Veillez et priez ».', '[{"text": "Minuit compte trois veilles.", "translation": "Chacune rappelle une prière du Christ à Gethsémani."}]'::jsonb, null, '{"id": "eg.d.c11_trois_veilles", "unitId": "eg.v.c11_trois_veilles", "word": "les trois veilles", "translation": "les trois parties de la prière de Minuit, comme les trois prières à Gethsémani", "partOfSpeech": "concept", "collection": "priere", "explanation": "La prière de Minuit se divise en trois veilles, avec leurs psaumes. Elles rappellent les trois prières du Christ à Gethsémani, où il dit : « Veillez et priez ».", "examples": [{"text": "Minuit compte trois veilles.", "translation": "Chacune rappelle une prière du Christ à Gethsémani."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_priere_du_voile', 'eg', 'la prière du voile', 'l''examen de conscience qui suit les sept heures, surtout pour évêques, prêtres et moines', 'La prière du voile (en arabe setar, « voile ») est une prière à part, à la fin de l''Agpeya. C''est un examen de conscience, surtout pour les évêques, les prêtres et les moines. Elle ne compte pas parmi les sept heures.', '[{"text": "La prière du voile n''est pas une des sept heures.", "translation": "C''est un temps à part, pour examiner sa conscience."}]'::jsonb, null, '{"id": "eg.d.c11_priere_du_voile", "unitId": "eg.v.c11_priere_du_voile", "word": "la prière du voile", "translation": "l''examen de conscience qui suit les sept heures, surtout pour évêques, prêtres et moines", "partOfSpeech": "concept", "collection": "priere", "explanation": "La prière du voile (en arabe setar, « voile ») est une prière à part, à la fin de l''Agpeya. C''est un examen de conscience, surtout pour les évêques, les prêtres et les moines. Elle ne compte pas parmi les sept heures.", "examples": [{"text": "La prière du voile n''est pas une des sept heures.", "translation": "C''est un temps à part, pour examiner sa conscience."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_psaume_50', 'eg', 'le psaume 50', 'la prière de repentance du roi David : « Aie pitié de moi, ô Dieu »', 'Le psaume 50 (51 dans la Bible hébraïque) est la prière de repentance du roi David. Il revient dans chaque heure de l''Agpeya, juste après le Notre Père et l''action de grâce.', '[{"text": "On dit le psaume 50 au début de chaque heure.", "translation": "Avant de louer, on reconnaît ses fautes."}]'::jsonb, null, '{"id": "eg.d.c11_psaume_50", "unitId": "eg.v.c11_psaume_50", "word": "le psaume 50", "translation": "la prière de repentance du roi David : « Aie pitié de moi, ô Dieu »", "partOfSpeech": "concept", "collection": "priere", "explanation": "Le psaume 50 (51 dans la Bible hébraïque) est la prière de repentance du roi David. Il revient dans chaque heure de l''Agpeya, juste après le Notre Père et l''action de grâce.", "examples": [{"text": "On dit le psaume 50 au début de chaque heure.", "translation": "Avant de louer, on reconnaît ses fautes."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_notre_pere', 'eg', 'le Notre Père', 'la prière que le Christ a lui-même enseignée (Mt 6, 9-13)', 'Le Notre Père ouvre chaque heure de l''Agpeya. C''est la prière que le Christ a enseignée à ses disciples. Il revient aussi à la fin de la tasbeha.', '[{"text": "Chaque heure commence par le Notre Père.", "translation": "On prie avec les mots du Christ."}]'::jsonb, null, '{"id": "eg.d.c11_notre_pere", "unitId": "eg.v.c11_notre_pere", "word": "le Notre Père", "translation": "la prière que le Christ a lui-même enseignée (Mt 6, 9-13)", "partOfSpeech": "concept", "collection": "priere", "explanation": "Le Notre Père ouvre chaque heure de l''Agpeya. C''est la prière que le Christ a enseignée à ses disciples. Il revient aussi à la fin de la tasbeha.", "examples": [{"text": "Chaque heure commence par le Notre Père.", "translation": "On prie avec les mots du Christ."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_metanie', 'eg', 'la métanie', 'la prosternation : on s''incline profondément pour adorer', 'La métanie est une prosternation. On en fait par exemple au nom de la Trinité. Le corps dit ce que le cœur pense : devant Dieu, on s''abaisse.', '[{"text": "Il fait une métanie au nom de la Trinité.", "translation": "Il s''incline pour adorer."}]'::jsonb, null, '{"id": "eg.d.c11_metanie", "unitId": "eg.v.c11_metanie", "word": "la métanie", "translation": "la prosternation : on s''incline profondément pour adorer", "partOfSpeech": "concept", "collection": "notion", "explanation": "La métanie est une prosternation. On en fait par exemple au nom de la Trinité. Le corps dit ce que le cœur pense : devant Dieu, on s''abaisse.", "examples": [{"text": "Il fait une métanie au nom de la Trinité.", "translation": "Il s''incline pour adorer."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_quarante_et_un_kyrie', 'eg', 'les 41 Kyrie', 'Kyrie eleison, « Seigneur, aie pitié », dit 41 fois dans chaque heure', 'Kyrie eleison est du grec : « Seigneur, aie pitié ». On le dit 41 fois à chaque heure. Selon la tradition, 41 rappelle les 39 coups de fouet, la couronne d''épines et la lance.', '[{"text": "Il dit les 41 Kyrie en pensant à la Passion.", "translation": "Chaque Kyrie rappelle ce que le Christ a souffert."}]'::jsonb, null, '{"id": "eg.d.c11_quarante_et_un_kyrie", "unitId": "eg.v.c11_quarante_et_un_kyrie", "word": "les 41 Kyrie", "translation": "Kyrie eleison, « Seigneur, aie pitié », dit 41 fois dans chaque heure", "partOfSpeech": "expression", "collection": "priere", "explanation": "Kyrie eleison est du grec : « Seigneur, aie pitié ». On le dit 41 fois à chaque heure. Selon la tradition, 41 rappelle les 39 coups de fouet, la couronne d''épines et la lance.", "examples": [{"text": "Il dit les 41 Kyrie en pensant à la Passion.", "translation": "Chaque Kyrie rappelle ce que le Christ a souffert."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_signe_de_croix', 'eg', 'le signe de croix', 'le geste fait au nom de la Trinité : Père, Fils et Saint-Esprit', 'On fait le signe de croix au nom de la Trinité, en prononçant Père, Fils et Saint-Esprit. On marque sur soi la croix du Christ.', '[{"text": "Elle commence sa prière par le signe de croix.", "translation": "Elle se place sous la croix du Christ."}]'::jsonb, null, '{"id": "eg.d.c11_signe_de_croix", "unitId": "eg.v.c11_signe_de_croix", "word": "le signe de croix", "translation": "le geste fait au nom de la Trinité : Père, Fils et Saint-Esprit", "partOfSpeech": "concept", "collection": "notion", "explanation": "On fait le signe de croix au nom de la Trinité, en prononçant Père, Fils et Saint-Esprit. On marque sur soi la croix du Christ.", "examples": [{"text": "Elle commence sa prière par le signe de croix.", "translation": "Elle se place sous la croix du Christ."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_est_orient', 'eg', 'l''est (l''orient)', 'le côté du soleil levant : la direction de la prière', 'On prie tourné vers l''est, l''orient, pour six raisons. C''est le côté de la lumière, du retour du Christ et du paradis perdu.', '[{"text": "Il se tourne vers l''est pour prier.", "translation": "Il regarde du côté de la lumière."}]'::jsonb, null, '{"id": "eg.d.c11_est_orient", "unitId": "eg.v.c11_est_orient", "word": "l''est (l''orient)", "translation": "le côté du soleil levant : la direction de la prière", "partOfSpeech": "concept", "collection": "notion", "explanation": "On prie tourné vers l''est, l''orient, pour six raisons. C''est le côté de la lumière, du retour du Christ et du paradis perdu.", "examples": [{"text": "Il se tourne vers l''est pour prier.", "translation": "Il regarde du côté de la lumière."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_soleil_de_justice', 'eg', 'le soleil de justice', 'le nom que Malachie donne au Christ, lumière du salut', 'Le prophète Malachie parle du « soleil de justice » (Ml 4, 2). Les chrétiens y voient le Christ : comme le soleil se lève à l''est, la lumière du salut vient de lui.', '[{"text": "Le Christ est le soleil de justice.", "translation": "On prie vers l''est, là où le soleil se lève."}]'::jsonb, null, '{"id": "eg.d.c11_soleil_de_justice", "unitId": "eg.v.c11_soleil_de_justice", "word": "le soleil de justice", "translation": "le nom que Malachie donne au Christ, lumière du salut", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le prophète Malachie parle du « soleil de justice » (Ml 4, 2). Les chrétiens y voient le Christ : comme le soleil se lève à l''est, la lumière du salut vient de lui.", "examples": [{"text": "Le Christ est le soleil de justice.", "translation": "On prie vers l''est, là où le soleil se lève."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_etoile_des_mages', 'eg', 'l''étoile des mages', 'l''étoile vue à l''orient par les mages, qui les conduit au Christ', 'Des sages venus d''Orient disent : « Nous avons vu son étoile à l''orient » (Mt 2, 2). Cette étoile les conduit à l''enfant Jésus. Prier vers l''est, c''est suivre la même étoile.', '[{"text": "Les mages suivent l''étoile.", "translation": "Elle les mène jusqu''au Christ."}]'::jsonb, null, '{"id": "eg.d.c11_etoile_des_mages", "unitId": "eg.v.c11_etoile_des_mages", "word": "l''étoile des mages", "translation": "l''étoile vue à l''orient par les mages, qui les conduit au Christ", "partOfSpeech": "concept", "collection": "notion", "explanation": "Des sages venus d''Orient disent : « Nous avons vu son étoile à l''orient » (Mt 2, 2). Cette étoile les conduit à l''enfant Jésus. Prier vers l''est, c''est suivre la même étoile.", "examples": [{"text": "Les mages suivent l''étoile.", "translation": "Elle les mène jusqu''au Christ."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c11_orientation_des_eglises', 'eg', 'l''orientation des églises', 'les églises sont bâties tournées vers l''est, comme la prière', 'Les églises sont bâties tournées vers l''est. L''assemblée prie ainsi dans le même sens que celui du baptême et de l''attente du Christ.', '[{"text": "L''église est tournée vers l''est.", "translation": "Toute l''assemblée prie dans le même sens."}]'::jsonb, null, '{"id": "eg.d.c11_orientation_des_eglises", "unitId": "eg.v.c11_orientation_des_eglises", "word": "l''orientation des églises", "translation": "les églises sont bâties tournées vers l''est, comme la prière", "partOfSpeech": "place", "collection": "objet", "explanation": "Les églises sont bâties tournées vers l''est. L''assemblée prie ainsi dans le même sens que celui du baptême et de l''attente du Christ.", "examples": [{"text": "L''église est tournée vers l''est.", "translation": "Toute l''assemblée prie dans le même sens."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_tasbeha', 'eg', 'la tasbeha', 'la louange de minuit : une nuit de cantiques et de psalmodie', 'Tasbeha vient de l''arabe et veut dire « louange ». C''est une psalmodie, priée chaque nuit dans les monastères et, en paroisse, surtout la veille d''une messe. Elle prolonge la prière de Minuit.', '[{"text": "Les moines prient la tasbeha chaque nuit.", "translation": "Ils veillent pour chanter la louange de Dieu."}]'::jsonb, null, '{"id": "eg.d.c12_tasbeha", "unitId": "eg.v.c12_tasbeha", "word": "la tasbeha", "translation": "la louange de minuit : une nuit de cantiques et de psalmodie", "partOfSpeech": "concept", "collection": "priere", "explanation": "Tasbeha vient de l''arabe et veut dire « louange ». C''est une psalmodie, priée chaque nuit dans les monastères et, en paroisse, surtout la veille d''une messe. Elle prolonge la prière de Minuit.", "examples": [{"text": "Les moines prient la tasbeha chaque nuit.", "translation": "Ils veillent pour chanter la louange de Dieu."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_ten_thino', 'eg', 'Ten thino', '« Levez-vous, fils de la lumière » : le chant qui réveille l''assemblée', 'Ten thino est du copte : « Levez-vous, fils de la lumière ». C''est l''appel à se réveiller pour louer. Il vient juste après l''Agpeya de minuit, au début de la tasbeha.', '[{"text": "La tasbeha commence par Ten thino.", "translation": "L''appel à se lever pour louer."}]'::jsonb, null, '{"id": "eg.d.c12_ten_thino", "unitId": "eg.v.c12_ten_thino", "word": "Ten thino", "translation": "« Levez-vous, fils de la lumière » : le chant qui réveille l''assemblée", "partOfSpeech": "expression", "collection": "priere", "explanation": "Ten thino est du copte : « Levez-vous, fils de la lumière ». C''est l''appel à se réveiller pour louer. Il vient juste après l''Agpeya de minuit, au début de la tasbeha.", "examples": [{"text": "La tasbeha commence par Ten thino.", "translation": "L''appel à se lever pour louer."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_fils_de_la_lumiere', 'eg', 'les fils de la lumière', 'les chrétiens, qui veillent au lieu de dormir (1 Th 5, 5)', 'Saint Paul appelle les chrétiens « fils de la lumière » et fils du jour (1 Th 5, 5). Ils ne dorment pas dans l''indifférence : ils veillent et attendent le Seigneur.', '[{"text": "Les fils de la lumière veillent.", "translation": "Les chrétiens restent éveillés pour louer Dieu."}]'::jsonb, null, '{"id": "eg.d.c12_fils_de_la_lumiere", "unitId": "eg.v.c12_fils_de_la_lumiere", "word": "les fils de la lumière", "translation": "les chrétiens, qui veillent au lieu de dormir (1 Th 5, 5)", "partOfSpeech": "concept", "collection": "notion", "explanation": "Saint Paul appelle les chrétiens « fils de la lumière » et fils du jour (1 Th 5, 5). Ils ne dorment pas dans l''indifférence : ils veillent et attendent le Seigneur.", "examples": [{"text": "Les fils de la lumière veillent.", "translation": "Les chrétiens restent éveillés pour louer Dieu."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_difnar', 'eg', 'le difnar', 'la lecture du jour qui rappelle le saint du jour', 'Le difnar (antiphonaire) est la lecture du jour dans la tasbeha. Il rappelle le saint du jour, avec le même rôle que le synaxaire. Chaque nuit de louange rappelle donc un saint différent.', '[{"text": "Le difnar rappelle le saint du jour.", "translation": "Chaque nuit, un saint différent."}]'::jsonb, null, '{"id": "eg.d.c12_difnar", "unitId": "eg.v.c12_difnar", "word": "le difnar", "translation": "la lecture du jour qui rappelle le saint du jour", "partOfSpeech": "concept", "collection": "priere", "explanation": "Le difnar (antiphonaire) est la lecture du jour dans la tasbeha. Il rappelle le saint du jour, avec le même rôle que le synaxaire. Chaque nuit de louange rappelle donc un saint différent.", "examples": [{"text": "Le difnar rappelle le saint du jour.", "translation": "Chaque nuit, un saint différent."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_trisagion', 'eg', 'le Trisagion', '« trois fois saint » : prière de la conclusion de la tasbeha', 'Trisagion veut dire « trois fois saint ». On le chante dans la conclusion de la tasbeha, avec le Credo et le Notre Père.', '[{"text": "Le Trisagion clôt la tasbeha.", "translation": "On proclame trois fois la sainteté de Dieu."}]'::jsonb, null, '{"id": "eg.d.c12_trisagion", "unitId": "eg.v.c12_trisagion", "word": "le Trisagion", "translation": "« trois fois saint » : prière de la conclusion de la tasbeha", "partOfSpeech": "expression", "collection": "priere", "explanation": "Trisagion veut dire « trois fois saint ». On le chante dans la conclusion de la tasbeha, avec le Credo et le Notre Père.", "examples": [{"text": "Le Trisagion clôt la tasbeha.", "translation": "On proclame trois fois la sainteté de Dieu."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_synaxaire', 'eg', 'le synaxaire', 'le livre des vies de saints, lu jour après jour', 'Le synaxaire est un livre de vies de saints, jour après jour. Le difnar de la tasbeha joue le même rôle : il rappelle le saint du jour.', '[{"text": "Le synaxaire raconte la vie des saints.", "translation": "Un saint pour chaque jour de l''année."}]'::jsonb, null, '{"id": "eg.d.c12_synaxaire", "unitId": "eg.v.c12_synaxaire", "word": "le synaxaire", "translation": "le livre des vies de saints, lu jour après jour", "partOfSpeech": "work", "collection": "notion", "explanation": "Le synaxaire est un livre de vies de saints, jour après jour. Le difnar de la tasbeha joue le même rôle : il rappelle le saint du jour.", "examples": [{"text": "Le synaxaire raconte la vie des saints.", "translation": "Un saint pour chaque jour de l''année."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_hoos', 'eg', 'le hoos', 'un cantique tiré de la Bible, chanté dans la tasbeha', 'Hoos est un mot copte qui veut dire « louange » : c''est un cantique tiré de la Bible. La tasbeha en compte quatre, chantés dans l''ordre.', '[{"text": "Le 1er hoos est le cantique de Moïse.", "translation": "Un cantique de la Bible, chanté en louange."}]'::jsonb, null, '{"id": "eg.d.c12_hoos", "unitId": "eg.v.c12_hoos", "word": "le hoos", "translation": "un cantique tiré de la Bible, chanté dans la tasbeha", "partOfSpeech": "concept", "collection": "priere", "explanation": "Hoos est un mot copte qui veut dire « louange » : c''est un cantique tiré de la Bible. La tasbeha en compte quatre, chantés dans l''ordre.", "examples": [{"text": "Le 1er hoos est le cantique de Moïse.", "translation": "Un cantique de la Bible, chanté en louange."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_lobsh', 'eg', 'le lobsh', '« explication » : la pièce qui commente le hoos qu''on vient de chanter', 'Lobsh est un mot copte qui veut dire « explication ». Après chaque hoos vient un lobsh, une pièce qui en donne le sens.', '[{"text": "Le lobsh suit chaque hoos.", "translation": "On chante, puis on comprend."}]'::jsonb, null, '{"id": "eg.d.c12_lobsh", "unitId": "eg.v.c12_lobsh", "word": "le lobsh", "translation": "« explication » : la pièce qui commente le hoos qu''on vient de chanter", "partOfSpeech": "concept", "collection": "priere", "explanation": "Lobsh est un mot copte qui veut dire « explication ». Après chaque hoos vient un lobsh, une pièce qui en donne le sens.", "examples": [{"text": "Le lobsh suit chaque hoos.", "translation": "On chante, puis on comprend."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_cantique_de_moise', 'eg', 'le cantique de Moïse', 'le chant d''Ex 15 après la traversée de la mer Rouge : le 1er hoos', 'Après la traversée de la mer Rouge, Moïse et Israël chantent leur joie (Ex 15). Ce cantique est le 1er hoos de la tasbeha. Il symbolise la sortie de l''esclavage du péché.', '[{"text": "Le cantique de Moïse ouvre les hoos.", "translation": "Israël échappe à pharaon, nous échappons au péché."}]'::jsonb, null, '{"id": "eg.d.c12_cantique_de_moise", "unitId": "eg.v.c12_cantique_de_moise", "word": "le cantique de Moïse", "translation": "le chant d''Ex 15 après la traversée de la mer Rouge : le 1er hoos", "partOfSpeech": "work", "collection": "priere", "explanation": "Après la traversée de la mer Rouge, Moïse et Israël chantent leur joie (Ex 15). Ce cantique est le 1er hoos de la tasbeha. Il symbolise la sortie de l''esclavage du péché.", "examples": [{"text": "Le cantique de Moïse ouvre les hoos.", "translation": "Israël échappe à pharaon, nous échappons au péché."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_doxologie', 'eg', 'la doxologie', 'un chant de gloire à la Vierge ou à un saint, entre le 3e et le 4e hoos', 'Doxa est un mot grec qui veut dire « gloire » : une doxologie est un chant de gloire. Dans la tasbeha, elles glorifient d''abord la Vierge Marie, puis les saints, entre le 3e et le 4e hoos.', '[{"text": "On chante les doxologies avant le 4e hoos.", "translation": "Un chant de gloire pour la Vierge et les saints."}]'::jsonb, null, '{"id": "eg.d.c12_doxologie", "unitId": "eg.v.c12_doxologie", "word": "la doxologie", "translation": "un chant de gloire à la Vierge ou à un saint, entre le 3e et le 4e hoos", "partOfSpeech": "concept", "collection": "priere", "explanation": "Doxa est un mot grec qui veut dire « gloire » : une doxologie est un chant de gloire. Dans la tasbeha, elles glorifient d''abord la Vierge Marie, puis les saints, entre le 3e et le 4e hoos.", "examples": [{"text": "On chante les doxologies avant le 4e hoos.", "translation": "Un chant de gloire pour la Vierge et les saints."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_commemoraison_des_saints', 'eg', 'la commémoraison des saints', 'on rappelle les noms des saints, entre le 3e et le 4e hoos', 'Entre le 3e et le 4e hoos, on rappelle les noms des saints. L''Église ne chante pas seule : elle chante avec ses saints, vivants en Dieu.', '[{"text": "On fait la commémoraison des saints.", "translation": "On les nomme, comme une grande famille."}]'::jsonb, null, '{"id": "eg.d.c12_commemoraison_des_saints", "unitId": "eg.v.c12_commemoraison_des_saints", "word": "la commémoraison des saints", "translation": "on rappelle les noms des saints, entre le 3e et le 4e hoos", "partOfSpeech": "concept", "collection": "priere", "explanation": "Entre le 3e et le 4e hoos, on rappelle les noms des saints. L''Église ne chante pas seule : elle chante avec ses saints, vivants en Dieu.", "examples": [{"text": "On fait la commémoraison des saints.", "translation": "On les nomme, comme une grande famille."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_cantique_des_trois_jeunes', 'eg', 'le cantique des trois jeunes gens', 'le chant de la fournaise de Babylone (Dn 3) : le 3e hoos', 'À Babylone, trois jeunes gens refusent d''adorer la statue du roi et sont jetés dans la fournaise. Dans le feu, ils chantent et appellent toute la création à louer Dieu. Leur cantique est le 3e hoos.', '[{"text": "Le 3e hoos vient de la fournaise.", "translation": "Même dans le feu, on peut louer Dieu."}]'::jsonb, null, '{"id": "eg.d.c12_cantique_des_trois_jeunes", "unitId": "eg.v.c12_cantique_des_trois_jeunes", "word": "le cantique des trois jeunes gens", "translation": "le chant de la fournaise de Babylone (Dn 3) : le 3e hoos", "partOfSpeech": "work", "collection": "priere", "explanation": "À Babylone, trois jeunes gens refusent d''adorer la statue du roi et sont jetés dans la fournaise. Dans le feu, ils chantent et appellent toute la création à louer Dieu. Leur cantique est le 3e hoos.", "examples": [{"text": "Le 3e hoos vient de la fournaise.", "translation": "Même dans le feu, on peut louer Dieu."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_psali', 'eg', 'le psali', 'un chant de louange au Christ : un par jour, deux le dimanche', 'Psali vient du grec psallein, « chanter des psaumes ». C''est un chant adressé au Christ, construit autour du nom de Jésus. Il y en a un par jour, et deux le dimanche.', '[{"text": "Le psali loue le Christ.", "translation": "Il suit les hoos dans la tasbeha."}]'::jsonb, null, '{"id": "eg.d.c12_psali", "unitId": "eg.v.c12_psali", "word": "le psali", "translation": "un chant de louange au Christ : un par jour, deux le dimanche", "partOfSpeech": "concept", "collection": "priere", "explanation": "Psali vient du grec psallein, « chanter des psaumes ». C''est un chant adressé au Christ, construit autour du nom de Jésus. Il y en a un par jour, et deux le dimanche.", "examples": [{"text": "Le psali loue le Christ.", "translation": "Il suit les hoos dans la tasbeha."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_theotokie', 'eg', 'la théotokie', 'un chant à la Vierge Marie : sept théotokies, une pour chaque jour', 'Théotokie vient de Théotokos, « mère de Dieu ». C''est une louange de la Vierge, différente chaque jour de la semaine. Elle explique l''incarnation par des symboles de l''Ancien Testament.', '[{"text": "La théotokie loue la Vierge Marie.", "translation": "Sept théotokies pour sept jours."}]'::jsonb, null, '{"id": "eg.d.c12_theotokie", "unitId": "eg.v.c12_theotokie", "word": "la théotokie", "translation": "un chant à la Vierge Marie : sept théotokies, une pour chaque jour", "partOfSpeech": "concept", "collection": "priere", "explanation": "Théotokie vient de Théotokos, « mère de Dieu ». C''est une louange de la Vierge, différente chaque jour de la semaine. Elle explique l''incarnation par des symboles de l''Ancien Testament.", "examples": [{"text": "La théotokie loue la Vierge Marie.", "translation": "Sept théotokies pour sept jours."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_buisson_ardent', 'eg', 'le buisson ardent', 'le buisson qui brûle sans se consumer (Ex 3) : image de la Vierge', 'Moïse voit un buisson qui brûle sans se consumer (Ex 3). Pour les théotokies, c''est l''image de Marie, qui porte le feu de la divinité sans être consumée.', '[{"text": "Le buisson ardent annonce Marie.", "translation": "Elle porte Dieu sans être consumée."}]'::jsonb, null, '{"id": "eg.d.c12_buisson_ardent", "unitId": "eg.v.c12_buisson_ardent", "word": "le buisson ardent", "translation": "le buisson qui brûle sans se consumer (Ex 3) : image de la Vierge", "partOfSpeech": "event", "collection": "notion", "explanation": "Moïse voit un buisson qui brûle sans se consumer (Ex 3). Pour les théotokies, c''est l''image de Marie, qui porte le feu de la divinité sans être consumée.", "examples": [{"text": "Le buisson ardent annonce Marie.", "translation": "Elle porte Dieu sans être consumée."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_jours_adam', 'eg', 'les jours Adam', 'dimanche, lundi et mardi : les jours de l''air Adam', 'Les jours Adam sont au nombre de trois : dimanche, lundi, mardi. Le psali et la théotokie se chantent alors sur l''air Adam, nommé d''après le premier mot de la théotokie du lundi.', '[{"text": "Le lundi est un jour Adam.", "translation": "On chante sur l''air Adam."}]'::jsonb, null, '{"id": "eg.d.c12_jours_adam", "unitId": "eg.v.c12_jours_adam", "word": "les jours Adam", "translation": "dimanche, lundi et mardi : les jours de l''air Adam", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les jours Adam sont au nombre de trois : dimanche, lundi, mardi. Le psali et la théotokie se chantent alors sur l''air Adam, nommé d''après le premier mot de la théotokie du lundi.", "examples": [{"text": "Le lundi est un jour Adam.", "translation": "On chante sur l''air Adam."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_jours_watos', 'eg', 'les jours Watos', 'mercredi, jeudi, vendredi et samedi : les jours de l''air Watos', 'Les jours Watos sont au nombre de quatre : mercredi, jeudi, vendredi, samedi. On chante alors sur l''air Watos (ou Batos), nommé d''après Pibatos, premier mot de la théotokie du jeudi.', '[{"text": "Le vendredi est un jour Watos.", "translation": "On chante sur l''air Watos."}]'::jsonb, null, '{"id": "eg.d.c12_jours_watos", "unitId": "eg.v.c12_jours_watos", "word": "les jours Watos", "translation": "mercredi, jeudi, vendredi et samedi : les jours de l''air Watos", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les jours Watos sont au nombre de quatre : mercredi, jeudi, vendredi, samedi. On chante alors sur l''air Watos (ou Batos), nommé d''après Pibatos, premier mot de la théotokie du jeudi.", "examples": [{"text": "Le vendredi est un jour Watos.", "translation": "On chante sur l''air Watos."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_pibatos', 'eg', 'Pibatos', '« le buisson » : premier mot de la théotokie du jeudi, d''où vient le nom Watos', 'Pibatos veut dire « le buisson » : le buisson que Moïse a vu dans le désert. C''est le premier mot de la théotokie du jeudi. De Pibatos vient le nom Watos.', '[{"text": "Watos vient de Pibatos.", "translation": "Le buisson ardent a donné son nom à l''air."}]'::jsonb, null, '{"id": "eg.d.c12_pibatos", "unitId": "eg.v.c12_pibatos", "word": "Pibatos", "translation": "« le buisson » : premier mot de la théotokie du jeudi, d''où vient le nom Watos", "partOfSpeech": "expression", "collection": "notion", "explanation": "Pibatos veut dire « le buisson » : le buisson que Moïse a vu dans le désert. C''est le premier mot de la théotokie du jeudi. De Pibatos vient le nom Watos.", "examples": [{"text": "Watos vient de Pibatos.", "translation": "Le buisson ardent a donné son nom à l''air."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_jour_liturgique', 'eg', 'le jour liturgique', 'le jour de l''Église, qui commence la veille au soir', 'La Genèse dit : « il y eut un soir, il y eut un matin ». Dans la Bible, le jour commence au soir. Pour l''Église aussi, le jour liturgique commence la veille au soir.', '[{"text": "Le samedi soir, on est déjà dans le jour liturgique du dimanche.", "translation": "Le jour commence la veille au soir."}]'::jsonb, null, '{"id": "eg.d.c12_jour_liturgique", "unitId": "eg.v.c12_jour_liturgique", "word": "le jour liturgique", "translation": "le jour de l''Église, qui commence la veille au soir", "partOfSpeech": "concept", "collection": "notion", "explanation": "La Genèse dit : « il y eut un soir, il y eut un matin ». Dans la Bible, le jour commence au soir. Pour l''Église aussi, le jour liturgique commence la veille au soir.", "examples": [{"text": "Le samedi soir, on est déjà dans le jour liturgique du dimanche.", "translation": "Le jour commence la veille au soir."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_regle_du_soir', 'eg', 'la règle du soir', 'le soir, on prie la théotokie et l''air du lendemain', 'Le soir, on prie la théotokie du lendemain, sur l''air du lendemain. Samedi soir : la théotokie du dimanche, air Adam. Mardi soir : celle du mercredi, air Watos.', '[{"text": "Mardi à 20 h, on suit la règle du soir.", "translation": "On prie déjà la théotokie du mercredi."}]'::jsonb, null, '{"id": "eg.d.c12_regle_du_soir", "unitId": "eg.v.c12_regle_du_soir", "word": "la règle du soir", "translation": "le soir, on prie la théotokie et l''air du lendemain", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le soir, on prie la théotokie du lendemain, sur l''air du lendemain. Samedi soir : la théotokie du dimanche, air Adam. Mardi soir : celle du mercredi, air Watos.", "examples": [{"text": "Mardi à 20 h, on suit la règle du soir.", "translation": "On prie déjà la théotokie du mercredi."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_kiahk', 'eg', 'Kiahk', 'le 4e mois copte (vers décembre) : le mois marial', 'Kiahk est le quatrième mois du calendrier copte, vers décembre. On y loue la Vierge par ses théotokies et ses chants. Il tombe pendant le jeûne de la Nativité.', '[{"text": "En Kiahk, on loue Marie chaque soir.", "translation": "Le mois entier lui est consacré."}]'::jsonb, null, '{"id": "eg.d.c12_kiahk", "unitId": "eg.v.c12_kiahk", "word": "Kiahk", "translation": "le 4e mois copte (vers décembre) : le mois marial", "partOfSpeech": "event", "collection": "notion", "explanation": "Kiahk est le quatrième mois du calendrier copte, vers décembre. On y loue la Vierge par ses théotokies et ses chants. Il tombe pendant le jeûne de la Nativité.", "examples": [{"text": "En Kiahk, on loue Marie chaque soir.", "translation": "Le mois entier lui est consacré."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_tasbeha_sept_et_quatre', 'eg', 'la tasbeha « sept et quatre »', 'la grande tasbeha de Kiahk : les 7 théotokies et les 4 hoos', 'En Kiahk, on prie la grande tasbeha dite « sept et quatre » : les 7 théotokies, une pour chaque jour de la semaine, et les 4 hoos. Elle est plus riche que la tasbeha ordinaire.', '[{"text": "La tasbeha « sept et quatre » est la grande tasbeha de Kiahk.", "translation": "Sept théotokies et quatre hoos."}]'::jsonb, null, '{"id": "eg.d.c12_tasbeha_sept_et_quatre", "unitId": "eg.v.c12_tasbeha_sept_et_quatre", "word": "la tasbeha « sept et quatre »", "translation": "la grande tasbeha de Kiahk : les 7 théotokies et les 4 hoos", "partOfSpeech": "concept", "collection": "priere", "explanation": "En Kiahk, on prie la grande tasbeha dite « sept et quatre » : les 7 théotokies, une pour chaque jour de la semaine, et les 4 hoos. Elle est plus riche que la tasbeha ordinaire.", "examples": [{"text": "La tasbeha « sept et quatre » est la grande tasbeha de Kiahk.", "translation": "Sept théotokies et quatre hoos."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c12_jeune_de_la_nativite', 'eg', 'le jeûne de la Nativité', 'le temps de jeûne qui précède Noël, pendant lequel tombe Kiahk', 'Le jeûne de la Nativité prépare la fête de la naissance du Christ. Le mois de Kiahk, mois de la Vierge, tombe pendant ce jeûne.', '[{"text": "Kiahk tombe pendant le jeûne de la Nativité.", "translation": "On prépare la venue du Christ avec Marie."}]'::jsonb, null, '{"id": "eg.d.c12_jeune_de_la_nativite", "unitId": "eg.v.c12_jeune_de_la_nativite", "word": "le jeûne de la Nativité", "translation": "le temps de jeûne qui précède Noël, pendant lequel tombe Kiahk", "partOfSpeech": "concept", "collection": "notion", "explanation": "Le jeûne de la Nativité prépare la fête de la naissance du Christ. Le mois de Kiahk, mois de la Vierge, tombe pendant ce jeûne.", "examples": [{"text": "Kiahk tombe pendant le jeûne de la Nativité.", "translation": "On prépare la venue du Christ avec Marie."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c13_calendrier_solaire', 'eg', 'le calendrier solaire', '12 mois de 30 jours plus un petit mois de 5 jours', 'Les anciens Égyptiens ont réglé leur année sur le soleil et sur le Nil : douze mois de 30 jours, plus un petit mois de 5 jours. Le total fait 365 jours. Les Coptes ont gardé ce calendrier.', '[{"text": "Douze mois de 30 jours, plus 5 jours : 365 en tout.", "translation": "Un calendrier réglé sur le soleil, pas sur la lune."}]'::jsonb, null, '{"id": "eg.d.c13_calendrier_solaire", "unitId": "eg.v.c13_calendrier_solaire", "word": "le calendrier solaire", "translation": "12 mois de 30 jours plus un petit mois de 5 jours", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les anciens Égyptiens ont réglé leur année sur le soleil et sur le Nil : douze mois de 30 jours, plus un petit mois de 5 jours. Le total fait 365 jours. Les Coptes ont gardé ce calendrier.", "examples": [{"text": "Douze mois de 30 jours, plus 5 jours : 365 en tout.", "translation": "Un calendrier réglé sur le soleil, pas sur la lune."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c13_regle_du_dix', 'eg', 'l''astuce du 10', 'un mois copte commence vers le 10 d''un mois de notre calendrier', 'Chaque mois copte commence autour du 10 d''un mois de notre calendrier, entre le 7 et le 11. C''est un repère à un jour près : dans une année sur quatre, les dates glissent d''un jour.', '[{"text": "Baramhat commence vers le 10 mars.", "translation": "Presque tous les mois coptes démarrent vers le 10."}]'::jsonb, null, '{"id": "eg.d.c13_regle_du_dix", "unitId": "eg.v.c13_regle_du_dix", "word": "l''astuce du 10", "translation": "un mois copte commence vers le 10 d''un mois de notre calendrier", "partOfSpeech": "concept", "collection": "notion", "explanation": "Chaque mois copte commence autour du 10 d''un mois de notre calendrier, entre le 7 et le 11. C''est un repère à un jour près : dans une année sur quatre, les dates glissent d''un jour.", "examples": [{"text": "Baramhat commence vers le 10 mars.", "translation": "Presque tous les mois coptes démarrent vers le 10."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c13_tout', 'eg', 'Tout', 'premier mois copte (توت), vers le 11 septembre', 'Tout ouvre l''année copte : son premier jour est le Nayrouz, vers le 11 septembre. Son nom vient du dieu égyptien Thot, patron de la sagesse et de l''écriture. Le Nil est alors encore en pleine crue.', '[{"text": "Le 1er Tout, on fête le Nayrouz.", "translation": "Tout est le premier mois de l''année."}]'::jsonb, null, '{"id": "eg.d.c13_tout", "unitId": "eg.v.c13_tout", "word": "Tout", "translation": "premier mois copte (توت), vers le 11 septembre", "partOfSpeech": "event", "collection": "date", "explanation": "Tout ouvre l''année copte : son premier jour est le Nayrouz, vers le 11 septembre. Son nom vient du dieu égyptien Thot, patron de la sagesse et de l''écriture. Le Nil est alors encore en pleine crue.", "examples": [{"text": "Le 1er Tout, on fête le Nayrouz.", "translation": "Tout est le premier mois de l''année."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c13_baba', 'eg', 'Baba', 'deuxième mois copte (بابه), vers le 11 octobre', 'Baba suit Tout. Son nom viendrait de la fête égyptienne d''Opet (l''étymologie est discutée). Le Nil commence à baisser, et le proverbe dit : entre et ferme la porte.', '[{"text": "Baba est le mois de « Entre et ferme la porte ».", "translation": "Le deuxième mois, quand les nuits fraîchissent."}]'::jsonb, null, '{"id": "eg.d.c13_baba", "unitId": "eg.v.c13_baba", "word": "Baba", "translation": "deuxième mois copte (بابه), vers le 11 octobre", "partOfSpeech": "event", "collection": "date", "explanation": "Baba suit Tout. Son nom viendrait de la fête égyptienne d''Opet (l''étymologie est discutée). Le Nil commence à baisser, et le proverbe dit : entre et ferme la porte.", "examples": [{"text": "Baba est le mois de « Entre et ferme la porte ».", "translation": "Le deuxième mois, quand les nuits fraîchissent."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c13_hatour', 'eg', 'Hatour', 'troisième mois copte (هاتور), vers le 10 novembre', 'Hatour porte le nom de la déesse Hathor, déesse de la joie et de l''amour. C''est le temps des semailles : on sème le blé dans la terre que le Nil vient de quitter. Le proverbe parle de « l''or répandu ».', '[{"text": "En Hatour, on sème le blé.", "translation": "Le troisième mois, celui des semailles."}]'::jsonb, null, '{"id": "eg.d.c13_hatour", "unitId": "eg.v.c13_hatour", "word": "Hatour", "translation": "troisième mois copte (هاتور), vers le 10 novembre", "partOfSpeech": "event", "collection": "date", "explanation": "Hatour porte le nom de la déesse Hathor, déesse de la joie et de l''amour. C''est le temps des semailles : on sème le blé dans la terre que le Nil vient de quitter. Le proverbe parle de « l''or répandu ».", "examples": [{"text": "En Hatour, on sème le blé.", "translation": "Le troisième mois, celui des semailles."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c13_touba', 'eg', 'Touba', 'cinquième mois copte (طوبة), vers le 9 janvier : le plus froid', 'Touba est le cœur de l''hiver, le mois le plus froid de l''année en Égypte. Le proverbe dit qu''il rend la jeune fille recroquevillée. L''origine exacte de son nom est discutée.', '[{"text": "Touba suit Kiahk.", "translation": "Le cinquième mois, plein hiver."}]'::jsonb, null, '{"id": "eg.d.c13_touba", "unitId": "eg.v.c13_touba", "word": "Touba", "translation": "cinquième mois copte (طوبة), vers le 9 janvier : le plus froid", "partOfSpeech": "event", "collection": "date", "explanation": "Touba est le cœur de l''hiver, le mois le plus froid de l''année en Égypte. Le proverbe dit qu''il rend la jeune fille recroquevillée. L''origine exacte de son nom est discutée.", "examples": [{"text": "Touba suit Kiahk.", "translation": "Le cinquième mois, plein hiver."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c13_amshir', 'eg', 'Amshir', 'sixième mois copte (أمشير), vers le 8 février : le mois des vents', 'Amshir est le mois des vents : rafales, poussière, temps qui change d''un jour à l''autre. Le proverbe dit « père des rafales nombreuses ». Il se termine vers le 9 mars.', '[{"text": "Amshir est le mois des rafales.", "translation": "Le sixième mois, juste avant Baramhat."}]'::jsonb, null, '{"id": "eg.d.c13_amshir", "unitId": "eg.v.c13_amshir", "word": "Amshir", "translation": "sixième mois copte (أمشير), vers le 8 février : le mois des vents", "partOfSpeech": "event", "collection": "date", "explanation": "Amshir est le mois des vents : rafales, poussière, temps qui change d''un jour à l''autre. Le proverbe dit « père des rafales nombreuses ». Il se termine vers le 9 mars.", "examples": [{"text": "Amshir est le mois des rafales.", "translation": "Le sixième mois, juste avant Baramhat."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c13_baramhat', 'eg', 'Baramhat', 'septième mois copte (برمهات), vers le 10 mars', 'Baramhat est le septième mois. Le blé mûrit et la récolte commence : « va au champ et rapporte ». Son nom viendrait d''une fête de l''ancienne Égypte (le détail est discuté).', '[{"text": "En Baramhat, on va au champ et on rapporte.", "translation": "Le septième mois, début de la récolte."}]'::jsonb, null, '{"id": "eg.d.c13_baramhat", "unitId": "eg.v.c13_baramhat", "word": "Baramhat", "translation": "septième mois copte (برمهات), vers le 10 mars", "partOfSpeech": "event", "collection": "date", "explanation": "Baramhat est le septième mois. Le blé mûrit et la récolte commence : « va au champ et rapporte ». Son nom viendrait d''une fête de l''ancienne Égypte (le détail est discuté).", "examples": [{"text": "En Baramhat, on va au champ et on rapporte.", "translation": "Le septième mois, début de la récolte."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c13_baramouda', 'eg', 'Baramouda', 'huitième mois copte (برمودة), vers le 9 avril', 'Baramouda est le huitième mois, en pleine moisson. Le blé mûr est battu : « bats le grain avec le bâton ». Ne le confonds pas avec Baramhat, qui vient juste avant.', '[{"text": "En Baramouda, on bat le grain.", "translation": "Le huitième mois, après Baramhat."}]'::jsonb, null, '{"id": "eg.d.c13_baramouda", "unitId": "eg.v.c13_baramouda", "word": "Baramouda", "translation": "huitième mois copte (برمودة), vers le 9 avril", "partOfSpeech": "event", "collection": "date", "explanation": "Baramouda est le huitième mois, en pleine moisson. Le blé mûr est battu : « bats le grain avec le bâton ». Ne le confonds pas avec Baramhat, qui vient juste avant.", "examples": [{"text": "En Baramouda, on bat le grain.", "translation": "Le huitième mois, après Baramhat."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c13_bashans', 'eg', 'Bashans', 'neuvième mois copte (بشنس), vers le 9 mai', 'Bashans est le neuvième mois. Les champs sont vides : le proverbe dit que Bashans balaie le champ. La récolte est finie.', '[{"text": "Bashans balaie le champ.", "translation": "Le neuvième mois, quand la moisson est finie."}]'::jsonb, null, '{"id": "eg.d.c13_bashans", "unitId": "eg.v.c13_bashans", "word": "Bashans", "translation": "neuvième mois copte (بشنس), vers le 9 mai", "partOfSpeech": "event", "collection": "date", "explanation": "Bashans est le neuvième mois. Les champs sont vides : le proverbe dit que Bashans balaie le champ. La récolte est finie.", "examples": [{"text": "Bashans balaie le champ.", "translation": "Le neuvième mois, quand la moisson est finie."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c13_baouna', 'eg', 'Baouna', 'dixième mois copte (بؤونة), vers le 8 juin', 'Baouna est le dixième mois, en pleine chaleur. Vers sa fin, le Nil commence à monter : la crue approche.', '[{"text": "En Baouna, le Nil recommence à monter.", "translation": "Le dixième mois, chaud mais plein d''espoir."}]'::jsonb, null, '{"id": "eg.d.c13_baouna", "unitId": "eg.v.c13_baouna", "word": "Baouna", "translation": "dixième mois copte (بؤونة), vers le 8 juin", "partOfSpeech": "event", "collection": "date", "explanation": "Baouna est le dixième mois, en pleine chaleur. Vers sa fin, le Nil commence à monter : la crue approche.", "examples": [{"text": "En Baouna, le Nil recommence à monter.", "translation": "Le dixième mois, chaud mais plein d''espoir."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c13_abib', 'eg', 'Abib', 'onzième mois copte (أبيب), vers le 8 juillet', 'Abib est le onzième mois, au cœur de l''été. On ne sait pas d''où vient son nom : c''est un petit mystère de plus dans le calendrier.', '[{"text": "Abib tombe en plein été.", "translation": "Le onzième mois, avant Misra."}]'::jsonb, null, '{"id": "eg.d.c13_abib", "unitId": "eg.v.c13_abib", "word": "Abib", "translation": "onzième mois copte (أبيب), vers le 8 juillet", "partOfSpeech": "event", "collection": "date", "explanation": "Abib est le onzième mois, au cœur de l''été. On ne sait pas d''où vient son nom : c''est un petit mystère de plus dans le calendrier.", "examples": [{"text": "Abib tombe en plein été.", "translation": "Le onzième mois, avant Misra."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c13_misra', 'eg', 'Misra', 'douzième mois copte (مسرى), vers le 7 août', 'Misra est le douzième et dernier grand mois. La crue remplit les canaux et irrigue les champs. Après lui, il ne reste plus que le petit mois, Nasie.', '[{"text": "En Misra, la crue remplit les canaux.", "translation": "Le douzième mois, celui de la crue."}]'::jsonb, null, '{"id": "eg.d.c13_misra", "unitId": "eg.v.c13_misra", "word": "Misra", "translation": "douzième mois copte (مسرى), vers le 7 août", "partOfSpeech": "event", "collection": "date", "explanation": "Misra est le douzième et dernier grand mois. La crue remplit les canaux et irrigue les champs. Après lui, il ne reste plus que le petit mois, Nasie.", "examples": [{"text": "En Misra, la crue remplit les canaux.", "translation": "Le douzième mois, celui de la crue."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c13_nasie', 'eg', 'Nasie', 'treizième mois copte (النسيء), le petit mois de 5 jours', 'Nasie est le petit mois, juste avant le Nayrouz. Il compte 5 jours, ou 6 dans l''année bissextile copte. Son nom arabe évoque un mois qu''on ajoute.', '[{"text": "Nasie ferme l''année copte.", "translation": "Le treizième mois, tout petit."}]'::jsonb, null, '{"id": "eg.d.c13_nasie", "unitId": "eg.v.c13_nasie", "word": "Nasie", "translation": "treizième mois copte (النسيء), le petit mois de 5 jours", "partOfSpeech": "event", "collection": "date", "explanation": "Nasie est le petit mois, juste avant le Nayrouz. Il compte 5 jours, ou 6 dans l''année bissextile copte. Son nom arabe évoque un mois qu''on ajoute.", "examples": [{"text": "Nasie ferme l''année copte.", "translation": "Le treizième mois, tout petit."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c13_annee_bissextile_copte', 'eg', 'l''année bissextile copte', 'année où Nasie compte 6 jours, tous les quatre ans', 'L''année du soleil dure un peu plus de 365 jours. Pour rattraper, Nasie compte 6 jours tous les quatre ans. Le Nayrouz suivant tombe alors le 12 septembre au lieu du 11.', '[{"text": "Dans l''année bissextile, Nasie a 6 jours.", "translation": "Un jour de plus tous les quatre ans."}]'::jsonb, null, '{"id": "eg.d.c13_annee_bissextile_copte", "unitId": "eg.v.c13_annee_bissextile_copte", "word": "l''année bissextile copte", "translation": "année où Nasie compte 6 jours, tous les quatre ans", "partOfSpeech": "concept", "collection": "notion", "explanation": "L''année du soleil dure un peu plus de 365 jours. Pour rattraper, Nasie compte 6 jours tous les quatre ans. Le Nayrouz suivant tombe alors le 12 septembre au lieu du 11.", "examples": [{"text": "Dans l''année bissextile, Nasie a 6 jours.", "translation": "Un jour de plus tous les quatre ans."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c13_trois_saisons', 'eg', 'les trois saisons', 'la crue, la croissance, la moisson : quatre mois chacune', 'L''ancienne année égyptienne a trois saisons de quatre mois : la crue (Akhet), la croissance (Peret) et la moisson (Shemu). Nasie, le petit mois, ferme l''année.', '[{"text": "La crue va de Tout à Kiahk.", "translation": "Trois saisons × quatre mois, plus Nasie."}]'::jsonb, null, '{"id": "eg.d.c13_trois_saisons", "unitId": "eg.v.c13_trois_saisons", "word": "les trois saisons", "translation": "la crue, la croissance, la moisson : quatre mois chacune", "partOfSpeech": "concept", "collection": "notion", "explanation": "L''ancienne année égyptienne a trois saisons de quatre mois : la crue (Akhet), la croissance (Peret) et la moisson (Shemu). Nasie, le petit mois, ferme l''année.", "examples": [{"text": "La crue va de Tout à Kiahk.", "translation": "Trois saisons × quatre mois, plus Nasie."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c13_crue_du_nil', 'eg', 'la crue du Nil', 'montée annuelle des eaux du Nil, qui rythme l''année', 'Chaque année, le Nil monte, couvre les champs, puis se retire en laissant une terre fertile. Le calendrier égyptien est né de ce rythme.', '[{"text": "Le Nil se retire et laisse une terre noire.", "translation": "La crue rend la terre fertile."}]'::jsonb, null, '{"id": "eg.d.c13_crue_du_nil", "unitId": "eg.v.c13_crue_du_nil", "word": "la crue du Nil", "translation": "montée annuelle des eaux du Nil, qui rythme l''année", "partOfSpeech": "concept", "collection": "notion", "explanation": "Chaque année, le Nil monte, couvre les champs, puis se retire en laissant une terre fertile. Le calendrier égyptien est né de ce rythme.", "examples": [{"text": "Le Nil se retire et laisse une terre noire.", "translation": "La crue rend la terre fertile."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c13_treize_mois', 'eg', 'les treize mois', 'de Tout à Nasie : douze mois de 30 jours et un petit mois', 'L''année copte compte treize mois : douze de 30 jours, plus Nasie, le petit mois de 5 jours. Ils commencent tous vers le 10 d''un mois de notre calendrier.', '[{"text": "Tout est le premier mois, Nasie le treizième.", "translation": "L''ordre des mois est le fil rouge du calendrier."}]'::jsonb, null, '{"id": "eg.d.c13_treize_mois", "unitId": "eg.v.c13_treize_mois", "word": "les treize mois", "translation": "de Tout à Nasie : douze mois de 30 jours et un petit mois", "partOfSpeech": "concept", "collection": "notion", "explanation": "L''année copte compte treize mois : douze de 30 jours, plus Nasie, le petit mois de 5 jours. Ils commencent tous vers le 10 d''un mois de notre calendrier.", "examples": [{"text": "Tout est le premier mois, Nasie le treizième.", "translation": "L''ordre des mois est le fil rouge du calendrier."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c13_proverbes_paysans', 'eg', 'les proverbes des mois', 'dictons de paysans égyptiens, un par mois ou presque', 'Les paysans ont mis les mois en proverbes, en arabe égyptien. Les formules varient d''un village à l''autre. Ce sont des dictons de la vie des champs, pas des règles de l''Église.', '[{"text": "« Bashans balaie le champ » est un proverbe de paysans.", "translation": "Un dicton, pas une règle de foi."}]'::jsonb, null, '{"id": "eg.d.c13_proverbes_paysans", "unitId": "eg.v.c13_proverbes_paysans", "word": "les proverbes des mois", "translation": "dictons de paysans égyptiens, un par mois ou presque", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les paysans ont mis les mois en proverbes, en arabe égyptien. Les formules varient d''un village à l''autre. Ce sont des dictons de la vie des champs, pas des règles de l''Église.", "examples": [{"text": "« Bashans balaie le champ » est un proverbe de paysans.", "translation": "Un dicton, pas une règle de foi."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_moise_le_noir', 'eg', 'Moïse le Noir', 'ancien chef de brigands devenu moine à Scété', 'Moïse, d''origine nubienne, est d''abord esclave puis chef de voleurs. Il se réfugie à Scété, devient moine, dompte sa violence et devient un père spirituel respecté. Il est tué vers 405 par des Berbères, avec sept frères. Son histoire dit à l''Église copte que personne n''est perdu.', '[{"text": "Moïse le Noir traîne un sac de sable troué devant ses frères.", "translation": "Ses propres péchés coulent derrière lui : il ne juge personne."}]'::jsonb, null, '{"id": "eg.d.c14_moise_le_noir", "unitId": "eg.v.c14_moise_le_noir", "word": "Moïse le Noir", "translation": "ancien chef de brigands devenu moine à Scété", "partOfSpeech": "person", "collection": "saint", "explanation": "Moïse, d''origine nubienne, est d''abord esclave puis chef de voleurs. Il se réfugie à Scété, devient moine, dompte sa violence et devient un père spirituel respecté. Il est tué vers 405 par des Berbères, avec sept frères. Son histoire dit à l''Église copte que personne n''est perdu.", "examples": [{"text": "Moïse le Noir traîne un sac de sable troué devant ses frères.", "translation": "Ses propres péchés coulent derrière lui : il ne juge personne."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_anba', 'eg', 'Anba (abba)', 'père : titre des moines et des évêques coptes', 'Anba vient de abba, « père ». On donne ce titre aux moines respectés et aux évêques. On dit Anba Bishoy, Anba Abraam. Un moine comme Moïse devient un père spirituel que l''on vient consulter.', '[{"text": "Les frères appellent Moïse « abba ».", "translation": "Ils le respectent comme un père."}]'::jsonb, null, '{"id": "eg.d.c14_anba", "unitId": "eg.v.c14_anba", "word": "Anba (abba)", "translation": "père : titre des moines et des évêques coptes", "partOfSpeech": "concept", "collection": "notion", "explanation": "Anba vient de abba, « père ». On donne ce titre aux moines respectés et aux évêques. On dit Anba Bishoy, Anba Abraam. Un moine comme Moïse devient un père spirituel que l''on vient consulter.", "examples": [{"text": "Les frères appellent Moïse « abba ».", "translation": "Ils le respectent comme un père."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_apophtegmes', 'eg', 'les Apophtegmes des Pères', 'recueil des paroles et petites histoires des Pères du désert', 'Les Apophtegmes sont des paroles courtes et des petites histoires des moines d''Égypte, notées par écrit au Ve siècle. Pas de théorie : de la sagesse de tous les jours, comme le sac de sable de Moïse.', '[{"text": "Les Apophtegmes des Pères gardent les paroles de Moïse le Noir.", "translation": "Ce sont les paroles des moines, mises par écrit."}]'::jsonb, null, '{"id": "eg.d.c14_apophtegmes", "unitId": "eg.v.c14_apophtegmes", "word": "les Apophtegmes des Pères", "translation": "recueil des paroles et petites histoires des Pères du désert", "partOfSpeech": "work", "collection": "livre", "explanation": "Les Apophtegmes sont des paroles courtes et des petites histoires des moines d''Égypte, notées par écrit au Ve siècle. Pas de théorie : de la sagesse de tous les jours, comme le sac de sable de Moïse.", "examples": [{"text": "Les Apophtegmes des Pères gardent les paroles de Moïse le Noir.", "translation": "Ce sont les paroles des moines, mises par écrit."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_jean_le_petit', 'eg', 'Jean le Petit', 'moine de Scété, le bâton sec de l''obéissance', 'Jean le Petit (vers 339-405) vit à Scété. Son maître lui demande d''arroser un bâton sec chaque jour, de très loin. Il obéit sans discuter pendant trois ans : le bâton donne des fruits. L''Église copte en fait le modèle de l''obéissance.', '[{"text": "Jean le Petit arrose son bâton sec jour après jour.", "translation": "Il obéit sans rien demander."}]'::jsonb, null, '{"id": "eg.d.c14_jean_le_petit", "unitId": "eg.v.c14_jean_le_petit", "word": "Jean le Petit", "translation": "moine de Scété, le bâton sec de l''obéissance", "partOfSpeech": "person", "collection": "saint", "explanation": "Jean le Petit (vers 339-405) vit à Scété. Son maître lui demande d''arroser un bâton sec chaque jour, de très loin. Il obéit sans discuter pendant trois ans : le bâton donne des fruits. L''Église copte en fait le modèle de l''obéissance.", "examples": [{"text": "Jean le Petit arrose son bâton sec jour après jour.", "translation": "Il obéit sans rien demander."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_arsene', 'eg', 'Arsène le Grand', 'précepteur des fils de l''empereur devenu moine du silence', 'Arsène est un Romain très instruit, précepteur des fils de l''empereur à Constantinople. Vers 400, il quitte la cour pour Scété et vit dans le silence. Il meurt au milieu du Ve siècle, près de Memphis.', '[{"text": "Arsène quitte la cour de l''empereur pour le désert.", "translation": "Il choisit le silence plutôt que la gloire."}]'::jsonb, null, '{"id": "eg.d.c14_arsene", "unitId": "eg.v.c14_arsene", "word": "Arsène le Grand", "translation": "précepteur des fils de l''empereur devenu moine du silence", "partOfSpeech": "person", "collection": "saint", "explanation": "Arsène est un Romain très instruit, précepteur des fils de l''empereur à Constantinople. Vers 400, il quitte la cour pour Scété et vit dans le silence. Il meurt au milieu du Ve siècle, près de Memphis.", "examples": [{"text": "Arsène quitte la cour de l''empereur pour le désert.", "translation": "Il choisit le silence plutôt que la gloire."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_obeissance', 'eg', 'l''obéissance', 'écouter et faire sans discuter, pour apprendre à aimer', 'Au désert, l''obéissance à l''ancien est une école d''humilité, avec la pauvreté et la chasteté. Jean le Petit en est l''image : il arrose un bâton sec sans comprendre, et le bâton donne du fruit.', '[{"text": "L''obéissance de Jean porte du fruit.", "translation": "Obéir, c''est faire confiance."}]'::jsonb, null, '{"id": "eg.d.c14_obeissance", "unitId": "eg.v.c14_obeissance", "word": "l''obéissance", "translation": "écouter et faire sans discuter, pour apprendre à aimer", "partOfSpeech": "concept", "collection": "notion", "explanation": "Au désert, l''obéissance à l''ancien est une école d''humilité, avec la pauvreté et la chasteté. Jean le Petit en est l''image : il arrose un bâton sec sans comprendre, et le bâton donne du fruit.", "examples": [{"text": "L''obéissance de Jean porte du fruit.", "translation": "Obéir, c''est faire confiance."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_bishoy', 'eg', 'Anba Bishoy', 'moine de Scété, ami du Christ et des pauvres', 'Bishoy (320-417) naît à Shansa, dans le Delta, et rejoint Scété auprès de Macaire le Grand. Pour ne pas s''endormir pendant la prière de la nuit, il attache ses cheveux au plafond de sa cellule. Selon la tradition, il porte le Christ lui-même, sous les traits d''un vieillard.', '[{"text": "Bishoy attache ses cheveux au plafond de sa cellule.", "translation": "Il veut prier toute la nuit sans s''endormir."}]'::jsonb, null, '{"id": "eg.d.c14_bishoy", "unitId": "eg.v.c14_bishoy", "word": "Anba Bishoy", "translation": "moine de Scété, ami du Christ et des pauvres", "partOfSpeech": "person", "collection": "saint", "explanation": "Bishoy (320-417) naît à Shansa, dans le Delta, et rejoint Scété auprès de Macaire le Grand. Pour ne pas s''endormir pendant la prière de la nuit, il attache ses cheveux au plafond de sa cellule. Selon la tradition, il porte le Christ lui-même, sous les traits d''un vieillard.", "examples": [{"text": "Bishoy attache ses cheveux au plafond de sa cellule.", "translation": "Il veut prier toute la nuit sans s''endormir."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_maxime_domece', 'eg', 'Maxime et Domèce', 'deux princes romains devenus moines à Scété', 'Maxime et Domèce sont deux frères, fils d''un empereur selon le Synaxaire. Ils quittent le palais et deviennent moines auprès de Macaire à Scété. Ils meurent jeunes, à trois jours d''écart, et sont enterrés ensemble.', '[{"text": "Maxime et Domèce quittent le palais pour une cellule.", "translation": "Des princes choisissent la pauvreté."}]'::jsonb, null, '{"id": "eg.d.c14_maxime_domece", "unitId": "eg.v.c14_maxime_domece", "word": "Maxime et Domèce", "translation": "deux princes romains devenus moines à Scété", "partOfSpeech": "person", "collection": "saint", "explanation": "Maxime et Domèce sont deux frères, fils d''un empereur selon le Synaxaire. Ils quittent le palais et deviennent moines auprès de Macaire à Scété. Ils meurent jeunes, à trois jours d''écart, et sont enterrés ensemble.", "examples": [{"text": "Maxime et Domèce quittent le palais pour une cellule.", "translation": "Des princes choisissent la pauvreté."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_hospitalite', 'eg', 'l''hospitalité', 'accueillir l''étranger et le pauvre comme le Christ', 'L''hospitalité est une vertu centrale des Pères du désert. Accueillir le pauvre ou l''étranger, c''est accueillir le Christ lui-même, comme Bishoy avec le vieillard.', '[{"text": "Bishoy pratique l''hospitalité en portant le vieillard.", "translation": "Le pauvre qu''on aide, c''est le Christ."}]'::jsonb, null, '{"id": "eg.d.c14_hospitalite", "unitId": "eg.v.c14_hospitalite", "word": "l''hospitalité", "translation": "accueillir l''étranger et le pauvre comme le Christ", "partOfSpeech": "concept", "collection": "notion", "explanation": "L''hospitalité est une vertu centrale des Pères du désert. Accueillir le pauvre ou l''étranger, c''est accueillir le Christ lui-même, comme Bishoy avec le vieillard.", "examples": [{"text": "Bishoy pratique l''hospitalité en portant le vieillard.", "translation": "Le pauvre qu''on aide, c''est le Christ."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_baramous', 'eg', 'Baramous, « des Romains »', 'monastère du Wadi Natroun, en souvenir de Maxime et Domèce', 'Baramous vient du copte Pa-Romeos, « des Romains », en souvenir de Maxime et Domèce. Ce monastère du Wadi Natroun existe encore. Moïse le Noir y repose, et le futur pape Cyrille VI y a vécu.', '[{"text": "Le monastère de Baramous porte le nom des deux princes romains.", "translation": "Baramous veut dire « des Romains »."}]'::jsonb, null, '{"id": "eg.d.c14_baramous", "unitId": "eg.v.c14_baramous", "word": "Baramous, « des Romains »", "translation": "monastère du Wadi Natroun, en souvenir de Maxime et Domèce", "partOfSpeech": "place", "collection": "lieu", "explanation": "Baramous vient du copte Pa-Romeos, « des Romains », en souvenir de Maxime et Domèce. Ce monastère du Wadi Natroun existe encore. Moïse le Noir y repose, et le futur pape Cyrille VI y a vécu.", "examples": [{"text": "Le monastère de Baramous porte le nom des deux princes romains.", "translation": "Baramous veut dire « des Romains »."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_samuel', 'eg', 'Samuel le Confesseur', 'moine du VIIe siècle, battu pour avoir refusé Chalcédoine', 'Samuel (vers 597-695) est un moine de Scété qui refuse Chalcédoine. Selon sa Vie, le patriarche melkite le fait battre et chasser. Il fonde ensuite le monastère de Qalamoun et reste fidèle jusqu''à sa mort. On l''appelle confesseur.', '[{"text": "Samuel le Confesseur est chassé de Scété pour sa fidélité.", "translation": "Il souffre sans mourir."}]'::jsonb, null, '{"id": "eg.d.c14_samuel", "unitId": "eg.v.c14_samuel", "word": "Samuel le Confesseur", "translation": "moine du VIIe siècle, battu pour avoir refusé Chalcédoine", "partOfSpeech": "person", "collection": "saint", "explanation": "Samuel (vers 597-695) est un moine de Scété qui refuse Chalcédoine. Selon sa Vie, le patriarche melkite le fait battre et chasser. Il fonde ensuite le monastère de Qalamoun et reste fidèle jusqu''à sa mort. On l''appelle confesseur.", "examples": [{"text": "Samuel le Confesseur est chassé de Scété pour sa fidélité.", "translation": "Il souffre sans mourir."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_qalamoun', 'eg', 'le monastère de Qalamoun', 'monastère fondé par Samuel en Moyenne-Égypte', 'Le monastère de Qalamoun est fondé par Samuel sur le mont Qalamoun, en Moyenne-Égypte, après son expulsion de Scété. C''est la preuve qu''on peut repartir de zéro sans renier sa foi.', '[{"text": "Samuel fonde Qalamoun après avoir été chassé de Scété.", "translation": "Chassé d''un désert, il en fonde un autre."}]'::jsonb, null, '{"id": "eg.d.c14_qalamoun", "unitId": "eg.v.c14_qalamoun", "word": "le monastère de Qalamoun", "translation": "monastère fondé par Samuel en Moyenne-Égypte", "partOfSpeech": "place", "collection": "lieu", "explanation": "Le monastère de Qalamoun est fondé par Samuel sur le mont Qalamoun, en Moyenne-Égypte, après son expulsion de Scété. C''est la preuve qu''on peut repartir de zéro sans renier sa foi.", "examples": [{"text": "Samuel fonde Qalamoun après avoir été chassé de Scété.", "translation": "Chassé d''un désert, il en fonde un autre."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_saint_mina', 'eg', 'saint Mina', 'soldat égyptien martyrisé vers 309, protecteur des pèlerins', 'Mina naît vers 285 à Nikiou, en Égypte. Soldat romain, il quitte l''armée pour vivre au désert, puis confesse sa foi en public. Il est martyrisé vers 309. Selon la tradition, un chameau emporte son corps jusqu''au lac Maryût.', '[{"text": "Saint Mina est l''un des saints soldats les plus aimés des Coptes.", "translation": "Il a quitté l''armée pour le Christ."}]'::jsonb, null, '{"id": "eg.d.c14_saint_mina", "unitId": "eg.v.c14_saint_mina", "word": "saint Mina", "translation": "soldat égyptien martyrisé vers 309, protecteur des pèlerins", "partOfSpeech": "person", "collection": "saint", "explanation": "Mina naît vers 285 à Nikiou, en Égypte. Soldat romain, il quitte l''armée pour vivre au désert, puis confesse sa foi en public. Il est martyrisé vers 309. Selon la tradition, un chameau emporte son corps jusqu''au lac Maryût.", "examples": [{"text": "Saint Mina est l''un des saints soldats les plus aimés des Coptes.", "translation": "Il a quitté l''armée pour le Christ."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_abou_mina', 'eg', 'Abou Mina', 'ville de pèlerinage bâtie sur la tombe de saint Mina', 'Abou Mina est la ville née sur la tombe de Mina, près d''Alexandrie. Du Ve au VIIe siècle, c''est un grand centre de pèlerinage : on y vient chercher la guérison.', '[{"text": "Les pèlerins se rendent à Abou Mina.", "translation": "C''est la ville du tombeau de Mina."}]'::jsonb, null, '{"id": "eg.d.c14_abou_mina", "unitId": "eg.v.c14_abou_mina", "word": "Abou Mina", "translation": "ville de pèlerinage bâtie sur la tombe de saint Mina", "partOfSpeech": "place", "collection": "lieu", "explanation": "Abou Mina est la ville née sur la tombe de Mina, près d''Alexandrie. Du Ve au VIIe siècle, c''est un grand centre de pèlerinage : on y vient chercher la guérison.", "examples": [{"text": "Les pèlerins se rendent à Abou Mina.", "translation": "C''est la ville du tombeau de Mina."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_ampoule', 'eg', 'les ampoules de saint Mina', 'petites gourdes d''argile des pèlerins d''Abou Mina', 'Les pèlerins repartent d''Abou Mina avec de petites ampoules d''argile pleines d''huile bénite. Chacune est marquée de l''image de Mina entre deux chameaux. On en retrouve dans toute la Méditerranée.', '[{"text": "Cette ampoule porte Mina entre deux chameaux.", "translation": "Une trace des pèlerins du Ve au VIIe siècle."}]'::jsonb, null, '{"id": "eg.d.c14_ampoule", "unitId": "eg.v.c14_ampoule", "word": "les ampoules de saint Mina", "translation": "petites gourdes d''argile des pèlerins d''Abou Mina", "partOfSpeech": "concept", "collection": "objet", "explanation": "Les pèlerins repartent d''Abou Mina avec de petites ampoules d''argile pleines d''huile bénite. Chacune est marquée de l''image de Mina entre deux chameaux. On en retrouve dans toute la Méditerranée.", "examples": [{"text": "Cette ampoule porte Mina entre deux chameaux.", "translation": "Une trace des pèlerins du Ve au VIIe siècle."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_maryut', 'eg', 'le lac Maryût', 'lac au sud d''Alexandrie où repose saint Mina', 'Le lac Maryût (Mariout) est au sud d''Alexandrie. Selon la tradition, le chameau qui porte le corps de Mina s''y arrête de lui-même, et c''est là qu''on l''enterre. Le grand monastère de Mina y est construit au XXe siècle.', '[{"text": "Mina est enterré près du lac Maryût.", "translation": "Le chameau s''est arrêté là."}]'::jsonb, null, '{"id": "eg.d.c14_maryut", "unitId": "eg.v.c14_maryut", "word": "le lac Maryût", "translation": "lac au sud d''Alexandrie où repose saint Mina", "partOfSpeech": "place", "collection": "lieu", "explanation": "Le lac Maryût (Mariout) est au sud d''Alexandrie. Selon la tradition, le chameau qui porte le corps de Mina s''y arrête de lui-même, et c''est là qu''on l''enterre. Le grand monastère de Mina y est construit au XXe siècle.", "examples": [{"text": "Mina est enterré près du lac Maryût.", "translation": "Le chameau s''est arrêté là."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_saint_soldat', 'eg', 'un saint soldat', 'militaire romain qui refuse d''adorer l''empereur et meurt martyr', 'Dans l''armée romaine, chaque soldat doit sacrifier aux dieux et à l''empereur. Les soldats chrétiens refusent et préfèrent mourir : l''Église les appelle saints soldats, car ils combattent pour le Christ. Georges, Mina et Mercure sont parmi les plus aimés des Coptes.', '[{"text": "Georges, Mina et Mercure sont des saints soldats.", "translation": "Ils refusent l''idole, pas le courage."}]'::jsonb, null, '{"id": "eg.d.c14_saint_soldat", "unitId": "eg.v.c14_saint_soldat", "word": "un saint soldat", "translation": "militaire romain qui refuse d''adorer l''empereur et meurt martyr", "partOfSpeech": "concept", "collection": "notion", "explanation": "Dans l''armée romaine, chaque soldat doit sacrifier aux dieux et à l''empereur. Les soldats chrétiens refusent et préfèrent mourir : l''Église les appelle saints soldats, car ils combattent pour le Christ. Georges, Mina et Mercure sont parmi les plus aimés des Coptes.", "examples": [{"text": "Georges, Mina et Mercure sont des saints soldats.", "translation": "Ils refusent l''idole, pas le courage."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_abou_sefein', 'eg', 'saint Mercure (Abou Sefein)', 'officier martyr du IIIe siècle, « le père des deux épées »', 'Philopatir Mercure (« qui aime son père ») est un officier romain sous l''empereur Dèce. Selon la tradition, l''archange Michel lui remet une épée avant un combat : d''où son surnom Abou Sefein, « père des deux épées ». Il refuse les idoles et est décapité à Césarée vers 250.', '[{"text": "Abou Sefein est le surnom de saint Mercure.", "translation": "Il veut dire « père des deux épées »."}]'::jsonb, null, '{"id": "eg.d.c14_abou_sefein", "unitId": "eg.v.c14_abou_sefein", "word": "saint Mercure (Abou Sefein)", "translation": "officier martyr du IIIe siècle, « le père des deux épées »", "partOfSpeech": "person", "collection": "saint", "explanation": "Philopatir Mercure (« qui aime son père ») est un officier romain sous l''empereur Dèce. Selon la tradition, l''archange Michel lui remet une épée avant un combat : d''où son surnom Abou Sefein, « père des deux épées ». Il refuse les idoles et est décapité à Césarée vers 250.", "examples": [{"text": "Abou Sefein est le surnom de saint Mercure.", "translation": "Il veut dire « père des deux épées »."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_prince_des_martyrs', 'eg', 'le prince des martyrs', 'titre donné par les Coptes à saint Georges', 'Les Coptes appellent Georges le prince des martyrs, pour sa fermeté sous les tortures. Ne le confonds pas avec le pape Pierre, qu''on appelle le sceau des martyrs.', '[{"text": "Georges est le prince des martyrs.", "translation": "Le titre dit sa fermeté sous la torture."}]'::jsonb, null, '{"id": "eg.d.c14_prince_des_martyrs", "unitId": "eg.v.c14_prince_des_martyrs", "word": "le prince des martyrs", "translation": "titre donné par les Coptes à saint Georges", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les Coptes appellent Georges le prince des martyrs, pour sa fermeté sous les tortures. Ne le confonds pas avec le pape Pierre, qu''on appelle le sceau des martyrs.", "examples": [{"text": "Georges est le prince des martyrs.", "translation": "Le titre dit sa fermeté sous la torture."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_abanoub', 'eg', 'saint Abanoub', 'l''enfant martyr de douze ans, de Nehisa', 'Abanoub naît à Nehisa, dans le Delta. À douze ans, selon la tradition, il refuse d''adorer les idoles devant le gouverneur, sous Dioclétien. Après des tortures, il est décapité à Alexandrie, et ses reliques reposent à Samannoud. Beaucoup d''églises coptes portent son nom.', '[{"text": "Abanoub a douze ans devant le gouverneur.", "translation": "Un enfant ne cède pas."}]'::jsonb, null, '{"id": "eg.d.c14_abanoub", "unitId": "eg.v.c14_abanoub", "word": "saint Abanoub", "translation": "l''enfant martyr de douze ans, de Nehisa", "partOfSpeech": "person", "collection": "saint", "explanation": "Abanoub naît à Nehisa, dans le Delta. À douze ans, selon la tradition, il refuse d''adorer les idoles devant le gouverneur, sous Dioclétien. Après des tortures, il est décapité à Alexandrie, et ses reliques reposent à Samannoud. Beaucoup d''églises coptes portent son nom.", "examples": [{"text": "Abanoub a douze ans devant le gouverneur.", "translation": "Un enfant ne cède pas."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_demiana', 'eg', 'sainte Démiana', 'fille d''un gouverneur, martyre avec quarante vierges', 'Démiana est la fille de Marc, gouverneur chrétien du Delta. Elle lui demande un palais pour vivre en prière avec quarante jeunes filles. Sous Dioclétien, elles refusent de renier leur foi et sont décapitées. Le couvent de Démiana, près de Belqas, garde sa mémoire.', '[{"text": "Démiana vit en prière dans un palais.", "translation": "Elle refuse de renier sa foi."}]'::jsonb, null, '{"id": "eg.d.c14_demiana", "unitId": "eg.v.c14_demiana", "word": "sainte Démiana", "translation": "fille d''un gouverneur, martyre avec quarante vierges", "partOfSpeech": "person", "collection": "saint", "explanation": "Démiana est la fille de Marc, gouverneur chrétien du Delta. Elle lui demande un palais pour vivre en prière avec quarante jeunes filles. Sous Dioclétien, elles refusent de renier leur foi et sont décapitées. Le couvent de Démiana, près de Belqas, garde sa mémoire.", "examples": [{"text": "Démiana vit en prière dans un palais.", "translation": "Elle refuse de renier sa foi."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_quarante_vierges', 'eg', 'les quarante vierges', 'les compagnes de Démiana, martyrisées avec elle', 'Les quarante vierges sont les jeunes filles qui vivent avec Démiana dans le palais de prière. Elles meurent martyres avec elle, sous Dioclétien.', '[{"text": "Démiana et les quarante vierges sont fêtées ensemble.", "translation": "Une petite communauté de prière devient une communauté de martyres."}]'::jsonb, null, '{"id": "eg.d.c14_quarante_vierges", "unitId": "eg.v.c14_quarante_vierges", "word": "les quarante vierges", "translation": "les compagnes de Démiana, martyrisées avec elle", "partOfSpeech": "person", "collection": "saint", "explanation": "Les quarante vierges sont les jeunes filles qui vivent avec Démiana dans le palais de prière. Elles meurent martyres avec elle, sous Dioclétien.", "examples": [{"text": "Démiana et les quarante vierges sont fêtées ensemble.", "translation": "Une petite communauté de prière devient une communauté de martyres."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_hagiographie', 'eg', 'l''hagiographie', 'récit de la vie d''un saint', 'L''hagiographie raconte la vie d''un saint. Ces récits sont souvent écrits longtemps après les faits : on y lit d''abord un témoignage de foi, avec des détails parfois discutés par les historiens.', '[{"text": "Les vies de Catherine et de Barbara sont des hagiographies.", "translation": "Le récit dit la foi plus que les détails."}]'::jsonb, null, '{"id": "eg.d.c14_hagiographie", "unitId": "eg.v.c14_hagiographie", "word": "l''hagiographie", "translation": "récit de la vie d''un saint", "partOfSpeech": "concept", "collection": "notion", "explanation": "L''hagiographie raconte la vie d''un saint. Ces récits sont souvent écrits longtemps après les faits : on y lit d''abord un témoignage de foi, avec des détails parfois discutés par les historiens.", "examples": [{"text": "Les vies de Catherine et de Barbara sont des hagiographies.", "translation": "Le récit dit la foi plus que les détails."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_catherine', 'eg', 'sainte Catherine d''Alexandrie', 'jeune savante martyre vers 305, à la roue brisée', 'Selon la tradition, Catherine est une jeune Alexandrine très instruite. Elle confond cinquante philosophes réunis par l''empereur ; la roue prévue pour la torturer se brise, puis elle est décapitée vers 305. On l''invoque comme patronne des étudiants et des philosophes.', '[{"text": "Catherine gagne un débat contre cinquante philosophes.", "translation": "L''intelligence au service de la foi."}]'::jsonb, null, '{"id": "eg.d.c14_catherine", "unitId": "eg.v.c14_catherine", "word": "sainte Catherine d''Alexandrie", "translation": "jeune savante martyre vers 305, à la roue brisée", "partOfSpeech": "person", "collection": "saint", "explanation": "Selon la tradition, Catherine est une jeune Alexandrine très instruite. Elle confond cinquante philosophes réunis par l''empereur ; la roue prévue pour la torturer se brise, puis elle est décapitée vers 305. On l''invoque comme patronne des étudiants et des philosophes.", "examples": [{"text": "Catherine gagne un débat contre cinquante philosophes.", "translation": "L''intelligence au service de la foi."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_barbara', 'eg', 'sainte Barbara', 'jeune martyre enfermée dans une tour par son père', 'Selon la tradition, Barbara est la fille d''un riche païen qui l''enferme dans une tour. Elle devient chrétienne en secret, refuse le mariage et meurt martyre. Une église du Vieux-Caire porte son nom et garde ses reliques.', '[{"text": "Barbara est enfermée dans une tour.", "translation": "Elle reste fidèle derrière les murs."}]'::jsonb, null, '{"id": "eg.d.c14_barbara", "unitId": "eg.v.c14_barbara", "word": "sainte Barbara", "translation": "jeune martyre enfermée dans une tour par son père", "partOfSpeech": "person", "collection": "saint", "explanation": "Selon la tradition, Barbara est la fille d''un riche païen qui l''enferme dans une tour. Elle devient chrétienne en secret, refuse le mariage et meurt martyre. Une église du Vieux-Caire porte son nom et garde ses reliques.", "examples": [{"text": "Barbara est enfermée dans une tour.", "translation": "Elle reste fidèle derrière les murs."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_marie_egyptienne', 'eg', 'Marie l''Égyptienne', 'pécheresse d''Alexandrie devenue sainte du désert', 'Marie quitte sa famille à douze ans et mène à Alexandrie une vie de péché. À Jérusalem, devant l''icône de la Vierge, elle pleure et promet de changer. Elle passe le reste de sa vie au désert. Sa Vie est écrite par Sophrone de Jérusalem, et l''Église copte fait mémoire d''elle le 6 Baramouda.', '[{"text": "Marie l''Égyptienne se repent devant l''icône de la Vierge.", "translation": "Elle montre qu''on peut toujours revenir à Dieu."}]'::jsonb, null, '{"id": "eg.d.c14_marie_egyptienne", "unitId": "eg.v.c14_marie_egyptienne", "word": "Marie l''Égyptienne", "translation": "pécheresse d''Alexandrie devenue sainte du désert", "partOfSpeech": "person", "collection": "saint", "explanation": "Marie quitte sa famille à douze ans et mène à Alexandrie une vie de péché. À Jérusalem, devant l''icône de la Vierge, elle pleure et promet de changer. Elle passe le reste de sa vie au désert. Sa Vie est écrite par Sophrone de Jérusalem, et l''Église copte fait mémoire d''elle le 6 Baramouda.", "examples": [{"text": "Marie l''Égyptienne se repent devant l''icône de la Vierge.", "translation": "Elle montre qu''on peut toujours revenir à Dieu."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_zosime', 'eg', 'Zosime', 'moine qui rencontre Marie au désert et l''enterre', 'Zosime est le moine qui rencontre Marie au désert, écoute son histoire et lui donne la communion. L''année suivante, il la retrouve morte : un lion l''aide à creuser sa tombe.', '[{"text": "Zosime donne la communion à Marie.", "translation": "Un lion l''aide à creuser la tombe."}]'::jsonb, null, '{"id": "eg.d.c14_zosime", "unitId": "eg.v.c14_zosime", "word": "Zosime", "translation": "moine qui rencontre Marie au désert et l''enterre", "partOfSpeech": "person", "collection": "saint", "explanation": "Zosime est le moine qui rencontre Marie au désert, écoute son histoire et lui donne la communion. L''année suivante, il la retrouve morte : un lion l''aide à creuser sa tombe.", "examples": [{"text": "Zosime donne la communion à Marie.", "translation": "Un lion l''aide à creuser la tombe."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_marina', 'eg', 'Marina la moniale', 'sainte déguisée en moine sous le nom de Marinos', 'Marina coupe ses cheveux et entre dans un monastère déguisée en homme, sous le nom de Marinos. Accusée à tort d''être le père d''un enfant, elle se tait, accepte la punition et élève l''enfant. À sa mort, on découvre qu''elle est une femme : son innocence éclate.', '[{"text": "Marina se tait quand on l''accuse à tort.", "translation": "Son humilité éclate à sa mort."}]'::jsonb, null, '{"id": "eg.d.c14_marina", "unitId": "eg.v.c14_marina", "word": "Marina la moniale", "translation": "sainte déguisée en moine sous le nom de Marinos", "partOfSpeech": "person", "collection": "saint", "explanation": "Marina coupe ses cheveux et entre dans un monastère déguisée en homme, sous le nom de Marinos. Accusée à tort d''être le père d''un enfant, elle se tait, accepte la punition et élève l''enfant. À sa mort, on découvre qu''elle est une femme : son innocence éclate.", "examples": [{"text": "Marina se tait quand on l''accuse à tort.", "translation": "Son humilité éclate à sa mort."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_anastasie', 'eg', 'Anastasie la patricienne', 'dame de la cour de Justinien devenue ermite à Scété', 'Anastasie est une dame de la cour de Justinien, au VIe siècle. Jalouse, l''impératrice Théodora la poursuit : elle s''enfuit en Égypte. Après la mort de Théodora, elle gagne Scété et vit en ermite, déguisée en moine, sous l''abbé Daniel.', '[{"text": "Anastasie fuit la jalousie de Théodora.", "translation": "Elle préfère le désert à la cour."}]'::jsonb, null, '{"id": "eg.d.c14_anastasie", "unitId": "eg.v.c14_anastasie", "word": "Anastasie la patricienne", "translation": "dame de la cour de Justinien devenue ermite à Scété", "partOfSpeech": "person", "collection": "saint", "explanation": "Anastasie est une dame de la cour de Justinien, au VIe siècle. Jalouse, l''impératrice Théodora la poursuit : elle s''enfuit en Égypte. Après la mort de Théodora, elle gagne Scété et vit en ermite, déguisée en moine, sous l''abbé Daniel.", "examples": [{"text": "Anastasie fuit la jalousie de Théodora.", "translation": "Elle préfère le désert à la cour."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_moniale_deguisee', 'eg', 'une moniale déguisée en moine', 'femme qui vit parmi les moines sous des habits d''homme', 'Quelques saintes, comme Marina et Anastasie, ont vécu parmi les moines sous des habits d''homme. Les Synaxaires gardent ces récits, qui disent surtout l''humilité et la fuite de la gloire.', '[{"text": "Marina est une moniale déguisée en moine.", "translation": "Elle vit parmi les moines sous le nom de Marinos."}]'::jsonb, null, '{"id": "eg.d.c14_moniale_deguisee", "unitId": "eg.v.c14_moniale_deguisee", "word": "une moniale déguisée en moine", "translation": "femme qui vit parmi les moines sous des habits d''homme", "partOfSpeech": "concept", "collection": "notion", "explanation": "Quelques saintes, comme Marina et Anastasie, ont vécu parmi les moines sous des habits d''homme. Les Synaxaires gardent ces récits, qui disent surtout l''humilité et la fuite de la gloire.", "examples": [{"text": "Marina est une moniale déguisée en moine.", "translation": "Elle vit parmi les moines sous le nom de Marinos."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_legion_thebaine', 'eg', 'la légion thébaine', 'troupe de soldats chrétiens de Thébaïde, massacrée en Suisse', 'Selon la tradition, la légion thébaine est une troupe de soldats chrétiens de Thébaïde, en Haute-Égypte. Vers 286, elle refuse de sacrifier aux dieux et est massacrée à Agaune, aujourd''hui Saint-Maurice, en Suisse. Les historiens discutent de ce récit.', '[{"text": "La légion thébaine est massacrée à Agaune.", "translation": "Des Égyptiens meurent en Suisse, selon la tradition."}]'::jsonb, null, '{"id": "eg.d.c14_legion_thebaine", "unitId": "eg.v.c14_legion_thebaine", "word": "la légion thébaine", "translation": "troupe de soldats chrétiens de Thébaïde, massacrée en Suisse", "partOfSpeech": "organization", "collection": "saint", "explanation": "Selon la tradition, la légion thébaine est une troupe de soldats chrétiens de Thébaïde, en Haute-Égypte. Vers 286, elle refuse de sacrifier aux dieux et est massacrée à Agaune, aujourd''hui Saint-Maurice, en Suisse. Les historiens discutent de ce récit.", "examples": [{"text": "La légion thébaine est massacrée à Agaune.", "translation": "Des Égyptiens meurent en Suisse, selon la tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_verena', 'eg', 'sainte Verena', 'sainte égyptienne qui soigne les pauvres en Suisse', 'Selon la tradition, Verena est née en Égypte et suit la légion thébaine. Elle s''installe en Suisse, près de Zurzach, où elle soigne les malades et les pauvres. En 1986, une partie de ses reliques arrive en Égypte, et une église du Caire reçoit son nom.', '[{"text": "Verena est représentée avec une cruche et un peigne.", "translation": "Elle soigne les pauvres en Suisse."}]'::jsonb, null, '{"id": "eg.d.c14_verena", "unitId": "eg.v.c14_verena", "word": "sainte Verena", "translation": "sainte égyptienne qui soigne les pauvres en Suisse", "partOfSpeech": "person", "collection": "saint", "explanation": "Selon la tradition, Verena est née en Égypte et suit la légion thébaine. Elle s''installe en Suisse, près de Zurzach, où elle soigne les malades et les pauvres. En 1986, une partie de ses reliques arrive en Égypte, et une église du Caire reçoit son nom.", "examples": [{"text": "Verena est représentée avec une cruche et un peigne.", "translation": "Elle soigne les pauvres en Suisse."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_abraam_ibn_zaraa', 'eg', 'Abraam ibn Zaraa', '62e pape, ancien marchand syrien, vers 975', 'Abraam ibn Zaraa est un riche marchand d''origine syrienne devenu moine, puis 62e pape d''Alexandrie vers 975, sous les Fatimides. Il est connu pour sa générosité envers les pauvres. Selon la tradition, il prie avec Simon et la montagne du Mokattam bouge.', '[{"text": "Abraam ibn Zaraa prie trois jours avec le peuple.", "translation": "Le pape marchand obéit à la Vierge."}]'::jsonb, null, '{"id": "eg.d.c14_abraam_ibn_zaraa", "unitId": "eg.v.c14_abraam_ibn_zaraa", "word": "Abraam ibn Zaraa", "translation": "62e pape, ancien marchand syrien, vers 975", "partOfSpeech": "person", "collection": "pape", "explanation": "Abraam ibn Zaraa est un riche marchand d''origine syrienne devenu moine, puis 62e pape d''Alexandrie vers 975, sous les Fatimides. Il est connu pour sa générosité envers les pauvres. Selon la tradition, il prie avec Simon et la montagne du Mokattam bouge.", "examples": [{"text": "Abraam ibn Zaraa prie trois jours avec le peuple.", "translation": "Le pape marchand obéit à la Vierge."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_simon_tanneur', 'eg', 'Simon le Tanneur', 'saint homme humble et borgne qui prie avec Abraam', 'Simon est un tanneur borgne, connu pour sa vie sainte. Selon la tradition, il s''est arraché un œil pour obéir à l''Évangile (Mt 5, 29). La Vierge le désigne à Abraam : il porte une cruche d''eau. Il prie au Mokattam, et la montagne se soulève.', '[{"text": "Simon le Tanneur porte une cruche d''eau.", "translation": "Le plus humble est choisi pour prier."}]'::jsonb, null, '{"id": "eg.d.c14_simon_tanneur", "unitId": "eg.v.c14_simon_tanneur", "word": "Simon le Tanneur", "translation": "saint homme humble et borgne qui prie avec Abraam", "partOfSpeech": "person", "collection": "saint", "explanation": "Simon est un tanneur borgne, connu pour sa vie sainte. Selon la tradition, il s''est arraché un œil pour obéir à l''Évangile (Mt 5, 29). La Vierge le désigne à Abraam : il porte une cruche d''eau. Il prie au Mokattam, et la montagne se soulève.", "examples": [{"text": "Simon le Tanneur porte une cruche d''eau.", "translation": "Le plus humble est choisi pour prier."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_mokattam', 'eg', 'le Mokattam', 'montagne du Caire, déplacée selon la tradition vers 975', 'Le Mokattam est la montagne du Caire où, selon la tradition, la foi d''Abraam et de Simon déplace la montagne vers 975. Au pied du Mokattam, une immense église taillée dans le rocher porte le nom de Simon le Tanneur.', '[{"text": "Au Mokattam, on prie le Kyrie eleison.", "translation": "La montagne se soulève, selon la tradition."}]'::jsonb, null, '{"id": "eg.d.c14_mokattam", "unitId": "eg.v.c14_mokattam", "word": "le Mokattam", "translation": "montagne du Caire, déplacée selon la tradition vers 975", "partOfSpeech": "place", "collection": "lieu", "explanation": "Le Mokattam est la montagne du Caire où, selon la tradition, la foi d''Abraam et de Simon déplace la montagne vers 975. Au pied du Mokattam, une immense église taillée dans le rocher porte le nom de Simon le Tanneur.", "examples": [{"text": "Au Mokattam, on prie le Kyrie eleison.", "translation": "La montagne se soulève, selon la tradition."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_barsoum', 'eg', 'Barsoum le Nu', 'ermite vêtu d''une peau de chèvre, mort en 1317', 'Barsoum le Nu (1257-1317) donne tous ses biens et vit en ermite près de l''église de Mercure, au Vieux-Caire. Il ne porte qu''une peau de chèvre. Il prie pour des chrétiens emprisonnés, qui sont libérés. Il est enterré au monastère de Shahran.', '[{"text": "Barsoum le Nu ne porte qu''une peau de chèvre.", "translation": "Il a tout donné."}]'::jsonb, null, '{"id": "eg.d.c14_barsoum", "unitId": "eg.v.c14_barsoum", "word": "Barsoum le Nu", "translation": "ermite vêtu d''une peau de chèvre, mort en 1317", "partOfSpeech": "person", "collection": "saint", "explanation": "Barsoum le Nu (1257-1317) donne tous ses biens et vit en ermite près de l''église de Mercure, au Vieux-Caire. Il ne porte qu''une peau de chèvre. Il prie pour des chrétiens emprisonnés, qui sont libérés. Il est enterré au monastère de Shahran.", "examples": [{"text": "Barsoum le Nu ne porte qu''une peau de chèvre.", "translation": "Il a tout donné."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_anba_abraam', 'eg', 'Anba Abraam de Fayoum', 'évêque du Fayoum, ami des pauvres (1829-1914)', 'Né Boulos en 1829, il devient moine, puis higoumène d''El-Muharraq, puis évêque du Fayoum et de Gizeh en 1881. Il donne ses revenus aux pauvres et vit simplement. Il meurt en 1914 et est canonisé en 1964. Les Coptes l''appellent l''ami des pauvres.', '[{"text": "Anba Abraam donne ses revenus aux pauvres.", "translation": "Un évêque qui vit comme un pauvre."}]'::jsonb, null, '{"id": "eg.d.c14_anba_abraam", "unitId": "eg.v.c14_anba_abraam", "word": "Anba Abraam de Fayoum", "translation": "évêque du Fayoum, ami des pauvres (1829-1914)", "partOfSpeech": "person", "collection": "saint", "explanation": "Né Boulos en 1829, il devient moine, puis higoumène d''El-Muharraq, puis évêque du Fayoum et de Gizeh en 1881. Il donne ses revenus aux pauvres et vit simplement. Il meurt en 1914 et est canonisé en 1964. Les Coptes l''appellent l''ami des pauvres.", "examples": [{"text": "Anba Abraam donne ses revenus aux pauvres.", "translation": "Un évêque qui vit comme un pauvre."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_canonisation', 'eg', 'la canonisation', 'proclamation officielle d''un saint par le Saint-Synode', 'La canonisation est la reconnaissance officielle d''un saint par le Saint-Synode, l''assemblée des évêques. Elle vient après la mort, souvent après de longues années de vénération par les fidèles. Anba Abraam est canonisé en 1964.', '[{"text": "Anba Abraam est canonisé en 1964.", "translation": "Le Saint-Synode proclame un saint."}]'::jsonb, null, '{"id": "eg.d.c14_canonisation", "unitId": "eg.v.c14_canonisation", "word": "la canonisation", "translation": "proclamation officielle d''un saint par le Saint-Synode", "partOfSpeech": "concept", "collection": "notion", "explanation": "La canonisation est la reconnaissance officielle d''un saint par le Saint-Synode, l''assemblée des évêques. Elle vient après la mort, souvent après de longues années de vénération par les fidèles. Anba Abraam est canonisé en 1964.", "examples": [{"text": "Anba Abraam est canonisé en 1964.", "translation": "Le Saint-Synode proclame un saint."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_cyrille_iv', 'eg', 'Cyrille IV', '110e pape (1854-1861), père de la réforme', 'Cyrille IV est pape de 1854 à 1861. On l''appelle le père de la réforme : il installe la première imprimerie non gouvernementale d''Égypte, ouvre des écoles modernes, y compris pour les filles, réorganise les biens de l''Église et demande l''égalité de tous les Égyptiens.', '[{"text": "Cyrille IV installe une imprimerie.", "translation": "Le pape du livre et de l''école."}]'::jsonb, null, '{"id": "eg.d.c14_cyrille_iv", "unitId": "eg.v.c14_cyrille_iv", "word": "Cyrille IV", "translation": "110e pape (1854-1861), père de la réforme", "partOfSpeech": "person", "collection": "pape", "explanation": "Cyrille IV est pape de 1854 à 1861. On l''appelle le père de la réforme : il installe la première imprimerie non gouvernementale d''Égypte, ouvre des écoles modernes, y compris pour les filles, réorganise les biens de l''Église et demande l''égalité de tous les Égyptiens.", "examples": [{"text": "Cyrille IV installe une imprimerie.", "translation": "Le pape du livre et de l''école."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_habib_guirguis', 'eg', 'Habib Guirguis', 'archidiacre laïc, fondateur des écoles du dimanche (1876-1951)', 'Habib Guirguis est un laïc, archidiacre. Premier étudiant du séminaire copte du Caire, il en devient le doyen de 1918 à 1951. Dès 1898, il rassemble des enfants le dimanche pour leur enseigner la foi. Il est proclamé saint en 2013.', '[{"text": "Habib Guirguis enseigne les enfants le dimanche.", "translation": "Un laïc fonde les écoles du dimanche."}]'::jsonb, null, '{"id": "eg.d.c14_habib_guirguis", "unitId": "eg.v.c14_habib_guirguis", "word": "Habib Guirguis", "translation": "archidiacre laïc, fondateur des écoles du dimanche (1876-1951)", "partOfSpeech": "person", "collection": "saint", "explanation": "Habib Guirguis est un laïc, archidiacre. Premier étudiant du séminaire copte du Caire, il en devient le doyen de 1918 à 1951. Dès 1898, il rassemble des enfants le dimanche pour leur enseigner la foi. Il est proclamé saint en 2013.", "examples": [{"text": "Habib Guirguis enseigne les enfants le dimanche.", "translation": "Un laïc fonde les écoles du dimanche."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_ecoles_du_dimanche', 'eg', 'les écoles du dimanche', 'catéchèse des enfants et des jeunes, le dimanche', 'Les écoles du dimanche enseignent la foi aux enfants et aux jeunes. L''Église les adopte officiellement en 1918. Elles ont formé des servants, des prêtres, des évêques, et même un pape, Chenouda III.', '[{"text": "Les écoles du dimanche réunissent les enfants.", "translation": "Elles apprennent la foi aux jeunes."}]'::jsonb, null, '{"id": "eg.d.c14_ecoles_du_dimanche", "unitId": "eg.v.c14_ecoles_du_dimanche", "word": "les écoles du dimanche", "translation": "catéchèse des enfants et des jeunes, le dimanche", "partOfSpeech": "concept", "collection": "notion", "explanation": "Les écoles du dimanche enseignent la foi aux enfants et aux jeunes. L''Église les adopte officiellement en 1918. Elles ont formé des servants, des prêtres, des évêques, et même un pape, Chenouda III.", "examples": [{"text": "Les écoles du dimanche réunissent les enfants.", "translation": "Elles apprennent la foi aux jeunes."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_cyrille_vi', 'eg', 'Cyrille VI', '116e pape (1959-1971), moine de prière, saint en 2013', 'Azer Youssef Atta naît en 1902 à Damanhour. Moine à Baramous sous le nom de père Mina, ermite dans un moulin à vent du Vieux-Caire, il est élu en 1959 : c''est le pape Cyrille VI. En 1968, il ramène les reliques de saint Marc. Le Saint-Synode le proclame saint en 2013.', '[{"text": "Cyrille VI prie dans un moulin avant d''être pape.", "translation": "Le moine de prière devient pape."}]'::jsonb, null, '{"id": "eg.d.c14_cyrille_vi", "unitId": "eg.v.c14_cyrille_vi", "word": "Cyrille VI", "translation": "116e pape (1959-1971), moine de prière, saint en 2013", "partOfSpeech": "person", "collection": "pape", "explanation": "Azer Youssef Atta naît en 1902 à Damanhour. Moine à Baramous sous le nom de père Mina, ermite dans un moulin à vent du Vieux-Caire, il est élu en 1959 : c''est le pape Cyrille VI. En 1968, il ramène les reliques de saint Marc. Le Saint-Synode le proclame saint en 2013.", "examples": [{"text": "Cyrille VI prie dans un moulin avant d''être pape.", "translation": "Le moine de prière devient pape."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_moulin', 'eg', 'le moulin à vent du Vieux-Caire', 'ermitage de Cyrille VI avant son élection', 'Avant d''être pape, le futur Cyrille VI vit en ermite dans un moulin à vent désaffecté du Vieux-Caire, devenu une église. Il y prie et célèbre la messe.', '[{"text": "Le père Mina célèbre la messe dans un moulin à vent.", "translation": "Un moulin devient un lieu de prière."}]'::jsonb, null, '{"id": "eg.d.c14_moulin", "unitId": "eg.v.c14_moulin", "word": "le moulin à vent du Vieux-Caire", "translation": "ermitage de Cyrille VI avant son élection", "partOfSpeech": "place", "collection": "lieu", "explanation": "Avant d''être pape, le futur Cyrille VI vit en ermite dans un moulin à vent désaffecté du Vieux-Caire, devenu une église. Il y prie et célèbre la messe.", "examples": [{"text": "Le père Mina célèbre la messe dans un moulin à vent.", "translation": "Un moulin devient un lieu de prière."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_martyrs_de_libye', 'eg', 'les 21 martyrs de Libye', '21 hommes tués à Syrte en 2015 pour leur foi', 'Le 15 février 2015, vingt Coptes et un Ghanaïen sont tués sur une plage près de Syrte, en Libye, parce qu''ils refusent de renier le Christ. Le pape Tawadros II les proclame martyrs et saints quelques jours après. Leur fête est le 15 février.', '[{"text": "Les 21 martyrs de Libye sont fêtés le 15 février.", "translation": "Ils ont refusé de renier le Christ."}]'::jsonb, null, '{"id": "eg.d.c14_martyrs_de_libye", "unitId": "eg.v.c14_martyrs_de_libye", "word": "les 21 martyrs de Libye", "translation": "21 hommes tués à Syrte en 2015 pour leur foi", "partOfSpeech": "person", "collection": "saint", "explanation": "Le 15 février 2015, vingt Coptes et un Ghanaïen sont tués sur une plage près de Syrte, en Libye, parce qu''ils refusent de renier le Christ. Le pape Tawadros II les proclame martyrs et saints quelques jours après. Leur fête est le 15 février.", "examples": [{"text": "Les 21 martyrs de Libye sont fêtés le 15 février.", "translation": "Ils ont refusé de renier le Christ."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_matthieu', 'eg', 'Matthieu, le 21e martyr', 'le Ghanaïen tué avec les 20 Coptes', 'Matthieu Ayariga, un Ghanaïen, est tué avec les vingt Coptes. Il n''est pas copte, mais l''Église le compte parmi les 21 martyrs : il a refusé lui aussi de renier le Christ.', '[{"text": "Matthieu est le 21e martyr.", "translation": "Un non-copte compté parmi eux."}]'::jsonb, null, '{"id": "eg.d.c14_matthieu", "unitId": "eg.v.c14_matthieu", "word": "Matthieu, le 21e martyr", "translation": "le Ghanaïen tué avec les 20 Coptes", "partOfSpeech": "person", "collection": "saint", "explanation": "Matthieu Ayariga, un Ghanaïen, est tué avec les vingt Coptes. Il n''est pas copte, mais l''Église le compte parmi les 21 martyrs : il a refusé lui aussi de renier le Christ.", "examples": [{"text": "Matthieu est le 21e martyr.", "translation": "Un non-copte compté parmi eux."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_al_our', 'eg', 'Al-Our', 'village de Moyenne-Égypte où reposent les 21 martyrs', 'Al-Our est un village de Moyenne-Égypte. Treize des martyrs en viennent. Leurs reliques, ramenées en 2018, reposent dans l''église des Martyrs de la foi et de la patrie.', '[{"text": "Treize des martyrs viennent d''Al-Our.", "translation": "Le village garde leurs reliques."}]'::jsonb, null, '{"id": "eg.d.c14_al_our", "unitId": "eg.v.c14_al_our", "word": "Al-Our", "translation": "village de Moyenne-Égypte où reposent les 21 martyrs", "partOfSpeech": "place", "collection": "lieu", "explanation": "Al-Our est un village de Moyenne-Égypte. Treize des martyrs en viennent. Leurs reliques, ramenées en 2018, reposent dans l''église des Martyrs de la foi et de la patrie.", "examples": [{"text": "Treize des martyrs viennent d''Al-Our.", "translation": "Le village garde leurs reliques."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_reliques', 'eg', 'les reliques', 'restes d''un saint, vénérés par les fidèles', 'Les reliques sont les restes d''un saint, ou de ce qu''il a touché. On les vénère sans les adorer, car on n''adore que Dieu. Marc repose à l''Abbassiya, Mina au Maryût, Barbara au Vieux-Caire.', '[{"text": "Les reliques de saint Mina sont au Maryût.", "translation": "On vénère, on n''adore pas."}]'::jsonb, null, '{"id": "eg.d.c14_reliques", "unitId": "eg.v.c14_reliques", "word": "les reliques", "translation": "restes d''un saint, vénérés par les fidèles", "partOfSpeech": "concept", "collection": "objet", "explanation": "Les reliques sont les restes d''un saint, ou de ce qu''il a touché. On les vénère sans les adorer, car on n''adore que Dieu. Marc repose à l''Abbassiya, Mina au Maryût, Barbara au Vieux-Caire.", "examples": [{"text": "Les reliques de saint Mina sont au Maryût.", "translation": "On vénère, on n''adore pas."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_saint_patron', 'eg', 'un saint patron', 'saint dont une église ou une personne porte le nom', 'Un saint patron est le saint dont une église, un monastère ou une personne porte le nom. On le prie en particulier, comme un ami dans le ciel.', '[{"text": "Saint Georges est le saint patron de cette église.", "translation": "L''église porte son nom."}]'::jsonb, null, '{"id": "eg.d.c14_saint_patron", "unitId": "eg.v.c14_saint_patron", "word": "un saint patron", "translation": "saint dont une église ou une personne porte le nom", "partOfSpeech": "concept", "collection": "notion", "explanation": "Un saint patron est le saint dont une église, un monastère ou une personne porte le nom. On le prie en particulier, comme un ami dans le ciel.", "examples": [{"text": "Saint Georges est le saint patron de cette église.", "translation": "L''église porte son nom."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.c14_communion_des_saints', 'eg', 'la communion des saints', 'l''Église du ciel et de la terre unies dans la prière', 'La communion des saints est l''union de tous les croyants, du ciel et de la terre, dans la prière et l''amour du Christ. Les saints sont nos modèles et nos intercesseurs.', '[{"text": "Dans la communion des saints, nous prions avec eux.", "translation": "Le ciel et la terre ne font qu''une Église."}]'::jsonb, null, '{"id": "eg.d.c14_communion_des_saints", "unitId": "eg.v.c14_communion_des_saints", "word": "la communion des saints", "translation": "l''Église du ciel et de la terre unies dans la prière", "partOfSpeech": "concept", "collection": "notion", "explanation": "La communion des saints est l''union de tous les croyants, du ciel et de la terre, dans la prière et l''amour du Christ. Les saints sont nos modèles et nos intercesseurs.", "examples": [{"text": "Dans la communion des saints, nous prions avec eux.", "translation": "Le ciel et la terre ne font qu''une Église."}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_nouti', 'eg', 'ⲛⲟⲩϯ', 'dieu (mot égyptien)', 'Mot égyptien très ancien pour « dieu ». Avec l''article, il donne Ⲫ̀ⲛⲟⲩϯ, Dieu. Tu l''entends dans presque toutes les prières, le plus souvent avec l''article.', '[{"text": "ⲛⲟⲩϯ", "translation": "un dieu"}, {"text": "ⲡⲁⲛⲟⲩϯ", "translation": "mon Dieu"}]'::jsonb, null, '{"id": "eg.d.cop_nouti", "unitId": "eg.v.cop_nouti", "word": "ⲛⲟⲩϯ", "translation": "dieu (mot égyptien)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Mot égyptien très ancien pour « dieu ». Avec l''article, il donne Ⲫ̀ⲛⲟⲩϯ, Dieu. Tu l''entends dans presque toutes les prières, le plus souvent avec l''article.", "examples": [{"text": "ⲛⲟⲩϯ", "translation": "un dieu"}, {"text": "ⲡⲁⲛⲟⲩϯ", "translation": "mon Dieu"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_ran', 'eg', 'ⲣⲁⲛ', 'nom (mot égyptien)', 'Mot égyptien pour « nom ». On le retrouve dans ⲫ̀ⲣⲁⲛ, « le nom ». C''est le « nom » de « au nom du Père ».', '[{"text": "ⲣⲁⲛ", "translation": "un nom"}, {"text": "ⲡⲉⲕⲣⲁⲛ", "translation": "ton nom"}]'::jsonb, null, '{"id": "eg.d.cop_ran", "unitId": "eg.v.cop_ran", "word": "ⲣⲁⲛ", "translation": "nom (mot égyptien)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Mot égyptien pour « nom ». On le retrouve dans ⲫ̀ⲣⲁⲛ, « le nom ». C''est le « nom » de « au nom du Père ».", "examples": [{"text": "ⲣⲁⲛ", "translation": "un nom"}, {"text": "ⲡⲉⲕⲣⲁⲛ", "translation": "ton nom"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_iot', 'eg', 'ⲓⲱⲧ', 'père (mot égyptien)', 'Mot égyptien pour « père ». Avec l''article : Ⲫ̀ⲓⲱⲧ, le Père. Il n''a aucune lettre spéciale, mais c''est un mot égyptien très ancien.', '[{"text": "ⲓⲱⲧ", "translation": "père"}, {"text": "ⲡⲉⲛⲓⲱⲧ", "translation": "notre père"}]'::jsonb, null, '{"id": "eg.d.cop_iot", "unitId": "eg.v.cop_iot", "word": "ⲓⲱⲧ", "translation": "père (mot égyptien)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Mot égyptien pour « père ». Avec l''article : Ⲫ̀ⲓⲱⲧ, le Père. Il n''a aucune lettre spéciale, mais c''est un mot égyptien très ancien.", "examples": [{"text": "ⲓⲱⲧ", "translation": "père"}, {"text": "ⲡⲉⲛⲓⲱⲧ", "translation": "notre père"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_shiri', 'eg', 'ϣⲏⲣⲓ', 'fils (mot égyptien)', 'Mot égyptien pour « fils » ; le ϣ est une lettre venue du démotique. Avec l''article : Ⲡ̀ϣⲏⲣⲓ, le Fils. Sa lettre spéciale ϣ est un indice : c''est un mot égyptien.', '[{"text": "ϣⲏⲣⲓ", "translation": "un fils"}, {"text": "Ⲡ̀ϣⲏⲣⲓ", "translation": "le Fils"}]'::jsonb, null, '{"id": "eg.d.cop_shiri", "unitId": "eg.v.cop_shiri", "word": "ϣⲏⲣⲓ", "translation": "fils (mot égyptien)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Mot égyptien pour « fils » ; le ϣ est une lettre venue du démotique. Avec l''article : Ⲡ̀ϣⲏⲣⲓ, le Fils. Sa lettre spéciale ϣ est un indice : c''est un mot égyptien.", "examples": [{"text": "ϣⲏⲣⲓ", "translation": "un fils"}, {"text": "Ⲡ̀ϣⲏⲣⲓ", "translation": "le Fils"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_angelos', 'eg', 'ⲁⲅⲅⲉⲗⲟⲥ', 'ange (du grec : messager)', 'Mot grec : le messager de Dieu. Au pluriel avec l''article : ⲛⲓⲁⲅⲅⲉⲗⲟⲥ. Le français « ange » vient de ce mot grec.', '[{"text": "ⲁⲅⲅⲉⲗⲟⲥ", "translation": "un ange, un messager"}, {"text": "ⲛⲓⲁⲅⲅⲉⲗⲟⲥ", "translation": "les anges"}]'::jsonb, null, '{"id": "eg.d.cop_angelos", "unitId": "eg.v.cop_angelos", "word": "ⲁⲅⲅⲉⲗⲟⲥ", "translation": "ange (du grec : messager)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Mot grec : le messager de Dieu. Au pluriel avec l''article : ⲛⲓⲁⲅⲅⲉⲗⲟⲥ. Le français « ange » vient de ce mot grec.", "examples": [{"text": "ⲁⲅⲅⲉⲗⲟⲥ", "translation": "un ange, un messager"}, {"text": "ⲛⲓⲁⲅⲅⲉⲗⲟⲥ", "translation": "les anges"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_euangelion', 'eg', 'ⲉⲩⲁⲅⲅⲉⲗⲓⲟⲛ', 'évangile, bonne nouvelle (mot grec)', 'Mot grec formé de « bonne » et « annonce » : la bonne nouvelle. Le français « évangile » vient de ce mot grec.', '[{"text": "ⲉⲩⲁⲅⲅⲉⲗⲓⲟⲛ", "translation": "la bonne nouvelle"}, {"text": "ⲡⲓⲉⲩⲁⲅⲅⲉⲗⲓⲟⲛ", "translation": "l''Évangile"}]'::jsonb, null, '{"id": "eg.d.cop_euangelion", "unitId": "eg.v.cop_euangelion", "word": "ⲉⲩⲁⲅⲅⲉⲗⲓⲟⲛ", "translation": "évangile, bonne nouvelle (mot grec)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Mot grec formé de « bonne » et « annonce » : la bonne nouvelle. Le français « évangile » vient de ce mot grec.", "examples": [{"text": "ⲉⲩⲁⲅⲅⲉⲗⲓⲟⲛ", "translation": "la bonne nouvelle"}, {"text": "ⲡⲓⲉⲩⲁⲅⲅⲉⲗⲓⲟⲛ", "translation": "l''Évangile"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_ekklesia', 'eg', 'ⲉⲕⲕⲗⲏⲥⲓⲁ', 'église (du grec : assemblée)', 'Mot grec : l''assemblée des fidèles, puis l''Église. Avec l''article : ϯⲉⲕⲕⲗⲏⲥⲓⲁ. Le français « église » vient de ce mot grec.', '[{"text": "ϯⲉⲕⲕⲗⲏⲥⲓⲁ", "translation": "l''Église"}, {"text": "ⲉⲕⲕⲗⲏⲥⲓⲁ", "translation": "église, assemblée"}]'::jsonb, null, '{"id": "eg.d.cop_ekklesia", "unitId": "eg.v.cop_ekklesia", "word": "ⲉⲕⲕⲗⲏⲥⲓⲁ", "translation": "église (du grec : assemblée)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Mot grec : l''assemblée des fidèles, puis l''Église. Avec l''article : ϯⲉⲕⲕⲗⲏⲥⲓⲁ. Le français « église » vient de ce mot grec.", "examples": [{"text": "ϯⲉⲕⲕⲗⲏⲥⲓⲁ", "translation": "l''Église"}, {"text": "ⲉⲕⲕⲗⲏⲥⲓⲁ", "translation": "église, assemblée"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_parthenos', 'eg', 'ⲡⲁⲣⲑⲉⲛⲟⲥ', 'vierge (mot grec)', 'Mot grec ; avec l''article, ϯⲡⲁⲣⲑⲉⲛⲟⲥ désigne la Vierge Marie. Il est féminin, c''est pourquoi on dit ϯⲡⲁⲣⲑⲉⲛⲟⲥ.', '[{"text": "ⲡⲁⲣⲑⲉⲛⲟⲥ", "translation": "une vierge"}, {"text": "ϯⲡⲁⲣⲑⲉⲛⲟⲥ", "translation": "la Vierge"}]'::jsonb, null, '{"id": "eg.d.cop_parthenos", "unitId": "eg.v.cop_parthenos", "word": "ⲡⲁⲣⲑⲉⲛⲟⲥ", "translation": "vierge (mot grec)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Mot grec ; avec l''article, ϯⲡⲁⲣⲑⲉⲛⲟⲥ désigne la Vierge Marie. Il est féminin, c''est pourquoi on dit ϯⲡⲁⲣⲑⲉⲛⲟⲥ.", "examples": [{"text": "ⲡⲁⲣⲑⲉⲛⲟⲥ", "translation": "une vierge"}, {"text": "ϯⲡⲁⲣⲑⲉⲛⲟⲥ", "translation": "la Vierge"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_jinkim', 'eg', 'ϫⲓⲛⲕⲓⲙ', 'la jinkim : « mouvement », le trait sur la lettre', 'Le nom du petit trait qui guide la lecture. Il vient d''un mot copte qui veut dire « mouvement ». Elle ne change ni la lettre ni le sens du mot.', '[{"text": "ϫⲓⲛⲕⲓⲙ", "translation": "le signe qui marque une syllabe"}, {"text": "Ⲫ̀ⲛⲟⲩϯ", "translation": "un mot où la jinkim est sur le premier ⲫ"}]'::jsonb, null, '{"id": "eg.d.cop_jinkim", "unitId": "eg.v.cop_jinkim", "word": "ϫⲓⲛⲕⲓⲙ", "translation": "la jinkim : « mouvement », le trait sur la lettre", "partOfSpeech": "noun", "collection": "copte", "explanation": "Le nom du petit trait qui guide la lecture. Il vient d''un mot copte qui veut dire « mouvement ». Elle ne change ni la lettre ni le sens du mot.", "examples": [{"text": "ϫⲓⲛⲕⲓⲙ", "translation": "le signe qui marque une syllabe"}, {"text": "Ⲫ̀ⲛⲟⲩϯ", "translation": "un mot où la jinkim est sur le premier ⲫ"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_nte', 'eg', 'ⲛ̀ⲧⲉ', 'de (appartenance)', 'Petit mot qui relie deux noms : « le roi de la paix ». Il se lit « ente ». La jinkim sur le ⲛ̀ ajoute un petit « e » devant.', '[{"text": "ⲡⲓⲟⲩⲣⲟ ⲛ̀ⲧⲉ ϯⲓ̀ⲣⲏⲛⲏ", "translation": "le roi de la paix"}, {"text": "ϯⲉⲕⲕⲗⲏⲥⲓⲁ ⲛ̀ⲧⲉ Ⲫ̀ⲛⲟⲩϯ", "translation": "l''Église de Dieu"}]'::jsonb, null, '{"id": "eg.d.cop_nte", "unitId": "eg.v.cop_nte", "word": "ⲛ̀ⲧⲉ", "translation": "de (appartenance)", "partOfSpeech": "preposition", "collection": "copte", "explanation": "Petit mot qui relie deux noms : « le roi de la paix ». Il se lit « ente ». La jinkim sur le ⲛ̀ ajoute un petit « e » devant.", "examples": [{"text": "ⲡⲓⲟⲩⲣⲟ ⲛ̀ⲧⲉ ϯⲓ̀ⲣⲏⲛⲏ", "translation": "le roi de la paix"}, {"text": "ϯⲉⲕⲕⲗⲏⲥⲓⲁ ⲛ̀ⲧⲉ Ⲫ̀ⲛⲟⲩϯ", "translation": "l''Église de Dieu"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_evol', 'eg', 'ⲉ̀ⲃⲟⲗ', 'dehors, hors de', 'Mot très fréquent, souvent derrière un verbe. Avec ϧⲉⲛ, il veut dire « hors de, issu de ». Il se lit « evol ». La jinkim sur le ⲉ̀ le fait lire à part.', '[{"text": "ⲉ̀ⲃⲟⲗ", "translation": "dehors"}, {"text": "ⲉ̀ⲃⲟⲗ ϧⲉⲛ", "translation": "hors de, à partir de"}]'::jsonb, null, '{"id": "eg.d.cop_evol", "unitId": "eg.v.cop_evol", "word": "ⲉ̀ⲃⲟⲗ", "translation": "dehors, hors de", "partOfSpeech": "adverb", "collection": "copte", "explanation": "Mot très fréquent, souvent derrière un verbe. Avec ϧⲉⲛ, il veut dire « hors de, issu de ». Il se lit « evol ». La jinkim sur le ⲉ̀ le fait lire à part.", "examples": [{"text": "ⲉ̀ⲃⲟⲗ", "translation": "dehors"}, {"text": "ⲉ̀ⲃⲟⲗ ϧⲉⲛ", "translation": "hors de, à partir de"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_agape', 'eg', 'ⲁ̀ⲅⲁⲡⲏ', 'amour (mot grec : agapè)', 'Mot grec pour l''amour de Dieu et des frères. Avec l''article : ϯⲁ̀ⲅⲁⲡⲏ. Le ⲁ̀ avec sa jinkim se lit à part : « ti-agapi ».', '[{"text": "ϯⲁ̀ⲅⲁⲡⲏ", "translation": "l''amour"}, {"text": "ⲁ̀ⲅⲁⲡⲏ", "translation": "amour"}]'::jsonb, null, '{"id": "eg.d.cop_agape", "unitId": "eg.v.cop_agape", "word": "ⲁ̀ⲅⲁⲡⲏ", "translation": "amour (mot grec : agapè)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Mot grec pour l''amour de Dieu et des frères. Avec l''article : ϯⲁ̀ⲅⲁⲡⲏ. Le ⲁ̀ avec sa jinkim se lit à part : « ti-agapi ».", "examples": [{"text": "ϯⲁ̀ⲅⲁⲡⲏ", "translation": "l''amour"}, {"text": "ⲁ̀ⲅⲁⲡⲏ", "translation": "amour"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_iesous', 'eg', 'Ⲓⲏⲥⲟⲩⲥ (ⲓ̅ⲏ̅ⲥ̅)', 'Jésus (nom sacré)', 'Le nom de Jésus, dont l''abréviation est ⲓ̅ⲏ̅ⲥ̅. Le nom veut dire « Dieu sauve ». Sur une icône, tu le lis sous la forme ⲓ̅ⲏ̅ⲥ̅.', '[{"text": "ⲓ̅ⲏ̅ⲥ̅", "translation": "Jésus, en abrégé"}, {"text": "Ⲡⲉⲛϭⲟⲓⲥ Ⲓⲏⲥⲟⲩⲥ Ⲡⲓⲭ̀ⲣⲓⲥⲧⲟⲥ", "translation": "Notre Seigneur Jésus-Christ"}]'::jsonb, null, '{"id": "eg.d.cop_iesous", "unitId": "eg.v.cop_iesous", "word": "Ⲓⲏⲥⲟⲩⲥ (ⲓ̅ⲏ̅ⲥ̅)", "translation": "Jésus (nom sacré)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Le nom de Jésus, dont l''abréviation est ⲓ̅ⲏ̅ⲥ̅. Le nom veut dire « Dieu sauve ». Sur une icône, tu le lis sous la forme ⲓ̅ⲏ̅ⲥ̅.", "examples": [{"text": "ⲓ̅ⲏ̅ⲥ̅", "translation": "Jésus, en abrégé"}, {"text": "Ⲡⲉⲛϭⲟⲓⲥ Ⲓⲏⲥⲟⲩⲥ Ⲡⲓⲭ̀ⲣⲓⲥⲧⲟⲥ", "translation": "Notre Seigneur Jésus-Christ"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_khristos', 'eg', 'Ⲡⲓⲭ̀ⲣⲓⲥⲧⲟⲥ (ⲭ̅ⲥ̅)', 'le Christ, « l''oint » (nom sacré)', 'Titre de Jésus, mot grec qui veut dire « l''oint ». Son abréviation est ⲭ̅ⲥ̅. Il fait partie des noms sacrés que l''on abrège depuis le IIe siècle.', '[{"text": "ⲭ̅ⲥ̅", "translation": "le Christ, en abrégé"}, {"text": "Ⲓⲏⲥⲟⲩⲥ Ⲡⲓⲭ̀ⲣⲓⲥⲧⲟⲥ", "translation": "Jésus-Christ"}]'::jsonb, null, '{"id": "eg.d.cop_khristos", "unitId": "eg.v.cop_khristos", "word": "Ⲡⲓⲭ̀ⲣⲓⲥⲧⲟⲥ (ⲭ̅ⲥ̅)", "translation": "le Christ, « l''oint » (nom sacré)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Titre de Jésus, mot grec qui veut dire « l''oint ». Son abréviation est ⲭ̅ⲥ̅. Il fait partie des noms sacrés que l''on abrège depuis le IIe siècle.", "examples": [{"text": "ⲭ̅ⲥ̅", "translation": "le Christ, en abrégé"}, {"text": "Ⲓⲏⲥⲟⲩⲥ Ⲡⲓⲭ̀ⲣⲓⲥⲧⲟⲥ", "translation": "Jésus-Christ"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_pchois', 'eg', 'Ⲡϭⲟⲓⲥ (ⲡ̅ⲟ̅ⲥ̅)', 'le Seigneur (nom sacré)', 'Mot copte : ⲡ (le) + ϭⲟⲓⲥ (seigneur). Son abréviation est ⲡ̅ⲟ̅ⲥ̅. Tu l''entends dans « Ⲡⲉⲛϭⲟⲓⲥ Ⲓⲏⲥⲟⲩⲥ Ⲡⲓⲭ̀ⲣⲓⲥⲧⲟⲥ », notre Seigneur Jésus-Christ.', '[{"text": "Ⲡϭⲟⲓⲥ", "translation": "le Seigneur"}, {"text": "ⲡⲉⲛϭⲟⲓⲥ", "translation": "notre Seigneur"}]'::jsonb, null, '{"id": "eg.d.cop_pchois", "unitId": "eg.v.cop_pchois", "word": "Ⲡϭⲟⲓⲥ (ⲡ̅ⲟ̅ⲥ̅)", "translation": "le Seigneur (nom sacré)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Mot copte : ⲡ (le) + ϭⲟⲓⲥ (seigneur). Son abréviation est ⲡ̅ⲟ̅ⲥ̅. Tu l''entends dans « Ⲡⲉⲛϭⲟⲓⲥ Ⲓⲏⲥⲟⲩⲥ Ⲡⲓⲭ̀ⲣⲓⲥⲧⲟⲥ », notre Seigneur Jésus-Christ.", "examples": [{"text": "Ⲡϭⲟⲓⲥ", "translation": "le Seigneur"}, {"text": "ⲡⲉⲛϭⲟⲓⲥ", "translation": "notre Seigneur"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_phnouti', 'eg', 'Ⲫ̀ⲛⲟⲩϯ (ⲫ̅ϯ̅)', 'Dieu (nom sacré)', 'Ⲫ̀ⲛⲟⲩϯ est ⲛⲟⲩϯ (dieu) avec l''article : « le Dieu », c''est-à-dire Dieu. Son abréviation est ⲫ̅ϯ̅. Il se lit « efnouti ». Sous la surligne, tu retrouves le mot égyptien ⲛⲟⲩϯ.', '[{"text": "Ⲫ̀ⲛⲟⲩϯ", "translation": "Dieu"}, {"text": "ⲡⲁⲛⲟⲩϯ", "translation": "mon Dieu"}]'::jsonb, null, '{"id": "eg.d.cop_phnouti", "unitId": "eg.v.cop_phnouti", "word": "Ⲫ̀ⲛⲟⲩϯ (ⲫ̅ϯ̅)", "translation": "Dieu (nom sacré)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Ⲫ̀ⲛⲟⲩϯ est ⲛⲟⲩϯ (dieu) avec l''article : « le Dieu », c''est-à-dire Dieu. Son abréviation est ⲫ̅ϯ̅. Il se lit « efnouti ». Sous la surligne, tu retrouves le mot égyptien ⲛⲟⲩϯ.", "examples": [{"text": "Ⲫ̀ⲛⲟⲩϯ", "translation": "Dieu"}, {"text": "ⲡⲁⲛⲟⲩϯ", "translation": "mon Dieu"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_pi', 'eg', 'ⲡⲓ', 'le (article masculin)', 'Article défini masculin, collé au nom. Détache-le pour retrouver le nom caché derrière.', '[{"text": "ⲡⲓⲁⲅⲅⲉⲗⲟⲥ", "translation": "l''ange"}, {"text": "ⲡⲓⲉⲩⲁⲅⲅⲉⲗⲓⲟⲛ", "translation": "l''Évangile"}]'::jsonb, null, '{"id": "eg.d.cop_pi", "unitId": "eg.v.cop_pi", "word": "ⲡⲓ", "translation": "le (article masculin)", "partOfSpeech": "article", "collection": "copte", "explanation": "Article défini masculin, collé au nom. Détache-le pour retrouver le nom caché derrière.", "examples": [{"text": "ⲡⲓⲁⲅⲅⲉⲗⲟⲥ", "translation": "l''ange"}, {"text": "ⲡⲓⲉⲩⲁⲅⲅⲉⲗⲓⲟⲛ", "translation": "l''Évangile"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_ti', 'eg', 'ϯ', 'la (article féminin)', 'Article défini féminin ; il se lit « ti ». Ne le confonds pas avec le ϯ- « je » que tu verras devant un verbe.', '[{"text": "ϯⲉⲕⲕⲗⲏⲥⲓⲁ", "translation": "l''Église"}, {"text": "ϯⲡⲁⲣⲑⲉⲛⲟⲥ", "translation": "la Vierge"}]'::jsonb, null, '{"id": "eg.d.cop_ti", "unitId": "eg.v.cop_ti", "word": "ϯ", "translation": "la (article féminin)", "partOfSpeech": "article", "collection": "copte", "explanation": "Article défini féminin ; il se lit « ti ». Ne le confonds pas avec le ϯ- « je » que tu verras devant un verbe.", "examples": [{"text": "ϯⲉⲕⲕⲗⲏⲥⲓⲁ", "translation": "l''Église"}, {"text": "ϯⲡⲁⲣⲑⲉⲛⲟⲥ", "translation": "la Vierge"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_ni', 'eg', 'ⲛⲓ', 'les (article pluriel)', 'Article défini pluriel, pour le masculin et le féminin. Il sert aussi bien pour des noms masculins que féminins.', '[{"text": "ⲛⲓⲁⲅⲅⲉⲗⲟⲥ", "translation": "les anges"}, {"text": "ⲛⲓⲙⲁⲣⲧⲩⲣⲟⲥ", "translation": "les martyrs"}]'::jsonb, null, '{"id": "eg.d.cop_ni", "unitId": "eg.v.cop_ni", "word": "ⲛⲓ", "translation": "les (article pluriel)", "partOfSpeech": "article", "collection": "copte", "explanation": "Article défini pluriel, pour le masculin et le féminin. Il sert aussi bien pour des noms masculins que féminins.", "examples": [{"text": "ⲛⲓⲁⲅⲅⲉⲗⲟⲥ", "translation": "les anges"}, {"text": "ⲛⲓⲙⲁⲣⲧⲩⲣⲟⲥ", "translation": "les martyrs"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_ou', 'eg', 'ⲟⲩ', 'un, une (article indéfini)', 'Article indéfini singulier, le même au masculin et au féminin. Il se colle au nom : ⲟⲩⲛⲟⲩϯ, un dieu.', '[{"text": "ⲟⲩⲁⲅⲅⲉⲗⲟⲥ", "translation": "un ange"}, {"text": "ⲟⲩⲛⲟⲩϯ", "translation": "un Dieu"}]'::jsonb, null, '{"id": "eg.d.cop_ou", "unitId": "eg.v.cop_ou", "word": "ⲟⲩ", "translation": "un, une (article indéfini)", "partOfSpeech": "article", "collection": "copte", "explanation": "Article indéfini singulier, le même au masculin et au féminin. Il se colle au nom : ⲟⲩⲛⲟⲩϯ, un dieu.", "examples": [{"text": "ⲟⲩⲁⲅⲅⲉⲗⲟⲥ", "translation": "un ange"}, {"text": "ⲟⲩⲛⲟⲩϯ", "translation": "un Dieu"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_pa', 'eg', 'ⲡⲁ-', 'mon (devant un nom masculin)', 'Possessif de la 1re personne du singulier ; il remplace l''article. Le possessif remplace l''article : on ne dit jamais ⲡⲁⲫ̀ⲛⲟⲩϯ.', '[{"text": "ⲡⲁⲛⲟⲩϯ", "translation": "mon Dieu"}, {"text": "ⲡⲁⲓⲱⲧ", "translation": "mon père"}]'::jsonb, null, '{"id": "eg.d.cop_pa", "unitId": "eg.v.cop_pa", "word": "ⲡⲁ-", "translation": "mon (devant un nom masculin)", "partOfSpeech": "determiner", "collection": "copte", "explanation": "Possessif de la 1re personne du singulier ; il remplace l''article. Le possessif remplace l''article : on ne dit jamais ⲡⲁⲫ̀ⲛⲟⲩϯ.", "examples": [{"text": "ⲡⲁⲛⲟⲩϯ", "translation": "mon Dieu"}, {"text": "ⲡⲁⲓⲱⲧ", "translation": "mon père"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_pek', 'eg', 'ⲡⲉⲕ-', 'ton (devant un nom masculin)', 'Possessif de la 2e personne du singulier. Le ⲕ veut dire « toi ».', '[{"text": "ⲡⲉⲕⲣⲁⲛ", "translation": "ton nom"}, {"text": "ⲡⲉⲕⲓⲱⲧ", "translation": "ton père"}]'::jsonb, null, '{"id": "eg.d.cop_pek", "unitId": "eg.v.cop_pek", "word": "ⲡⲉⲕ-", "translation": "ton (devant un nom masculin)", "partOfSpeech": "determiner", "collection": "copte", "explanation": "Possessif de la 2e personne du singulier. Le ⲕ veut dire « toi ».", "examples": [{"text": "ⲡⲉⲕⲣⲁⲛ", "translation": "ton nom"}, {"text": "ⲡⲉⲕⲓⲱⲧ", "translation": "ton père"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_pef', 'eg', 'ⲡⲉϥ-', 'son, à lui (devant un nom masculin)', 'Possessif de la 3e personne : le ϥ veut dire « lui ». Le ϥ veut dire « lui », le même que dans ⲁϥ-.', '[{"text": "ⲡⲉϥⲣⲁⲛ", "translation": "son nom"}, {"text": "ⲡⲉϥⲓⲱⲧ", "translation": "son père"}]'::jsonb, null, '{"id": "eg.d.cop_pef", "unitId": "eg.v.cop_pef", "word": "ⲡⲉϥ-", "translation": "son, à lui (devant un nom masculin)", "partOfSpeech": "determiner", "collection": "copte", "explanation": "Possessif de la 3e personne : le ϥ veut dire « lui ». Le ϥ veut dire « lui », le même que dans ⲁϥ-.", "examples": [{"text": "ⲡⲉϥⲣⲁⲛ", "translation": "son nom"}, {"text": "ⲡⲉϥⲓⲱⲧ", "translation": "son père"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_pen', 'eg', 'ⲡⲉⲛ-', 'notre (devant un nom masculin)', 'Possessif de la 1re personne du pluriel : le ⲛ veut dire « nous ». Très fréquent dans les prières. Le ⲛ veut dire « nous » ; ne le confonds pas avec ⲡⲉⲧⲉⲛ-, « votre ».', '[{"text": "Ⲡⲉⲛⲓⲱⲧ", "translation": "notre Père"}, {"text": "Ⲡⲉⲛϭⲟⲓⲥ", "translation": "notre Seigneur"}]'::jsonb, null, '{"id": "eg.d.cop_pen", "unitId": "eg.v.cop_pen", "word": "ⲡⲉⲛ-", "translation": "notre (devant un nom masculin)", "partOfSpeech": "determiner", "collection": "copte", "explanation": "Possessif de la 1re personne du pluriel : le ⲛ veut dire « nous ». Très fréquent dans les prières. Le ⲛ veut dire « nous » ; ne le confonds pas avec ⲡⲉⲧⲉⲛ-, « votre ».", "examples": [{"text": "Ⲡⲉⲛⲓⲱⲧ", "translation": "notre Père"}, {"text": "Ⲡⲉⲛϭⲟⲓⲥ", "translation": "notre Seigneur"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_nem', 'eg', 'ⲛⲉⲙ', 'et, avec', 'Relie deux noms : Ⲫ̀ⲓⲱⲧ ⲛⲉⲙ Ⲡ̀ϣⲏⲣⲓ, le Père et le Fils. Veut aussi dire « avec ». Il relie des noms, pas des phrases.', '[{"text": "Ⲫ̀ⲓⲱⲧ ⲛⲉⲙ Ⲡ̀ϣⲏⲣⲓ", "translation": "le Père et le Fils"}, {"text": "ⲛⲉⲙ ⲡⲉⲕⲓⲱⲧ", "translation": "avec ton père"}]'::jsonb, null, '{"id": "eg.d.cop_nem", "unitId": "eg.v.cop_nem", "word": "ⲛⲉⲙ", "translation": "et, avec", "partOfSpeech": "conjunction", "collection": "copte", "explanation": "Relie deux noms : Ⲫ̀ⲓⲱⲧ ⲛⲉⲙ Ⲡ̀ϣⲏⲣⲓ, le Père et le Fils. Veut aussi dire « avec ». Il relie des noms, pas des phrases.", "examples": [{"text": "Ⲫ̀ⲓⲱⲧ ⲛⲉⲙ Ⲡ̀ϣⲏⲣⲓ", "translation": "le Père et le Fils"}, {"text": "ⲛⲉⲙ ⲡⲉⲕⲓⲱⲧ", "translation": "avec ton père"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_hen', 'eg', 'ϧⲉⲛ', 'dans, en', 'Préposition du lieu et de la manière. On la trouve dans ϧⲉⲛ ⲫ̀ⲣⲁⲛ, « au nom de ». Ne le confonds pas avec ϩⲓⲧⲉⲛ, « par » : ϧⲉⲛ donne le lieu.', '[{"text": "ϧⲉⲛ ⲫ̀ⲣⲁⲛ", "translation": "dans le nom"}, {"text": "ϧⲉⲛ ϯⲉⲕⲕⲗⲏⲥⲓⲁ", "translation": "dans l''Église"}]'::jsonb, null, '{"id": "eg.d.cop_hen", "unitId": "eg.v.cop_hen", "word": "ϧⲉⲛ", "translation": "dans, en", "partOfSpeech": "preposition", "collection": "copte", "explanation": "Préposition du lieu et de la manière. On la trouve dans ϧⲉⲛ ⲫ̀ⲣⲁⲛ, « au nom de ». Ne le confonds pas avec ϩⲓⲧⲉⲛ, « par » : ϧⲉⲛ donne le lieu.", "examples": [{"text": "ϧⲉⲛ ⲫ̀ⲣⲁⲛ", "translation": "dans le nom"}, {"text": "ϧⲉⲛ ϯⲉⲕⲕⲗⲏⲥⲓⲁ", "translation": "dans l''Église"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_n_de', 'eg', 'ⲛ̀/ⲙ̀', 'de', 'Le petit mot « de » ; il devient ⲙ̀ devant ⲡ, ⲫ, ⲃ, ⲙ. Il devient ⲙ̀ devant ⲡ, ⲫ, ⲃ, ⲙ, comme « en » devient « em » devant p ou b.', '[{"text": "ⲫ̀ⲣⲁⲛ ⲙ̀Ⲫ̀ⲓⲱⲧ", "translation": "le nom du Père"}, {"text": "ⲫ̀ⲣⲁⲛ ⲛ̀ⲛⲓⲁⲅⲅⲉⲗⲟⲥ", "translation": "le nom des anges"}]'::jsonb, null, '{"id": "eg.d.cop_n_de", "unitId": "eg.v.cop_n_de", "word": "ⲛ̀/ⲙ̀", "translation": "de", "partOfSpeech": "preposition", "collection": "copte", "explanation": "Le petit mot « de » ; il devient ⲙ̀ devant ⲡ, ⲫ, ⲃ, ⲙ. Il devient ⲙ̀ devant ⲡ, ⲫ, ⲃ, ⲙ, comme « en » devient « em » devant p ou b.", "examples": [{"text": "ⲫ̀ⲣⲁⲛ ⲙ̀Ⲫ̀ⲓⲱⲧ", "translation": "le nom du Père"}, {"text": "ⲫ̀ⲣⲁⲛ ⲛ̀ⲛⲓⲁⲅⲅⲉⲗⲟⲥ", "translation": "le nom des anges"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_ethouab', 'eg', 'ⲉⲑⲟⲩⲁⲃ', 'saint (placé après le nom)', 'Littéralement « qui est saint, pur ». Il se place après le nom. Le ⲉⲑ- veut dire « qui est ».', '[{"text": "ϯⲉⲕⲕⲗⲏⲥⲓⲁ ⲉⲑⲟⲩⲁⲃ", "translation": "l''Église sainte"}, {"text": "ⲡⲉⲕⲣⲁⲛ ⲉⲑⲟⲩⲁⲃ", "translation": "ton saint nom"}]'::jsonb, null, '{"id": "eg.d.cop_ethouab", "unitId": "eg.v.cop_ethouab", "word": "ⲉⲑⲟⲩⲁⲃ", "translation": "saint (placé après le nom)", "partOfSpeech": "adjective", "collection": "copte", "explanation": "Littéralement « qui est saint, pur ». Il se place après le nom. Le ⲉⲑ- veut dire « qui est ».", "examples": [{"text": "ϯⲉⲕⲕⲗⲏⲥⲓⲁ ⲉⲑⲟⲩⲁⲃ", "translation": "l''Église sainte"}, {"text": "ⲡⲉⲕⲣⲁⲛ ⲉⲑⲟⲩⲁⲃ", "translation": "ton saint nom"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_af', 'eg', 'ⲁϥ-', 'il a (marque du passé)', 'Marque du passé à la 3e personne du masculin : ⲁ (passé) + ϥ (il). Le ⲁ marque le passé et le ϥ dit « il » : tu retrouves ce ϥ dans ⲡⲉϥ-.', '[{"text": "ⲁϥⲧⲱⲛϥ", "translation": "il est ressuscité"}, {"text": "ⲁϥⲧⲱⲛϥ", "translation": "il s''est levé"}]'::jsonb, null, '{"id": "eg.d.cop_af", "unitId": "eg.v.cop_af", "word": "ⲁϥ-", "translation": "il a (marque du passé)", "partOfSpeech": "particle", "collection": "copte", "explanation": "Marque du passé à la 3e personne du masculin : ⲁ (passé) + ϥ (il). Le ⲁ marque le passé et le ϥ dit « il » : tu retrouves ce ϥ dans ⲡⲉϥ-.", "examples": [{"text": "ⲁϥⲧⲱⲛϥ", "translation": "il est ressuscité"}, {"text": "ⲁϥⲧⲱⲛϥ", "translation": "il s''est levé"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_ton', 'eg', 'ⲧⲱⲛ', 'se lever, ressusciter', 'Verbe « se lever », employé pour la résurrection : ⲁϥⲧⲱⲛϥ. Pour « elle s''est levée », on dit ⲁⲥⲧⲱⲛⲥ ; pour « ils se sont levés », ⲁⲩⲧⲱⲛⲟⲩ.', '[{"text": "ⲁϥⲧⲱⲛϥ", "translation": "il est ressuscité"}, {"text": "ⲧⲱⲛ", "translation": "se lever"}]'::jsonb, null, '{"id": "eg.d.cop_ton", "unitId": "eg.v.cop_ton", "word": "ⲧⲱⲛ", "translation": "se lever, ressusciter", "partOfSpeech": "verb", "collection": "copte", "explanation": "Verbe « se lever », employé pour la résurrection : ⲁϥⲧⲱⲛϥ. Pour « elle s''est levée », on dit ⲁⲥⲧⲱⲛⲥ ; pour « ils se sont levés », ⲁⲩⲧⲱⲛⲟⲩ.", "examples": [{"text": "ⲁϥⲧⲱⲛϥ", "translation": "il est ressuscité"}, {"text": "ⲧⲱⲛ", "translation": "se lever"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_alithos', 'eg', 'ⲁ̀ⲗⲏⲑⲱⲥ', 'vraiment (mot grec)', 'Mot grec pour « vraiment ». On le dit à Pâques : ⲁ̀ⲗⲏⲑⲱⲥ ⲁϥⲧⲱⲛϥ. La réponse de l''assemblée au salut de Pâques.', '[{"text": "ⲁ̀ⲗⲏⲑⲱⲥ ⲁϥⲧⲱⲛϥ", "translation": "vraiment, il est ressuscité"}, {"text": "ⲁ̀ⲗⲏⲑⲱⲥ", "translation": "vraiment"}]'::jsonb, null, '{"id": "eg.d.cop_alithos", "unitId": "eg.v.cop_alithos", "word": "ⲁ̀ⲗⲏⲑⲱⲥ", "translation": "vraiment (mot grec)", "partOfSpeech": "adverb", "collection": "copte", "explanation": "Mot grec pour « vraiment ». On le dit à Pâques : ⲁ̀ⲗⲏⲑⲱⲥ ⲁϥⲧⲱⲛϥ. La réponse de l''assemblée au salut de Pâques.", "examples": [{"text": "ⲁ̀ⲗⲏⲑⲱⲥ ⲁϥⲧⲱⲛϥ", "translation": "vraiment, il est ressuscité"}, {"text": "ⲁ̀ⲗⲏⲑⲱⲥ", "translation": "vraiment"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_ti_je', 'eg', 'ϯ-', 'je (devant un verbe, au présent)', 'Devant un verbe, ϯ- veut dire « je ». Devant un nom, ϯ est l''article « la ». Devant un nom, ϯ est l''article « la » : regarde ce qui suit.', '[{"text": "ϯⲛⲁϩϯ", "translation": "je crois"}, {"text": "Ϯⲛⲁϩϯ ϧⲉⲛ ⲟⲩⲛⲟⲩϯ", "translation": "je crois en un Dieu"}]'::jsonb, null, '{"id": "eg.d.cop_ti_je", "unitId": "eg.v.cop_ti_je", "word": "ϯ-", "translation": "je (devant un verbe, au présent)", "partOfSpeech": "pronoun", "collection": "copte", "explanation": "Devant un verbe, ϯ- veut dire « je ». Devant un nom, ϯ est l''article « la ». Devant un nom, ϯ est l''article « la » : regarde ce qui suit.", "examples": [{"text": "ϯⲛⲁϩϯ", "translation": "je crois"}, {"text": "Ϯⲛⲁϩϯ ϧⲉⲛ ⲟⲩⲛⲟⲩϯ", "translation": "je crois en un Dieu"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_nahti', 'eg', 'ⲛⲁϩϯ', 'croire', 'Verbe « croire ». Avec ϯ- : ϯⲛⲁϩϯ, je crois. Les premiers mots du Credo copte : Ϯⲛⲁϩϯ ϧⲉⲛ ⲟⲩⲛⲟⲩϯ.', '[{"text": "ϯⲛⲁϩϯ", "translation": "je crois"}, {"text": "ⲛⲁϩϯ", "translation": "croire"}]'::jsonb, null, '{"id": "eg.d.cop_nahti", "unitId": "eg.v.cop_nahti", "word": "ⲛⲁϩϯ", "translation": "croire", "partOfSpeech": "verb", "collection": "copte", "explanation": "Verbe « croire ». Avec ϯ- : ϯⲛⲁϩϯ, je crois. Les premiers mots du Credo copte : Ϯⲛⲁϩϯ ϧⲉⲛ ⲟⲩⲛⲟⲩϯ.", "examples": [{"text": "ϯⲛⲁϩϯ", "translation": "je crois"}, {"text": "ⲛⲁϩϯ", "translation": "croire"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_smou', 'eg', 'ⲥⲙⲟⲩ', 'bénis ! (impératif)', 'Verbe « bénir », employé seul pour donner l''ordre : bénis ! Le mot ne change pas, qu''on parle à une personne ou à toute l''assemblée.', '[{"text": "ⲥⲙⲟⲩ", "translation": "bénis !"}, {"text": "ⲥⲙⲟⲩ", "translation": "bénissez !"}]'::jsonb, null, '{"id": "eg.d.cop_smou", "unitId": "eg.v.cop_smou", "word": "ⲥⲙⲟⲩ", "translation": "bénis ! (impératif)", "partOfSpeech": "verb", "collection": "copte", "explanation": "Verbe « bénir », employé seul pour donner l''ordre : bénis ! Le mot ne change pas, qu''on parle à une personne ou à toute l''assemblée.", "examples": [{"text": "ⲥⲙⲟⲩ", "translation": "bénis !"}, {"text": "ⲥⲙⲟⲩ", "translation": "bénissez !"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_phiot', 'eg', 'Ⲫ̀ⲓⲱⲧ', 'le Père', 'Première personne de la Trinité. Se lit « efiot ». Il se lit « efiot ».', '[{"text": "Ⲫ̀ⲓⲱⲧ", "translation": "le Père"}, {"text": "ⲫ̀ⲣⲁⲛ ⲙ̀Ⲫ̀ⲓⲱⲧ", "translation": "le nom du Père"}]'::jsonb, null, '{"id": "eg.d.cop_phiot", "unitId": "eg.v.cop_phiot", "word": "Ⲫ̀ⲓⲱⲧ", "translation": "le Père", "partOfSpeech": "noun", "collection": "copte", "explanation": "Première personne de la Trinité. Se lit « efiot ». Il se lit « efiot ».", "examples": [{"text": "Ⲫ̀ⲓⲱⲧ", "translation": "le Père"}, {"text": "ⲫ̀ⲣⲁⲛ ⲙ̀Ⲫ̀ⲓⲱⲧ", "translation": "le nom du Père"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_pshiri', 'eg', 'Ⲡ̀ϣⲏⲣⲓ', 'le Fils', 'Deuxième personne de la Trinité. Se lit « epshiri ». Il se lit « epshiri ».', '[{"text": "Ⲡ̀ϣⲏⲣⲓ", "translation": "le Fils"}, {"text": "Ⲫ̀ⲓⲱⲧ ⲛⲉⲙ Ⲡ̀ϣⲏⲣⲓ", "translation": "le Père et le Fils"}]'::jsonb, null, '{"id": "eg.d.cop_pshiri", "unitId": "eg.v.cop_pshiri", "word": "Ⲡ̀ϣⲏⲣⲓ", "translation": "le Fils", "partOfSpeech": "noun", "collection": "copte", "explanation": "Deuxième personne de la Trinité. Se lit « epshiri ». Il se lit « epshiri ».", "examples": [{"text": "Ⲡ̀ϣⲏⲣⲓ", "translation": "le Fils"}, {"text": "Ⲫ̀ⲓⲱⲧ ⲛⲉⲙ Ⲡ̀ϣⲏⲣⲓ", "translation": "le Père et le Fils"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_pnevma', 'eg', 'Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ', 'l''Esprit (mot grec : souffle)', 'Mot grec pneuma. Avec ⲉⲑⲟⲩⲁⲃ : le Saint-Esprit. La jinkim sur le ⲡ̀ se lit : « pi-epnevma ».', '[{"text": "Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ ⲉⲑⲟⲩⲁⲃ", "translation": "le Saint-Esprit"}, {"text": "Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ", "translation": "l''Esprit"}]'::jsonb, null, '{"id": "eg.d.cop_pnevma", "unitId": "eg.v.cop_pnevma", "word": "Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ", "translation": "l''Esprit (mot grec : souffle)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Mot grec pneuma. Avec ⲉⲑⲟⲩⲁⲃ : le Saint-Esprit. La jinkim sur le ⲡ̀ se lit : « pi-epnevma ».", "examples": [{"text": "Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ ⲉⲑⲟⲩⲁⲃ", "translation": "le Saint-Esprit"}, {"text": "Ⲡⲓⲡ̀ⲛⲉⲩⲙⲁ", "translation": "l''Esprit"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_phran', 'eg', 'ⲫ̀ⲣⲁⲛ', 'le nom', 'ⲫ̀ (le) + ⲣⲁⲛ (nom). On le trouve dans « au nom du Père ». Dans la formule du signe de croix, il est au singulier : un seul nom pour trois personnes.', '[{"text": "ⲫ̀ⲣⲁⲛ", "translation": "le nom"}, {"text": "ⲡⲉⲕⲣⲁⲛ ⲉⲑⲟⲩⲁⲃ", "translation": "ton saint nom"}]'::jsonb, null, '{"id": "eg.d.cop_phran", "unitId": "eg.v.cop_phran", "word": "ⲫ̀ⲣⲁⲛ", "translation": "le nom", "partOfSpeech": "noun", "collection": "copte", "explanation": "ⲫ̀ (le) + ⲣⲁⲛ (nom). On le trouve dans « au nom du Père ». Dans la formule du signe de croix, il est au singulier : un seul nom pour trois personnes.", "examples": [{"text": "ⲫ̀ⲣⲁⲛ", "translation": "le nom"}, {"text": "ⲡⲉⲕⲣⲁⲛ ⲉⲑⲟⲩⲁⲃ", "translation": "ton saint nom"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_trias', 'eg', 'ϯⲧ̀ⲣⲓⲁⲥ', 'la Trinité (mot grec : triade)', 'Mot grec trias. Avec ⲉⲑⲟⲩⲁⲃ : la sainte Trinité. Le ⲧ̀ porte une jinkim parce que deux consonnes se suivent : « ti-etrias ».', '[{"text": "ϯⲧ̀ⲣⲓⲁⲥ", "translation": "la Trinité"}, {"text": "ϯⲧ̀ⲣⲓⲁⲥ ⲉⲑⲟⲩⲁⲃ", "translation": "la sainte Trinité"}]'::jsonb, null, '{"id": "eg.d.cop_trias", "unitId": "eg.v.cop_trias", "word": "ϯⲧ̀ⲣⲓⲁⲥ", "translation": "la Trinité (mot grec : triade)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Mot grec trias. Avec ⲉⲑⲟⲩⲁⲃ : la sainte Trinité. Le ⲧ̀ porte une jinkim parce que deux consonnes se suivent : « ti-etrias ».", "examples": [{"text": "ϯⲧ̀ⲣⲓⲁⲥ", "translation": "la Trinité"}, {"text": "ϯⲧ̀ⲣⲓⲁⲥ ⲉⲑⲟⲩⲁⲃ", "translation": "la sainte Trinité"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_ouro', 'eg', 'ⲟⲩⲣⲟ', 'roi', 'Mot égyptien pour « roi », le titre du pharaon et du Christ. Avec l''article : ⲡⲓⲟⲩⲣⲟ. Il n''a pas besoin d''article pour être reconnu : ⲡⲓⲟⲩⲣⲟ, c''est le roi.', '[{"text": "ⲟⲩⲣⲟ", "translation": "un roi"}, {"text": "ⲡⲓⲟⲩⲣⲟ", "translation": "le roi"}]'::jsonb, null, '{"id": "eg.d.cop_ouro", "unitId": "eg.v.cop_ouro", "word": "ⲟⲩⲣⲟ", "translation": "roi", "partOfSpeech": "noun", "collection": "copte", "explanation": "Mot égyptien pour « roi », le titre du pharaon et du Christ. Avec l''article : ⲡⲓⲟⲩⲣⲟ. Il n''a pas besoin d''article pour être reconnu : ⲡⲓⲟⲩⲣⲟ, c''est le roi.", "examples": [{"text": "ⲟⲩⲣⲟ", "translation": "un roi"}, {"text": "ⲡⲓⲟⲩⲣⲟ", "translation": "le roi"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_pantokrator', 'eg', 'Ⲡⲓⲡⲁⲛⲧⲟⲕⲣⲁⲧⲱⲣ', 'le Tout-Puissant (mot grec)', 'Mot grec : pan (tout) + krátos (puissance), « celui qui tient tout ». Il est formé de pan (tout) et krátos (puissance).', '[{"text": "Ⲡⲓⲡⲁⲛⲧⲟⲕⲣⲁⲧⲱⲣ", "translation": "le Tout-Puissant"}, {"text": "ⲡⲁⲛⲧⲟⲕⲣⲁⲧⲱⲣ", "translation": "tout-puissant, celui qui tient tout"}]'::jsonb, null, '{"id": "eg.d.cop_pantokrator", "unitId": "eg.v.cop_pantokrator", "word": "Ⲡⲓⲡⲁⲛⲧⲟⲕⲣⲁⲧⲱⲣ", "translation": "le Tout-Puissant (mot grec)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Mot grec : pan (tout) + krátos (puissance), « celui qui tient tout ». Il est formé de pan (tout) et krátos (puissance).", "examples": [{"text": "Ⲡⲓⲡⲁⲛⲧⲟⲕⲣⲁⲧⲱⲣ", "translation": "le Tout-Puissant"}, {"text": "ⲡⲁⲛⲧⲟⲕⲣⲁⲧⲱⲣ", "translation": "tout-puissant, celui qui tient tout"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_soter', 'eg', 'ⲥⲱⲧⲏⲣ', 'sauveur (mot grec)', 'Mot grec : celui qui sauve. Ⲡⲉⲛⲥⲱⲧⲏⲣ : notre Sauveur. Jésus veut dire « Dieu sauve » : le Sauveur et Jésus disent la même chose.', '[{"text": "ⲥⲱⲧⲏⲣ", "translation": "sauveur"}, {"text": "Ⲡⲉⲛⲥⲱⲧⲏⲣ", "translation": "notre Sauveur"}]'::jsonb, null, '{"id": "eg.d.cop_soter", "unitId": "eg.v.cop_soter", "word": "ⲥⲱⲧⲏⲣ", "translation": "sauveur (mot grec)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Mot grec : celui qui sauve. Ⲡⲉⲛⲥⲱⲧⲏⲣ : notre Sauveur. Jésus veut dire « Dieu sauve » : le Sauveur et Jésus disent la même chose.", "examples": [{"text": "ⲥⲱⲧⲏⲣ", "translation": "sauveur"}, {"text": "Ⲡⲉⲛⲥⲱⲧⲏⲣ", "translation": "notre Sauveur"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_maria', 'eg', 'Ⲙⲁⲣⲓⲁ', 'Marie', 'Nom de la Vierge Marie, mère du Christ. Avec ϯⲡⲁⲣⲑⲉⲛⲟⲥ, on dit ϯⲡⲁⲣⲑⲉⲛⲟⲥ Ⲙⲁⲣⲓⲁ, la Vierge Marie.', '[{"text": "Ⲙⲁⲣⲓⲁ", "translation": "Marie"}, {"text": "ϯⲡⲁⲣⲑⲉⲛⲟⲥ Ⲙⲁⲣⲓⲁ", "translation": "la Vierge Marie"}]'::jsonb, null, '{"id": "eg.d.cop_maria", "unitId": "eg.v.cop_maria", "word": "Ⲙⲁⲣⲓⲁ", "translation": "Marie", "partOfSpeech": "noun", "collection": "copte", "explanation": "Nom de la Vierge Marie, mère du Christ. Avec ϯⲡⲁⲣⲑⲉⲛⲟⲥ, on dit ϯⲡⲁⲣⲑⲉⲛⲟⲥ Ⲙⲁⲣⲓⲁ, la Vierge Marie.", "examples": [{"text": "Ⲙⲁⲣⲓⲁ", "translation": "Marie"}, {"text": "ϯⲡⲁⲣⲑⲉⲛⲟⲥ Ⲙⲁⲣⲓⲁ", "translation": "la Vierge Marie"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_theotokos', 'eg', 'ϯⲑⲉⲟⲧⲟⲕⲟⲥ', 'la mère de Dieu (mot grec : celle qui enfante Dieu)', 'Titre de la Vierge, formé de ⲑⲉⲟⲥ (Dieu) et ⲧⲟⲕⲟⲥ (enfantement). Ce titre a été proclamé au concile d''Éphèse, en 431, face à Nestorius qui le refusait.', '[{"text": "ϯⲑⲉⲟⲧⲟⲕⲟⲥ", "translation": "la mère de Dieu"}, {"text": "ϯⲑⲉⲟⲧⲟⲕⲟⲥ ⲉⲑⲟⲩⲁⲃ", "translation": "la sainte mère de Dieu"}]'::jsonb, null, '{"id": "eg.d.cop_theotokos", "unitId": "eg.v.cop_theotokos", "word": "ϯⲑⲉⲟⲧⲟⲕⲟⲥ", "translation": "la mère de Dieu (mot grec : celle qui enfante Dieu)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Titre de la Vierge, formé de ⲑⲉⲟⲥ (Dieu) et ⲧⲟⲕⲟⲥ (enfantement). Ce titre a été proclamé au concile d''Éphèse, en 431, face à Nestorius qui le refusait.", "examples": [{"text": "ϯⲑⲉⲟⲧⲟⲕⲟⲥ", "translation": "la mère de Dieu"}, {"text": "ϯⲑⲉⲟⲧⲟⲕⲟⲥ ⲉⲑⲟⲩⲁⲃ", "translation": "la sainte mère de Dieu"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_khere', 'eg', 'ⲭⲉⲣⲉ', 'salut, réjouis-toi (mot grec)', 'Salut grec adressé à Marie par l''ange Gabriel. Le petit ⲱ̀ qui suit veut dire « ô ».', '[{"text": "ⲭⲉⲣⲉ ⲛⲉ ⲱ̀ Ⲙⲁⲣⲓⲁ", "translation": "salut à toi, ô Marie"}, {"text": "ⲭⲉⲣⲉ", "translation": "salut, réjouis-toi"}]'::jsonb, null, '{"id": "eg.d.cop_khere", "unitId": "eg.v.cop_khere", "word": "ⲭⲉⲣⲉ", "translation": "salut, réjouis-toi (mot grec)", "partOfSpeech": "interjection", "collection": "copte", "explanation": "Salut grec adressé à Marie par l''ange Gabriel. Le petit ⲱ̀ qui suit veut dire « ô ».", "examples": [{"text": "ⲭⲉⲣⲉ ⲛⲉ ⲱ̀ Ⲙⲁⲣⲓⲁ", "translation": "salut à toi, ô Marie"}, {"text": "ⲭⲉⲣⲉ", "translation": "salut, réjouis-toi"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_hiten', 'eg', 'ϩⲓⲧⲉⲛ', 'par, au moyen de', 'Donne le moyen ou l''intermédiaire : « par ». Ne le confonds pas avec ϧⲉⲛ, « dans » : ϧⲉⲛ donne le lieu, ϩⲓⲧⲉⲛ le moyen.', '[{"text": "ϩⲓⲧⲉⲛ ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ", "translation": "par les intercessions"}, {"text": "ϩⲓⲧⲉⲛ ⲫ̀ⲣⲁⲛ", "translation": "par le nom"}]'::jsonb, null, '{"id": "eg.d.cop_hiten", "unitId": "eg.v.cop_hiten", "word": "ϩⲓⲧⲉⲛ", "translation": "par, au moyen de", "partOfSpeech": "preposition", "collection": "copte", "explanation": "Donne le moyen ou l''intermédiaire : « par ». Ne le confonds pas avec ϧⲉⲛ, « dans » : ϧⲉⲛ donne le lieu, ϩⲓⲧⲉⲛ le moyen.", "examples": [{"text": "ϩⲓⲧⲉⲛ ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ", "translation": "par les intercessions"}, {"text": "ϩⲓⲧⲉⲛ ⲫ̀ⲣⲁⲛ", "translation": "par le nom"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_martyros', 'eg', 'ⲙⲁⲣⲧⲩⲣⲟⲥ', 'martyr, « témoin » (mot grec)', 'Mot grec : le témoin, celui qui témoigne jusqu''à la mort. Le martyr est celui qui témoigne de sa foi jusqu''à la mort.', '[{"text": "ⲛⲓⲙⲁⲣⲧⲩⲣⲟⲥ", "translation": "les martyrs"}, {"text": "ⲙⲁⲣⲧⲩⲣⲟⲥ", "translation": "martyr, témoin"}]'::jsonb, null, '{"id": "eg.d.cop_martyros", "unitId": "eg.v.cop_martyros", "word": "ⲙⲁⲣⲧⲩⲣⲟⲥ", "translation": "martyr, « témoin » (mot grec)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Mot grec : le témoin, celui qui témoigne jusqu''à la mort. Le martyr est celui qui témoigne de sa foi jusqu''à la mort.", "examples": [{"text": "ⲛⲓⲙⲁⲣⲧⲩⲣⲟⲥ", "translation": "les martyrs"}, {"text": "ⲙⲁⲣⲧⲩⲣⲟⲥ", "translation": "martyr, témoin"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_agios', 'eg', 'ⲁ̀ⲅⲓⲟⲥ', 'saint (mot grec)', 'Mot grec pour « saint ». Avec l''article : ⲡⲓⲁ̀ⲅⲓⲟⲥ, le saint. On l''entend dans le Trisagion. Le copte a aussi son propre mot pour « saint » : ⲉⲑⲟⲩⲁⲃ.', '[{"text": "ⲡⲓⲁ̀ⲅⲓⲟⲥ", "translation": "le saint"}, {"text": "ⲛⲓⲁ̀ⲅⲓⲟⲥ", "translation": "les saints"}]'::jsonb, null, '{"id": "eg.d.cop_agios", "unitId": "eg.v.cop_agios", "word": "ⲁ̀ⲅⲓⲟⲥ", "translation": "saint (mot grec)", "partOfSpeech": "adjective", "collection": "copte", "explanation": "Mot grec pour « saint ». Avec l''article : ⲡⲓⲁ̀ⲅⲓⲟⲥ, le saint. On l''entend dans le Trisagion. Le copte a aussi son propre mot pour « saint » : ⲉⲑⲟⲩⲁⲃ.", "examples": [{"text": "ⲡⲓⲁ̀ⲅⲓⲟⲥ", "translation": "le saint"}, {"text": "ⲛⲓⲁ̀ⲅⲓⲟⲥ", "translation": "les saints"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_presbia', 'eg', 'ⲡ̀ⲣⲉⲥⲃⲓⲁ', 'intercession (mot grec)', 'Mot grec : la prière faite en faveur de quelqu''un. Pluriel avec l''article : ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ. La jinkim sur le ⲡ̀ se lit : « ni-epresvia ».', '[{"text": "ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ", "translation": "les intercessions"}, {"text": "ⲡ̀ⲣⲉⲥⲃⲓⲁ", "translation": "intercession"}]'::jsonb, null, '{"id": "eg.d.cop_presbia", "unitId": "eg.v.cop_presbia", "word": "ⲡ̀ⲣⲉⲥⲃⲓⲁ", "translation": "intercession (mot grec)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Mot grec : la prière faite en faveur de quelqu''un. Pluriel avec l''article : ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ. La jinkim sur le ⲡ̀ se lit : « ni-epresvia ».", "examples": [{"text": "ⲛⲓⲡ̀ⲣⲉⲥⲃⲓⲁ", "translation": "les intercessions"}, {"text": "ⲡ̀ⲣⲉⲥⲃⲓⲁ", "translation": "intercession"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_amin', 'eg', 'ⲁ̀ⲙⲏⲛ', 'amen : c''est vrai, ainsi soit-il (hébreu)', 'Mot hébreu, réponse de l''assemblée à une prière. C''est le « oui » de l''assemblée à une prière.', '[{"text": "ⲁ̀ⲙⲏⲛ", "translation": "amen, c''est vrai"}, {"text": "ⲁ̀ⲙⲏⲛ ⲁ̀ⲗⲗⲏⲗⲟⲩⲓⲁ", "translation": "amen, alléluia"}]'::jsonb, null, '{"id": "eg.d.cop_amin", "unitId": "eg.v.cop_amin", "word": "ⲁ̀ⲙⲏⲛ", "translation": "amen : c''est vrai, ainsi soit-il (hébreu)", "partOfSpeech": "interjection", "collection": "copte", "explanation": "Mot hébreu, réponse de l''assemblée à une prière. C''est le « oui » de l''assemblée à une prière.", "examples": [{"text": "ⲁ̀ⲙⲏⲛ", "translation": "amen, c''est vrai"}, {"text": "ⲁ̀ⲙⲏⲛ ⲁ̀ⲗⲗⲏⲗⲟⲩⲓⲁ", "translation": "amen, alléluia"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_alleluia', 'eg', 'ⲁ̀ⲗⲗⲏⲗⲟⲩⲓⲁ', 'alléluia : louez Dieu (hébreu)', 'Mot hébreu : « louez » + le nom de Dieu. Les Coptes le chantent dans de nombreux répons.', '[{"text": "ⲁ̀ⲗⲗⲏⲗⲟⲩⲓⲁ", "translation": "alléluia, louez Dieu"}, {"text": "ⲁ̀ⲙⲏⲛ ⲁ̀ⲗⲗⲏⲗⲟⲩⲓⲁ", "translation": "amen, alléluia"}]'::jsonb, null, '{"id": "eg.d.cop_alleluia", "unitId": "eg.v.cop_alleluia", "word": "ⲁ̀ⲗⲗⲏⲗⲟⲩⲓⲁ", "translation": "alléluia : louez Dieu (hébreu)", "partOfSpeech": "interjection", "collection": "copte", "explanation": "Mot hébreu : « louez » + le nom de Dieu. Les Coptes le chantent dans de nombreux répons.", "examples": [{"text": "ⲁ̀ⲗⲗⲏⲗⲟⲩⲓⲁ", "translation": "alléluia, louez Dieu"}, {"text": "ⲁ̀ⲙⲏⲛ ⲁ̀ⲗⲗⲏⲗⲟⲩⲓⲁ", "translation": "amen, alléluia"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_sha_enah', 'eg', 'ϣⲁ ⲉ̀ⲛⲉϩ', 'pour toujours', 'Expression qui revient à la fin de nombreuses prières : littéralement « jusqu''à l''éternité ». Le ϣ et le ϩ trahissent un mot égyptien.', '[{"text": "ϣⲁ ⲉ̀ⲛⲉϩ", "translation": "pour toujours"}, {"text": "ϣⲁ ⲉ̀ⲛⲉϩ", "translation": "littéralement : jusqu''à l''éternité"}]'::jsonb, null, '{"id": "eg.d.cop_sha_enah", "unitId": "eg.v.cop_sha_enah", "word": "ϣⲁ ⲉ̀ⲛⲉϩ", "translation": "pour toujours", "partOfSpeech": "expression", "collection": "copte", "explanation": "Expression qui revient à la fin de nombreuses prières : littéralement « jusqu''à l''éternité ». Le ϣ et le ϩ trahissent un mot égyptien.", "examples": [{"text": "ϣⲁ ⲉ̀ⲛⲉϩ", "translation": "pour toujours"}, {"text": "ϣⲁ ⲉ̀ⲛⲉϩ", "translation": "littéralement : jusqu''à l''éternité"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_irini', 'eg', 'ⲓ̀ⲣⲏⲛⲏ', 'paix (mot grec)', 'Mot grec pour la paix. Dans Ⲓ̀ⲣⲏⲛⲏ ⲡⲁⲥⲓ, « la paix à tous ». C''est aussi le prénom Irène.', '[{"text": "ⲓ̀ⲣⲏⲛⲏ", "translation": "paix"}, {"text": "Ⲓ̀ⲣⲏⲛⲏ ⲡⲁⲥⲓ", "translation": "la paix à tous"}]'::jsonb, null, '{"id": "eg.d.cop_irini", "unitId": "eg.v.cop_irini", "word": "ⲓ̀ⲣⲏⲛⲏ", "translation": "paix (mot grec)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Mot grec pour la paix. Dans Ⲓ̀ⲣⲏⲛⲏ ⲡⲁⲥⲓ, « la paix à tous ». C''est aussi le prénom Irène.", "examples": [{"text": "ⲓ̀ⲣⲏⲛⲏ", "translation": "paix"}, {"text": "Ⲓ̀ⲣⲏⲛⲏ ⲡⲁⲥⲓ", "translation": "la paix à tous"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_kyrie', 'eg', 'Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ', 'Seigneur, aie pitié (grec)', 'Prière grecque répétée dans les litanies : ⲕⲩⲣⲓⲉ (Seigneur) + ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ (aie pitié). La messe le répète 41 fois dans les litanies.', '[{"text": "Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ", "translation": "Seigneur, aie pitié"}, {"text": "ⲕⲩⲣⲓⲉ", "translation": "Seigneur (quand on l''appelle)"}]'::jsonb, null, '{"id": "eg.d.cop_kyrie", "unitId": "eg.v.cop_kyrie", "word": "Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ", "translation": "Seigneur, aie pitié (grec)", "partOfSpeech": "expression", "collection": "copte", "explanation": "Prière grecque répétée dans les litanies : ⲕⲩⲣⲓⲉ (Seigneur) + ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ (aie pitié). La messe le répète 41 fois dans les litanies.", "examples": [{"text": "Ⲕⲩⲣⲓⲉ ⲉ̀ⲗⲉⲏ̀ⲥⲟⲛ", "translation": "Seigneur, aie pitié"}, {"text": "ⲕⲩⲣⲓⲉ", "translation": "Seigneur (quand on l''appelle)"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_nai', 'eg', 'ⲛⲁⲓ', 'pitié, miséricorde (copte)', 'Mot copte pour la miséricorde. Avec ⲛⲁⲛ (à nous) : ⲛⲁⲓ ⲛⲁⲛ, aie pitié de nous. Le ⲛ de ⲛⲁⲛ est le même que dans ⲡⲉⲛ-, « notre ».', '[{"text": "ⲛⲁⲓ ⲛⲁⲛ", "translation": "aie pitié de nous"}, {"text": "ⲛⲁⲓ", "translation": "miséricorde, pitié"}]'::jsonb, null, '{"id": "eg.d.cop_nai", "unitId": "eg.v.cop_nai", "word": "ⲛⲁⲓ", "translation": "pitié, miséricorde (copte)", "partOfSpeech": "noun", "collection": "copte", "explanation": "Mot copte pour la miséricorde. Avec ⲛⲁⲛ (à nous) : ⲛⲁⲓ ⲛⲁⲛ, aie pitié de nous. Le ⲛ de ⲛⲁⲛ est le même que dans ⲡⲉⲛ-, « notre ».", "examples": [{"text": "ⲛⲁⲓ ⲛⲁⲛ", "translation": "aie pitié de nous"}, {"text": "ⲛⲁⲓ", "translation": "miséricorde, pitié"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_doxa', 'eg', 'Ⲇⲟⲝⲁ ⲥⲓ Ⲕⲩⲣⲓⲉ', 'gloire à toi, Seigneur (grec)', 'Réponse grecque de louange : ⲇⲟⲝⲁ (gloire) + ⲥⲓ (à toi) + ⲕⲩⲣⲓⲉ (Seigneur). Mot à mot : « gloire à toi, Seigneur ».', '[{"text": "Ⲇⲟⲝⲁ ⲥⲓ Ⲕⲩⲣⲓⲉ", "translation": "gloire à toi, Seigneur"}, {"text": "ⲇⲟⲝⲁ", "translation": "gloire"}]'::jsonb, null, '{"id": "eg.d.cop_doxa", "unitId": "eg.v.cop_doxa", "word": "Ⲇⲟⲝⲁ ⲥⲓ Ⲕⲩⲣⲓⲉ", "translation": "gloire à toi, Seigneur (grec)", "partOfSpeech": "expression", "collection": "copte", "explanation": "Réponse grecque de louange : ⲇⲟⲝⲁ (gloire) + ⲥⲓ (à toi) + ⲕⲩⲣⲓⲉ (Seigneur). Mot à mot : « gloire à toi, Seigneur ».", "examples": [{"text": "Ⲇⲟⲝⲁ ⲥⲓ Ⲕⲩⲣⲓⲉ", "translation": "gloire à toi, Seigneur"}, {"text": "ⲇⲟⲝⲁ", "translation": "gloire"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_iwou', 'eg', 'ⲡⲓⲱⲟⲩ', 'la gloire (copte)', 'ⲡⲓ (le) + ⲱⲟⲩ (gloire) : le mot copte pour la gloire. Le grec dit ⲇⲟⲝⲁ pour la même idée.', '[{"text": "ⲡⲓⲱⲟⲩ", "translation": "la gloire"}, {"text": "ⲡⲓⲱⲟⲩ", "translation": "le mot copte, à côté du grec ⲇⲟⲝⲁ"}]'::jsonb, null, '{"id": "eg.d.cop_iwou", "unitId": "eg.v.cop_iwou", "word": "ⲡⲓⲱⲟⲩ", "translation": "la gloire (copte)", "partOfSpeech": "noun", "collection": "copte", "explanation": "ⲡⲓ (le) + ⲱⲟⲩ (gloire) : le mot copte pour la gloire. Le grec dit ⲇⲟⲝⲁ pour la même idée.", "examples": [{"text": "ⲡⲓⲱⲟⲩ", "translation": "la gloire"}, {"text": "ⲡⲓⲱⲟⲩ", "translation": "le mot copte, à côté du grec ⲇⲟⲝⲁ"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_toub', 'eg', 'طوب (ⲧⲱⲃⲉ)', 'brique : mot arabe venu du copte ⲧⲱⲃⲉ', 'Le mot arabe طوب vient du copte ⲧⲱⲃⲉ. Le mois طوبة est un autre mot, de ⲧⲱⲃⲓ. Ne le confonds pas avec طوبة, le mois.', '[{"text": "طوب", "translation": "les briques"}, {"text": "ⲧⲱⲃⲉ", "translation": "brique (copte)"}]'::jsonb, null, '{"id": "eg.d.cop_toub", "unitId": "eg.v.cop_toub", "word": "طوب (ⲧⲱⲃⲉ)", "translation": "brique : mot arabe venu du copte ⲧⲱⲃⲉ", "partOfSpeech": "noun", "collection": "copte", "explanation": "Le mot arabe طوب vient du copte ⲧⲱⲃⲉ. Le mois طوبة est un autre mot, de ⲧⲱⲃⲓ. Ne le confonds pas avec طوبة, le mois.", "examples": [{"text": "طوب", "translation": "les briques"}, {"text": "ⲧⲱⲃⲉ", "translation": "brique (copte)"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_waha', 'eg', 'واحة (ⲟⲩⲁϩⲉ)', 'oasis : mot arabe venu du copte ⲟⲩⲁϩⲉ', 'Le mot arabe واحة vient du copte ⲟⲩⲁϩⲉ ; le français « oasis » a la même origine. Le français « oasis » vient du même mot.', '[{"text": "واحة", "translation": "une oasis"}, {"text": "ⲟⲩⲁϩⲉ", "translation": "oasis (copte)"}]'::jsonb, null, '{"id": "eg.d.cop_waha", "unitId": "eg.v.cop_waha", "word": "واحة (ⲟⲩⲁϩⲉ)", "translation": "oasis : mot arabe venu du copte ⲟⲩⲁϩⲉ", "partOfSpeech": "noun", "collection": "copte", "explanation": "Le mot arabe واحة vient du copte ⲟⲩⲁϩⲉ ; le français « oasis » a la même origine. Le français « oasis » vient du même mot.", "examples": [{"text": "واحة", "translation": "une oasis"}, {"text": "ⲟⲩⲁϩⲉ", "translation": "oasis (copte)"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_timsah', 'eg', 'تمساح (ⲉⲙⲥⲁϩ)', 'crocodile : mot arabe venu du copte ⲉⲙⲥⲁϩ', 'Le mot arabe تمساح vient du copte ⲉⲙⲥⲁϩ. Il contient la lettre spéciale ϩ : un mot égyptien.', '[{"text": "تمساح", "translation": "un crocodile"}, {"text": "ⲉⲙⲥⲁϩ", "translation": "crocodile (copte)"}]'::jsonb, null, '{"id": "eg.d.cop_timsah", "unitId": "eg.v.cop_timsah", "word": "تمساح (ⲉⲙⲥⲁϩ)", "translation": "crocodile : mot arabe venu du copte ⲉⲙⲥⲁϩ", "partOfSpeech": "noun", "collection": "copte", "explanation": "Le mot arabe تمساح vient du copte ⲉⲙⲥⲁϩ. Il contient la lettre spéciale ϩ : un mot égyptien.", "examples": [{"text": "تمساح", "translation": "un crocodile"}, {"text": "ⲉⲙⲥⲁϩ", "translation": "crocodile (copte)"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_fayoum', 'eg', 'الفيوم (ⲫⲓⲟⲙ)', 'le Fayoum, « le lac », du copte ⲫⲓⲟⲙ', 'Région d''Égypte dont le nom vient de ⲫⲓⲟⲙ : ⲫ (le) + ⲓⲟⲙ (la mer, le lac). Le ⲫ du début est l''article « le », comme dans Ⲫ̀ⲛⲟⲩϯ.', '[{"text": "الفيوم", "translation": "le Fayoum"}, {"text": "ⲫⲓⲟⲙ", "translation": "le lac (copte)"}]'::jsonb, null, '{"id": "eg.d.cop_fayoum", "unitId": "eg.v.cop_fayoum", "word": "الفيوم (ⲫⲓⲟⲙ)", "translation": "le Fayoum, « le lac », du copte ⲫⲓⲟⲙ", "partOfSpeech": "place", "collection": "copte", "explanation": "Région d''Égypte dont le nom vient de ⲫⲓⲟⲙ : ⲫ (le) + ⲓⲟⲙ (la mer, le lac). Le ⲫ du début est l''article « le », comme dans Ⲫ̀ⲛⲟⲩϯ.", "examples": [{"text": "الفيوم", "translation": "le Fayoum"}, {"text": "ⲫⲓⲟⲙ", "translation": "le lac (copte)"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_anba', 'eg', 'أنبا (ⲁⲃⲁ)', 'Anba : titre « père », du copte ⲁⲃⲁ', 'Titre des évêques et des grands moines. Le copte ⲁⲃⲁ veut dire « père ». Abanoub se compose de Ⲁⲃⲁ (père) et Ⲛⲟⲩⲃ (or) : « père d''or ».', '[{"text": "أنبا بيشوي", "translation": "Anba Bishoy"}, {"text": "ⲁⲃⲁ", "translation": "père (copte)"}]'::jsonb, null, '{"id": "eg.d.cop_anba", "unitId": "eg.v.cop_anba", "word": "أنبا (ⲁⲃⲁ)", "translation": "Anba : titre « père », du copte ⲁⲃⲁ", "partOfSpeech": "noun", "collection": "copte", "explanation": "Titre des évêques et des grands moines. Le copte ⲁⲃⲁ veut dire « père ». Abanoub se compose de Ⲁⲃⲁ (père) et Ⲛⲟⲩⲃ (or) : « père d''or ».", "examples": [{"text": "أنبا بيشوي", "translation": "Anba Bishoy"}, {"text": "ⲁⲃⲁ", "translation": "père (copte)"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_shenouda', 'eg', 'شنودة (Ϣⲉⲛⲟⲩϯ)', 'Shenouda : « enfant de Dieu », du copte Ϣⲉⲛⲟⲩϯ', 'Le prénom contient ⲛⲟⲩϯ, « dieu ». Ce sens est celui que donne la tradition copte.', '[{"text": "شنودة", "translation": "Shenouda"}, {"text": "Ϣⲉⲛⲟⲩϯ", "translation": "enfant de Dieu (copte)"}]'::jsonb, null, '{"id": "eg.d.cop_shenouda", "unitId": "eg.v.cop_shenouda", "word": "شنودة (Ϣⲉⲛⲟⲩϯ)", "translation": "Shenouda : « enfant de Dieu », du copte Ϣⲉⲛⲟⲩϯ", "partOfSpeech": "person", "collection": "copte", "explanation": "Le prénom contient ⲛⲟⲩϯ, « dieu ». Ce sens est celui que donne la tradition copte.", "examples": [{"text": "شنودة", "translation": "Shenouda"}, {"text": "Ϣⲉⲛⲟⲩϯ", "translation": "enfant de Dieu (copte)"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_bishoy', 'eg', 'بيشوي (Ⲡⲓϣⲱⲓ)', 'Bishoy : « le haut », du copte Ⲡⲓϣⲱⲓ', 'Le prénom vient de Ⲡⲓϣⲱⲓ : ⲡⲓ (le) + ϣⲱⲓ (haut, élevé). Ce sens est celui que donne la tradition copte.', '[{"text": "بيشوي", "translation": "Bishoy"}, {"text": "Ⲡⲓϣⲱⲓ", "translation": "le haut (copte)"}]'::jsonb, null, '{"id": "eg.d.cop_bishoy", "unitId": "eg.v.cop_bishoy", "word": "بيشوي (Ⲡⲓϣⲱⲓ)", "translation": "Bishoy : « le haut », du copte Ⲡⲓϣⲱⲓ", "partOfSpeech": "person", "collection": "copte", "explanation": "Le prénom vient de Ⲡⲓϣⲱⲓ : ⲡⲓ (le) + ϣⲱⲓ (haut, élevé). Ce sens est celui que donne la tradition copte.", "examples": [{"text": "بيشوي", "translation": "Bishoy"}, {"text": "Ⲡⲓϣⲱⲓ", "translation": "le haut (copte)"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cop_tawadros', 'eg', 'تاوضروس (ⲑⲉⲟⲇⲱⲣⲟⲥ)', 'Tawadros : « don de Dieu », du grec ⲑⲉⲟⲇⲱⲣⲟⲥ', 'Prénom grec : ⲑⲉⲟ (Dieu) + ⲇⲱⲣⲟⲥ (don). Boutros, بطرس, vient du grec Ⲡⲉⲧⲣⲟⲥ, « pierre ».', '[{"text": "تاوضروس", "translation": "Tawadros"}, {"text": "ⲑⲉⲟⲇⲱⲣⲟⲥ", "translation": "don de Dieu (grec)"}]'::jsonb, null, '{"id": "eg.d.cop_tawadros", "unitId": "eg.v.cop_tawadros", "word": "تاوضروس (ⲑⲉⲟⲇⲱⲣⲟⲥ)", "translation": "Tawadros : « don de Dieu », du grec ⲑⲉⲟⲇⲱⲣⲟⲥ", "partOfSpeech": "person", "collection": "copte", "explanation": "Prénom grec : ⲑⲉⲟ (Dieu) + ⲇⲱⲣⲟⲥ (don). Boutros, بطرس, vient du grec Ⲡⲉⲧⲣⲟⲥ, « pierre ».", "examples": [{"text": "تاوضروس", "translation": "Tawadros"}, {"text": "ⲑⲉⲟⲇⲱⲣⲟⲥ", "translation": "don de Dieu (grec)"}]}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
